  (31, 1, '', '[{"id":791,"position":1,"text_uthmani":"الٓمٓ","transliteration":"alif-lam-meem","translation_bn":"আলিফ লাম - মীম-","root":"—","lemma":"الٓمٓ","grammar_bn":"শব্দ"},{"id":792,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem', 'আলিফ-লাম-মীম।', 'Alif, Lam, Meem.', 'আলিফ-লাম-মীম।', 'Alif, Lam, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031001.mp3', now()),
  (31, 2, '', '[{"id":1877,"position":1,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":1878,"position":2,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"আয়াতগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1879,"position":3,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1880,"position":4,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"(যা) জ্ঞানময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1881,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'til''ka āyātu l-kitābi l-ḥakīmi', 'এগুলো হিকমাতে ভরপুর কিতাবের আয়াত।', 'These are verses of the wise Book,', 'এগুলো হিকমাতে ভরপুর কিতাবের আয়াত।', 'These are verses of the wise Book,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031002.mp3', now()),
  (31, 3, '', '[{"id":3047,"position":1,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"পথ নির্দেশনা","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":3048,"position":2,"text_uthmani":"وَرَحْمَةًۭ","transliteration":"waraḥmatan","translation_bn":"ও দয়াস্বরূপ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3049,"position":3,"text_uthmani":"لِّلْمُحْسِنِينَ","transliteration":"lil''muḥ''sinīna","translation_bn":"জন্যে সৎকর্মশীলদের","root":"حسن","lemma":"مُحْسِن","grammar_bn":"অব্যয় (Preposition)"},{"id":3050,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'hudan waraḥmatan lil''muḥ''sinīna', 'সৎকর্মশীলদের জন্য পথ নির্দেশ ও রহমত।', 'As guidance and mercy for the doers of good', 'সৎকর্মশীলদের জন্য পথ নির্দেশ ও রহমত।', 'As guidance and mercy for the doers of good', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031003.mp3', now()),
  (31, 4, '', '[{"id":4389,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4390,"position":2,"text_uthmani":"يُقِيمُونَ","transliteration":"yuqīmūna","translation_bn":"তারা প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4391,"position":3,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":4392,"position":4,"text_uthmani":"وَيُؤْتُونَ","transliteration":"wayu''tūna","translation_bn":"ও তারা দেয়","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4393,"position":5,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":4394,"position":6,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4395,"position":7,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"উপর আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":4396,"position":8,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারাই","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4397,"position":9,"text_uthmani":"يُوقِنُونَ","transliteration":"yūqinūna","translation_bn":"দৃঢ় বিশ্বাস করে","root":"يقن","lemma":"يُوقِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4398,"position":10,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yuqīmūna l-ṣalata wayu''tūna l-zakata wahum bil-ākhirati hum yūqinūna', 'যারা নামায প্রতিষ্ঠা করে, যাকাত দেয় আর তারা আখেরাতের প্রতি দৃঢ় বিশ্বাস রাখে।', 'Who establish prayer and give zakah, and they, of the Hereafter, are certain [in faith].', 'যারা নামায প্রতিষ্ঠা করে, যাকাত দেয় আর তারা আখেরাতের প্রতি দৃঢ় বিশ্বাস রাখে।', 'Who establish prayer and give zakah, and they, of the Hereafter, are certain [in faith].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031004.mp3', now()),
  (31, 5, '', '[{"id":5628,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব (লোকই)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5629,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর (প্রতিষ্ঠিত)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5630,"position":3,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"পথনির্দেশের","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":5631,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5632,"position":5,"text_uthmani":"رَّبِّهِمْ ۖ","transliteration":"rabbihim","translation_bn":"রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5634,"position":6,"text_uthmani":"وَأُو۟لَـٰٓئِكَ","transliteration":"wa-ulāika","translation_bn":"এবং ঐসব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5635,"position":7,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5636,"position":8,"text_uthmani":"ٱلْمُفْلِحُونَ","transliteration":"l-muf''liḥūna","translation_bn":"সফলকাম","root":"فلح","lemma":"مُفْلِحُون","grammar_bn":"শব্দ"},{"id":5637,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika ʿalā hudan min rabbihim wa-ulāika humu l-muf''liḥūna', 'তারাই তাদের পালনকর্তার সঠিক পথে আছে আর তারাই সফলকাম। (দুনিয়া ও আখেরাতে)', 'Those are on [right] guidance from their Lord, and it is those who are the successful.', 'তারাই তাদের পালনকর্তার সঠিক পথে আছে আর তারাই সফলকাম। (দুনিয়া ও আখেরাতে)', 'Those are on [right] guidance from their Lord, and it is those who are the successful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031005.mp3', now()),
  (31, 6, '', '[{"id":6917,"position":1,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"এবং মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6918,"position":2,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের (এমনও আছে)","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":6919,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6920,"position":4,"text_uthmani":"يَشْتَرِى","transliteration":"yashtarī","translation_bn":"কোনো","root":"شري","lemma":"ٱشْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6921,"position":5,"text_uthmani":"لَهْوَ","transliteration":"lahwa","translation_bn":"অসার","root":"لهو","lemma":"لَهْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":6922,"position":6,"text_uthmani":"ٱلْحَدِيثِ","transliteration":"l-ḥadīthi","translation_bn":"কথা","root":"حدث","lemma":"حَدِيث","grammar_bn":"শব্দ"},{"id":6923,"position":7,"text_uthmani":"لِيُضِلَّ","transliteration":"liyuḍilla","translation_bn":"যেন সে বিভ্রান্ত করতে পারে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"শব্দ"},{"id":6924,"position":8,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6925,"position":9,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":6926,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6927,"position":11,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":6928,"position":12,"text_uthmani":"عِلْمٍۢ","transliteration":"ʿil''min","translation_bn":"কোনো জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6929,"position":13,"text_uthmani":"وَيَتَّخِذَهَا","transliteration":"wayattakhidhahā","translation_bn":"এবং গ্রহণ করে তা","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6930,"position":14,"text_uthmani":"هُزُوًا ۚ","transliteration":"huzuwan","translation_bn":"বিদ্রুপরূপে","root":"هزا","lemma":"هُزُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":6932,"position":15,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6933,"position":16,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6934,"position":17,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":6935,"position":18,"text_uthmani":"مُّهِينٌۭ","transliteration":"muhīnun","translation_bn":"অপমানকর","root":"هون","lemma":"مُّهِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":6936,"position":19,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamina l-nāsi man yashtarī lahwa l-ḥadīthi liyuḍilla ʿan sabīli l-lahi bighayri ʿil''min wayattakhidhahā huzuwan ulāika lahum ʿadhābun muhīnun', 'কতক মানুষ আল্লাহর পথ থেকে বিচ্যুত করার উদ্দেশ্যে অজ্ঞতাবশতঃ অবান্তর কথাবার্তা (গান-বাজনা) ক্রয় করে আর আল্লাহর পথকে ঠাট্টা-বিদ্রূপ করে। ওদের জন্যই আছে অবমাননাকর শাস্তি।', 'And of the people is he who buys the amusement of speech to mislead [others] from the way of Allah without knowledge and who takes it in ridicule. Those will have a humiliating punishment.', 'কতক মানুষ আল্লাহর পথ থেকে বিচ্যুত করার উদ্দেশ্যে অজ্ঞতাবশতঃ অবান্তর কথাবার্তা (গান-বাজনা) ক্রয় করে আর আল্লাহর পথকে ঠাট্টা-বিদ্রূপ করে। ওদের জন্যই আছে অবমাননাকর শাস্তি।', 'And of the people is he who buys the amusement of speech to mislead [others] from the way of Allah without knowledge and who takes it in ridicule. Those will have a humiliating punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031006.mp3', now()),
  (31, 7, '', '[{"id":8242,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8243,"position":2,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"তিলাওয়াত করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8244,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"নিকট তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8245,"position":4,"text_uthmani":"ءَايَـٰتُنَا","transliteration":"āyātunā","translation_bn":"আয়াতসমূহ আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8246,"position":5,"text_uthmani":"وَلَّىٰ","transliteration":"wallā","translation_bn":"সে মুখ ফিরায়","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8247,"position":6,"text_uthmani":"مُسْتَكْبِرًۭا","transliteration":"mus''takbiran","translation_bn":"অহঙ্কারী হিসেবে","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8248,"position":7,"text_uthmani":"كَأَن","transliteration":"ka-an","translation_bn":"যেন","root":"—","lemma":"أَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8249,"position":8,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":8250,"position":9,"text_uthmani":"يَسْمَعْهَا","transliteration":"yasmaʿhā","translation_bn":"শুনতে পায় তা","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8251,"position":10,"text_uthmani":"كَأَنَّ","transliteration":"ka-anna","translation_bn":"যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8252,"position":11,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8253,"position":12,"text_uthmani":"أُذُنَيْهِ","transliteration":"udhunayhi","translation_bn":"দু''কানের তার","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8254,"position":13,"text_uthmani":"وَقْرًۭا ۖ","transliteration":"waqran","translation_bn":"বধিরতা","root":"وقر","lemma":"وَقْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8256,"position":14,"text_uthmani":"فَبَشِّرْهُ","transliteration":"fabashir''hu","translation_bn":"অতএব সুসংবাদ দাও তাকে","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"শব্দ"},{"id":8257,"position":15,"text_uthmani":"بِعَذَابٍ","transliteration":"biʿadhābin","translation_bn":"ব্যাপারে শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":8258,"position":16,"text_uthmani":"أَلِيمٍ","transliteration":"alīmin","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":8259,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā tut''lā ʿalayhi āyātunā wallā mus''takbiran ka-an lam yasmaʿhā ka-anna fī udhunayhi waqran fabashir''hu biʿadhābin alīmin', 'যখন তার কাছে আমার আয়াত আবৃত্তি করা হয়, তখন সে অহংকারবশতঃ এমনভাবে মুখ ফিরিয়ে নেয় যেন সে তা শুনতেই পায়নি, যেন তার দুই কানে বধিরতা আছে, কজেই তাকে ভয়াবহ শাস্তির সুসংবাদ দাও।', 'And when our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment.', 'যখন তার কাছে আমার আয়াত আবৃত্তি করা হয়, তখন সে অহংকারবশতঃ এমনভাবে মুখ ফিরিয়ে নেয় যেন সে তা শুনতেই পায়নি, যেন তার দুই কানে বধিরতা আছে, কজেই তাকে ভয়াবহ শাস্তির সুসংবাদ দাও।', 'And when our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031007.mp3', now()),
  (31, 8, '', '[{"id":9434,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9435,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9436,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9437,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9438,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":9439,"position":6,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":9440,"position":7,"text_uthmani":"جَنَّـٰتُ","transliteration":"jannātu","translation_bn":"জান্নাতসমুহ","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9441,"position":8,"text_uthmani":"ٱلنَّعِيمِ","transliteration":"l-naʿīmi","translation_bn":"সুখকর","root":"نعم","lemma":"نَعِيم","grammar_bn":"শব্দ"},{"id":9442,"position":9,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna āmanū waʿamilū l-ṣāliḥāti lahum jannātu l-naʿīmi', 'যারা ঈমান আনে আর সৎকাজ করে তাদের জন্য আছে নি‘য়ামাতে ভরা জান্নাত।', 'Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure.', 'যারা ঈমান আনে আর সৎকাজ করে তাদের জন্য আছে নি‘য়ামাতে ভরা জান্নাত।', 'Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031008.mp3', now()),
  (31, 9, '', '[{"id":10583,"position":1,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"চিরস্থায়ীভাবে থাকবে তারা","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10584,"position":2,"text_uthmani":"فِيهَا ۖ","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10586,"position":3,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10587,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10588,"position":5,"text_uthmani":"حَقًّۭا ۚ","transliteration":"ḥaqqan","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10590,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10591,"position":7,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":10592,"position":8,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":10593,"position":9,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'khālidīna fīhā waʿda l-lahi ḥaqqan wahuwa l-ʿazīzu l-ḥakīmu', 'তাতে তারা চিরকাল থাকবে। আল্লাহর ও‘য়াদা সত্য আর তিনি মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Wherein they abide eternally; [it is] the promise of Allah [which is] truth. And He is the Exalted in Might, the Wise.', 'তাতে তারা চিরকাল থাকবে। আল্লাহর ও‘য়াদা সত্য আর তিনি মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Wherein they abide eternally; [it is] the promise of Allah [which is] truth. And He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/031009.mp3', now()),
  (31, 10, '', '[{"id":11835,"position":1,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11836,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":11837,"position":3,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":11838,"position":4,"text_uthmani":"عَمَدٍۢ","transliteration":"ʿamadin","translation_bn":"কোন খুঁটি","root":"عمد","lemma":"عَمَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11839,"position":5,"text_uthmani":"تَرَوْنَهَا ۖ","transliteration":"tarawnahā","translation_bn":"তোমরা দেখছো তা","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":11841,"position":6,"text_uthmani":"وَأَلْقَىٰ","transliteration":"wa-alqā","translation_bn":"এবং স্থাপন করেছেন","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11842,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11843,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":11844,"position":9,"text_uthmani":"رَوَٰسِىَ","transliteration":"rawāsiya","translation_bn":"পর্বতমালা","root":"رسو","lemma":"رَوَٰسِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":11845,"position":10,"text_uthmani":"أَن","transliteration":"an","translation_bn":"( এমন না হয় ) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":11846,"position":11,"text_uthmani":"تَمِيدَ","transliteration":"tamīda","translation_bn":"ঢলে যায়","root":"ميد","lemma":"تَمِيدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11847,"position":12,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"ন