  (32, 1, '', '[{"id":796,"position":1,"text_uthmani":"الٓمٓ","transliteration":"alif-lam-meem","translation_bn":"আলিফ লাম- মীম-","root":"—","lemma":"الٓمٓ","grammar_bn":"শব্দ"},{"id":797,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem', 'আলিফ-লাম-মীম,', 'Alif, Lam, Meem.', 'আলিফ-লাম-মীম,', 'Alif, Lam, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032001.mp3', now()),
  (32, 2, '', '[{"id":1882,"position":1,"text_uthmani":"تَنزِيلُ","transliteration":"tanzīlu","translation_bn":"অবতরণ (হয়েছে)","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1883,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এই) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1884,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1885,"position":4,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1886,"position":5,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1887,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1888,"position":7,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1889,"position":8,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":1890,"position":9,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlu l-kitābi lā rayba fīhi min rabbi l-ʿālamīna', 'এ কিতাব বিশ্বজগতের পালনকর্তার নিকট হতে অবতীর্ণ, এতে কোন সন্দেহ নেই।', '[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds.', 'এ কিতাব বিশ্বজগতের পালনকর্তার নিকট হতে অবতীর্ণ, এতে কোন সন্দেহ নেই।', '[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032002.mp3', now()),
  (32, 3, '', '[{"id":3051,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3052,"position":2,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলেছে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3053,"position":3,"text_uthmani":"ٱفْتَرَىٰهُ ۚ","transliteration":"if''tarāhu","translation_bn":"\"সে মিথ্যা রচনা করেছে তা\"","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3055,"position":4,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":3056,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3057,"position":6,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":3058,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3059,"position":8,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"রবের তোমার","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3060,"position":9,"text_uthmani":"لِتُنذِرَ","transliteration":"litundhira","translation_bn":"যেন তুমি সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":3061,"position":10,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"(এমন)এক জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3062,"position":11,"text_uthmani":"مَّآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3063,"position":12,"text_uthmani":"أَتَىٰهُم","transliteration":"atāhum","translation_bn":"কাছে এসেছে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3064,"position":13,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3065,"position":14,"text_uthmani":"نَّذِيرٍۢ","transliteration":"nadhīrin","translation_bn":"সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":3066,"position":15,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3067,"position":16,"text_uthmani":"قَبْلِكَ","transliteration":"qablika","translation_bn":"তোমার পূর্ব","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3068,"position":17,"text_uthmani":"لَعَلَّهُمْ","transliteration":"laʿallahum","translation_bn":"সম্ভবত তারা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3069,"position":18,"text_uthmani":"يَهْتَدُونَ","transliteration":"yahtadūna","translation_bn":"সঠিক পথে চলবে","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3070,"position":19,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'am yaqūlūna if''tarāhu bal huwa l-ḥaqu min rabbika litundhira qawman mā atāhum min nadhīrin min qablika laʿallahum yahtadūna', 'তবে তারা কি বলে যে, সে নিজেই তা রচনা করেছে (এবং আল্লাহর নিকট থেকে আগত কিতাব ব’লে মিথ্যে দাবী করছে, না তা নয়), বরং তা তোমাদের প্রতিপালকের নিকট থেকে (আগত) সত্য যাতে তুমি এমন এক সম্প্রদায়কে সতর্ক করতে পার যাদের কাছে তোমার পূর্বে কোন সকর্তকারী আসেনি, সম্ভবতঃ তারা সঠিকপথ প্রাপ্ত হবে।', 'Or do they say, "He invented it"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided.', 'তবে তারা কি বলে যে, সে নিজেই তা রচনা করেছে (এবং আল্লাহর নিকট থেকে আগত কিতাব ব’লে মিথ্যে দাবী করছে, না তা নয়), বরং তা তোমাদের প্রতিপালকের নিকট থেকে (আগত) সত্য যাতে তুমি এমন এক সম্প্রদায়কে সতর্ক করতে পার যাদের কাছে তোমার পূর্বে কোন সকর্তকারী আসেনি, সম্ভবতঃ তারা সঠিকপথ প্রাপ্ত হবে।', 'Or do they say, "He invented it"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032003.mp3', now()),
  (32, 4, '', '[{"id":4409,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"(তিনিই)আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4410,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4411,"position":3,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4412,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":4413,"position":5,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4414,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4415,"position":7,"text_uthmani":"بَيْنَهُمَا","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে তাদের (আছে)","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":4416,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4417,"position":9,"text_uthmani":"سِتَّةِ","transliteration":"sittati","translation_bn":"ছয়","root":"ستت","lemma":"سِتَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4418,"position":10,"text_uthmani":"أَيَّامٍۢ","transliteration":"ayyāmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4419,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4420,"position":12,"text_uthmani":"ٱسْتَوَىٰ","transliteration":"is''tawā","translation_bn":"সমাসীন হন","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":4421,"position":13,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4422,"position":14,"text_uthmani":"ٱلْعَرْشِ ۖ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":4424,"position":15,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4425,"position":16,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":4426,"position":17,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4427,"position":18,"text_uthmani":"دُونِهِۦ","transliteration":"dūnihi","translation_bn":"তিনি","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":4428,"position":19,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4429,"position":20,"text_uthmani":"وَلِىٍّۢ","transliteration":"waliyyin","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4430,"position":21,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4431,"position":22,"text_uthmani":"شَفِيعٍ ۚ","transliteration":"shafīʿin","translation_bn":"সুপারিশকারী","root":"شفع","lemma":"شَفِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":4433,"position":23,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"কি তবে না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":4434,"position":24,"text_uthmani":"تَتَذَكَّرُونَ","transliteration":"tatadhakkarūna","translation_bn":"তোমরা উপদেশ গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4435,"position":25,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu alladhī khalaqa l-samāwāti wal-arḍa wamā baynahumā fī sittati ayyāmin thumma is''tawā ʿalā l-ʿarshi mā lakum min dūnihi min waliyyin walā shafīʿin afalā tatadhakkarūna', 'আল্লাহ যিনি আকাশমন্ডলী ও পৃথিবী এবং এ দু’এর মাঝে যা কিছু আছে ছয় দিনে সৃষ্টি করেছেন- অতঃপর তিনি ‘আরশে সমুন্নত হন। তিনি ব্যতীত তোমাদের জন্য কোন অভিভাবক নেই, সুপারিশকারীও নেই। তবুও কি তোমরা উপদেশ গ্রহণ করবে না?', 'It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?', 'আল্লাহ যিনি আকাশমন্ডলী ও পৃথিবী এবং এ দু’এর মাঝে যা কিছু আছে ছয় দিনে সৃষ্টি করেছেন- অতঃপর তিনি ‘আরশে সমুন্নত হন। তিনি ব্যতীত তোমাদের জন্য কোন অভিভাবক নেই, সুপারিশকারীও নেই। তবুও কি তোমরা উপদেশ গ্রহণ করবে না?', 'It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032004.mp3', now()),
  (32, 5, '', '[{"id":5669,"position":1,"text_uthmani":"يُدَبِّرُ","transliteration":"yudabbiru","translation_bn":"তিনি পরিচালনা করেন","root":"دبر","lemma":"يُدَبِّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5670,"position":2,"text_uthmani":"ٱلْأَمْرَ","transliteration":"l-amra","translation_bn":"সবকাজের","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":5671,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5672,"position":4,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":5673,"position":5,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5674,"position":6,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":5675,"position":7,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5676,"position":8,"text_uthmani":"يَعْرُجُ","transliteration":"yaʿruju","translation_bn":"উত্থিত হবে","root":"عرج","lemma":"يَعْرُجُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5677,"position":9,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5678,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5679,"position":11,"text_uthmani":"يَوْمٍۢ","transliteration":"yawmin","translation_bn":"একদিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":5680,"position":12,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5681,"position":13,"text_uthmani":"مِقْدَارُهُۥٓ","transliteration":"miq''dāruhu","translation_bn":"যার পরিমাণ (তোমাদের কাছে)","root":"قدر","lemma":"مِقْدَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":5682,"position":14,"text_uthmani":"أَلْفَ","transliteration":"alfa","translation_bn":"এক হাজার","root":"الف","lemma":"أَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":5683,"position":15,"text_uthmani":"سَنَةٍۢ","transliteration":"sanatin","translation_bn":"বছর","root":"سنو","lemma":"سَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":5684,"position":16,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"সেই(হিসেব)থেকে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5685,"position":17,"text_uthmani":"تَعُدُّونَ","transliteration":"taʿuddūna","translation_bn":"তোমরা গণনা করো","root":"عدد","lemma":"عَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5686,"position":18,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'yudabbiru l-amra mina l-samāi ilā l-arḍi thumma yaʿruju ilayhi fī yawmin kāna miq''dāruhu alfa sanatin mimmā taʿuddūna', 'তিনি আকাশ হতে পৃথিবী পর্যন্ত কার্য পরিচালনা করেন, অতঃপর সকল বিষয়াদি তাঁরই কাছে একদিন উত্থিত হবে যার পরিমাপ তোমাদের গণনা অনুযায়ী হাজার বছর।', 'He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count.', 'তিনি আকাশ হতে পৃথিবী পর্যন্ত কার্য পরিচালনা করেন, অতঃপর সকল বিষয়াদি তাঁরই কাছে একদিন উত্থিত হবে যার পরিমাপ তোমাদের গণনা অনুযায়ী হাজার বছর।', 'He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032005.mp3', now()),
  (32, 6, '', '[{"id":6969,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"তিনিই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6970,"position":2,"text_uthmani":"عَـٰلِمُ","transliteration":"ʿālimu","translation_bn":"জ্ঞানী","root":"علم","lemma":"عَٰلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6971,"position":3,"text_uthmani":"ٱلْغَيْبِ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":6972,"position":4,"text_uthmani":"وَٱلشَّهَـٰدَةِ","transliteration":"wal-shahādati","translation_bn":"ও দৃশ্যের","root":"شهد","lemma":"شَهَٰدَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6973,"position":5,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":6974,"position":6,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":6975,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika ʿālimu l-ghaybi wal-shahādati l-ʿazīzu l-raḥīmu', 'এমনই তিনি, অদৃশ্য ও দৃশ্যমান সম্পর্কে জ্ঞাত, মহাপরাক্রমশালী, পরম দয়ালু।', 'That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,', 'এমনই তিনি, অদৃশ্য ও দৃশ্যমান সম্পর্কে জ্ঞাত, মহাপরাক্রমশালী, পরম দয়ালু।', 'That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/032006.mp3', now()),
