  (33, 1, '', '[{"id":798,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":799,"position":2,"text_uthmani":"ٱلنَّبِىُّ","transliteration":"l-nabiyu","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":800,"position":3,"text_uthmani":"ٱتَّقِ","transliteration":"ittaqi","translation_bn":"ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":801,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":802,"position":5,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":803,"position":6,"text_uthmani":"تُطِعِ","transliteration":"tuṭiʿi","translation_bn":"আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":804,"position":7,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফিরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":805,"position":8,"text_uthmani":"وَٱلْمُنَـٰفِقِينَ ۗ","transliteration":"wal-munāfiqīna","translation_bn":"আর (না) মুনাফিকদেরকে","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":807,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":808,"position":10,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":809,"position":11,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":810,"position":12,"text_uthmani":"عَلِيمًا","transliteration":"ʿalīman","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":811,"position":13,"text_uthmani":"حَكِيمًۭا","transliteration":"ḥakīman","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":812,"position":14,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nabiyu ittaqi l-laha walā tuṭiʿi l-kāfirīna wal-munāfiqīna inna l-laha kāna ʿalīman ḥakīman', 'হে নবী (সা)! আল্লাহকে ভয় কর, আর কাফির ও মুনাফিকদের আনুগত্য কর না, নিশ্চয় আল্লাহ সর্বজ্ঞাতা, মহাপ্রজ্ঞাময়।', 'O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Indeed, Allah is ever Knowing and Wise.', 'হে নবী (সা)! আল্লাহকে ভয় কর, আর কাফির ও মুনাফিকদের আনুগত্য কর না, নিশ্চয় আল্লাহ সর্বজ্ঞাতা, মহাপ্রজ্ঞাময়।', 'O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033001.mp3', now()),
  (33, 2, '', '[{"id":1891,"position":1,"text_uthmani":"وَٱتَّبِعْ","transliteration":"wa-ittabiʿ","translation_bn":"এবং অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1892,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1893,"position":3,"text_uthmani":"يُوحَىٰٓ","transliteration":"yūḥā","translation_bn":"ওহী করা হয়েছে","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":1894,"position":4,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"প্রতি তোমার","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1895,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1896,"position":6,"text_uthmani":"رَّبِّكَ ۚ","transliteration":"rabbika","translation_bn":"রবের তোমার","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1898,"position":7,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1899,"position":8,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1900,"position":9,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1901,"position":10,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1902,"position":11,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1903,"position":12,"text_uthmani":"خَبِيرًۭا","transliteration":"khabīran","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":1904,"position":13,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittabiʿ mā yūḥā ilayka min rabbika inna l-laha kāna bimā taʿmalūna khabīran', 'তোমার প্রতি তোমার প্রতিপালকের নিকট হতে যা ওয়াহী করা হয় তুমি তার অনুসরণ কর। তোমরা যা কর সে সম্পর্কে আল্লাহ পূর্ণরূপে অবহিত।', 'And follow that which is revealed to you from your Lord. Indeed Allah is ever, with what you do, Acquainted.', 'তোমার প্রতি তোমার প্রতিপালকের নিকট হতে যা ওয়াহী করা হয় তুমি তার অনুসরণ কর। তোমরা যা কর সে সম্পর্কে আল্লাহ পূর্ণরূপে অবহিত।', 'And follow that which is revealed to you from your Lord. Indeed Allah is ever, with what you do, Acquainted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033002.mp3', now()),
  (33, 3, '', '[{"id":3071,"position":1,"text_uthmani":"وَتَوَكَّلْ","transliteration":"watawakkal","translation_bn":"এবং নির্ভর করো","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3072,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3073,"position":3,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3075,"position":4,"text_uthmani":"وَكَفَىٰ","transliteration":"wakafā","translation_bn":"এবং যথেষ্ট","root":"كفي","lemma":"كَفَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3076,"position":5,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":3077,"position":6,"text_uthmani":"وَكِيلًۭا","transliteration":"wakīlan","translation_bn":"(দায়িত্বশীল বা) কর্মবিধায়করূপে","root":"وكل","lemma":"وَكِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3078,"position":7,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'watawakkal ʿalā l-lahi wakafā bil-lahi wakīlan', 'আর তুমি নির্ভর কর আল্লাহর উপর, কর্ম সম্পাদনে আল্লাহই যথেষ্ট।', 'And rely upon Allah; and sufficient is Allah as Disposer of affairs.', 'আর তুমি নির্ভর কর আল্লাহর উপর, কর্ম সম্পাদনে আল্লাহই যথেষ্ট।', 'And rely upon Allah; and sufficient is Allah as Disposer of affairs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033003.mp3', now()),
  (33, 4, '', '[{"id":4436,"position":1,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4437,"position":2,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4438,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4439,"position":4,"text_uthmani":"لِرَجُلٍۢ","transliteration":"lirajulin","translation_bn":"জন্যে কোনো ব্যক্তির","root":"رجل","lemma":"رَجُل","grammar_bn":"অব্যয় (Preposition)"},{"id":4440,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4441,"position":6,"text_uthmani":"قَلْبَيْنِ","transliteration":"qalbayni","translation_bn":"দু''টি হৃদয়","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4442,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4443,"position":8,"text_uthmani":"جَوْفِهِۦ ۚ","transliteration":"jawfihi","translation_bn":"অভ্যন্তরে তার","root":"جوف","lemma":"جَوْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":4445,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4446,"position":10,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4447,"position":11,"text_uthmani":"أَزْوَٰجَكُمُ","transliteration":"azwājakumu","translation_bn":"স্ত্রীদেরকে তোমাদের","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":4448,"position":12,"text_uthmani":"ٱلَّـٰٓـِٔى","transliteration":"allāī","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّٰ^ـ#ِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4449,"position":13,"text_uthmani":"تُظَـٰهِرُونَ","transliteration":"tuẓāhirūna","translation_bn":"তোমরা জিহার কর","root":"ظهر","lemma":"ظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4450,"position":14,"text_uthmani":"مِنْهُنَّ","transliteration":"min''hunna","translation_bn":"মধ্যে হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4451,"position":15,"text_uthmani":"أُمَّهَـٰتِكُمْ ۚ","transliteration":"ummahātikum","translation_bn":"তোমাদের মা তোমাদের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4453,"position":16,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4454,"position":17,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"(আল্লাহ) করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4455,"position":18,"text_uthmani":"أَدْعِيَآءَكُمْ","transliteration":"adʿiyāakum","translation_bn":"মুখডাকা পুত্রদেরকে (পালকপুত্র)তোমাদের","root":"دعو","lemma":"دُعَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":4456,"position":19,"text_uthmani":"أَبْنَآءَكُمْ ۚ","transliteration":"abnāakum","translation_bn":"(প্রকৃত)পুত্র তোমাদের","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4458,"position":20,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":4459,"position":21,"text_uthmani":"قَوْلُكُم","transliteration":"qawlukum","translation_bn":"(মুখে বলা)কথা তোমাদের","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4460,"position":22,"text_uthmani":"بِأَفْوَٰهِكُمْ ۖ","transliteration":"bi-afwāhikum","translation_bn":"দিয়ে মুখ(বলা)তোমাদের","root":"فوه","lemma":"أَفْوَٰه","grammar_bn":"অব্যয় (Preposition)"},{"id":4462,"position":23,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4463,"position":24,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4464,"position":25,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":4465,"position":26,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4466,"position":27,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"পরিচালনা করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":4467,"position":28,"text_uthmani":"ٱلسَّبِيلَ","transliteration":"l-sabīla","translation_bn":"(সৎ)পথে","root":"سبل","lemma":"سَبِيل","grammar_bn":"শব্দ"},{"id":4468,"position":29,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'mā jaʿala l-lahu lirajulin min qalbayni fī jawfihi wamā jaʿala azwājakumu allāī tuẓāhirūna min''hunna ummahātikum wamā jaʿala adʿiyāakum abnāakum dhālikum qawlukum bi-afwāhikum wal-lahu yaqūlu l-ḥaqa wahuwa yahdī l-sabīla', 'আল্লাহ কোন মানুষের বুকে দু’টি অন্তর সৃষ্টি করেননি। তোমাদের স্ত্রীদের মধ্যে যাদের সঙ্গে তোমরা জিহার কর, তিনি তাদেরকে তোমাদের জননী করেননি, আর তিনি তোমাদের পোষ্য পুত্রদেরকে তোমাদের পুত্র করেননি, এগুলো তোমাদের মুখের বুলি, আল্লাহই বলেন সত্য কথা, আর তিনিই দেখান (সঠিক) পথ।', 'Allah has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And he has not made your adopted sons your [true] sons. That is [merely] your saying by your mouths, but Allah says the truth, and He guides to the [right] way.', 'আল্লাহ কোন মানুষের বুকে দু’টি অন্তর সৃষ্টি করেননি। তোমাদের স্ত্রীদের মধ্যে যাদের সঙ্গে তোমরা জিহার কর, তিনি তাদেরকে তোমাদের জননী করেননি, আর তিনি তোমাদের পোষ্য পুত্রদেরকে তোমাদের পুত্র করেননি, এগুলো তোমাদের মুখের বুলি, আল্লাহই বলেন সত্য কথা, আর তিনিই দেখান (সঠিক) পথ।', 'Allah has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And he has not made your adopted sons your [true] sons. That is [merely] your saying by your mouths, but Allah says the truth, and He guides to the [right] way.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033004.mp3', now()),
  (33, 5, '', '[{"id":5687,"position":1,"text_uthmani":"ٱدْعُوهُمْ","transliteration":"id''ʿūhum","translation_bn":"তোমরা ডাকো তাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":5688,"position":2,"text_uthmani":"لِـَٔابَآئِهِمْ","transliteration":"liābāihim","translation_bn":"নিয়ে পিতাদের তাদের (সম্পর্কে)","root":"ابو","lemma":"ا^بَاء","grammar_bn":"অব্যয় (Preposition)"},{"id":5689,"position":3,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা-ই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5690,"position":4,"text_uthmani":"أَقْسَطُ","transliteration":"aqsaṭu","translation_bn":"অধিক ন্যায়সঙ্গত","root":"قسط","lemma":"أَقْسَط","grammar_bn":"বিশেষ্য (Noun)"},{"id":5691,"position":5,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":5692,"position":6,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5694,"position":7,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":5695,"position":8,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":5696,"position":9,"text_uthmani":"تَعْلَمُوٓا۟","transliteration":"taʿlamū","translation_bn":"তোমরা জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5697,"position":10,"text_uthmani":"ءَابَآءَهُمْ","transliteration":"ābāahum","translation_bn":"পিতাদের তাদের(পরিচয়)","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5698,"position":11,"text_uthmani":"فَإِخْوَٰنُكُمْ","transliteration":"fa-ikh''wānukum","translation_bn":"তবে ভাই তোমাদের","root":"اخو","lemma":"أَخ","grammar_bn":"শব্দ"},{"id":5699,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ভিত্তিতে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5700,"position":13,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"দ্বীনের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":5701,"position":14,"text_uthmani":"وَمَوَٰلِيكُمْ ۚ","transliteration":"wamawālīkum","translation_bn":"ও  বন্ধু তোমাদের","root":"ولي","lemma":"مَوَٰلِي","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5703,"position":15,"text_uthmani":"وَلَيْسَ","transliteration":"walaysa","translation_bn":"এবং নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5704,"position":16,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"উপর তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5705,"position":17,"text_uthmani":"جُنَاحٌۭ","transliteration":"junāḥun","translation_bn":"কোনো ত্রুটি","root":"جنح","lemma":"جُنَاح","grammar_bn":"বিশেষ্য (Noun)"},{"id":5706,"position":18,"text_uthmani":"فِيمَآ","transliteration":"fīmā","translation_bn":"(এসব বিষয়ে) যা","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5707,"position":19,"text_uthmani":"أَخْطَأْتُم","transliteration":"akhṭatum","translation_bn":"তোমরা ভুল করে ফেলেছো","root":"خطا","lemma":"أَخْطَأْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5708,"position":20,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সম্পর্কে সে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":5709,"position":21,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5710,"position":22,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5711,"position":23,"text_uthmani":"تَعَمَّدَتْ","transliteration":"taʿammadat","translation_bn":"ইচ্ছাকৃতভাবে করে","root":"عمد","lemma":"تَعَمَّدَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5712,"position":24,"text_uthmani":"قُلُوبُكُمْ ۚ","transliteration":"qulūbukum","translation_bn":"অন্তর তোমাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5714,"position":25,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5715,"position":26,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5716,"position":27,"text_uthmani":"غَفُورًۭا","transliteration":"ghafūran","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":5717,"position":28,"text_uthmani":"رَّحِيمًا","transliteration":"raḥīman","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":5718,"position":29,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'id''ʿūhum liābāihim huwa aqsaṭu ʿinda l-lahi fa-in lam taʿlamū ābāahum fa-ikh''wānukum fī l-dīni wamawālīkum walaysa ʿalaykum junāḥun fīmā akhṭatum bihi walākin mā taʿammadat qulūbukum wakāna l-lahu ghafūran raḥīman', 'তাদেরকে তাদের পিতৃ-পরিচয়ে ডাক, আল্লাহর কাছে এটাই অধিক ইনসাফপূর্ণ। আর যদি তোমরা তাদের পিতৃ-পরিচয় না জান, তাহলে তারা তোমাদের দ্বীনী ভাই এবং তোমাদের বন্ধু। এ ব্যাপারে তোমাদের ত্রুটি-বিচ্যুতি হলে তোমাদের কোন গুনাহ্ নেই, কিন্তু (ধর্তব্য হল) তোমাদের অন্তরের সংকল্প। আল্লাহ অতি ক্ষমাশীল, পরম দয়ালু।', 'Call them by [the names of] their fathers; it is more just in the sight of Allah. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allah Forgiving and Merciful.', 'তাদেরকে তাদের পিতৃ-পরিচয়ে ডাক, আল্লাহর কাছে এটাই অধিক ইনসাফপূর্ণ। আর যদি তোমরা তাদের পিতৃ-পরিচয় না জান, তাহলে তারা তোমাদের দ্বীনী ভাই এবং তোমাদের বন্ধু। এ ব্যাপারে তোমাদের ত্রুটি-বিচ্যুতি হলে তোমাদের কোন গুনাহ্ নেই, কিন্তু (ধর্তব্য হল) তোমাদের অন্তরের সংকল্প। আল্লাহ অতি ক্ষমাশীল, পরম দয়ালু।', 'Call them by [the names of] their fathers; it is more just in the sight of Allah. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allah Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033005.mp3', now()),
  (33, 6, '', '[{"id":6976,"position":1,"text_uthmani":"ٱلنَّبِىُّ","transliteration":"al-nabiyu","translation_bn":"নাবীই","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":6977,"position":2,"text_uthmani":"أَوْلَىٰ","transliteration":"awlā","translation_bn":"অধিক ঘনিষ্ঠ","root":"ولي","lemma":"أَوْلَىٰ","grammar_bn":"বিশেষণ (Adjective)"},{"id":6978,"position":3,"text_uthmani":"بِٱلْمُؤْمِنِينَ","transliteration":"bil-mu''minīna","translation_bn":"কাছে মু’মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":6979,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"অপেক্ষা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6980,"position":5,"text_uthmani":"أَنفُسِهِمْ ۖ","transliteration":"anfusihim","translation_bn":"নিজেদের তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":6982,"position":6,"text_uthmani":"وَأَزْوَٰجُهُۥٓ","transliteration":"wa-azwājuhu","translation_bn":"এবং স্ত্রীগণ তার","root":"زوج","lemma":"زَوْج","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6983,"position":7,"text_uthmani":"أُمَّهَـٰتُهُمْ ۗ","transliteration":"ummahātuhum","translation_bn":"মা তাদের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6985,"position":8,"text_uthmani":"وَأُو۟لُوا۟","transliteration":"wa-ulū","translation_bn":"এবং অধিকারীরা","root":"اول","lemma":"أُولِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6986,"position":9,"text_uthmani":"ٱلْأَرْحَامِ","transliteration":"l-arḥāmi","translation_bn":"আত্নীয়তা-সম্পর্কের (নিকট আত্মীয়-স্বজনরা মু’মিন হ''লে)","root":"رحم","lemma":"أَرْحَام","grammar_bn":"শব্দ"},{"id":6987,"position":10,"text_uthmani":"بَعْضُهُمْ","transliteration":"baʿḍuhum","translation_bn":"পরস্পরে তাদের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":6988,"position":11,"text_uthmani":"أَوْلَىٰ","transliteration":"awlā","translation_bn":"অধিক ঘনিষ্ঠ","root":"ولي","lemma":"أَوْلَىٰ","grammar_bn":"বিশেষণ (Adjective)"},{"id":6989,"position":12,"text_uthmani":"بِبَعْضٍۢ","transliteration":"bibaʿḍin","translation_bn":"সাথে পরস্পরের","root":"بعض","lemma":"بَعْض","grammar_bn":"অব্যয় (Preposition)"},{"id":6990,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"অনুসারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6991,"position":14,"text_uthmani":"كِتَـٰبِ","transliteration":"kitābi","translation_bn":"বিধান","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":6992,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6993,"position":16,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6994,"position":17,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"(সাধারণ) মু’মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":6995,"position":18,"text_uthmani":"وَٱلْمُهَـٰجِرِينَ","transliteration":"wal-muhājirīna","translation_bn":"ও মুহাজিরদের","root":"هجر","lemma":"مُهَاجِر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6996,"position":19,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"তবে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":6997,"position":20,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এটা) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":6998,"position":21,"text_uthmani":"تَفْعَلُوٓا۟","transliteration":"tafʿalū","translation_bn":"(চাও যদি) তোমরা করতে পারো","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6999,"position":22,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7000,"position":23,"text_uthmani":"أَوْلِيَآئِكُم","transliteration":"awliyāikum","translation_bn":"(এসব)বন্ধুদের তোমাদের","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7001,"position":24,"text_uthmani":"مَّعْرُوفًۭا ۚ","transliteration":"maʿrūfan","translation_bn":"ভালো ব্যবহার","root":"عرف","lemma":"مَّعْرُوف","grammar_bn":"বিশেষ্য (Noun)"},{"id":7003,"position":25,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"আছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7004,"position":26,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":7005,"position":27,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7006,"position":28,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":7007,"position":29,"text_uthmani":"مَسْطُورًۭا","transliteration":"masṭūran","translation_bn":"লিখিত","root":"سطر","lemma":"مَسْطُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":7008,"position":30,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'al-nabiyu awlā bil-mu''minīna min anfusihim wa-azwājuhu ummahātuhum wa-ulū l-arḥāmi baʿḍuhum awlā bibaʿḍin fī kitābi l-lahi mina l-mu''minīna wal-muhājirīna illā an tafʿalū ilā awliyāikum maʿrūfan kāna dhālika fī l-kitābi masṭūran', 'নবী (সাঃ) মু’মিনদের নিকট তাদের নিজেদের চেয়ে ঘনিষ্ঠ, আর তার স্ত্রীগণ তাদের মাতা। আল্লাহর বিধানে মু’মিন ও মুহাজিরদের (দ্বীনী সম্পর্ক) অপেক্ষা আত্মীয়-স্বজনগণ পরস্পর পরস্পরের নিকট ঘনিষ্ঠতর। তবে তোমরা তোমাদের বন্ধু বান্ধবদের প্রতি দয়া-দাক্ষিণ্য প্রদর্শন করতে চাইলে, করতে পার। (আল্লাহর) কিতাবে এটাই লিখিত।', 'The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allah than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed.', 'নবী (সাঃ) মু’মিনদের নিকট তাদের নিজেদের চেয়ে ঘনিষ্ঠ, আর তার স্ত্রীগণ তাদের মাতা। আল্লাহর বিধানে মু’মিন ও মুহাজিরদের (দ্বীনী সম্পর্ক) অপেক্ষা আত্মীয়-স্বজনগণ পরস্পর পরস্পরের নিকট ঘনিষ্ঠতর। তবে তোমরা তোমাদের বন্ধু বান্ধবদের প্রতি দয়া-দাক্ষিণ্য প্রদর্শন করতে চাইলে, করতে পার। (আল্লাহর) কিতাবে এটাই লিখিত।', 'The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allah than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033006.mp3', now()),
  (33, 7, '', '[{"id":8290,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8291,"position":2,"text_uthmani":"أَخَذْنَا","transliteration":"akhadhnā","translation_bn":"নিয়েছিলাম আমরা","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8292,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"কাছ থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8293,"position":4,"text_uthmani":"ٱلنَّبِيِّـۧنَ","transliteration":"l-nabiyīna","translation_bn":"নাবীদের","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":8294,"position":5,"text_uthmani":"مِيثَـٰقَهُمْ","transliteration":"mīthāqahum","translation_bn":"অঙ্গীকার তাদের","root":"وثق","lemma":"مِّيثَٰق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8295,"position":6,"text_uthmani":"وَمِنكَ","transliteration":"waminka","translation_bn":"এবং থেকেও তোমার","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8296,"position":7,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8297,"position":8,"text_uthmani":"نُّوحٍۢ","transliteration":"nūḥin","translation_bn":"নূহ","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8298,"position":9,"text_uthmani":"وَإِبْرَٰهِيمَ","transliteration":"wa-ib''rāhīma","translation_bn":"এবং ইবরাহীম","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8299,"position":10,"text_uthmani":"وَمُوسَىٰ","transliteration":"wamūsā","translation_bn":"এবং মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8300,"position":11,"text_uthmani":"وَعِيسَى","transliteration":"waʿīsā","translation_bn":"ও ঈসা","root":"—","lemma":"عِيسَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8301,"position":12,"text_uthmani":"ٱبْنِ","transliteration":"ib''ni","translation_bn":"তনয়","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":8302,"position":13,"text_uthmani":"مَرْيَمَ ۖ","transliteration":"maryama","translation_bn":"মারইয়াম (থেকেও)","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8304,"position":14,"text_uthmani":"وَأَخَذْنَا","transliteration":"wa-akhadhnā","translation_bn":"এবং নিয়েছিলাম আমরা","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8305,"position":15,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8306,"position":16,"text_uthmani":"مِّيثَـٰقًا","transliteration":"mīthāqan","translation_bn":"অঙ্গীকার","root":"وثق","lemma":"مِّيثَٰق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8307,"position":17,"text_uthmani":"غَلِيظًۭا","transliteration":"ghalīẓan","translation_bn":"দৃঢ়","root":"غلظ","lemma":"غَلِيظ","grammar_bn":"বিশেষণ (Adjective)"},{"id":8308,"position":18,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh akhadhnā mina l-nabiyīna mīthāqahum waminka wamin nūḥin wa-ib''rāhīma wamūsā waʿīsā ib''ni maryama wa-akhadhnā min''hum mīthāqan ghalīẓan', 'স্মরণ কর, আমি যখন নবীদের কাছ থেকে অঙ্গীকার নিয়েছিলাম আর তোমার কাছ থেকেও; আর নূহ্, ইব্রাহীম, মূসা আর মারইয়াম পুত্র ‘ঈসা থেকেও। আমি তাদের কাছ থেকে নিয়েছিলাম দৃঢ় অঙ্গীকার', 'And [mention, O Muhammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant.', 'স্মরণ কর, আমি যখন নবীদের কাছ থেকে অঙ্গীকার নিয়েছিলাম আর তোমার কাছ থেকেও; আর নূহ্, ইব্রাহীম, মূসা আর মারইয়াম পুত্র ‘ঈসা থেকেও। আমি তাদের কাছ থেকে নিয়েছিলাম দৃঢ় অঙ্গীকার', 'And [mention, O Muhammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033007.mp3', now()),
  (33, 8, '', '[{"id":9469,"position":1,"text_uthmani":"لِّيَسْـَٔلَ","transliteration":"liyasala","translation_bn":"যেন সে জিজ্ঞেস করতে পারে","root":"سال","lemma":"سَأَلَ","grammar_bn":"শব্দ"},{"id":9470,"position":2,"text_uthmani":"ٱلصَّـٰدِقِينَ","transliteration":"l-ṣādiqīna","translation_bn":"সত্যবাদীদেরকে","root":"صدق","lemma":"صَادِق","grammar_bn":"শব্দ"},{"id":9471,"position":3,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"সম্বন্ধে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9472,"position":4,"text_uthmani":"صِدْقِهِمْ ۚ","transliteration":"ṣid''qihim","translation_bn":"সত্যবাদীতা তাদের","root":"صدق","lemma":"صِدْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":9474,"position":5,"text_uthmani":"وَأَعَدَّ","transliteration":"wa-aʿadda","translation_bn":"এবং তিনি প্রস্তুত করে রেখেছেন","root":"عدد","lemma":"أَعَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9475,"position":6,"text_uthmani":"لِلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"জন্যে কাফিরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":9476,"position":7,"text_uthmani":"عَذَابًا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9477,"position":8,"text_uthmani":"أَلِيمًۭا","transliteration":"alīman","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":9478,"position":9,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'liyasala l-ṣādiqīna ʿan ṣid''qihim wa-aʿadda lil''kāfirīna ʿadhāban alīman', 'সত্যবাদীদেরকে (অর্থাৎ নবীদেরকে) তাদের সত্যবাদিতা (অর্থাৎ আল্লাহর বাণী পৌঁছে দেয়ার কাজ) সম্পর্কে জিজ্ঞেস করার জন্য। তিনি কাফিরদের জন্য প্রস্তুত করে রেখেছেন ভয়াবহ শাস্তি।', 'That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment.', 'সত্যবাদীদেরকে (অর্থাৎ নবীদেরকে) তাদের সত্যবাদিতা (অর্থাৎ আল্লাহর বাণী পৌঁছে দেয়ার কাজ) সম্পর্কে জিজ্ঞেস করার জন্য। তিনি কাফিরদের জন্য প্রস্তুত করে রেখেছেন ভয়াবহ শাস্তি।', 'That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033008.mp3', now()),
  (33, 9, '', '[{"id":10617,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":10618,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10619,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10620,"position":4,"text_uthmani":"ٱذْكُرُوا۟","transliteration":"udh''kurū","translation_bn":"তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10621,"position":5,"text_uthmani":"نِعْمَةَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহের","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10622,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10623,"position":7,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"প্রতি তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10624,"position":8,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":10625,"position":9,"text_uthmani":"جَآءَتْكُمْ","transliteration":"jāatkum","translation_bn":"এসেছিলো তোমাদের (উপর)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10626,"position":10,"text_uthmani":"جُنُودٌۭ","transliteration":"junūdun","translation_bn":"(শত্রু) সৈন্যবাহিনী","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":10627,"position":11,"text_uthmani":"فَأَرْسَلْنَا","transliteration":"fa-arsalnā","translation_bn":"তখন পাঠিয়েছিলাম আমরা","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10628,"position":12,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"বিরুদ্ধে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10629,"position":13,"text_uthmani":"رِيحًۭا","transliteration":"rīḥan","translation_bn":"প্রবল ঝড়","root":"روح","lemma":"رِيح","grammar_bn":"বিশেষ্য (Noun)"},{"id":10630,"position":14,"text_uthmani":"وَجُنُودًۭا","transliteration":"wajunūdan","translation_bn":"ও সৈন্যবাহিনী","root":"جند","lemma":"جُند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10631,"position":15,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"নাই","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":10632,"position":16,"text_uthmani":"تَرَوْهَا ۚ","transliteration":"tarawhā","translation_bn":"তোমরা দেখো তা","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":10634,"position":17,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10635,"position":18,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10636,"position":19,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10637,"position":20,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10638,"position":21,"text_uthmani":"بَصِيرًا","transliteration":"baṣīran","translation_bn":"খুব দৃষ্টিমান","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":10639,"position":22,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū udh''kurū niʿ''mata l-lahi ʿalaykum idh jāatkum junūdun fa-arsalnā ʿalayhim rīḥan wajunūdan lam tarawhā wakāna l-lahu bimā taʿmalūna baṣīran', 'হে মু’মিনগণ! তোমরা তোমাদের প্রতি আল্লাহর অনুগ্রহের কথা স্মরণ কর যখন সৈন্যবাহিনী তোমাদের বিরুদ্ধে নিকটবর্তী হয়েছিল, অতঃপর আমি তাদের বিরুদ্ধে পাঠিয়েছিলাম ঝড়ো হাওয়া এবং এক (ফেরেশতারূপী) সৈন্যবাহিনী যা তোমরা দেখনি। তোমরা যা কর আল্লাহ তা প্রত্যক্ষকারী।', 'O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing.', 'হে মু’মিনগণ! তোমরা তোমাদের প্রতি আল্লাহর অনুগ্রহের কথা স্মরণ কর যখন সৈন্যবাহিনী তোমাদের বিরুদ্ধে নিকটবর্তী হয়েছিল, অতঃপর আমি তাদের বিরুদ্ধে পাঠিয়েছিলাম ঝড়ো হাওয়া এবং এক (ফেরেশতারূপী) সৈন্যবাহিনী যা তোমরা দেখনি। তোমরা যা কর আল্লাহ তা প্রত্যক্ষকারী।', 'O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033009.mp3', now()),
  (33, 10, '', '[{"id":11896,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":11897,"position":2,"text_uthmani":"جَآءُوكُم","transliteration":"jāūkum","translation_bn":"তারা এসেছিলো বিরুদ্ধে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11898,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11899,"position":4,"text_uthmani":"فَوْقِكُمْ","transliteration":"fawqikum","translation_bn":"উপর তোমাদের(অঞ্চল)","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":11900,"position":5,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"ও হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11901,"position":6,"text_uthmani":"أَسْفَلَ","transliteration":"asfala","translation_bn":"নিচ (অঞ্চল)","root":"سفل","lemma":"أَسْفَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11902,"position":7,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"হ''তে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11903,"position":8,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11904,"position":9,"text_uthmani":"زَاغَتِ","transliteration":"zāghati","translation_bn":"বিস্ফোরিত হয়েছিলো","root":"زيغ","lemma":"زَاغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11905,"position":10,"text_uthmani":"ٱلْأَبْصَـٰرُ","transliteration":"l-abṣāru","translation_bn":"চোখসমূহ","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":11906,"position":11,"text_uthmani":"وَبَلَغَتِ","transliteration":"wabalaghati","translation_bn":"ও পৌঁছে গিয়েছিলো","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11907,"position":12,"text_uthmani":"ٱلْقُلُوبُ","transliteration":"l-qulūbu","translation_bn":"প্রাণসমূহ","root":"قلب","lemma":"قَلْب","grammar_bn":"শব্দ"},{"id":11908,"position":13,"text_uthmani":"ٱلْحَنَاجِرَ","transliteration":"l-ḥanājira","translation_bn":"কণ্ঠসমূহে","root":"حنجر","lemma":"حَنَاجِر","grammar_bn":"শব্দ"},{"id":11909,"position":14,"text_uthmani":"وَتَظُنُّونَ","transliteration":"wataẓunnūna","translation_bn":"এবং তোমরা মনে করতে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11910,"position":15,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"সম্পর্কে আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":11911,"position":16,"text_uthmani":"ٱلظُّنُونَا۠","transliteration":"l-ẓunūnā","translation_bn":"নানাবিধ ধারণা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"শব্দ"},{"id":11912,"position":17,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'idh jāūkum min fawqikum wamin asfala minkum wa-idh zāghati l-abṣāru wabalaghati l-qulūbu l-ḥanājira wataẓunnūna bil-lahi l-ẓunūnā', 'তারা যখন তোমাদের কাছে এসেছিল তোমাদের উপর থেকে আর তোমাদের নীচের দিক থেকে, তখন তোমাদের চক্ষু হয়েছিল বিস্ফোরিত আর প্রাণ হয়েছিল কণ্ঠাগত; আর তোমরা আল্লাহ সম্পর্কে নানা রকম (খারাপ) ধারণা পোষণ করতে শুরু করেছিলে।', '[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions.', 'তারা যখন তোমাদের কাছে এসেছিল তোমাদের উপর থেকে আর তোমাদের নীচের দিক থেকে, তখন তোমাদের চক্ষু হয়েছিল বিস্ফোরিত আর প্রাণ হয়েছিল কণ্ঠাগত; আর তোমরা আল্লাহ সম্পর্কে নানা রকম (খারাপ) ধারণা পোষণ করতে শুরু করেছিলে।', '[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033010.mp3', now()),
  (33, 11, '', '[{"id":13199,"position":1,"text_uthmani":"هُنَالِكَ","transliteration":"hunālika","translation_bn":"তখনই","root":"—","lemma":"هُنَالِك\r","grammar_bn":"কালবাচক (Time)"},{"id":13200,"position":2,"text_uthmani":"ٱبْتُلِىَ","transliteration":"ub''tuliya","translation_bn":"পরীক্ষা করা হয়েছিলো","root":"بلو","lemma":"ٱبْتَلَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":13201,"position":3,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু’মিনদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":13202,"position":4,"text_uthmani":"وَزُلْزِلُوا۟","transliteration":"wazul''zilū","translation_bn":"এবং প্রকম্পিত করা হয়েছিলো","root":"زلزل","lemma":"زُلْزِلُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13203,"position":5,"text_uthmani":"زِلْزَالًۭا","transliteration":"zil''zālan","translation_bn":"প্রকম্পন","root":"زلزل","lemma":"زِلْزَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":13204,"position":6,"text_uthmani":"شَدِيدًۭا","transliteration":"shadīdan","translation_bn":"ভীষণভাবে","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":13205,"position":7,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'hunālika ub''tuliya l-mu''minūna wazul''zilū zil''zālan shadīdan', 'সে সময় মু’মিনগণকে পরীক্ষা করা হয়েছিল আর তাদেরকে ভীষণ কম্পনে প্রকম্পিত করা হয়েছিল।', 'There the believers were tested and shaken with a severe shaking.', 'সে সময় মু’মিনগণকে পরীক্ষা করা হয়েছিল আর তাদেরকে ভীষণ কম্পনে প্রকম্পিত করা হয়েছিল।', 'There the believers were tested and shaken with a severe shaking.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033011.mp3', now()),
  (33, 12, '', '[{"id":14481,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14482,"position":2,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14483,"position":3,"text_uthmani":"ٱلْمُنَـٰفِقُونَ","transliteration":"l-munāfiqūna","translation_bn":"মুনাফিকরা","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":14484,"position":4,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"ও যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14485,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14486,"position":6,"text_uthmani":"قُلُوبِهِم","transliteration":"qulūbihim","translation_bn":"অন্তরসমূহের তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":14487,"position":7,"text_uthmani":"مَّرَضٌۭ","transliteration":"maraḍun","translation_bn":"রোগ (ছিলো)","root":"مرض","lemma":"مَّرَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":14488,"position":8,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":14489,"position":9,"text_uthmani":"وَعَدَنَا","transliteration":"waʿadanā","translation_bn":"প্রতিশ্রুতি দিয়েছেন আমাদের","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14490,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14491,"position":11,"text_uthmani":"وَرَسُولُهُۥٓ","transliteration":"warasūluhu","translation_bn":"ও রাসূল তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14492,"position":12,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":14493,"position":13,"text_uthmani":"غُرُورًۭا","transliteration":"ghurūran","translation_bn":"প্রতারণা\"","root":"غرر","lemma":"غُرُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":14494,"position":14,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh yaqūlu l-munāfiqūna wa-alladhīna fī qulūbihim maraḍun mā waʿadanā l-lahu warasūluhu illā ghurūran', 'আর স্মরণ কর, যখন মুনাফিকরা এবং যাদের অন্তরে রোগ আছে তারা বলছিল- আল্লাহ ও তাঁর রসূল আমাদেরকে যে ওয়া‘দা দিয়েছেন তা ধোঁকা ছাড়া আর কিছুই নয়।', 'And [remember] when the hypocrites and those in whose hearts is disease said, "Allah and His Messenger did not promise us except delusion,"', 'আর স্মরণ কর, যখন মুনাফিকরা এবং যাদের অন্তরে রোগ আছে তারা বলছিল- আল্লাহ ও তাঁর রসূল আমাদেরকে যে ওয়া‘দা দিয়েছেন তা ধোঁকা ছাড়া আর কিছুই নয়।', 'And [remember] when the hypocrites and those in whose hearts is disease said, "Allah and His Messenger did not promise us except delusion,"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033012.mp3', now()),
  (33, 13, '', '[{"id":15587,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15588,"position":2,"text_uthmani":"قَالَت","transliteration":"qālat","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15589,"position":3,"text_uthmani":"طَّآئِفَةٌۭ","transliteration":"ṭāifatun","translation_bn":"একদল","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15590,"position":4,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্যে হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15591,"position":5,"text_uthmani":"يَـٰٓأَهْلَ","transliteration":"yāahla","translation_bn":"\"হে অধিবাসীরা","root":"اهل","lemma":"أَهْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":15592,"position":6,"text_uthmani":"يَثْرِبَ","transliteration":"yathriba","translation_bn":"ইযাসরিবের (অর্থাৎ মাদীনাহর)","root":"—","lemma":"يَثْرِب","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15593,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15594,"position":8,"text_uthmani":"مُقَامَ","transliteration":"muqāma","translation_bn":"দাঁড়াবার স্থান","root":"قوم","lemma":"مُقَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":15595,"position":9,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":15596,"position":10,"text_uthmani":"فَٱرْجِعُوا۟ ۚ","transliteration":"fa-ir''jiʿū","translation_bn":"সুতরাং তোমরা ফিরে যাও\"","root":"رجع","lemma":"رَجَعَ","grammar_bn":"শব্দ"},{"id":15598,"position":11,"text_uthmani":"وَيَسْتَـْٔذِنُ","transliteration":"wayastadhinu","translation_bn":"এবং অনুমতি (অব্যাহতি) নিতে চায়","root":"اذن","lemma":"ٱسْتَـ#ْذَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15599,"position":12,"text_uthmani":"فَرِيقٌۭ","transliteration":"farīqun","translation_bn":"একদল","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":15600,"position":13,"text_uthmani":"مِّنْهُمُ","transliteration":"min''humu","translation_bn":"মধ্যে হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15601,"position":14,"text_uthmani":"ٱلنَّبِىَّ","transliteration":"l-nabiya","translation_bn":"নাবী (থেকে)","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":15602,"position":15,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15603,"position":16,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15604,"position":17,"text_uthmani":"بُيُوتَنَا","transliteration":"buyūtanā","translation_bn":"ঘরসমূহ আমাদের","root":"بيت","lemma":"بَيْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":15605,"position":18,"text_uthmani":"عَوْرَةٌۭ","transliteration":"ʿawratun","translation_bn":"অরক্ষিত\"","root":"عور","lemma":"عَوْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15606,"position":19,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"অথচ না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15607,"position":20,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তা (ছিলো)","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":15608,"position":21,"text_uthmani":"بِعَوْرَةٍ ۖ","transliteration":"biʿawratin","translation_bn":"অবস্থায় অরক্ষিত","root":"عور","lemma":"عَوْرَة","grammar_bn":"অব্যয় (Preposition)"},{"id":15610,"position":22,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":15611,"position":23,"text_uthmani":"يُرِيدُونَ","transliteration":"yurīdūna","translation_bn":"তারা চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15612,"position":24,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":15613,"position":25,"text_uthmani":"فِرَارًۭا","transliteration":"firāran","translation_bn":"পালিয়ে যাওয়া","root":"فرر","lemma":"فِرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":15614,"position":26,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qālat ṭāifatun min''hum yāahla yathriba lā muqāma lakum fa-ir''jiʿū wayastadhinu farīqun min''humu l-nabiya yaqūlūna inna buyūtanā ʿawratun wamā hiya biʿawratin in yurīdūna illā firāran', 'স্মরণ কর, যখন তাদের একদল বলেছিল- হে ইয়াসরিববাসী! তোমরা (শত্রুর আক্রমণের বিরুদ্ধে) দাঁড়াতে পারবে না, কাজেই তোমরা ফিরে যাও। আর তাদের একদল এই বলে নবী (সা)র কাছে অব্যাহতি চাচ্ছিল যে, আমাদের বাড়ীঘর অরক্ষিত অথচ ওগুলো অরক্ষিত ছিল না, আসলে পালিয়ে যাওয়াই তাদের ছিল একমাত্র উদ্দেশ্য।', 'And when a faction of them said, "O people of Yathrib, there is no stability for you [here], so return [home]." And a party of them asked permission of the Prophet, saying, "Indeed, our houses are unprotected," while they were not exposed. They did not intend except to flee.', 'স্মরণ কর, যখন তাদের একদল বলেছিল- হে ইয়াসরিববাসী! তোমরা (শত্রুর আক্রমণের বিরুদ্ধে) দাঁড়াতে পারবে না, কাজেই তোমরা ফিরে যাও। আর তাদের একদল এই বলে নবী (সা)র কাছে অব্যাহতি চাচ্ছিল যে, আমাদের বাড়ীঘর অরক্ষিত অথচ ওগুলো অরক্ষিত ছিল না, আসলে পালিয়ে যাওয়াই তাদের ছিল একমাত্র উদ্দেশ্য।', 'And when a faction of them said, "O people of Yathrib, there is no stability for you [here], so return [home]." And a party of them asked permission of the Prophet, saying, "Indeed, our houses are unprotected," while they were not exposed. They did not intend except to flee.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033013.mp3', now()),
  (33, 14, '', '[{"id":16647,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16648,"position":2,"text_uthmani":"دُخِلَتْ","transliteration":"dukhilat","translation_bn":"প্রবেশ করতো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16649,"position":3,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"মধ্যে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16650,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16651,"position":5,"text_uthmani":"أَقْطَارِهَا","transliteration":"aqṭārihā","translation_bn":"চারদিক তার","root":"قطر","lemma":"أَقْطَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":16652,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16653,"position":7,"text_uthmani":"سُئِلُوا۟","transliteration":"su-ilū","translation_bn":"তাদের কাছে চাওয়া (আহ্বান করা) হতো","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16654,"position":8,"text_uthmani":"ٱلْفِتْنَةَ","transliteration":"l-fit''nata","translation_bn":"বিদ্রোহের","root":"فتن","lemma":"فِتْنَة","grammar_bn":"শব্দ"},{"id":16655,"position":9,"text_uthmani":"لَـَٔاتَوْهَا","transliteration":"laātawhā","translation_bn":"অবশ্যই তারা করে বসতো তা","root":"اتي","lemma":"ا^تَى","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":16656,"position":10,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16657,"position":11,"text_uthmani":"تَلَبَّثُوا۟","transliteration":"talabbathū","translation_bn":"তারা অবস্থান করতো","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16658,"position":12,"text_uthmani":"بِهَآ","transliteration":"bihā","translation_bn":"জন্যে তার","root":"—","lemma":"بِهَآ","grammar_bn":"অব্যয় (Preposition)"},{"id":16659,"position":13,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":16660,"position":14,"text_uthmani":"يَسِيرًۭا","transliteration":"yasīran","translation_bn":"সামান্য","root":"يسر","lemma":"يَسِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":16661,"position":15,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'walaw dukhilat ʿalayhim min aqṭārihā thumma su-ilū l-fit''nata laātawhā wamā talabbathū bihā illā yasīran', 'যদি শত্রুপক্ষ (মদীনা নগরীর) চারদিক থেকে তাদের উপর আক্রমণ করতো, অতঃপর তাদেরকে কুফুরীর আহবান করা হত, তবে তারা তাই করে বসত। তাতে তারা মোটেও বিলম্ব করত না।', 'And if they had been entered upon from all its [surrounding] regions and fitnah had been demanded of them, they would have done it and not hesitated over it except briefly.', 'যদি শত্রুপক্ষ (মদীনা নগরীর) চারদিক থেকে তাদের উপর আক্রমণ করতো, অতঃপর তাদেরকে কুফুরীর আহবান করা হত, তবে তারা তাই করে বসত। তাতে তারা মোটেও বিলম্ব করত না।', 'And if they had been entered upon from all its [surrounding] regions and fitnah had been demanded of them, they would have done it and not hesitated over it except briefly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033014.mp3', now()),
  (33, 15, '', '[{"id":17828,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17829,"position":2,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17830,"position":3,"text_uthmani":"عَـٰهَدُوا۟","transliteration":"ʿāhadū","translation_bn":"তারা অঙ্গীকার করেছিলো","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17831,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর (সাথে)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17832,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17833,"position":6,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্ব (যে)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":17834,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17835,"position":8,"text_uthmani":"يُوَلُّونَ","transliteration":"yuwallūna","translation_bn":"তারা ফিরাবে","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17836,"position":9,"text_uthmani":"ٱلْأَدْبَـٰرَ ۚ","transliteration":"l-adbāra","translation_bn":"পিঠসমূহ","root":"دبر","lemma":"دُبُر","grammar_bn":"শব্দ"},{"id":17838,"position":10,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17839,"position":11,"text_uthmani":"عَهْدُ","transliteration":"ʿahdu","translation_bn":"অঙ্গীকার","root":"عهد","lemma":"عَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":17840,"position":12,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর (সাথে কৃত)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17841,"position":13,"text_uthmani":"مَسْـُٔولًۭا","transliteration":"masūlan","translation_bn":"জিজ্ঞাসিত","root":"سال","lemma":"مَسْـ#ُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":17842,"position":14,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad kānū ʿāhadū l-laha min qablu lā yuwallūna l-adbāra wakāna ʿahdu l-lahi masūlan', 'অথচ তারা ইতোপূর্বে আল্লাহর সাথে অঙ্গীকার করেছিল যে, তারা পৃষ্ঠপ্রদর্শন করবে না। আল্লাহর সঙ্গে কৃত ওয়া‘দা সম্পর্কে অবশ্যই জিজ্ঞেস করা হবে।', 'And they had already promised Allah before not to turn their backs and flee. And ever is the promise to Allah [that about which one will be] questioned.', 'অথচ তারা ইতোপূর্বে আল্লাহর সাথে অঙ্গীকার করেছিল যে, তারা পৃষ্ঠপ্রদর্শন করবে না। আল্লাহর সঙ্গে কৃত ওয়া‘দা সম্পর্কে অবশ্যই জিজ্ঞেস করা হবে।', 'And they had already promised Allah before not to turn their backs and flee. And ever is the promise to Allah [that about which one will be] questioned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033015.mp3', now()),
  (33, 16, '', '[{"id":18868,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18869,"position":2,"text_uthmani":"لَّن","transliteration":"lan","translation_bn":"\"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":18870,"position":3,"text_uthmani":"يَنفَعَكُمُ","transliteration":"yanfaʿakumu","translation_bn":"উপকার দিবে তোমাদের","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18871,"position":4,"text_uthmani":"ٱلْفِرَارُ","transliteration":"l-firāru","translation_bn":"পালিয়ে যাওয়া","root":"فرر","lemma":"فِرَار","grammar_bn":"শব্দ"},{"id":18872,"position":5,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদিও","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":18873,"position":6,"text_uthmani":"فَرَرْتُم","transliteration":"farartum","translation_bn":"তোমরা পালাও","root":"فرر","lemma":"فَرَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18874,"position":7,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18875,"position":8,"text_uthmani":"ٱلْمَوْتِ","transliteration":"l-mawti","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":18876,"position":9,"text_uthmani":"أَوِ","transliteration":"awi","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18877,"position":10,"text_uthmani":"ٱلْقَتْلِ","transliteration":"l-qatli","translation_bn":"হত্যা (হ''তে)","root":"قتل","lemma":"قَتْل","grammar_bn":"শব্দ"},{"id":18878,"position":11,"text_uthmani":"وَإِذًۭا","transliteration":"wa-idhan","translation_bn":"এবং তখন","root":"—","lemma":"إِذًا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18879,"position":12,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":18880,"position":13,"text_uthmani":"تُمَتَّعُونَ","transliteration":"tumattaʿūna","translation_bn":"তোমাদের ভোগ করতে দেয়া হবে","root":"متع","lemma":"مَّتَّعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18881,"position":14,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":18882,"position":15,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"অতি সামান্য\"","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18883,"position":16,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul lan yanfaʿakumu l-firāru in farartum mina l-mawti awi l-qatli wa-idhan lā tumattaʿūna illā qalīlan', 'বল, পলায়নে তোমাদের কোনই লাভ হবে না, যদি তোমরা মৃত্যু অথবা হত্যা থেকে পলায়ন কর তাহলে তোমাদেরকে সামান্যই ভোগ করতে দেয়া হবে।', 'Say, [O Muhammad], "Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little."', 'বল, পলায়নে তোমাদের কোনই লাভ হবে না, যদি তোমরা মৃত্যু অথবা হত্যা থেকে পলায়ন কর তাহলে তোমাদেরকে সামান্যই ভোগ করতে দেয়া হবে।', 'Say, [O Muhammad], "Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033016.mp3', now()),
  (33, 17, '', '[{"id":19971,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19972,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19973,"position":3,"text_uthmani":"ذَا","transliteration":"dhā","translation_bn":"এমন","root":"—","lemma":"ذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":19974,"position":4,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19975,"position":5,"text_uthmani":"يَعْصِمُكُم","transliteration":"yaʿṣimukum","translation_bn":"রক্ষা করবে তোমাদেরকে","root":"عصم","lemma":"يَعْصِمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19976,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19977,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19978,"position":8,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19979,"position":9,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"তিনি ইচ্ছে করেন","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19980,"position":10,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"সাথে তোমাদের","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":19981,"position":11,"text_uthmani":"سُوٓءًا","transliteration":"sūan","translation_bn":"অমঙ্গলের","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":19982,"position":12,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা (যদি)","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19983,"position":13,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"তিনি ইচ্ছে করেন","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19984,"position":14,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"সাথে তোমাদের","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":19985,"position":15,"text_uthmani":"رَحْمَةًۭ ۚ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহের (তবে কে বন্ধ করতে পারে)\"","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19987,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19988,"position":17,"text_uthmani":"يَجِدُونَ","transliteration":"yajidūna","translation_bn":"তারা পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19989,"position":18,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":19990,"position":19,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19991,"position":20,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":19992,"position":21,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19993,"position":22,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"কোনো অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19994,"position":23,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19995,"position":24,"text_uthmani":"نَصِيرًۭا","transliteration":"naṣīran","translation_bn":"কোন সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":19996,"position":25,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'qul man dhā alladhī yaʿṣimukum mina l-lahi in arāda bikum sūan aw arāda bikum raḥmatan walā yajidūna lahum min dūni l-lahi waliyyan walā naṣīran', 'বল, তোমাদেরকে আল্লাহ (’র শাস্তি) হতে কে রক্ষা করবে তিনি যদি তোমাদের অকল্যাণ করতে চান অথবা তোমাদেরকে অনুগ্রহ করতে চান? তারা আল্লাহকে ছাড়া তাদের জন্য না পাবে কোন অভিভাবক, আর না কোন সাহায্যকারী।', 'Say, "Who is it that can protect you from Allah if He intends for you an ill or intends for you a mercy?" And they will not find for themselves besides Allah any protector or any helper.', 'বল, তোমাদেরকে আল্লাহ (’র শাস্তি) হতে কে রক্ষা করবে তিনি যদি তোমাদের অকল্যাণ করতে চান অথবা তোমাদেরকে অনুগ্রহ করতে চান? তারা আল্লাহকে ছাড়া তাদের জন্য না পাবে কোন অভিভাবক, আর না কোন সাহায্যকারী।', 'Say, "Who is it that can protect you from Allah if He intends for you an ill or intends for you a mercy?" And they will not find for themselves besides Allah any protector or any helper.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033017.mp3', now()),
  (33, 18, '', '[{"id":21000,"position":1,"text_uthmani":"۞ قَدْ","transliteration":"qad","translation_bn":"অবশ্যই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":21001,"position":2,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21002,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21003,"position":4,"text_uthmani":"ٱلْمُعَوِّقِينَ","transliteration":"l-muʿawiqīna","translation_bn":"বাধাদানকারীদেরকে","root":"عوق","lemma":"مُعَوِّقِين","grammar_bn":"শব্দ"},{"id":21004,"position":5,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"মধ্য হ''তে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21005,"position":6,"text_uthmani":"وَٱلْقَآئِلِينَ","transliteration":"wal-qāilīna","translation_bn":"কথকদেরকে (যারা বলে)","root":"قول","lemma":"قَا^ئِل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21006,"position":7,"text_uthmani":"لِإِخْوَٰنِهِمْ","transliteration":"li-ikh''wānihim","translation_bn":"উদ্দেশ্যে ভাইদের তাদের","root":"اخو","lemma":"أَخ","grammar_bn":"অব্যয় (Preposition)"},{"id":21007,"position":8,"text_uthmani":"هَلُمَّ","transliteration":"halumma","translation_bn":"\"চলে এসো","root":"لمم","lemma":"لُمَّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":21008,"position":9,"text_uthmani":"إِلَيْنَا ۖ","transliteration":"ilaynā","translation_bn":"দিকে আমাদের\"","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21010,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"কিন্তু না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21011,"position":11,"text_uthmani":"يَأْتُونَ","transliteration":"yatūna","translation_bn":"তারা আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":21012,"position":12,"text_uthmani":"ٱلْبَأْسَ","transliteration":"l-basa","translation_bn":"যুদ্ধে","root":"باس","lemma":"بَأْس","grammar_bn":"শব্দ"},{"id":21013,"position":13,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":21014,"position":14,"text_uthmani":"قَلِيلًا","transliteration":"qalīlan","translation_bn":"অল্পই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21015,"position":15,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'qad yaʿlamu l-lahu l-muʿawiqīna minkum wal-qāilīna li-ikh''wānihim halumma ilaynā walā yatūna l-basa illā qalīlan', 'আল্লাহ তোমাদের মধ্যে তাদেরকে নিশ্চিতই জানেন কারা (যুদ্ধে অংশগ্রহণে) বাধা সৃষ্টিকারী আর কারা নিজেদের ভাইদেরকে বলে- আমাদের কাছে এসো। যুদ্ধ তারা সামান্যই করে', 'Already Allah knows the hinderers among you and those [hypocrites] who say to their brothers, "Come to us," and do not go to battle, except for a few,', 'আল্লাহ তোমাদের মধ্যে তাদেরকে নিশ্চিতই জানেন কারা (যুদ্ধে অংশগ্রহণে) বাধা সৃষ্টিকারী আর কারা নিজেদের ভাইদেরকে বলে- আমাদের কাছে এসো। যুদ্ধ তারা সামান্যই করে', 'Already Allah knows the hinderers among you and those [hypocrites] who say to their brothers, "Come to us," and do not go to battle, except for a few,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033018.mp3', now()),
  (33, 19, '', '[{"id":22129,"position":1,"text_uthmani":"أَشِحَّةً","transliteration":"ashiḥḥatan","translation_bn":"কৃপণতাবশত","root":"شحح","lemma":"شُحّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":22130,"position":2,"text_uthmani":"عَلَيْكُمْ ۖ","transliteration":"ʿalaykum","translation_bn":"ব্যাপারে তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22132,"position":3,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":22133,"position":4,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22134,"position":5,"text_uthmani":"ٱلْخَوْفُ","transliteration":"l-khawfu","translation_bn":"ভয় (বিপদ)","root":"خوف","lemma":"خَوْف","grammar_bn":"শব্দ"},{"id":22135,"position":6,"text_uthmani":"رَأَيْتَهُمْ","transliteration":"ra-aytahum","translation_bn":"তুমি দেখবে তাদেরকে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":22136,"position":7,"text_uthmani":"يَنظُرُونَ","transliteration":"yanẓurūna","translation_bn":"তারা তাকাচ্ছে","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22137,"position":8,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"প্রতি তোমার","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22138,"position":9,"text_uthmani":"تَدُورُ","transliteration":"tadūru","translation_bn":"ঘুরছে","root":"دور","lemma":"تَدُورُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22139,"position":10,"text_uthmani":"أَعْيُنُهُمْ","transliteration":"aʿyunuhum","translation_bn":"চোখগুলো তাদের","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":22140,"position":11,"text_uthmani":"كَٱلَّذِى","transliteration":"ka-alladhī","translation_bn":"(তার) মতো যাকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":22141,"position":12,"text_uthmani":"يُغْشَىٰ","transliteration":"yugh''shā","translation_bn":"অচেতনতা চেপে বসেছে","root":"غشو","lemma":"غَشِيَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22142,"position":13,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22143,"position":14,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"ভয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22144,"position":15,"text_uthmani":"ٱلْمَوْتِ ۖ","transliteration":"l-mawti","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":22146,"position":16,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"কিন্তু যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":22147,"position":17,"text_uthmani":"ذَهَبَ","transliteration":"dhahaba","translation_bn":"চলে যায়","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22148,"position":18,"text_uthmani":"ٱلْخَوْفُ","transliteration":"l-khawfu","translation_bn":"ভয় (বিপদ)","root":"خوف","lemma":"خَوْف","grammar_bn":"শব্দ"},{"id":22149,"position":19,"text_uthmani":"سَلَقُوكُم","transliteration":"salaqūkum","translation_bn":"শীঘ্রই সাথে মিলবে তোমাদের","root":"سلق","lemma":"سَلَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22150,"position":20,"text_uthmani":"بِأَلْسِنَةٍ","transliteration":"bi-alsinatin","translation_bn":"নিয়ে ভাষা","root":"لسن","lemma":"لِسَان","grammar_bn":"অব্যয় (Preposition)"},{"id":22151,"position":21,"text_uthmani":"حِدَادٍ","transliteration":"ḥidādin","translation_bn":"তীক্ষ্ণ","root":"حدد","lemma":"حِدَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":22152,"position":22,"text_uthmani":"أَشِحَّةً","transliteration":"ashiḥḥatan","translation_bn":"লোভবশত","root":"شحح","lemma":"شُحّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":22153,"position":23,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"ক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22154,"position":24,"text_uthmani":"ٱلْخَيْرِ ۚ","transliteration":"l-khayri","translation_bn":"ধনমালের (বা স্বার্থ সুযোগের)","root":"خير","lemma":"خَيْر","grammar_bn":"শব্দ"},{"id":22156,"position":25,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐ সব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22157,"position":26,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":22158,"position":27,"text_uthmani":"يُؤْمِنُوا۟","transliteration":"yu''minū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22159,"position":28,"text_uthmani":"فَأَحْبَطَ","transliteration":"fa-aḥbaṭa","translation_bn":"সুতরাং নষ্ট করে দিয়েছেন","root":"حبط","lemma":"أَحْبَطَ","grammar_bn":"শব্দ"},{"id":22160,"position":29,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22161,"position":30,"text_uthmani":"أَعْمَـٰلَهُمْ ۚ","transliteration":"aʿmālahum","translation_bn":"কর্মসমূহ তাদের","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":22163,"position":31,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22164,"position":32,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22165,"position":33,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"পক্ষে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22166,"position":34,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22167,"position":35,"text_uthmani":"يَسِيرًۭا","transliteration":"yasīran","translation_bn":"সহজ","root":"يسر","lemma":"يَسِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":22168,"position":36,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'ashiḥḥatan ʿalaykum fa-idhā jāa l-khawfu ra-aytahum yanẓurūna ilayka tadūru aʿyunuhum ka-alladhī yugh''shā ʿalayhi mina l-mawti fa-idhā dhahaba l-khawfu salaqūkum bi-alsinatin ḥidādin ashiḥḥatan ʿalā l-khayri ulāika lam yu''minū fa-aḥbaṭa l-lahu aʿmālahum wakāna dhālika ʿalā l-lahi yasīran', 'তোমাদের প্রতি কৃপণতার বশবর্তী হয়ে। যখন বিপদ আসে তখন তুমি তাদেরকে দেখবে মৃত্যু ভয়ে অচেতন ব্যক্তির ন্যায় চোখ উল্টিয়ে তারা তোমার দিকে তাকাচ্ছে। অতঃপর বিপদ যখন কেটে যায় তখন ধনের লালসায় তারা তোমাদেরকে তীক্ষ্ম বাক্য-বাণে বিদ্ধ করে। এরা ঈমান আনেনি। এজন্য আল্লাহ তাদের কার্যাবলী নিস্ফল করে দিয়েছেন, আর তা আল্লাহর জন্য সহজ।', 'Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allah has rendered their deeds worthless, and ever is that, for Allah, easy.', 'তোমাদের প্রতি কৃপণতার বশবর্তী হয়ে। যখন বিপদ আসে তখন তুমি তাদেরকে দেখবে মৃত্যু ভয়ে অচেতন ব্যক্তির ন্যায় চোখ উল্টিয়ে তারা তোমার দিকে তাকাচ্ছে। অতঃপর বিপদ যখন কেটে যায় তখন ধনের লালসায় তারা তোমাদেরকে তীক্ষ্ম বাক্য-বাণে বিদ্ধ করে। এরা ঈমান আনেনি। এজন্য আল্লাহ তাদের কার্যাবলী নিস্ফল করে দিয়েছেন, আর তা আল্লাহর জন্য সহজ।', 'Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allah has rendered their deeds worthless, and ever is that, for Allah, easy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033019.mp3', now()),
  (33, 20, '', '[{"id":23189,"position":1,"text_uthmani":"يَحْسَبُونَ","transliteration":"yaḥsabūna","translation_bn":"তারা মনে করে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23190,"position":2,"text_uthmani":"ٱلْأَحْزَابَ","transliteration":"l-aḥzāba","translation_bn":"(আক্রমণকারী) দলসমূহ","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":23191,"position":3,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":23192,"position":4,"text_uthmani":"يَذْهَبُوا۟ ۖ","transliteration":"yadhhabū","translation_bn":"চলে যায়","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23194,"position":5,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23195,"position":6,"text_uthmani":"يَأْتِ","transliteration":"yati","translation_bn":"(ফিরে) আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":23196,"position":7,"text_uthmani":"ٱلْأَحْزَابُ","transliteration":"l-aḥzābu","translation_bn":"দলসমূহ","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":23197,"position":8,"text_uthmani":"يَوَدُّوا۟","transliteration":"yawaddū","translation_bn":"তারা কামনা করবে","root":"ودد","lemma":"وَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23198,"position":9,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":23199,"position":10,"text_uthmani":"أَنَّهُم","transliteration":"annahum","translation_bn":"(এমন হতো) যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":23200,"position":11,"text_uthmani":"بَادُونَ","transliteration":"bādūna","translation_bn":"অবস্হানকারী","root":"بدو","lemma":"بَادُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":23201,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23202,"position":13,"text_uthmani":"ٱلْأَعْرَابِ","transliteration":"l-aʿrābi","translation_bn":"মরুবাসীদের","root":"عرب","lemma":"أَعْرَاب","grammar_bn":"শব্দ"},{"id":23203,"position":14,"text_uthmani":"يَسْـَٔلُونَ","transliteration":"yasalūna","translation_bn":"জিজ্ঞাসাবাদ করতো","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23204,"position":15,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23205,"position":16,"text_uthmani":"أَنۢبَآئِكُمْ ۖ","transliteration":"anbāikum","translation_bn":"সংবাদ তোমাদের (সেখানে বসে)","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23207,"position":17,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23208,"position":18,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23209,"position":19,"text_uthmani":"فِيكُم","transliteration":"fīkum","translation_bn":"মাঝে তোমাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23210,"position":20,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23211,"position":21,"text_uthmani":"قَـٰتَلُوٓا۟","transliteration":"qātalū","translation_bn":"তারা যুদ্ধ করতো","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23212,"position":22,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":23213,"position":23,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"অল্পই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23214,"position":24,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'yaḥsabūna l-aḥzāba lam yadhhabū wa-in yati l-aḥzābu yawaddū law annahum bādūna fī l-aʿrābi yasalūna ʿan anbāikum walaw kānū fīkum mā qātalū illā qalīlan', 'তারা মনে করে সম্মিলিত বাহিনী চলে যায়নি। সম্মিলিত বাহিনী যদি আবার এসে যায়, তাহলে তারা কামনা করবে যে, যদি মরুচারীদের মধ্যে থেকে তারা তোমাদের সংবাদ নিতে পারত! তারা তোমাদের মধ্যে অবস্থান করলেও তারা যুদ্ধ সামান্যই করত।', 'They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little.', 'তারা মনে করে সম্মিলিত বাহিনী চলে যায়নি। সম্মিলিত বাহিনী যদি আবার এসে যায়, তাহলে তারা কামনা করবে যে, যদি মরুচারীদের মধ্যে থেকে তারা তোমাদের সংবাদ নিতে পারত! তারা তোমাদের মধ্যে অবস্থান করলেও তারা যুদ্ধ সামান্যই করত।', 'They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033020.mp3', now()),
  (33, 21, '', '[{"id":24214,"position":1,"text_uthmani":"لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24215,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"রয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24216,"position":3,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":24217,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24218,"position":5,"text_uthmani":"رَسُولِ","transliteration":"rasūli","translation_bn":"রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":24219,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24220,"position":7,"text_uthmani":"أُسْوَةٌ","transliteration":"us''watun","translation_bn":"আদর্শ","root":"اسو","lemma":"أُسْوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24221,"position":8,"text_uthmani":"حَسَنَةٌۭ","transliteration":"ḥasanatun","translation_bn":"উত্তম","root":"حسن","lemma":"حَسَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24222,"position":9,"text_uthmani":"لِّمَن","transliteration":"liman","translation_bn":"(তার) জন্যে যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24223,"position":10,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24224,"position":11,"text_uthmani":"يَرْجُوا۟","transliteration":"yarjū","translation_bn":"আশা রাখে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":24225,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24226,"position":13,"text_uthmani":"وَٱلْيَوْمَ","transliteration":"wal-yawma","translation_bn":"ও দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24227,"position":14,"text_uthmani":"ٱلْـَٔاخِرَ","transliteration":"l-ākhira","translation_bn":"শেষ","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":24228,"position":15,"text_uthmani":"وَذَكَرَ","transliteration":"wadhakara","translation_bn":"এবং স্মরণ করে","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24229,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24230,"position":17,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অধিক","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":24231,"position":18,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'laqad kāna lakum fī rasūli l-lahi us''watun ḥasanatun liman kāna yarjū l-laha wal-yawma l-ākhira wadhakara l-laha kathīran', 'তোমাদের জন্য আল্লাহর রসূলের মধ্যে উত্তম আদর্শ রয়েছে যারা আল্লাহ ও শেষ দিনের আশা রাখে আর আল্লাহকে অধিক স্মরণ করে।', 'There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often.', 'তোমাদের জন্য আল্লাহর রসূলের মধ্যে উত্তম আদর্শ রয়েছে যারা আল্লাহ ও শেষ দিনের আশা রাখে আর আল্লাহকে অধিক স্মরণ করে।', 'There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033021.mp3', now()),
  (33, 22, '', '[{"id":25191,"position":1,"text_uthmani":"وَلَمَّا","transliteration":"walammā","translation_bn":"এবং যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25192,"position":2,"text_uthmani":"رَءَا","transliteration":"raā","translation_bn":"দেখলো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":25193,"position":3,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু’মিনরা","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":25194,"position":4,"text_uthmani":"ٱلْأَحْزَابَ","transliteration":"l-aḥzāba","translation_bn":"(শত্রু) দলগুলোকে","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":25195,"position":5,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25196,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"এটাই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25197,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"(তা) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25198,"position":8,"text_uthmani":"وَعَدَنَا","transliteration":"waʿadanā","translation_bn":"আমাদের কাছে অঙ্গীকার করেছেন","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25199,"position":9,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25200,"position":10,"text_uthmani":"وَرَسُولُهُۥ","transliteration":"warasūluhu","translation_bn":"ও তাঁর রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25201,"position":11,"text_uthmani":"وَصَدَقَ","transliteration":"waṣadaqa","translation_bn":"এবং সত্য বলেছেন","root":"صدق","lemma":"صَدَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25202,"position":12,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25203,"position":13,"text_uthmani":"وَرَسُولُهُۥ ۚ","transliteration":"warasūluhu","translation_bn":"ও তাঁর রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25205,"position":14,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25206,"position":15,"text_uthmani":"زَادَهُمْ","transliteration":"zādahum","translation_bn":"বৃদ্ধি পায় তাদের(অন্য কিছু)","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25207,"position":16,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":25208,"position":17,"text_uthmani":"إِيمَـٰنًۭا","transliteration":"īmānan","translation_bn":"ঈমান","root":"امن","lemma":"إِيمَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":25209,"position":18,"text_uthmani":"وَتَسْلِيمًۭا","transliteration":"wataslīman","translation_bn":"ও (তাঁর) আনুগত্য","root":"سلم","lemma":"تَسْلِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25210,"position":19,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'walammā raā l-mu''minūna l-aḥzāba qālū hādhā mā waʿadanā l-lahu warasūluhu waṣadaqa l-lahu warasūluhu wamā zādahum illā īmānan wataslīman', 'মু’মিনরা যখন সম্মিলিত বাহিনীকে দেখল তখন তারা বলে উঠল- আল্লাহ ও তাঁর রসূল এরই ওয়া‘দা আমাদেরকে দিয়েছিলেন এবং আল্লাহ ও তাঁর রসূল সত্য বলেছেন। এতে তাদের ঈমান ও আনুগত্যের আগ্রহই বৃদ্ধি পেল।', 'And when the believers saw the companies, they said, "This is what Allah and His Messenger had promised us, and Allah and His Messenger spoke the truth." And it increased them only in faith and acceptance.', 'মু’মিনরা যখন সম্মিলিত বাহিনীকে দেখল তখন তারা বলে উঠল- আল্লাহ ও তাঁর রসূল এরই ওয়া‘দা আমাদেরকে দিয়েছিলেন এবং আল্লাহ ও তাঁর রসূল সত্য বলেছেন। এতে তাদের ঈমান ও আনুগত্যের আগ্রহই বৃদ্ধি পেল।', 'And when the believers saw the companies, they said, "This is what Allah and His Messenger had promised us, and Allah and His Messenger spoke the truth." And it increased them only in faith and acceptance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033022.mp3', now()),
  (33, 23, '', '[{"id":26297,"position":1,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26298,"position":2,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":26299,"position":3,"text_uthmani":"رِجَالٌۭ","transliteration":"rijālun","translation_bn":"(কিছু) লোক","root":"رجل","lemma":"رِجَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":26300,"position":4,"text_uthmani":"صَدَقُوا۟","transliteration":"ṣadaqū","translation_bn":"সত্য প্রমাণ করেছে","root":"صدق","lemma":"صَدَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26301,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26302,"position":6,"text_uthmani":"عَـٰهَدُوا۟","transliteration":"ʿāhadū","translation_bn":"তারা অঙ্গীকার করেছিলো","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26303,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26304,"position":8,"text_uthmani":"عَلَيْهِ ۖ","transliteration":"ʿalayhi","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26306,"position":9,"text_uthmani":"فَمِنْهُم","transliteration":"famin''hum","translation_bn":"অতঃপর মধ্য থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26307,"position":10,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"কেউ","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26308,"position":11,"text_uthmani":"قَضَىٰ","transliteration":"qaḍā","translation_bn":"পূর্ণ করেছে","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":26309,"position":12,"text_uthmani":"نَحْبَهُۥ","transliteration":"naḥbahu","translation_bn":"ব্রত তার (শহীদ হয়েছে)","root":"نحب","lemma":"نَحْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26310,"position":13,"text_uthmani":"وَمِنْهُم","transliteration":"wamin''hum","translation_bn":"আবার মধ্যে হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26311,"position":14,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"কেউ","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26312,"position":15,"text_uthmani":"يَنتَظِرُ ۖ","transliteration":"yantaẓiru","translation_bn":"অপেক্ষায় আছে","root":"نظر","lemma":"يَنتَظِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26314,"position":16,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26315,"position":17,"text_uthmani":"بَدَّلُوا۟","transliteration":"baddalū","translation_bn":"তারা পরিবর্তন করেছে","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26316,"position":18,"text_uthmani":"تَبْدِيلًۭا","transliteration":"tabdīlan","translation_bn":"কোনো পরিবর্তন","root":"بدل","lemma":"تَبْدِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26317,"position":19,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'mina l-mu''minīna rijālun ṣadaqū mā ʿāhadū l-laha ʿalayhi famin''hum man qaḍā naḥbahu wamin''hum man yantaẓiru wamā baddalū tabdīlan', 'মু’মিনদের মধ্যে কতক লোক আল্লাহর সঙ্গে কৃত তাদের অঙ্গীকার সত্যে পরিণত করেছে। তাদের কতক উদ্দেশ্য বাস্তবায়নে (শাহাদাত বরণ) করেছে আর তাদের কতক অপেক্ষায় আছে। তারা (তাদের সংকল্প) কখনো তিল পরিমাণ পরিবর্তন করেনি।', 'Among the believers are men true to what they promised Allah. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -', 'মু’মিনদের মধ্যে কতক লোক আল্লাহর সঙ্গে কৃত তাদের অঙ্গীকার সত্যে পরিণত করেছে। তাদের কতক উদ্দেশ্য বাস্তবায়নে (শাহাদাত বরণ) করেছে আর তাদের কতক অপেক্ষায় আছে। তারা (তাদের সংকল্প) কখনো তিল পরিমাণ পরিবর্তন করেনি।', 'Among the believers are men true to what they promised Allah. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033023.mp3', now()),
  (33, 24, '', '[{"id":27331,"position":1,"text_uthmani":"لِّيَجْزِىَ","transliteration":"liyajziya","translation_bn":"যেন পুরস্কার দেন","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"শব্দ"},{"id":27332,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27333,"position":3,"text_uthmani":"ٱلصَّـٰدِقِينَ","transliteration":"l-ṣādiqīna","translation_bn":"সত্যবাদীদেরকে","root":"صدق","lemma":"صَادِق","grammar_bn":"শব্দ"},{"id":27334,"position":4,"text_uthmani":"بِصِدْقِهِمْ","transliteration":"biṣid''qihim","translation_bn":"কারণে সত্যবাদীতার তাদের","root":"صدق","lemma":"صِدْق","grammar_bn":"অব্যয় (Preposition)"},{"id":27335,"position":5,"text_uthmani":"وَيُعَذِّبَ","transliteration":"wayuʿadhiba","translation_bn":"এবং শাস্তি দেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27336,"position":6,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফিকদেরকে","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":27337,"position":7,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":27338,"position":8,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27339,"position":9,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27340,"position":10,"text_uthmani":"يَتُوبَ","transliteration":"yatūba","translation_bn":"ক্ষমা করে দিবেন","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27341,"position":11,"text_uthmani":"عَلَيْهِمْ ۚ","transliteration":"ʿalayhim","translation_bn":"প্রতি তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27343,"position":12,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27344,"position":13,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27345,"position":14,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27346,"position":15,"text_uthmani":"غَفُورًۭا","transliteration":"ghafūran","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":27347,"position":16,"text_uthmani":"رَّحِيمًۭا","transliteration":"raḥīman","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":27348,"position":17,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'liyajziya l-lahu l-ṣādiqīna biṣid''qihim wayuʿadhiba l-munāfiqīna in shāa aw yatūba ʿalayhim inna l-laha kāna ghafūran raḥīman', 'যাতে আল্লাহ (ওয়া‘দার প্রতি) সত্যবাদীদেরকে তাদের সত্যবাদিতার পুরস্কার দেন আর মুনাফিকদেরকে ইচ্ছে করলে শাস্তি দেন অথবা তাদেরকে ক্ষমা করেন। আল্লাহ পরম ক্ষমাশীল, পরম দয়ালু।', 'That Allah may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allah is ever Forgiving and Merciful.', 'যাতে আল্লাহ (ওয়া‘দার প্রতি) সত্যবাদীদেরকে তাদের সত্যবাদিতার পুরস্কার দেন আর মুনাফিকদেরকে ইচ্ছে করলে শাস্তি দেন অথবা তাদেরকে ক্ষমা করেন। আল্লাহ পরম ক্ষমাশীল, পরম দয়ালু।', 'That Allah may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allah is ever Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033024.mp3', now()),
  (33, 25, '', '[{"id":28402,"position":1,"text_uthmani":"وَرَدَّ","transliteration":"waradda","translation_bn":"এবং ফিরিয়ে দিলেন","root":"ردد","lemma":"رَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28403,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28404,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28405,"position":4,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28406,"position":5,"text_uthmani":"بِغَيْظِهِمْ","transliteration":"bighayẓihim","translation_bn":"সহ মনের জ্বালা তাদের","root":"غيظ","lemma":"غَيْظ","grammar_bn":"অব্যয় (Preposition)"},{"id":28407,"position":6,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":28408,"position":7,"text_uthmani":"يَنَالُوا۟","transliteration":"yanālū","translation_bn":"তারা পায়","root":"نيل","lemma":"يَنَالُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28409,"position":8,"text_uthmani":"خَيْرًۭا ۚ","transliteration":"khayran","translation_bn":"কল্যাণ","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":28411,"position":9,"text_uthmani":"وَكَفَى","transliteration":"wakafā","translation_bn":"এবং যথেষ্ট","root":"كفي","lemma":"كَفَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28412,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28413,"position":11,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের (জন্যে)","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":28414,"position":12,"text_uthmani":"ٱلْقِتَالَ ۚ","transliteration":"l-qitāla","translation_bn":"যুদ্ধে","root":"قتل","lemma":"قِتَال","grammar_bn":"শব্দ"},{"id":28416,"position":13,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28417,"position":14,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28418,"position":15,"text_uthmani":"قَوِيًّا","transliteration":"qawiyyan","translation_bn":"শক্তিমান","root":"قوي","lemma":"قَوِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28419,"position":16,"text_uthmani":"عَزِيزًۭا","transliteration":"ʿazīzan","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"বিশেষণ (Adjective)"},{"id":28420,"position":17,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'waradda l-lahu alladhīna kafarū bighayẓihim lam yanālū khayran wakafā l-lahu l-mu''minīna l-qitāla wakāna l-lahu qawiyyan ʿazīzan', 'আর আল্লাহ কাফিরদেরকে তাদের রাগের অবস্থাতেই ফিরিয়ে দিলেন, তারা কোন কল্যাণ লাভ করতে পারেনি। যুদ্ধে মু’মিনদের জন্য আল্লাহই যথেষ্ট। আল্লাহ সর্বশক্তিমান, মহাপরাক্রমশালী।', 'And Allah repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allah for the believers in battle, and ever is Allah Powerful and Exalted in Might.', 'আর আল্লাহ কাফিরদেরকে তাদের রাগের অবস্থাতেই ফিরিয়ে দিলেন, তারা কোন কল্যাণ লাভ করতে পারেনি। যুদ্ধে মু’মিনদের জন্য আল্লাহই যথেষ্ট। আল্লাহ সর্বশক্তিমান, মহাপরাক্রমশালী।', 'And Allah repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allah for the believers in battle, and ever is Allah Powerful and Exalted in Might.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033025.mp3', now()),
  (33, 26, '', '[{"id":29303,"position":1,"text_uthmani":"وَأَنزَلَ","transliteration":"wa-anzala","translation_bn":"এবং নামিয়ে দিলেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29304,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29305,"position":3,"text_uthmani":"ظَـٰهَرُوهُم","transliteration":"ẓāharūhum","translation_bn":"সাহায্য করেছিলো তাদের","root":"ظهر","lemma":"ظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29306,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29307,"position":5,"text_uthmani":"أَهْلِ","transliteration":"ahli","translation_bn":"অধিকারীদের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29308,"position":6,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":29309,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29310,"position":8,"text_uthmani":"صَيَاصِيهِمْ","transliteration":"ṣayāṣīhim","translation_bn":"দূর্গসমূহ তাদের","root":"صيص","lemma":"صَيَاصِي","grammar_bn":"বিশেষ্য (Noun)"},{"id":29311,"position":9,"text_uthmani":"وَقَذَفَ","transliteration":"waqadhafa","translation_bn":"এবং সঞ্চার করলেন","root":"قذف","lemma":"قَذَفَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29312,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29313,"position":11,"text_uthmani":"قُلُوبِهِمُ","transliteration":"qulūbihimu","translation_bn":"অন্তসমূহের তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":29314,"position":12,"text_uthmani":"ٱلرُّعْبَ","transliteration":"l-ruʿ''ba","translation_bn":"ভয়","root":"رعب","lemma":"رُعْب","grammar_bn":"শব্দ"},{"id":29315,"position":13,"text_uthmani":"فَرِيقًۭا","transliteration":"farīqan","translation_bn":"(এখন) এক দলকে","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":29316,"position":14,"text_uthmani":"تَقْتُلُونَ","transliteration":"taqtulūna","translation_bn":"তোমরা হত্যা করছো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29317,"position":15,"text_uthmani":"وَتَأْسِرُونَ","transliteration":"watasirūna","translation_bn":"এবং তোমরা বন্দী করছো","root":"اسر","lemma":"تَأْسِرُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29318,"position":16,"text_uthmani":"فَرِيقًۭا","transliteration":"farīqan","translation_bn":"(অপর) দলকে","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":29319,"position":17,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-anzala alladhīna ẓāharūhum min ahli l-kitābi min ṣayāṣīhim waqadhafa fī qulūbihimu l-ruʿ''ba farīqan taqtulūna watasirūna farīqan', 'আর গ্রন্থধারীদের মধ্য হতে যারা তাদেরকে (অর্থাৎ সম্মিলিত কাফির বাহিনীকে) সাহায্য করেছিল তাদেরকে তিনি তাদের দূর্গ হতে নামিয়ে দিলেন এবং তাদের অন্তরে ভীতি নিক্ষেপ করলেন। তাদের কতককে তোমরা হত্যা করলে, আর কতককে করলে বন্দী।', 'And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party you killed, and you took captive a party.', 'আর গ্রন্থধারীদের মধ্য হতে যারা তাদেরকে (অর্থাৎ সম্মিলিত কাফির বাহিনীকে) সাহায্য করেছিল তাদেরকে তিনি তাদের দূর্গ হতে নামিয়ে দিলেন এবং তাদের অন্তরে ভীতি নিক্ষেপ করলেন। তাদের কতককে তোমরা হত্যা করলে, আর কতককে করলে বন্দী।', 'And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party you killed, and you took captive a party.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033026.mp3', now()),
  (33, 27, '', '[{"id":30282,"position":1,"text_uthmani":"وَأَوْرَثَكُمْ","transliteration":"wa-awrathakum","translation_bn":"এবং উত্তরাধিকারী বানালেন তোমাদেরকে","root":"ورث","lemma":"أَوْرَثَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30283,"position":2,"text_uthmani":"أَرْضَهُمْ","transliteration":"arḍahum","translation_bn":"জায়গা জমির তাদের","root":"ارض","lemma":"أَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":30284,"position":3,"text_uthmani":"وَدِيَـٰرَهُمْ","transliteration":"wadiyārahum","translation_bn":"ও ঘর বাড়িসমূহের তাদের","root":"دور","lemma":"دَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30285,"position":4,"text_uthmani":"وَأَمْوَٰلَهُمْ","transliteration":"wa-amwālahum","translation_bn":"ও ধনসম্পদের তাদের","root":"مول","lemma":"مَال","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30286,"position":5,"text_uthmani":"وَأَرْضًۭا","transliteration":"wa-arḍan","translation_bn":"এবং (এমন)এক দেশের","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30287,"position":6,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"(যা) নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":30288,"position":7,"text_uthmani":"تَطَـُٔوهَا ۚ","transliteration":"taṭaūhā","translation_bn":"তোমরা পা রাখো তাতে","root":"وطا","lemma":"يَطَـ#ُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30290,"position":8,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30291,"position":9,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30292,"position":10,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30293,"position":11,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30294,"position":12,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":30295,"position":13,"text_uthmani":"قَدِيرًۭا","transliteration":"qadīran","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":30296,"position":14,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-awrathakum arḍahum wadiyārahum wa-amwālahum wa-arḍan lam taṭaūhā wakāna l-lahu ʿalā kulli shayin qadīran', 'আর তিনি তোমাদেরকে উত্তরাধিকারী করে দিলেন তাদের ভূমির, তাদের ঘরবাড়ির আর তাদের ধন-সম্পদের; আর এমন এক ভূখন্ডের যেখানে তোমরা (এখনও) অভিযানই পরিচালনা করনি। আল্লাহ সর্ববিষয়ে ক্ষমতাবান।', 'And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allah, over all things, competent.', 'আর তিনি তোমাদেরকে উত্তরাধিকারী করে দিলেন তাদের ভূমির, তাদের ঘরবাড়ির আর তাদের ধন-সম্পদের; আর এমন এক ভূখন্ডের যেখানে তোমরা (এখনও) অভিযানই পরিচালনা করনি। আল্লাহ সর্ববিষয়ে ক্ষমতাবান।', 'And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allah, over all things, competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033027.mp3', now()),
  (33, 28, '', '[{"id":31282,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":31283,"position":2,"text_uthmani":"ٱلنَّبِىُّ","transliteration":"l-nabiyu","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":31284,"position":3,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31285,"position":4,"text_uthmani":"لِّأَزْوَٰجِكَ","transliteration":"li-azwājika","translation_bn":"উদ্দেশ্যে তোমার স্ত্রীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"অব্যয় (Preposition)"},{"id":31286,"position":5,"text_uthmani":"إِن","transliteration":"in","translation_bn":"\"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":31287,"position":6,"text_uthmani":"كُنتُنَّ","transliteration":"kuntunna","translation_bn":"তোমরা হও (এমন যে)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31288,"position":7,"text_uthmani":"تُرِدْنَ","transliteration":"turid''na","translation_bn":"তোমরা পেতে চাও","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31289,"position":8,"text_uthmani":"ٱلْحَيَوٰةَ","transliteration":"l-ḥayata","translation_bn":"জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":31290,"position":9,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":31291,"position":10,"text_uthmani":"وَزِينَتَهَا","transliteration":"wazīnatahā","translation_bn":"ও চাকচিক্য তার","root":"زين","lemma":"زِينَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31292,"position":11,"text_uthmani":"فَتَعَالَيْنَ","transliteration":"fataʿālayna","translation_bn":"তবে তোমরা এসো","root":"علو","lemma":"تَعَالَ","grammar_bn":"শব্দ"},{"id":31293,"position":12,"text_uthmani":"أُمَتِّعْكُنَّ","transliteration":"umattiʿ''kunna","translation_bn":"আমি ভোগসামগ্রী দিয়ে দিই তোমাদেরকে","root":"متع","lemma":"مَّتَّعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31294,"position":13,"text_uthmani":"وَأُسَرِّحْكُنَّ","transliteration":"wa-usarriḥ''kunna","translation_bn":"ও আমি বিদায় দিই তোমাদেরকে","root":"سرح","lemma":"سَرِّحُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31295,"position":14,"text_uthmani":"سَرَاحًۭا","transliteration":"sarāḥan","translation_bn":"বিদায়","root":"سرح","lemma":"سَرَاح","grammar_bn":"বিশেষ্য (Noun)"},{"id":31296,"position":15,"text_uthmani":"جَمِيلًۭا","transliteration":"jamīlan","translation_bn":"সৌজন্যের সাথে","root":"جمل","lemma":"جَمِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":31297,"position":16,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nabiyu qul li-azwājika in kuntunna turid''na l-ḥayata l-dun''yā wazīnatahā fataʿālayna umattiʿ''kunna wa-usarriḥ''kunna sarāḥan jamīlan', 'হে নবী (সা.)! তুমি তোমার স্ত্রীদের বলে দাও- তোমরা যদি পার্থিব জীবন আর তার শোভাসৌন্দর্য কামনা কর, তাহলে এসো, তোমাদেরকে ভোগসামগ্রী দিয়ে দেই এবং উত্তম পন্থায় তোমাদেরকে বিদায় দেই।', 'O Prophet, say to your wives, "If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release.', 'হে নবী (সা.)! তুমি তোমার স্ত্রীদের বলে দাও- তোমরা যদি পার্থিব জীবন আর তার শোভাসৌন্দর্য কামনা কর, তাহলে এসো, তোমাদেরকে ভোগসামগ্রী দিয়ে দেই এবং উত্তম পন্থায় তোমাদেরকে বিদায় দেই।', 'O Prophet, say to your wives, "If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033028.mp3', now()),
  (33, 29, '', '[{"id":32271,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32272,"position":2,"text_uthmani":"كُنتُنَّ","transliteration":"kuntunna","translation_bn":"তোমরা হও (এমন যে)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32273,"position":3,"text_uthmani":"تُرِدْنَ","transliteration":"turid''na","translation_bn":"তোমরা চাও","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32274,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32275,"position":5,"text_uthmani":"وَرَسُولَهُۥ","transliteration":"warasūlahu","translation_bn":"ও তাঁর রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32276,"position":6,"text_uthmani":"وَٱلدَّارَ","transliteration":"wal-dāra","translation_bn":"ও ঘরকে","root":"دور","lemma":"دَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32277,"position":7,"text_uthmani":"ٱلْـَٔاخِرَةَ","transliteration":"l-ākhirata","translation_bn":"আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":32278,"position":8,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"তবে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":32279,"position":9,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32280,"position":10,"text_uthmani":"أَعَدَّ","transliteration":"aʿadda","translation_bn":"প্রস্তুত করে রেখেছেন","root":"عدد","lemma":"أَعَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32281,"position":11,"text_uthmani":"لِلْمُحْسِنَـٰتِ","transliteration":"lil''muḥ''sināti","translation_bn":"জন্যে সৎকর্মশীলদের","root":"حسن","lemma":"مُحْسِنَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":32282,"position":12,"text_uthmani":"مِنكُنَّ","transliteration":"minkunna","translation_bn":"মধ্য হ''তে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32283,"position":13,"text_uthmani":"أَجْرًا","transliteration":"ajran","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":32284,"position":14,"text_uthmani":"عَظِيمًۭا","transliteration":"ʿaẓīman","translation_bn":"মহা\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":32285,"position":15,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in kuntunna turid''na l-laha warasūlahu wal-dāra l-ākhirata fa-inna l-laha aʿadda lil''muḥ''sināti minkunna ajran ʿaẓīman', 'আর তোমরা যদি আল্লাহ, তাঁর রসূল ও পরকালের গৃহ কামনা কর, তবে তোমাদের মধ্যে যারা সৎকর্মশীল তাদের জন্য আল্লাহ মহা পুরস্কার প্রস্তুত করে রেখেছেন।', 'But if you should desire Allah and His Messenger and the home of the Hereafter - then indeed, Allah has prepared for the doers of good among you a great reward."', 'আর তোমরা যদি আল্লাহ, তাঁর রসূল ও পরকালের গৃহ কামনা কর, তবে তোমাদের মধ্যে যারা সৎকর্মশীল তাদের জন্য আল্লাহ মহা পুরস্কার প্রস্তুত করে রেখেছেন।', 'But if you should desire Allah and His Messenger and the home of the Hereafter - then indeed, Allah has prepared for the doers of good among you a great reward."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033029.mp3', now()),
  (33, 30, '', '[{"id":33114,"position":1,"text_uthmani":"يَـٰنِسَآءَ","transliteration":"yānisāa","translation_bn":"হে স্ত্রীগণ","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":33115,"position":2,"text_uthmani":"ٱلنَّبِىِّ","transliteration":"l-nabiyi","translation_bn":"নাবীর","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":33116,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":33117,"position":4,"text_uthmani":"يَأْتِ","transliteration":"yati","translation_bn":"আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":33118,"position":5,"text_uthmani":"مِنكُنَّ","transliteration":"minkunna","translation_bn":"মধ্য হ''তে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33119,"position":6,"text_uthmani":"بِفَـٰحِشَةٍۢ","transliteration":"bifāḥishatin","translation_bn":"নিয়ে (করে)অশ্লীল কাজ","root":"فحش","lemma":"فَٰحِشَة","grammar_bn":"অব্যয় (Preposition)"},{"id":33120,"position":7,"text_uthmani":"مُّبَيِّنَةٍۢ","transliteration":"mubayyinatin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبَيِّنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33121,"position":8,"text_uthmani":"يُضَـٰعَفْ","transliteration":"yuḍāʿaf","translation_bn":"দ্বিগুণ দেয়া হবে","root":"ضعف","lemma":"يُضَٰعِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33122,"position":9,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"জন্যে তার","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":33123,"position":10,"text_uthmani":"ٱلْعَذَابُ","transliteration":"l-ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":33124,"position":11,"text_uthmani":"ضِعْفَيْنِ ۚ","transliteration":"ḍiʿ''fayni","translation_bn":"দ্বিগুণ","root":"ضعف","lemma":"ضِعْف","grammar_bn":"বিশেষণ (Adjective)"},{"id":33126,"position":12,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হ''লে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33127,"position":13,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":33128,"position":14,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33129,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":33130,"position":16,"text_uthmani":"يَسِيرًۭا","transliteration":"yasīran","translation_bn":"সহজ","root":"يسر","lemma":"يَسِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":33131,"position":17,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'yānisāa l-nabiyi man yati minkunna bifāḥishatin mubayyinatin yuḍāʿaf lahā l-ʿadhābu ḍiʿ''fayni wakāna dhālika ʿalā l-lahi yasīran', 'হে নবী পত্নীগণ! তোমাদের মধ্যে কেউ প্রকাশ্যে অশ্লীল কাজ করলে তাকে দ্বিগুণ শাস্তি দেয়া হবে। আল্লাহর জন্য এটা সহজ।', 'O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allah, easy.', 'হে নবী পত্নীগণ! তোমাদের মধ্যে কেউ প্রকাশ্যে অশ্লীল কাজ করলে তাকে দ্বিগুণ শাস্তি দেয়া হবে। আল্লাহর জন্য এটা সহজ।', 'O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allah, easy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033030.mp3', now()),
  (33, 31, '', '[{"id":34070,"position":1,"text_uthmani":"۞ وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34071,"position":2,"text_uthmani":"يَقْنُتْ","transliteration":"yaqnut","translation_bn":"অনুগত হবে","root":"قنت","lemma":"يَقْنُتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34072,"position":3,"text_uthmani":"مِنكُنَّ","transliteration":"minkunna","translation_bn":"মধ্য হ''তে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34073,"position":4,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"প্রতি আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":34074,"position":5,"text_uthmani":"وَرَسُولِهِۦ","transliteration":"warasūlihi","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34075,"position":6,"text_uthmani":"وَتَعْمَلْ","transliteration":"wataʿmal","translation_bn":"ও কাজ করবে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34076,"position":7,"text_uthmani":"صَـٰلِحًۭا","transliteration":"ṣāliḥan","translation_bn":"সৎ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":34077,"position":8,"text_uthmani":"نُّؤْتِهَآ","transliteration":"nu''tihā","translation_bn":"আমরা দিবো তাকে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":34078,"position":9,"text_uthmani":"أَجْرَهَا","transliteration":"ajrahā","translation_bn":"পুরস্কার তার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":34079,"position":10,"text_uthmani":"مَرَّتَيْنِ","transliteration":"marratayni","translation_bn":"দু’বার","root":"مرر","lemma":"مَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":34080,"position":11,"text_uthmani":"وَأَعْتَدْنَا","transliteration":"wa-aʿtadnā","translation_bn":"এবং প্রস্তুত করে রেখেছি আমরা","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34081,"position":12,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"জন্যে তার","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":34082,"position":13,"text_uthmani":"رِزْقًۭا","transliteration":"riz''qan","translation_bn":"জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":34083,"position":14,"text_uthmani":"كَرِيمًۭا","transliteration":"karīman","translation_bn":"সম্মানজনক","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":34084,"position":15,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'waman yaqnut minkunna lillahi warasūlihi wataʿmal ṣāliḥan nu''tihā ajrahā marratayni wa-aʿtadnā lahā riz''qan karīman', 'তোমাদের মধ্যে যে কেউ আল্লাহ ও তাঁর রসূলের অনুগত হবে আর সৎ কাজ করবে, আমি তাকে দু’বার পুরস্কার দেব আর তার জন্য আমি সম্মানজনক রিযক প্রস্তুত রেখেছি।', 'And whoever of you devoutly obeys Allah and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision.', 'তোমাদের মধ্যে যে কেউ আল্লাহ ও তাঁর রসূলের অনুগত হবে আর সৎ কাজ করবে, আমি তাকে দু’বার পুরস্কার দেব আর তার জন্য আমি সম্মানজনক রিযক প্রস্তুত রেখেছি।', 'And whoever of you devoutly obeys Allah and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033031.mp3', now()),
  (33, 32, '', '[{"id":34996,"position":1,"text_uthmani":"يَـٰنِسَآءَ","transliteration":"yānisāa","translation_bn":"হে স্ত্রীগণ","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":34997,"position":2,"text_uthmani":"ٱلنَّبِىِّ","transliteration":"l-nabiyi","translation_bn":"নাবীর","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":34998,"position":3,"text_uthmani":"لَسْتُنَّ","transliteration":"lastunna","translation_bn":"তোমরা নও","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34999,"position":4,"text_uthmani":"كَأَحَدٍۢ","transliteration":"ka-aḥadin","translation_bn":"মতো একজনের","root":"احد","lemma":"أَحَد","grammar_bn":"অব্যয় (Preposition)"},{"id":35000,"position":5,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্য কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35001,"position":6,"text_uthmani":"ٱلنِّسَآءِ ۚ","transliteration":"l-nisāi","translation_bn":"নারীদের","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"শব্দ"},{"id":35003,"position":7,"text_uthmani":"إِنِ","transliteration":"ini","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":35004,"position":8,"text_uthmani":"ٱتَّقَيْتُنَّ","transliteration":"ittaqaytunna","translation_bn":"তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35005,"position":9,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তবে না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":35006,"position":10,"text_uthmani":"تَخْضَعْنَ","transliteration":"takhḍaʿna","translation_bn":"কোমল করো","root":"خضع","lemma":"تَخْضَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35007,"position":11,"text_uthmani":"بِٱلْقَوْلِ","transliteration":"bil-qawli","translation_bn":"(অন্য পুরুষদের সাথে) কথাকে","root":"قول","lemma":"قَوْل","grammar_bn":"অব্যয় (Preposition)"},{"id":35008,"position":12,"text_uthmani":"فَيَطْمَعَ","transliteration":"fayaṭmaʿa","translation_bn":"ফলে প্রলুদ্ধ হয়","root":"طمع","lemma":"يَطْمَعُ","grammar_bn":"কারণবাচক (Cause)"},{"id":35009,"position":13,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(সে) যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":35010,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35011,"position":15,"text_uthmani":"قَلْبِهِۦ","transliteration":"qalbihi","translation_bn":"অন্তরে তার","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":35012,"position":16,"text_uthmani":"مَرَضٌۭ","transliteration":"maraḍun","translation_bn":"রোগ","root":"مرض","lemma":"مَّرَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":35013,"position":17,"text_uthmani":"وَقُلْنَ","transliteration":"waqul''na","translation_bn":"বরং তোমরা বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35014,"position":18,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35015,"position":19,"text_uthmani":"مَّعْرُوفًۭا","transliteration":"maʿrūfan","translation_bn":"সঙ্গতভাবে","root":"عرف","lemma":"مَّعْرُوف","grammar_bn":"বিশেষ্য (Noun)"},{"id":35016,"position":20,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'yānisāa l-nabiyi lastunna ka-aḥadin mina l-nisāi ini ittaqaytunna falā takhḍaʿna bil-qawli fayaṭmaʿa alladhī fī qalbihi maraḍun waqul''na qawlan maʿrūfan', 'হে নবী পত্নীগণ! তোমরা অন্য নারীদের মত নও। তোমরা যদি আল্লাহকে ভয় কর, তাহলে পর পুরুষের সঙ্গে আকর্ষণীয় ভঙ্গিতে কথা বলো না, যাতে যার অন্তরে ব্যাধি আছে সে প্রলুদ্ধ হয়। তোমরা সঙ্গত কথা বলবে।', 'O wives of the Prophet, you are not like anyone among women. If you fear Allah, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech.', 'হে নবী পত্নীগণ! তোমরা অন্য নারীদের মত নও। তোমরা যদি আল্লাহকে ভয় কর, তাহলে পর পুরুষের সঙ্গে আকর্ষণীয় ভঙ্গিতে কথা বলো না, যাতে যার অন্তরে ব্যাধি আছে সে প্রলুদ্ধ হয়। তোমরা সঙ্গত কথা বলবে।', 'O wives of the Prophet, you are not like anyone among women. If you fear Allah, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033032.mp3', now()),
  (33, 33, '', '[{"id":35869,"position":1,"text_uthmani":"وَقَرْنَ","transliteration":"waqarna","translation_bn":"এবং তোমরা অবস্থান করো","root":"قرر","lemma":"تَقَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35870,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35871,"position":3,"text_uthmani":"بُيُوتِكُنَّ","transliteration":"buyūtikunna","translation_bn":"ঘরগুলোর তোমাদের","root":"بيت","lemma":"بَيْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":35872,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35873,"position":5,"text_uthmani":"تَبَرَّجْنَ","transliteration":"tabarrajna","translation_bn":"তোমরা প্রদর্শন করো","root":"برج","lemma":"تَبَرَّجْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35874,"position":6,"text_uthmani":"تَبَرُّجَ","transliteration":"tabarruja","translation_bn":"প্রদর্শনী","root":"برج","lemma":"تَبَرُّج","grammar_bn":"বিশেষ্য (Noun)"},{"id":35875,"position":7,"text_uthmani":"ٱلْجَـٰهِلِيَّةِ","transliteration":"l-jāhiliyati","translation_bn":"অজ্ঞযুগের","root":"جهل","lemma":"جَٰهِلِيَّة2","grammar_bn":"শব্দ"},{"id":35876,"position":8,"text_uthmani":"ٱلْأُولَىٰ ۖ","transliteration":"l-ūlā","translation_bn":"প্রাচীন","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":35878,"position":9,"text_uthmani":"وَأَقِمْنَ","transliteration":"wa-aqim''na","translation_bn":"এবং তোমরা প্রতিষ্ঠিত করো","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35879,"position":10,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":35880,"position":11,"text_uthmani":"وَءَاتِينَ","transliteration":"waātīna","translation_bn":"ও তোমরা আদায় করো","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35881,"position":12,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":35882,"position":13,"text_uthmani":"وَأَطِعْنَ","transliteration":"wa-aṭiʿ''na","translation_bn":"এবং তোমরা আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35883,"position":14,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":35884,"position":15,"text_uthmani":"وَرَسُولَهُۥٓ ۚ","transliteration":"warasūlahu","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35886,"position":16,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"কেবল","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":35887,"position":17,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"চান","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35888,"position":18,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":35889,"position":19,"text_uthmani":"لِيُذْهِبَ","transliteration":"liyudh''hiba","translation_bn":"যাতে দূর করে দেন","root":"ذهب","lemma":"أَذْهَبَ","grammar_bn":"শব্দ"},{"id":35890,"position":20,"text_uthmani":"عَنكُمُ","transliteration":"ʿankumu","translation_bn":"হ''তে তোমাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35891,"position":21,"text_uthmani":"ٱلرِّجْسَ","transliteration":"l-rij''sa","translation_bn":"অপবিত্রতা","root":"رجس","lemma":"رِجْس","grammar_bn":"শব্দ"},{"id":35892,"position":22,"text_uthmani":"أَهْلَ","transliteration":"ahla","translation_bn":"(অর্থাৎ হ''তে) বাসিন্দাদের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":35893,"position":23,"text_uthmani":"ٱلْبَيْتِ","transliteration":"l-bayti","translation_bn":"(নাবীর) ঘরের","root":"بيت","lemma":"بَيْت","grammar_bn":"শব্দ"},{"id":35894,"position":24,"text_uthmani":"وَيُطَهِّرَكُمْ","transliteration":"wayuṭahhirakum","translation_bn":"এবং পবিত্র করবেন তোমাদেরকে","root":"طهر","lemma":"طَهَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35895,"position":25,"text_uthmani":"تَطْهِيرًۭا","transliteration":"taṭhīran","translation_bn":"সম্পূর্ণ পবিত্র","root":"طهر","lemma":"تَطْهِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":35896,"position":26,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'waqarna fī buyūtikunna walā tabarrajna tabarruja l-jāhiliyati l-ūlā wa-aqim''na l-ṣalata waātīna l-zakata wa-aṭiʿ''na l-laha warasūlahu innamā yurīdu l-lahu liyudh''hiba ʿankumu l-rij''sa ahla l-bayti wayuṭahhirakum taṭhīran', 'আর তোমরা নিজেদের গৃহে অবস্থান কর, প্রাচীন অজ্ঞতার যুগের মত চোখ ঝলসানো প্রদর্শনী করে বেড়িও না। আর তোমরা নামায প্রতিষ্ঠা কর, যাকাত প্রদান কর এবং আল্লাহ ও তাঁর রসূলের আনুগত্য কর। হে নবীর পরিবার! আল্লাহ কেবল চান তোমাদের থেকে অপবিত্রতা দূর করতে এবং তোমাদেরকে পবিত্র ও নিষ্কলংক করতে।', 'And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakah and obey Allah and His Messenger. Allah intends only to remove from you the impurity [of sin], O people of the [Prophet''s] household, and to purify you with [extensive] purification.', 'আর তোমরা নিজেদের গৃহে অবস্থান কর, প্রাচীন অজ্ঞতার যুগের মত চোখ ঝলসানো প্রদর্শনী করে বেড়িও না। আর তোমরা নামায প্রতিষ্ঠা কর, যাকাত প্রদান কর এবং আল্লাহ ও তাঁর রসূলের আনুগত্য কর। হে নবীর পরিবার! আল্লাহ কেবল চান তোমাদের থেকে অপবিত্রতা দূর করতে এবং তোমাদেরকে পবিত্র ও নিষ্কলংক করতে।', 'And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakah and obey Allah and His Messenger. Allah intends only to remove from you the impurity [of sin], O people of the [Prophet''s] household, and to purify you with [extensive] purification.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033033.mp3', now()),
  (33, 34, '', '[{"id":36759,"position":1,"text_uthmani":"وَٱذْكُرْنَ","transliteration":"wa-udh''kur''na","translation_bn":"এবং তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36760,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":36761,"position":3,"text_uthmani":"يُتْلَىٰ","transliteration":"yut''lā","translation_bn":"তিলাওয়াত করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36762,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36763,"position":5,"text_uthmani":"بُيُوتِكُنَّ","transliteration":"buyūtikunna","translation_bn":"তোমাদের ঘরগুলোর","root":"بيت","lemma":"بَيْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":36764,"position":6,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36765,"position":7,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":36766,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36767,"position":9,"text_uthmani":"وَٱلْحِكْمَةِ ۚ","transliteration":"wal-ḥik''mati","translation_bn":"ও প্রজ্ঞার কথা","root":"حكم","lemma":"حِكْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36769,"position":10,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":36770,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36771,"position":12,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36772,"position":13,"text_uthmani":"لَطِيفًا","transliteration":"laṭīfan","translation_bn":"সূক্ষ্মদর্শী","root":"لطف","lemma":"لَطِيف","grammar_bn":"বিশেষ্য (Noun)"},{"id":36773,"position":14,"text_uthmani":"خَبِيرًا","transliteration":"khabīran","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":36774,"position":15,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur''na mā yut''lā fī buyūtikunna min āyāti l-lahi wal-ḥik''mati inna l-laha kāna laṭīfan khabīran', 'তোমাদের গৃহে আল্লাহর আয়াত ও হিকমত থেকে যা পাঠ করা হয় তার চর্চা কর। আল্লাহ অতি সূক্ষ্ণদর্শী, সর্ববিষয়ে খবর রাখেন।', 'And remember what is recited in your houses of the verses of Allah and wisdom. Indeed, Allah is ever Subtle and Acquainted [with all things].', 'তোমাদের গৃহে আল্লাহর আয়াত ও হিকমত থেকে যা পাঠ করা হয় তার চর্চা কর। আল্লাহ অতি সূক্ষ্ণদর্শী, সর্ববিষয়ে খবর রাখেন।', 'And remember what is recited in your houses of the verses of Allah and wisdom. Indeed, Allah is ever Subtle and Acquainted [with all things].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/033034.mp3', now()),
  (33, 35, '', '[{"id":37572,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37573,"position":2,"text_uthmani":"ٱلْمُسْلِمِينَ","transliteration":"l-mus''limīna","translation_bn":"মুসলমান পুরুষগণ","root":"سلم","lemma":"مُسْلِم","grammar_bn":"শব্দ"},{"id":37574,"position":3,"text_uthmani":"وَٱلْمُسْلِمَـٰتِ","transliteration":"wal-mus''limāti","translation_bn":"ও মুসলমান নারীগণ","root":"سلم","lemma":"مُسْلِمَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37575,"position":4,"text_uthmani":"وَٱلْمُؤْمِنِينَ","transliteration":"wal-mu''minīna","translation_bn":"এবং মু’মিন পুরুষগণ","root":"امن","lemma":"مُؤْمِن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37576,"position":5,"text_uthmani":"وَٱلْمُؤْمِنَـٰتِ","transliteration":"wal-mu''mināti","translation_bn":"ও মুু’মিনা নারীগণ","root":"امن","lemma":"مُّؤْمِنَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37577,"position":6,"text_uthmani":"وَٱلْقَـٰنِتِينَ","transliteration":"wal-qānitīna","translation_bn":"এবং অনুগত পুরুষগণ","root":"قنت","lemma":"قَانِت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37578,"position":7,"text_uthmani":"وَٱلْقَـٰنِتَـٰتِ","transliteration":"wal-qānitāti","translation_bn":"ও অনুগত নারীগণ","root":"قنت","lemma":"قَٰنِتَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37579,"position":8,"text_uthmani":"وَٱلصَّـٰدِقِينَ","transliteration":"wal-ṣādiqīna","translation_bn":"এবং সত্যবাদী পুরুষগণ","root":"صدق","lemma":"صَادِق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37580,"position":9,"text_uthmani":"وَٱلصَّـٰدِقَـٰتِ","transliteration":"wal-ṣādiqāti","translation_bn":"ও সত্যবাদী নারীগণ","root":"صدق","lemma":"صَّٰدِقَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37581,"position":10,"text_uthmani":"وَٱلصَّـٰبِرِينَ","transliteration":"wal-ṣābirīna","translation_bn":"এবং ধৈয্যশীল পুরুষগণ","root":"صبر","lemma":"صَابِر","grammar_bn":"সংযোজক অব্যয় 