  (34, 1, '', '[{"id":841,"position":1,"text_uthmani":"ٱلْحَمْدُ","transliteration":"al-ḥamdu","translation_bn":"সমস্ত প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":842,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":843,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি (এমন সত্ত্বা)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":844,"position":4,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তাঁরই (মালিকানায়)","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":845,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":846,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":847,"position":7,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমন্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":848,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":849,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":850,"position":10,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":851,"position":11,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"এবং জন্যে তাঁরই","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":852,"position":12,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":853,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":854,"position":14,"text_uthmani":"ٱلْـَٔاخِرَةِ ۚ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":856,"position":15,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":857,"position":16,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":858,"position":17,"text_uthmani":"ٱلْخَبِيرُ","transliteration":"l-khabīru","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"শব্দ"},{"id":859,"position":18,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'al-ḥamdu lillahi alladhī lahu mā fī l-samāwāti wamā fī l-arḍi walahu l-ḥamdu fī l-ākhirati wahuwa l-ḥakīmu l-khabīru', 'যাবতীয় প্রশংসা আল্লাহর যিনি আকাশ ও পৃথিবীতে যা আছে সব কিছুর মালিক। আখিরাতেও প্রশংসা তাঁরই; তিনি মহা প্রজ্ঞাশীল, সকল বিষয়ে অবহিত।', '[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Acquainted.', 'যাবতীয় প্রশংসা আল্লাহর যিনি আকাশ ও পৃথিবীতে যা আছে সব কিছুর মালিক। আখিরাতেও প্রশংসা তাঁরই; তিনি মহা প্রজ্ঞাশীল, সকল বিষয়ে অবহিত।', '[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Acquainted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034001.mp3', now()),
  (34, 2, '', '[{"id":1905,"position":1,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1906,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1907,"position":3,"text_uthmani":"يَلِجُ","transliteration":"yaliju","translation_bn":"প্রবেশ করে","root":"ولج","lemma":"يَلِجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1908,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1909,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":1910,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1911,"position":7,"text_uthmani":"يَخْرُجُ","transliteration":"yakhruju","translation_bn":"বের হয়","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1912,"position":8,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"থেকে তা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1913,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1914,"position":10,"text_uthmani":"يَنزِلُ","transliteration":"yanzilu","translation_bn":"নামে (অবতীর্ণ হয়)","root":"نزل","lemma":"نَزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1915,"position":11,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1916,"position":12,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":1917,"position":13,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1918,"position":14,"text_uthmani":"يَعْرُجُ","transliteration":"yaʿruju","translation_bn":"উত্থিত হয়","root":"عرج","lemma":"يَعْرُجُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1919,"position":15,"text_uthmani":"فِيهَا ۚ","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1921,"position":16,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1922,"position":17,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":1923,"position":18,"text_uthmani":"ٱلْغَفُورُ","transliteration":"l-ghafūru","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"শব্দ"},{"id":1924,"position":19,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'yaʿlamu mā yaliju fī l-arḍi wamā yakhruju min''hā wamā yanzilu mina l-samāi wamā yaʿruju fīhā wahuwa l-raḥīmu l-ghafūru', 'ভূমিতে যা প্রবেশ করে আর তাত্থেকে যা বের হয়, আর আকাশ হতে যা অবতীর্ণ হয় আর তাতে যা উত্থিত হয় তা তিনি জানেন। তিনি পরম দয়ালু, পরম ক্ষমাশীল।', 'He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving.', 'ভূমিতে যা প্রবেশ করে আর তাত্থেকে যা বের হয়, আর আকাশ হতে যা অবতীর্ণ হয় আর তাতে যা উত্থিত হয় তা তিনি জানেন। তিনি পরম দয়ালু, পরম ক্ষমাশীল।', 'He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034002.mp3', now()),
  (34, 3, '', '[{"id":3097,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3098,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3099,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3100,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"(কেন) না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3101,"position":5,"text_uthmani":"تَأْتِينَا","transliteration":"tatīnā","translation_bn":"উপর আসছে আমাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3102,"position":6,"text_uthmani":"ٱلسَّاعَةُ ۖ","transliteration":"l-sāʿatu","translation_bn":"ক্বিয়ামাত\"","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":3104,"position":7,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3105,"position":8,"text_uthmani":"بَلَىٰ","transliteration":"balā","translation_bn":"\"কেন না নিশ্চয়ই","root":"—","lemma":"بَلَىٰ\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":3106,"position":9,"text_uthmani":"وَرَبِّى","transliteration":"warabbī","translation_bn":"শপথ আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3107,"position":10,"text_uthmani":"لَتَأْتِيَنَّكُمْ","transliteration":"latatiyannakum","translation_bn":"অবশ্যই উপর আসবেই তোমাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3108,"position":11,"text_uthmani":"عَـٰلِمِ","transliteration":"ʿālimi","translation_bn":"(আমার রব)জ্ঞানী","root":"علم","lemma":"عَٰلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3109,"position":12,"text_uthmani":"ٱلْغَيْبِ ۖ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের (ব্যাপারে)\"","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":3111,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3112,"position":14,"text_uthmani":"يَعْزُبُ","transliteration":"yaʿzubu","translation_bn":"লুকায়িত আছে","root":"عزب","lemma":"يَعْزُبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3113,"position":15,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"থেকে তাঁর","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3114,"position":16,"text_uthmani":"مِثْقَالُ","transliteration":"mith''qālu","translation_bn":"(কিছু) পরিমাণও","root":"ثقل","lemma":"مِثْقَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":3115,"position":17,"text_uthmani":"ذَرَّةٍۢ","transliteration":"dharratin","translation_bn":"কোনো অণুর","root":"ذرر","lemma":"ذَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3116,"position":18,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3117,"position":19,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3118,"position":20,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3119,"position":21,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3120,"position":22,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":3121,"position":23,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3122,"position":24,"text_uthmani":"أَصْغَرُ","transliteration":"aṣgharu","translation_bn":"ক্ষুদ্রতর","root":"صغر","lemma":"أَصْغَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":3123,"position":25,"text_uthmani":"مِن","transliteration":"min","translation_bn":"চেয়েও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3124,"position":26,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"সেটার","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3125,"position":27,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3126,"position":28,"text_uthmani":"أَكْبَرُ","transliteration":"akbaru","translation_bn":"বৃহত্তর","root":"كبر","lemma":"أَكْبَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":3127,"position":29,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3128,"position":30,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3129,"position":31,"text_uthmani":"كِتَـٰبٍۢ","transliteration":"kitābin","translation_bn":"(লিখিত) একটি কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3130,"position":32,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":3131,"position":33,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna kafarū lā tatīnā l-sāʿatu qul balā warabbī latatiyannakum ʿālimi l-ghaybi lā yaʿzubu ʿanhu mith''qālu dharratin fī l-samāwāti walā fī l-arḍi walā aṣgharu min dhālika walā akbaru illā fī kitābin mubīnin', 'কাফিরগণ বলে- ক্বিয়ামত আমাদের নিকট আসবে না। বল, না, আমার প্রতিপালকের শপথ! তোমাদের নিকট তা অবশ্য অবশ্যই আসবে। তিনি যাবতীয় অদৃশ্যের জ্ঞানী। তাঁর থেকে লুক্কায়িত নেই আকাশ ও পৃথিবীতে ক্ষুদ্রাতিক্ষুদ্র অনুকণা, না তার থেকে ছোট আর না তার থেকে বড় (কোনটাই নেই লুক্কায়িত)। সবই আছে (লাওহে মাহফুয নামক) এক সুস্পষ্ট কিতাবে।', 'But those who disbelieve say, "The Hour will not come to us." Say, "Yes, by my Lord, it will surely come to you. [Allah is] the Knower of the unseen." Not absent from Him is an atom''s weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -', 'কাফিরগণ বলে- ক্বিয়ামত আমাদের নিকট আসবে না। বল, না, আমার প্রতিপালকের শপথ! তোমাদের নিকট তা অবশ্য অবশ্যই আসবে। তিনি যাবতীয় অদৃশ্যের জ্ঞানী। তাঁর থেকে লুক্কায়িত নেই আকাশ ও পৃথিবীতে ক্ষুদ্রাতিক্ষুদ্র অনুকণা, না তার থেকে ছোট আর না তার থেকে বড় (কোনটাই নেই লুক্কায়িত)। সবই আছে (লাওহে মাহফুয নামক) এক সুস্পষ্ট কিতাবে।', 'But those who disbelieve say, "The Hour will not come to us." Say, "Yes, by my Lord, it will surely come to you. [Allah is] the Knower of the unseen." Not absent from Him is an atom''s weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034003.mp3', now()),
  (34, 4, '', '[{"id":4495,"position":1,"text_uthmani":"لِّيَجْزِىَ","transliteration":"liyajziya","translation_bn":"(ক্বিয়ামাত এজন্যে) যেন তিনি পুরস্কার দেন","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"শব্দ"},{"id":4496,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4497,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4498,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4499,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ ۚ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":4501,"position":6,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":4502,"position":7,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"জন্যে তাদের (রয়েছে)","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":4503,"position":8,"text_uthmani":"مَّغْفِرَةٌۭ","transliteration":"maghfiratun","translation_bn":"ক্ষমা","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4504,"position":9,"text_uthmani":"وَرِزْقٌۭ","transliteration":"wariz''qun","translation_bn":"ও জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4505,"position":10,"text_uthmani":"كَرِيمٌۭ","transliteration":"karīmun","translation_bn":"সম্মানজনক","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":4506,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'liyajziya alladhīna āmanū waʿamilū l-ṣāliḥāti ulāika lahum maghfiratun wariz''qun karīmun', 'যাতে তিনি প্রতিদান দিতে পারেন তাদেরকে যারা ঈমান আনে ও সৎকাজ করে, এদেরই জন্য আছে ক্ষমা ও সম্মানজনক রিযক।', 'That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.', 'যাতে তিনি প্রতিদান দিতে পারেন তাদেরকে যারা ঈমান আনে ও সৎকাজ করে, এদেরই জন্য আছে ক্ষমা ও সম্মানজনক রিযক।', 'That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034004.mp3', now()),
  (34, 5, '', '[{"id":5753,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5754,"position":2,"text_uthmani":"سَعَوْ","transliteration":"saʿaw","translation_bn":"চেষ্টা করে","root":"سعي","lemma":"سَعَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5755,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"ক্ষেত্রে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5756,"position":4,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"আয়াতগুলোর আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":5757,"position":5,"text_uthmani":"مُعَـٰجِزِينَ","transliteration":"muʿājizīna","translation_bn":"ব্যর্থ প্রমাণ করতে","root":"عجز","lemma":"مُعَٰجِزِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":5758,"position":6,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব (লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5759,"position":7,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের(রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5760,"position":8,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5761,"position":9,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"ধরণের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5762,"position":10,"text_uthmani":"رِّجْزٍ","transliteration":"rij''zin","translation_bn":"ভয়ংকর","root":"رجز","lemma":"رِجْز","grammar_bn":"বিশেষ্য (Noun)"},{"id":5763,"position":11,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"নির্মম","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":5764,"position":12,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna saʿaw fī āyātinā muʿājizīna ulāika lahum ʿadhābun min rij''zin alīmun', 'যারা আমার আয়াতকে ব্যর্থ করার চেষ্টা চালায় তাদেরই জন্য রয়েছে যন্ত্রণাদায়ক ভয়াবহ শাস্তি।', 'But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature.', 'যারা আমার আয়াতকে ব্যর্থ করার চেষ্টা চালায় তাদেরই জন্য রয়েছে যন্ত্রণাদায়ক ভয়াবহ শাস্তি।', 'But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034005.mp3', now()),
  (34, 6, '', '[{"id":7037,"position":1,"text_uthmani":"وَيَرَى","transliteration":"wayarā","translation_bn":"এবং জানে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7038,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারা) যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7039,"position":3,"text_uthmani":"أُوتُوا۟","transliteration":"ūtū","translation_bn":"দেয়া হয়েছে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":7040,"position":4,"text_uthmani":"ٱلْعِلْمَ","transliteration":"l-ʿil''ma","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"শব্দ"},{"id":7041,"position":5,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7042,"position":6,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7043,"position":7,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"প্রতি তোমার","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7044,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7045,"position":9,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7046,"position":10,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":7047,"position":11,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":7048,"position":12,"text_uthmani":"وَيَهْدِىٓ","transliteration":"wayahdī","translation_bn":"এবং তা পথ দেখায়","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7049,"position":13,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7050,"position":14,"text_uthmani":"صِرَٰطِ","transliteration":"ṣirāṭi","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":7051,"position":15,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"পরাক্রমশালী (রবের)","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":7052,"position":16,"text_uthmani":"ٱلْحَمِيدِ","transliteration":"l-ḥamīdi","translation_bn":"(যিনি) প্রশংসিত","root":"حمد","lemma":"حَمِيد","grammar_bn":"শব্দ"},{"id":7053,"position":17,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wayarā alladhīna ūtū l-ʿil''ma alladhī unzila ilayka min rabbika huwa l-ḥaqa wayahdī ilā ṣirāṭi l-ʿazīzi l-ḥamīdi', 'যাদেরকে জ্ঞান দেয়া হয়েছে তারা তোমার কাছে তোমার প্রতিপালকের পক্ষ থেকে যা অবতীর্ণ হয়েছে তাকে সত্য বলে জানে এবং (তারা আরো জানে যে) তা মহাপরাক্রমশালী ও প্রশংসিত (আল্লাহ)’র পথে পরিচালিত করে।', 'And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy.', 'যাদেরকে জ্ঞান দেয়া হয়েছে তারা তোমার কাছে তোমার প্রতিপালকের পক্ষ থেকে যা অবতীর্ণ হয়েছে তাকে সত্য বলে জানে এবং (তারা আরো জানে যে) তা মহাপরাক্রমশালী ও প্রশংসিত (আল্লাহ)’র পথে পরিচালিত করে।', 'And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034006.mp3', now()),
  (34, 7, '', '[{"id":8337,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8338,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারা) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8339,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8340,"position":4,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":8341,"position":5,"text_uthmani":"نَدُلُّكُمْ","transliteration":"nadullukum","translation_bn":"আমরা সন্ধান দিবো তোমাদেরকে","root":"دلل","lemma":"دَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8342,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8343,"position":7,"text_uthmani":"رَجُلٍۢ","transliteration":"rajulin","translation_bn":"এক ব্যক্তির","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":8344,"position":8,"text_uthmani":"يُنَبِّئُكُمْ","transliteration":"yunabbi-ukum","translation_bn":"যে জানিয়ে দিবে তোমাদেরকে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8345,"position":9,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":8346,"position":10,"text_uthmani":"مُزِّقْتُمْ","transliteration":"muzziq''tum","translation_bn":"ছিন্ন-বিচ্ছিন্ন করা হবে তোমাদেরকে","root":"مزق","lemma":"مُزِّقْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8347,"position":11,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"সম্পূর্ণ","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8348,"position":12,"text_uthmani":"مُمَزَّقٍ","transliteration":"mumazzaqin","translation_bn":"খুব ছিন্ন-বিচ্ছিন্ন","root":"مزق","lemma":"مُمَزَّق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8349,"position":13,"text_uthmani":"إِنَّكُمْ","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমরা(হবে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8350,"position":14,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8351,"position":15,"text_uthmani":"خَلْقٍۢ","transliteration":"khalqin","translation_bn":"সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8352,"position":16,"text_uthmani":"جَدِيدٍ","transliteration":"jadīdin","translation_bn":"নতুন (অর্থাৎ উত্থিত হবে?)","root":"جدد","lemma":"جَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":8353,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla alladhīna kafarū hal nadullukum ʿalā rajulin yunabbi-ukum idhā muzziq''tum kulla mumazzaqin innakum lafī khalqin jadīdin', 'কাফিরগণ বলে- তোমাদেরকে কি আমরা এমন একজন লোকের সন্ধান দেব যে তোমাদেরকে খবর দেয় যে, তোমরা ছিন্ন ভিন্ন হয়ে গেলেও তোমাদেরকে নতুনভাবে সৃষ্টি করা হবে?', 'But those who disbelieve say, "Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?', 'কাফিরগণ বলে- তোমাদেরকে কি আমরা এমন একজন লোকের সন্ধান দেব যে তোমাদেরকে খবর দেয় যে, তোমরা ছিন্ন ভিন্ন হয়ে গেলেও তোমাদেরকে নতুনভাবে সৃষ্টি করা হবে?', 'But those who disbelieve say, "Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034007.mp3', now()),
  (34, 8, '', '[{"id":9510,"position":1,"text_uthmani":"أَفْتَرَىٰ","transliteration":"aftarā","translation_bn":"কি রচনা করেছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9511,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9512,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9513,"position":4,"text_uthmani":"كَذِبًا","transliteration":"kadhiban","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9514,"position":5,"text_uthmani":"أَم","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9515,"position":6,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সাথে তার (আছে)","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":9516,"position":7,"text_uthmani":"جِنَّةٌۢ ۗ","transliteration":"jinnatun","translation_bn":"জিন\"","root":"جنن","lemma":"جِنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9518,"position":8,"text_uthmani":"بَلِ","transliteration":"bali","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":9519,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9520,"position":10,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":9521,"position":11,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9522,"position":12,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"প্রতি আখেরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":9523,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9524,"position":14,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":9525,"position":15,"text_uthmani":"وَٱلضَّلَـٰلِ","transliteration":"wal-ḍalāli","translation_bn":"এবং বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9526,"position":16,"text_uthmani":"ٱلْبَعِيدِ","transliteration":"l-baʿīdi","translation_bn":"সুদূর","root":"بعد","lemma":"بَعِيد","grammar_bn":"শব্দ"},{"id":9527,"position":17,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'aftarā ʿalā l-lahi kadhiban am bihi jinnatun bali alladhīna lā yu''minūna bil-ākhirati fī l-ʿadhābi wal-ḍalāli l-baʿīdi', 'সে আল্লাহ সম্পর্কে মিথ্যে বলে, না হয় সে পাগল। বস্তুতঃ যারা আখিরাতে বিশ্বাস করে না তারাই শাস্তি এবং সুদূর গুমরাহীতে পড়ে আছে।', 'Has he invented about Allah a lie or is there in him madness?" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error.', 'সে আল্লাহ সম্পর্কে মিথ্যে বলে, না হয় সে পাগল। বস্তুতঃ যারা আখিরাতে বিশ্বাস করে না তারাই শাস্তি এবং সুদূর গুমরাহীতে পড়ে আছে।', 'Has he invented about Allah a lie or is there in him madness?" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034008.mp3', now()),
  (34, 9, '', '[{"id":10681,"position":1,"text_uthmani":"أَفَلَمْ","transliteration":"afalam","translation_bn":"কি তবে না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":10682,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা দেখে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":10683,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10684,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"(তার) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10685,"position":5,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":10686,"position":6,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"হাতের (সামনে রয়েছে) তাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10687,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10688,"position":8,"text_uthmani":"خَلْفَهُم","transliteration":"khalfahum","translation_bn":"পিছনে তাদের","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":10689,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10690,"position":10,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":10691,"position":11,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10693,"position":12,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":10694,"position":13,"text_uthmani":"نَّشَأْ","transliteration":"nasha","translation_bn":"আমরা চাই","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10695,"position":14,"text_uthmani":"نَخْسِفْ","transliteration":"nakhsif","translation_bn":"আমরা ধ্বসিয়ে দিবো","root":"خسف","lemma":"خَسَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10696,"position":15,"text_uthmani":"بِهِمُ","transliteration":"bihimu","translation_bn":"সহ তাদের","root":"—","lemma":"بِهِمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":10697,"position":16,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":10698,"position":17,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10699,"position":18,"text_uthmani":"نُسْقِطْ","transliteration":"nus''qiṭ","translation_bn":"আমরা পতিত করবো","root":"سقط","lemma":"تُسْقِطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10700,"position":19,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10701,"position":20,"text_uthmani":"كِسَفًۭا","transliteration":"kisafan","translation_bn":"(কিছু) খণ্ড","root":"كسف","lemma":"كِسَف","grammar_bn":"বিশেষ্য (Noun)"},{"id":10702,"position":21,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10703,"position":22,"text_uthmani":"ٱلسَّمَآءِ ۚ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":10705,"position":23,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10706,"position":24,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10707,"position":25,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10708,"position":26,"text_uthmani":"لَـَٔايَةًۭ","transliteration":"laāyatan","translation_bn":"অবশ্যই নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10709,"position":27,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":10710,"position":28,"text_uthmani":"عَبْدٍۢ","transliteration":"ʿabdin","translation_bn":"দাসের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10711,"position":29,"text_uthmani":"مُّنِيبٍۢ","transliteration":"munībin","translation_bn":"যে (আল্লাহ) অভিমুখী","root":"نوب","lemma":"مُّنِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":10712,"position":30,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'afalam yaraw ilā mā bayna aydīhim wamā khalfahum mina l-samāi wal-arḍi in nasha nakhsif bihimu l-arḍa aw nus''qiṭ ʿalayhim kisafan mina l-samāi inna fī dhālika laāyatan likulli ʿabdin munībin', 'তারা কি আকাশ ও পৃথিবীতে তাদের সামনে ও পেছনে লক্ষ্য করে না? আমি ইচ্ছে করলে তাদেরকেসহ ভূমি ধ্বসিয়ে দেব অথবা আকাশের এক টুকরো তাদের উপর ফেলে দেব। প্রতিটি আল্লাহ অভিমুখী বান্দাহর জন্য এতে নিদর্শন রয়েছে।', 'Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allah].', 'তারা কি আকাশ ও পৃথিবীতে তাদের সামনে ও পেছনে লক্ষ্য করে না? আমি ইচ্ছে করলে তাদেরকেসহ ভূমি ধ্বসিয়ে দেব অথবা আকাশের এক টুকরো তাদের উপর ফেলে দেব। প্রতিটি আল্লাহ অভিমুখী বান্দাহর জন্য এতে নিদর্শন রয়েছে।', 'Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034009.mp3', now()),
  (34, 10, '', '[{"id":11951,"position":1,"text_uthmani":"۞ وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11952,"position":2,"text_uthmani":"ءَاتَيْنَا","transliteration":"ātaynā","translation_bn":"আমরা দিয়েছি","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":11953,"position":3,"text_uthmani":"دَاوُۥدَ","transliteration":"dāwūda","translation_bn":"দাউদকে","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11954,"position":4,"text_uthmani":"مِنَّا","transliteration":"minnā","translation_bn":"আমাদের পক্ষ থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11955,"position":5,"text_uthmani":"فَضْلًۭا ۖ","transliteration":"faḍlan","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11957,"position":6,"text_uthmani":"يَـٰجِبَالُ","transliteration":"yājibālu","translation_bn":"\"(এবং বলেছিলাম) হে পর্বতমালা","root":"جبل","lemma":"جَبَل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":11958,"position":7,"text_uthmani":"أَوِّبِى","transliteration":"awwibī","translation_bn":"পবিত্রতা ঘোষণা করো","root":"اوب","lemma":"أَوِّبِ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11959,"position":8,"text_uthmani":"مَعَهُۥ","transliteration":"maʿahu","translation_bn":"তার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":11960,"position":9,"text_uthmani":"وَٱلطَّيْرَ ۖ","transliteration":"wal-ṭayra","translation_bn":"এবং পাখীদেরকেও (হুকুম দিয়েছিলাম)\"","root":"طير","lemma":"طَيْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11962,"position":10,"text_uthmani":"وَأَلَنَّا","transliteration":"wa-alannā","translation_bn":"এবং আমরা নরম করে দেই","root":"لين","lemma":"أَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11963,"position":11,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":11964,"position":12,"text_uthmani":"ٱلْحَدِيدَ","transliteration":"l-ḥadīda","translation_bn":"লোহাকে","root":"حدد","lemma":"حَدِيد","grammar_bn":"শব্দ"},{"id":11965,"position":13,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ātaynā dāwūda minnā faḍlan yājibālu awwibī maʿahu wal-ṭayra wa-alannā lahu l-ḥadīda', 'আমি আমার পক্ষ থেকে দাঊদের প্রতি অনুগ্রহ করেছিলাম। (আমি আদেশ করেছিলাম) হে পর্বতমালা! তোমরা দাঊদের সঙ্গে আমার পবিত্রতা ঘোষণা কর আর পাখীদেরকেও (এ আদেশ করেছিলাম)। আমি লোহাকে তার জন্য নরম করেছিলাম।', 'And We certainly gave David from Us bounty. [We said], "O mountains, repeat [Our] praises with him, and the birds [as well]." And We made pliable for him iron,', 'আমি আমার পক্ষ থেকে দাঊদের প্রতি অনুগ্রহ করেছিলাম। (আমি আদেশ করেছিলাম) হে পর্বতমালা! তোমরা দাঊদের সঙ্গে আমার পবিত্রতা ঘোষণা কর আর পাখীদেরকেও (এ আদেশ করেছিলাম)। আমি লোহাকে তার জন্য নরম করেছিলাম।', 'And We certainly gave David from Us bounty. [We said], "O mountains, repeat [Our] praises with him, and the birds [as well]." And We made pliable for him iron,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034010.mp3', now()),
  (34, 11, '', '[{"id":13247,"position":1,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"(এবং নির্দেশ দিয়েছিলাম) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":13248,"position":2,"text_uthmani":"ٱعْمَلْ","transliteration":"iʿ''mal","translation_bn":"তুমি তৈরি করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13249,"position":3,"text_uthmani":"سَـٰبِغَـٰتٍۢ","transliteration":"sābighātin","translation_bn":"(নিখুঁত) বর্মসমূহ","root":"سبغ","lemma":"سَٰبِغَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":13250,"position":4,"text_uthmani":"وَقَدِّرْ","transliteration":"waqaddir","translation_bn":"ও পরিমাণ রক্ষা করো","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13251,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13252,"position":6,"text_uthmani":"ٱلسَّرْدِ ۖ","transliteration":"l-sardi","translation_bn":"কড়াগুলোর","root":"سرد","lemma":"سَّرْد","grammar_bn":"শব্দ"},{"id":13254,"position":7,"text_uthmani":"وَٱعْمَلُوا۟","transliteration":"wa-iʿ''malū","translation_bn":"এবং তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13255,"position":8,"text_uthmani":"صَـٰلِحًا ۖ","transliteration":"ṣāliḥan","translation_bn":"সৎ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":13257,"position":9,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13258,"position":10,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13259,"position":11,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা করছো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13260,"position":12,"text_uthmani":"بَصِيرٌۭ","transliteration":"baṣīrun","translation_bn":"দৃষ্টিমান","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":13261,"position":13,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'ani iʿ''mal sābighātin waqaddir fī l-sardi wa-iʿ''malū ṣāliḥan innī bimā taʿmalūna baṣīrun', 'যাতে তুমি পূর্ণ মাপের বর্ম তৈরি করতে পার, কড়াসমূহ সঠিকভাবে সংযুক্ত কর আর তোমরা সৎকর্ম কর। তোমরা যা কর আমি তার প্রত্যক্ষদর্শী।', '[Commanding him], "Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing."', 'যাতে তুমি পূর্ণ মাপের বর্ম তৈরি করতে পার, কড়াসমূহ সঠিকভাবে সংযুক্ত কর আর তোমরা সৎকর্ম কর। তোমরা যা কর আমি তার প্রত্যক্ষদর্শী।', '[Commanding him], "Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034011.mp3', now()),
  (34, 12, '', '[{"id":14525,"position":1,"text_uthmani":"وَلِسُلَيْمَـٰنَ","transliteration":"walisulaymāna","translation_bn":"এবং জন্যে সোলায়মানের (অধীন করে দেই)","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14526,"position":2,"text_uthmani":"ٱلرِّيحَ","transliteration":"l-rīḥa","translation_bn":"বাতাসকে","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":14527,"position":3,"text_uthmani":"غُدُوُّهَا","transliteration":"ghuduwwuhā","translation_bn":"সকালের বেড়ানো তার","root":"غدو","lemma":"غُدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14528,"position":4,"text_uthmani":"شَهْرٌۭ","transliteration":"shahrun","translation_bn":"এক মাসের","root":"شهر","lemma":"شَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14529,"position":5,"text_uthmani":"وَرَوَاحُهَا","transliteration":"warawāḥuhā","translation_bn":"এবং সন্ধ্যার বেড়ানো তার","root":"روح","lemma":"رَوَاح","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14530,"position":6,"text_uthmani":"شَهْرٌۭ ۖ","transliteration":"shahrun","translation_bn":"এক মাসের (অর্থাৎ সে এক মাসের পথ এক সকাল বা এক সন্ধায় অতিক্রম করতো","root":"شهر","lemma":"شَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14532,"position":7,"text_uthmani":"وَأَسَلْنَا","transliteration":"wa-asalnā","translation_bn":"এবং আমরা প্রবাহিত করেছি","root":"سيل","lemma":"أَسَلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14533,"position":8,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":14534,"position":9,"text_uthmani":"عَيْنَ","transliteration":"ʿayna","translation_bn":"ঝর্ণা","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":14535,"position":10,"text_uthmani":"ٱلْقِطْرِ ۖ","transliteration":"l-qiṭ''ri","translation_bn":"গলানো তামার","root":"قطر","lemma":"قِطْر","grammar_bn":"শব্দ"},{"id":14537,"position":11,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"এবং কিছু","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14538,"position":12,"text_uthmani":"ٱلْجِنِّ","transliteration":"l-jini","translation_bn":"জিনদের","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":14539,"position":13,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যারা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14540,"position":14,"text_uthmani":"يَعْمَلُ","transliteration":"yaʿmalu","translation_bn":"কাজ করতো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14541,"position":15,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":14542,"position":16,"text_uthmani":"يَدَيْهِ","transliteration":"yadayhi","translation_bn":"হাতের (সামনে) তার","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":14543,"position":17,"text_uthmani":"بِإِذْنِ","transliteration":"bi-idh''ni","translation_bn":"ক্রমে অনুমতি","root":"اذن","lemma":"إِذْن","grammar_bn":"অব্যয় (Preposition)"},{"id":14544,"position":18,"text_uthmani":"رَبِّهِۦ ۖ","transliteration":"rabbihi","translation_bn":"তাঁর রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14546,"position":19,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14547,"position":20,"text_uthmani":"يَزِغْ","transliteration":"yazigh","translation_bn":"অমান্য করতো","root":"زيغ","lemma":"زَاغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14548,"position":21,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14549,"position":22,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14550,"position":23,"text_uthmani":"أَمْرِنَا","transliteration":"amrinā","translation_bn":"নির্দেশের আমাদের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14551,"position":24,"text_uthmani":"نُذِقْهُ","transliteration":"nudhiq''hu","translation_bn":"আমরা আস্বাদন করাতাম তাকে","root":"ذوق","lemma":"أَذَاقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14552,"position":25,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14553,"position":26,"text_uthmani":"عَذَابِ","transliteration":"ʿadhābi","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":14554,"position":27,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"জ্বলন্ত আগুনের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":14555,"position":28,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'walisulaymāna l-rīḥa ghuduwwuhā shahrun warawāḥuhā shahrun wa-asalnā lahu ʿayna l-qiṭ''ri wamina l-jini man yaʿmalu bayna yadayhi bi-idh''ni rabbihi waman yazigh min''hum ʿan amrinā nudhiq''hu min ʿadhābi l-saʿīri', 'আর সুলাইমানের জন্য (আমি তার অধীন করে দিয়েছিলাম) বাতাসকে। তার সকালের অতিক্রমণ ছিল এক মাসের পথ আর সন্ধ্যার অতিক্রমণ ছিল এক মাসের পথ। আমি তার জন্য গলিত তামার ঝরণা প্রবাহিত করেছিলাম। কতক জ্বিন তার সম্মুখে কাজ করত তার পালনকর্তার অনুমতিক্রমে। তাদের যে কেউ আমার নির্দেশ অমান্য করে, তাকে আমি জ্বলন্ত আগুনের শাস্তি আস্বাদন করাব।', 'And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze.', 'আর সুলাইমানের জন্য (আমি তার অধীন করে দিয়েছিলাম) বাতাসকে। তার সকালের অতিক্রমণ ছিল এক মাসের পথ আর সন্ধ্যার অতিক্রমণ ছিল এক মাসের পথ। আমি তার জন্য গলিত তামার ঝরণা প্রবাহিত করেছিলাম। কতক জ্বিন তার সম্মুখে কাজ করত তার পালনকর্তার অনুমতিক্রমে। তাদের যে কেউ আমার নির্দেশ অমান্য করে, তাকে আমি জ্বলন্ত আগুনের শাস্তি আস্বাদন করাব।', 'And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034012.mp3', now()),
  (34, 13, '', '[{"id":15633,"position":1,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা তৈরি করতো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15634,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":15635,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":15636,"position":4,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"সে ইচ্ছে করতো","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15637,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"যেমন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15638,"position":6,"text_uthmani":"مَّحَـٰرِيبَ","transliteration":"maḥārība","translation_bn":"প্রাসাদসমূহ","root":"حرب","lemma":"مَّحَٰرِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":15639,"position":7,"text_uthmani":"وَتَمَـٰثِيلَ","transliteration":"watamāthīla","translation_bn":"ও (প্রাণহীন বস্তুর)ভাস্কর্য","root":"مثل","lemma":"تَّمَاثِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15640,"position":8,"text_uthmani":"وَجِفَانٍۢ","transliteration":"wajifānin","translation_bn":"ও বড় পাত্রসমূহ","root":"جفن","lemma":"جِفَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15641,"position":9,"text_uthmani":"كَٱلْجَوَابِ","transliteration":"kal-jawābi","translation_bn":"হাউজসদৃশ","root":"جبي","lemma":"جَوَاب2","grammar_bn":"অব্যয় (Preposition)"},{"id":15642,"position":10,"text_uthmani":"وَقُدُورٍۢ","transliteration":"waqudūrin","translation_bn":"এবং বড় ডেগসমূহ","root":"قدر","lemma":"قُدُور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15643,"position":11,"text_uthmani":"رَّاسِيَـٰتٍ ۚ","transliteration":"rāsiyātin","translation_bn":"দৃঢ়ভাবে প্রতিষ্ঠিত","root":"رسو","lemma":"رَوَٰسِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":15645,"position":12,"text_uthmani":"ٱعْمَلُوٓا۟","transliteration":"iʿ''malū","translation_bn":"\"(আরও বলেছিলাম) তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15646,"position":13,"text_uthmani":"ءَالَ","transliteration":"āla","translation_bn":"(হে)বংশধররা","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":15647,"position":14,"text_uthmani":"دَاوُۥدَ","transliteration":"dāwūda","translation_bn":"দাউদের","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15648,"position":15,"text_uthmani":"شُكْرًۭا ۚ","transliteration":"shuk''ran","translation_bn":"কৃতজ্ঞতা সহকারে\"","root":"شكر","lemma":"شُكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":15650,"position":16,"text_uthmani":"وَقَلِيلٌۭ","transliteration":"waqalīlun","translation_bn":"এবং কমই","root":"قلل","lemma":"قَلِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15651,"position":17,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15652,"position":18,"text_uthmani":"عِبَادِىَ","transliteration":"ʿibādiya","translation_bn":"আমার দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":15653,"position":19,"text_uthmani":"ٱلشَّكُورُ","transliteration":"l-shakūru","translation_bn":"কৃতজ্ঞ","root":"شكر","lemma":"شَكُور","grammar_bn":"শব্দ"},{"id":15654,"position":20,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'yaʿmalūna lahu mā yashāu min maḥārība watamāthīla wajifānin kal-jawābi waqudūrin rāsiyātin iʿ''malū āla dāwūda shuk''ran waqalīlun min ʿibādiya l-shakūru', 'তারা সুলাইমানের ইচ্ছে অনুযায়ী তার জন্য প্রাসাদ, ভাস্কর্য, হাউযের ন্যায় বৃহদাকার পাত্র এবং চুল্লির উপর স্থাপিত বিশালাকায় ডেগ নির্মাণ করত। (আমি বলেছিলাম) হে দাঊদের সন্তানগণ! তোমরা কৃতজ্ঞচিত্তে কাজ করে যাও। আমার বান্দাদের অল্পই কৃতজ্ঞ।', 'They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], "Work, O family of David, in gratitude." And few of My servants are grateful.', 'তারা সুলাইমানের ইচ্ছে অনুযায়ী তার জন্য প্রাসাদ, ভাস্কর্য, হাউযের ন্যায় বৃহদাকার পাত্র এবং চুল্লির উপর স্থাপিত বিশালাকায় ডেগ নির্মাণ করত। (আমি বলেছিলাম) হে দাঊদের সন্তানগণ! তোমরা কৃতজ্ঞচিত্তে কাজ করে যাও। আমার বান্দাদের অল্পই কৃতজ্ঞ।', 'They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], "Work, O family of David, in gratitude." And few of My servants are grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034013.mp3', now()),
  (34, 14, '', '[{"id":16674,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":16675,"position":2,"text_uthmani":"قَضَيْنَا","transliteration":"qaḍaynā","translation_bn":"সিদ্ধান্ত করলাম আমরা","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":16676,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"উপর তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16677,"position":4,"text_uthmani":"ٱلْمَوْتَ","transliteration":"l-mawta","translation_bn":"মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":16678,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":16679,"position":6,"text_uthmani":"دَلَّهُمْ","transliteration":"dallahum","translation_bn":"জানালো তাদের","root":"دلل","lemma":"دَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16680,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16681,"position":8,"text_uthmani":"مَوْتِهِۦٓ","transliteration":"mawtihi","translation_bn":"মৃত্যু তার","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":16682,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":16683,"position":10,"text_uthmani":"دَآبَّةُ","transliteration":"dābbatu","translation_bn":"ঘুণপোকা","root":"دبب","lemma":"دَا^بَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16684,"position":11,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"মাটির","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":16685,"position":12,"text_uthmani":"تَأْكُلُ","transliteration":"takulu","translation_bn":"(যা) খাচ্ছিলো","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16686,"position":13,"text_uthmani":"مِنسَأَتَهُۥ ۖ","transliteration":"minsa-atahu","translation_bn":"লাঠিকে তার","root":"نسا","lemma":"مِنسَأَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":16688,"position":14,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":16689,"position":15,"text_uthmani":"خَرَّ","transliteration":"kharra","translation_bn":"সে পড়ে গেলো","root":"خرر","lemma":"خَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16690,"position":16,"text_uthmani":"تَبَيَّنَتِ","transliteration":"tabayyanati","translation_bn":"পরিষ্কারভাবে জানতে পারলো","root":"بين","lemma":"تَبَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16691,"position":17,"text_uthmani":"ٱلْجِنُّ","transliteration":"l-jinu","translation_bn":"জিনরা","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":16692,"position":18,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":16693,"position":19,"text_uthmani":"لَّوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":16694,"position":20,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16695,"position":21,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানতো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16696,"position":22,"text_uthmani":"ٱلْغَيْبَ","transliteration":"l-ghayba","translation_bn":"অদৃশ্য বিষয়ে","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":16697,"position":23,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":16698,"position":24,"text_uthmani":"لَبِثُوا۟","transliteration":"labithū","translation_bn":"তারা অবস্থান করতো (বাঁধা থাকতো)","root":"لبث","lemma":"لَبِثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16699,"position":25,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16700,"position":26,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":16701,"position":27,"text_uthmani":"ٱلْمُهِينِ","transliteration":"l-muhīni","translation_bn":"অপমানকর","root":"هون","lemma":"مُّهِين","grammar_bn":"শব্দ"},{"id":16702,"position":28,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'falammā qaḍaynā ʿalayhi l-mawta mā dallahum ʿalā mawtihi illā dābbatu l-arḍi takulu minsa-atahu falammā kharra tabayyanati l-jinu an law kānū yaʿlamūna l-ghayba mā labithū fī l-ʿadhābi l-muhīni', 'অতঃপর আমি যখন সুলাইমানের মৃত্যু ঘটালাম, তখন ঘুণে পোকাই জ্বিনদেরকে তার মৃত্যু সম্পর্কে অবহিত করল, তারা (ধীরে ধীরে) সুলাইমানের লাঠি খেয়ে যাচ্ছিল। যখন সে পড়ে গেল তখন জ্বিনেরা বুঝতে পারল যে, তারা (নিজেরা) যদি অদৃশ্য বিষয় সম্পর্কে অবগত থাকত তাহলে তাদেরকে লাঞ্ছনাদায়ক শাস্তির মধ্যে পড়ে থাকতে হত না।', 'And when We decreed for Solomon death, nothing indicated to the jinn his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment.', 'অতঃপর আমি যখন সুলাইমানের মৃত্যু ঘটালাম, তখন ঘুণে পোকাই জ্বিনদেরকে তার মৃত্যু সম্পর্কে অবহিত করল, তারা (ধীরে ধীরে) সুলাইমানের লাঠি খেয়ে যাচ্ছিল। যখন সে পড়ে গেল তখন জ্বিনেরা বুঝতে পারল যে, তারা (নিজেরা) যদি অদৃশ্য বিষয় সম্পর্কে অবগত থাকত তাহলে তাদেরকে লাঞ্ছনাদায়ক শাস্তির মধ্যে পড়ে থাকতে হত না।', 'And when We decreed for Solomon death, nothing indicated to the jinn his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034014.mp3', now()),
  (34, 15, '', '[{"id":17849,"position":1,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":17850,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17851,"position":3,"text_uthmani":"لِسَبَإٍۢ","transliteration":"lisaba-in","translation_bn":"জন্যে সাবা (জাতির)","root":"—","lemma":"سَبَإ","grammar_bn":"অব্যয় (Preposition)"},{"id":17852,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17853,"position":5,"text_uthmani":"مَسْكَنِهِمْ","transliteration":"maskanihim","translation_bn":"বাসভূমির তাদের","root":"سكن","lemma":"مَسْكَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":17854,"position":6,"text_uthmani":"ءَايَةٌۭ ۖ","transliteration":"āyatun","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17856,"position":7,"text_uthmani":"جَنَّتَانِ","transliteration":"jannatāni","translation_bn":"দু''টি বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17857,"position":8,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17858,"position":9,"text_uthmani":"يَمِينٍۢ","transliteration":"yamīnin","translation_bn":"ডানদিক","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":17859,"position":10,"text_uthmani":"وَشِمَالٍۢ ۖ","transliteration":"washimālin","translation_bn":"ও বামদিকে","root":"شمل","lemma":"شِّمَال","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17861,"position":11,"text_uthmani":"كُلُوا۟","transliteration":"kulū","translation_bn":"\"(বলেছিলাম) তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17862,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17863,"position":13,"text_uthmani":"رِّزْقِ","transliteration":"riz''qi","translation_bn":"জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":17864,"position":14,"text_uthmani":"رَبِّكُمْ","transliteration":"rabbikum","translation_bn":"রবের তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17865,"position":15,"text_uthmani":"وَٱشْكُرُوا۟","transliteration":"wa-ush''kurū","translation_bn":"ও তোমরা কৃতজ্ঞতা প্রকাশ করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17866,"position":16,"text_uthmani":"لَهُۥ ۚ","transliteration":"lahu","translation_bn":"জন্যে তাঁর","root":"—","lemma":"لَهُۥ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":17868,"position":17,"text_uthmani":"بَلْدَةٌۭ","transliteration":"baldatun","translation_bn":"(এই) দেশ","root":"بلد","lemma":"بَلْدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17869,"position":18,"text_uthmani":"طَيِّبَةٌۭ","transliteration":"ṭayyibatun","translation_bn":"উত্তম","root":"طيب","lemma":"طَيِّبَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":17870,"position":19,"text_uthmani":"وَرَبٌّ","transliteration":"warabbun","translation_bn":"এবং রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17871,"position":20,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল\"","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":17872,"position":21,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'laqad kāna lisaba-in fī maskanihim āyatun jannatāni ʿan yamīnin washimālin kulū min riz''qi rabbikum wa-ush''kurū lahu baldatun ṭayyibatun warabbun ghafūrun', 'সাবার অধিবাসীদের জন্য তাদের বাসভূমিতে একটা নিদর্শন ছিল- দু’টো বাগান; একটা ডানে, একটা বামে। (তাদেরকে বলেছিলাম) তোমাদের প্রতিপালক প্রদত্ত রিযক ভোগ কর আর তাঁর প্রতি কৃতজ্ঞতা প্রকাশ কর। সুখ-শান্তির শহর আর ক্ষমাশীল পালনকর্তা।', 'There was for [the tribe of] Saba'' in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], "Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord."', 'সাবার অধিবাসীদের জন্য তাদের বাসভূমিতে একটা নিদর্শন ছিল- দু’টো বাগান; একটা ডানে, একটা বামে। (তাদেরকে বলেছিলাম) তোমাদের প্রতিপালক প্রদত্ত রিযক ভোগ কর আর তাঁর প্রতি কৃতজ্ঞতা প্রকাশ কর। সুখ-শান্তির শহর আর ক্ষমাশীল পালনকর্তা।', 'There was for [the tribe of] Saba'' in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], "Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034015.mp3', now()),
  (34, 16, '', '[{"id":18898,"position":1,"text_uthmani":"فَأَعْرَضُوا۟","transliteration":"fa-aʿraḍū","translation_bn":"কিন্তু তারা মুখ ফেরালো","root":"عرض","lemma":"أَعْرَضَ","grammar_bn":"শব্দ"},{"id":18899,"position":2,"text_uthmani":"فَأَرْسَلْنَا","transliteration":"fa-arsalnā","translation_bn":"তাই পাঠালাম আমরা","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"শব্দ"},{"id":18900,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18901,"position":4,"text_uthmani":"سَيْلَ","transliteration":"sayla","translation_bn":"বন্যা","root":"سيل","lemma":"سَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18902,"position":5,"text_uthmani":"ٱلْعَرِمِ","transliteration":"l-ʿarimi","translation_bn":"বাঁধ-ভাঙ্গা","root":"عرم","lemma":"عَرِم","grammar_bn":"শব্দ"},{"id":18903,"position":6,"text_uthmani":"وَبَدَّلْنَـٰهُم","transliteration":"wabaddalnāhum","translation_bn":"এবং আমরা পাল্টে দিলাম তাদের","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18904,"position":7,"text_uthmani":"بِجَنَّتَيْهِمْ","transliteration":"bijannatayhim","translation_bn":"বিনিময়ে দু''টি বাগানের তাদের","root":"جنن","lemma":"جَنَّة","grammar_bn":"অব্যয় (Preposition)"},{"id":18905,"position":8,"text_uthmani":"جَنَّتَيْنِ","transliteration":"jannatayni","translation_bn":"দু''টি বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18906,"position":9,"text_uthmani":"ذَوَاتَىْ","transliteration":"dhawātay","translation_bn":"সম্পন্ন","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":18907,"position":10,"text_uthmani":"أُكُلٍ","transliteration":"ukulin","translation_bn":"ফল-মূল","root":"اكل","lemma":"أُكُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18908,"position":11,"text_uthmani":"خَمْطٍۢ","transliteration":"khamṭin","translation_bn":"বিস্বাদ","root":"خمط","lemma":"خَمْط","grammar_bn":"বিশেষণ (Adjective)"},{"id":18909,"position":12,"text_uthmani":"وَأَثْلٍۢ","transliteration":"wa-athlin","translation_bn":"এবং ঝাউগাছ","root":"اثل","lemma":"أَثْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18910,"position":13,"text_uthmani":"وَشَىْءٍۢ","transliteration":"washayin","translation_bn":"ও কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18911,"position":14,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18912,"position":15,"text_uthmani":"سِدْرٍۢ","transliteration":"sid''rin","translation_bn":"কুলগাছ","root":"سدر","lemma":"سِدْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18913,"position":16,"text_uthmani":"قَلِيلٍۢ","transliteration":"qalīlin","translation_bn":"সামান্য","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":18914,"position":17,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-aʿraḍū fa-arsalnā ʿalayhim sayla l-ʿarimi wabaddalnāhum bijannatayhim jannatayni dhawātay ukulin khamṭin wa-athlin washayin min sid''rin qalīlin', 'কিন্তু তারা (আল্লাহ হতে) মুখ ফিরিয়ে নিল। কাজেই আমি তাদের বিরুদ্ধে পাঠালাম বাঁধ-ভাঙ্গা বন্যা, আর আমি তাদের বাগান দু’টিকে পরিবর্তিত করে দিলাম এমন দু’টি বাগানে যাতে জন্মিত বিস্বাদ ফল, ঝাউগাছ আর কিছু কুল গাছ।', 'But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees.', 'কিন্তু তারা (আল্লাহ হতে) মুখ ফিরিয়ে নিল। কাজেই আমি তাদের বিরুদ্ধে পাঠালাম বাঁধ-ভাঙ্গা বন্যা, আর আমি তাদের বাগান দু’টিকে পরিবর্তিত করে দিলাম এমন দু’টি বাগানে যাতে জন্মিত বিস্বাদ ফল, ঝাউগাছ আর কিছু কুল গাছ।', 'But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034016.mp3', now()),
  (34, 17, '', '[{"id":20015,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":20016,"position":2,"text_uthmani":"جَزَيْنَـٰهُم","transliteration":"jazaynāhum","translation_bn":"আমরা প্রতিফল দিই তাদের","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20017,"position":3,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণ","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20018,"position":4,"text_uthmani":"كَفَرُوا۟ ۖ","transliteration":"kafarū","translation_bn":"তারা অবিশ্বাস করেছিলো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20020,"position":5,"text_uthmani":"وَهَلْ","transliteration":"wahal","translation_bn":"এবং না","root":"—","lemma":"هَل\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20021,"position":6,"text_uthmani":"نُجَـٰزِىٓ","transliteration":"nujāzī","translation_bn":"আমরা দেই (এমন) প্রতিফল","root":"جزي","lemma":"نُجَٰزِى^","grammar_bn":"ক্রিয়া (Verb)"},{"id":20022,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":20023,"position":8,"text_uthmani":"ٱلْكَفُورَ","transliteration":"l-kafūra","translation_bn":"অকৃতজ্ঞকে","root":"كفر","lemma":"كَفُور","grammar_bn":"শব্দ"},{"id":20024,"position":9,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika jazaynāhum bimā kafarū wahal nujāzī illā l-kafūra', 'অকৃতজ্ঞতাভরে তাদের সত্য প্রত্যাখ্যান করার জন্য আমি তাদেরকে এ শাস্তি দিয়েছিলাম। আমি অকৃতজ্ঞদের ছাড়া এমন শাস্তি কাউকে দেই না।', '[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?', 'অকৃতজ্ঞতাভরে তাদের সত্য প্রত্যাখ্যান করার জন্য আমি তাদেরকে এ শাস্তি দিয়েছিলাম। আমি অকৃতজ্ঞদের ছাড়া এমন শাস্তি কাউকে দেই না।', '[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034017.mp3', now()),
  (34, 18, '', '[{"id":21042,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং স্থাপন করেছিলাম আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21043,"position":2,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"মাঝে তাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":21044,"position":3,"text_uthmani":"وَبَيْنَ","transliteration":"wabayna","translation_bn":"ও মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21045,"position":4,"text_uthmani":"ٱلْقُرَى","transliteration":"l-qurā","translation_bn":"জনবসতিগুলোর","root":"قري","lemma":"قَرْيَة","grammar_bn":"শব্দ"},{"id":21046,"position":5,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যাতে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":21047,"position":6,"text_uthmani":"بَـٰرَكْنَا","transliteration":"bāraknā","translation_bn":"কল্যাণ দিয়েছিলাম আমরা","root":"برك","lemma":"بَٰرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21048,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21049,"position":8,"text_uthmani":"قُرًۭى","transliteration":"quran","translation_bn":"(বহু) জনপদ","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21050,"position":9,"text_uthmani":"ظَـٰهِرَةًۭ","transliteration":"ẓāhiratan","translation_bn":"দৃশ্যমান","root":"ظهر","lemma":"ظَٰهِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21051,"position":10,"text_uthmani":"وَقَدَّرْنَا","transliteration":"waqaddarnā","translation_bn":"এবং পরিমাণ মতো রেখেছিলাম আমরা","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21052,"position":11,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21053,"position":12,"text_uthmani":"ٱلسَّيْرَ ۖ","transliteration":"l-sayra","translation_bn":"সফরের (দুরত্ব)","root":"سير","lemma":"سَيْر","grammar_bn":"শব্দ"},{"id":21055,"position":13,"text_uthmani":"سِيرُوا۟","transliteration":"sīrū","translation_bn":"\"(বলেছিলাম) তোমরা ভ্রমণ করো","root":"سير","lemma":"سَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21056,"position":14,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21057,"position":15,"text_uthmani":"لَيَالِىَ","transliteration":"layāliya","translation_bn":"রাতগুলোতে","root":"ليل","lemma":"لَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21058,"position":16,"text_uthmani":"وَأَيَّامًا","transliteration":"wa-ayyāman","translation_bn":"ও দিনগুলোতে","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21059,"position":17,"text_uthmani":"ءَامِنِينَ","transliteration":"āminīna","translation_bn":"নিরাপদে\"","root":"امن","lemma":"ءَامِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":21060,"position":18,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā baynahum wabayna l-qurā allatī bāraknā fīhā quran ẓāhiratan waqaddarnā fīhā l-sayra sīrū fīhā layāliya wa-ayyāman āminīna', 'তাদের এবং যে সব জনপদের প্রতি আমি অনুগ্রহ বর্ষণ করেছিলাম সেগুলোর মাঝে অনেক দৃশ্যমান জনপদ স্থাপন করে দিয়েছিলাম এবং ওগুলোর মাঝে সমান সমান দূরত্বে সফর মনযিল করে দিয়েছিলাম। (আর তাদেরকে বলেছিলাম) তোমরা এ সব জনপদে রাতে আর দিনে নিরাপদে ভ্রমণ কর।', 'And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], "Travel between them by night or day in safety."', 'তাদের এবং যে সব জনপদের প্রতি আমি অনুগ্রহ বর্ষণ করেছিলাম সেগুলোর মাঝে অনেক দৃশ্যমান জনপদ স্থাপন করে দিয়েছিলাম এবং ওগুলোর মাঝে সমান সমান দূরত্বে সফর মনযিল করে দিয়েছিলাম। (আর তাদেরকে বলেছিলাম) তোমরা এ সব জনপদে রাতে আর দিনে নিরাপদে ভ্রমণ কর।', 'And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], "Travel between them by night or day in safety."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034018.mp3', now()),
  (34, 19, '', '[{"id":22193,"position":1,"text_uthmani":"فَقَالُوا۟","transliteration":"faqālū","translation_bn":"কিন্তু তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":22194,"position":2,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22195,"position":3,"text_uthmani":"بَـٰعِدْ","transliteration":"bāʿid","translation_bn":"দূরত্ব বাড়াও","root":"بعد","lemma":"بَٰعِدْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22196,"position":4,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":22197,"position":5,"text_uthmani":"أَسْفَارِنَا","transliteration":"asfārinā","translation_bn":"সফরসমূহের আমাদের\"","root":"سفر","lemma":"أَسْفَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":22198,"position":6,"text_uthmani":"وَظَلَمُوٓا۟","transliteration":"waẓalamū","translation_bn":"এবং তারা সীমালঙ্ঘন করেছিলো","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22199,"position":7,"text_uthmani":"أَنفُسَهُمْ","transliteration":"anfusahum","translation_bn":"নিজেদের তাদের (উপর)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":22200,"position":8,"text_uthmani":"فَجَعَلْنَـٰهُمْ","transliteration":"fajaʿalnāhum","translation_bn":"অতঃপর আমরা পরিণত করলাম তাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"শব্দ"},{"id":22201,"position":9,"text_uthmani":"أَحَادِيثَ","transliteration":"aḥādītha","translation_bn":"কাহিনীর বিষয়বস্তু","root":"حدث","lemma":"حَدِيث","grammar_bn":"বিশেষ্য (Noun)"},{"id":22202,"position":10,"text_uthmani":"وَمَزَّقْنَـٰهُمْ","transliteration":"wamazzaqnāhum","translation_bn":"এবং আমরা ছিন্ন-ভিন্ন করলাম তাদেরকে","root":"مزق","lemma":"مُزِّقْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22203,"position":11,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেককে","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22204,"position":12,"text_uthmani":"مُمَزَّقٍ ۚ","transliteration":"mumazzaqin","translation_bn":"খুব ছিন্ন-ভিন্ন","root":"مزق","lemma":"مُمَزَّق","grammar_bn":"বিশেষ্য (Noun)"},{"id":22206,"position":13,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":22207,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22208,"position":15,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22209,"position":16,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":22210,"position":17,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":22211,"position":18,"text_uthmani":"صَبَّارٍۢ","transliteration":"ṣabbārin","translation_bn":"বড় ধৈর্যশীল","root":"صبر","lemma":"صَبَّار","grammar_bn":"বিশেষণ (Adjective)"},{"id":22212,"position":19,"text_uthmani":"شَكُورٍۢ","transliteration":"shakūrin","translation_bn":"কৃতজ্ঞ ব্যক্তির","root":"شكر","lemma":"شَكُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":22213,"position":20,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'faqālū rabbanā bāʿid bayna asfārinā waẓalamū anfusahum fajaʿalnāhum aḥādītha wamazzaqnāhum kulla mumazzaqin inna fī dhālika laāyātin likulli ṣabbārin shakūrin', 'কিন্তু তারা বলল- হে আমাদের পালনকর্তা! আমাদের সফর-মঞ্জিলগুলোর মাঝে ব্যবধান বাড়িয়ে দাও। তারা নিজেদের প্রতি যুলম করেছিল। কাজেই আমি তাদেরকে কাহিনী বানিয়ে ছাড়লাম (যে কাহিনী শোনানো হয়) আর তাদেরকে ছিন্ন ভিন্ন করে দিলাম। এতে প্রত্যেক ধৈর্যশীল কৃতজ্ঞ ব্যক্তির জন্য নিদর্শন রয়েছে।', 'But [insolently] they said, "Our Lord, lengthen the distance between our journeys," and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful.', 'কিন্তু তারা বলল- হে আমাদের পালনকর্তা! আমাদের সফর-মঞ্জিলগুলোর মাঝে ব্যবধান বাড়িয়ে দাও। তারা নিজেদের প্রতি যুলম করেছিল। কাজেই আমি তাদেরকে কাহিনী বানিয়ে ছাড়লাম (যে কাহিনী শোনানো হয়) আর তাদেরকে ছিন্ন ভিন্ন করে দিলাম। এতে প্রত্যেক ধৈর্যশীল কৃতজ্ঞ ব্যক্তির জন্য নিদর্শন রয়েছে।', 'But [insolently] they said, "Our Lord, lengthen the distance between our journeys," and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034019.mp3', now()),
  (34, 20, '', '[{"id":23228,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23229,"position":2,"text_uthmani":"صَدَّقَ","transliteration":"ṣaddaqa","translation_bn":"সত্য প্রমাণ করলো","root":"صدق","lemma":"صَدَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23230,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"ব্যাপারে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23231,"position":4,"text_uthmani":"إِبْلِيسُ","transliteration":"ib''līsu","translation_bn":"ইবলীস","root":"—","lemma":"إِبْلِيس","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23232,"position":5,"text_uthmani":"ظَنَّهُۥ","transliteration":"ẓannahu","translation_bn":"অনুমানকে তার","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23233,"position":6,"text_uthmani":"فَٱتَّبَعُوهُ","transliteration":"fa-ittabaʿūhu","translation_bn":"অতঃপর তারা অনুসরণ করলো তার","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"শব্দ"},{"id":23234,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":23235,"position":8,"text_uthmani":"فَرِيقًۭا","transliteration":"farīqan","translation_bn":"একটি দল","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":23236,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23237,"position":10,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":23238,"position":11,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ṣaddaqa ʿalayhim ib''līsu ẓannahu fa-ittabaʿūhu illā farīqan mina l-mu''minīna', 'তাদের ব্যাপারে ইবলীস তার ধারণা সত্য প্রমাণিত করল (যে ধারণা ইবলীস আল্লাহর নিকট ব্যক্ত করেছিল যে, অল্প সংখ্যক ব্যতীত সে মানুষদেরকে নিজের বশীভূত করে ছাড়বে)। ফলে মু’মিনদের একটি দল ছাড়া তারা সবাই তার অনুসরণ করল।', 'And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers.', 'তাদের ব্যাপারে ইবলীস তার ধারণা সত্য প্রমাণিত করল (যে ধারণা ইবলীস আল্লাহর নিকট ব্যক্ত করেছিল যে, অল্প সংখ্যক ব্যতীত সে মানুষদেরকে নিজের বশীভূত করে ছাড়বে)। ফলে মু’মিনদের একটি দল ছাড়া তারা সবাই তার অনুসরণ করল।', 'And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034020.mp3', now()),
  (34, 21, '', '[{"id":24269,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24270,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24271,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":24272,"position":4,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24273,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24274,"position":6,"text_uthmani":"سُلْطَـٰنٍ","transliteration":"sul''ṭānin","translation_bn":"আধিপত্য","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":24275,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":24276,"position":8,"text_uthmani":"لِنَعْلَمَ","transliteration":"linaʿlama","translation_bn":"যেন আমরা (বাস্তবে)  জানি","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":24277,"position":9,"text_uthmani":"مَن","transliteration":"man","translation_bn":"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24278,"position":10,"text_uthmani":"يُؤْمِنُ","transliteration":"yu''minu","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24279,"position":11,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"উপর আখেরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":24280,"position":12,"text_uthmani":"مِمَّنْ","transliteration":"mimman","translation_bn":"মধ্যে হ''তে কে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24281,"position":13,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":24282,"position":14,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"সম্পর্কে তার","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24283,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24284,"position":16,"text_uthmani":"شَكٍّۢ ۗ","transliteration":"shakkin","translation_bn":"সন্দেহের","root":"شكك","lemma":"شَكّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24286,"position":17,"text_uthmani":"وَرَبُّكَ","transliteration":"warabbuka","translation_bn":"এবং রব তোমার","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24287,"position":18,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24288,"position":19,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24289,"position":20,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":24290,"position":21,"text_uthmani":"حَفِيظٌۭ","transliteration":"ḥafīẓun","translation_bn":"তত্তাবধায়ক","root":"حفظ","lemma":"حَفِيظ","grammar_bn":"বিশেষণ (Adjective)"},{"id":24291,"position":22,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wamā kāna lahu ʿalayhim min sul''ṭānin illā linaʿlama man yu''minu bil-ākhirati mimman huwa min''hā fī shakkin warabbuka ʿalā kulli shayin ḥafīẓun', 'তাদের উপর শয়ত্বানের কোন ক্ষমতা ছিল না, তবে কে আখিরাতে বিশ্বাস করে আর কে তাতে সন্দেহ করে, তা প্রকাশ করাই ছিল আমার উদ্দেশ্য। তোমার প্রতিপালক সকল বিষয়ে হিফাযাতকারী।', 'And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian.', 'তাদের উপর শয়ত্বানের কোন ক্ষমতা ছিল না, তবে কে আখিরাতে বিশ্বাস করে আর কে তাতে সন্দেহ করে, তা প্রকাশ করাই ছিল আমার উদ্দেশ্য। তোমার প্রতিপালক সকল বিষয়ে হিফাযাতকারী।', 'And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034021.mp3', now()),
  (34, 22, '', '[{"id":25261,"position":1,"text_uthmani":"قُلِ","transliteration":"quli","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25262,"position":2,"text_uthmani":"ٱدْعُوا۟","transliteration":"id''ʿū","translation_bn":"\"(মুশরিকদেরকে) তোমরা ডাকো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":25263,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25264,"position":4,"text_uthmani":"زَعَمْتُم","transliteration":"zaʿamtum","translation_bn":"(ইলাহ) মনে করেছো তোমরা","root":"زعم","lemma":"زَعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25265,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25266,"position":6,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":25267,"position":7,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহ\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25269,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"(প্রকৃতপক্ষে) না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25270,"position":9,"text_uthmani":"يَمْلِكُونَ","transliteration":"yamlikūna","translation_bn":"তারা মালিক হয়","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25271,"position":10,"text_uthmani":"مِثْقَالَ","transliteration":"mith''qāla","translation_bn":"পরিমাণ","root":"ثقل","lemma":"مِثْقَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":25272,"position":11,"text_uthmani":"ذَرَّةٍۢ","transliteration":"dharratin","translation_bn":"কোনো অণুর","root":"ذرر","lemma":"ذَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25273,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25274,"position":13,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":25275,"position":14,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25276,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25277,"position":16,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":25278,"position":17,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নেই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25279,"position":18,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":25280,"position":19,"text_uthmani":"فِيهِمَا","transliteration":"fīhimā","translation_bn":"মধ্যে(আছে)এ দু''য়ের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25281,"position":20,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25282,"position":21,"text_uthmani":"شِرْكٍۢ","transliteration":"shir''kin","translation_bn":"অংশ","root":"شرك","lemma":"شِرْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":25283,"position":22,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25284,"position":23,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"জন্যে তাঁর","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":25285,"position":24,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"মধ্য হ''তে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25286,"position":25,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25287,"position":26,"text_uthmani":"ظَهِيرٍۢ","transliteration":"ẓahīrin","translation_bn":"সাহায্যকারী","root":"ظهر","lemma":"ظَهِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":25288,"position":27,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'quli id''ʿū alladhīna zaʿamtum min dūni l-lahi lā yamlikūna mith''qāla dharratin fī l-samāwāti walā fī l-arḍi wamā lahum fīhimā min shir''kin wamā lahu min''hum min ẓahīrin', 'বল, আল্লাহর পরিবর্তে তোমরা যাদেরকে (ইলাহ) মনে করতে তাদেরকে ডাক। তারা আসমান ও যমীনে অণু পরিমাণও কোন কিছুর মালিক নয়। এ দু’য়ে তাদের এতটুকু অংশ নেই, আর তাদের কেউ আল্লাহর সাহায্যকারীও নয়।', 'Say, [O Muhammad], "Invoke those you claim [as deities] besides Allah." They do not possess an atom''s weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant.', 'বল, আল্লাহর পরিবর্তে তোমরা যাদেরকে (ইলাহ) মনে করতে তাদেরকে ডাক। তারা আসমান ও যমীনে অণু পরিমাণও কোন কিছুর মালিক নয়। এ দু’য়ে তাদের এতটুকু অংশ নেই, আর তাদের কেউ আল্লাহর সাহায্যকারীও নয়।', 'Say, [O Muhammad], "Invoke those you claim [as deities] besides Allah." They do not possess an atom''s weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034022.mp3', now()),
  (34, 23, '', '[{"id":26349,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26350,"position":2,"text_uthmani":"تَنفَعُ","transliteration":"tanfaʿu","translation_bn":"উপকার দিবে","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26351,"position":3,"text_uthmani":"ٱلشَّفَـٰعَةُ","transliteration":"l-shafāʿatu","translation_bn":"কোনো সুপারিশ","root":"شفع","lemma":"شَفَٰعَة","grammar_bn":"শব্দ"},{"id":26352,"position":4,"text_uthmani":"عِندَهُۥٓ","transliteration":"ʿindahu","translation_bn":"কাছে তাঁর","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":26353,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26354,"position":6,"text_uthmani":"لِمَنْ","transliteration":"liman","translation_bn":"জন্যে যার","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26355,"position":7,"text_uthmani":"أَذِنَ","transliteration":"adhina","translation_bn":"তিনি অনুমতি দিবেন","root":"اذن","lemma":"أَذِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26356,"position":8,"text_uthmani":"لَهُۥ ۚ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":26358,"position":9,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"এমনকি","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":26359,"position":10,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":26360,"position":11,"text_uthmani":"فُزِّعَ","transliteration":"fuzziʿa","translation_bn":"দূর হয়ে যাবে (ভয়)","root":"فزع","lemma":"فُزِّعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26361,"position":12,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26362,"position":13,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"অন্তরগুলো তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26363,"position":14,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে( সুপারিশকারীদের)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26364,"position":15,"text_uthmani":"مَاذَا","transliteration":"mādhā","translation_bn":"\"কি","root":"—","lemma":"مَاذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":26365,"position":16,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছেন\"","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26366,"position":17,"text_uthmani":"رَبُّكُمْ ۖ","transliteration":"rabbukum","translation_bn":"রব তোমাদের\"","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26368,"position":18,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26369,"position":19,"text_uthmani":"ٱلْحَقَّ ۖ","transliteration":"l-ḥaqa","translation_bn":"\"(যা)সত্য\"","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":26371,"position":20,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26372,"position":21,"text_uthmani":"ٱلْعَلِىُّ","transliteration":"l-ʿaliyu","translation_bn":"সুউচ্চ","root":"علو","lemma":"عَلِيّ","grammar_bn":"শব্দ"},{"id":26373,"position":22,"text_uthmani":"ٱلْكَبِيرُ","transliteration":"l-kabīru","translation_bn":"সুমহান","root":"كبر","lemma":"كَبِير","grammar_bn":"শব্দ"},{"id":26374,"position":23,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'walā tanfaʿu l-shafāʿatu ʿindahu illā liman adhina lahu ḥattā idhā fuzziʿa ʿan qulūbihim qālū mādhā qāla rabbukum qālū l-ḥaqa wahuwa l-ʿaliyu l-kabīru', 'তাঁর কাছে সুপারিশ কোন কাজে আসবে না, তবে তাদের ব্যতীত যাদেরকে তিনি অনুমতি দেবেন। অতঃপর তাদের (অর্থাৎ আল্লাহর নৈকট্যলাভকারী ফেরেশতার কিংবা অন্যের জন্য সুপারিশ করার অনুমতিপ্রাপ্তদের) অন্তর থেকে যখন ভয় দূর হবে তখন তারা পরস্পর জিজ্ঞেস করবে- তোমাদের পালনকর্তা কী নির্দেশ দিলেন? তারা বলবে- যা সত্য ও ন্যায় (তার নির্দেশই তিনি দিয়েছেন), তিনি সর্বোচ্চ, সর্বশ্রেষ্ঠ।', 'And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], "What has your Lord said?" They will say, "The truth." And He is the Most High, the Grand.', 'তাঁর কাছে সুপারিশ কোন কাজে আসবে না, তবে তাদের ব্যতীত যাদেরকে তিনি অনুমতি দেবেন। অতঃপর তাদের (অর্থাৎ আল্লাহর নৈকট্যলাভকারী ফেরেশতার কিংবা অন্যের জন্য সুপারিশ করার অনুমতিপ্রাপ্তদের) অন্তর থেকে যখন ভয় দূর হবে তখন তারা পরস্পর জিজ্ঞেস করবে- তোমাদের পালনকর্তা কী নির্দেশ দিলেন? তারা বলবে- যা সত্য ও ন্যায় (তার নির্দেশই তিনি দিয়েছেন), তিনি সর্বোচ্চ, সর্বশ্রেষ্ঠ।', 'And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], "What has your Lord said?" They will say, "The truth." And He is the Most High, the Grand.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034023.mp3', now()),
  (34, 24, '', '[{"id":27366,"position":1,"text_uthmani":"۞ قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27367,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27368,"position":3,"text_uthmani":"يَرْزُقُكُم","transliteration":"yarzuqukum","translation_bn":"জীবিকা দেন আমাদের","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27369,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27370,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":27371,"position":6,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবী (হ''তে)\"","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27373,"position":7,"text_uthmani":"قُلِ","transliteration":"quli","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27374,"position":8,"text_uthmani":"ٱللَّهُ ۖ","transliteration":"l-lahu","translation_bn":"\"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27376,"position":9,"text_uthmani":"وَإِنَّآ","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27377,"position":10,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27378,"position":11,"text_uthmani":"إِيَّاكُمْ","transliteration":"iyyākum","translation_bn":"তোমরা (কোনো এক পক্ষ)","root":"—","lemma":"إِيَّا","grammar_bn":"সর্বনাম (Pronoun)"},{"id":27379,"position":12,"text_uthmani":"لَعَلَىٰ","transliteration":"laʿalā","translation_bn":"অবশ্যই উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27380,"position":13,"text_uthmani":"هُدًى","transliteration":"hudan","translation_bn":"সৎপথের","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":27381,"position":14,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27382,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27383,"position":16,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তি","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":27384,"position":17,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":27385,"position":18,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'qul man yarzuqukum mina l-samāwāti wal-arḍi quli l-lahu wa-innā aw iyyākum laʿalā hudan aw fī ḍalālin mubīnin', 'বল- আসমান ও যমীন হতে কে তোমাদেরকে রিযক দান করেন? বল- আল্লাহ। হয় আমরা, না হয় তোমরা অবশ্যই সৎপথে পরিচালিত অথবা স্পষ্ট গুমরাহিতে পতিত।', 'Say, "Who provides for you from the heavens and the earth?" Say, "Allah. And indeed, we or you are either upon guidance or in clear error."', 'বল- আসমান ও যমীন হতে কে তোমাদেরকে রিযক দান করেন? বল- আল্লাহ। হয় আমরা, না হয় তোমরা অবশ্যই সৎপথে পরিচালিত অথবা স্পষ্ট গুমরাহিতে পতিত।', 'Say, "Who provides for you from the heavens and the earth?" Say, "Allah. And indeed, we or you are either upon guidance or in clear error."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034024.mp3', now()),
  (34, 25, '', '[{"id":28435,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28436,"position":2,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":28437,"position":3,"text_uthmani":"تُسْـَٔلُونَ","transliteration":"tus''alūna","translation_bn":"তোমাদের জিজ্ঞাসা করা হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28438,"position":4,"text_uthmani":"عَمَّآ","transliteration":"ʿammā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28439,"position":5,"text_uthmani":"أَجْرَمْنَا","transliteration":"ajramnā","translation_bn":"আমরা অপরাধ করেছি","root":"جرم","lemma":"أَجْرَمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28440,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28441,"position":7,"text_uthmani":"نُسْـَٔلُ","transliteration":"nus''alu","translation_bn":"আমাদের জিজ্ঞেস করা হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28442,"position":8,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28443,"position":9,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করছো\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28444,"position":10,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'qul lā tus''alūna ʿammā ajramnā walā nus''alu ʿammā taʿmalūna', 'বল- আমাদের অপরাধের জন্য তোমরা জিজ্ঞাসিত হবে না, আর তোমরা যা কর তার জন্য আমাদেরকে জবাবদিহি করতে হবে না।', 'Say, "You will not be asked about what we committed, and we will not be asked about what you do."', 'বল- আমাদের অপরাধের জন্য তোমরা জিজ্ঞাসিত হবে না, আর তোমরা যা কর তার জন্য আমাদেরকে জবাবদিহি করতে হবে না।', 'Say, "You will not be asked about what we committed, and we will not be asked about what you do."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034025.mp3', now()),
  (34, 26, '', '[{"id":29351,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29352,"position":2,"text_uthmani":"يَجْمَعُ","transliteration":"yajmaʿu","translation_bn":"\"একত্র করবেন","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29353,"position":3,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"মাঝে আমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":29354,"position":4,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"রব আমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29355,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29356,"position":6,"text_uthmani":"يَفْتَحُ","transliteration":"yaftaḥu","translation_bn":"তিনি মীমাংসা করে দিবেন","root":"فتح","lemma":"فَتَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29357,"position":7,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"মাঝে আমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":29358,"position":8,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে সঠিক","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":29359,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29360,"position":10,"text_uthmani":"ٱلْفَتَّاحُ","transliteration":"l-fatāḥu","translation_bn":"শ্রেষ্ঠ বিচারক","root":"فتح","lemma":"فَتَّاح","grammar_bn":"শব্দ"},{"id":29361,"position":11,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সর্বজ্ঞ\"","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":29362,"position":12,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul yajmaʿu baynanā rabbunā thumma yaftaḥu baynanā bil-ḥaqi wahuwa l-fatāḥu l-ʿalīmu', 'বল- আমাদের পালনকর্তা আমাদেরকে একত্রিত করবেন অবশেষে তিনি আমাদের মাঝে সত্য ও ন্যায়সঙ্গতভাবে ফয়সালা করবেন। তিনি সর্বশ্রেষ্ঠ ফয়সালাকারী, সর্বজ্ঞাতা।', 'Say, "Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge."', 'বল- আমাদের পালনকর্তা আমাদেরকে একত্রিত করবেন অবশেষে তিনি আমাদের মাঝে সত্য ও ন্যায়সঙ্গতভাবে ফয়সালা করবেন। তিনি সর্বশ্রেষ্ঠ ফয়সালাকারী, সর্বজ্ঞাতা।', 'Say, "Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034026.mp3', now()),
  (34, 27, '', '[{"id":30324,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30325,"position":2,"text_uthmani":"أَرُونِىَ","transliteration":"arūniya","translation_bn":"\"তোমরা দেখাও তোমরা","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30326,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30327,"position":4,"text_uthmani":"أَلْحَقْتُم","transliteration":"alḥaqtum","translation_bn":"সংযুক্ত করেছো তোমরা","root":"لحق","lemma":"أَلْحَقْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30328,"position":5,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সাথে তাঁর","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":30329,"position":6,"text_uthmani":"شُرَكَآءَ ۖ","transliteration":"shurakāa","translation_bn":"শরিক হিসেবে","root":"شرك","lemma":"شَرِيك","grammar_bn":"বিশেষ্য (Noun)"},{"id":30331,"position":7,"text_uthmani":"كَلَّا ۚ","transliteration":"kallā","translation_bn":"কখনও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":30333,"position":8,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":30334,"position":9,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":30335,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30336,"position":11,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":30337,"position":12,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়\"","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":30338,"position":13,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'qul arūniya alladhīna alḥaqtum bihi shurakāa kallā bal huwa l-lahu l-ʿazīzu l-ḥakīmu', 'বল- তোমরা আমাকে (তাদেরকে) দেখাও যাদেরকে তোমরা তাঁর অংশীদার জুড়ে দিয়েছ। কক্ষনো (দেখাতে পারবে) না, বরং তিনি আল্লাহ, মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Say, "Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allah, the Exalted in Might, the Wise."', 'বল- তোমরা আমাকে (তাদেরকে) দেখাও যাদেরকে তোমরা তাঁর অংশীদার জুড়ে দিয়েছ। কক্ষনো (দেখাতে পারবে) না, বরং তিনি আল্লাহ, মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Say, "Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allah, the Exalted in Might, the Wise."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034027.mp3', now()),
  (34, 28, '', '[{"id":31312,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31313,"position":2,"text_uthmani":"أَرْسَلْنَـٰكَ","transliteration":"arsalnāka","translation_bn":"আমরা পাঠিয়েছি তোমাকে","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31314,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":31315,"position":4,"text_uthmani":"كَآفَّةًۭ","transliteration":"kāffatan","translation_bn":"সমগ্র","root":"كفف","lemma":"كَا^فَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31316,"position":5,"text_uthmani":"لِّلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানবজাতির","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":31317,"position":6,"text_uthmani":"بَشِيرًۭا","transliteration":"bashīran","translation_bn":"সুসংবাদ দাতারূপে","root":"بشر","lemma":"بَشِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":31318,"position":7,"text_uthmani":"وَنَذِيرًۭا","transliteration":"wanadhīran","translation_bn":"ও সতর্ককারী রূপে","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31319,"position":8,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31320,"position":9,"text_uthmani":"أَكْثَرَ","transliteration":"akthara","translation_bn":"অধিকাংশ","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":31321,"position":10,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":31322,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":31323,"position":12,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31324,"position":13,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wamā arsalnāka illā kāffatan lilnnāsi bashīran wanadhīran walākinna akthara l-nāsi lā yaʿlamūna', 'আমি তোমাকে সমগ্র মানবমন্ডলীর জন্য সুসংবাদদাতা ও সতর্ককারীরূপে প্রেরণ করেছি, কিন্তু অধিকাংশ মানুষ জানে না।', 'And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know.', 'আমি তোমাকে সমগ্র মানবমন্ডলীর জন্য সুসংবাদদাতা ও সতর্ককারীরূপে প্রেরণ করেছি, কিন্তু অধিকাংশ মানুষ জানে না।', 'And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034028.mp3', now()),
  (34, 29, '', '[{"id":32299,"position":1,"text_uthmani":"وَيَقُولُونَ","transliteration":"wayaqūlūna","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32300,"position":2,"text_uthmani":"مَتَىٰ","transliteration":"matā","translation_bn":"\"কখন","root":"—","lemma":"مَتَىٰ\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":32301,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"সেই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":32302,"position":4,"text_uthmani":"ٱلْوَعْدُ","transliteration":"l-waʿdu","translation_bn":"প্রতিশ্রুতি(পূর্ণ হবে)","root":"وعد","lemma":"وَعْد","grammar_bn":"শব্দ"},{"id":32303,"position":5,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":32304,"position":6,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32305,"position":7,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"সত্যবাদী\"","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":32306,"position":8,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'wayaqūlūna matā hādhā l-waʿdu in kuntum ṣādiqīna', 'তারা বলে- তুমি যদি সত্যবাদী হও তাহলে বল, (তোমার শুনানো) ও‘য়াদা কখন বাস্তবায়িত হবে?', 'And they say, "When is this promise, if you should be truthful?"', 'তারা বলে- তুমি যদি সত্যবাদী হও তাহলে বল, (তোমার শুনানো) ও‘য়াদা কখন বাস্তবায়িত হবে?', 'And they say, "When is this promise, if you should be truthful?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034029.mp3', now()),
  (34, 30, '', '[{"id":33132,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33133,"position":2,"text_uthmani":"لَّكُم","transliteration":"lakum","translation_bn":"\"জন্যে তোমাদের","root":"—","lemma":"لَّكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":33134,"position":3,"text_uthmani":"مِّيعَادُ","transliteration":"mīʿādu","translation_bn":"নির্দিষ্ট সময়","root":"وعد","lemma":"مِّيعَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":33135,"position":4,"text_uthmani":"يَوْمٍۢ","transliteration":"yawmin","translation_bn":"দিনে (যা)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":33136,"position":5,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":33137,"position":6,"text_uthmani":"تَسْتَـْٔخِرُونَ","transliteration":"tastakhirūna","translation_bn":"তোমরা পিছিয়ে দিতে পারবে","root":"اخر","lemma":"يَسْتَأْخِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33138,"position":7,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"থেকে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33139,"position":8,"text_uthmani":"سَاعَةًۭ","transliteration":"sāʿatan","translation_bn":"মুহূর্তকাল","root":"سوع","lemma":"سَاعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33140,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33141,"position":10,"text_uthmani":"تَسْتَقْدِمُونَ","transliteration":"tastaqdimūna","translation_bn":"তোমরা এগিয়ে আনতে পারবে\"","root":"قدم","lemma":"يَسْتَقْدِمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33142,"position":11,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'qul lakum mīʿādu yawmin lā tastakhirūna ʿanhu sāʿatan walā tastaqdimūna', 'বল- তোমাদের জন্য আছে এক নির্ধারিত দিন যা তোমরা এক মুহূর্তকালের জন্য বিলম্বিত করতে পারবে না, আর ত্বরান্বিত করতেও পারবে না।', 'Say, "For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it]."', 'বল- তোমাদের জন্য আছে এক নির্ধারিত দিন যা তোমরা এক মুহূর্তকালের জন্য বিলম্বিত করতে পারবে না, আর ত্বরান্বিত করতেও পারবে না।', 'Say, "For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it]."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/034030.mp3', now()),
