  (35, 1, '', '[{"id":860,"position":1,"text_uthmani":"ٱلْحَمْدُ","transliteration":"al-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":861,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":862,"position":3,"text_uthmani":"فَاطِرِ","transliteration":"fāṭiri","translation_bn":"(যিনি) স্রষ্টা","root":"فطر","lemma":"فَاطِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":863,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":864,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":865,"position":6,"text_uthmani":"جَاعِلِ","transliteration":"jāʿili","translation_bn":"(তিনিই) নিয়োগকারী","root":"جعل","lemma":"جَاعِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":866,"position":7,"text_uthmani":"ٱلْمَلَـٰٓئِكَةِ","transliteration":"l-malāikati","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":867,"position":8,"text_uthmani":"رُسُلًا","transliteration":"rusulan","translation_bn":"বাণীবাহক রূপে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":868,"position":9,"text_uthmani":"أُو۟لِىٓ","transliteration":"ulī","translation_bn":"বিশিষ্ট","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":869,"position":10,"text_uthmani":"أَجْنِحَةٍۢ","transliteration":"ajniḥatin","translation_bn":"(বহু) ডানা","root":"جنح","lemma":"جَنَاح","grammar_bn":"বিশেষ্য (Noun)"},{"id":870,"position":11,"text_uthmani":"مَّثْنَىٰ","transliteration":"mathnā","translation_bn":"দু''টি","root":"ثني","lemma":"مَثْنَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":871,"position":12,"text_uthmani":"وَثُلَـٰثَ","transliteration":"wathulātha","translation_bn":"ও তিনটি","root":"ثلث","lemma":"ثُلَٰث","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":872,"position":13,"text_uthmani":"وَرُبَـٰعَ ۚ","transliteration":"warubāʿa","translation_bn":"ও চারটি (করে)","root":"ربع","lemma":"رُبَٰع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":874,"position":14,"text_uthmani":"يَزِيدُ","transliteration":"yazīdu","translation_bn":"বৃদ্ধি করেন","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":875,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":876,"position":16,"text_uthmani":"ٱلْخَلْقِ","transliteration":"l-khalqi","translation_bn":"সৃষ্টি (কাঠামোর)","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":877,"position":17,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":878,"position":18,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন তিনি","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":880,"position":19,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":881,"position":20,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":882,"position":21,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":883,"position":22,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":884,"position":23,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুরই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":885,"position":24,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":886,"position":25,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'al-ḥamdu lillahi fāṭiri l-samāwāti wal-arḍi jāʿili l-malāikati rusulan ulī ajniḥatin mathnā wathulātha warubāʿa yazīdu fī l-khalqi mā yashāu inna l-laha ʿalā kulli shayin qadīrun', 'যাবতীয় প্রশংসা আকাশমন্ডলী ও পৃথিবীর সৃষ্টিকর্তা আল্লাহর জন্য। তিনি দূত মনোনীত করেন ফেরেশতামন্ডলীকে, যারা দুই দুই বা তিন তিন বা চার চার ডানা বিশিষ্ট। তিনি সৃষ্টিতে যা ইচ্ছে বৃদ্ধি করেন। আল্লাহ সকল বিষয়ের উপর সর্বশক্তিমান।', '[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent.', 'যাবতীয় প্রশংসা আকাশমন্ডলী ও পৃথিবীর সৃষ্টিকর্তা আল্লাহর জন্য। তিনি দূত মনোনীত করেন ফেরেশতামন্ডলীকে, যারা দুই দুই বা তিন তিন বা চার চার ডানা বিশিষ্ট। তিনি সৃষ্টিতে যা ইচ্ছে বৃদ্ধি করেন। আল্লাহ সকল বিষয়ের উপর সর্বশক্তিমান।', '[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035001.mp3', now()),
  (35, 2, '', '[{"id":1952,"position":1,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1953,"position":2,"text_uthmani":"يَفْتَحِ","transliteration":"yaftaḥi","translation_bn":"খুলে দেন","root":"فتح","lemma":"فَتَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1954,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1955,"position":4,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"মানুষের জন্যে","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":1956,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1957,"position":6,"text_uthmani":"رَّحْمَةٍۢ","transliteration":"raḥmatin","translation_bn":"(তাঁর) অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1958,"position":7,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"সে ক্ষেত্রে নেই","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":1959,"position":8,"text_uthmani":"مُمْسِكَ","transliteration":"mum''sika","translation_bn":"কোনো প্রতিরোধকারী","root":"مسك","lemma":"مُمْسِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":1960,"position":9,"text_uthmani":"لَهَا ۖ","transliteration":"lahā","translation_bn":"তার","root":"—","lemma":"لَهَا ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":1962,"position":10,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1963,"position":11,"text_uthmani":"يُمْسِكْ","transliteration":"yum''sik","translation_bn":"তিনি বন্ধ করেন","root":"مسك","lemma":"أَمْسَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1964,"position":12,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তখনও নেই","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":1965,"position":13,"text_uthmani":"مُرْسِلَ","transliteration":"mur''sila","translation_bn":"কোনো উন্মুক্তকারী (প্রেরণকারী)","root":"رسل","lemma":"مُرْسِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1966,"position":14,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":1967,"position":15,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1968,"position":16,"text_uthmani":"بَعْدِهِۦ ۚ","transliteration":"baʿdihi","translation_bn":"তাঁর পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":1970,"position":17,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1971,"position":18,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":1972,"position":19,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1973,"position":20,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā yaftaḥi l-lahu lilnnāsi min raḥmatin falā mum''sika lahā wamā yum''sik falā mur''sila lahu min baʿdihi wahuwa l-ʿazīzu l-ḥakīmu', 'আল্লাহ মানুষের জন্য তাঁর অনুগ্রহ থেকে যা খুলে দেন তা নিবারণ করার কেউ নেই। আর তিনি যা বারিত করেন অতঃপর কেউ তা প্রেরণ করতে পারে না। তিনি মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Whatever Allah grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise.', 'আল্লাহ মানুষের জন্য তাঁর অনুগ্রহ থেকে যা খুলে দেন তা নিবারণ করার কেউ নেই। আর তিনি যা বারিত করেন অতঃপর কেউ তা প্রেরণ করতে পারে না। তিনি মহাপরাক্রমশালী, মহাপ্রজ্ঞাময়।', 'Whatever Allah grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035002.mp3', now()),
  (35, 3, '', '[{"id":3141,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":3142,"position":2,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানব সম্প্রদায়","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":3143,"position":3,"text_uthmani":"ٱذْكُرُوا۟","transliteration":"udh''kurū","translation_bn":"তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3144,"position":4,"text_uthmani":"نِعْمَتَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহের (কথা)","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3145,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3146,"position":6,"text_uthmani":"عَلَيْكُمْ ۚ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3148,"position":7,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"(আছে) কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":3149,"position":8,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3150,"position":9,"text_uthmani":"خَـٰلِقٍ","transliteration":"khāliqin","translation_bn":"সৃষ্টিকর্তা","root":"خلق","lemma":"خَٰلِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":3151,"position":10,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"ব্যতীত","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":3152,"position":11,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3153,"position":12,"text_uthmani":"يَرْزُقُكُم","transliteration":"yarzuqukum","translation_bn":"তোমাদের জীবিকা দেয় (যে)","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3154,"position":13,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3155,"position":14,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3156,"position":15,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবী (হ''তে)","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3158,"position":16,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3159,"position":17,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোন ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":3160,"position":18,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3161,"position":19,"text_uthmani":"هُوَ ۖ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ ۖ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3163,"position":20,"text_uthmani":"فَأَنَّىٰ","transliteration":"fa-annā","translation_bn":"তা হ''লে কেমন করে","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"শব্দ"},{"id":3164,"position":21,"text_uthmani":"تُؤْفَكُونَ","transliteration":"tu''fakūna","translation_bn":"তোমাদের ফিরানো হচ্ছে","root":"افك","lemma":"أُفِكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3165,"position":22,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nāsu udh''kurū niʿ''mata l-lahi ʿalaykum hal min khāliqin ghayru l-lahi yarzuqukum mina l-samāi wal-arḍi lā ilāha illā huwa fa-annā tu''fakūna', 'হে মানুষ! তোমরা তোমাদের প্রতি আল্লাহর অনুগ্রহের কথা স্মরণ কর। তিনি ছাড়া কোন সৃষ্টিকর্তা আছে কি যে তোমাদেরকে আকাশ ও যমীন থেকে রিযক দান করে? তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, তাহলে কীভাবে তোমরা বিপথগামী হচ্ছ?', 'O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?', 'হে মানুষ! তোমরা তোমাদের প্রতি আল্লাহর অনুগ্রহের কথা স্মরণ কর। তিনি ছাড়া কোন সৃষ্টিকর্তা আছে কি যে তোমাদেরকে আকাশ ও যমীন থেকে রিযক দান করে? তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, তাহলে কীভাবে তোমরা বিপথগামী হচ্ছ?', 'O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035003.mp3', now()),
  (35, 4, '', '[{"id":4511,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং (হে নাবী) যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4512,"position":2,"text_uthmani":"يُكَذِّبُوكَ","transliteration":"yukadhibūka","translation_bn":"তোমাকে তারা মিথ্যারোপ করে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4513,"position":3,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"নিশ্চয়ই তবে","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":4514,"position":4,"text_uthmani":"كُذِّبَتْ","transliteration":"kudhibat","translation_bn":"মিথ্যারোপ করা হয়েছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4515,"position":5,"text_uthmani":"رُسُلٌۭ","transliteration":"rusulun","translation_bn":"রাসূলদেরকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":4516,"position":6,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4517,"position":7,"text_uthmani":"قَبْلِكَ ۚ","transliteration":"qablika","translation_bn":"তোমার পূর্বেও","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4519,"position":8,"text_uthmani":"وَإِلَى","transliteration":"wa-ilā","translation_bn":"এবং দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4520,"position":9,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4521,"position":10,"text_uthmani":"تُرْجَعُ","transliteration":"tur''jaʿu","translation_bn":"ফিরিয়ে আনা হয়","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4522,"position":11,"text_uthmani":"ٱلْأُمُورُ","transliteration":"l-umūru","translation_bn":"(সব) বিষয়","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":4523,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in yukadhibūka faqad kudhibat rusulun min qablika wa-ilā l-lahi tur''jaʿu l-umūru', 'তারা যদি তোমাকে মিথ্যে বলে অস্বীকার করে, তাহলে (তাদের এ আচরণ তো কোন নতুন বিষয় নয়) তোমার পূর্বেও রসূলদেরকে মিথ্যে বলে অস্বীকার করা হয়েছে। (যে যা-ই কিছু করুক না কেন) সমস্ত কার্যকলাপ (হিসাব নিকাশের জন্য) আল্লাহর কাছে ফিরে যাবে।', 'And if they deny you, [O Muhammad] - already were messengers denied before you. And to Allah are returned [all] matters.', 'তারা যদি তোমাকে মিথ্যে বলে অস্বীকার করে, তাহলে (তাদের এ আচরণ তো কোন নতুন বিষয় নয়) তোমার পূর্বেও রসূলদেরকে মিথ্যে বলে অস্বীকার করা হয়েছে। (যে যা-ই কিছু করুক না কেন) সমস্ত কার্যকলাপ (হিসাব নিকাশের জন্য) আল্লাহর কাছে ফিরে যাবে।', 'And if they deny you, [O Muhammad] - already were messengers denied before you. And to Allah are returned [all] matters.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035004.mp3', now()),
  (35, 5, '', '[{"id":5765,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":5766,"position":2,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানব সম্প্রদায়","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":5767,"position":3,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5768,"position":4,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5769,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5770,"position":6,"text_uthmani":"حَقٌّۭ ۖ","transliteration":"ḥaqqun","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5772,"position":7,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"সুতরাং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":5773,"position":8,"text_uthmani":"تَغُرَّنَّكُمُ","transliteration":"taghurrannakumu","translation_bn":"তোমাদেরকে ধোঁকা দেয় (যেন)","root":"غرر","lemma":"غَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5774,"position":9,"text_uthmani":"ٱلْحَيَوٰةُ","transliteration":"l-ḥayatu","translation_bn":"জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":5775,"position":10,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":5777,"position":11,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5778,"position":12,"text_uthmani":"يَغُرَّنَّكُم","transliteration":"yaghurrannakum","translation_bn":"তোমাদের ধোঁকা দেয় (যেন)","root":"غرر","lemma":"غَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5779,"position":13,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহর ব্যাপারে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":5780,"position":14,"text_uthmani":"ٱلْغَرُورُ","transliteration":"l-gharūru","translation_bn":"কোনো বড় ধোঁকাবাজ (অর্থাৎ শয়তান)","root":"غرر","lemma":"غَرُور","grammar_bn":"শব্দ"},{"id":5781,"position":15,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nāsu inna waʿda l-lahi ḥaqqun falā taghurrannakumu l-ḥayatu l-dun''yā walā yaghurrannakum bil-lahi l-gharūru', 'হে মানুষ! আল্লাহর ওয়া‘দা সত্য, কাজেই পার্থিব জীবন কিছুতেই যেন তোমাদেরকে প্রতারিত না করে; আর সেই প্রধান প্রতারক (শয়ত্বান) যেন কিছুতেই তোমাদেরকে আল্লাহ সম্পর্কে প্রতারিত না করে।', 'O mankind, indeed the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.', 'হে মানুষ! আল্লাহর ওয়া‘দা সত্য, কাজেই পার্থিব জীবন কিছুতেই যেন তোমাদেরকে প্রতারিত না করে; আর সেই প্রধান প্রতারক (শয়ত্বান) যেন কিছুতেই তোমাদেরকে আল্লাহ সম্পর্কে প্রতারিত না করে।', 'O mankind, indeed the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035005.mp3', now()),
  (35, 6, '', '[{"id":7054,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7055,"position":2,"text_uthmani":"ٱلشَّيْطَـٰنَ","transliteration":"l-shayṭāna","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":7056,"position":3,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":7057,"position":4,"text_uthmani":"عَدُوٌّۭ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7058,"position":5,"text_uthmani":"فَٱتَّخِذُوهُ","transliteration":"fa-ittakhidhūhu","translation_bn":"সুতরাং তোমরা তাকে  গ্রহণ করো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"শব্দ"},{"id":7059,"position":6,"text_uthmani":"عَدُوًّا ۚ","transliteration":"ʿaduwwan","translation_bn":"শত্রু হিসেবে","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7061,"position":7,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7062,"position":8,"text_uthmani":"يَدْعُوا۟","transliteration":"yadʿū","translation_bn":"সে ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":7063,"position":9,"text_uthmani":"حِزْبَهُۥ","transliteration":"ḥiz''bahu","translation_bn":"তার দলবলকে","root":"حزب","lemma":"حِزْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7064,"position":10,"text_uthmani":"لِيَكُونُوا۟","transliteration":"liyakūnū","translation_bn":"তারা হয় যেন","root":"كون","lemma":"كَانَ","grammar_bn":"শব্দ"},{"id":7065,"position":11,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7066,"position":12,"text_uthmani":"أَصْحَـٰبِ","transliteration":"aṣḥābi","translation_bn":"অধিবাসীদের","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7067,"position":13,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"জাহান্নামের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":7068,"position":14,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-shayṭāna lakum ʿaduwwun fa-ittakhidhūhu ʿaduwwan innamā yadʿū ḥiz''bahu liyakūnū min aṣḥābi l-saʿīri', 'শয়ত্বান তোমাদের শত্রু, কাজেই তাকে শত্রু হিসেবে গ্রহণ কর। সে কেবল তার দলবলকে ডাকে, যাতে তারা জ্বলন্ত অগ্নির সঙ্গী হয়।', 'Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze.', 'শয়ত্বান তোমাদের শত্রু, কাজেই তাকে শত্রু হিসেবে গ্রহণ কর। সে কেবল তার দলবলকে ডাকে, যাতে তারা জ্বলন্ত অগ্নির সঙ্গী হয়।', 'Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035006.mp3', now()),
  (35, 7, '', '[{"id":8361,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8362,"position":2,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8363,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":8364,"position":4,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8365,"position":5,"text_uthmani":"شَدِيدٌۭ ۖ","transliteration":"shadīdun","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":8367,"position":6,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"আর যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8368,"position":7,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8369,"position":8,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8370,"position":9,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকাজ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":8371,"position":10,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":8372,"position":11,"text_uthmani":"مَّغْفِرَةٌۭ","transliteration":"maghfiratun","translation_bn":"ক্ষমা","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8373,"position":12,"text_uthmani":"وَأَجْرٌۭ","transliteration":"wa-ajrun","translation_bn":"ও পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8374,"position":13,"text_uthmani":"كَبِيرٌ","transliteration":"kabīrun","translation_bn":"বড়","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":8375,"position":14,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna kafarū lahum ʿadhābun shadīdun wa-alladhīna āmanū waʿamilū l-ṣāliḥāti lahum maghfiratun wa-ajrun kabīrun', 'যারা কুফুরী করে তাদের জন্য রয়েছে কঠিন শাস্তি। আর যারা ঈমান আনে আর সৎকাজ করে তাদের জন্য রয়েছে ক্ষমা ও মহা প্রতিফল।', 'Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward.', 'যারা কুফুরী করে তাদের জন্য রয়েছে কঠিন শাস্তি। আর যারা ঈমান আনে আর সৎকাজ করে তাদের জন্য রয়েছে ক্ষমা ও মহা প্রতিফল।', 'Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035007.mp3', now()),
  (35, 8, '', '[{"id":9532,"position":1,"text_uthmani":"أَفَمَن","transliteration":"afaman","translation_bn":"তবে কি যে","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9533,"position":2,"text_uthmani":"زُيِّنَ","transliteration":"zuyyina","translation_bn":"শোভন করে দেখানো হয়েছে","root":"زين","lemma":"زَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9534,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার কাছে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":9535,"position":4,"text_uthmani":"سُوٓءُ","transliteration":"sūu","translation_bn":"মন্দ","root":"سوا","lemma":"سُو^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":9536,"position":5,"text_uthmani":"عَمَلِهِۦ","transliteration":"ʿamalihi","translation_bn":"তার কাজকে","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9537,"position":6,"text_uthmani":"فَرَءَاهُ","transliteration":"faraāhu","translation_bn":"তা অতঃপর সে মনে করে","root":"راي","lemma":"رَءَا","grammar_bn":"শব্দ"},{"id":9538,"position":7,"text_uthmani":"حَسَنًۭا ۖ","transliteration":"ḥasanan","translation_bn":"উত্তম হিসেবে (সে কি হেদায়াত পাবে?)","root":"حسن","lemma":"حَسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9540,"position":8,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"প্রকৃত পক্ষে নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":9541,"position":9,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9542,"position":10,"text_uthmani":"يُضِلُّ","transliteration":"yuḍillu","translation_bn":"বিভ্রান্ত করেন","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9543,"position":11,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9544,"position":12,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন তিনি","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9545,"position":13,"text_uthmani":"وَيَهْدِى","transliteration":"wayahdī","translation_bn":"এবং সৎ পথে পরিচালিত করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9546,"position":14,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9547,"position":15,"text_uthmani":"يَشَآءُ ۖ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9549,"position":16,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"সুতরাং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":9550,"position":17,"text_uthmani":"تَذْهَبْ","transliteration":"tadhhab","translation_bn":"চলে যায় (অর্থাৎ শেষ করে দিও)","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9551,"position":18,"text_uthmani":"نَفْسُكَ","transliteration":"nafsuka","translation_bn":"তোমার প্রাণ","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":9552,"position":19,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9553,"position":20,"text_uthmani":"حَسَرَٰتٍ ۚ","transliteration":"ḥasarātin","translation_bn":"আক্ষেপ করে","root":"حسر","lemma":"حَسْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9555,"position":21,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9556,"position":22,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9557,"position":23,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুব অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":9558,"position":24,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9559,"position":25,"text_uthmani":"يَصْنَعُونَ","transliteration":"yaṣnaʿūna","translation_bn":"তারা তৈরি করছে","root":"صنع","lemma":"صَنَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9560,"position":26,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'afaman zuyyina lahu sūu ʿamalihi faraāhu ḥasanan fa-inna l-laha yuḍillu man yashāu wayahdī man yashāu falā tadhhab nafsuka ʿalayhim ḥasarātin inna l-laha ʿalīmun bimā yaṣnaʿūna', 'যাকে তার মন্দ কর্ম শোভনীয় ক’রে দেখানো হয়, অতঃপর সে সেটাকে উত্তম মনে করে (সে কি তার সমান, যে সৎ পথে পরিচালিত?) আল্লাহ যাকে ইচ্ছে বিপথগামী করেন, আর যাকে ইচ্ছে সঠিক পথে পরিচালিত করেন। কাজেই তাদের জন্য আক্ষেপ ক’রে, তুমি তোমার জীবনকে ধ্বংস হতে দিও না। তারা যা করে আল্লাহ তা খুব ভালভাবেই জানেন।', 'Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allah sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allah is Knowing of what they do.', 'যাকে তার মন্দ কর্ম শোভনীয় ক’রে দেখানো হয়, অতঃপর সে সেটাকে উত্তম মনে করে (সে কি তার সমান, যে সৎ পথে পরিচালিত?) আল্লাহ যাকে ইচ্ছে বিপথগামী করেন, আর যাকে ইচ্ছে সঠিক পথে পরিচালিত করেন। কাজেই তাদের জন্য আক্ষেপ ক’রে, তুমি তোমার জীবনকে ধ্বংস হতে দিও না। তারা যা করে আল্লাহ তা খুব ভালভাবেই জানেন।', 'Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allah sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allah is Knowing of what they do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035008.mp3', now()),
  (35, 9, '', '[{"id":10722,"position":1,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ (তিনিই)","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10723,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10724,"position":3,"text_uthmani":"أَرْسَلَ","transliteration":"arsala","translation_bn":"পাঠান","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10725,"position":4,"text_uthmani":"ٱلرِّيَـٰحَ","transliteration":"l-riyāḥa","translation_bn":"বাতাস","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":10726,"position":5,"text_uthmani":"فَتُثِيرُ","transliteration":"fatuthīru","translation_bn":"অতঃপর (তা) সঞ্চালন","root":"ثور","lemma":"أَثَارُ","grammar_bn":"শব্দ"},{"id":10727,"position":6,"text_uthmani":"سَحَابًۭا","transliteration":"saḥāban","translation_bn":"মেঘমালা","root":"سحب","lemma":"سَحَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":10728,"position":7,"text_uthmani":"فَسُقْنَـٰهُ","transliteration":"fasuq''nāhu","translation_bn":"তা আমরা অতঃপর পরিচালনা করি","root":"سوق","lemma":"سِيقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10729,"position":8,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10730,"position":9,"text_uthmani":"بَلَدٍۢ","transliteration":"baladin","translation_bn":"ভূখণ্ডের","root":"بلد","lemma":"بَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10731,"position":10,"text_uthmani":"مَّيِّتٍۢ","transliteration":"mayyitin","translation_bn":"(যা ছিলো) নির্জীব মৃত","root":"موت","lemma":"مَّيِّت","grammar_bn":"বিশেষণ (Adjective)"},{"id":10732,"position":11,"text_uthmani":"فَأَحْيَيْنَا","transliteration":"fa-aḥyaynā","translation_bn":"আমরা এভাবে জীবিত করি","root":"حيي","lemma":"أَحْيَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10733,"position":12,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"তা দ্বারা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":10734,"position":13,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"মাটিকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":10735,"position":14,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":10736,"position":15,"text_uthmani":"مَوْتِهَا ۚ","transliteration":"mawtihā","translation_bn":"তার মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10738,"position":16,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবেই (হবে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":10739,"position":17,"text_uthmani":"ٱلنُّشُورُ","transliteration":"l-nushūru","translation_bn":"উত্থান","root":"نشر","lemma":"نُشُور","grammar_bn":"শব্দ"},{"id":10740,"position":18,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wal-lahu alladhī arsala l-riyāḥa fatuthīru saḥāban fasuq''nāhu ilā baladin mayyitin fa-aḥyaynā bihi l-arḍa baʿda mawtihā kadhālika l-nushūru', 'আল্লাহ, যিনি বায়ু প্রেরণ করেন, অতঃপর তা মেঘ সঞ্চার করে, অতঃপর আমি তা নির্জীব ভূখন্ডের দিকে পরিচালিত করি। অতঃপর আমি তা দিয়ে মৃত্তিকাকে তার মৃত্যুর পর আবার সঞ্জীবিত করি। এভাবেই (ঘটবে) পুনরুত্থান।', 'And it is Allah who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection.', 'আল্লাহ, যিনি বায়ু প্রেরণ করেন, অতঃপর তা মেঘ সঞ্চার করে, অতঃপর আমি তা নির্জীব ভূখন্ডের দিকে পরিচালিত করি। অতঃপর আমি তা দিয়ে মৃত্তিকাকে তার মৃত্যুর পর আবার সঞ্জীবিত করি। এভাবেই (ঘটবে) পুনরুত্থান।', 'And it is Allah who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035009.mp3', now()),
  (35, 10, '', '[{"id":11966,"position":1,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11967,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11968,"position":3,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11969,"position":4,"text_uthmani":"ٱلْعِزَّةَ","transliteration":"l-ʿizata","translation_bn":"সম্মান","root":"عزز","lemma":"عِزَّة","grammar_bn":"শব্দ"},{"id":11970,"position":5,"text_uthmani":"فَلِلَّهِ","transliteration":"falillahi","translation_bn":"তবে (জেনে রাখুক) আল্লাহর জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":11971,"position":6,"text_uthmani":"ٱلْعِزَّةُ","transliteration":"l-ʿizatu","translation_bn":"সম্মান","root":"عزز","lemma":"عِزَّة","grammar_bn":"শব্দ"},{"id":11972,"position":7,"text_uthmani":"جَمِيعًا ۚ","transliteration":"jamīʿan","translation_bn":"সবই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":11974,"position":8,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11975,"position":9,"text_uthmani":"يَصْعَدُ","transliteration":"yaṣʿadu","translation_bn":"উঠে","root":"صعد","lemma":"يَصْعَدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11976,"position":10,"text_uthmani":"ٱلْكَلِمُ","transliteration":"l-kalimu","translation_bn":"কথা","root":"كلم","lemma":"كَلِم","grammar_bn":"শব্দ"},{"id":11977,"position":11,"text_uthmani":"ٱلطَّيِّبُ","transliteration":"l-ṭayibu","translation_bn":"ভালো","root":"طيب","lemma":"طَيِّب","grammar_bn":"শব্দ"},{"id":11978,"position":12,"text_uthmani":"وَٱلْعَمَلُ","transliteration":"wal-ʿamalu","translation_bn":"এবং কাজ","root":"عمل","lemma":"عَمَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11979,"position":13,"text_uthmani":"ٱلصَّـٰلِحُ","transliteration":"l-ṣāliḥu","translation_bn":"সত","root":"صلح","lemma":"صَٰلِح","grammar_bn":"শব্দ"},{"id":11980,"position":14,"text_uthmani":"يَرْفَعُهُۥ ۚ","transliteration":"yarfaʿuhu","translation_bn":"তা উন্নীত করে","root":"رفع","lemma":"رَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11982,"position":15,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"ও যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11983,"position":16,"text_uthmani":"يَمْكُرُونَ","transliteration":"yamkurūna","translation_bn":"ষড়যন্ত্র করে","root":"مكر","lemma":"مَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11984,"position":17,"text_uthmani":"ٱلسَّيِّـَٔاتِ","transliteration":"l-sayiāti","translation_bn":"মন্দ (কাজের)","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":11985,"position":18,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":11986,"position":19,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11987,"position":20,"text_uthmani":"شَدِيدٌۭ ۖ","transliteration":"shadīdun","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":11989,"position":21,"text_uthmani":"وَمَكْرُ","transliteration":"wamakru","translation_bn":"এবং ষড়যন্ত্র","root":"مكر","lemma":"مَكْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11990,"position":22,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"তাদের","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":11991,"position":23,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":11992,"position":24,"text_uthmani":"يَبُورُ","transliteration":"yabūru","translation_bn":"ব্যর্থ হবে","root":"بور","lemma":"يَبُورُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11993,"position":25,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'man kāna yurīdu l-ʿizata falillahi l-ʿizatu jamīʿan ilayhi yaṣʿadu l-kalimu l-ṭayibu wal-ʿamalu l-ṣāliḥu yarfaʿuhu wa-alladhīna yamkurūna l-sayiāti lahum ʿadhābun shadīdun wamakru ulāika huwa yabūru', 'কেউ সম্মান-সুখ্যাতি চাইলে (আল্লাহকে উপেক্ষা করে তা লাভ করা যাবে না), সে জেনে নিক যাবতীয় সম্মান-সুখ্যাতির অধিকারী হলেন আল্লাহ। তাঁরই দিকে উত্থিত হয় পবিত্র কথাগুলো আর সৎকাজ সেগুলোকে উচ্চে তুলে ধরে। যারা মন্দ কাজের চক্রান্ত করে তাদের জন্য আছে কঠিন শাস্তি। তাদের চক্রান্ত নিষ্ফল হবে।', 'Whoever desires honor [through power] - then to Allah belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish.', 'কেউ সম্মান-সুখ্যাতি চাইলে (আল্লাহকে উপেক্ষা করে তা লাভ করা যাবে না), সে জেনে নিক যাবতীয় সম্মান-সুখ্যাতির অধিকারী হলেন আল্লাহ। তাঁরই দিকে উত্থিত হয় পবিত্র কথাগুলো আর সৎকাজ সেগুলোকে উচ্চে তুলে ধরে। যারা মন্দ কাজের চক্রান্ত করে তাদের জন্য আছে কঠিন শাস্তি। তাদের চক্রান্ত নিষ্ফল হবে।', 'Whoever desires honor [through power] - then to Allah belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035010.mp3', now()),
