  (35, 21, '', '[{"id":24304,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24305,"position":2,"text_uthmani":"ٱلظِّلُّ","transliteration":"l-ẓilu","translation_bn":"ছায়া","root":"ظلل","lemma":"ظِلّ","grammar_bn":"শব্দ"},{"id":24306,"position":3,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24307,"position":4,"text_uthmani":"ٱلْحَرُورُ","transliteration":"l-ḥarūru","translation_bn":"রৌদ্র","root":"حرر","lemma":"حَرُور","grammar_bn":"শব্দ"},{"id":24308,"position":5,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'walā l-ẓilu walā l-ḥarūru', 'আর ছায়া ও রোদও (সমান নয়)।', 'Nor are the shade and the heat,', 'আর ছায়া ও রোদও (সমান নয়)।', 'Nor are the shade and the heat,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035021.mp3', now()),
  (35, 22, '', '[{"id":25314,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25315,"position":2,"text_uthmani":"يَسْتَوِى","transliteration":"yastawī","translation_bn":"সমান হয়","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":25316,"position":3,"text_uthmani":"ٱلْأَحْيَآءُ","transliteration":"l-aḥyāu","translation_bn":"জীবিত","root":"حيي","lemma":"حَيّ","grammar_bn":"শব্দ"},{"id":25317,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25318,"position":5,"text_uthmani":"ٱلْأَمْوَٰتُ ۚ","transliteration":"l-amwātu","translation_bn":"মৃত","root":"موت","lemma":"مَّيِّت","grammar_bn":"শব্দ"},{"id":25320,"position":6,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25321,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25322,"position":8,"text_uthmani":"يُسْمِعُ","transliteration":"yus''miʿu","translation_bn":"শুনান","root":"سمع","lemma":"أَسْمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25323,"position":9,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25324,"position":10,"text_uthmani":"يَشَآءُ ۖ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন তিনি","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25326,"position":11,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25327,"position":12,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":25328,"position":13,"text_uthmani":"بِمُسْمِعٍۢ","transliteration":"bimus''miʿin","translation_bn":"শুনাতে সমর্থ","root":"سمع","lemma":"مُسْمِع","grammar_bn":"অব্যয় (Preposition)"},{"id":25329,"position":14,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"যে (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25330,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25331,"position":16,"text_uthmani":"ٱلْقُبُورِ","transliteration":"l-qubūri","translation_bn":"কবরগুলোর","root":"قبر","lemma":"قَبْر","grammar_bn":"শব্দ"},{"id":25332,"position":17,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yastawī l-aḥyāu walā l-amwātu inna l-laha yus''miʿu man yashāu wamā anta bimus''miʿin man fī l-qubūri', 'আর জীবিত ও মৃতও সমান নয়। আল্লাহ যাকে ইচ্ছে করেন শোনান; যারা ক্ববরে আছে তুমি তাদেরকে শোনাতে পার না।', 'And not equal are the living and the dead. Indeed, Allah causes to hear whom He wills, but you cannot make hear those in the graves.', 'আর জীবিত ও মৃতও সমান নয়। আল্লাহ যাকে ইচ্ছে করেন শোনান; যারা ক্ববরে আছে তুমি তাদেরকে শোনাতে পার না।', 'And not equal are the living and the dead. Indeed, Allah causes to hear whom He wills, but you cannot make hear those in the graves.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035022.mp3', now()),
  (35, 23, '', '[{"id":26375,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নও","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":26376,"position":2,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26377,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26378,"position":4,"text_uthmani":"نَذِيرٌ","transliteration":"nadhīrun","translation_bn":"একজন সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":26379,"position":5,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'in anta illā nadhīrun', 'তুমি তো কেবল একজন সতর্ককারী।', 'You, [O Muhammad], are not but a warner.', 'তুমি তো কেবল একজন সতর্ককারী।', 'You, [O Muhammad], are not but a warner.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035023.mp3', now()),
  (35, 24, '', '[{"id":27386,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27387,"position":2,"text_uthmani":"أَرْسَلْنَـٰكَ","transliteration":"arsalnāka","translation_bn":"তোমাকে আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27388,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"সত্যসহ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":27389,"position":4,"text_uthmani":"بَشِيرًۭا","transliteration":"bashīran","translation_bn":"সুসংবাদদাতা রূপে","root":"بشر","lemma":"بَشِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":27390,"position":5,"text_uthmani":"وَنَذِيرًۭا ۚ","transliteration":"wanadhīran","translation_bn":"ও সতর্ককারী হিসেবে","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27392,"position":6,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং নেই","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27393,"position":7,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27394,"position":8,"text_uthmani":"أُمَّةٍ","transliteration":"ummatin","translation_bn":"(এমন) জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27395,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27396,"position":10,"text_uthmani":"خَلَا","transliteration":"khalā","translation_bn":"অতিক্রম করেছে","root":"خلو","lemma":"خَلَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":27397,"position":11,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27398,"position":12,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"কোনো সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":27399,"position":13,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'innā arsalnāka bil-ḥaqi bashīran wanadhīran wa-in min ummatin illā khalā fīhā nadhīrun', 'আমি তোমাকে সত্যসহ পাঠিয়েছি সুসংবাদদাতা ও সতর্ককারীরূপে। এমন কোন সম্প্রদায় নেই যাতে সতর্ককারী আসেনি।', 'Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner.', 'আমি তোমাকে সত্যসহ পাঠিয়েছি সুসংবাদদাতা ও সতর্ককারীরূপে। এমন কোন সম্প্রদায় নেই যাতে সতর্ককারী আসেনি।', 'Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035024.mp3', now()),
  (35, 25, '', '[{"id":28450,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28451,"position":2,"text_uthmani":"يُكَذِّبُوكَ","transliteration":"yukadhibūka","translation_bn":"তোমাকে তারা মিথ্যারোপ করে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28452,"position":3,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তবে (নতুন কিছু নয়)","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":28453,"position":4,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28454,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা (ছিলো)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28455,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পূর্বেও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28456,"position":7,"text_uthmani":"قَبْلِهِمْ","transliteration":"qablihim","translation_bn":"তাদের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":28457,"position":8,"text_uthmani":"جَآءَتْهُمْ","transliteration":"jāathum","translation_bn":"তাদের কাছে এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28458,"position":9,"text_uthmani":"رُسُلُهُم","transliteration":"rusuluhum","translation_bn":"তাদের রাসূলগণ","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":28459,"position":10,"text_uthmani":"بِٱلْبَيِّنَـٰتِ","transliteration":"bil-bayināti","translation_bn":"স্পষ্ট নিদর্শনসহ","root":"بين","lemma":"بَيِّنَة","grammar_bn":"অব্যয় (Preposition)"},{"id":28460,"position":11,"text_uthmani":"وَبِٱلزُّبُرِ","transliteration":"wabil-zuburi","translation_bn":"এবং ছোট ছোট সহীফাসহ","root":"زبر","lemma":"زُبُر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28461,"position":12,"text_uthmani":"وَبِٱلْكِتَـٰبِ","transliteration":"wabil-kitābi","translation_bn":"ও কিতাবসহ","root":"كتب","lemma":"كِتَٰب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28462,"position":13,"text_uthmani":"ٱلْمُنِيرِ","transliteration":"l-munīri","translation_bn":"দীপ্তিময়","root":"نور","lemma":"مُّنِير","grammar_bn":"শব্দ"},{"id":28463,"position":14,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in yukadhibūka faqad kadhaba alladhīna min qablihim jāathum rusuluhum bil-bayināti wabil-zuburi wabil-kitābi l-munīri', 'তারা যদি তোমাকে মিথ্যে ব’লে অস্বীকার করে, (তাহলে জেনে রেখ, এটা কোন নতুন ব্যাপার নয়, কারণ) তাদের পূর্ববর্তীরাও (নবী-রসূলদেরকে) মিথ্যে ব’লে অস্বীকার করেছিল। তাদের কাছে তাদের রসূলগণ সুস্পষ্ট নিদর্শন, লিখিত দলীল ও আলোকপ্রদ কিতাব নিয়ে এসেছিল।', 'And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture.', 'তারা যদি তোমাকে মিথ্যে ব’লে অস্বীকার করে, (তাহলে জেনে রেখ, এটা কোন নতুন ব্যাপার নয়, কারণ) তাদের পূর্ববর্তীরাও (নবী-রসূলদেরকে) মিথ্যে ব’লে অস্বীকার করেছিল। তাদের কাছে তাদের রসূলগণ সুস্পষ্ট নিদর্শন, লিখিত দলীল ও আলোকপ্রদ কিতাব নিয়ে এসেছিল।', 'And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035025.mp3', now()),
  (35, 26, '', '[{"id":29363,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29364,"position":2,"text_uthmani":"أَخَذْتُ","transliteration":"akhadhtu","translation_bn":"আমি পাকড়াও করেছি","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29365,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"তাদেরকে (যারা)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29366,"position":4,"text_uthmani":"كَفَرُوا۟ ۖ","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29368,"position":5,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"অতঃপর কেমন (দেখো)","root":"كيف\r","lemma":"كَيْف","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29369,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29370,"position":7,"text_uthmani":"نَكِيرِ","transliteration":"nakīri","translation_bn":"আমার শাস্তি","root":"نكر","lemma":"نَكِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":29371,"position":8,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'thumma akhadhtu alladhīna kafarū fakayfa kāna nakīri', 'যারা কুফরী করেছিল, অতঃপর আমি তাদেরকে পাকড়াও করেছিলাম। কী (ভয়ংকর) ছিল আমার শাস্তি!', 'Then I seized the ones who disbelieved, and how [terrible] was My reproach.', 'যারা কুফরী করেছিল, অতঃপর আমি তাদেরকে পাকড়াও করেছিলাম। কী (ভয়ংকর) ছিল আমার শাস্তি!', 'Then I seized the ones who disbelieved, and how [terrible] was My reproach.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/035026.mp3', now()),
  (35, 27, '', '[{"id":30339,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"তুমি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":30340,"position":2,"text_uthmani":"تَرَ","transliteration":"tara","translation_bn":"দেখো নাই","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":30341,"position":3,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":30342,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30343,"position":5,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"বর্ষণ করেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30344,"position":6,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30345,"position":7,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":30346,"position":8,"text_uthmani":"مَآءًۭ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":30347,"position":9,"text_uthmani":"فَأَخْرَجْنَا","transliteration":"fa-akhrajnā","translation_bn":"অতঃপর আমরা উৎপন্ন করি","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":30348,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তা দিয়ে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":30349,"position":11,"text_uthmani":"ثَمَرَٰتٍۢ","transliteration":"thamarātin","translation_bn":"ফল মূলসমূহ","root":"ثمر","lemma":"ثَمَرَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":30350,"position":12,"text_uthmani":"مُّخْتَلِفًا","transliteration":"mukh''talifan","translation_bn":"বিচিত্র","root":"خلف","lemma":"م