  (36, 1, '', '[{"id":887,"position":1,"text_uthmani":"يسٓ","transliteration":"ya-seen","translation_bn":"ইয়া-সীন।","root":"—","lemma":"يسٓ","grammar_bn":"শব্দ"},{"id":888,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'ya-seen', 'ইয়াসীন।', 'Ya, Seen.', 'ইয়াসীন।', 'Ya, Seen.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036001.mp3', now()),
  (36, 2, '', '[{"id":1974,"position":1,"text_uthmani":"وَٱلْقُرْءَانِ","transliteration":"wal-qur''āni","translation_bn":"শপথ কুরআনের (যা)","root":"قرا","lemma":"قُرْءَان","grammar_bn":"অব্যয় (Preposition)"},{"id":1975,"position":2,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"জ্ঞানময়  (বিজ্ঞানময়)।","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1976,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-qur''āni l-ḥakīmi', 'শপথ হিকমতপূর্ণ কুরআনের।', 'By the wise Qur''an.', 'শপথ হিকমতপূর্ণ কুরআনের।', 'By the wise Qur''an.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036002.mp3', now()),
  (36, 3, '', '[{"id":3169,"position":1,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3170,"position":2,"text_uthmani":"لَمِنَ","transliteration":"lamina","translation_bn":"অন্তর্ভুক্ত অবশ্যই","root":"—","lemma":"مِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3171,"position":3,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদের।","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":3172,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'innaka lamina l-mur''salīna', 'তুমি অবশ্যই রসূলগণের অন্তর্ভুক্ত।', 'Indeed you, [O Muhammad], are from among the messengers,', 'তুমি অবশ্যই রসূলগণের অন্তর্ভুক্ত।', 'Indeed you, [O Muhammad], are from among the messengers,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036003.mp3', now()),
  (36, 4, '', '[{"id":4524,"position":1,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"(তুমি প্রতিষ্ঠিত) উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4525,"position":2,"text_uthmani":"صِرَٰطٍۢ","transliteration":"ṣirāṭin","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":4526,"position":3,"text_uthmani":"مُّسْتَقِيمٍۢ","transliteration":"mus''taqīmin","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4527,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'ʿalā ṣirāṭin mus''taqīmin', 'তুমি সরল সঠিক পথে প্রতিষ্ঠিত।', 'On a straight path.', 'তুমি সরল সঠিক পথে প্রতিষ্ঠিত।', 'On a straight path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036004.mp3', now()),
  (36, 5, '', '[{"id":5782,"position":1,"text_uthmani":"تَنزِيلَ","transliteration":"tanzīla","translation_bn":"(এই কোরআন) অবতীর্ণ করা","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5783,"position":2,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"পরাক্রমশালীর (পক্ষ হ''তে)","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":5784,"position":3,"text_uthmani":"ٱلرَّحِيمِ","transliteration":"l-raḥīmi","translation_bn":"(যিনি) পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":5785,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīla l-ʿazīzi l-raḥīmi', '(এ কুরআন) মহাপরাক্রমশালী পরম করুণাময় (আল্লাহ) হতে অবতীর্ণ।', '[This is] a revelation of the Exalted in Might, the Merciful,', '(এ কুরআন) মহাপরাক্রমশালী পরম করুণাময় (আল্লাহ) হতে অবতীর্ণ।', '[This is] a revelation of the Exalted in Might, the Merciful,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036005.mp3', now()),
  (36, 6, '', '[{"id":7069,"position":1,"text_uthmani":"لِتُنذِرَ","transliteration":"litundhira","translation_bn":"সতর্ক করো তুমি যেন","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":7070,"position":2,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"(এমন) জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7071,"position":3,"text_uthmani":"مَّآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7072,"position":4,"text_uthmani":"أُنذِرَ","transliteration":"undhira","translation_bn":"সতর্ক করা হয়েছে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7073,"position":5,"text_uthmani":"ءَابَآؤُهُمْ","transliteration":"ābāuhum","translation_bn":"তাদের পিতৃ-পুরুষদেরকে","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7074,"position":6,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"অতএব তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":7075,"position":7,"text_uthmani":"غَـٰفِلُونَ","transliteration":"ghāfilūna","translation_bn":"উদাসীন (হয়ে আছে)","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7076,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'litundhira qawman mā undhira ābāuhum fahum ghāfilūna', 'যাতে তুমি সতর্ক করতে পার এমন এক সম্প্রদায়কে যাদের পিৃতপুরুষদেরকে সতর্ক করা হয়নি, কাজেই তারা (আল্লাহর নিদর্শন সম্পর্কে) উদাসীন।', 'That you may warn a people whose forefathers were not warned, so they are unaware.', 'যাতে তুমি সতর্ক করতে পার এমন এক সম্প্রদায়কে যাদের পিৃতপুরুষদেরকে সতর্ক করা হয়নি, কাজেই তারা (আল্লাহর নিদর্শন সম্পর্কে) উদাসীন।', 'That you may warn a people whose forefathers were not warned, so they are unaware.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036006.mp3', now()),
  (36, 7, '', '[{"id":8380,"position":1,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8381,"position":2,"text_uthmani":"حَقَّ","transliteration":"ḥaqqa","translation_bn":"অবধারিত হয়েছে","root":"حقق","lemma":"حَقَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8382,"position":3,"text_uthmani":"ٱلْقَوْلُ","transliteration":"l-qawlu","translation_bn":"(শান্তির) বাণী","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":8383,"position":4,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8384,"position":5,"text_uthmani":"أَكْثَرِهِمْ","transliteration":"aktharihim","translation_bn":"তাদের অধিক অংশের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8385,"position":6,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"সুতরাং তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":8386,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8387,"position":8,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8388,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'laqad ḥaqqa l-qawlu ʿalā aktharihim fahum lā yu''minūna', '(জেনে বুঝে আল্লাহর অবাধ্য হওয়ার কারণে) তাদের অধিকাংশের উপর (তাদের অন্তঃকরণে সীল লাগিয়ে দেয়ার) বাণী অবধারিত হয়ে গেছে, কাজেই তারা ঈমান আনবে না।', 'Already the word has come into effect upon most of them, so they do not believe.', '(জেনে বুঝে আল্লাহর অবাধ্য হওয়ার কারণে) তাদের অধিকাংশের উপর (তাদের অন্তঃকরণে সীল লাগিয়ে দেয়ার) বাণী অবধারিত হয়ে গেছে, কাজেই তারা ঈমান আনবে না।', 'Already the word has come into effect upon most of them, so they do not believe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036007.mp3', now()),
  (36, 8, '', '[{"id":9561,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9562,"position":2,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা লাগিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9563,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9564,"position":4,"text_uthmani":"أَعْنَـٰقِهِمْ","transliteration":"aʿnāqihim","translation_bn":"তাদের গলায়","root":"عنق","lemma":"عُنُق","grammar_bn":"বিশেষ্য (Noun)"},{"id":9565,"position":5,"text_uthmani":"أَغْلَـٰلًۭا","transliteration":"aghlālan","translation_bn":"বেড়িসমূহ","root":"غلل","lemma":"غِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9566,"position":6,"text_uthmani":"فَهِىَ","transliteration":"fahiya","translation_bn":"তা তাই","root":"—","lemma":"فَهِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9567,"position":7,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"(রয়েছে) পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9568,"position":8,"text_uthmani":"ٱلْأَذْقَانِ","transliteration":"l-adhqāni","translation_bn":"চিবুকগুলো (শৃঙ্খলিত হয়ে)","root":"ذقن","lemma":"أَذْقَان","grammar_bn":"শব্দ"},{"id":9569,"position":9,"text_uthmani":"فَهُم","transliteration":"fahum","translation_bn":"তারা এজন্য","root":"—","lemma":"فَهُم","grammar_bn":"শব্দ"},{"id":9570,"position":10,"text_uthmani":"مُّقْمَحُونَ","transliteration":"muq''maḥūna","translation_bn":"ঊর্ধ্বমুখী (হয়ে আছে)","root":"قمح","lemma":"مُّقْمَحُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":9571,"position":11,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'innā jaʿalnā fī aʿnāqihim aghlālan fahiya ilā l-adhqāni fahum muq''maḥūna', 'আমি তাদের গলদেশে (তাদের জিদ ও অহমিকার) বেড়ি পরিয়ে দিয়েছি আর তা থুতনি পর্যন্ত (গিয়ে ঠেকেছে), কাজেই তারা মাথা খাড়া করে রেখেছে।', 'Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft.', 'আমি তাদের গলদেশে (তাদের জিদ ও অহমিকার) বেড়ি পরিয়ে দিয়েছি আর তা থুতনি পর্যন্ত (গিয়ে ঠেকেছে), কাজেই তারা মাথা খাড়া করে রেখেছে।', 'Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036008.mp3', now()),
  (36, 9, '', '[{"id":10741,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা খাড়া করেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10742,"position":2,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10743,"position":3,"text_uthmani":"بَيْنِ","transliteration":"bayni","translation_bn":"সামনে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10744,"position":4,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"তাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10745,"position":5,"text_uthmani":"سَدًّۭا","transliteration":"saddan","translation_bn":"প্রাচীর","root":"سدد","lemma":"سَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10746,"position":6,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"ও থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10747,"position":7,"text_uthmani":"خَلْفِهِمْ","transliteration":"khalfihim","translation_bn":"তাদের পিছন","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":10748,"position":8,"text_uthmani":"سَدًّۭا","transliteration":"saddan","translation_bn":"প্রাচীর","root":"سدد","lemma":"سَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10749,"position":9,"text_uthmani":"فَأَغْشَيْنَـٰهُمْ","transliteration":"fa-aghshaynāhum","translation_bn":"তাদেরকে আমরা এভাবে ঢেকে দিয়েছি","root":"غشو","lemma":"أُغْشِيَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10750,"position":10,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"তারা অতএব","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":10751,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":10752,"position":12,"text_uthmani":"يُبْصِرُونَ","transliteration":"yub''ṣirūna","translation_bn":"দেখতে পায়","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10753,"position":13,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā min bayni aydīhim saddan wamin khalfihim saddan fa-aghshaynāhum fahum lā yub''ṣirūna', 'তাদের সামনে আমি একটা (বাধার) প্রাচীর দাঁড় করিয়ে দিয়েছি, আর পেছনে একটা প্রাচীর, উপরন্তু তাদেরকে ঢেকে দিয়েছি; কাজেই তারা দেখতে পায় না।', 'And We have put before them a barrier and behind them a barrier and covered them, so they do not see.', 'তাদের সামনে আমি একটা (বাধার) প্রাচীর দাঁড় করিয়ে দিয়েছি, আর পেছনে একটা প্রাচীর, উপরন্তু তাদেরকে ঢেকে দিয়েছি; কাজেই তারা দেখতে পায় না।', 'And We have put before them a barrier and behind them a barrier and covered them, so they do not see.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036009.mp3', now()),
  (36, 10, '', '[{"id":11994,"position":1,"text_uthmani":"وَسَوَآءٌ","transliteration":"wasawāon","translation_bn":"এবং সমান","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11995,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের পক্ষে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11996,"position":3,"text_uthmani":"ءَأَنذَرْتَهُمْ","transliteration":"a-andhartahum","translation_bn":"তাদের তুমি সতর্ক করো কি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সমতাবাচক (Equalization)"},{"id":11997,"position":4,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"বা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11998,"position":5,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":11999,"position":6,"text_uthmani":"تُنذِرْهُمْ","transliteration":"tundhir''hum","translation_bn":"তাদের সতর্ক করো তুমি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12000,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":12001,"position":8,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"তারা ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12002,"position":9,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wasawāon ʿalayhim a-andhartahum am lam tundhir''hum lā yu''minūna', 'তুমি তাদেরকে সতর্ক কর আর না কর, তাদের কাছে দু’টোই সমান, তারা ঈমান আনবে না।', 'And it is all the same for them whether you warn them or do not warn them - they will not believe.', 'তুমি তাদেরকে সতর্ক কর আর না কর, তাদের কাছে দু’টোই সমান, তারা ঈমান আনবে না।', 'And it is all the same for them whether you warn them or do not warn them - they will not believe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036010.mp3', now()),
  (36, 11, '', '[{"id":13300,"position":1,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13301,"position":2,"text_uthmani":"تُنذِرُ","transliteration":"tundhiru","translation_bn":"সতর্ক করো তুমি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13302,"position":3,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"(তাকে) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13303,"position":4,"text_uthmani":"ٱتَّبَعَ","transliteration":"ittabaʿa","translation_bn":"মেনে চলে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13304,"position":5,"text_uthmani":"ٱلذِّكْرَ","transliteration":"l-dhik''ra","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":13305,"position":6,"text_uthmani":"وَخَشِىَ","transliteration":"wakhashiya","translation_bn":"ও ভয় করে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13306,"position":7,"text_uthmani":"ٱلرَّحْمَـٰنَ","transliteration":"l-raḥmāna","translation_bn":"দয়াময়কে","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":13307,"position":8,"text_uthmani":"بِٱلْغَيْبِ ۖ","transliteration":"bil-ghaybi","translation_bn":"না দেখা অবস্থায়","root":"غيب","lemma":"غَيْب","grammar_bn":"অব্যয় (Preposition)"},{"id":13309,"position":9,"text_uthmani":"فَبَشِّرْهُ","transliteration":"fabashir''hu","translation_bn":"তাকে সুতরাং দাও সুসংবাদ","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"শব্দ"},{"id":13310,"position":10,"text_uthmani":"بِمَغْفِرَةٍۢ","transliteration":"bimaghfiratin","translation_bn":"ক্ষমার","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"অব্যয় (Preposition)"},{"id":13311,"position":11,"text_uthmani":"وَأَجْرٍۢ","transliteration":"wa-ajrin","translation_bn":"ও প্রতিফলের","root":"اجر","lemma":"أَجْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13312,"position":12,"text_uthmani":"كَرِيمٍ","transliteration":"karīmin","translation_bn":"সম্মানজনক","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":13313,"position":13,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'innamā tundhiru mani ittabaʿa l-dhik''ra wakhashiya l-raḥmāna bil-ghaybi fabashir''hu bimaghfiratin wa-ajrin karīmin', 'তুমি তো সতর্ক কেবল তাকেই করতে পার যে লোক উপদেশ মেনে চলে আর দয়াময় (আল্লাহ)-কে না দেখেও ভয় করে। অতঃপর এদেরকে তুমি ক্ষমা ও সম্মানজনক পুরস্কারের সুসংবাদ দাও।', 'You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.', 'তুমি তো সতর্ক কেবল তাকেই করতে পার যে লোক উপদেশ মেনে চলে আর দয়াময় (আল্লাহ)-কে না দেখেও ভয় করে। অতঃপর এদেরকে তুমি ক্ষমা ও সম্মানজনক পুরস্কারের সুসংবাদ দাও।', 'You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036011.mp3', now()),
  (36, 12, '', '[{"id":14591,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14592,"position":2,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":14593,"position":3,"text_uthmani":"نُحْىِ","transliteration":"nuḥ''yī","translation_bn":"জীবিত করবো (একদিন)","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":14594,"position":4,"text_uthmani":"ٱلْمَوْتَىٰ","transliteration":"l-mawtā","translation_bn":"মৃতদেরকে","root":"موت","lemma":"مَّيِّت","grammar_bn":"শব্দ"},{"id":14595,"position":5,"text_uthmani":"وَنَكْتُبُ","transliteration":"wanaktubu","translation_bn":"এবং আমরা লিখে রাখি","root":"كتب","lemma":"كَتَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14596,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14597,"position":7,"text_uthmani":"قَدَّمُوا۟","transliteration":"qaddamū","translation_bn":"তারা আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14598,"position":8,"text_uthmani":"وَءَاثَـٰرَهُمْ ۚ","transliteration":"waāthārahum","translation_bn":"ও তাদের কীর্তিসমূহ (যা পিছনে রেখেছে)","root":"اثر","lemma":"أَثَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14600,"position":9,"text_uthmani":"وَكُلَّ","transliteration":"wakulla","translation_bn":"এবং প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14601,"position":10,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"জিনিস","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":14602,"position":11,"text_uthmani":"أَحْصَيْنَـٰهُ","transliteration":"aḥṣaynāhu","translation_bn":"তা আমরা সংরক্ষণ করেছি","root":"حصي","lemma":"أَحْصَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14603,"position":12,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14604,"position":13,"text_uthmani":"إِمَامٍۢ","transliteration":"imāmin","translation_bn":"একটি কিতাবের","root":"امم","lemma":"إِمَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":14605,"position":14,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":14606,"position":15,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'innā naḥnu nuḥ''yī l-mawtā wanaktubu mā qaddamū waāthārahum wakulla shayin aḥṣaynāhu fī imāmin mubīnin', 'আমিই মৃতকে জীবিত করি, আর লিখে রাখি যা তারা আগে পাঠিয়ে দেয় আর যা পেছনে ছেড়ে যায়। সব কিছুই আমি স্পষ্ট কিতাবে সংরক্ষিত করে রেখেছি।', 'Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register.', 'আমিই মৃতকে জীবিত করি, আর লিখে রাখি যা তারা আগে পাঠিয়ে দেয় আর যা পেছনে ছেড়ে যায়। সব কিছুই আমি স্পষ্ট কিতাবে সংরক্ষিত করে রেখেছি।', 'Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036012.mp3', now()),
  (36, 13, '', '[{"id":15686,"position":1,"text_uthmani":"وَٱضْرِبْ","transliteration":"wa-iḍ''rib","translation_bn":"এবং বর্ণনা করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15687,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের কাছে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":15688,"position":3,"text_uthmani":"مَّثَلًا","transliteration":"mathalan","translation_bn":"দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15689,"position":4,"text_uthmani":"أَصْحَـٰبَ","transliteration":"aṣḥāba","translation_bn":"অধিবাসীদেরকে","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":15690,"position":5,"text_uthmani":"ٱلْقَرْيَةِ","transliteration":"l-qaryati","translation_bn":"জনপদের","root":"قري","lemma":"قَرْيَة","grammar_bn":"শব্দ"},{"id":15691,"position":6,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":15692,"position":7,"text_uthmani":"جَآءَهَا","transliteration":"jāahā","translation_bn":"সেখানে এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15693,"position":8,"text_uthmani":"ٱلْمُرْسَلُونَ","transliteration":"l-mur''salūna","translation_bn":"রাসূলগণ","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":15694,"position":9,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iḍ''rib lahum mathalan aṣḥāba l-qaryati idh jāahā l-mur''salūna', 'তাদের কাছে দৃষ্টান্ত স্বরূপ এক জনপদবাসীদের কথা শুনিয়ে দাও যখন তাদের কাছে এসেছিল রসূলগণ।', 'And present to them an example: the people of the city, when the messengers came to it -', 'তাদের কাছে দৃষ্টান্ত স্বরূপ এক জনপদবাসীদের কথা শুনিয়ে দাও যখন তাদের কাছে এসেছিল রসূলগণ।', 'And present to them an example: the people of the city, when the messengers came to it -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036013.mp3', now()),
  (36, 14, '', '[{"id":16734,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":16735,"position":2,"text_uthmani":"أَرْسَلْنَآ","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16736,"position":3,"text_uthmani":"إِلَيْهِمُ","transliteration":"ilayhimu","translation_bn":"তাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16737,"position":4,"text_uthmani":"ٱثْنَيْنِ","transliteration":"ith''nayni","translation_bn":"দু''জনকে","root":"ثني","lemma":"ٱثْنَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":16738,"position":5,"text_uthmani":"فَكَذَّبُوهُمَا","transliteration":"fakadhabūhumā","translation_bn":"তখন উভয়কে তারা মিথ্যারোপ করলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":16739,"position":6,"text_uthmani":"فَعَزَّزْنَا","transliteration":"faʿazzaznā","translation_bn":"আমরা শক্তিশালী করলাম তখন","root":"عزز","lemma":"عَزَّزْ","grammar_bn":"শব্দ"},{"id":16740,"position":7,"text_uthmani":"بِثَالِثٍۢ","transliteration":"bithālithin","translation_bn":"তৃতীয়জনকে দিয়ে","root":"ثلث","lemma":"ثَالِث","grammar_bn":"অব্যয় (Preposition)"},{"id":16741,"position":8,"text_uthmani":"فَقَالُوٓا۟","transliteration":"faqālū","translation_bn":"তারা অতঃপর বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16742,"position":9,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"\"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16743,"position":10,"text_uthmani":"إِلَيْكُم","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16744,"position":11,"text_uthmani":"مُّرْسَلُونَ","transliteration":"mur''salūna","translation_bn":"প্রেরিত রাসূল\"","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16745,"position":12,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'idh arsalnā ilayhimu ith''nayni fakadhabūhumā faʿazzaznā bithālithin faqālū innā ilaykum mur''salūna', 'যখন তাদের কাছে দু’জন রসূল পাঠিয়েছিলাম তখন তারা সে দু’জনকে মিথ্যে ব’লে প্রত্যাখ্যান করল। অতঃপর আমি তৃতীয় আরেকজন দ্বারা তাদের শক্তি বৃদ্ধি করলাম। তারা বলল- আমরা তোমাদের প্রতি প্রেরিত হয়েছি।', 'When We sent to them two but they denied them, so We strengthened them with a third, and they said, "Indeed, we are messengers to you."', 'যখন তাদের কাছে দু’জন রসূল পাঠিয়েছিলাম তখন তারা সে দু’জনকে মিথ্যে ব’লে প্রত্যাখ্যান করল। অতঃপর আমি তৃতীয় আরেকজন দ্বারা তাদের শক্তি বৃদ্ধি করলাম। তারা বলল- আমরা তোমাদের প্রতি প্রেরিত হয়েছি।', 'When We sent to them two but they denied them, so We strengthened them with a third, and they said, "Indeed, we are messengers to you."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036014.mp3', now()),
  (36, 15, '', '[{"id":17907,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(লোকেরা) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17908,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17909,"position":3,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":17910,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":17911,"position":5,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":17912,"position":6,"text_uthmani":"مِّثْلُنَا","transliteration":"mith''lunā","translation_bn":"আমাদেরই মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":17913,"position":7,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"না এবং","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17914,"position":8,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17915,"position":9,"text_uthmani":"ٱلرَّحْمَـٰنُ","transliteration":"l-raḥmānu","translation_bn":"দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":17916,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17917,"position":11,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":17918,"position":12,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":17919,"position":13,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":17920,"position":14,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":17921,"position":15,"text_uthmani":"تَكْذِبُونَ","transliteration":"takdhibūna","translation_bn":"মিথ্যা বলছো\"","root":"كذب","lemma":"كَذَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17922,"position":16,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'qālū mā antum illā basharun mith''lunā wamā anzala l-raḥmānu min shayin in antum illā takdhibūna', 'জনপদবাসীরা বলল- তোমরা তো আমাদেরই মত মানুষ বতীত অন্য কিছু নও। আর দয়াময় (আল্লাহ) কোন কিছুই নাযিল করেননি। তোমরা শুধু মিথ্যেই বলছ।', 'They said, "You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies."', 'জনপদবাসীরা বলল- তোমরা তো আমাদেরই মত মানুষ বতীত অন্য কিছু নও। আর দয়াময় (আল্লাহ) কোন কিছুই নাযিল করেননি। তোমরা শুধু মিথ্যেই বলছ।', 'They said, "You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036015.mp3', now()),
  (36, 16, '', '[{"id":18930,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(রাসূলগণ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18931,"position":2,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"\"আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18932,"position":3,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18933,"position":4,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":18934,"position":5,"text_uthmani":"إِلَيْكُمْ","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18935,"position":6,"text_uthmani":"لَمُرْسَلُونَ","transliteration":"lamur''salūna","translation_bn":"প্রেরিত অবশ্যই (রাসূল হিসেবে)","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":18936,"position":7,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'qālū rabbunā yaʿlamu innā ilaykum lamur''salūna', 'রসূলগণ বলল- আমাদের পালনকর্তা জানেন আমরা অবশ্যই তোমাদের প্রতি প্রেরিত হয়েছি।', 'They said, "Our Lord knows that we are messengers to you,', 'রসূলগণ বলল- আমাদের পালনকর্তা জানেন আমরা অবশ্যই তোমাদের প্রতি প্রেরিত হয়েছি।', 'They said, "Our Lord knows that we are messengers to you,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036016.mp3', now()),
  (36, 17, '', '[{"id":20037,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20038,"position":2,"text_uthmani":"عَلَيْنَآ","transliteration":"ʿalaynā","translation_bn":"আমাদের উপর (দায়িত্ব)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20039,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":20040,"position":4,"text_uthmani":"ٱلْبَلَـٰغُ","transliteration":"l-balāghu","translation_bn":"প্রচার","root":"بلغ","lemma":"بَلَٰغ","grammar_bn":"শব্দ"},{"id":20041,"position":5,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্ট (পয়গাম)\"","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":20042,"position":6,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā ʿalaynā illā l-balāghu l-mubīnu', 'স্পষ্টভাবে (আল্লাহর বাণী) পৌঁছে দেয়াই আমাদের একমাত্র দায়িত্ব।', 'And we are not responsible except for clear notification."', 'স্পষ্টভাবে (আল্লাহর বাণী) পৌঁছে দেয়াই আমাদের একমাত্র দায়িত্ব।', 'And we are not responsible except for clear notification."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036017.mp3', now()),
  (36, 18, '', '[{"id":21108,"position":1,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21109,"position":2,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"\"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21110,"position":3,"text_uthmani":"تَطَيَّرْنَا","transliteration":"taṭayyarnā","translation_bn":"আমরা অমঙ্গল মনে করি","root":"طير","lemma":"ٱطَّيَّرْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21111,"position":4,"text_uthmani":"بِكُمْ ۖ","transliteration":"bikum","translation_bn":"তোমাদেরকে","root":"—","lemma":"بِكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":21113,"position":5,"text_uthmani":"لَئِن","transliteration":"la-in","translation_bn":"অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21114,"position":6,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":21115,"position":7,"text_uthmani":"تَنتَهُوا۟","transliteration":"tantahū","translation_bn":"তোমরা বিরত হও","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21116,"position":8,"text_uthmani":"لَنَرْجُمَنَّكُمْ","transliteration":"lanarjumannakum","translation_bn":"তোমাদেরকে আমরা পাথর মেরে হত্যা করবোই","root":"رجم","lemma":"رَجَمْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21117,"position":9,"text_uthmani":"وَلَيَمَسَّنَّكُم","transliteration":"walayamassannakum","translation_bn":"এবং তোমাদেরকে ধরবে অবশ্যই","root":"مسس","lemma":"مَسَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21118,"position":10,"text_uthmani":"مِّنَّا","transliteration":"minnā","translation_bn":"আমাদের পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21119,"position":11,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":21120,"position":12,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"নিদারুণ\"","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":21121,"position":13,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'qālū innā taṭayyarnā bikum la-in lam tantahū lanarjumannakum walayamassannakum minnā ʿadhābun alīmun', 'জনপদের লোকেরা বলল- আমরা তোমাদেরকেই অমঙ্গলের কারণ মনে করি। তোমরা যদি (প্রচারকার্য থেকে) নিবৃত্ত না হও, তাহলে আমরা অবশ্য অবশ্যই তোমাদেরকে পাথর মেরে হত্যা করব এবং আমাদের পক্ষ থেকে বড়ই মর্মান্তিক শাস্তি তোমাদের উপর অবশ্য অবশ্যই নেমে আসবে।', 'They said, "Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment."', 'জনপদের লোকেরা বলল- আমরা তোমাদেরকেই অমঙ্গলের কারণ মনে করি। তোমরা যদি (প্রচারকার্য থেকে) নিবৃত্ত না হও, তাহলে আমরা অবশ্য অবশ্যই তোমাদেরকে পাথর মেরে হত্যা করব এবং আমাদের পক্ষ থেকে বড়ই মর্মান্তিক শাস্তি তোমাদের উপর অবশ্য অবশ্যই নেমে আসবে।', 'They said, "Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036018.mp3', now()),
  (36, 19, '', '[{"id":22231,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(রাসূলগণ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22232,"position":2,"text_uthmani":"طَـٰٓئِرُكُم","transliteration":"ṭāirukum","translation_bn":"\"তোমাদের অমঙ্গলের (কারণ)","root":"طير","lemma":"طَٰ^ئِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":22233,"position":3,"text_uthmani":"مَّعَكُمْ ۚ","transliteration":"maʿakum","translation_bn":"তোমাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":22235,"position":4,"text_uthmani":"أَئِن","transliteration":"a-in","translation_bn":"(এসব বলছো) কি","root":"—","lemma":"إِن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":22236,"position":5,"text_uthmani":"ذُكِّرْتُم ۚ","transliteration":"dhukkir''tum","translation_bn":"তোমাদের উপদেশ দেওয়া হয়েছে","root":"ذكر","lemma":"ذُكِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22238,"position":6,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":22239,"position":7,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22240,"position":8,"text_uthmani":"قَوْمٌۭ","transliteration":"qawmun","translation_bn":"সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22241,"position":9,"text_uthmani":"مُّسْرِفُونَ","transliteration":"mus''rifūna","translation_bn":"সীমালঙ্ঘনকারী\"","root":"سرف","lemma":"مُسْرِف","grammar_bn":"বিশেষণ (Adjective)"},{"id":22242,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'qālū ṭāirukum maʿakum a-in dhukkir''tum bal antum qawmun mus''rifūna', 'রসূলগণ বলল- তোমাদের অমঙ্গলের কারণ তোমাদের সাথেই আছে (আর তা হল তোমাদের অপকর্ম)। তোমাদেরকে নসীহত করা হলেই কি (সেটাকে তোমরা তোমাদের অমঙ্গলের কারণ মনে কর)? আসলে তোমরা হচ্ছ এক সীমালঙ্ঘনকারী জাতি।', 'They said, "Your omen is with yourselves. Is it because you were reminded? Rather, you are a transgressing people."', 'রসূলগণ বলল- তোমাদের অমঙ্গলের কারণ তোমাদের সাথেই আছে (আর তা হল তোমাদের অপকর্ম)। তোমাদেরকে নসীহত করা হলেই কি (সেটাকে তোমরা তোমাদের অমঙ্গলের কারণ মনে কর)? আসলে তোমরা হচ্ছ এক সীমালঙ্ঘনকারী জাতি।', 'They said, "Your omen is with yourselves. Is it because you were reminded? Rather, you are a transgressing people."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036019.mp3', now()),
  (36, 20, '', '[{"id":23253,"position":1,"text_uthmani":"وَجَآءَ","transliteration":"wajāa","translation_bn":"এ অবস্থায় আসলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23254,"position":2,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23255,"position":3,"text_uthmani":"أَقْصَا","transliteration":"aqṣā","translation_bn":"এক প্রান্ত","root":"قصو","lemma":"أَقْصَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":23256,"position":4,"text_uthmani":"ٱلْمَدِينَةِ","transliteration":"l-madīnati","translation_bn":"শহরের","root":"مدن","lemma":"مَدِينَة","grammar_bn":"শব্দ"},{"id":23257,"position":5,"text_uthmani":"رَجُلٌۭ","transliteration":"rajulun","translation_bn":"এক ব্যক্তি","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23258,"position":6,"text_uthmani":"يَسْعَىٰ","transliteration":"yasʿā","translation_bn":"দৌঁড়ে","root":"سعي","lemma":"سَعَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23259,"position":7,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23260,"position":8,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"হে আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":23261,"position":9,"text_uthmani":"ٱتَّبِعُوا۟","transliteration":"ittabiʿū","translation_bn":"তোমরা অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23262,"position":10,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলগণকে","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":23263,"position":11,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wajāa min aqṣā l-madīnati rajulun yasʿā qāla yāqawmi ittabiʿū l-mur''salīna', 'নগর প্রান্ত থেকে এক লোক ছুটে আসলো। সে বলল- হে আমার জাতির লোকেরা! তোমরা রসূলদের মান্য কর।', 'And there came from the farthest end of the city a man, running. He said, "O my people, follow the messengers.', 'নগর প্রান্ত থেকে এক লোক ছুটে আসলো। সে বলল- হে আমার জাতির লোকেরা! তোমরা রসূলদের মান্য কর।', 'And there came from the farthest end of the city a man, running. He said, "O my people, follow the messengers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036020.mp3', now()),
  (36, 21, '', '[{"id":24321,"position":1,"text_uthmani":"ٱتَّبِعُوا۟","transliteration":"ittabiʿū","translation_bn":"তোমরা অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24322,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তার) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24323,"position":3,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24324,"position":4,"text_uthmani":"يَسْـَٔلُكُمْ","transliteration":"yasalukum","translation_bn":"তোমাদের কাছে চায়","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24325,"position":5,"text_uthmani":"أَجْرًۭا","transliteration":"ajran","translation_bn":"কোনো বিনিময়","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24326,"position":6,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24327,"position":7,"text_uthmani":"مُّهْتَدُونَ","transliteration":"muh''tadūna","translation_bn":"সৎপথপ্রাপ্ত","root":"هدي","lemma":"مُّهْتَدُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":24328,"position":8,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'ittabiʿū man lā yasalukum ajran wahum muh''tadūna', 'তোমরা মান্য কর এদেরকে- যারা তোমাদের কাছে কোন প্রতিদান চায় না। উপরন্তু তারা সঠিক পথে পরিচালিত।', 'Follow those who do not ask of you [any] payment, and they are [rightly] guided.', 'তোমরা মান্য কর এদেরকে- যারা তোমাদের কাছে কোন প্রতিদান চায় না। উপরন্তু তারা সঠিক পথে পরিচালিত।', 'Follow those who do not ask of you [any] payment, and they are [rightly] guided.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036021.mp3', now()),
  (36, 22, '', '[{"id":25346,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং কি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25347,"position":2,"text_uthmani":"لِىَ","transliteration":"liya","translation_bn":"আমার জন্য (যুক্তি আছে যে)","root":"—","lemma":"لِىَ","grammar_bn":"অব্যয় (Preposition)"},{"id":25348,"position":3,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25349,"position":4,"text_uthmani":"أَعْبُدُ","transliteration":"aʿbudu","translation_bn":"ইবাদত করবো আমি","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25350,"position":5,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(তাঁর) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25351,"position":6,"text_uthmani":"فَطَرَنِى","transliteration":"faṭaranī","translation_bn":"আমাকে সৃষ্টি করেছেন","root":"فطر","lemma":"فَطَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25352,"position":7,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"ও তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25353,"position":8,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমাদেরকে ফিরিয়ে নেয়া হবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25354,"position":9,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamā liya lā aʿbudu alladhī faṭaranī wa-ilayhi tur''jaʿūna', 'কেন আমি তাঁর ‘ইবাদাত করব না যিনি আমাকে সৃষ্টি করেছেন, আর তাঁর কাছেই তোমাদেরকে ফিরে যেতে হবে?', 'And why should I not worship He who created me and to whom you will be returned?', 'কেন আমি তাঁর ‘ইবাদাত করব না যিনি আমাকে সৃষ্টি করেছেন, আর তাঁর কাছেই তোমাদেরকে ফিরে যেতে হবে?', 'And why should I not worship He who created me and to whom you will be returned?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036022.mp3', now()),
  (36, 23, '', '[{"id":26387,"position":1,"text_uthmani":"ءَأَتَّخِذُ","transliteration":"a-attakhidhu","translation_bn":"গ্রহণ করবো আমি কি","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":26388,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26389,"position":3,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":26390,"position":4,"text_uthmani":"ءَالِهَةً","transliteration":"ālihatan","translation_bn":"উপাস্য (অন্য কাউকে)","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":26391,"position":5,"text_uthmani":"إِن","transliteration":"in","translation_bn":"(অথচ) যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":26392,"position":6,"text_uthmani":"يُرِدْنِ","transliteration":"yurid''ni","translation_bn":"আমাকে চান","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26393,"position":7,"text_uthmani":"ٱلرَّحْمَـٰنُ","transliteration":"l-raḥmānu","translation_bn":"দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":26394,"position":8,"text_uthmani":"بِضُرٍّۢ","transliteration":"biḍurrin","translation_bn":"কোনো ক্ষতি করতে","root":"ضرر","lemma":"ضُرّ","grammar_bn":"অব্যয় (Preposition)"},{"id":26395,"position":9,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":26396,"position":10,"text_uthmani":"تُغْنِ","transliteration":"tugh''ni","translation_bn":"কাজে আসবে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26397,"position":11,"text_uthmani":"عَنِّى","transliteration":"ʿannī","translation_bn":"আমার জন্যে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26398,"position":12,"text_uthmani":"شَفَـٰعَتُهُمْ","transliteration":"shafāʿatuhum","translation_bn":"তাদের সুপারিশ","root":"شفع","lemma":"شَفَٰعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26399,"position":13,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছু মাত্র","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":26400,"position":14,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26401,"position":15,"text_uthmani":"يُنقِذُونِ","transliteration":"yunqidhūni","translation_bn":"আমাকে তারা উদ্ধার করতে পারবে","root":"نقذ","lemma":"أَنقَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26402,"position":16,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'a-attakhidhu min dūnihi ālihatan in yurid''ni l-raḥmānu biḍurrin lā tugh''ni ʿannī shafāʿatuhum shayan walā yunqidhūni', 'আমি কি তাঁর পরিবর্তে (অন্য) সব ইলাহ্ গ্রহণ করব? করুণাময় আল্লাহ যদি আমার কোন ক্ষতি করতে চান তবে আমার জন্য তাদের সুপারিশ কোনই কাজে আসবে না, আর তারা আমাকে উদ্ধার করতেও পারবে না।', 'Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?', 'আমি কি তাঁর পরিবর্তে (অন্য) সব ইলাহ্ গ্রহণ করব? করুণাময় আল্লাহ যদি আমার কোন ক্ষতি করতে চান তবে আমার জন্য তাদের সুপারিশ কোনই কাজে আসবে না, আর তারা আমাকে উদ্ধার করতেও পারবে না।', 'Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036023.mp3', now()),
  (36, 24, '', '[{"id":27408,"position":1,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27409,"position":2,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"তাহ''লে","root":"—","lemma":"إِذًا\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":27410,"position":3,"text_uthmani":"لَّفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে হব","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27411,"position":4,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":27412,"position":5,"text_uthmani":"مُّبِينٍ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":27413,"position":6,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'innī idhan lafī ḍalālin mubīnin', 'তা যদি করি, তাহলে আমি স্পষ্ট পথভ্রষ্টতেই পতিত হব।', 'Indeed, I would then be in manifest error.', 'তা যদি করি, তাহলে আমি স্পষ্ট পথভ্রষ্টতেই পতিত হব।', 'Indeed, I would then be in manifest error.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036024.mp3', now()),
  (36, 25, '', '[{"id":28473,"position":1,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"নিশ্চযই় আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28474,"position":2,"text_uthmani":"ءَامَنتُ","transliteration":"āmantu","translation_bn":"আমি ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28475,"position":3,"text_uthmani":"بِرَبِّكُمْ","transliteration":"birabbikum","translation_bn":"প্রতি তোমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":28476,"position":4,"text_uthmani":"فَٱسْمَعُونِ","transliteration":"fa-is''maʿūni","translation_bn":"সুতরা তোমরা আমার কথা শোনো (ও মানো)\"","root":"سمع","lemma":"سَمِعَ","grammar_bn":"শব্দ"},{"id":28477,"position":5,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'innī āmantu birabbikum fa-is''maʿūni', 'আমি তো তোমাদের পালনকর্তার উপর ঈমান এনেছি, কাজেই তোমরা আমার কথা শুন।', 'Indeed, I have believed in your Lord, so listen to me."', 'আমি তো তোমাদের পালনকর্তার উপর ঈমান এনেছি, কাজেই তোমরা আমার কথা শুন।', 'Indeed, I have believed in your Lord, so listen to me."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036025.mp3', now()),
  (36, 26, '', '[{"id":29381,"position":1,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"(তাকে তারা হত্যা করলো এবং তাকে) বলা হলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29382,"position":2,"text_uthmani":"ٱدْخُلِ","transliteration":"ud''khuli","translation_bn":"\"প্রবেশ করো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29383,"position":3,"text_uthmani":"ٱلْجَنَّةَ ۖ","transliteration":"l-janata","translation_bn":"জান্নাতে\"","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":29385,"position":4,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29386,"position":5,"text_uthmani":"يَـٰلَيْتَ","transliteration":"yālayta","translation_bn":"\"হায় আফসোস্‌","root":"—","lemma":"لَيْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":29387,"position":6,"text_uthmani":"قَوْمِى","transliteration":"qawmī","translation_bn":"আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":29388,"position":7,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"(যদি) জানতো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29389,"position":8,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'qīla ud''khuli l-janata qāla yālayta qawmī yaʿlamūna', '(লোকেরা তাকে হত্যা করে ফেললে আল্লাহর পক্ষ থেকে) তাকে বলা হল- জান্নাতে প্রবেশ কর। (তখন) সে বলল- হায়! আমার জাতির লোকেরা যদি জানত,', 'It was said, "Enter Paradise." He said, "I wish my people could know', '(লোকেরা তাকে হত্যা করে ফেললে আল্লাহর পক্ষ থেকে) তাকে বলা হল- জান্নাতে প্রবেশ কর। (তখন) সে বলল- হায়! আমার জাতির লোকেরা যদি জানত,', 'It was said, "Enter Paradise." He said, "I wish my people could know', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036026.mp3', now()),
  (36, 27, '', '[{"id":30371,"position":1,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যে কারণে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30372,"position":2,"text_uthmani":"غَفَرَ","transliteration":"ghafara","translation_bn":"ক্ষমা করেছেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30373,"position":3,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":30374,"position":4,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব্‌","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30375,"position":5,"text_uthmani":"وَجَعَلَنِى","transliteration":"wajaʿalanī","translation_bn":"ও আমাকে করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30376,"position":6,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30377,"position":7,"text_uthmani":"ٱلْمُكْرَمِينَ","transliteration":"l-muk''ramīna","translation_bn":"সম্মানিতদের\"","root":"كرم","lemma":"مُّكْرَمُون","grammar_bn":"শব্দ"},{"id":30378,"position":8,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'bimā ghafara lī rabbī wajaʿalanī mina l-muk''ramīna', 'আমার পালনকর্তা কোন্ জিনিসের বদৌলতে আমাকে ক্ষমা করেছেন আর আমাকে সম্মানিতদের অন্তর্ভুক্ত করেছেন।', 'Of how my Lord has forgiven me and placed me among the honored."', 'আমার পালনকর্তা কোন্ জিনিসের বদৌলতে আমাকে ক্ষমা করেছেন আর আমাকে সম্মানিতদের অন্তর্ভুক্ত করেছেন।', 'Of how my Lord has forgiven me and placed me among the honored."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036027.mp3', now()),
  (36, 28, '', '[{"id":31381,"position":1,"text_uthmani":"۞ وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31382,"position":2,"text_uthmani":"أَنزَلْنَا","transliteration":"anzalnā","translation_bn":"আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31383,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31384,"position":4,"text_uthmani":"قَوْمِهِۦ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":31385,"position":5,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"পরে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31386,"position":6,"text_uthmani":"بَعْدِهِۦ","transliteration":"baʿdihi","translation_bn":"তার","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":31387,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31388,"position":8,"text_uthmani":"جُندٍۢ","transliteration":"jundin","translation_bn":"সৈন্য","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":31389,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31390,"position":10,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":31391,"position":11,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31392,"position":12,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31393,"position":13,"text_uthmani":"مُنزِلِينَ","transliteration":"munzilīna","translation_bn":"অবতীর্ণকারী","root":"نزل","lemma":"مُنزِلِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":31394,"position":14,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wamā anzalnā ʿalā qawmihi min baʿdihi min jundin mina l-samāi wamā kunnā munzilīna', 'আমি তার মৃত্যুর পর তার জাতির বিরুদ্ধে আসমান থেকে কোন সৈন্যবাহিনী পাঠাইনি, আর তা পাঠানোর আমার কোন দরকারও ছিল না।', 'And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so.', 'আমি তার মৃত্যুর পর তার জাতির বিরুদ্ধে আসমান থেকে কোন সৈন্যবাহিনী পাঠাইনি, আর তা পাঠানোর আমার কোন দরকারও ছিল না।', 'And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036028.mp3', now()),
  (36, 29, '', '[{"id":32334,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":32335,"position":2,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32336,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":32337,"position":4,"text_uthmani":"صَيْحَةًۭ","transliteration":"ṣayḥatan","translation_bn":"মহাগর্জন","root":"صيح","lemma":"صَيْحَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":32338,"position":5,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একটি মাত্র","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":32339,"position":6,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"তখন","root":"—","lemma":"إِذَا2\r","grammar_bn":"শব্দ"},{"id":32340,"position":7,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":32341,"position":8,"text_uthmani":"خَـٰمِدُونَ","transliteration":"khāmidūna","translation_bn":"নিথর নিস্তব্ধ হয়ে গেলো","root":"خمد","lemma":"خَٰمِدِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":32342,"position":9,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'in kānat illā ṣayḥatan wāḥidatan fa-idhā hum khāmidūna', 'ওটা ছিল মাত্র একটা প্রচন্ড শব্দ, ফলে তারা সহসাই নিস্তব্ধ হয়ে গেল।', 'It was not but one shout, and immediately they were extinguished.', 'ওটা ছিল মাত্র একটা প্রচন্ড শব্দ, ফলে তারা সহসাই নিস্তব্ধ হয়ে গেল।', 'It was not but one shout, and immediately they were extinguished.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036029.mp3', now()),
  (36, 30, '', '[{"id":33190,"position":1,"text_uthmani":"يَـٰحَسْرَةً","transliteration":"yāḥasratan","translation_bn":"হায় পরিতাপ","root":"حسر","lemma":"حَسْرَة","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":33191,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্য","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33192,"position":3,"text_uthmani":"ٱلْعِبَادِ ۚ","transliteration":"l-ʿibādi","translation_bn":"দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"শব্দ"},{"id":33194,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":33195,"position":5,"text_uthmani":"يَأْتِيهِم","transliteration":"yatīhim","translation_bn":"তাদেরর কাছে এসেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":33196,"position":6,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"(এমন) কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33197,"position":7,"text_uthmani":"رَّسُولٍ","transliteration":"rasūlin","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":33198,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":33199,"position":9,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33200,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তাঁর সাথে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":33201,"position":11,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"ঠাট্টা বিদ্রূপ করতো","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33202,"position":12,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'yāḥasratan ʿalā l-ʿibādi mā yatīhim min rasūlin illā kānū bihi yastahziūna', 'বান্দাহদের জন্য পরিতাপ! তাদের কাছে এমন কোন রসূলই আসেনি যাকে তারা ঠাট্টা-বিদ্রূপ করেনি।', 'How regretful for the servants. There did not come to them any messenger except that they used to ridicule him.', 'বান্দাহদের জন্য পরিতাপ! তাদের কাছে এমন কোন রসূলই আসেনি যাকে তারা ঠাট্টা-বিদ্রূপ করেনি।', 'How regretful for the servants. There did not come to them any messenger except that they used to ridicule him.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036030.mp3', now()),
  (36, 31, '', '[{"id":34250,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"দেখে নি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":34251,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":34252,"position":3,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"কত (জাতিকে)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":34253,"position":4,"text_uthmani":"أَهْلَكْنَا","transliteration":"ahlaknā","translation_bn":"আমরা ধ্বংস করেছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34254,"position":5,"text_uthmani":"قَبْلَهُم","transliteration":"qablahum","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":34255,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34256,"position":7,"text_uthmani":"ٱلْقُرُونِ","transliteration":"l-qurūni","translation_bn":"মানবগোষ্ঠীর","root":"قرن","lemma":"قَرْن","grammar_bn":"শব্দ"},{"id":34257,"position":8,"text_uthmani":"أَنَّهُمْ","transliteration":"annahum","translation_bn":"তারা যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":34258,"position":9,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"তাদের মধ্যে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34259,"position":10,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":34260,"position":11,"text_uthmani":"يَرْجِعُونَ","transliteration":"yarjiʿūna","translation_bn":"ফিরে আসবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34261,"position":12,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'alam yaraw kam ahlaknā qablahum mina l-qurūni annahum ilayhim lā yarjiʿūna', 'তারা কি দেখে না যে, তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করে দিয়েছি? তারা তাদের কাছে ফিরে আসবে না।', 'Have they not considered how many generations We destroyed before them - that they to them will not return?', 'তারা কি দেখে না যে, তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করে দিয়েছি? তারা তাদের কাছে ফিরে আসবে না।', 'Have they not considered how many generations We destroyed before them - that they to them will not return?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036031.mp3', now()),
  (36, 32, '', '[{"id":35113,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং নি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35114,"position":2,"text_uthmani":"كُلٌّۭ","transliteration":"kullun","translation_bn":"কেউ (এমন)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":35115,"position":3,"text_uthmani":"لَّمَّا","transliteration":"lammā","translation_bn":"এছাড়া","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":35116,"position":4,"text_uthmani":"جَمِيعٌۭ","transliteration":"jamīʿun","translation_bn":"সকলকেই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":35117,"position":5,"text_uthmani":"لَّدَيْنَا","transliteration":"ladaynā","translation_bn":"আমাদের কাছে","root":"—","lemma":"لَدَي\r","grammar_bn":"স্থানবাচক (Location)"},{"id":35118,"position":6,"text_uthmani":"مُحْضَرُونَ","transliteration":"muḥ''ḍarūna","translation_bn":"উপস্থিত করা হবে","root":"حضر","lemma":"مُّحْضَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":35119,"position":7,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in kullun lammā jamīʿun ladaynā muḥ''ḍarūna', 'তাদের সব্বাইকে একত্রে আমার কাছে হাজির করা হবে।', 'And indeed, all of them will yet be brought present before Us.', 'তাদের সব্বাইকে একত্রে আমার কাছে হাজির করা হবে।', 'And indeed, all of them will yet be brought present before Us.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036032.mp3', now()),
  (36, 33, '', '[{"id":35972,"position":1,"text_uthmani":"وَءَايَةٌۭ","transliteration":"waāyatun","translation_bn":"এবং (অন্যতম) নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35973,"position":2,"text_uthmani":"لَّهُمُ","transliteration":"lahumu","translation_bn":"তাদের জন্য (রয়েছে)","root":"—","lemma":"لَّهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":35974,"position":3,"text_uthmani":"ٱلْأَرْضُ","transliteration":"l-arḍu","translation_bn":"মাটি","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":35975,"position":4,"text_uthmani":"ٱلْمَيْتَةُ","transliteration":"l-maytatu","translation_bn":"নিষ্প্রাণ","root":"موت","lemma":"مَيْتَة","grammar_bn":"শব্দ"},{"id":35976,"position":5,"text_uthmani":"أَحْيَيْنَـٰهَا","transliteration":"aḥyaynāhā","translation_bn":"তাকে আমরা জীবিত করি","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":35977,"position":6,"text_uthmani":"وَأَخْرَجْنَا","transliteration":"wa-akhrajnā","translation_bn":"ও আমরা উৎপন্ন করি","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35978,"position":7,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35979,"position":8,"text_uthmani":"حَبًّۭا","transliteration":"ḥabban","translation_bn":"শস্যদানা","root":"حبب","lemma":"حَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":35980,"position":9,"text_uthmani":"فَمِنْهُ","transliteration":"famin''hu","translation_bn":"অতঃপর তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35981,"position":10,"text_uthmani":"يَأْكُلُونَ","transliteration":"yakulūna","translation_bn":"তারা খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35982,"position":11,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'waāyatun lahumu l-arḍu l-maytatu aḥyaynāhā wa-akhrajnā min''hā ḥabban famin''hu yakulūna', 'মৃত যমীন তাদের জন্য একটা নিদর্শন। তাকে আমি জীবিত করি আর তা থেকে আমি উৎপন্ন করি শস্য যা থেকে তারা খায়।', 'And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat.', 'মৃত যমীন তাদের জন্য একটা নিদর্শন। তাকে আমি জীবিত করি আর তা থেকে আমি উৎপন্ন করি শস্য যা থেকে তারা খায়।', 'And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036033.mp3', now()),
  (36, 34, '', '[{"id":36725,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36726,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36727,"position":3,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"বাগানসমূহ","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":36728,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36729,"position":5,"text_uthmani":"نَّخِيلٍۢ","transliteration":"nakhīlin","translation_bn":"খেজুরের","root":"نخل","lemma":"نَّخِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":36730,"position":6,"text_uthmani":"وَأَعْنَـٰبٍۢ","transliteration":"wa-aʿnābin","translation_bn":"ও আঙ্গুরের","root":"عنب","lemma":"عِنَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36731,"position":7,"text_uthmani":"وَفَجَّرْنَا","transliteration":"wafajjarnā","translation_bn":"এবং আমরা বইয়ে দিয়েছি","root":"فجر","lemma":"فُجِّرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36732,"position":8,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36733,"position":9,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36734,"position":10,"text_uthmani":"ٱلْعُيُونِ","transliteration":"l-ʿuyūni","translation_bn":"ঝর্ণা সমূহ","root":"عين","lemma":"عَيْن","grammar_bn":"শব্দ"},{"id":36735,"position":11,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā fīhā jannātin min nakhīlin wa-aʿnābin wafajjarnā fīhā mina l-ʿuyūni', 'আর আমি তাতে খেজুর ও আঙ্গুরের বাগান তৈরি করি, আর তাতে প্রবাহিত করি ঝর্ণাধারা।', 'And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -', 'আর আমি তাতে খেজুর ও আঙ্গুরের বাগান তৈরি করি, আর তাতে প্রবাহিত করি ঝর্ণাধারা।', 'And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036034.mp3', now()),
  (36, 35, '', '[{"id":37639,"position":1,"text_uthmani":"لِيَأْكُلُوا۟","transliteration":"liyakulū","translation_bn":"তারা খেতে পারে যেন","root":"اكل","lemma":"أَكَلَ","grammar_bn":"শব্দ"},{"id":37640,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37641,"position":3,"text_uthmani":"ثَمَرِهِۦ","transliteration":"thamarihi","translation_bn":"তার ফলমূল","root":"ثمر","lemma":"ثَمَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":37642,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"অথচ নি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37643,"position":5,"text_uthmani":"عَمِلَتْهُ","transliteration":"ʿamilathu","translation_bn":"তা সৃষ্টি করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37644,"position":6,"text_uthmani":"أَيْدِيهِمْ ۖ","transliteration":"aydīhim","translation_bn":"তাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":37646,"position":7,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবুও কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":37647,"position":8,"text_uthmani":"يَشْكُرُونَ","transliteration":"yashkurūna","translation_bn":"তারা কৃতজ্ঞতা প্রকাশ করে","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37648,"position":9,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'liyakulū min thamarihi wamā ʿamilathu aydīhim afalā yashkurūna', 'যাতে তারা তার ফল খেতে পারে- যা তারা তাদের হাত দিয়ে বানায়নি। তাহলে কেন তারা কৃতজ্ঞতা প্রকাশ করে না?', 'That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?', 'যাতে তারা তার ফল খেতে পারে- যা তারা তাদের হাত দিয়ে বানায়নি। তাহলে কেন তারা কৃতজ্ঞতা প্রকাশ করে না?', 'That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036035.mp3', now()),
  (36, 36, '', '[{"id":38514,"position":1,"text_uthmani":"سُبْحَـٰنَ","transliteration":"sub''ḥāna","translation_bn":"(আল্লাহ) মহান পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":38515,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":38516,"position":3,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38517,"position":4,"text_uthmani":"ٱلْأَزْوَٰجَ","transliteration":"l-azwāja","translation_bn":"জোড়া জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"শব্দ"},{"id":38518,"position":5,"text_uthmani":"كُلَّهَا","transliteration":"kullahā","translation_bn":"সব কিছুকেই","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":38519,"position":6,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38520,"position":7,"text_uthmani":"تُنۢبِتُ","transliteration":"tunbitu","translation_bn":"উৎপন্ন করে","root":"نبت","lemma":"أَن[بَتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38521,"position":8,"text_uthmani":"ٱلْأَرْضُ","transliteration":"l-arḍu","translation_bn":"ভূমি","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":38522,"position":9,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38523,"position":10,"text_uthmani":"أَنفُسِهِمْ","transliteration":"anfusihim","translation_bn":"তাদের নিজেদের (মানব জাতিরও)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":38524,"position":11,"text_uthmani":"وَمِمَّا","transliteration":"wamimmā","translation_bn":"এবং তাহ''তেও যা","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38525,"position":12,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":38526,"position":13,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"(এখনও) তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38527,"position":14,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'sub''ḥāna alladhī khalaqa l-azwāja kullahā mimmā tunbitu l-arḍu wamin anfusihim wamimmā lā yaʿlamūna', 'পূত পবিত্র সেই সত্তা যিনি জোড়া সৃষ্টি করেছেন প্রত্যেকটির যা উৎপন্ন করে যমীন, আর তাদের নিজেদের ভিতরেও আর সে সবেও যা তারা জানে না।', 'Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.', 'পূত পবিত্র সেই সত্তা যিনি জোড়া সৃষ্টি করেছেন প্রত্যেকটির যা উৎপন্ন করে যমীন, আর তাদের নিজেদের ভিতরেও আর সে সবেও যা তারা জানে না।', 'Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036036.mp3', now()),
  (36, 37, '', '[{"id":39386,"position":1,"text_uthmani":"وَءَايَةٌۭ","transliteration":"waāyatun","translation_bn":"এবং (আরো) একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39387,"position":2,"text_uthmani":"لَّهُمُ","transliteration":"lahumu","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَّهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":39388,"position":3,"text_uthmani":"ٱلَّيْلُ","transliteration":"al-laylu","translation_bn":"রাত","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":39389,"position":4,"text_uthmani":"نَسْلَخُ","transliteration":"naslakhu","translation_bn":"সরিয়ে দিই আমরা","root":"سلخ","lemma":"نَسْلَخُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39390,"position":5,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39391,"position":6,"text_uthmani":"ٱلنَّهَارَ","transliteration":"l-nahāra","translation_bn":"দিনকে","root":"نهر","lemma":"نَهَار","grammar_bn":"শব্দ"},{"id":39392,"position":7,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর তখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":39393,"position":8,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":39394,"position":9,"text_uthmani":"مُّظْلِمُونَ","transliteration":"muẓ''limūna","translation_bn":"অন্ধকারাচ্ছন্ন (হয়ে যায়)","root":"ظلم","lemma":"مُظْلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":39395,"position":10,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'waāyatun lahumu al-laylu naslakhu min''hu l-nahāra fa-idhā hum muẓ''limūna', 'তাদের জন্য একটি নিদর্শন হচ্ছে রাত, তাত্থেকে আমি দিনকে সরিয়ে নেই, ফলে তখনই তারা অন্ধকারে ডুবে যায়।', 'And a sign for them is the night. We remove from it [the light of] day, so they are [left] in darkness.', 'তাদের জন্য একটি নিদর্শন হচ্ছে রাত, তাত্থেকে আমি দিনকে সরিয়ে নেই, ফলে তখনই তারা অন্ধকারে ডুবে যায়।', 'And a sign for them is the night. We remove from it [the light of] day, so they are [left] in darkness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036037.mp3', now()),
  (36, 38, '', '[{"id":40071,"position":1,"text_uthmani":"وَٱلشَّمْسُ","transliteration":"wal-shamsu","translation_bn":"এবং সূর্য","root":"شمس","lemma":"شَمْس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40072,"position":2,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"আবর্তন করে","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40073,"position":3,"text_uthmani":"لِمُسْتَقَرٍّۢ","transliteration":"limus''taqarrin","translation_bn":"নির্দিষ্ট গন্ডির মধ্যে","root":"قرر","lemma":"مُسْتَقَرّ","grammar_bn":"অব্যয় (Preposition)"},{"id":40074,"position":4,"text_uthmani":"لَّهَا ۚ","transliteration":"lahā","translation_bn":"তার","root":"—","lemma":"لَّهَا ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":40076,"position":5,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":40077,"position":6,"text_uthmani":"تَقْدِيرُ","transliteration":"taqdīru","translation_bn":"নির্দিষ্ট (হিসাব)","root":"قدر","lemma":"تَقْدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":40078,"position":7,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"পরাক্রমশালীর","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":40079,"position":8,"text_uthmani":"ٱلْعَلِيمِ","transliteration":"l-ʿalīmi","translation_bn":"(যিনি) সুবিজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":40080,"position":9,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'wal-shamsu tajrī limus''taqarrin lahā dhālika taqdīru l-ʿazīzi l-ʿalīmi', 'আর সূর্য তার জন্যে নির্দিষ্ট ক’রে দেয়া জায়গায় গতিশীল, এটা মহা পরাক্রমশালী সর্বজ্ঞের সুনিরূপিত নির্ধারণ।', 'And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.', 'আর সূর্য তার জন্যে নির্দিষ্ট ক’রে দেয়া জায়গায় গতিশীল, এটা মহা পরাক্রমশালী সর্বজ্ঞের সুনিরূপিত নির্ধারণ।', 'And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036038.mp3', now()),
  (36, 39, '', '[{"id":40880,"position":1,"text_uthmani":"وَٱلْقَمَرَ","transliteration":"wal-qamara","translation_bn":"এবং চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40881,"position":2,"text_uthmani":"قَدَّرْنَـٰهُ","transliteration":"qaddarnāhu","translation_bn":"তার আমরা নির্দিষ্ট করেছি","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40882,"position":3,"text_uthmani":"مَنَازِلَ","transliteration":"manāzila","translation_bn":"বিভিন্ন কক্ষপথ (যার উপর চলে)","root":"نزل","lemma":"مَنَازِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":40883,"position":4,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"অবশেষে","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40884,"position":5,"text_uthmani":"عَادَ","transliteration":"ʿāda","translation_bn":"সে ফিরে আসে","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40885,"position":6,"text_uthmani":"كَٱلْعُرْجُونِ","transliteration":"kal-ʿur''jūni","translation_bn":"খেজুর শাখার মতো","root":"عرجن","lemma":"عُرْجُون","grammar_bn":"অব্যয় (Preposition)"},{"id":40886,"position":7,"text_uthmani":"ٱلْقَدِيمِ","transliteration":"l-qadīmi","translation_bn":"(এমন যা শুষ্ক) পুরান","root":"قدم","lemma":"قَدِيم","grammar_bn":"শব্দ"},{"id":40887,"position":8,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'wal-qamara qaddarnāhu manāzila ḥattā ʿāda kal-ʿur''jūni l-qadīmi', 'আর চাঁদ-তার জন্য আমি নির্দিষ্ট করেছি বিভিন্ন মান্যিল (যা সে অতিক্রম করে), এমনকি শেষ পর্যন্ত সেটি খেজুরের কাঁদির পুরানো শুকনো দন্ডের মত হয়ে ফিরে আসে।', 'And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.', 'আর চাঁদ-তার জন্য আমি নির্দিষ্ট করেছি বিভিন্ন মান্যিল (যা সে অতিক্রম করে), এমনকি শেষ পর্যন্ত সেটি খেজুরের কাঁদির পুরানো শুকনো দন্ডের মত হয়ে ফিরে আসে।', 'And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036039.mp3', now()),
