  (36, 59, '', '[{"id":54137,"position":1,"text_uthmani":"وَٱمْتَـٰزُوا۟","transliteration":"wa-im''tāzū","translation_bn":"\"এবং (বলা হবে) তোমারা আলাদা হয়ে যাও","root":"ميز","lemma":"ٱمْتَٰزُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54138,"position":2,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":54139,"position":3,"text_uthmani":"أَيُّهَا","transliteration":"ayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":54140,"position":4,"text_uthmani":"ٱلْمُجْرِمُونَ","transliteration":"l-muj''rimūna","translation_bn":"অপরাধীরা","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":54141,"position":5,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-im''tāzū l-yawma ayyuhā l-muj''rimūna', '(সে দিন বলা হবে) ‘হে অপরাধীরা! আজ তোমরা আলাদা হয়ে যাও।’', '[Then He will say], "But stand apart today, you criminals.', '(সে দিন বলা হবে) ‘হে অপরাধীরা! আজ তোমরা আলাদা হয়ে যাও।’', '[Then He will say], "But stand apart today, you criminals.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036059.mp3', now()),
  (36, 60, '', '[{"id":54448,"position":1,"text_uthmani":"۞ أَلَمْ","transliteration":"alam","translation_bn":"দিই নি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":54449,"position":2,"text_uthmani":"أَعْهَدْ","transliteration":"aʿhad","translation_bn":"আমি নির্দেশ","root":"عهد","lemma":"عَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54450,"position":3,"text_uthmani":"إِلَيْكُمْ","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":54451,"position":4,"text_uthmani":"يَـٰبَنِىٓ","transliteration":"yābanī","translation_bn":"হে সন্তান","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":54452,"position":5,"text_uthmani":"ءَادَمَ","transliteration":"ādama","translation_bn":"আদমের","root":"—","lemma":"ا^دَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":54453,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":54454,"position":7,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":54455,"position":8,"text_uthmani":"تَعْبُدُوا۟","transliteration":"taʿbudū","translation_bn":"তোমরা দাসত্ব করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54456,"position":9,"text_uthmani":"ٱلشَّيْطَـٰنَ ۖ","transliteration":"l-shayṭāna","translation_bn":"শয়তানের","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":54458,"position":10,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"সে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":54459,"position":11,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":54460,"position":12,"text_uthmani":"عَدُوٌّۭ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":54461,"position":13,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"প্রকাশ্য","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":54462,"position":14,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'alam aʿhad ilaykum yābanī ādama an lā taʿbudū l-shayṭāna innahu lakum ʿaduwwun mubīnun', '‘হে আদাম সন্তান! আমি কি তোমাদেরকে নির্দেশ দেইনি যে, তোমরা শয়ত্বানের ‘ইবাদাত করো না, কারণ সে তোমাদের প্রকাশ্য দুশমন?', 'Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -', '‘হে আদাম সন্তান! আমি কি তোমাদেরকে নির্দেশ দেইনি যে, তোমরা শয়ত্বানের ‘ইবাদাত করো না, কারণ সে তোমাদের প্রকাশ্য দুশমন?', 'Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036060.mp3', now()),
  (36, 61, '', '[{"id":55338,"position":1,"text_uthmani":"وَأَنِ","transliteration":"wa-ani","translation_bn":"এবং (এও) যে","root":"—","lemma":"أَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55339,"position":2,"text_uthmani":"ٱعْبُدُونِى ۚ","transliteration":"uʿ''budūnī","translation_bn":"আমারই তোমরা ইবাদত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55341,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটাই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":55342,"position":4,"text_uthmani":"صِرَٰطٌۭ","transliteration":"ṣirāṭun","translation_bn":"পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":55343,"position":5,"text_uthmani":"مُّسْتَقِيمٌۭ","transliteration":"mus''taqīmun","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":55344,"position":6,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ani uʿ''budūnī hādhā ṣirāṭun mus''taqīmun', 'আর আমারই ‘ইবাদাত কর, এটাই সরল সঠিক পথ।', 'And that you worship [only] Me? This is a straight path.', 'আর আমারই ‘ইবাদাত কর, এটাই সরল সঠিক পথ।', 'And that you worship [only] Me? This is a straight path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036061.mp3', now()),
  (36, 62, '', '[{"id":55858,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং (এ সত্ত্বেও) নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55859,"position":2,"text_uthmani":"أَضَلَّ","transliteration":"aḍalla","translation_bn":"সে পথ ভ্রষ্ট করেছে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55860,"position":3,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55861,"position":4,"text_uthmani":"جِبِلًّۭا","transliteration":"jibillan","translation_bn":"বড় দলকে","root":"جبل","lemma":"جِبِلَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":55862,"position":5,"text_uthmani":"كَثِيرًا ۖ","transliteration":"kathīran","translation_bn":"অনেক","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":55864,"position":6,"text_uthmani":"أَفَلَمْ","transliteration":"afalam","translation_bn":"তবুও কি না","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":55865,"position":7,"text_uthmani":"تَكُونُوا۟","transliteration":"takūnū","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55866,"position":8,"text_uthmani":"تَعْقِلُونَ","transliteration":"taʿqilūna","translation_bn":"তোমরা বুঝতে","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55867,"position":9,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad aḍalla minkum jibillan kathīran afalam takūnū taʿqilūna', '(কিন্তু তোমাদেরকে সতর্ক করে দেয়া সত্ত্বেও) শয়ত্বান তোমাদের বহু দলকে বিভ্রান্ত করে দিয়েছে, তবুও কি তোমরা বুঝ না?', 'And he had already led astray from among you much of creation, so did you not use reason?', '(কিন্তু তোমাদেরকে সতর্ক করে দেয়া সত্ত্বেও) শয়ত্বান তোমাদের বহু দলকে বিভ্রান্ত করে দিয়েছে, তবুও কি তোমরা বুঝ না?', 'And he had already led astray from among you much of creation, so did you not use reason?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036062.mp3', now()),
  (36, 63, '', '[{"id":56417,"position":1,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"এই সেই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":56418,"position":2,"text_uthmani":"جَهَنَّمُ","transliteration":"jahannamu","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":56419,"position":3,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":56420,"position":4,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমাদের","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56421,"position":5,"text_uthmani":"تُوعَدُونَ","transliteration":"tūʿadūna","translation_bn":"প্রতিশ্রুতি দেয়া হয়েছিলো","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56422,"position":6,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'hādhihi jahannamu allatī kuntum tūʿadūna', 'এটা সেই জাহান্নাম যে বিষয়ে তোমাদেরকে ভয় দেখানো হয়েছিল।', 'This is the Hellfire which you were promised.', 'এটা সেই জাহান্নাম যে বিষয়ে তোমাদেরকে ভয় দেখানো হয়েছিল।', 'This is the Hellfire which you were promised.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036063.mp3', now()),
  (36, 64, '', '[{"id":56645,"position":1,"text_uthmani":"ٱصْلَوْهَا","transliteration":"iṣ''lawhā","translation_bn":"তাতে তোমরা প্রবেশ করো","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":56646,"position":2,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":56647,"position":3,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"বিনিময়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56648,"position":4,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56649,"position":5,"text_uthmani":"تَكْفُرُونَ","transliteration":"takfurūna","translation_bn":"অস্বীকার করছিলে\"","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56650,"position":6,"text_uthmani":"٦٤","transliteration":"","translation_bn":"(৬৪)","root":"—","lemma":"٦٤","grammar_bn":"মার্কার"}]'::jsonb, 'iṣ''lawhā l-yawma bimā kuntum takfurūna', 'আজ তাতে প্রবেশ কর, কেননা তোমরা এটাকে অবিশ্বাস করেছিলে।’', '[Enter to] burn therein today for what you used to deny."', 'আজ তাতে প্রবেশ কর, কেননা তোমরা এটাকে অবিশ্বাস করেছিলে।’', '[Enter to] burn therein today for what you used to deny."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036064.mp3', now()),
  (36, 65, '', '[{"id":57166,"position":1,"text_uthmani":"ٱلْيَوْمَ","transliteration":"al-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":57167,"position":2,"text_uthmani":"نَخْتِمُ","transliteration":"nakhtimu","translation_bn":"সীল করে দিবো আমরা","root":"ختم","lemma":"خَتَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57168,"position":3,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57169,"position":4,"text_uthmani":"أَفْوَٰهِهِمْ","transliteration":"afwāhihim","translation_bn":"তাদের মুখগুলোর","root":"فوه","lemma":"أَفْوَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":57170,"position":5,"text_uthmani":"وَتُكَلِّمُنَآ","transliteration":"watukallimunā","translation_bn":"এবং আমাদের সাথে কথা বলবে","root":"كلم","lemma":"كَلَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57171,"position":6,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"তাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":57172,"position":7,"text_uthmani":"وَتَشْهَدُ","transliteration":"watashhadu","translation_bn":"এবং সাক্ষ্য দিবে","root":"شهد","lemma":"شَهِدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57173,"position":8,"text_uthmani":"أَرْجُلُهُم","transliteration":"arjuluhum","translation_bn":"তাদের পাগুলো","root":"رجل","lemma":"رِجْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":57174,"position":9,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57175,"position":10,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"করেছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57176,"position":11,"text_uthmani":"يَكْسِبُونَ","transliteration":"yaksibūna","translation_bn":"তারা কামাই","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57177,"position":12,"text_uthmani":"٦٥","transliteration":"","translation_bn":"(৬৫)","root":"—","lemma":"٦٥","grammar_bn":"মার্কার"}]'::jsonb, 'al-yawma nakhtimu ʿalā afwāhihim watukallimunā aydīhim watashhadu arjuluhum bimā kānū yaksibūna', 'আজ আমি তাদের মুখে সীল মোহর লাগিয়ে দেব, তাদের হাত আমার সঙ্গে কথা বলবে, আর তারা যা করত সে সম্পর্কে তাদের পাগুলো সাক্ষ্য দেবে।', 'That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn.', 'আজ আমি তাদের মুখে সীল মোহর লাগিয়ে দেব, তাদের হাত আমার সঙ্গে কথা বলবে, আর তারা যা করত সে সম্পর্কে তাদের পাগুলো সাক্ষ্য দেবে।', 'That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036065.mp3', now()),
  (36, 66, '', '[{"id":57692,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":57693,"position":2,"text_uthmani":"نَشَآءُ","transliteration":"nashāu","translation_bn":"চাই আমরা","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57694,"position":3,"text_uthmani":"لَطَمَسْنَا","transliteration":"laṭamasnā","translation_bn":"দিতে পারি অবশ্যই","root":"طمس","lemma":"طُمِسَتْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":57695,"position":4,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"আমরা আলো নিভিয়ে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":57696,"position":5,"text_uthmani":"أَعْيُنِهِمْ","transliteration":"aʿyunihim","translation_bn":"তাদের চোখের","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":57697,"position":6,"text_uthmani":"فَٱسْتَبَقُوا۟","transliteration":"fa-is''tabaqū","translation_bn":"তারা অতঃপর চলতে চাইতো","root":"سبق","lemma":"ٱسْتَبَقَ","grammar_bn":"শব্দ"},{"id":57698,"position":7,"text_uthmani":"ٱلصِّرَٰطَ","transliteration":"l-ṣirāṭa","translation_bn":"পথে","root":"صرط","lemma":"صِرَٰط","grammar_bn":"শব্দ"},{"id":57699,"position":8,"text_uthmani":"فَأَنَّىٰ","transliteration":"fa-annā","translation_bn":"তখন কেমন করে","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"শব্দ"},{"id":57700,"position":9,"text_uthmani":"يُبْصِرُونَ","transliteration":"yub''ṣirūna","translation_bn":"তারা দেখতে পাবে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":57701,"position":10,"text_uthmani":"٦٦","transliteration":"","translation_bn":"(৬৬)","root":"—","lemma":"٦٦","grammar_bn":"মার্কার"}]'::jsonb, 'walaw nashāu laṭamasnā ʿalā aʿyunihim fa-is''tabaqū l-ṣirāṭa fa-annā yub''ṣirūna', 'আমি ইচ্ছে করলে তাদের দৃষ্টিশক্তি বিলুপ্ত করে দিতাম। তখন তারা পথের দিকে দৌঁড়ে দেখতে চাইলে কীভাবে তারা দেখতে পেত?', 'And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?', 'আমি ইচ্ছে করলে তাদের দৃষ্টিশক্তি বিলুপ্ত করে দিতাম। তখন তারা পথের দিকে দৌঁড়ে দেখতে চাইলে কীভাবে তারা দেখতে পেত?', 'And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036066.mp3', now()),
  (36, 67, '', '[{"id":58055,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":58056,"position":2,"text_uthmani":"نَشَآءُ","transliteration":"nashāu","translation_bn":"চাই আমরা","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58057,"position":3,"text_uthmani":"لَمَسَخْنَـٰهُمْ","transliteration":"lamasakhnāhum","translation_bn":"তাদেরকে আমরা অবশ্যই বিকৃত করে দিতে পারি","root":"مسخ","lemma":"مَسَخْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":58058,"position":4,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":58059,"position":5,"text_uthmani":"مَكَانَتِهِمْ","transliteration":"makānatihim","translation_bn":"তাদের (নিজ নিজ) অবস্থানেই","root":"كون","lemma":"مَكَانَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":58060,"position":6,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":58061,"position":7,"text_uthmani":"ٱسْتَطَـٰعُوا۟","transliteration":"is''taṭāʿū","translation_bn":"তারা সমর্থ হবে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58062,"position":8,"text_uthmani":"مُضِيًّۭا","transliteration":"muḍiyyan","translation_bn":"আগে যেতে","root":"مضي","lemma":"مُضِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":58063,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":58064,"position":10,"text_uthmani":"يَرْجِعُونَ","transliteration":"yarjiʿūna","translation_bn":"পিছনে ফিরতে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58065,"position":11,"text_uthmani":"٦٧","transliteration":"","translation_bn":"(৬৭)","root":"—","lemma":"٦٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaw nashāu lamasakhnāhum ʿalā makānatihim famā is''taṭāʿū muḍiyyan walā yarjiʿūna', 'আমি ইচ্ছে করলে তাদের নিজ নিজ জায়গাতেই তাদের আকৃতি পরিবর্তন করে দিতাম, তখন তারা না সামনের দিকে চলতে পারত, আর না পারত পেছনে ফিরে যেতে।', 'And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return.', 'আমি ইচ্ছে করলে তাদের নিজ নিজ জায়গাতেই তাদের আকৃতি পরিবর্তন করে দিতাম, তখন তারা না সামনের দিকে চলতে পারত, আর না পারত পেছনে ফিরে যেতে।', 'And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036067.mp3', now()),
  (36, 68, '', '[{"id":58816,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং কোনো ব্যক্তি","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":58817,"position":2,"text_uthmani":"نُّعَمِّرْهُ","transliteration":"nuʿammir''hu","translation_bn":"যাকে দীর্ঘায়ু দিই আমরা","root":"عمر","lemma":"يُعَمَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58818,"position":3,"text_uthmani":"نُنَكِّسْهُ","transliteration":"nunakkis''hu","translation_bn":"উল্টিয়ে দিই আমরা তার","root":"نكس","lemma":"نُنَكِّسْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58819,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":58820,"position":5,"text_uthmani":"ٱلْخَلْقِ ۖ","transliteration":"l-khalqi","translation_bn":"আকৃতি-প্রকৃতির (বুদ্ধি ও যোগ্যতার)","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":58822,"position":6,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবুও কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":58823,"position":7,"text_uthmani":"يَعْقِلُونَ","transliteration":"yaʿqilūna","translation_bn":"তারা জ্ঞানবুদ্ধি কাজে লাগায়","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":58824,"position":8,"text_uthmani":"٦٨","transliteration":"","translation_bn":"(৬৮)","root":"—","lemma":"٦٨","grammar_bn":"মার্কার"}]'::jsonb, 'waman nuʿammir''hu nunakkis''hu fī l-khalqi afalā yaʿqilūna', 'আমি যাকে দীর্ঘ জীবন দেই, তাকে সৃষ্টির ক্ষেত্রে পূর্বের অবস্থায় ফিরিয়ে আনি। তবুও কি তারা বুঝে না?', 'And he to whom We grant long life We reverse in creation; so will they not understand?', 'আমি যাকে দীর্ঘ জীবন দেই, তাকে সৃষ্টির ক্ষেত্রে পূর্বের অবস্থায় ফিরিয়ে আনি। তবুও কি তারা বুঝে না?', 'And he to whom We grant long life We reverse in creation; so will they not understand?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036068.mp3', now()),
  (36, 69, '', '[{"id":59315,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59316,"position":2,"text_uthmani":"عَلَّمْنَـٰهُ","transliteration":"ʿallamnāhu","translation_bn":"তাকে আমরা শিখিয়েছি","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59317,"position":3,"text_uthmani":"ٱلشِّعْرَ","transliteration":"l-shiʿ''ra","translation_bn":"কবিতা","root":"شعر","lemma":"شِّعْر","grammar_bn":"শব্দ"},{"id":59318,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59319,"position":5,"text_uthmani":"يَنۢبَغِى","transliteration":"yanbaghī","translation_bn":"শোভা পায় (এটা)","root":"بغي","lemma":"يَن[بَغِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":59320,"position":6,"text_uthmani":"لَهُۥٓ ۚ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥٓ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":59322,"position":7,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":59323,"position":8,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":59324,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":59325,"position":10,"text_uthmani":"ذِكْرٌۭ","transliteration":"dhik''run","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":59326,"position":11,"text_uthmani":"وَقُرْءَانٌۭ","transliteration":"waqur''ānun","translation_bn":"ও (পাঠযোগ্য কিতাব) কোরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59327,"position":12,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":59328,"position":13,"text_uthmani":"٦٩","transliteration":"","translation_bn":"(৬৯)","root":"—","lemma":"٦٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamā ʿallamnāhu l-shiʿ''ra wamā yanbaghī lahu in huwa illā dhik''run waqur''ānun mubīnun', '[কাফিররা রসূল (সা.)-কে উদ্দেশ্য করে বলে, লোকটা একটা কবি। কিন্তু) আমি রসূলকে কবিতা শিখাইনি, আর তা তার জন্য শোভনীয়ও নয়। তাতো এক উপদেশ ও স্পষ্ট কুরআন ব্যতীত অন্য কিছু নয়।', 'And We did not give Prophet Muhammad, knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur''an', '[কাফিররা রসূল (সা.)-কে উদ্দেশ্য করে বলে, লোকটা একটা কবি। কিন্তু) আমি রসূলকে কবিতা শিখাইনি, আর তা তার জন্য শোভনীয়ও নয়। তাতো এক উপদেশ ও স্পষ্ট কুরআন ব্যতীত অন্য কিছু নয়।', 'And We did not give Prophet Muhammad, knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur''an', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036069.mp3', now()),
  (36, 70, '', '[{"id":59753,"position":1,"text_uthmani":"لِّيُنذِرَ","transliteration":"liyundhira","translation_bn":"সতর্ক করে যেন","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":59754,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(এমন প্রত্যেককে) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":59755,"position":3,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59756,"position":4,"text_uthmani":"حَيًّۭا","transliteration":"ḥayyan","translation_bn":"জীবিত","root":"حيي","lemma":"حَيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":59757,"position":5,"text_uthmani":"وَيَحِقَّ","transliteration":"wayaḥiqqa","translation_bn":"এবং প্রতিষ্ঠিত হতে পারে (যেন)","root":"حقق","lemma":"حَقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":59758,"position":6,"text_uthmani":"ٱلْقَوْلُ","transliteration":"l-qawlu","translation_bn":"(শাস্তির) বাণী","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":59759,"position":7,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59760,"position":8,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফিরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":59761,"position":9,"text_uthmani":"٧٠","transliteration":"","translation_bn":"(৭০)","root":"—","lemma":"٧٠","grammar_bn":"মার্কার"}]'::jsonb, 'liyundhira man kāna ḥayyan wayaḥiqqa l-qawlu ʿalā l-kāfirīna', 'যাতে সে (আত্মিকভাবে) জীবিতকে সতর্ক করতে পারে আর কাফিরদের বিরুদ্ধে অকাট্য দলীল হতে পারে।', 'To warn whoever is alive and justify the word against the disbelievers.', 'যাতে সে (আত্মিকভাবে) জীবিতকে সতর্ক করতে পারে আর কাফিরদের বিরুদ্ধে অকাট্য দলীল হতে পারে।', 'To warn whoever is alive and justify the word against the disbelievers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036070.mp3', now()),
  (36, 71, '', '[{"id":59964,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"নি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":59965,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা দেখে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":59966,"position":3,"text_uthmani":"أَنَّا","transliteration":"annā","translation_bn":"যে আমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":59967,"position":4,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59968,"position":5,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":59969,"position":6,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"সেসব থেকে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59970,"position":7,"text_uthmani":"عَمِلَتْ","transliteration":"ʿamilat","translation_bn":"সৃষ্টি করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":59971,"position":8,"text_uthmani":"أَيْدِينَآ","transliteration":"aydīnā","translation_bn":"আমাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":59972,"position":9,"text_uthmani":"أَنْعَـٰمًۭا","transliteration":"anʿāman","translation_bn":"(যেমন) গবাদি পশু","root":"نعم","lemma":"نَّعَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":59973,"position":10,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"এখন তারাই","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":59974,"position":11,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"সেগুলোর","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":59975,"position":12,"text_uthmani":"مَـٰلِكُونَ","transliteration":"mālikūna","translation_bn":"মালিক","root":"ملك","lemma":"مَٰلِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":59976,"position":13,"text_uthmani":"٧١","transliteration":"","translation_bn":"(৭১)","root":"—","lemma":"٧١","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yaraw annā khalaqnā lahum mimmā ʿamilat aydīnā anʿāman fahum lahā mālikūna', 'তারা কি দেখে না যে আমার হাতে তৈরি জিনিসগুলোর মধ্যে আমি তাদের জন্য সৃষ্টি করেছি গৃহপালিত পশু আর এখন তারা এগুলোর মালিক!', 'Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?', 'তারা কি দেখে না যে আমার হাতে তৈরি জিনিসগুলোর মধ্যে আমি তাদের জন্য সৃষ্টি করেছি গৃহপালিত পশু আর এখন তারা এগুলোর মালিক!', 'Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036071.mp3', now()),
  (36, 72, '', '[{"id":60840,"position":1,"text_uthmani":"وَذَلَّلْنَـٰهَا","transliteration":"wadhallalnāhā","translation_bn":"এবং সেগুলোকে আমরা বশীভূত করেছি","root":"ذلل","lemma":"ذُلِّلَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60841,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":60842,"position":3,"text_uthmani":"فَمِنْهَا","transliteration":"famin''hā","translation_bn":"অতঃপর (রয়েছে) সেগুলোর কিছু কিছু","root":"—","lemma":"مِن\r","grammar_bn":"শব্দ"},{"id":60843,"position":4,"text_uthmani":"رَكُوبُهُمْ","transliteration":"rakūbuhum","translation_bn":"তাদের বাহনও (যেমন উট)","root":"ركب","lemma":"رَكُوب","grammar_bn":"বিশেষ্য (Noun)"},{"id":60844,"position":5,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"এবং সেগুলোর কিছু কিছু","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60845,"position":6,"text_uthmani":"يَأْكُلُونَ","transliteration":"yakulūna","translation_bn":"তারা আহারও করে","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60846,"position":7,"text_uthmani":"٧٢","transliteration":"","translation_bn":"(৭২)","root":"—","lemma":"٧٢","grammar_bn":"মার্কার"}]'::jsonb, 'wadhallalnāhā lahum famin''hā rakūbuhum wamin''hā yakulūna', 'আমি এগুলোকে তাদের বশীভূত করে দিয়েছি, ফলে এগুলোর কতক তাদের বাহন, আর এদের কতকগুলো তারা খায়।', 'And We have tamed them for them, so some of them they ride, and some of them they eat.', 'আমি এগুলোকে তাদের বশীভূত করে দিয়েছি, ফলে এগুলোর কতক তাদের বাহন, আর এদের কতকগুলো তারা খায়।', 'And We have tamed them for them, so some of them they ride, and some of them they eat.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036072.mp3', now()),
  (36, 73, '', '[{"id":60926,"position":1,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদের জন্যে রয়েছে","root":"—","lemma":"وَلَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60927,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"সেগুলোর মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60928,"position":3,"text_uthmani":"مَنَـٰفِعُ","transliteration":"manāfiʿu","translation_bn":"(নানা রকম) উপকার","root":"نفع","lemma":"مَنَٰفِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":60929,"position":4,"text_uthmani":"وَمَشَارِبُ ۖ","transliteration":"wamashāribu","translation_bn":"এবং (নানা প্রকার) পানীয়","root":"شرب","lemma":"مَّشْرَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60931,"position":5,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবুও কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":60932,"position":6,"text_uthmani":"يَشْكُرُونَ","transliteration":"yashkurūna","translation_bn":"তারা কৃতজ্ঞ হবে","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60933,"position":7,"text_uthmani":"٧٣","transliteration":"","translation_bn":"(৭৩)","root":"—","lemma":"٧٣","grammar_bn":"মার্কার"}]'::jsonb, 'walahum fīhā manāfiʿu wamashāribu afalā yashkurūna', 'তাদের জন্য এগুলোতে আছে বহু উপকার আর পানীয় দ্রব্য। তবুও তারা কেন শুকরিয়া আদায় করে না?', 'And for them therein are [other] benefits and drinks, so will they not be grateful?', 'তাদের জন্য এগুলোতে আছে বহু উপকার আর পানীয় দ্রব্য। তবুও তারা কেন শুকরিয়া আদায় করে না?', 'And for them therein are [other] benefits and drinks, so will they not be grateful?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036073.mp3', now()),
  (36, 74, '', '[{"id":61426,"position":1,"text_uthmani":"وَٱتَّخَذُوا۟","transliteration":"wa-ittakhadhū","translation_bn":"এবং (এ সত্ত্বেও) তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":61427,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":61428,"position":3,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":61429,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":61430,"position":5,"text_uthmani":"ءَالِهَةًۭ","transliteration":"ālihatan","translation_bn":"উপাস্যরূপে (অন্যদেরকে)","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":61431,"position":6,"text_uthmani":"لَّعَلَّهُمْ","transliteration":"laʿallahum","translation_bn":"তারা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":61432,"position":7,"text_uthmani":"يُنصَرُونَ","transliteration":"yunṣarūna","translation_bn":"তারা সাহায্য পাবে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61433,"position":8,"text_uthmani":"٧٤","transliteration":"","translation_bn":"(৭৪)","root":"—","lemma":"٧٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittakhadhū min dūni l-lahi ālihatan laʿallahum yunṣarūna', 'তারা আল্লাহর পরিবর্তে অনেক ইলাহ গ্রহণ করেছে এই আশায় যে, তারা (ঐ সব ইলাহ দ্বারা) সাহায্যপ্রাপ্ত হবে।', 'But they have taken besides Allah [false] deities that perhaps they would be helped.', 'তারা আল্লাহর পরিবর্তে অনেক ইলাহ গ্রহণ করেছে এই আশায় যে, তারা (ঐ সব ইলাহ দ্বারা) সাহায্যপ্রাপ্ত হবে।', 'But they have taken besides Allah [false] deities that perhaps they would be helped.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036074.mp3', now()),
  (36, 75, '', '[{"id":61951,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":61952,"position":2,"text_uthmani":"يَسْتَطِيعُونَ","transliteration":"yastaṭīʿūna","translation_bn":"তারা সমর্থ হবে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":61953,"position":3,"text_uthmani":"نَصْرَهُمْ","transliteration":"naṣrahum","translation_bn":"তাদের সাহায্য করতে","root":"نصر","lemma":"نَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":61954,"position":4,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"বরং তারাই (হয়ে আছে)","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":61955,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":61956,"position":6,"text_uthmani":"جُندٌۭ","transliteration":"jundun","translation_bn":"সৈন্য (রক্ষাকারী রূপে)","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":61957,"position":7,"text_uthmani":"مُّحْضَرُونَ","transliteration":"muḥ''ḍarūna","translation_bn":"সদা উপস্থিত","root":"حضر","lemma":"مُّحْضَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":61958,"position":8,"text_uthmani":"٧٥","transliteration":"","translation_bn":"(৭৫)","root":"—","lemma":"٧٥","grammar_bn":"মার্কার"}]'::jsonb, 'lā yastaṭīʿūna naṣrahum wahum lahum jundun muḥ''ḍarūna', 'ঐ সব ইলাহ তাদেরকে সাহায্য করতে সক্ষম নয়, বরং (উল্টো) এ লোকেরাই (ঐ সব ইলাহকে সাহায্য করার জন্য) সদা প্রস্তুত সেনাবাহিনীর মত হাযির হয়ে আছে।', 'They are not able to help them, and they [themselves] are for them soldiers in attendance.', 'ঐ সব ইলাহ তাদেরকে সাহায্য করতে সক্ষম নয়, বরং (উল্টো) এ লোকেরাই (ঐ সব ইলাহকে সাহায্য করার জন্য) সদা প্রস্তুত সেনাবাহিনীর মত হাযির হয়ে আছে।', 'They are not able to help them, and they [themselves] are for them soldiers in attendance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036075.mp3', now()),
  (36, 76, '', '[{"id":62457,"position":1,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"কাজেই না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":62458,"position":2,"text_uthmani":"يَحْزُنكَ","transliteration":"yaḥzunka","translation_bn":"তোমাকে দুঃখ দেয়","root":"حزن","lemma":"يَحْزُن","grammar_bn":"ক্রিয়া (Verb)"},{"id":62459,"position":3,"text_uthmani":"قَوْلُهُمْ ۘ","transliteration":"qawluhum","translation_bn":"তাদের কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":62461,"position":4,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":62462,"position":5,"text_uthmani":"نَعْلَمُ","transliteration":"naʿlamu","translation_bn":"জানি আমরা","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62463,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":62464,"position":7,"text_uthmani":"يُسِرُّونَ","transliteration":"yusirrūna","translation_bn":"তারা গোপন করে","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62465,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62466,"position":9,"text_uthmani":"يُعْلِنُونَ","transliteration":"yuʿ''linūna","translation_bn":"তারা প্রকাশ করে","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":62467,"position":10,"text_uthmani":"٧٦","transliteration":"","translation_bn":"(৭৬)","root":"—","lemma":"٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'falā yaḥzunka qawluhum innā naʿlamu mā yusirrūna wamā yuʿ''linūna', 'কাজেই তাদের কথাবার্তা তোমাকে যেন দুঃখ না দেয়; আমি জানি তারা যা গোপন করে, আর যা প্রকাশ করে।', 'So let not their speech grieve you. Indeed, We know what they conceal and what they declare.', 'কাজেই তাদের কথাবার্তা তোমাকে যেন দুঃখ না দেয়; আমি জানি তারা যা গোপন করে, আর যা প্রকাশ করে।', 'So let not their speech grieve you. Indeed, We know what they conceal and what they declare.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036076.mp3', now()),
  (36, 77, '', '[{"id":62862,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"নি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":62863,"position":2,"text_uthmani":"يَرَ","transliteration":"yara","translation_bn":"দেখে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":62864,"position":3,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":62865,"position":4,"text_uthmani":"أَنَّا","transliteration":"annā","translation_bn":"যে আমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":62866,"position":5,"text_uthmani":"خَلَقْنَـٰهُ","transliteration":"khalaqnāhu","translation_bn":"তাকে আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":62867,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62868,"position":7,"text_uthmani":"نُّطْفَةٍۢ","transliteration":"nuṭ''fatin","translation_bn":"শুক্রবিন্দু","root":"نطف","lemma":"نُّطْفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":62869,"position":8,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অথচ পরে","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":62870,"position":9,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে (হয়েছে)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":62871,"position":10,"text_uthmani":"خَصِيمٌۭ","transliteration":"khaṣīmun","translation_bn":"ঝগড়াটে","root":"خصم","lemma":"خَصِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":62872,"position":11,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"প্রকাশ্য","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":62873,"position":12,"text_uthmani":"٧٧","transliteration":"","translation_bn":"(৭৭)","root":"—","lemma":"٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yara l-insānu annā khalaqnāhu min nuṭ''fatin fa-idhā huwa khaṣīmun mubīnun', 'মানুষ কি দেখে না যে আমি তাকে সৃষ্টি করেছি শুক্রবিন্দু হতে? অতঃপর সে হয়ে গেল সুস্পষ্ট ঝগড়াটে।', 'Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?', 'মানুষ কি দেখে না যে আমি তাকে সৃষ্টি করেছি শুক্রবিন্দু হতে? অতঃপর সে হয়ে গেল সুস্পষ্ট ঝগড়াটে।', 'Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036077.mp3', now()),
  (36, 78, '', '[{"id":63505,"position":1,"text_uthmani":"وَضَرَبَ","transliteration":"waḍaraba","translation_bn":"এবং পেশ করে","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63506,"position":2,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":63507,"position":3,"text_uthmani":"مَثَلًۭا","transliteration":"mathalan","translation_bn":"উপমা","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":63508,"position":4,"text_uthmani":"وَنَسِىَ","transliteration":"wanasiya","translation_bn":"অথচ সে ভুলে যায়","root":"نسي","lemma":"نَسِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63509,"position":5,"text_uthmani":"خَلْقَهُۥ ۖ","transliteration":"khalqahu","translation_bn":"তার সৃষ্টিকে","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":63511,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63512,"position":7,"text_uthmani":"مَن","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":63513,"position":8,"text_uthmani":"يُحْىِ","transliteration":"yuḥ''yī","translation_bn":"প্রাণ দিবে","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":63514,"position":9,"text_uthmani":"ٱلْعِظَـٰمَ","transliteration":"l-ʿiẓāma","translation_bn":"হাড়ে","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":63515,"position":10,"text_uthmani":"وَهِىَ","transliteration":"wahiya","translation_bn":"যখন তা (হয়ে যাবে)","root":"—","lemma":"وَهِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":63516,"position":11,"text_uthmani":"رَمِيمٌۭ","transliteration":"ramīmun","translation_bn":"পচাগলা জরাজীর্ণ\"","root":"رمم","lemma":"رَمِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":63517,"position":12,"text_uthmani":"٧٨","transliteration":"","translation_bn":"(৭৮)","root":"—","lemma":"٧٨","grammar_bn":"মার্কার"}]'::jsonb, 'waḍaraba lanā mathalan wanasiya khalqahu qāla man yuḥ''yī l-ʿiẓāma wahiya ramīmun', 'সে (আমার সৃষ্টির সাথে) আমার তুলনা করে, অথচ সে তার নিজের সৃষ্টির ব্যপারটি ভুলে যায় (যে তাকে আমিই সৃষ্টি করেছি)। সে বলে, ‘হাড়গুলোকে কে আবার জীবন্ত করবে যখন তা পচে গলে যাবে?’’', 'And he presents for Us an example and forgets his [own] creation. He says, "Who will give life to bones while they are disintegrated?"', 'সে (আমার সৃষ্টির সাথে) আমার তুলনা করে, অথচ সে তার নিজের সৃষ্টির ব্যপারটি ভুলে যায় (যে তাকে আমিই সৃষ্টি করেছি)। সে বলে, ‘হাড়গুলোকে কে আবার জীবন্ত করবে যখন তা পচে গলে যাবে?’’', 'And he presents for Us an example and forgets his [own] creation. He says, "Who will give life to bones while they are disintegrated?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036078.mp3', now()),
  (36, 79, '', '[{"id":63978,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো (তাদেরকে)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63979,"position":2,"text_uthmani":"يُحْيِيهَا","transliteration":"yuḥ''yīhā","translation_bn":"\"তাতে প্রাণ দিবেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":63980,"position":3,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"(তিনিই) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":63981,"position":4,"text_uthmani":"أَنشَأَهَآ","transliteration":"ansha-ahā","translation_bn":"তা সৃষ্টি করেছেন","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":63982,"position":5,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":63983,"position":6,"text_uthmani":"مَرَّةٍۢ ۖ","transliteration":"marratin","translation_bn":"বার","root":"مرر","lemma":"مَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":63985,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63986,"position":8,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"সম্পর্কে সবকিছু","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":63987,"position":9,"text_uthmani":"خَلْقٍ","transliteration":"khalqin","translation_bn":"(তাঁর) সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":63988,"position":10,"text_uthmani":"عَلِيمٌ","transliteration":"ʿalīmun","translation_bn":"সম্যক অবগত\"","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":63989,"position":11,"text_uthmani":"٧٩","transliteration":"","translation_bn":"(৭৯)","root":"—","lemma":"٧٩","grammar_bn":"মার্কার"}]'::jsonb, 'qul yuḥ''yīhā alladhī ansha-ahā awwala marratin wahuwa bikulli khalqin ʿalīmun', 'বল, ‘‘তাকে তিনিই জীবন্ত করবেন যিনি ওগুলোকে প্রথমবার সৃষ্টি করেছেন, আর তিনি প্রতিটি সৃষ্টি সম্পর্কে সবচেয়ে বেশি অবগত।', 'Say, "He will give them life who produced them the first time; and He is, of all creation, Knowing."', 'বল, ‘‘তাকে তিনিই জীবন্ত করবেন যিনি ওগুলোকে প্রথমবার সৃষ্টি করেছেন, আর তিনি প্রতিটি সৃষ্টি সম্পর্কে সবচেয়ে বেশি অবগত।', 'Say, "He will give them life who produced them the first time; and He is, of all creation, Knowing."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036079.mp3', now()),
  (36, 80, '', '[{"id":64227,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":64228,"position":2,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64229,"position":3,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":64230,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":64231,"position":5,"text_uthmani":"ٱلشَّجَرِ","transliteration":"l-shajari","translation_bn":"গাছ","root":"شجر","lemma":"شَجَر","grammar_bn":"শব্দ"},{"id":64232,"position":6,"text_uthmani":"ٱلْأَخْضَرِ","transliteration":"l-akhḍari","translation_bn":"সবুজ","root":"خضر","lemma":"أَخْضَر","grammar_bn":"শব্দ"},{"id":64233,"position":7,"text_uthmani":"نَارًۭا","transliteration":"nāran","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":64234,"position":8,"text_uthmani":"فَإِذَآ","transliteration":"fa-idhā","translation_bn":"অতঃপর","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64235,"position":9,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":64236,"position":10,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":64237,"position":11,"text_uthmani":"تُوقِدُونَ","transliteration":"tūqidūna","translation_bn":"আগুন জ্বালো","root":"وقد","lemma":"أَوْقَدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64238,"position":12,"text_uthmani":"٨٠","transliteration":"","translation_bn":"(৮০)","root":"—","lemma":"٨٠","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī jaʿala lakum mina l-shajari l-akhḍari nāran fa-idhā antum min''hu tūqidūna', 'যিনি তোমাদের জন্য সবুজ গাছ হতে আগুন তৈরি করেছেন, অতঃপর তোমরা তাত্থেকে আগুন জ্বালাও।', '[It is] He who made for you from the green tree, fire, and then from it you ignite.', 'যিনি তোমাদের জন্য সবুজ গাছ হতে আগুন তৈরি করেছেন, অতঃপর তোমরা তাত্থেকে আগুন জ্বালাও।', '[It is] He who made for you from the green tree, fire, and then from it you ignite.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036080.mp3', now()),
  (36, 81, '', '[{"id":64623,"position":1,"text_uthmani":"أَوَلَيْسَ","transliteration":"awalaysa","translation_bn":"নন কি (সেই আল্লাহ)","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":64624,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":64625,"position":3,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64626,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ সমূহ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":64627,"position":5,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64628,"position":6,"text_uthmani":"بِقَـٰدِرٍ","transliteration":"biqādirin","translation_bn":"সক্ষম","root":"قدر","lemma":"قَادِر","grammar_bn":"অব্যয় (Preposition)"},{"id":64629,"position":7,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"এক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":64630,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":64631,"position":9,"text_uthmani":"يَخْلُقَ","transliteration":"yakhluqa","translation_bn":"সৃষ্টি করবেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":64632,"position":10,"text_uthmani":"مِثْلَهُم ۚ","transliteration":"mith''lahum","translation_bn":"তাদের মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":64634,"position":11,"text_uthmani":"بَلَىٰ","transliteration":"balā","translation_bn":"হ্যাঁ নিশ্চয়ই","root":"—","lemma":"بَلَىٰ\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":64635,"position":12,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64636,"position":13,"text_uthmani":"ٱلْخَلَّـٰقُ","transliteration":"l-khalāqu","translation_bn":"মহাস্রষ্টা","root":"خلق","lemma":"خَلَّٰق","grammar_bn":"শব্দ"},{"id":64637,"position":14,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":64638,"position":15,"text_uthmani":"٨١","transliteration":"","translation_bn":"(৮১)","root":"—","lemma":"٨١","grammar_bn":"মার্কার"}]'::jsonb, 'awalaysa alladhī khalaqa l-samāwāti wal-arḍa biqādirin ʿalā an yakhluqa mith''lahum balā wahuwa l-khalāqu l-ʿalīmu', 'যিনি আসমান যমীন সৃষ্টি করেছেন তিনি কি সেই লোকদের অনুরূপ (আবার) সৃষ্টি করতে সক্ষম নন? হাঁ, অবশ্যই। তিনি মহা স্রষ্টা, সর্বজ্ঞ।', 'Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator.', 'যিনি আসমান যমীন সৃষ্টি করেছেন তিনি কি সেই লোকদের অনুরূপ (আবার) সৃষ্টি করতে সক্ষম নন? হাঁ, অবশ্যই। তিনি মহা স্রষ্টা, সর্বজ্ঞ।', 'Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036081.mp3', now()),
  (36, 82, '', '[{"id":65041,"position":1,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"কেবল","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":65042,"position":2,"text_uthmani":"أَمْرُهُۥٓ","transliteration":"amruhu","translation_bn":"তাঁর নির্দেশ হয়","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":65043,"position":3,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":65044,"position":4,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"ইচ্ছে করেন","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65045,"position":5,"text_uthmani":"شَيْـًٔا","transliteration":"shayan","translation_bn":"কিছু (করতে)","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":65046,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":65047,"position":7,"text_uthmani":"يَقُولَ","transliteration":"yaqūla","translation_bn":"বলেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65048,"position":8,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":65049,"position":9,"text_uthmani":"كُن","transliteration":"kun","translation_bn":"\"হও\"","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65050,"position":10,"text_uthmani":"فَيَكُونُ","transliteration":"fayakūnu","translation_bn":"তখনই হয়ে যায়","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65051,"position":11,"text_uthmani":"٨٢","transliteration":"","translation_bn":"(৮২)","root":"—","lemma":"٨٢","grammar_bn":"মার্কার"}]'::jsonb, 'innamā amruhu idhā arāda shayan an yaqūla lahu kun fayakūnu', 'তাঁর কাজকর্ম কেবল এ রকম যে, যখন তিনি কোন কিছুর ইচ্ছে করেন তখন তাকে হুকুম করেন যে হয়ে যাও, আর অমনি তা হয়ে যায়।', 'His command is only when He intends a thing that He says to it, "Be," and it is.', 'তাঁর কাজকর্ম কেবল এ রকম যে, যখন তিনি কোন কিছুর ইচ্ছে করেন তখন তাকে হুকুম করেন যে হয়ে যাও, আর অমনি তা হয়ে যায়।', 'His command is only when He intends a thing that He says to it, "Be," and it is.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036082.mp3', now()),
  (36, 83, '', '[{"id":65312,"position":1,"text_uthmani":"فَسُبْحَـٰنَ","transliteration":"fasub''ḥāna","translation_bn":"অতএব মহান পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"শব্দ"},{"id":65313,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(সেই সত্ত্বা) তিনিই","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":65314,"position":3,"text_uthmani":"بِيَدِهِۦ","transliteration":"biyadihi","translation_bn":"যার হাতে (আছে)","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":65315,"position":4,"text_uthmani":"مَلَكُوتُ","transliteration":"malakūtu","translation_bn":"সার্বভৌম ক্ষমতা","root":"ملك","lemma":"مَلَكُوت","grammar_bn":"বিশেষ্য (Noun)"},{"id":65316,"position":5,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":65317,"position":6,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"জিনিসের","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":65318,"position":7,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":65319,"position":8,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমাদেরকে ফিরিয়ে নেয়া হবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":65320,"position":9,"text_uthmani":"٨٣","transliteration":"","translation_bn":"(৮৩)","root":"—","lemma":"٨٣","grammar_bn":"মার্কার"}]'::jsonb, 'fasub''ḥāna alladhī biyadihi malakūtu kulli shayin wa-ilayhi tur''jaʿūna', 'কাজেই পবিত্র ও মহান তিনি যাঁর হাতে সব কিছুর সর্বময় কর্তৃত্ব, আর তাঁর কাছেই তোমাদের (সকলকে) ফিরিয়ে আনা হবে।', 'So exalted is He in whose hand is the realm of all things, and to Him you will be returned.', 'কাজেই পবিত্র ও মহান তিনি যাঁর হাতে সব কিছুর সর্বময় কর্তৃত্ব, আর তাঁর কাছেই তোমাদের (সকলকে) ফিরিয়ে আনা হবে।', 'So exalted is He in whose hand is the realm of all things, and to Him you will be returned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/036083.mp3', now())
