  (37, 1, '', '[{"id":889,"position":1,"text_uthmani":"وَٱلصَّـٰٓفَّـٰتِ","transliteration":"wal-ṣāfāti","translation_bn":"শপথ সারি বেঁধে দাঁড়ায় যারা","root":"صفف","lemma":"صَٰ^فَّٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":890,"position":2,"text_uthmani":"صَفًّۭا","transliteration":"ṣaffan","translation_bn":"সারি সারি","root":"صفف","lemma":"صَفّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":891,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-ṣāfāti ṣaffan', 'শপথ তাদের যারা সারিবদ্ধভাবে দাঁড়ানো,', 'By those [angels] lined up in rows', 'শপথ তাদের যারা সারিবদ্ধভাবে দাঁড়ানো,', 'By those [angels] lined up in rows', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037001.mp3', now()),
  (37, 2, '', '[{"id":1977,"position":1,"text_uthmani":"فَٱلزَّٰجِرَٰتِ","transliteration":"fal-zājirāti","translation_bn":"অতঃপর (শপথ) ধমকদানকারীদের","root":"زجر","lemma":"زَّٰجِرَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1978,"position":2,"text_uthmani":"زَجْرًۭا","transliteration":"zajran","translation_bn":"সজোরে","root":"زجر","lemma":"زَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1979,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'fal-zājirāti zajran', 'অতঃপর যারা ধমক দিয়ে তিরস্কার করে তাদের শপথ,', 'And those who drive [the clouds]', 'অতঃপর যারা ধমক দিয়ে তিরস্কার করে তাদের শপথ,', 'And those who drive [the clouds]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037002.mp3', now()),
