  (37, 4, '', '[{"id":4528,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4529,"position":2,"text_uthmani":"إِلَـٰهَكُمْ","transliteration":"ilāhakum","translation_bn":"তোমাদের ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":4530,"position":3,"text_uthmani":"لَوَٰحِدٌۭ","transliteration":"lawāḥidun","translation_bn":"একজন অবশ্যই","root":"وحد","lemma":"وَٰحِد","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":4531,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna ilāhakum lawāḥidun', 'তোমাদের প্রকৃত ইলাহ অবশ্য একজন।', 'Indeed, your God is One,', 'তোমাদের প্রকৃত ইলাহ অবশ্য একজন।', 'Indeed, your God is One,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037004.mp3', now()),
