  (37, 53, '', '[{"id":50889,"position":1,"text_uthmani":"أَءِذَا","transliteration":"a-idhā","translation_bn":"কি যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":50890,"position":2,"text_uthmani":"مِتْنَا","transliteration":"mit''nā","translation_bn":"আমরা মারা যাবো","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50891,"position":3,"text_uthmani":"وَكُنَّا","transliteration":"wakunnā","translation_bn":"এবং আমরা হবো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50892,"position":4,"text_uthmani":"تُرَابًۭا","transliteration":"turāban","translation_bn":"মাটি","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":50893,"position":5,"text_uthmani":"وَعِظَـٰمًا","transliteration":"waʿiẓāman","translation_bn":"ও হাড় (সর্বস্ব)","root":"عظم","lemma":"عَظِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":50894,"position":6,"text_uthmani":"أَءِنَّا","transliteration":"a-innā","translation_bn":"আমরা কি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":50895,"position":7,"text_uthmani":"لَمَدِينُونَ","transliteration":"lamadīnūna","translation_bn":"প্রতিফলপ্রাপ্ত হবো অবশ্যই\"","root":"دين","lemma":"مَدِينِين","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":50896,"position":8,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'a-idhā mit''nā wakunnā turāban waʿiẓāman a-innā lamadīnūna', 'আমরা যখন মরে যাব আর মাটি ও হাড্ডিতে পরিণত হব তখনো সত্যিই কি আমাদেরকে পুরস্কার ও শাস্তি দেয়া হবে?', 'That when we have died and become dust and bones, we will indeed be recompensed?''"', 'আমরা যখন মরে যাব আর মাটি ও হাড্ডিতে পরিণত হব তখনো সত্যিই কি আমাদেরকে পুরস্কার ও শাস্তি দেয়া হবে?', 'That when we have died and become dust and bones, we will indeed be recompensed?''"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037053.mp3', now()),
