  (37, 55, '', '[{"id":51994,"position":1,"text_uthmani":"فَٱطَّلَعَ","transliteration":"fa-iṭṭalaʿa","translation_bn":"সে তখন উঁকি মেরে দেখবে","root":"طلع","lemma":"طَّلَعَ","grammar_bn":"শব্দ"},{"id":51995,"position":2,"text_uthmani":"فَرَءَاهُ","transliteration":"faraāhu","translation_bn":"তাকে ফলে দেখতে পাবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51996,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51997,"position":4,"text_uthmani":"سَوَآءِ","transliteration":"sawāi","translation_bn":"মাঝখানে","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":51998,"position":5,"text_uthmani":"ٱلْجَحِيمِ","transliteration":"l-jaḥīmi","translation_bn":"জাহান্নামের","root":"جحم","lemma":"جَحِيم","grammar_bn":"শব্দ"},{"id":51999,"position":6,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-iṭṭalaʿa faraāhu fī sawāi l-jaḥīmi', 'তারপর সে উঁকি দিয়ে দেখবে এবং তাকে জাহান্নামের মাঝখানে দেখতে পাবে।', 'And he will look and see him in the midst of the Hellfire.', 'তারপর সে উঁকি দিয়ে দেখবে এবং তাকে জাহান্নামের মাঝখানে দেখতে পাবে।', 'And he will look and see him in the midst of the Hellfire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037055.mp3', now()),
  (37, 56, '', '[{"id":52294,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52295,"position":2,"text_uthmani":"تَٱللَّهِ","transliteration":"tal-lahi","translation_bn":"\"আল্লাহর শপথ","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":52296,"position":3,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যে","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":52297,"position":4,"text_uthmani":"كِدتَّ","transliteration":"kidtta","translation_bn":"তুমি প্রায়","root":"كود","lemma":"كَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52298,"position":5,"text_uthmani":"لَتُرْدِينِ","transliteration":"latur''dīni","translation_bn":"আমাকে ধ্বংস করেই ফেলেছিলে","root":"ردي","lemma":"أَرْدَىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":52299,"position":6,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla tal-lahi in kidtta latur''dīni', 'সে বলবে, ‘আল্লাহর কসম! তুমি তো আমাকে প্রায় ধ্বংসই করে দিয়েছিলে,', 'He will say, "By Allah, you almost ruined me.', 'সে বলবে, ‘আল্লাহর কসম! তুমি তো আমাকে প্রায় ধ্বংসই করে দিয়েছিলে,', 'He will say, "By Allah, you almost ruined me.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037056.mp3', now()),
  (37, 57, '', '[{"id":53039,"position":1,"text_uthmani":"وَلَوْلَا","transliteration":"walawlā","translation_bn":"এবং যদি না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53040,"position":2,"text_uthmani":"نِعْمَةُ","transliteration":"niʿ''matu","translation_bn":"অনুগ্রহ (হতো)","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":53041,"position":3,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":53042,"position":4,"text_uthmani":"لَكُنتُ","transliteration":"lakuntu","translation_bn":"অবশ্যই আমি হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":53043,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":53044,"position":6,"text_uthmani":"ٱلْمُحْضَرِينَ","transliteration":"l-muḥ''ḍarīna","translation_bn":"(জাহান্নামে) উপস্থিত করা লোকদের","root":"حضر","lemma":"مُّحْضَر","grammar_bn":"শব্দ"},{"id":53045,"position":7,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'walawlā niʿ''matu rabbī lakuntu mina l-muḥ''ḍarīna', 'আমার প্রতিপালকের অনুগ্রহ না হলে আমিও তো (জাহান্নামের ভিতর) হাজির করা লোকেদের মধ্যে শামিল থাকতাম।', 'If not for the favor of my Lord, I would have been of those brought in [to Hell].', 'আমার প্রতিপালকের অনুগ্রহ না হলে আমিও তো (জাহান্নামের ভিতর) হাজির করা লোকেদের মধ্যে শামিল থাকতাম।', 'If not for the favor of my Lord, I would have been of those brought in [to Hell].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037057.mp3', now()),
