  (37, 59, '', '[{"id":54142,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":54143,"position":2,"text_uthmani":"مَوْتَتَنَا","transliteration":"mawtatanā","translation_bn":"আমাদের মৃত্যু","root":"موت","lemma":"مَوْتَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":54144,"position":3,"text_uthmani":"ٱلْأُولَىٰ","transliteration":"l-ūlā","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":54145,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54146,"position":5,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":54147,"position":6,"text_uthmani":"بِمُعَذَّبِينَ","transliteration":"bimuʿadhabīna","translation_bn":"শাস্তিপ্রাপ্ত হবো\"","root":"عذب","lemma":"مُعَذَّبِين","grammar_bn":"অব্যয় (Preposition)"},{"id":54148,"position":7,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'illā mawtatanā l-ūlā wamā naḥnu bimuʿadhabīna', 'আমাদের প্রথম মৃত্যুর পর, আর আমাদেরকে শাস্তিও দেয়া হবে না।', 'Except for our first death, and we will not be punished?"', 'আমাদের প্রথম মৃত্যুর পর, আর আমাদেরকে শাস্তিও দেয়া হবে না।', 'Except for our first death, and we will not be punished?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037059.mp3', now()),
