  (37, 76, '', '[{"id":62353,"position":1,"text_uthmani":"وَنَجَّيْنَـٰهُ","transliteration":"wanajjaynāhu","translation_bn":"এবং তাকে আমরা করেছিলাম উদ্ধার","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62354,"position":2,"text_uthmani":"وَأَهْلَهُۥ","transliteration":"wa-ahlahu","translation_bn":"ও তার পরিবারকে","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":62355,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62356,"position":4,"text_uthmani":"ٱلْكَرْبِ","transliteration":"l-karbi","translation_bn":"সংকট","root":"كرب","lemma":"كَرْب","grammar_bn":"শব্দ"},{"id":62357,"position":5,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহা","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":62358,"position":6,"text_uthmani":"٧٦","transliteration":"","translation_bn":"(৭৬)","root":"—","lemma":"٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'wanajjaynāhu wa-ahlahu mina l-karbi l-ʿaẓīmi', 'তাকে আর তার পরিবারবর্গকে আমি মহা বিপদ থেকে উদ্ধার করেছিলাম।', 'And We saved him and his family from the great affliction.', 'তাকে আর তার পরিবারবর্গকে আমি মহা বিপদ থেকে উদ্ধার করেছিলাম।', 'And We saved him and his family from the great affliction.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037076.mp3', now()),
  (37, 77, '', '[{"id":63163,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা রাখলাম","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":63164,"position":2,"text_uthmani":"ذُرِّيَّتَهُۥ","transliteration":"dhurriyyatahu","translation_bn":"তার বংশধরকে (এমন যে)","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":63165,"position":3,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":63166,"position":4,"text_uthmani":"ٱلْبَاقِينَ","transliteration":"l-bāqīna","translation_bn":"অবশিষ্ট","root":"بقي","lemma":"بَاقِين","grammar_bn":"শব্দ"},{"id":63167,"position":5,"text_uthmani":"٧٧","transliteration":"","translation_bn":"(৭৭)","root":"—","lemma":"٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā dhurriyyatahu humu l-bāqīna', 'আর তার বংশধরদেরকেই আমি বংশানুক্রমে বিদ্যমান রাখলাম।', 'And We made his descendants those remaining [on the earth]', 'আর তার বংশধরদেরকেই আমি বংশানুক্রমে বিদ্যমান রাখলাম।', 'And We made his descendants those remaining [on the earth]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037077.mp3', now()),
