  (37, 104, '', '[{"id":72668,"position":1,"text_uthmani":"وَنَـٰدَيْنَـٰهُ","transliteration":"wanādaynāhu","translation_bn":"এবং তাকে আমরা ডাক দিলাম","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":72669,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":72670,"position":3,"text_uthmani":"يَـٰٓإِبْرَٰهِيمُ","transliteration":"yāib''rāhīmu","translation_bn":"\"হে ইব্রাহীম","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":72671,"position":4,"text_uthmani":"١٠٤","transliteration":"","translation_bn":"(১০৪)","root":"—","lemma":"١٠٤","grammar_bn":"মার্কার"}]'::jsonb, 'wanādaynāhu an yāib''rāhīmu', 'তখন আমি তাকে ডাক দিলাম, ‘হে ইবরাহীম!', 'We called to him, "O Abraham,', 'তখন আমি তাকে ডাক দিলাম, ‘হে ইবরাহীম!', 'We called to him, "O Abraham,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037104.mp3', now()),
  (37, 105, '', '[{"id":72910,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":72911,"position":2,"text_uthmani":"صَدَّقْتَ","transliteration":"ṣaddaqta","translation_bn":"তুমি সত্য করেছো","root":"صدق","lemma":"صَدَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72912,"position":3,"text_uthmani":"ٱلرُّءْيَآ ۚ","transliteration":"l-ru''yā","translation_bn":"স্বপ্নকে\"","root":"راي","lemma":"رُّءْيَا","grammar_bn":"শব্দ"},{"id":72914,"position":4,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":72915,"position":5,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এরূপে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":72916,"position":6,"text_uthmani":"نَجْزِى","transliteration":"najzī","translation_bn":"প্রতিফল দিই আমরা","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":72917,"position":7,"text_uthmani":"ٱلْمُحْسِنِينَ","transliteration":"l-muḥ''sinīna","translation_bn":"সৎকর্মপরায়ণদের","root":"حسن","lemma":"مُحْسِن","grammar_bn":"শব্দ"},{"id":72918,"position":8,"text_uthmani":"١٠٥","transliteration":"","translation_bn":"(১০৫)","root":"—","lemma":"١٠٥","grammar_bn":"মার্কার"}]'::jsonb, 'qad ṣaddaqta l-ru''yā innā kadhālika najzī l-muḥ''sinīna', 'স্বপ্নে দেয়া আদেশ তুমি সত্যে পরিণত করেই ছাড়লে। এভাবেই আমি সৎকর্মশীলদেরকে প্রতিদান দিয়ে থাকি।', 'You have fulfilled the vision." Indeed, We thus reward the doers of good.', 'স্বপ্নে দেয়া আদেশ তুমি সত্যে পরিণত করেই ছাড়লে। এভাবেই আমি সৎকর্মশীলদেরকে প্রতিদান দিয়ে থাকি।', 'You have fulfilled the vision." Indeed, We thus reward the doers of good.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037105.mp3', now()),
  (37, 106, '', '[{"id":73174,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":73175,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":73176,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"তা অবশ্যই (ছিলো)","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":73177,"position":4,"text_uthmani":"ٱلْبَلَـٰٓؤُا۟","transliteration":"l-balāu","translation_bn":"পরীক্ষা","root":"بلو","lemma":"بَلَا^ء","grammar_bn":"শব্দ"},{"id":73178,"position":5,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":73179,"position":6,"text_uthmani":"١٠٦","transliteration":"","translation_bn":"(১০৬)","root":"—","lemma":"١٠٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā lahuwa l-balāu l-mubīnu', 'অবশ্যই এটা ছিল এক সুস্পষ্ট পরীক্ষা।', 'Indeed, this was the clear trial.', 'অবশ্যই এটা ছিল এক সুস্পষ্ট পরীক্ষা।', 'Indeed, this was the clear trial.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037106.mp3', now()),
  (37, 107, '', '[{"id":73420,"position":1,"text_uthmani":"وَفَدَيْنَـٰهُ","transliteration":"wafadaynāhu","translation_bn":"এবং তাকে আমরা ছাড়িয়ে নিই","root":"فدي","lemma":"فَدَيْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73421,"position":2,"text_uthmani":"بِذِبْحٍ","transliteration":"bidhib''ḥin","translation_bn":"জবাই পশুর বিনিময়ে","root":"ذبح","lemma":"ذِبْح","grammar_bn":"অব্যয় (Preposition)"},{"id":73422,"position":3,"text_uthmani":"عَظِيمٍۢ","transliteration":"ʿaẓīmin","translation_bn":"বড়","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":73423,"position":4,"text_uthmani":"١٠٧","transliteration":"","translation_bn":"(১০৭)","root":"—","lemma":"١٠٧","grammar_bn":"মার্কার"}]'::jsonb, 'wafadaynāhu bidhib''ḥin ʿaẓīmin', 'আমি এক মহান কুরবানীর বিনিময়ে পুত্রটিকে ছাড়িয়ে নিলাম।', 'And We ransomed him with a great sacrifice,', 'আমি এক মহান কুরবানীর বিনিময়ে পুত্রটিকে ছাড়িয়ে নিলাম।', 'And We ransomed him with a great sacrifice,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037107.mp3', now()),
  (37, 108, '', '[{"id":73688,"position":1,"text_uthmani":"وَتَرَكْنَا","transliteration":"wataraknā","translation_bn":"এবং আমরা প্রচলিত রাখলাম","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73689,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তাঁর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73690,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":73691,"position":4,"text_uthmani":"ٱلْـَٔاخِرِينَ","transliteration":"l-ākhirīna","translation_bn":"পরবর্তীদের (তাঁর স্মরণ)","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":73692,"position":5,"text_uthmani":"١٠٨","transliteration":"","translation_bn":"(১০৮)","root":"—","lemma":"١٠٨","grammar_bn":"মার্কার"}]'::jsonb, 'wataraknā ʿalayhi fī l-ākhirīna', 'আর আমি তাকে পরবর্তীদের মাঝে স্মরণীয় করে রাখলাম।', 'And We left for him [favorable mention] among later generations:', 'আর আমি তাকে পরবর্তীদের মাঝে স্মরণীয় করে রাখলাম।', 'And We left for him [favorable mention] among later generations:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037108.mp3', now()),
