  (37, 112, '', '[{"id":74716,"position":1,"text_uthmani":"وَبَشَّرْنَـٰهُ","transliteration":"wabasharnāhu","translation_bn":"এবং তাকে আমরা সুসংবাদ দিলাম","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74717,"position":2,"text_uthmani":"بِإِسْحَـٰقَ","transliteration":"bi-is''ḥāqa","translation_bn":"ইসহাক সম্পর্কে","root":"—","lemma":"إِسْحَاق","grammar_bn":"অব্যয় (Preposition)"},{"id":74718,"position":3,"text_uthmani":"نَبِيًّۭا","transliteration":"nabiyyan","translation_bn":"একজন নাবী হিসেবে","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":74719,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্যতম","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74720,"position":5,"text_uthmani":"ٱلصَّـٰلِحِينَ","transliteration":"l-ṣāliḥīna","translation_bn":"সৎকর্মশীলদের","root":"صلح","lemma":"صَٰلِح","grammar_bn":"শব্দ"},{"id":74721,"position":6,"text_uthmani":"١١٢","transliteration":"","translation_bn":"(১১২)","root":"—","lemma":"١١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wabasharnāhu bi-is''ḥāqa nabiyyan mina l-ṣāliḥīna', 'আর তাকে সুসংবাদ দিয়েছিলাম ইসহাকের- যে ছিল সৎকর্মশীল বান্দাহদের অন্তর্ভুক্ত একজন নবী।', 'And We gave him good tidings of Isaac, a prophet from among the righteous.', 'আর তাকে সুসংবাদ দিয়েছিলাম ইসহাকের- যে ছিল সৎকর্মশীল বান্দাহদের অন্তর্ভুক্ত একজন নবী।', 'And We gave him good tidings of Isaac, a prophet from among the righteous.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037112.mp3', now()),
  (37, 113, '', '[{"id":74891,"position":1,"text_uthmani":"وَبَـٰرَكْنَا","transliteration":"wabāraknā","translation_bn":"এবং আমরা সমৃদ্ধি দিলাম","root":"برك","lemma":"بَٰرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74892,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তাঁর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":74893,"position":3,"text_uthmani":"وَعَلَىٰٓ","transliteration":"waʿalā","translation_bn":"ও উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74894,"position":4,"text_uthmani":"إِسْحَـٰقَ ۚ","transliteration":"is''ḥāqa","translation_bn":"ইসহাকের","root":"—","lemma":"إِسْحَاق","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":74896,"position":5,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74897,"position":6,"text_uthmani":"ذُرِّيَّتِهِمَا","transliteration":"dhurriyyatihimā","translation_bn":"তাদের দু''জনের বংশধরদের","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":74898,"position":7,"text_uthmani":"مُحْسِنٌۭ","transliteration":"muḥ''sinun","translation_bn":"(কেউ হয়) সৎকর্মপরায়ণ","root":"حسن","lemma":"مُحْسِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":74899,"position":8,"text_uthmani":"وَظَالِمٌۭ","transliteration":"waẓālimun","translation_bn":"ও (কেউ হয়) সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":74900,"position":9,"text_uthmani":"لِّنَفْسِهِۦ","transliteration":"linafsihi","translation_bn":"তার নিজের উপর","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":74901,"position":10,"text_uthmani":"مُبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":74902,"position":11,"text_uthmani":"١١٣","transliteration":"","translation_bn":"(১১৩)","root":"—","lemma":"١١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wabāraknā ʿalayhi waʿalā is''ḥāqa wamin dhurriyyatihimā muḥ''sinun waẓālimun linafsihi mubīnun', 'আর আমি বরকত দিলাম তাকে আর ইসহাককে; (তাদের দু’জনের) বংশধরদের কতক সৎকর্মশীল, আর কতক নিজেদের প্রতি সুস্পষ্ট যুলুমকারী।', 'And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself.', 'আর আমি বরকত দিলাম তাকে আর ইসহাককে; (তাদের দু’জনের) বংশধরদের কতক সৎকর্মশীল, আর কতক নিজেদের প্রতি সুস্পষ্ট যুলুমকারী।', 'And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037113.mp3', now()),
