  (37, 115, '', '[{"id":75357,"position":1,"text_uthmani":"وَنَجَّيْنَـٰهُمَا","transliteration":"wanajjaynāhumā","translation_bn":"এবং উদ্ধার করেছি আমরা উভয়কে","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":75358,"position":2,"text_uthmani":"وَقَوْمَهُمَا","transliteration":"waqawmahumā","translation_bn":"ও উভয়ের জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":75359,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":75360,"position":4,"text_uthmani":"ٱلْكَرْبِ","transliteration":"l-karbi","translation_bn":"সংকট","root":"كرب","lemma":"كَرْب","grammar_bn":"শব্দ"},{"id":75361,"position":5,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহা","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":75362,"position":6,"text_uthmani":"١١٥","transliteration":"","translation_bn":"(১১৫)","root":"—","lemma":"١١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wanajjaynāhumā waqawmahumā mina l-karbi l-ʿaẓīmi', 'আর তাদের দু’জনকে এবং তাদের জাতিকে মহা বিপদ থেকে রক্ষা করেছিলাম।', 'And We saved them and their people from the great affliction,', 'আর তাদের দু’জনকে এবং তাদের জাতিকে মহা বিপদ থেকে রক্ষা করেছিলাম।', 'And We saved them and their people from the great affliction,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037115.mp3', now()),
