  (37, 125, '', '[{"id":77121,"position":1,"text_uthmani":"أَتَدْعُونَ","transliteration":"atadʿūna","translation_bn":"তোমরা ডাকবে কি","root":"دعو","lemma":"دَعَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":77122,"position":2,"text_uthmani":"بَعْلًۭا","transliteration":"baʿlan","translation_bn":"বা''আল (নামক মূর্তিকে)","root":"بعل","lemma":"بَعْل2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":77123,"position":3,"text_uthmani":"وَتَذَرُونَ","transliteration":"watadharūna","translation_bn":"আর ত্যাগ করবে","root":"وذر","lemma":"يَذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":77124,"position":4,"text_uthmani":"أَحْسَنَ","transliteration":"aḥsana","translation_bn":"সর্বশ্রেষ্ঠ","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":77125,"position":5,"text_uthmani":"ٱلْخَـٰلِقِينَ","transliteration":"l-khāliqīna","translation_bn":"স্রষ্টা","root":"خلق","lemma":"خَٰلِق","grammar_bn":"শব্দ"},{"id":77126,"position":6,"text_uthmani":"١٢٥","transliteration":"","translation_bn":"(১২৫)","root":"—","lemma":"١٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'atadʿūna baʿlan watadharūna aḥsana l-khāliqīna', '‘তোমরা কি বা‘য়ালকে ডাক, আর পরিত্যাগ কর সর্বোত্তম সৃষ্টিকারী', 'Do you call upon Ba''l and leave the best of creators -', '‘তোমরা কি বা‘য়ালকে ডাক, আর পরিত্যাগ কর সর্বোত্তম সৃষ্টিকারী', 'Do you call upon Ba''l and leave the best of creators -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037125.mp3', now()),
  (37, 126, '', '[{"id":77351,"position":1,"text_uthmani":"ٱللَّهَ","transliteration":"al-laha","translation_bn":"(অর্থাৎ) আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":77352,"position":2,"text_uthmani":"رَبَّكُمْ","transliteration":"rabbakum","translation_bn":"(যিনি) তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":77353,"position":3,"text_uthmani":"وَرَبَّ","transliteration":"warabba","translation_bn":"ও রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":77354,"position":4,"text_uthmani":"ءَابَآئِكُمُ","transliteration":"ābāikumu","translation_bn":"তোমাদের পিতৃপুরুষদেরও\"","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":77355,"position":5,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বের\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":77356,"position":6,"text_uthmani":"١٢٦","transliteration":"","translation_bn":"(১২৬)","root":"—","lemma":"١٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'al-laha rabbakum warabba ābāikumu l-awalīna', 'আল্লাহকে, যিনি তোমাদের প্রতিপালক আর তোমাদের পূর্ববর্তী পিতৃপুরুষদেরও প্রতিপালক।', 'Allah, your Lord and the Lord of your first forefathers?"', 'আল্লাহকে, যিনি তোমাদের প্রতিপালক আর তোমাদের পূর্ববর্তী পিতৃপুরুষদেরও প্রতিপালক।', 'Allah, your Lord and the Lord of your first forefathers?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037126.mp3', now()),
  (37, 127, '', '[{"id":77515,"position":1,"text_uthmani":"فَكَذَّبُوهُ","transliteration":"fakadhabūhu","translation_bn":"তাকে তারা তখন অমান্য করলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":77516,"position":2,"text_uthmani":"فَإِنَّهُمْ","transliteration":"fa-innahum","translation_bn":"নিশ্চয় তাই তাদের","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":77517,"position":3,"text_uthmani":"لَمُحْضَرُونَ","transliteration":"lamuḥ''ḍarūna","translation_bn":"উপস্থিত করা হবে অবশ্যই (শাস্তির জন্যে)","root":"حضر","lemma":"مُّحْضَر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":77518,"position":4,"text_uthmani":"١٢٧","transliteration":"","translation_bn":"(১২৭)","root":"—","lemma":"١٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'fakadhabūhu fa-innahum lamuḥ''ḍarūna', 'কিন্তু তারা তাকে মিথ্যে বলে প্রত্যাখ্যান করল, কাজেই তাদেরকে অবশ্যই (শাস্তির জন্য) হাজির করা হবে।', 'And they denied him, so indeed, they will be brought [for punishment],', 'কিন্তু তারা তাকে মিথ্যে বলে প্রত্যাখ্যান করল, কাজেই তাদেরকে অবশ্যই (শাস্তির জন্য) হাজির করা হবে।', 'And they denied him, so indeed, they will be brought [for punishment],', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037127.mp3', now()),
