  (37, 175, '', '[{"id":83301,"position":1,"text_uthmani":"وَأَبْصِرْهُمْ","transliteration":"wa-abṣir''hum","translation_bn":"এবং দেখতে থাকো তাদেরকে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83302,"position":2,"text_uthmani":"فَسَوْفَ","transliteration":"fasawfa","translation_bn":"অতঃপর শীঘ্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"শব্দ"},{"id":83303,"position":3,"text_uthmani":"يُبْصِرُونَ","transliteration":"yub''ṣirūna","translation_bn":"তারাই দেখবে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83304,"position":4,"text_uthmani":"١٧٥","transliteration":"","translation_bn":"(১৭৫)","root":"—","lemma":"١٧٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-abṣir''hum fasawfa yub''ṣirūna', 'আর তাদেরকে দেখতে থাক, তারা শীঘ্রই দেখতে পাবে (ঈমান ও কুফুরীর পরিণাম)।', 'And see [what will befall] them, for they are going to see.', 'আর তাদেরকে দেখতে থাক, তারা শীঘ্রই দেখতে পাবে (ঈমান ও কুফুরীর পরিণাম)।', 'And see [what will befall] them, for they are going to see.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037175.mp3', now()),
  (37, 176, '', '[{"id":83382,"position":1,"text_uthmani":"أَفَبِعَذَابِنَا","transliteration":"afabiʿadhābinā","translation_bn":"আমাদের শাস্তি সম্পর্কে তবে কি","root":"عذب","lemma":"عَذَاب","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":83383,"position":2,"text_uthmani":"يَسْتَعْجِلُونَ","transliteration":"yastaʿjilūna","translation_bn":"তারা তাড়াহুড়া করছে","root":"عجل","lemma":"ٱسْتَعْجَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83384,"position":3,"text_uthmani":"١٧٦","transliteration":"","translation_bn":"(১৭৬)","root":"—","lemma":"١٧٦","grammar_bn":"মার্কার"}]'::jsonb, 'afabiʿadhābinā yastaʿjilūna', 'তারা কি আমার শাস্তি তরান্বিত করতে চায়?', 'Then for Our punishment are they impatient?', 'তারা কি আমার শাস্তি তরান্বিত করতে চায়?', 'Then for Our punishment are they impatient?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037176.mp3', now()),
  (37, 177, '', '[{"id":83583,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":83584,"position":2,"text_uthmani":"نَزَلَ","transliteration":"nazala","translation_bn":"নেমে আসবে (তা)","root":"نزل","lemma":"نَزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83585,"position":3,"text_uthmani":"بِسَاحَتِهِمْ","transliteration":"bisāḥatihim","translation_bn":"তাদের আঙ্গিনায়","root":"سوح","lemma":"سَاحَت","grammar_bn":"অব্যয় (Preposition)"},{"id":83586,"position":4,"text_uthmani":"فَسَآءَ","transliteration":"fasāa","translation_bn":"কত মন্দ হবে তখন","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"শব্দ"},{"id":83587,"position":5,"text_uthmani":"صَبَاحُ","transliteration":"ṣabāḥu","translation_bn":"প্রভাত","root":"صبح","lemma":"صَبَاح","grammar_bn":"বিশেষ্য (Noun)"},{"id":83588,"position":6,"text_uthmani":"ٱلْمُنذَرِينَ","transliteration":"l-mundharīna","translation_bn":"সতর্কীকৃতদের","root":"نذر","lemma":"مُنذَرِين","grammar_bn":"শব্দ"},{"id":83589,"position":7,"text_uthmani":"١٧٧","transliteration":"","translation_bn":"(১৭৭)","root":"—","lemma":"١٧٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā nazala bisāḥatihim fasāa ṣabāḥu l-mundharīna', 'শাস্তি যখন তাদের উঠানে নেমে আসবে, তখন কতই না মন্দ হবে ঐ লোকেদের সকালটি যাদেরকে সতর্ক করা হয়েছিল!', 'But when it descends in their territory, then evil is the morning of those who were warned.', 'শাস্তি যখন তাদের উঠানে নেমে আসবে, তখন কতই না মন্দ হবে ঐ লোকেদের সকালটি যাদেরকে সতর্ক করা হয়েছিল!', 'But when it descends in their territory, then evil is the morning of those who were warned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037177.mp3', now()),
