  (37, 179, '', '[{"id":83771,"position":1,"text_uthmani":"وَأَبْصِرْ","transliteration":"wa-abṣir","translation_bn":"আর দেখতে থাকো","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83772,"position":2,"text_uthmani":"فَسَوْفَ","transliteration":"fasawfa","translation_bn":"শীঘ্র্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"শব্দ"},{"id":83773,"position":3,"text_uthmani":"يُبْصِرُونَ","transliteration":"yub''ṣirūna","translation_bn":"তারাও দেখতে পাবে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83774,"position":4,"text_uthmani":"١٧٩","transliteration":"","translation_bn":"(১৭৯)","root":"—","lemma":"١٧٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-abṣir fasawfa yub''ṣirūna', 'আর দেখতে থাক, শীঘ্রই তারা দেখতে পাবে (ঈমান ও কুফুরীর পরিণাম)।', 'And see, for they are going to see.', 'আর দেখতে থাক, শীঘ্রই তারা দেখতে পাবে (ঈমান ও কুফুরীর পরিণাম)।', 'And see, for they are going to see.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037179.mp3', now()),
  (37, 180, '', '[{"id":83805,"position":1,"text_uthmani":"سُبْحَـٰنَ","transliteration":"sub''ḥāna","translation_bn":"পবিত্র","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":83806,"position":2,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":83807,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":83808,"position":4,"text_uthmani":"ٱلْعِزَّةِ","transliteration":"l-ʿizati","translation_bn":"সম্মানের (মালিক)","root":"عزز","lemma":"عِزَّة","grammar_bn":"শব্দ"},{"id":83809,"position":5,"text_uthmani":"عَمَّا","transliteration":"ʿammā","translation_bn":"তাহ''তে যা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83810,"position":6,"text_uthmani":"يَصِفُونَ","transliteration":"yaṣifūna","translation_bn":"তারা আরোপ করে","root":"وصف","lemma":"يَصِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":83811,"position":7,"text_uthmani":"١٨٠","transliteration":"","translation_bn":"(১৮০)","root":"—","lemma":"١٨٠","grammar_bn":"মার্কার"}]'::jsonb, 'sub''ḥāna rabbika rabbi l-ʿizati ʿammā yaṣifūna', 'সকল সম্মান ও ক্ষমতার রব্ব, তোমার প্রতিপালক পবিত্র ও মহান সে সকল কথাবার্তা হতে যা তারা আরোপ করে।', 'Exalted is your Lord, the Lord of might, above what they describe.', 'সকল সম্মান ও ক্ষমতার রব্ব, তোমার প্রতিপালক পবিত্র ও মহান সে সকল কথাবার্তা হতে যা তারা আরোপ করে।', 'Exalted is your Lord, the Lord of might, above what they describe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037180.mp3', now()),
  (37, 181, '', '[{"id":83921,"position":1,"text_uthmani":"وَسَلَـٰمٌ","transliteration":"wasalāmun","translation_bn":"এবং শান্তি (বর্ষিত হোক)","root":"سلم","lemma":"سَلَٰم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83922,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":83923,"position":3,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদের","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":83924,"position":4,"text_uthmani":"١٨١","transliteration":"","translation_bn":"(১৮১)","root":"—","lemma":"١٨١","grammar_bn":"মার্কার"}]'::jsonb, 'wasalāmun ʿalā l-mur''salīna', 'শান্তি বর্ষিত হোক রসূলদের প্রতি।', 'And peace upon the messengers.', 'শান্তি বর্ষিত হোক রসূলদের প্রতি।', 'And peace upon the messengers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037181.mp3', now()),
  (37, 182, '', '[{"id":83956,"position":1,"text_uthmani":"وَٱلْحَمْدُ","transliteration":"wal-ḥamdu","translation_bn":"এবং সমস্ত প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":83957,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":83958,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(যিনি) রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":83959,"position":4,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":83960,"position":5,"text_uthmani":"١٨٢","transliteration":"","translation_bn":"(১৮২)","root":"—","lemma":"١٨٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-ḥamdu lillahi rabbi l-ʿālamīna', 'আর যাবতীয় প্রশংসা বিশ্বজগতের প্রতিপালক আল্লাহর জন্যই।', 'And praise to Allah, Lord of the worlds.', 'আর যাবতীয় প্রশংসা বিশ্বজগতের প্রতিপালক আল্লাহর জন্যই।', 'And praise to Allah, Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/037182.mp3', now())
