  (38, 1, '', '[{"id":903,"position":1,"text_uthmani":"صٓ ۚ","transliteration":"sad","translation_bn":"সাদ","root":"—","lemma":"صٓ ۚ","grammar_bn":"শব্দ"},{"id":905,"position":2,"text_uthmani":"وَٱلْقُرْءَانِ","transliteration":"wal-qur''āni","translation_bn":"কোরআনের শপথ","root":"قرا","lemma":"قُرْءَان","grammar_bn":"অব্যয় (Preposition)"},{"id":906,"position":3,"text_uthmani":"ذِى","transliteration":"dhī","translation_bn":"পূর্ণ","root":"—","lemma":"ذُو","grammar_bn":"বিশেষণ (Adjective)"},{"id":907,"position":4,"text_uthmani":"ٱلذِّكْرِ","transliteration":"l-dhik''ri","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":908,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sad wal-qur''āni dhī l-dhik''ri', 'স্ব-দ, উপদেশপূর্ণ কুরআনের শপথ- (এটা সত্য)।', 'Sad. By the Qur''an containing reminder...', 'স্ব-দ, উপদেশপূর্ণ কুরআনের শপথ- (এটা সত্য)।', 'Sad. By the Qur''an containing reminder...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038001.mp3', now()),
  (38, 2, '', '[{"id":2013,"position":1,"text_uthmani":"بَلِ","transliteration":"bali","translation_bn":"কিন্তু","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":2014,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2015,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2016,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (লিপ্ত)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2017,"position":5,"text_uthmani":"عِزَّةٍۢ","transliteration":"ʿizzatin","translation_bn":"ঔদ্ধত্যের","root":"عزز","lemma":"عِزَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2018,"position":6,"text_uthmani":"وَشِقَاقٍۢ","transliteration":"washiqāqin","translation_bn":"ও বিরোধীতার","root":"شقق","lemma":"شِقَاق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2019,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'bali alladhīna kafarū fī ʿizzatin washiqāqin', 'কিন্তু কাফিররা আত্মম্ভরিতা আর বিরোধিতায় নিমজ্জিত।', 'But those who disbelieve are in pride and dissension.', 'কিন্তু কাফিররা আত্মম্ভরিতা আর বিরোধিতায় নিমজ্জিত।', 'But those who disbelieve are in pride and dissension.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038002.mp3', now()),
  (38, 3, '', '[{"id":3201,"position":1,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"কত (জাতিকেই)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":3202,"position":2,"text_uthmani":"أَهْلَكْنَا","transliteration":"ahlaknā","translation_bn":"আমরা ধ্বংস করেছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3203,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পূর্বে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3204,"position":4,"text_uthmani":"قَبْلِهِم","transliteration":"qablihim","translation_bn":"তাদের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3205,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"মধ্যে হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3206,"position":6,"text_uthmani":"قَرْنٍۢ","transliteration":"qarnin","translation_bn":"জাতিসমূহের","root":"قرن","lemma":"قَرْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":3207,"position":7,"text_uthmani":"فَنَادَوا۟","transliteration":"fanādaw","translation_bn":"তারা তখন চিৎকার করেছে","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"শব্দ"},{"id":3208,"position":8,"text_uthmani":"وَّلَاتَ","transliteration":"walāta","translation_bn":"কিন্তু আর ছিলো না","root":"لوت","lemma":"لَاتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3209,"position":9,"text_uthmani":"حِينَ","transliteration":"ḥīna","translation_bn":"সময়","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":3210,"position":10,"text_uthmani":"مَنَاصٍۢ","transliteration":"manāṣin","translation_bn":"মুক্তি লাভের","root":"نوص","lemma":"مَنَاص","grammar_bn":"বিশেষ্য (Noun)"},{"id":3211,"position":11,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'kam ahlaknā min qablihim min qarnin fanādaw walāta ḥīna manāṣin', 'তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করে দিয়েছি, অবশেষে তারা (ক্ষমা লাভের জন্য) আর্তচিৎকার করেছিল, কিন্তু তখন পরিত্রাণ লাভের আর কোন অবকাশই ছিল না।', 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.', 'তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করে দিয়েছি, অবশেষে তারা (ক্ষমা লাভের জন্য) আর্তচিৎকার করেছিল, কিন্তু তখন পরিত্রাণ লাভের আর কোন অবকাশই ছিল না।', 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038003.mp3', now()),
  (38, 4, '', '[{"id":4543,"position":1,"text_uthmani":"وَعَجِبُوٓا۟","transliteration":"waʿajibū","translation_bn":"এবং অবাক হয়েছে তারা","root":"عجب","lemma":"عَجِبُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4544,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":4545,"position":3,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"তাদের কাছে এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4546,"position":4,"text_uthmani":"مُّنذِرٌۭ","transliteration":"mundhirun","translation_bn":"একজন সতর্ককারী","root":"نذر","lemma":"مُنذِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4547,"position":5,"text_uthmani":"مِّنْهُمْ ۖ","transliteration":"min''hum","translation_bn":"তাদেরই মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4549,"position":6,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4550,"position":7,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"কাফিররা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":4551,"position":8,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"এই (ব্যক্তি)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":4552,"position":9,"text_uthmani":"سَـٰحِرٌۭ","transliteration":"sāḥirun","translation_bn":"যাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4553,"position":10,"text_uthmani":"كَذَّابٌ","transliteration":"kadhābun","translation_bn":"বড় মিথ্যাবাদী","root":"كذب","lemma":"كَذَّاب","grammar_bn":"বিশেষণ (Adjective)"},{"id":4554,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'waʿajibū an jāahum mundhirun min''hum waqāla l-kāfirūna hādhā sāḥirun kadhābun', 'আর তারা (এ ব্যাপারে) বিস্ময়বোধ করল যে, তাদের কাছে তাদেরই মধ্য হতে একজন সতর্ককারী এসেছে। কাফিরগণ বলল- ’এটা একটা যাদুকর, মিথ্যুক।', 'And they wonder that there has come to them a warner from among themselves. And the disbelievers say, "This is a magician and a liar.', 'আর তারা (এ ব্যাপারে) বিস্ময়বোধ করল যে, তাদের কাছে তাদেরই মধ্য হতে একজন সতর্ককারী এসেছে। কাফিরগণ বলল- ’এটা একটা যাদুকর, মিথ্যুক।', 'And they wonder that there has come to them a warner from among themselves. And the disbelievers say, "This is a magician and a liar.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038004.mp3', now()),
  (38, 5, '', '[{"id":5821,"position":1,"text_uthmani":"أَجَعَلَ","transliteration":"ajaʿala","translation_bn":"সাব্যস্ত করেছে কি সে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":5822,"position":2,"text_uthmani":"ٱلْـَٔالِهَةَ","transliteration":"l-ālihata","translation_bn":"সব উপাস্যকে","root":"اله","lemma":"إِلَٰه","grammar_bn":"শব্দ"},{"id":5823,"position":3,"text_uthmani":"إِلَـٰهًۭا","transliteration":"ilāhan","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":5824,"position":4,"text_uthmani":"وَٰحِدًا ۖ","transliteration":"wāḥidan","translation_bn":"একই","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":5826,"position":5,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5827,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5828,"position":7,"text_uthmani":"لَشَىْءٌ","transliteration":"lashayon","translation_bn":"অবশ্যই ব্যাপার","root":"شيا","lemma":"شَىْء","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":5829,"position":8,"text_uthmani":"عُجَابٌۭ","transliteration":"ʿujābun","translation_bn":"আজব\"","root":"عجب","lemma":"عُجَاب","grammar_bn":"বিশেষণ (Adjective)"},{"id":5830,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ajaʿala l-ālihata ilāhan wāḥidan inna hādhā lashayon ʿujābun', 'সে কি সব ইলাহকে এক ইলাহ বানিয়ে ফেলেছে? এটা বড়ই আশ্চর্য ব্যাপার তো!’', 'Has he made the gods [only] one God? Indeed, this is a curious thing."', 'সে কি সব ইলাহকে এক ইলাহ বানিয়ে ফেলেছে? এটা বড়ই আশ্চর্য ব্যাপার তো!’', 'Has he made the gods [only] one God? Indeed, this is a curious thing."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038005.mp3', now()),
  (38, 6, '', '[{"id":7103,"position":1,"text_uthmani":"وَٱنطَلَقَ","transliteration":"wa-inṭalaqa","translation_bn":"এবং সরে পড়লো","root":"طلق","lemma":"ٱنطَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7104,"position":2,"text_uthmani":"ٱلْمَلَأُ","transliteration":"l-mala-u","translation_bn":"প্রধানেরা","root":"ملا","lemma":"مَلَأ","grammar_bn":"শব্দ"},{"id":7105,"position":3,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যকার","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7106,"position":4,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"(এই বলে) যে,","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":7107,"position":5,"text_uthmani":"ٱمْشُوا۟","transliteration":"im''shū","translation_bn":"\"তোমরা চলে যাও","root":"مشي","lemma":"مَّشَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7108,"position":6,"text_uthmani":"وَٱصْبِرُوا۟","transliteration":"wa-iṣ''birū","translation_bn":"ও তোমরা অবিচল থাকো","root":"صبر","lemma":"صَبَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7109,"position":7,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7110,"position":8,"text_uthmani":"ءَالِهَتِكُمْ ۖ","transliteration":"ālihatikum","translation_bn":"তোমাদের উপাস্যদের (উপাসনায়)","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":7112,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7113,"position":10,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":7114,"position":11,"text_uthmani":"لَشَىْءٌۭ","transliteration":"lashayon","translation_bn":"ব্যাপার অবশ্যই","root":"شيا","lemma":"شَىْء","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":7115,"position":12,"text_uthmani":"يُرَادُ","transliteration":"yurādu","translation_bn":"উদ্দেশ্যমূলক","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7116,"position":13,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inṭalaqa l-mala-u min''hum ani im''shū wa-iṣ''birū ʿalā ālihatikum inna hādhā lashayon yurādu', 'তাদের প্রধানরা প্রস্থান করে এই বলে যে, ‘তোমরা চলে যাও আর অবিচলিত চিত্তে তোমাদের ইলাহদের পূজায় লেগে থাক। অবশ্যই এ ব্যাপারটির পিছনে অন্য উদ্দেশ্য আছে।', 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.', 'তাদের প্রধানরা প্রস্থান করে এই বলে যে, ‘তোমরা চলে যাও আর অবিচলিত চিত্তে তোমাদের ইলাহদের পূজায় লেগে থাক। অবশ্যই এ ব্যাপারটির পিছনে অন্য উদ্দেশ্য আছে।', 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038006.mp3', now()),
  (38, 7, '', '[{"id":8434,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8435,"position":2,"text_uthmani":"سَمِعْنَا","transliteration":"samiʿ''nā","translation_bn":"আমরা শুনেছি","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8436,"position":3,"text_uthmani":"بِهَـٰذَا","transliteration":"bihādhā","translation_bn":"এ সম্পর্কে","root":"—","lemma":"هَٰذَا","grammar_bn":"অব্যয় (Preposition)"},{"id":8437,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8438,"position":5,"text_uthmani":"ٱلْمِلَّةِ","transliteration":"l-milati","translation_bn":"জাতি-ধর্মগুলোতে","root":"ملل","lemma":"مِلَّة","grammar_bn":"শব্দ"},{"id":8439,"position":6,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"(অতীতের) অন্যান্য","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":8440,"position":7,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":8441,"position":8,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":8442,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":8443,"position":10,"text_uthmani":"ٱخْتِلَـٰقٌ","transliteration":"ikh''tilāqun","translation_bn":"মনগড়া কথা","root":"خلق","lemma":"ٱخْتِلَٰق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8444,"position":11,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'mā samiʿ''nā bihādhā fī l-milati l-ākhirati in hādhā illā ikh''tilāqun', 'এমন কথা তো আমাদের নিকট অতীতের মিল্লাতগুলো থেকে শুনিনি। এটা শুধু একটা মন-গড়া কথা।', 'We have not heard of this in the latest religion. This is not but a fabrication.', 'এমন কথা তো আমাদের নিকট অতীতের মিল্লাতগুলো থেকে শুনিনি। এটা শুধু একটা মন-গড়া কথা।', 'We have not heard of this in the latest religion. This is not but a fabrication.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038007.mp3', now()),
  (38, 8, '', '[{"id":9621,"position":1,"text_uthmani":"أَءُنزِلَ","transliteration":"a-unzila","translation_bn":"কি অবতরণ করা হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9622,"position":2,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9623,"position":3,"text_uthmani":"ٱلذِّكْرُ","transliteration":"l-dhik''ru","translation_bn":"কোরআন (কিতাব)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":9624,"position":4,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9625,"position":5,"text_uthmani":"بَيْنِنَا ۚ","transliteration":"bayninā","translation_bn":"আমাদের মধ্যে\"","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9627,"position":6,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":9628,"position":7,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9629,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9630,"position":9,"text_uthmani":"شَكٍّۢ","transliteration":"shakkin","translation_bn":"সন্দেহের","root":"شكك","lemma":"شَكّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9631,"position":10,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"সম্পর্কে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9632,"position":11,"text_uthmani":"ذِكْرِى ۖ","transliteration":"dhik''rī","translation_bn":"আমার কোরআন (অর্থাৎ কিতাব)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":9634,"position":12,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":9635,"position":13,"text_uthmani":"لَّمَّا","transliteration":"lammā","translation_bn":"করে নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":9636,"position":14,"text_uthmani":"يَذُوقُوا۟","transliteration":"yadhūqū","translation_bn":"তারা স্বাদ গ্রহণ","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9637,"position":15,"text_uthmani":"عَذَابِ","transliteration":"ʿadhābi","translation_bn":"আমার শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9638,"position":16,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'a-unzila ʿalayhi l-dhik''ru min bayninā bal hum fī shakkin min dhik''rī bal lammā yadhūqū ʿadhābi', 'আমাদের মধ্যে তার কাছেই কি বাণী পাঠানো হয়েছে?’ আসলে তারা আমার বাণীতে সন্দিহান, (তার কারণ) তারা এখনও আমার শাস্তির স্বাদ পায়নি।', 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.', 'আমাদের মধ্যে তার কাছেই কি বাণী পাঠানো হয়েছে?’ আসলে তারা আমার বাণীতে সন্দিহান, (তার কারণ) তারা এখনও আমার শাস্তির স্বাদ পায়নি।', 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038008.mp3', now()),
  (38, 9, '', '[{"id":10784,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10785,"position":2,"text_uthmani":"عِندَهُمْ","transliteration":"ʿindahum","translation_bn":"কাছে আছে তাদের","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":10786,"position":3,"text_uthmani":"خَزَآئِنُ","transliteration":"khazāinu","translation_bn":"ভান্ডারসমূহ","root":"خزن","lemma":"خَزَا^ئِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10787,"position":4,"text_uthmani":"رَحْمَةِ","transliteration":"raḥmati","translation_bn":"অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10788,"position":5,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10789,"position":6,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"(যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":10790,"position":7,"text_uthmani":"ٱلْوَهَّابِ","transliteration":"l-wahābi","translation_bn":"মহান দাতা","root":"وهب","lemma":"وَهَّاب","grammar_bn":"শব্দ"},{"id":10791,"position":8,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'am ʿindahum khazāinu raḥmati rabbika l-ʿazīzi l-wahābi', '(রহমতের ভান্ডার আছে আমার কাছে, তাত্থেকে যাকে যতখানি ইচ্ছে আমি দেই) তাদের কাছে কি তোমার প্রতিপালকের রহমতের ভান্ডার আছে যিনি মহা প্রতাপশালী, অসীম দাতা?', 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?', '(রহমতের ভান্ডার আছে আমার কাছে, তাত্থেকে যাকে যতখানি ইচ্ছে আমি দেই) তাদের কাছে কি তোমার প্রতিপালকের রহমতের ভান্ডার আছে যিনি মহা প্রতাপশালী, অসীম দাতা?', 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038009.mp3', now()),
  (38, 10, '', '[{"id":12044,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"না কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12045,"position":2,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের আছে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":12046,"position":3,"text_uthmani":"مُّلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":12047,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12048,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12049,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12050,"position":7,"text_uthmani":"بَيْنَهُمَا ۖ","transliteration":"baynahumā","translation_bn":"তাদের উভয়ের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":12052,"position":8,"text_uthmani":"فَلْيَرْتَقُوا۟","transliteration":"falyartaqū","translation_bn":"তারা আরোহণ করুক তাহ''লে","root":"رقي","lemma":"يَرْتَقُ","grammar_bn":"শব্দ"},{"id":12053,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সাহায্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12054,"position":10,"text_uthmani":"ٱلْأَسْبَـٰبِ","transliteration":"l-asbābi","translation_bn":"(উচ্চজগতের) সিঁড়ির","root":"سبب","lemma":"سَبَب","grammar_bn":"শব্দ"},{"id":12055,"position":11,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'am lahum mul''ku l-samāwāti wal-arḍi wamā baynahumā falyartaqū fī l-asbābi', 'কিংবা আকাশ ও পৃথিবী- এ দু’ এর মাঝে যা আছে তার সর্বময় ক্ষমতা কি তাদের আছে? তাহলে তারা বিশ্ব পরিচালনার উচ্চস্থানে উঠে পড়ুক।', 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.', 'কিংবা আকাশ ও পৃথিবী- এ দু’ এর মাঝে যা আছে তার সর্বময় ক্ষমতা কি তাদের আছে? তাহলে তারা বিশ্ব পরিচালনার উচ্চস্থানে উঠে পড়ুক।', 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038010.mp3', now()),
  (38, 11, '', '[{"id":13367,"position":1,"text_uthmani":"جُندٌۭ","transliteration":"jundun","translation_bn":"(এটা তো) একটি বাহিনী","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":13368,"position":2,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13369,"position":3,"text_uthmani":"هُنَالِكَ","transliteration":"hunālika","translation_bn":"এখানেই (মাক্কায়)","root":"—","lemma":"هُنَالِك\r","grammar_bn":"স্থানবাচক (Location)"},{"id":13370,"position":4,"text_uthmani":"مَهْزُومٌۭ","transliteration":"mahzūmun","translation_bn":"পরাজিত হবে","root":"هزم","lemma":"مَهْزُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":13371,"position":5,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13372,"position":6,"text_uthmani":"ٱلْأَحْزَابِ","transliteration":"l-aḥzābi","translation_bn":"(অনেকগুলো) বহু বাহিনীর","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":13373,"position":7,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'jundun mā hunālika mahzūmun mina l-aḥzābi', '(আরবের কাফিরদের) সম্মিলিত বাহিনীর এই দলটি এখানেই (অর্থাৎ এই মক্কা নগরীতেই একদিন) পরাজিত হবে।', '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].', '(আরবের কাফিরদের) সম্মিলিত বাহিনীর এই দলটি এখানেই (অর্থাৎ এই মক্কা নগরীতেই একদিন) পরাজিত হবে।', '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038011.mp3', now()),
  (38, 12, '', '[{"id":14648,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14649,"position":2,"text_uthmani":"قَبْلَهُمْ","transliteration":"qablahum","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":14650,"position":3,"text_uthmani":"قَوْمُ","transliteration":"qawmu","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":14651,"position":4,"text_uthmani":"نُوحٍۢ","transliteration":"nūḥin","translation_bn":"নূহের","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14652,"position":5,"text_uthmani":"وَعَادٌۭ","transliteration":"waʿādun","translation_bn":"ও আ''দ","root":"عود","lemma":"عَاد2","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14653,"position":6,"text_uthmani":"وَفِرْعَوْنُ","transliteration":"wafir''ʿawnu","translation_bn":"ও ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14654,"position":7,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"অধিপতি","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":14655,"position":8,"text_uthmani":"ٱلْأَوْتَادِ","transliteration":"l-awtādi","translation_bn":"কিলক ও স্তম্ভসমূহের","root":"وتد","lemma":"أَوْتَاد","grammar_bn":"শব্দ"},{"id":14656,"position":9,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat qablahum qawmu nūḥin waʿādun wafir''ʿawnu dhū l-awtādi', 'তাদের পূর্বে নূহের জাতি, ‘আদ ও বহু সেনা শিবিরের অধিপতি ফেরাউনও রসূলদেরকে মিথ্যে বলে অস্বীকার করেছিল।', 'The people of Noah denied before them, and [the tribe of] ''Aad and Pharaoh, the owner of stakes,', 'তাদের পূর্বে নূহের জাতি, ‘আদ ও বহু সেনা শিবিরের অধিপতি ফেরাউনও রসূলদেরকে মিথ্যে বলে অস্বীকার করেছিল।', 'The people of Noah denied before them, and [the tribe of] ''Aad and Pharaoh, the owner of stakes,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038012.mp3', now()),
  (38, 13, '', '[{"id":15733,"position":1,"text_uthmani":"وَثَمُودُ","transliteration":"wathamūdu","translation_bn":"ও সামূদ","root":"—","lemma":"ثَمُود","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15734,"position":2,"text_uthmani":"وَقَوْمُ","transliteration":"waqawmu","translation_bn":"ও জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15735,"position":3,"text_uthmani":"لُوطٍۢ","transliteration":"lūṭin","translation_bn":"লূতের","root":"—","lemma":"لُوط","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15736,"position":4,"text_uthmani":"وَأَصْحَـٰبُ","transliteration":"wa-aṣḥābu","translation_bn":"ও অধিবাসী","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15737,"position":5,"text_uthmani":"لْـَٔيْكَةِ ۚ","transliteration":"al''aykati","translation_bn":"আইকা’র","root":"—","lemma":"أَيْكَة","grammar_bn":"শব্দ"},{"id":15739,"position":6,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐ সবই (ছিলো)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":15740,"position":7,"text_uthmani":"ٱلْأَحْزَابُ","transliteration":"l-aḥzābu","translation_bn":"(বিশাল) সম্মিলিত বাহিনী","root":"حزب","lemma":"حِزْب","grammar_bn":"শব্দ"},{"id":15741,"position":8,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wathamūdu waqawmu lūṭin wa-aṣḥābu al''aykati ulāika l-aḥzābu', 'আর সামূদ, লূতের জাতি ও আইকাবাসী- এরা ছিল বিরাট বিরাট দল।', 'And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies.', 'আর সামূদ, লূতের জাতি ও আইকাবাসী- এরা ছিল বিরাট বিরাট দল।', 'And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038013.mp3', now()),
  (38, 14, '', '[{"id":16795,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":16796,"position":2,"text_uthmani":"كُلٌّ","transliteration":"kullun","translation_bn":"কেউই (ছিলো)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16797,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":16798,"position":4,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ করতো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16799,"position":5,"text_uthmani":"ٱلرُّسُلَ","transliteration":"l-rusula","translation_bn":"রাসূলগণকে","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":16800,"position":6,"text_uthmani":"فَحَقَّ","transliteration":"faḥaqqa","translation_bn":"অতঃপর কার্যকর হয়েছিলো","root":"حقق","lemma":"حَقَّ","grammar_bn":"শব্দ"},{"id":16801,"position":7,"text_uthmani":"عِقَابِ","transliteration":"ʿiqābi","translation_bn":"আমার শাস্তি","root":"عقب","lemma":"عِقَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":16802,"position":8,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'in kullun illā kadhaba l-rusula faḥaqqa ʿiqābi', 'এদের কেউই এমন নয় যারা রসূলদেরকে অস্বীকার করেনি। ফলে (তাদের উপর) আমার শাস্তি হয়েছিল অবধারিত।', 'Each of them denied the messengers, so My penalty was justified.', 'এদের কেউই এমন নয় যারা রসূলদেরকে অস্বীকার করেনি। ফলে (তাদের উপর) আমার শাস্তি হয়েছিল অবধারিত।', 'Each of them denied the messengers, so My penalty was justified.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038014.mp3', now()),
  (38, 15, '', '[{"id":17947,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17948,"position":2,"text_uthmani":"يَنظُرُ","transliteration":"yanẓuru","translation_bn":"অপেক্ষা করছে","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17949,"position":3,"text_uthmani":"هَـٰٓؤُلَآءِ","transliteration":"hāulāi","translation_bn":"এই সব (লোক)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":17950,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":17951,"position":5,"text_uthmani":"صَيْحَةًۭ","transliteration":"ṣayḥatan","translation_bn":"মহা গর্জনের","root":"صيح","lemma":"صَيْحَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17952,"position":6,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একটি (মাত্র)","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17953,"position":7,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17954,"position":8,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"তার জন্যে (থাকবে)","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":17955,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17956,"position":10,"text_uthmani":"فَوَاقٍۢ","transliteration":"fawāqin","translation_bn":"দম ফেলার অবকাশ","root":"فوق","lemma":"فَوَاق","grammar_bn":"বিশেষ্য (Noun)"},{"id":17957,"position":11,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yanẓuru hāulāi illā ṣayḥatan wāḥidatan mā lahā min fawāqin', '(আজ) এই লোকেরা তো প্রচন্ড একটা বিস্ফোরণের অপেক্ষায় আছে, (তা যখন ঘটবে) তাতে কোন বিরাম থাকবে না।', 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.', '(আজ) এই লোকেরা তো প্রচন্ড একটা বিস্ফোরণের অপেক্ষায় আছে, (তা যখন ঘটবে) তাতে কোন বিরাম থাকবে না।', 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038015.mp3', now()),
  (38, 16, '', '[{"id":18959,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"ও তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18960,"position":2,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18961,"position":3,"text_uthmani":"عَجِّل","transliteration":"ʿajjil","translation_bn":"শীঘ্র দাও","root":"عجل","lemma":"عَجَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18962,"position":4,"text_uthmani":"لَّنَا","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَّنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":18963,"position":5,"text_uthmani":"قِطَّنَا","transliteration":"qiṭṭanā","translation_bn":"আমাদের পাওনা","root":"قطط","lemma":"قِطّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18964,"position":6,"text_uthmani":"قَبْلَ","transliteration":"qabla","translation_bn":"পূর্বেই","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":18965,"position":7,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18966,"position":8,"text_uthmani":"ٱلْحِسَابِ","transliteration":"l-ḥisābi","translation_bn":"বিচারের\"","root":"حسب","lemma":"حِسَاب","grammar_bn":"শব্দ"},{"id":18967,"position":9,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū rabbanā ʿajjil lanā qiṭṭanā qabla yawmi l-ḥisābi', 'এরা বলে, হে আমাদের প্রতিপালক! হিসাবের দিনের আগেই আমাদের প্রাপ্য (শাস্তি) আমাদেরকে তাড়াতাড়ি দিয়ে দিন।', 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account"', 'এরা বলে, হে আমাদের প্রতিপালক! হিসাবের দিনের আগেই আমাদের প্রাপ্য (শাস্তি) আমাদেরকে তাড়াতাড়ি দিয়ে দিন।', 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038016.mp3', now()),
  (38, 17, '', '[{"id":20072,"position":1,"text_uthmani":"ٱصْبِرْ","transliteration":"iṣ''bir","translation_bn":"(হে নাবী) ধৈর্য্য ধরো","root":"صبر","lemma":"صَبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20073,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20074,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20075,"position":4,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলছে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20076,"position":5,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20077,"position":6,"text_uthmani":"عَبْدَنَا","transliteration":"ʿabdanā","translation_bn":"আমাদের দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20078,"position":7,"text_uthmani":"دَاوُۥدَ","transliteration":"dāwūda","translation_bn":"দাউদের (ঘটনা)","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20079,"position":8,"text_uthmani":"ذَا","transliteration":"dhā","translation_bn":"অধিকারী","root":"—","lemma":"ذَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":20080,"position":9,"text_uthmani":"ٱلْأَيْدِ ۖ","transliteration":"l-aydi","translation_bn":"(যে ছিলো) শক্তির","root":"ايد","lemma":"أَيْيد","grammar_bn":"শব্দ"},{"id":20082,"position":10,"text_uthmani":"إِنَّهُۥٓ","transliteration":"innahu","translation_bn":"নিশ্চয়ই সে (ছিলো)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20083,"position":11,"text_uthmani":"أَوَّابٌ","transliteration":"awwābun","translation_bn":"(আল্লাহ) অভিমুখী","root":"اوب","lemma":"أَوَّاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20084,"position":12,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'iṣ''bir ʿalā mā yaqūlūna wa-udh''kur ʿabdanā dāwūda dhā l-aydi innahu awwābun', 'এরা যা বলে তাতে তুমি ধৈর্য ধারণ কর, আর আমার বান্দাহ দাঊদের কথা স্মরণ কর, সে ছিল শক্তি-সামর্থ্যের অধিকারী আর বড়ই আল্লাহর দিকে প্রত্যাবর্তনকারী।', 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah].', 'এরা যা বলে তাতে তুমি ধৈর্য ধারণ কর, আর আমার বান্দাহ দাঊদের কথা স্মরণ কর, সে ছিল শক্তি-সামর্থ্যের অধিকারী আর বড়ই আল্লাহর দিকে প্রত্যাবর্তনকারী।', 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038017.mp3', now()),
  (38, 18, '', '[{"id":21161,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21162,"position":2,"text_uthmani":"سَخَّرْنَا","transliteration":"sakharnā","translation_bn":"আমরা বশ করে দিয়েছিলাম","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21163,"position":3,"text_uthmani":"ٱلْجِبَالَ","transliteration":"l-jibāla","translation_bn":"পাহাড়সমূহকে","root":"جبل","lemma":"جَبَل","grammar_bn":"শব্দ"},{"id":21164,"position":4,"text_uthmani":"مَعَهُۥ","transliteration":"maʿahu","translation_bn":"তার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":21165,"position":5,"text_uthmani":"يُسَبِّحْنَ","transliteration":"yusabbiḥ''na","translation_bn":"তারা পবিত্র মহিমা ঘোষণা করতো","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21166,"position":6,"text_uthmani":"بِٱلْعَشِىِّ","transliteration":"bil-ʿashiyi","translation_bn":"সন্ধ্যায়","root":"عشو","lemma":"عَشِىّ","grammar_bn":"অব্যয় (Preposition)"},{"id":21167,"position":7,"text_uthmani":"وَٱلْإِشْرَاقِ","transliteration":"wal-ish''rāqi","translation_bn":"ও সকালে","root":"شرق","lemma":"إِشْرَاق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21168,"position":8,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'innā sakharnā l-jibāla maʿahu yusabbiḥ''na bil-ʿashiyi wal-ish''rāqi', 'আমি পর্বতমালাকে কাজে নিয়োজিত করেছিলাম, তারা তার সঙ্গে সকাল-সন্ধ্যা আমার পবিত্রতা ও মহিমা ঘোষণা করত।', 'Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise.', 'আমি পর্বতমালাকে কাজে নিয়োজিত করেছিলাম, তারা তার সঙ্গে সকাল-সন্ধ্যা আমার পবিত্রতা ও মহিমা ঘোষণা করত।', 'Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038018.mp3', now()),
  (38, 19, '', '[{"id":22275,"position":1,"text_uthmani":"وَٱلطَّيْرَ","transliteration":"wal-ṭayra","translation_bn":"এবং পাখিগুলো","root":"طير","lemma":"طَيْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22276,"position":2,"text_uthmani":"مَحْشُورَةًۭ ۖ","transliteration":"maḥshūratan","translation_bn":"সমবেত হতো","root":"حشر","lemma":"مَحْشُورَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22278,"position":3,"text_uthmani":"كُلٌّۭ","transliteration":"kullun","translation_bn":"প্রত্যেকে (ছিলো)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22279,"position":4,"text_uthmani":"لَّهُۥٓ","transliteration":"lahu","translation_bn":"তাঁরই","root":"—","lemma":"لَّهُۥٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":22280,"position":5,"text_uthmani":"أَوَّابٌۭ","transliteration":"awwābun","translation_bn":"অভিমুখী (ও অনুগত)","root":"اوب","lemma":"أَوَّاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":22281,"position":6,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wal-ṭayra maḥshūratan kullun lahu awwābun', 'আর পাখীরা সমবেত হত, সকলেই তার সঙ্গে আল্লাহ অভিমুখী হত (তাসবীহ করার মাধ্যমে)।', 'And the birds were assembled, all with him repeating [praises].', 'আর পাখীরা সমবেত হত, সকলেই তার সঙ্গে আল্লাহ অভিমুখী হত (তাসবীহ করার মাধ্যমে)।', 'And the birds were assembled, all with him repeating [praises].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038019.mp3', now()),
  (38, 20, '', '[{"id":23329,"position":1,"text_uthmani":"وَشَدَدْنَا","transliteration":"washadadnā","translation_bn":"এবং আমরা সুদৃঢ় করেছিলাম","root":"شدد","lemma":"شَدَدْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23330,"position":2,"text_uthmani":"مُلْكَهُۥ","transliteration":"mul''kahu","translation_bn":"তার রাজত্বকে","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":23331,"position":3,"text_uthmani":"وَءَاتَيْنَـٰهُ","transliteration":"waātaynāhu","translation_bn":"এবং তাকে আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23332,"position":4,"text_uthmani":"ٱلْحِكْمَةَ","transliteration":"l-ḥik''mata","translation_bn":"প্রজ্ঞা","root":"حكم","lemma":"حِكْمَة","grammar_bn":"শব্দ"},{"id":23333,"position":5,"text_uthmani":"وَفَصْلَ","transliteration":"wafaṣla","translation_bn":"ও চূড়ান্তকারী","root":"فصل","lemma":"فَصْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23334,"position":6,"text_uthmani":"ٱلْخِطَابِ","transliteration":"l-khiṭābi","translation_bn":"বাগ্মিতা","root":"خطب","lemma":"خِطَاب","grammar_bn":"শব্দ"},{"id":23335,"position":7,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'washadadnā mul''kahu waātaynāhu l-ḥik''mata wafaṣla l-khiṭābi', 'আমি তার রাজত্বকে সুদৃঢ় করেছিলাম, আর তাকে দিয়েছিলাম জ্ঞান-বুদ্ধি-বিচক্ষণতা আর বিচারকার্য ও কথাবার্তায় উত্তম সিদ্ধান্ত দানের যোগ্যতা।', 'And We strengthened his kingdom and gave him wisdom and discernment in speech.', 'আমি তার রাজত্বকে সুদৃঢ় করেছিলাম, আর তাকে দিয়েছিলাম জ্ঞান-বুদ্ধি-বিচক্ষণতা আর বিচারকার্য ও কথাবার্তায় উত্তম সিদ্ধান্ত দানের যোগ্যতা।', 'And We strengthened his kingdom and gave him wisdom and discernment in speech.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038020.mp3', now()),
  (38, 21, '', '[{"id":24356,"position":1,"text_uthmani":"۞ وَهَلْ","transliteration":"wahal","translation_bn":"এবং কি","root":"—","lemma":"هَل\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24357,"position":2,"text_uthmani":"أَتَىٰكَ","transliteration":"atāka","translation_bn":"তোমার কাছে পৌঁছেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":24358,"position":3,"text_uthmani":"نَبَؤُا۟","transliteration":"naba-u","translation_bn":"খবর","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24359,"position":4,"text_uthmani":"ٱلْخَصْمِ","transliteration":"l-khaṣmi","translation_bn":"বিবদমান লোকদের","root":"خصم","lemma":"خَصْم","grammar_bn":"শব্দ"},{"id":24360,"position":5,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":24361,"position":6,"text_uthmani":"تَسَوَّرُوا۟","transliteration":"tasawwarū","translation_bn":"তারা দেয়াল টপকে ঢুকে পড়লো","root":"سور","lemma":"تَسَوَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24362,"position":7,"text_uthmani":"ٱلْمِحْرَابَ","transliteration":"l-miḥ''rāba","translation_bn":"খাসকামরায়","root":"حرب","lemma":"مِحْرَاب","grammar_bn":"শব্দ"},{"id":24363,"position":8,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wahal atāka naba-u l-khaṣmi idh tasawwarū l-miḥ''rāba', 'বিবদমান লোকেদের কথা তোমার কাছে পৌঁছেছে কি? যখন তারা প্রাচীর ডিঙ্গিয়ে ‘ইবাদাতখানায় আসলো,', 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -', 'বিবদমান লোকেদের কথা তোমার কাছে পৌঁছেছে কি? যখন তারা প্রাচীর ডিঙ্গিয়ে ‘ইবাদাতখানায় আসলো,', 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038021.mp3', now()),
  (38, 22, '', '[{"id":25408,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":25409,"position":2,"text_uthmani":"دَخَلُوا۟","transliteration":"dakhalū","translation_bn":"তারা প্রবেশ করেছিলো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25410,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25411,"position":4,"text_uthmani":"دَاوُۥدَ","transliteration":"dāwūda","translation_bn":"দাউদের","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25412,"position":5,"text_uthmani":"فَفَزِعَ","transliteration":"fafaziʿa","translation_bn":"সে তখন ভয় পেলো","root":"فزع","lemma":"فَزِعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25413,"position":6,"text_uthmani":"مِنْهُمْ ۖ","transliteration":"min''hum","translation_bn":"তাদের থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25415,"position":7,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25416,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":25417,"position":9,"text_uthmani":"تَخَفْ ۖ","transliteration":"takhaf","translation_bn":"ভয় পাবেন","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25419,"position":10,"text_uthmani":"خَصْمَانِ","transliteration":"khaṣmāni","translation_bn":"(আমরা) বিবদমান  দু''পক্ষ","root":"خصم","lemma":"خَصْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":25420,"position":11,"text_uthmani":"بَغَىٰ","transliteration":"baghā","translation_bn":"বাড়াবাড়ি করেছে","root":"بغي","lemma":"بَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25421,"position":12,"text_uthmani":"بَعْضُنَا","transliteration":"baʿḍunā","translation_bn":"আমাদের একজন","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":25422,"position":13,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25423,"position":14,"text_uthmani":"بَعْضٍۢ","transliteration":"baʿḍin","translation_bn":"অপরজনের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":25424,"position":15,"text_uthmani":"فَٱحْكُم","transliteration":"fa-uḥ''kum","translation_bn":"সুতরাং বিচার করে দিন","root":"حكم","lemma":"حَكَمَ","grammar_bn":"শব্দ"},{"id":25425,"position":16,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"আমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":25426,"position":17,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ন্যায়ভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":25427,"position":18,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25428,"position":19,"text_uthmani":"تُشْطِطْ","transliteration":"tush''ṭiṭ","translation_bn":"অবিচার করবেন","root":"شطط","lemma":"تُشْطِطْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25429,"position":20,"text_uthmani":"وَٱهْدِنَآ","transliteration":"wa-ih''dinā","translation_bn":"এবং আমাদের পরিচালনা করবেন","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25430,"position":21,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25431,"position":22,"text_uthmani":"سَوَآءِ","transliteration":"sawāi","translation_bn":"সরল সঠিক","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":25432,"position":23,"text_uthmani":"ٱلصِّرَٰطِ","transliteration":"l-ṣirāṭi","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"শব্দ"},{"id":25433,"position":24,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'idh dakhalū ʿalā dāwūda fafaziʿa min''hum qālū lā takhaf khaṣmāni baghā baʿḍunā ʿalā baʿḍin fa-uḥ''kum baynanā bil-ḥaqi walā tush''ṭiṭ wa-ih''dinā ilā sawāi l-ṣirāṭi', 'যখন তারা দাঊদের কাছে প্রবেশ করল, তাদেরকে দেখে সে ভয় পেয়ে গেল। তারা বলল- ভয় করবেন না, আমরা বিবাদের দু’পক্ষ, আমাদের একে অপরের উপর যুলম করেছে, কাজেই আমাদের মাঝে ন্যায্য বিচার করে দিন, অবিচার করবেন না, আর আমাদেরকে সোজা পথের নির্দেশ দিন।', 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.', 'যখন তারা দাঊদের কাছে প্রবেশ করল, তাদেরকে দেখে সে ভয় পেয়ে গেল। তারা বলল- ভয় করবেন না, আমরা বিবাদের দু’পক্ষ, আমাদের একে অপরের উপর যুলম করেছে, কাজেই আমাদের মাঝে ন্যায্য বিচার করে দিন, অবিচার করবেন না, আর আমাদেরকে সোজা পথের নির্দেশ দিন।', 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038022.mp3', now()),
  (38, 23, '', '[{"id":26465,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26466,"position":2,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":26467,"position":3,"text_uthmani":"أَخِى","transliteration":"akhī","translation_bn":"আমার ভাই","root":"اخو","lemma":"أَخ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26468,"position":4,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার আছে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":26469,"position":5,"text_uthmani":"تِسْعٌۭ","transliteration":"tis''ʿun","translation_bn":"নয়","root":"تسع","lemma":"تِسْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":26470,"position":6,"text_uthmani":"وَتِسْعُونَ","transliteration":"watis''ʿūna","translation_bn":"এবং নব্বই (অর্থাৎ নিরানব্বইটি)","root":"تسع","lemma":"تِسْع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26471,"position":7,"text_uthmani":"نَعْجَةًۭ","transliteration":"naʿjatan","translation_bn":"দুম্বী","root":"نعج","lemma":"نَعْجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26472,"position":8,"text_uthmani":"وَلِىَ","transliteration":"waliya","translation_bn":"ও আমার আছে","root":"—","lemma":"وَلِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":26473,"position":9,"text_uthmani":"نَعْجَةٌۭ","transliteration":"naʿjatun","translation_bn":"দুম্বী","root":"نعج","lemma":"نَعْجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26474,"position":10,"text_uthmani":"وَٰحِدَةٌۭ","transliteration":"wāḥidatun","translation_bn":"একটি","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26475,"position":11,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"তবুও সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":26476,"position":12,"text_uthmani":"أَكْفِلْنِيهَا","transliteration":"akfil''nīhā","translation_bn":"\"তা আমার দায়িত্বে দাও\"","root":"كفل","lemma":"أَكْفِلْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26477,"position":13,"text_uthmani":"وَعَزَّنِى","transliteration":"waʿazzanī","translation_bn":"এবং সে আমাকে পরাস্ত করে ফেললো","root":"عزز","lemma":"عَزَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26478,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26479,"position":15,"text_uthmani":"ٱلْخِطَابِ","transliteration":"l-khiṭābi","translation_bn":"কথাবার্তার\"","root":"خطب","lemma":"خِطَاب","grammar_bn":"শব্দ"},{"id":26480,"position":16,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā akhī lahu tis''ʿun watis''ʿūna naʿjatan waliya naʿjatun wāḥidatun faqāla akfil''nīhā waʿazzanī fī l-khiṭābi', 'এ হচ্ছে আমার ভাই, এর আছে নিরানব্বইটা দুম্বী, আর আমার আছে মাত্র একটা দুম্বী; তবুও সে বলে- এটি আমার তত্ত্বাবধানে দিয়ে দাও, আর সে যুক্তি-তর্কে আমাকে পরাস্ত করেছে।', 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, ''Entrust her to me,'' and he overpowered me in speech."', 'এ হচ্ছে আমার ভাই, এর আছে নিরানব্বইটা দুম্বী, আর আমার আছে মাত্র একটা দুম্বী; তবুও সে বলে- এটি আমার তত্ত্বাবধানে দিয়ে দাও, আর সে যুক্তি-তর্কে আমাকে পরাস্ত করেছে।', 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, ''Entrust her to me,'' and he overpowered me in speech."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038023.mp3', now()),
  (38, 24, '', '[{"id":27463,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27464,"position":2,"text_uthmani":"لَقَدْ","transliteration":"laqad","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27465,"position":3,"text_uthmani":"ظَلَمَكَ","transliteration":"ẓalamaka","translation_bn":"অবিচার করেছে তোমার উপর","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27466,"position":4,"text_uthmani":"بِسُؤَالِ","transliteration":"bisuāli","translation_bn":"(যোগ করার) দাবীর কারণে","root":"سال","lemma":"سُؤَال","grammar_bn":"অব্যয় (Preposition)"},{"id":27467,"position":5,"text_uthmani":"نَعْجَتِكَ","transliteration":"naʿjatika","translation_bn":"তোমার দুম্বী","root":"نعج","lemma":"نَعْجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27468,"position":6,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"সাথে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27469,"position":7,"text_uthmani":"نِعَاجِهِۦ ۖ","transliteration":"niʿājihi","translation_bn":"তার দুম্বীগুলোর","root":"نعج","lemma":"نَعْجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27471,"position":8,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27472,"position":9,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অনেকেই","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":27473,"position":10,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27474,"position":11,"text_uthmani":"ٱلْخُلَطَآءِ","transliteration":"l-khulaṭāi","translation_bn":"শরিকদের","root":"خلط","lemma":"خُلَطَا^ء","grammar_bn":"শব্দ"},{"id":27475,"position":12,"text_uthmani":"لَيَبْغِى","transliteration":"layabghī","translation_bn":"বাড়াবাড়ি করে অবশ্যই","root":"بغي","lemma":"بَغَىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":27476,"position":13,"text_uthmani":"بَعْضُهُمْ","transliteration":"baʿḍuhum","translation_bn":"তাদের একে","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":27477,"position":14,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27478,"position":15,"text_uthmani":"بَعْضٍ","transliteration":"baʿḍin","translation_bn":"অন্যের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":27479,"position":16,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"(তবে) ব্যতিক্রম","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27480,"position":17,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27481,"position":18,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27482,"position":19,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27483,"position":20,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকর্মসমূহ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":27484,"position":21,"text_uthmani":"وَقَلِيلٌۭ","transliteration":"waqalīlun","translation_bn":"এবং খুব কম (সংখ্যায়)","root":"قلل","lemma":"قَلِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27485,"position":22,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা\"","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27486,"position":23,"text_uthmani":"هُمْ ۗ","transliteration":"hum","translation_bn":"তারা\"","root":"—","lemma":"هُمْ ۗ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":27488,"position":24,"text_uthmani":"وَظَنَّ","transliteration":"waẓanna","translation_bn":"এবং তখনই বুঝতে পারলো","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27489,"position":25,"text_uthmani":"دَاوُۥدُ","transliteration":"dāwūdu","translation_bn":"দাউদ","root":"—","lemma":"دَاوُد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27490,"position":26,"text_uthmani":"أَنَّمَا","transliteration":"annamā","translation_bn":"যে আসলে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27491,"position":27,"text_uthmani":"فَتَنَّـٰهُ","transliteration":"fatannāhu","translation_bn":"তাকে আমরা পরীক্ষা করেছি","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27492,"position":28,"text_uthmani":"فَٱسْتَغْفَرَ","transliteration":"fa-is''taghfara","translation_bn":"সে ক্ষমা চাইলো তখন","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27493,"position":29,"text_uthmani":"رَبَّهُۥ","transliteration":"rabbahu","translation_bn":"তার রবের কাছে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":27494,"position":30,"text_uthmani":"وَخَرَّ","transliteration":"wakharra","translation_bn":"এবং লুটিয়ে পড়লো","root":"خرر","lemma":"خَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27495,"position":31,"text_uthmani":"رَاكِعًۭا","transliteration":"rākiʿan","translation_bn":"এবং রুকূতে (সিজদায়)","root":"ركع","lemma":"رَاكِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":27496,"position":32,"text_uthmani":"وَأَنَابَ ۩","transliteration":"wa-anāba","translation_bn":"এবং সে (আল্লাহ) অভিমুখী হলো","root":"نوب","lemma":"أَنَابَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27498,"position":33,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla laqad ẓalamaka bisuāli naʿjatika ilā niʿājihi wa-inna kathīran mina l-khulaṭāi layabghī baʿḍuhum ʿalā baʿḍin illā alladhīna āmanū waʿamilū l-ṣāliḥāti waqalīlun mā hum waẓanna dāwūdu annamā fatannāhu fa-is''taghfara rabbahu wakharra rākiʿan wa-anāba', 'দাঊদ বলল- তোমার (মাত্র) একটি দুম্বীকে তার দুম্বীর পালে যুক্ত করার দাবী করে (সে) তোমার প্রতি যুলম করেছে। শরীকদের অধিকাংশই সত্যিই পরস্পরের প্রতি বাড়াবাড়ি করে, কিন্তু যারা ঈমান আনে আর সৎ ‘আমাল করে তারা ব্যতীত, এদের সংখ্যা খুবই কম। দাঊদ বুঝতে পারল আমি তাকে পরীক্ষা করেছি। তখন সে তার প্রতিপালকের কাছে ক্ষমা প্রার্থনা করল, সাজদায় লুটিয়ে পড়ল ও তাঁর পানে ফিরে আসল।(সাজদাহ)', '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah].', 'দাঊদ বলল- তোমার (মাত্র) একটি দুম্বীকে তার দুম্বীর পালে যুক্ত করার দাবী করে (সে) তোমার প্রতি যুলম করেছে। শরীকদের অধিকাংশই সত্যিই পরস্পরের প্রতি বাড়াবাড়ি করে, কিন্তু যারা ঈমান আনে আর সৎ ‘আমাল করে তারা ব্যতীত, এদের সংখ্যা খুবই কম। দাঊদ বুঝতে পারল আমি তাকে পরীক্ষা করেছি। তখন সে তার প্রতিপালকের কাছে ক্ষমা প্রার্থনা করল, সাজদায় লুটিয়ে পড়ল ও তাঁর পানে ফিরে আসল।(সাজদাহ)', '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038024.mp3', now()),
  (38, 25, '', '[{"id":28501,"position":1,"text_uthmani":"فَغَفَرْنَا","transliteration":"faghafarnā","translation_bn":"আমরা তখন মাফ করলাম","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":28502,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":28503,"position":3,"text_uthmani":"ذَٰلِكَ ۖ","transliteration":"dhālika","translation_bn":"সেই (অপরাধ)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":28505,"position":4,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28506,"position":5,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":28507,"position":6,"text_uthmani":"عِندَنَا","transliteration":"ʿindanā","translation_bn":"আমাদের কাছে আছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":28508,"position":7,"text_uthmani":"لَزُلْفَىٰ","transliteration":"lazul''fā","translation_bn":"অবশ্যই নৈকট্যের মর্যাদা","root":"زلف","lemma":"زُلْفَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":28509,"position":8,"text_uthmani":"وَحُسْنَ","transliteration":"waḥus''na","translation_bn":"ও সুন্দর","root":"حسن","lemma":"حُسْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28510,"position":9,"text_uthmani":"مَـَٔابٍۢ","transliteration":"maābin","translation_bn":"পরিণাম","root":"اوب","lemma":"مَـ#َاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":28511,"position":10,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'faghafarnā lahu dhālika wa-inna lahu ʿindanā lazul''fā waḥus''na maābin', 'তখন আমি তার সে অপরাধ ক্ষমা করে দিলাম। তার জন্য আমার কাছে অবশ্যই আছে নৈকট্য আর উত্তম প্রত্যাবর্তনস্থল।', 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.', 'তখন আমি তার সে অপরাধ ক্ষমা করে দিলাম। তার জন্য আমার কাছে অবশ্যই আছে নৈকট্য আর উত্তম প্রত্যাবর্তনস্থল।', 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038025.mp3', now()),
  (38, 26, '', '[{"id":29417,"position":1,"text_uthmani":"يَـٰدَاوُۥدُ","transliteration":"yādāwūdu","translation_bn":"\"(আল্লাহ বললেন) হে দাউদ","root":"—","lemma":"دَاوُد","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":29418,"position":2,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29419,"position":3,"text_uthmani":"جَعَلْنَـٰكَ","transliteration":"jaʿalnāka","translation_bn":"তোমাকে আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29420,"position":4,"text_uthmani":"خَلِيفَةًۭ","transliteration":"khalīfatan","translation_bn":"প্রতিনিধি","root":"خلف","lemma":"خَلِيفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":29421,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29422,"position":6,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":29423,"position":7,"text_uthmani":"فَٱحْكُم","transliteration":"fa-uḥ''kum","translation_bn":"সুতরাং শাসন করো","root":"حكم","lemma":"حَكَمَ","grammar_bn":"শব্দ"},{"id":29424,"position":8,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":29425,"position":9,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":29426,"position":10,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ন্যায়ভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":29427,"position":11,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29428,"position":12,"text_uthmani":"تَتَّبِعِ","transliteration":"tattabiʿi","translation_bn":"অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29429,"position":13,"text_uthmani":"ٱلْهَوَىٰ","transliteration":"l-hawā","translation_bn":"খেয়ালখুশীর","root":"هوي","lemma":"هَوَا^ء","grammar_bn":"শব্দ"},{"id":29430,"position":14,"text_uthmani":"فَيُضِلَّكَ","transliteration":"fayuḍillaka","translation_bn":"তোমাকে তা হ''লে সরিয়ে দিবে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"কারণবাচক (Cause)"},{"id":29431,"position":15,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29432,"position":16,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29433,"position":17,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29435,"position":18,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29436,"position":19,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29437,"position":20,"text_uthmani":"يَضِلُّونَ","transliteration":"yaḍillūna","translation_bn":"বিভ্রান্ত হয়","root":"ضلل","lemma":"ضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29438,"position":21,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29439,"position":22,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29440,"position":23,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29441,"position":24,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":29442,"position":25,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":29443,"position":26,"text_uthmani":"شَدِيدٌۢ","transliteration":"shadīdun","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":29444,"position":27,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"একারণে যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29445,"position":28,"text_uthmani":"نَسُوا۟","transliteration":"nasū","translation_bn":"তারা ভুলে গিয়েছে","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29446,"position":29,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":29447,"position":30,"text_uthmani":"ٱلْحِسَابِ","transliteration":"l-ḥisābi","translation_bn":"বিচারের\"","root":"حسب","lemma":"حِسَاب","grammar_bn":"শব্দ"},{"id":29448,"position":31,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'yādāwūdu innā jaʿalnāka khalīfatan fī l-arḍi fa-uḥ''kum bayna l-nāsi bil-ḥaqi walā tattabiʿi l-hawā fayuḍillaka ʿan sabīli l-lahi inna alladhīna yaḍillūna ʿan sabīli l-lahi lahum ʿadhābun shadīdun bimā nasū yawma l-ḥisābi', 'হে দাঊদ! আমি তোমাকে পৃথিবীতে (আমার) প্রতিনিধি করেছি, কাজেই তুমি মানুষের মধ্যে ন্যায়পরায়ণতার সঙ্গে শাসন-বিচার পরিচালনা কর, এবং প্রবৃত্তির অনুসরণ করো না। কেননা, তা তোমাকে আল্লাহর পথ হতে বিচ্যুত করে ফেলবে। যারা আল্লাহর পথ থেকে বিচ্যুত হয়, তাদের জন্য আছে কঠিন ‘আযাব, কারণ তারা হিসাব-নিকাশের দিনকে ভুলে গেছে।', '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah." Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account.', 'হে দাঊদ! আমি তোমাকে পৃথিবীতে (আমার) প্রতিনিধি করেছি, কাজেই তুমি মানুষের মধ্যে ন্যায়পরায়ণতার সঙ্গে শাসন-বিচার পরিচালনা কর, এবং প্রবৃত্তির অনুসরণ করো না। কেননা, তা তোমাকে আল্লাহর পথ হতে বিচ্যুত করে ফেলবে। যারা আল্লাহর পথ থেকে বিচ্যুত হয়, তাদের জন্য আছে কঠিন ‘আযাব, কারণ তারা হিসাব-নিকাশের দিনকে ভুলে গেছে।', '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah." Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038026.mp3', now()),
  (38, 27, '', '[{"id":30424,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30425,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30426,"position":3,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":30427,"position":4,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30428,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30429,"position":6,"text_uthmani":"بَيْنَهُمَا","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":30430,"position":7,"text_uthmani":"بَـٰطِلًۭا ۚ","transliteration":"bāṭilan","translation_bn":"অনর্থক","root":"بطل","lemma":"بَٰطِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":30432,"position":8,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"সেটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":30433,"position":9,"text_uthmani":"ظَنُّ","transliteration":"ẓannu","translation_bn":"ধারণা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30434,"position":10,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30435,"position":11,"text_uthmani":"كَفَرُوا۟ ۚ","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30437,"position":12,"text_uthmani":"فَوَيْلٌۭ","transliteration":"fawaylun","translation_bn":"দুর্ভোগ সুতরাং","root":"—","lemma":"وَيْل","grammar_bn":"শব্দ"},{"id":30438,"position":13,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":30439,"position":14,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30440,"position":15,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30441,"position":16,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"(জাহান্নামের) আগুনের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":30442,"position":17,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā khalaqnā l-samāa wal-arḍa wamā baynahumā bāṭilan dhālika ẓannu alladhīna kafarū fawaylun lilladhīna kafarū mina l-nāri', 'আমি আকাশ, পৃথিবী ও এ দু’ এর মাঝে যা আছে তা অনর্থক সৃষ্টি করিনি। এ রকম ধারণা তো কাফিররা করে, কাজেই কাফিরদের জন্য আছে আগুনের দুর্ভোগ।', 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.', 'আমি আকাশ, পৃথিবী ও এ দু’ এর মাঝে যা আছে তা অনর্থক সৃষ্টি করিনি। এ রকম ধারণা তো কাফিররা করে, কাজেই কাফিরদের জন্য আছে আগুনের দুর্ভোগ।', 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038027.mp3', now()),
  (38, 28, '', '[{"id":31424,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31425,"position":2,"text_uthmani":"نَجْعَلُ","transliteration":"najʿalu","translation_bn":"গণ্য করবো আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31426,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31427,"position":4,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31428,"position":5,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31429,"position":6,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকর্মসমূহ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":31430,"position":7,"text_uthmani":"كَٱلْمُفْسِدِينَ","transliteration":"kal-muf''sidīna","translation_bn":"মতো বিপর্যয় সৃষ্টিকারীদের","root":"فسد","lemma":"مُفْسِد","grammar_bn":"অব্যয় (Preposition)"},{"id":31431,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31432,"position":9,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":31433,"position":10,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31434,"position":11,"text_uthmani":"نَجْعَلُ","transliteration":"najʿalu","translation_bn":"গণ্য করবো আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31435,"position":12,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীদেরকে","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":31436,"position":13,"text_uthmani":"كَٱلْفُجَّارِ","transliteration":"kal-fujāri","translation_bn":"পাপাচারীদের মতো","root":"فجر","lemma":"فُجَّار","grammar_bn":"অব্যয় (Preposition)"},{"id":31437,"position":14,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'am najʿalu alladhīna āmanū waʿamilū l-ṣāliḥāti kal-muf''sidīna fī l-arḍi am najʿalu l-mutaqīna kal-fujāri', 'যারা ঈমান আনে আর সৎ কাজ করে তাদেরকে কি আমি ওদের মত করব যারা দুনিয়াতে বিপর্যয় সৃষ্টি করে? আমি মুত্তাক্বীদের কি অপরাধীদের মত গণ্য করব?', 'Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?', 'যারা ঈমান আনে আর সৎ কাজ করে তাদেরকে কি আমি ওদের মত করব যারা দুনিয়াতে বিপর্যয় সৃষ্টি করে? আমি মুত্তাক্বীদের কি অপরাধীদের মত গণ্য করব?', 'Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038028.mp3', now()),
  (38, 29, '', '[{"id":32396,"position":1,"text_uthmani":"كِتَـٰبٌ","transliteration":"kitābun","translation_bn":"(হে নাবী) এই কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":32397,"position":2,"text_uthmani":"أَنزَلْنَـٰهُ","transliteration":"anzalnāhu","translation_bn":"তা আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32398,"position":3,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32399,"position":4,"text_uthmani":"مُبَـٰرَكٌۭ","transliteration":"mubārakun","translation_bn":"কল্যাণকর (কিতাব)","root":"برك","lemma":"مُبَارَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":32400,"position":5,"text_uthmani":"لِّيَدَّبَّرُوٓا۟","transliteration":"liyaddabbarū","translation_bn":"তারা চিন্তাভাবনা করে যেন","root":"دبر","lemma":"يَتَدَبَّرُ","grammar_bn":"শব্দ"},{"id":32401,"position":6,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"তাঁর আয়াতসমূহকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":32402,"position":7,"text_uthmani":"وَلِيَتَذَكَّرَ","transliteration":"waliyatadhakkara","translation_bn":"এবং উপদেশ নেয় যেন","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32403,"position":8,"text_uthmani":"أُو۟لُوا۟","transliteration":"ulū","translation_bn":"সম্পন্নরা","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":32404,"position":9,"text_uthmani":"ٱلْأَلْبَـٰبِ","transliteration":"l-albābi","translation_bn":"বুদ্ধি-জ্ঞান","root":"لبب","lemma":"أَلْبَٰب","grammar_bn":"শব্দ"},{"id":32405,"position":10,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'kitābun anzalnāhu ilayka mubārakun liyaddabbarū āyātihi waliyatadhakkara ulū l-albābi', 'এটি একটি কল্যাণময় কিতাব তোমার কাছে অবতীর্ণ করেছি যাতে তারা এর আয়াতগুলোর প্রতি চিন্তা-ভাবনা করে, আর জ্ঞান-বুদ্ধিসম্পন্ন লোকেরা উপদেশ গ্রহণ করে থাকে।', '[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded.', 'এটি একটি কল্যাণময় কিতাব তোমার কাছে অবতীর্ণ করেছি যাতে তারা এর আয়াতগুলোর প্রতি চিন্তা-ভাবনা করে, আর জ্ঞান-বুদ্ধিসম্পন্ন লোকেরা উপদেশ গ্রহণ করে থাকে।', '[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038029.mp3', now()),
  (38, 30, '', '[{"id":33241,"position":1,"text_uthmani":"وَوَهَبْنَا","transliteration":"wawahabnā","translation_bn":"এবং আমরা দান করেছিলাম","root":"وهب","lemma":"وَهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33242,"position":2,"text_uthmani":"لِدَاوُۥدَ","transliteration":"lidāwūda","translation_bn":"দাউদের জন্য","root":"—","lemma":"دَاوُد","grammar_bn":"অব্যয় (Preposition)"},{"id":33243,"position":3,"text_uthmani":"سُلَيْمَـٰنَ ۚ","transliteration":"sulaymāna","translation_bn":"(তার পুত্র) সুলায়মানকে","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":33245,"position":4,"text_uthmani":"نِعْمَ","transliteration":"niʿ''ma","translation_bn":"অতি উত্তম","root":"نعم","lemma":"نِعْمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33246,"position":5,"text_uthmani":"ٱلْعَبْدُ ۖ","transliteration":"l-ʿabdu","translation_bn":"দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"শব্দ"},{"id":33248,"position":6,"text_uthmani":"إِنَّهُۥٓ","transliteration":"innahu","translation_bn":"সে নিশ্চযই় (ছিলো)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":33249,"position":7,"text_uthmani":"أَوَّابٌ","transliteration":"awwābun","translation_bn":"অতিশয় (আল্লাহ) অভিমুখী","root":"اوب","lemma":"أَوَّاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":33250,"position":8,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'wawahabnā lidāwūda sulaymāna niʿ''ma l-ʿabdu innahu awwābun', 'আমি দাঊদের জন্য দান করেছিলাম সুলাইমান। কতই না উত্তম বান্দাহ! বার বার (অনুশোচনাভরে) আল্লাহর দিকে প্রত্যাবর্তনকারী।', 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah].', 'আমি দাঊদের জন্য দান করেছিলাম সুলাইমান। কতই না উত্তম বান্দাহ! বার বার (অনুশোচনাভরে) আল্লাহর দিকে প্রত্যাবর্তনকারী।', 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038030.mp3', now()),
  (38, 31, '', '[{"id":34288,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":34289,"position":2,"text_uthmani":"عُرِضَ","transliteration":"ʿuriḍa","translation_bn":"উপস্হিত করা হলো","root":"عرض","lemma":"عَرَضَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34290,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার সামনে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34291,"position":4,"text_uthmani":"بِٱلْعَشِىِّ","transliteration":"bil-ʿashiyi","translation_bn":"সন্ধ্যায়","root":"عشو","lemma":"عَشِىّ","grammar_bn":"অব্যয় (Preposition)"},{"id":34292,"position":5,"text_uthmani":"ٱلصَّـٰفِنَـٰتُ","transliteration":"l-ṣāfinātu","translation_bn":"দ্রুতগামী ঘোড়াসমূহ","root":"صفن","lemma":"صَّٰفِنَٰت","grammar_bn":"শব্দ"},{"id":34293,"position":6,"text_uthmani":"ٱلْجِيَادُ","transliteration":"l-jiyādu","translation_bn":"উৎকৃষ্টমানের (ঘোড়া)","root":"جود","lemma":"جِيَاد","grammar_bn":"শব্দ"},{"id":34294,"position":7,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'idh ʿuriḍa ʿalayhi bil-ʿashiyi l-ṣāfinātu l-jiyādu', 'যখন তার সামনে সন্ধ্যাকালে উৎকৃষ্ট জাতের দ্রুতগামী অশ্ব উপস্থিত করা হল,', '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.', 'যখন তার সামনে সন্ধ্যাকালে উৎকৃষ্ট জাতের দ্রুতগামী অশ্ব উপস্থিত করা হল,', '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038031.mp3', now()),
  (38, 32, '', '[{"id":35139,"position":1,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"তখন সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35140,"position":2,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":35141,"position":3,"text_uthmani":"أَحْبَبْتُ","transliteration":"aḥbabtu","translation_bn":"আমি ভালোবেসেছি","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35142,"position":4,"text_uthmani":"حُبَّ","transliteration":"ḥubba","translation_bn":"ভালোবাসা","root":"حبب","lemma":"حُبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":35143,"position":5,"text_uthmani":"ٱلْخَيْرِ","transliteration":"l-khayri","translation_bn":"(এই) সম্পদের","root":"خير","lemma":"خَيْر","grammar_bn":"শব্দ"},{"id":35144,"position":6,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"কারণে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35145,"position":7,"text_uthmani":"ذِكْرِ","transliteration":"dhik''ri","translation_bn":"স্মরণের","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":35146,"position":8,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রবের\"","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":35147,"position":9,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"এমনকি (যখন)","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35148,"position":10,"text_uthmani":"تَوَارَتْ","transliteration":"tawārat","translation_bn":"অদৃশ্য হয়ে গেলো","root":"وري","lemma":"تَوَارَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35149,"position":11,"text_uthmani":"بِٱلْحِجَابِ","transliteration":"bil-ḥijābi","translation_bn":"(চোখের) আড়ালে","root":"حجب","lemma":"حِجَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":35150,"position":12,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'faqāla innī aḥbabtu ḥubba l-khayri ʿan dhik''ri rabbī ḥattā tawārat bil-ḥijābi', 'তখন সে বলল- আমি আমার প্রতিপালকের স্মরণ হতে ধন-সম্পদকে বেশি ভালবেসে ফেলেছি, এমনকি সূর্য (রাতের) পর্দায় লুকিয়ে গেছে।', 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness]."', 'তখন সে বলল- আমি আমার প্রতিপালকের স্মরণ হতে ধন-সম্পদকে বেশি ভালবেসে ফেলেছি, এমনকি সূর্য (রাতের) পর্দায় লুকিয়ে গেছে।', 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness]."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038032.mp3', now()),
  (38, 33, '', '[{"id":35495,"position":1,"text_uthmani":"رُدُّوهَا","transliteration":"ruddūhā","translation_bn":"\"(সে বললো) সেগুলো ফিরিয়ে আনো","root":"ردد","lemma":"رَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35496,"position":2,"text_uthmani":"عَلَىَّ ۖ","transliteration":"ʿalayya","translation_bn":"আমার কাছে\"","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35498,"position":3,"text_uthmani":"فَطَفِقَ","transliteration":"faṭafiqa","translation_bn":"সে অতঃপর শুরু করলো","root":"طفق","lemma":"طَفِقَ","grammar_bn":"শব্দ"},{"id":35499,"position":4,"text_uthmani":"مَسْحًۢا","transliteration":"masḥan","translation_bn":"(হাত) বুলাতে","root":"مسح","lemma":"مَسْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":35500,"position":5,"text_uthmani":"بِٱلسُّوقِ","transliteration":"bil-sūqi","translation_bn":"(ঘোড়ার) পাগুলোর উপর","root":"سوق","lemma":"سُّوق","grammar_bn":"অব্যয় (Preposition)"},{"id":35501,"position":6,"text_uthmani":"وَٱلْأَعْنَاقِ","transliteration":"wal-aʿnāqi","translation_bn":"ও ঘাড়ে","root":"عنق","lemma":"عُنُق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35502,"position":7,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'ruddūhā ʿalayya faṭafiqa masḥan bil-sūqi wal-aʿnāqi', '(সে তার সন্ধ্যাকালীন ‘ইবাদাত সম্পন্ন করে (বলল) ওগুলোকে আমার কাছে আবার এনে হাজির কর। তখন সে তাদের পায়ে ও গলায় হাত বুলাতে লাগল।', '[He said], "Return them to me," and set about striking [their] legs and necks.', '(সে তার সন্ধ্যাকালীন ‘ইবাদাত সম্পন্ন করে (বলল) ওগুলোকে আমার কাছে আবার এনে হাজির কর। তখন সে তাদের পায়ে ও গলায় হাত বুলাতে লাগল।', '[He said], "Return them to me," and set about striking [their] legs and necks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038033.mp3', now()),
  (38, 34, '', '[{"id":36861,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36862,"position":2,"text_uthmani":"فَتَنَّا","transliteration":"fatannā","translation_bn":"আমরা পরীক্ষা করেছিলাম","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36863,"position":3,"text_uthmani":"سُلَيْمَـٰنَ","transliteration":"sulaymāna","translation_bn":"সুলায়মানকে","root":"—","lemma":"سُلَيْمَٰن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36864,"position":4,"text_uthmani":"وَأَلْقَيْنَا","transliteration":"wa-alqaynā","translation_bn":"ও আমরা রেখে দিলাম","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36865,"position":5,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36866,"position":6,"text_uthmani":"كُرْسِيِّهِۦ","transliteration":"kur''siyyihi","translation_bn":"তার আসনের","root":"كرس","lemma":"كُرْسِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36867,"position":7,"text_uthmani":"جَسَدًۭا","transliteration":"jasadan","translation_bn":"একটি দেহ","root":"جسد","lemma":"جَسَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":36868,"position":8,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36869,"position":9,"text_uthmani":"أَنَابَ","transliteration":"anāba","translation_bn":"সে মুখ ফেরালো","root":"نوب","lemma":"أَنَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36870,"position":10,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad fatannā sulaymāna wa-alqaynā ʿalā kur''siyyihi jasadan thumma anāba', 'আমি সুলাইমানকে পরীক্ষা করলাম (তার রাজত্ব কেড়ে নিয়ে) আর তার সিংহাসনের উপর রাখলাম একটি দেহ (শয়তানকে, কাজেই সুলাইমান কিছু সময়ের জন্য তার রাজত্ব হারাল) অতঃপর সে (আনুগত্য নিয়ে অনুশোচনা করে আল্লাহর পানে) প্রত্যাবর্তন করল (আর আল্লাহর অনুগ্রহে ফিরে পেল তার রাজত্ব ও সিংহাসন)।', 'And We certainly tried Solomon and placed on his throne a body; then he returned.', 'আমি সুলাইমানকে পরীক্ষা করলাম (তার রাজত্ব কেড়ে নিয়ে) আর তার সিংহাসনের উপর রাখলাম একটি দেহ (শয়তানকে, কাজেই সুলাইমান কিছু সময়ের জন্য তার রাজত্ব হারাল) অতঃপর সে (আনুগত্য নিয়ে অনুশোচনা করে আল্লাহর পানে) প্রত্যাবর্তন করল (আর আল্লাহর অনুগ্রহে ফিরে পেল তার রাজত্ব ও সিংহাসন)।', 'And We certainly tried Solomon and placed on his throne a body; then he returned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038034.mp3', now()),
  (38, 35, '', '[{"id":37695,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37696,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37697,"position":3,"text_uthmani":"ٱغْفِرْ","transliteration":"igh''fir","translation_bn":"মাফ করো","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37698,"position":4,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":37699,"position":5,"text_uthmani":"وَهَبْ","transliteration":"wahab","translation_bn":"ও দাও","root":"وهب","lemma":"وَهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37700,"position":6,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমাকে","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":37701,"position":7,"text_uthmani":"مُلْكًۭا","transliteration":"mul''kan","translation_bn":"(এমন) রাজত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":37702,"position":8,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":37703,"position":9,"text_uthmani":"يَنۢبَغِى","transliteration":"yanbaghī","translation_bn":"শোভনীয় হবে (যা)","root":"بغي","lemma":"يَن[بَغِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":37704,"position":10,"text_uthmani":"لِأَحَدٍۢ","transliteration":"li-aḥadin","translation_bn":"কারও জন্যে","root":"احد","lemma":"أَحَد","grammar_bn":"অব্যয় (Preposition)"},{"id":37705,"position":11,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37706,"position":12,"text_uthmani":"بَعْدِىٓ ۖ","transliteration":"baʿdī","translation_bn":"আমার পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":37708,"position":13,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37709,"position":14,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমিই","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":37710,"position":15,"text_uthmani":"ٱلْوَهَّابُ","transliteration":"l-wahābu","translation_bn":"মহাদাতা\"","root":"وهب","lemma":"وَهَّاب","grammar_bn":"শব্দ"},{"id":37711,"position":16,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi igh''fir lī wahab lī mul''kan lā yanbaghī li-aḥadin min baʿdī innaka anta l-wahābu', 'সে বলল- হে আমার প্রতিপালক! আমাকে ক্ষমা কর, আর আমাকে এমন রাজ্য দান কর যা আমার পরে আর কারো জন্য শোভনীয় হবে না। তুমি হলে পরম দাতা।', 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."', 'সে বলল- হে আমার প্রতিপালক! আমাকে ক্ষমা কর, আর আমাকে এমন রাজ্য দান কর যা আমার পরে আর কারো জন্য শোভনীয় হবে না। তুমি হলে পরম দাতা।', 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038035.mp3', now()),
  (38, 36, '', '[{"id":37948,"position":1,"text_uthmani":"فَسَخَّرْنَا","transliteration":"fasakharnā","translation_bn":"আমরা তখন অধীন করে দিলাম","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"শব্দ"},{"id":37949,"position":2,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":37950,"position":3,"text_uthmani":"ٱلرِّيحَ","transliteration":"l-rīḥa","translation_bn":"বাতাসকে","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":37951,"position":4,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"বয়ে যেতো","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37952,"position":5,"text_uthmani":"بِأَمْرِهِۦ","transliteration":"bi-amrihi","translation_bn":"তার আদেশে","root":"امر","lemma":"أَمْر","grammar_bn":"অব্যয় (Preposition)"},{"id":37953,"position":6,"text_uthmani":"رُخَآءً","transliteration":"rukhāan","translation_bn":"গতিতে","root":"رخو","lemma":"رُخَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":37954,"position":7,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখানে","root":"حيث\r","lemma":"حَيْث","grammar_bn":"স্থানবাচক (Location)"},{"id":37955,"position":8,"text_uthmani":"أَصَابَ","transliteration":"aṣāba","translation_bn":"তিনি চাইতেন","root":"صوب","lemma":"أَصَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37956,"position":9,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'fasakharnā lahu l-rīḥa tajrī bi-amrihi rukhāan ḥaythu aṣāba', 'অতঃপর বাতাসকে তার অধীন করে দিলাম, তার আদেশে তা মৃদুমন্দ গতিতে প্রবাহিত হত, যেখানে সে ইচ্ছে করত।', 'So We subjected to him the wind blowing by his command, gently, wherever he directed,', 'অতঃপর বাতাসকে তার অধীন করে দিলাম, তার আদেশে তা মৃদুমন্দ গতিতে প্রবাহিত হত, যেখানে সে ইচ্ছে করত।', 'So We subjected to him the wind blowing by his command, gently, wherever he directed,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038036.mp3', now()),
  (38, 37, '', '[{"id":39430,"position":1,"text_uthmani":"وَٱلشَّيَـٰطِينَ","transliteration":"wal-shayāṭīna","translation_bn":"এবং শয়তানগুলোকেও (অধীন করেছিলাম)","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39431,"position":2,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেকে (যারা ছিলো)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":39432,"position":3,"text_uthmani":"بَنَّآءٍۢ","transliteration":"bannāin","translation_bn":"স্হপতি","root":"بني","lemma":"بَنَّا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":39433,"position":4,"text_uthmani":"وَغَوَّاصٍۢ","transliteration":"waghawwāṣin","translation_bn":"ও ডুবুরী","root":"غوص","lemma":"غَوَّاص","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39434,"position":5,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-shayāṭīna kulla bannāin waghawwāṣin', 'আর শয়ত্বানদেরকেও (তার বশীভূত করে দিলাম), সব ছিল নির্মাতা ও ডুবুরী।', 'And [also] the devils [of jinn] - every builder and diver', 'আর শয়ত্বানদেরকেও (তার বশীভূত করে দিলাম), সব ছিল নির্মাতা ও ডুবুরী।', 'And [also] the devils [of jinn] - every builder and diver', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038037.mp3', now()),
  (38, 38, '', '[{"id":40247,"position":1,"text_uthmani":"وَءَاخَرِينَ","transliteration":"waākharīna","translation_bn":"এবং অন্যান্যদেরকে","root":"اخر","lemma":"ا^خَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40248,"position":2,"text_uthmani":"مُقَرَّنِينَ","transliteration":"muqarranīna","translation_bn":"আবদ্ধ (করলাম)","root":"قرن","lemma":"مُّقَرَّنِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":40249,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40250,"position":4,"text_uthmani":"ٱلْأَصْفَادِ","transliteration":"l-aṣfādi","translation_bn":"শেকলসমূহের","root":"صفد","lemma":"أَصْفَاد","grammar_bn":"শব্দ"},{"id":40251,"position":5,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'waākharīna muqarranīna fī l-aṣfādi', 'আর অন্যদেরকেও যারা ছিল শৃঙ্খলে আবদ্ধ।', 'And others bound together in shackles.', 'আর অন্যদেরকেও যারা ছিল শৃঙ্খলে আবদ্ধ।', 'And others bound together in shackles.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038038.mp3', now()),
  (38, 39, '', '[{"id":40995,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"(আমি বললাম) এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":40996,"position":2,"text_uthmani":"عَطَآؤُنَا","transliteration":"ʿaṭāunā","translation_bn":"আমাদের দান","root":"عطو","lemma":"عَطَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":40997,"position":3,"text_uthmani":"فَٱمْنُنْ","transliteration":"fa-um''nun","translation_bn":"সুতরাং দান করো (যাকে চাও)","root":"منن","lemma":"مَنَّ","grammar_bn":"শব্দ"},{"id":40998,"position":4,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40999,"position":5,"text_uthmani":"أَمْسِكْ","transliteration":"amsik","translation_bn":"রেখে দাও (নিজের জন্যে)","root":"مسك","lemma":"أَمْسَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41000,"position":6,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ছাড়াই","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":41001,"position":7,"text_uthmani":"حِسَابٍۢ","transliteration":"ḥisābin","translation_bn":"কোনো হিসেব\"","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":41002,"position":8,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā ʿaṭāunā fa-um''nun aw amsik bighayri ḥisābin', '(আমি তাকে বললাম) এ সব আমারই দান। এত্থেকে তুমি যাকে ইচ্ছে দাও, কিংবা (না দিয়ে) নিজের কাছে রেখে দাও, তোমাকে কোন হিসেব দিতে হবে না।', '[We said], "This is Our gift, so grant or withhold without account."', '(আমি তাকে বললাম) এ সব আমারই দান। এত্থেকে তুমি যাকে ইচ্ছে দাও, কিংবা (না দিয়ে) নিজের কাছে রেখে দাও, তোমাকে কোন হিসেব দিতে হবে না।', '[We said], "This is Our gift, so grant or withhold without account."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038039.mp3', now()),
  (38, 40, '', '[{"id":41266,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41267,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":41268,"position":3,"text_uthmani":"عِندَنَا","transliteration":"ʿindanā","translation_bn":"আমাদের কাছে আছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":41269,"position":4,"text_uthmani":"لَزُلْفَىٰ","transliteration":"lazul''fā","translation_bn":"অবশ্যই নৈকট্যের মর্যাদা","root":"زلف","lemma":"زُلْفَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":41270,"position":5,"text_uthmani":"وَحُسْنَ","transliteration":"waḥus''na","translation_bn":"ও সুন্দর","root":"حسن","lemma":"حُسْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41271,"position":6,"text_uthmani":"مَـَٔابٍۢ","transliteration":"maābin","translation_bn":"প্রত্যাবর্তন স্থান (পরিণাম)","root":"اوب","lemma":"مَـ#َاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":41272,"position":7,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna lahu ʿindanā lazul''fā waḥus''na maābin', 'তার জন্য আমার কাছে অবশ্যই আছে নৈকট্য আর উত্তম প্রত্যাবর্তনস্থল।', 'And indeed, for him is nearness to Us and a good place of return.', 'তার জন্য আমার কাছে অবশ্যই আছে নৈকট্য আর উত্তম প্রত্যাবর্তনস্থল।', 'And indeed, for him is nearness to Us and a good place of return.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038040.mp3', now()),
  (38, 41, '', '[{"id":42632,"position":1,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42633,"position":2,"text_uthmani":"عَبْدَنَآ","transliteration":"ʿabdanā","translation_bn":"আমাদের দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":42634,"position":3,"text_uthmani":"أَيُّوبَ","transliteration":"ayyūba","translation_bn":"আইয়ূবকে","root":"—","lemma":"أَيُّوب","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":42635,"position":4,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":42636,"position":5,"text_uthmani":"نَادَىٰ","transliteration":"nādā","translation_bn":"সে ডেকে ছিলো","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42637,"position":6,"text_uthmani":"رَبَّهُۥٓ","transliteration":"rabbahu","translation_bn":"তার রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":42638,"position":7,"text_uthmani":"أَنِّى","transliteration":"annī","translation_bn":"\"নিশ্চযই় আমি","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":42639,"position":8,"text_uthmani":"مَسَّنِىَ","transliteration":"massaniya","translation_bn":"আমাকে স্পর্শ করেছে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42640,"position":9,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":42641,"position":10,"text_uthmani":"بِنُصْبٍۢ","transliteration":"binuṣ''bin","translation_bn":"কষ্ট দিয়ে","root":"نصب","lemma":"نُصْب","grammar_bn":"অব্যয় (Preposition)"},{"id":42642,"position":11,"text_uthmani":"وَعَذَابٍ","transliteration":"waʿadhābin","translation_bn":"ও যন্ত্রণায়\"","root":"عذب","lemma":"عَذَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42643,"position":12,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur ʿabdanā ayyūba idh nādā rabbahu annī massaniya l-shayṭānu binuṣ''bin waʿadhābin', 'স্মরণ কর আমার বান্দা আইয়ূবের কথা, যখন সে তার প্রতিপালককে ডেকে বলেছিল- শয়ত্বান আমাকে কষ্ট আর ‘আযাবে ফেলেছে (অর্থাৎ আমার ধৈর্যচ্যুতি ঘটিয়ে আমাকে আল্লাহর অকৃতজ্ঞ বান্দাহ বানানোর জন্য কুমন্ত্রণা দিয়ে চলেছে)।', 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."', 'স্মরণ কর আমার বান্দা আইয়ূবের কথা, যখন সে তার প্রতিপালককে ডেকে বলেছিল- শয়ত্বান আমাকে কষ্ট আর ‘আযাবে ফেলেছে (অর্থাৎ আমার ধৈর্যচ্যুতি ঘটিয়ে আমাকে আল্লাহর অকৃতজ্ঞ বান্দাহ বানানোর জন্য কুমন্ত্রণা দিয়ে চলেছে)।', 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038041.mp3', now()),
  (38, 42, '', '[{"id":42874,"position":1,"text_uthmani":"ٱرْكُضْ","transliteration":"ur''kuḍ","translation_bn":"\"(তাকে বললাম) আঘাত করো","root":"ركض","lemma":"يَرْكُضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42875,"position":2,"text_uthmani":"بِرِجْلِكَ ۖ","transliteration":"birij''lika","translation_bn":"তোমার পা দিয়ে (যমীনে)","root":"رجل","lemma":"رِجْل","grammar_bn":"অব্যয় (Preposition)"},{"id":42877,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":42878,"position":4,"text_uthmani":"مُغْتَسَلٌۢ","transliteration":"mugh''tasalun","translation_bn":"গোসলের পানি","root":"غسل","lemma":"مُغْتَسَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":42879,"position":5,"text_uthmani":"بَارِدٌۭ","transliteration":"bāridun","translation_bn":"ঠান্ডা","root":"برد","lemma":"بَارِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":42880,"position":6,"text_uthmani":"وَشَرَابٌۭ","transliteration":"washarābun","translation_bn":"ও সুপেয় পানীয়\"","root":"شرب","lemma":"شَرَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42881,"position":7,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'ur''kuḍ birij''lika hādhā mugh''tasalun bāridun washarābun', '(আমি তাকে নির্দেশ দিলাম) তুমি তোমার পা দিয়ে যমীনে আঘাত কর, এই তো ঠান্ডা পানি, গোসলের জন্য আর পানের জন্য।', '[So he was told], "Strike [the ground] with your foot; this is a [spring for] a cool bath and drink."', '(আমি তাকে নির্দেশ দিলাম) তুমি তোমার পা দিয়ে যমীনে আঘাত কর, এই তো ঠান্ডা পানি, গোসলের জন্য আর পানের জন্য।', '[So he was told], "Strike [the ground] with your foot; this is a [spring for] a cool bath and drink."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038042.mp3', now()),
  (38, 43, '', '[{"id":44116,"position":1,"text_uthmani":"وَوَهَبْنَا","transliteration":"wawahabnā","translation_bn":"এবং আমরা (ফিরিয়ে) দিলাম","root":"وهب","lemma":"وَهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44117,"position":2,"text_uthmani":"لَهُۥٓ","transliteration":"lahu","translation_bn":"তার কাছে","root":"—","lemma":"لَهُۥٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":44118,"position":3,"text_uthmani":"أَهْلَهُۥ","transliteration":"ahlahu","translation_bn":"তার পরিবারকে","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":44119,"position":4,"text_uthmani":"وَمِثْلَهُم","transliteration":"wamith''lahum","translation_bn":"আরও তাদের মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44120,"position":5,"text_uthmani":"مَّعَهُمْ","transliteration":"maʿahum","translation_bn":"তাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":44121,"position":6,"text_uthmani":"رَحْمَةًۭ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহ স্বরূপ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":44122,"position":7,"text_uthmani":"مِّنَّا","transliteration":"minnā","translation_bn":"আমাদের থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":44123,"position":8,"text_uthmani":"وَذِكْرَىٰ","transliteration":"wadhik''rā","translation_bn":"এবং শিক্ষা","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44124,"position":9,"text_uthmani":"لِأُو۟لِى","transliteration":"li-ulī","translation_bn":"সম্পন্নদের জন্যে","root":"اول","lemma":"أُولِى","grammar_bn":"অব্যয় (Preposition)"},{"id":44125,"position":10,"text_uthmani":"ٱلْأَلْبَـٰبِ","transliteration":"l-albābi","translation_bn":"বিবেক-বুদ্ধি","root":"لبب","lemma":"أَلْبَٰب","grammar_bn":"শব্দ"},{"id":44126,"position":11,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'wawahabnā lahu ahlahu wamith''lahum maʿahum raḥmatan minnā wadhik''rā li-ulī l-albābi', 'আমি তাকে দান করলাম তার পরিবার-পরিজন আর তাদের সাথে তাদের মত আরো, আমার রহমত স্বরূপ আর জ্ঞান-বুদ্ধিসম্পন্ন লোকেদের জন্য উপদেশ স্বরূপ।', 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.', 'আমি তাকে দান করলাম তার পরিবার-পরিজন আর তাদের সাথে তাদের মত আরো, আমার রহমত স্বরূপ আর জ্ঞান-বুদ্ধিসম্পন্ন লোকেদের জন্য উপদেশ স্বরূপ।', 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038043.mp3', now()),
  (38, 44, '', '[{"id":44295,"position":1,"text_uthmani":"وَخُذْ","transliteration":"wakhudh","translation_bn":"\"এবং (তাকে বললাম) ধরো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44296,"position":2,"text_uthmani":"بِيَدِكَ","transliteration":"biyadika","translation_bn":"তোমার হাত দিয়ে","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":44297,"position":3,"text_uthmani":"ضِغْثًۭا","transliteration":"ḍigh''than","translation_bn":"একমুঠো ঘাস","root":"ضغث","lemma":"ضِغْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":44298,"position":4,"text_uthmani":"فَٱضْرِب","transliteration":"fa-iḍ''rib","translation_bn":"অতঃপর আঘাত করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44299,"position":5,"text_uthmani":"بِّهِۦ","transliteration":"bihi","translation_bn":"তা দিয়ে (তোমার স্ত্রীকে)","root":"—","lemma":"بِّهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":44300,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44301,"position":7,"text_uthmani":"تَحْنَثْ ۗ","transliteration":"taḥnath","translation_bn":"তুমি শপথ ভঙ্গ করো\"","root":"حنث","lemma":"تَحْنَثْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44303,"position":8,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চযই় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":44304,"position":9,"text_uthmani":"وَجَدْنَـٰهُ","transliteration":"wajadnāhu","translation_bn":"তাকে আমরা পেয়েছি","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44305,"position":10,"text_uthmani":"صَابِرًۭا ۚ","transliteration":"ṣābiran","translation_bn":"ধৈর্য্যশীল","root":"صبر","lemma":"صَابِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":44307,"position":11,"text_uthmani":"نِّعْمَ","transliteration":"niʿ''ma","translation_bn":"অতি উত্তম","root":"نعم","lemma":"نِعْمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44308,"position":12,"text_uthmani":"ٱلْعَبْدُ ۖ","transliteration":"l-ʿabdu","translation_bn":"দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"শব্দ"},{"id":44310,"position":13,"text_uthmani":"إِنَّهُۥٓ","transliteration":"innahu","translation_bn":"সে নিশ্চয়ই  ছিলো","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":44311,"position":14,"text_uthmani":"أَوَّابٌۭ","transliteration":"awwābun","translation_bn":"বড় (আল্লাহ) অভিমুখী","root":"اوب","lemma":"أَوَّاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":44312,"position":15,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'wakhudh biyadika ḍigh''than fa-iḍ''rib bihi walā taḥnath innā wajadnāhu ṣābiran niʿ''ma l-ʿabdu innahu awwābun', '(আমি তাকে বললাম) কিছু ঘাস লও আর তা দিয়ে আঘাত কর, (আর তোমার স্ত্রীকে একশত বেত্রাঘাত করার শপথ) ভঙ্গ করো না। আমি তাকে পেয়েছিলাম পূর্ণ ধৈর্যশীল, কতই না উত্তম বান্দাহ, প্রকৃতই (আল্লাহ) অভিমুখী।', '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah].', '(আমি তাকে বললাম) কিছু ঘাস লও আর তা দিয়ে আঘাত কর, (আর তোমার স্ত্রীকে একশত বেত্রাঘাত করার শপথ) ভঙ্গ করো না। আমি তাকে পেয়েছিলাম পূর্ণ ধৈর্যশীল, কতই না উত্তম বান্দাহ, প্রকৃতই (আল্লাহ) অভিমুখী।', '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038044.mp3', now()),
  (38, 45, '', '[{"id":45597,"position":1,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45598,"position":2,"text_uthmani":"عِبَـٰدَنَآ","transliteration":"ʿibādanā","translation_bn":"আমাদের দাসদেরকে","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":45599,"position":3,"text_uthmani":"إِبْرَٰهِيمَ","transliteration":"ib''rāhīma","translation_bn":"(যেমন) ইবরাহীম","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":45600,"position":4,"text_uthmani":"وَإِسْحَـٰقَ","transliteration":"wa-is''ḥāqa","translation_bn":"ও ইসহাক","root":"—","lemma":"إِسْحَاق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45601,"position":5,"text_uthmani":"وَيَعْقُوبَ","transliteration":"wayaʿqūba","translation_bn":"ও ইয়াকূব","root":"—","lemma":"يَعْقُوب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45602,"position":6,"text_uthmani":"أُو۟لِى","transliteration":"ulī","translation_bn":"সম্পন্ন","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":45603,"position":7,"text_uthmani":"ٱلْأَيْدِى","transliteration":"l-aydī","translation_bn":"কর্মক্ষমতা","root":"يدي","lemma":"يَد","grammar_bn":"শব্দ"},{"id":45604,"position":8,"text_uthmani":"وَٱلْأَبْصَـٰرِ","transliteration":"wal-abṣāri","translation_bn":"ও সূক্ষ্মদৃষ্টি (সম্পন্ন)","root":"بصر","lemma":"بَصَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45605,"position":9,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur ʿibādanā ib''rāhīma wa-is''ḥāqa wayaʿqūba ulī l-aydī wal-abṣāri', 'স্মরণ কর আমার বান্দাহ ইবরাহীম, ইসহাক্ব ও ইয়া‘কূব-এর কথা- তারা ছিল শক্তি ও সূক্ষ্ণদর্শিতার অধিকারী।', 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.', 'স্মরণ কর আমার বান্দাহ ইবরাহীম, ইসহাক্ব ও ইয়া‘কূব-এর কথা- তারা ছিল শক্তি ও সূক্ষ্ণদর্শিতার অধিকারী।', 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038045.mp3', now()),
  (38, 46, '', '[{"id":46282,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":46283,"position":2,"text_uthmani":"أَخْلَصْنَـٰهُم","transliteration":"akhlaṣnāhum","translation_bn":"তাদেরকে আমরা  মর্যাদা দিয়েছিলাম","root":"خلص","lemma":"أَخْلَصُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46284,"position":3,"text_uthmani":"بِخَالِصَةٍۢ","transliteration":"bikhāliṣatin","translation_bn":"একটি স্বতন্ত্রগুণের কারণে","root":"خلص","lemma":"خَالِصَة","grammar_bn":"অব্যয় (Preposition)"},{"id":46285,"position":4,"text_uthmani":"ذِكْرَى","transliteration":"dhik''rā","translation_bn":"(তা ছিলো) স্মরণ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":46286,"position":5,"text_uthmani":"ٱلدَّارِ","transliteration":"l-dāri","translation_bn":"পরকালের","root":"دور","lemma":"دَار","grammar_bn":"শব্দ"},{"id":46287,"position":6,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'innā akhlaṣnāhum bikhāliṣatin dhik''rā l-dāri', 'বস্তুত আমি তাদেরকে বৈশিষ্ট্যমন্ডিত করেছিলাম এক বিশেষ বৈশিষ্ট্যে- তা হল পরলোকের স্মরণ।', 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].', 'বস্তুত আমি তাদেরকে বৈশিষ্ট্যমন্ডিত করেছিলাম এক বিশেষ বৈশিষ্ট্যে- তা হল পরলোকের স্মরণ।', 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038046.mp3', now()),
  (38, 47, '', '[{"id":46995,"position":1,"text_uthmani":"وَإِنَّهُمْ","transliteration":"wa-innahum","translation_bn":"এবং তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46996,"position":2,"text_uthmani":"عِندَنَا","transliteration":"ʿindanā","translation_bn":"আমাদের কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":46997,"position":3,"text_uthmani":"لَمِنَ","transliteration":"lamina","translation_bn":"অবশ্যই অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":46998,"position":4,"text_uthmani":"ٱلْمُصْطَفَيْنَ","transliteration":"l-muṣ''ṭafayna","translation_bn":"মনোনীত  (বান্দাদের)","root":"صفو","lemma":"مُصْطَفَيْن","grammar_bn":"শব্দ"},{"id":46999,"position":5,"text_uthmani":"ٱلْأَخْيَارِ","transliteration":"l-akhyāri","translation_bn":"উত্তম (বান্দাদের)","root":"خير","lemma":"خَيْر","grammar_bn":"শব্দ"},{"id":47000,"position":6,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahum ʿindanā lamina l-muṣ''ṭafayna l-akhyāri', 'আমার দৃষ্টিতে তারা ছিল আমার বাছাইকৃত উত্তম বান্দাহদের অন্তর্ভুক্ত।', 'And indeed they are, to Us, among the chosen and outstanding.', 'আমার দৃষ্টিতে তারা ছিল আমার বাছাইকৃত উত্তম বান্দাহদের অন্তর্ভুক্ত।', 'And indeed they are, to Us, among the chosen and outstanding.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038047.mp3', now()),
  (38, 48, '', '[{"id":47205,"position":1,"text_uthmani":"وَٱذْكُرْ","transliteration":"wa-udh''kur","translation_bn":"এবং স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47206,"position":2,"text_uthmani":"إِسْمَـٰعِيلَ","transliteration":"is''māʿīla","translation_bn":"ইসমাঈল","root":"—","lemma":"إِسْمَاعِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":47207,"position":3,"text_uthmani":"وَٱلْيَسَعَ","transliteration":"wal-yasaʿa","translation_bn":"ও আলইয়াসা","root":"—","lemma":"ٱلْيَسَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47208,"position":4,"text_uthmani":"وَذَا","transliteration":"wadhā","translation_bn":"ও","root":"—","lemma":"ذَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47209,"position":5,"text_uthmani":"ٱلْكِفْلِ ۖ","transliteration":"l-kif''li","translation_bn":"যুলকিফ্‌লকে","root":"كفل","lemma":"كِفْل","grammar_bn":"শব্দ"},{"id":47211,"position":6,"text_uthmani":"وَكُلٌّۭ","transliteration":"wakullun","translation_bn":"এবং প্রত্যেকে (ছিলো)","root":"كلل","lemma":"كُلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47212,"position":7,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47213,"position":8,"text_uthmani":"ٱلْأَخْيَارِ","transliteration":"l-akhyāri","translation_bn":"উত্তম (বান্দাদের)","root":"خير","lemma":"خَيْر","grammar_bn":"শব্দ"},{"id":47214,"position":9,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kur is''māʿīla wal-yasaʿa wadhā l-kif''li wakullun mina l-akhyāri', 'স্মরণ কর ইসমাঈল, ইয়াসা‘আ ও যুলকিফলের কথা- এরা সবাই ছিল উত্তমদের মধ্যে গণ্য।', 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.', 'স্মরণ কর ইসমাঈল, ইয়াসা‘আ ও যুলকিফলের কথা- এরা সবাই ছিল উত্তমদের মধ্যে গণ্য।', 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038048.mp3', now()),
  (38, 49, '', '[{"id":48334,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":48335,"position":2,"text_uthmani":"ذِكْرٌۭ ۚ","transliteration":"dhik''run","translation_bn":"একটি স্মরণ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":48337,"position":3,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48338,"position":4,"text_uthmani":"لِلْمُتَّقِينَ","transliteration":"lil''muttaqīna","translation_bn":"মুত্তাকীদের জন্যে (রয়েছে)","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"অব্যয় (Preposition)"},{"id":48339,"position":5,"text_uthmani":"لَحُسْنَ","transliteration":"laḥus''na","translation_bn":"অবশ্যই উত্তম","root":"حسن","lemma":"حُسْن","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":48340,"position":6,"text_uthmani":"مَـَٔابٍۢ","transliteration":"maābin","translation_bn":"আবাস","root":"اوب","lemma":"مَـ#َاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":48341,"position":7,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā dhik''run wa-inna lil''muttaqīna laḥus''na maābin', 'এ হচ্ছে স্মৃতিচারণ, মুত্তাক্বীদের জন্য অবশ্যই আছে উত্তম প্রত্যাবর্তন স্থল।', 'This is a reminder. And indeed, for the righteous is a good place of return', 'এ হচ্ছে স্মৃতিচারণ, মুত্তাক্বীদের জন্য অবশ্যই আছে উত্তম প্রত্যাবর্তন স্থল।', 'This is a reminder. And indeed, for the righteous is a good place of return', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038049.mp3', now()),
  (38, 50, '', '[{"id":49006,"position":1,"text_uthmani":"جَنَّـٰتِ","transliteration":"jannāti","translation_bn":"জান্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":49007,"position":2,"text_uthmani":"عَدْنٍۢ","transliteration":"ʿadnin","translation_bn":"চিরস্থায়ী","root":"—","lemma":"عَدْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":49008,"position":3,"text_uthmani":"مُّفَتَّحَةًۭ","transliteration":"mufattaḥatan","translation_bn":"খোলা (রয়েছে)","root":"فتح","lemma":"مُّفَتَّحَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":49009,"position":4,"text_uthmani":"لَّهُمُ","transliteration":"lahumu","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَّهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":49010,"position":5,"text_uthmani":"ٱلْأَبْوَٰبُ","transliteration":"l-abwābu","translation_bn":"দরজাসমূহ","root":"بوب","lemma":"بَاب","grammar_bn":"শব্দ"},{"id":49011,"position":6,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'jannāti ʿadnin mufattaḥatan lahumu l-abwābu', 'চিরস্থায়ী জান্নাত, তাদের জন্য উন্মুক্ত দ্বার।', 'Gardens of perpetual residence, whose doors will be opened to them.', 'চিরস্থায়ী জান্নাত, তাদের জন্য উন্মুক্ত দ্বার।', 'Gardens of perpetual residence, whose doors will be opened to them.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038050.mp3', now()),
  (38, 51, '', '[{"id":49640,"position":1,"text_uthmani":"مُتَّكِـِٔينَ","transliteration":"muttakiīna","translation_bn":"তারা হেলান দিয়ে বসবে","root":"وكا","lemma":"مُتَّكِـ#ِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":49641,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49642,"position":3,"text_uthmani":"يَدْعُونَ","transliteration":"yadʿūna","translation_bn":"তারা আদেশ করবে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":49643,"position":4,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49644,"position":5,"text_uthmani":"بِفَـٰكِهَةٍۢ","transliteration":"bifākihatin","translation_bn":"ফলমূলের","root":"فكه","lemma":"فَٰكِهَة","grammar_bn":"অব্যয় (Preposition)"},{"id":49645,"position":6,"text_uthmani":"كَثِيرَةٍۢ","transliteration":"kathīratin","translation_bn":"অনেক","root":"كثر","lemma":"كَثِيرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":49646,"position":7,"text_uthmani":"وَشَرَابٍۢ","transliteration":"washarābin","translation_bn":"ও পানীয়ের","root":"شرب","lemma":"شَرَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49647,"position":8,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'muttakiīna fīhā yadʿūna fīhā bifākihatin kathīratin washarābin', 'সেখানে তারা হেলান দিয়ে বসবে, চাইবে প্রচুর ফলমূল আর পানীয়।', 'Reclining within them, they will call therein for abundant fruit and drink.', 'সেখানে তারা হেলান দিয়ে বসবে, চাইবে প্রচুর ফলমূল আর পানীয়।', 'Reclining within them, they will call therein for abundant fruit and drink.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038051.mp3', now()),
  (38, 52, '', '[{"id":49825,"position":1,"text_uthmani":"۞ وَعِندَهُمْ","transliteration":"waʿindahum","translation_bn":"এবং কাছে (থাকবে) তাদের","root":"عند","lemma":"عِند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49826,"position":2,"text_uthmani":"قَـٰصِرَٰتُ","transliteration":"qāṣirātu","translation_bn":"আনত","root":"قصر","lemma":"قَٰصِرَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":49827,"position":3,"text_uthmani":"ٱلطَّرْفِ","transliteration":"l-ṭarfi","translation_bn":"নয়না","root":"طرف","lemma":"طَرْف","grammar_bn":"শব্দ"},{"id":49828,"position":4,"text_uthmani":"أَتْرَابٌ","transliteration":"atrābun","translation_bn":"সমবয়ষ্কা (সহধর্মিনী)","root":"ترب","lemma":"أَتْرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":49829,"position":5,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'waʿindahum qāṣirātu l-ṭarfi atrābun', 'আর তাদের পাশে থাকবে সতীসাধ্বী সংযতনয়না সমবয়স্কা রমণীগণ।', 'And with them will be women limiting [their] glances and of equal age.', 'আর তাদের পাশে থাকবে সতীসাধ্বী সংযতনয়না সমবয়স্কা রমণীগণ।', 'And with them will be women limiting [their] glances and of equal age.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038052.mp3', now()),
  (38, 53, '', '[{"id":50922,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই (সব নিয়ামাত)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":50923,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":50924,"position":3,"text_uthmani":"تُوعَدُونَ","transliteration":"tūʿadūna","translation_bn":"তোমাদের প্রতিশ্রুতি দেওয়া হচ্ছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50925,"position":4,"text_uthmani":"لِيَوْمِ","transliteration":"liyawmi","translation_bn":"দিনের জন্যে","root":"يوم","lemma":"يَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":50926,"position":5,"text_uthmani":"ٱلْحِسَابِ","transliteration":"l-ḥisābi","translation_bn":"বিচারের","root":"حسب","lemma":"حِسَاب","grammar_bn":"শব্দ"},{"id":50927,"position":6,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā mā tūʿadūna liyawmi l-ḥisābi', 'এসব হল যা তোমাদেরকে হিসাবের দিনে দেয়ার ওয়া‘দা দেয়া হচ্ছে।', 'This is what you, [the righteous], are promised for the Day of Account.', 'এসব হল যা তোমাদেরকে হিসাবের দিনে দেয়ার ওয়া‘দা দেয়া হচ্ছে।', 'This is what you, [the righteous], are promised for the Day of Account.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038053.mp3', now()),
  (38, 54, '', '[{"id":51539,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":51540,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":51541,"position":3,"text_uthmani":"لَرِزْقُنَا","transliteration":"lariz''qunā","translation_bn":"অবশ্যই আমাদের জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":51542,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":51543,"position":5,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":51544,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51545,"position":7,"text_uthmani":"نَّفَادٍ","transliteration":"nafādin","translation_bn":"শেষ","root":"نفد","lemma":"نَّفَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":51546,"position":8,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā lariz''qunā mā lahu min nafādin', 'এ হল আমার দেয়া রিযক- যা কক্ষনো ফুরাবে না।', 'Indeed, this is Our provision; for it there is no depletion.', 'এ হল আমার দেয়া রিযক- যা কক্ষনো ফুরাবে না।', 'Indeed, this is Our provision; for it there is no depletion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038054.mp3', now()),
  (38, 55, '', '[{"id":52037,"position":1,"text_uthmani":"هَـٰذَا ۚ","transliteration":"hādhā","translation_bn":"এটাই (মুত্তাকীদের পরিণাম)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":52039,"position":2,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"আর নিশ্চয়ই (রয়েছে)","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52040,"position":3,"text_uthmani":"لِلطَّـٰغِينَ","transliteration":"lilṭṭāghīna","translation_bn":"সীমালংঘনকারীদের জন্যে","root":"طغي","lemma":"طَٰغِين","grammar_bn":"অব্যয় (Preposition)"},{"id":52041,"position":4,"text_uthmani":"لَشَرَّ","transliteration":"lasharra","translation_bn":"অবশ্যই নিকৃষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":52042,"position":5,"text_uthmani":"مَـَٔابٍۢ","transliteration":"maābin","translation_bn":"প্রত্যাবর্তন স্থান","root":"اوب","lemma":"مَـ#َاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":52043,"position":6,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā wa-inna lilṭṭāghīna lasharra maābin', 'সত্য বটে, এ সব (মুত্তাক্বীদের জন্য); আর আল্লাহদ্রোহীদের জন্য অবশ্যই আছে নিকৃষ্ট প্রত্যাবর্তনস্থল।', 'This [is so]. But indeed, for the transgressors is an evil place of return -', 'সত্য বটে, এ সব (মুত্তাক্বীদের জন্য); আর আল্লাহদ্রোহীদের জন্য অবশ্যই আছে নিকৃষ্ট প্রত্যাবর্তনস্থল।', 'This [is so]. But indeed, for the transgressors is an evil place of return -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038055.mp3', now()),
  (38, 56, '', '[{"id":52127,"position":1,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":52128,"position":2,"text_uthmani":"يَصْلَوْنَهَا","transliteration":"yaṣlawnahā","translation_bn":"তাতে তারা প্রবেশ জ্বলবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":52129,"position":3,"text_uthmani":"فَبِئْسَ","transliteration":"fabi''sa","translation_bn":"আর কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52130,"position":4,"text_uthmani":"ٱلْمِهَادُ","transliteration":"l-mihādu","translation_bn":"ঠিকানা","root":"مهد","lemma":"مِهَٰد","grammar_bn":"শব্দ"},{"id":52131,"position":5,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'jahannama yaṣlawnahā fabi''sa l-mihādu', 'জাহান্নাম, সেখানে তারা জ্বলবে, কতই না নিকৃষ্ট বিশ্রামস্থল!', 'Hell, which they will [enter to] burn, and wretched is the resting place.', 'জাহান্নাম, সেখানে তারা জ্বলবে, কতই না নিকৃষ্ট বিশ্রামস্থল!', 'Hell, which they will [enter to] burn, and wretched is the resting place.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038056.mp3', now()),
  (38, 57, '', '[{"id":53055,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটাই (তাদের পরিণাম)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":53056,"position":2,"text_uthmani":"فَلْيَذُوقُوهُ","transliteration":"falyadhūqūhu","translation_bn":"সুতরাং  তার তারা স্বাদ নিক","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"শব্দ"},{"id":53057,"position":3,"text_uthmani":"حَمِيمٌۭ","transliteration":"ḥamīmun","translation_bn":"ফুটন্ত পানির","root":"حمم","lemma":"حَمِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":53058,"position":4,"text_uthmani":"وَغَسَّاقٌۭ","transliteration":"waghassāqun","translation_bn":"ও পূঁজের","root":"غسق","lemma":"غَسَّاق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53059,"position":5,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā falyadhūqūhu ḥamīmun waghassāqun', 'সত্য বটে, এসব (আল্লাহদ্রোহীদের জন্য), কাজেই সেখানে তারা পান করুক ফুটন্ত পানি ও রক্ত পুঁজ।', 'This - so let them taste it - is scalding water and [foul] purulence.', 'সত্য বটে, এসব (আল্লাহদ্রোহীদের জন্য), কাজেই সেখানে তারা পান করুক ফুটন্ত পানি ও রক্ত পুঁজ।', 'This - so let them taste it - is scalding water and [foul] purulence.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038057.mp3', now()),
  (38, 58, '', '[{"id":53619,"position":1,"text_uthmani":"وَءَاخَرُ","transliteration":"waākharu","translation_bn":"এবং অন্য কিছু","root":"اخر","lemma":"ا^خَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53620,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":53621,"position":3,"text_uthmani":"شَكْلِهِۦٓ","transliteration":"shaklihi","translation_bn":"সে ধরণের","root":"شكل","lemma":"شَكْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":53622,"position":4,"text_uthmani":"أَزْوَٰجٌ","transliteration":"azwājun","translation_bn":"বিভিন্ন প্রকার (কষ্টের)","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":53623,"position":5,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'waākharu min shaklihi azwājun', 'এ ধরনের আরো অন্যান্য (শাস্তি) যা তাদের জন্য যথোপযুক্ত।', 'And other [punishments] of its type [in various] kinds.', 'এ ধরনের আরো অন্যান্য (শাস্তি) যা তাদের জন্য যথোপযুক্ত।', 'And other [punishments] of its type [in various] kinds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038058.mp3', now()),
  (38, 59, '', '[{"id":54159,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"(তারা বলবে) এই তো","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":54160,"position":2,"text_uthmani":"فَوْجٌۭ","transliteration":"fawjun","translation_bn":"একটি দল","root":"فوج","lemma":"فَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":54161,"position":3,"text_uthmani":"مُّقْتَحِمٌۭ","transliteration":"muq''taḥimun","translation_bn":"প্রবেশকারী","root":"قحم","lemma":"مُّقْتَحِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":54162,"position":4,"text_uthmani":"مَّعَكُمْ ۖ","transliteration":"maʿakum","translation_bn":"তোমাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":54164,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":54165,"position":6,"text_uthmani":"مَرْحَبًۢا","transliteration":"marḥaban","translation_bn":"কোনো অভিনন্দন","root":"رحب","lemma":"مَرْحَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54166,"position":7,"text_uthmani":"بِهِمْ ۚ","transliteration":"bihim","translation_bn":"তাদের জন্যে","root":"—","lemma":"بِهِمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":54168,"position":8,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":54169,"position":9,"text_uthmani":"صَالُوا۟","transliteration":"ṣālū","translation_bn":"জ্বলবে","root":"صلي","lemma":"صَالُوا","grammar_bn":"বিশেষ্য (Noun)"},{"id":54170,"position":10,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"(জাহান্নামের) আগুনে","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":54171,"position":11,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā fawjun muq''taḥimun maʿakum lā marḥaban bihim innahum ṣālū l-nāri', '(নিজেদের একদল অনুসারীকে জাহান্নামের দিকে আসতে দেখে জাহান্নামীরা বলাবলি করবে) এই তো এক বাহিনী তোমাদের সঙ্গে এসে প্রবেশ করছে। তাদের জন্য নেই কোন সংবর্ধনা, তারা আগুনে জ্বলবে।', '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."', '(নিজেদের একদল অনুসারীকে জাহান্নামের দিকে আসতে দেখে জাহান্নামীরা বলাবলি করবে) এই তো এক বাহিনী তোমাদের সঙ্গে এসে প্রবেশ করছে। তাদের জন্য নেই কোন সংবর্ধনা, তারা আগুনে জ্বলবে।', '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038059.mp3', now()),
  (38, 60, '', '[{"id":54172,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(অনুসারীরা) বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54173,"position":2,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"\"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":54174,"position":3,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরাও (তাতে জ্বলছো)","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":54175,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":54176,"position":5,"text_uthmani":"مَرْحَبًۢا","transliteration":"marḥaban","translation_bn":"কোনো অভিনন্দন","root":"رحب","lemma":"مَرْحَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54177,"position":6,"text_uthmani":"بِكُمْ ۖ","transliteration":"bikum","translation_bn":"তোমাদের জন্যও","root":"—","lemma":"بِكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":54179,"position":7,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরাই","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":54180,"position":8,"text_uthmani":"قَدَّمْتُمُوهُ","transliteration":"qaddamtumūhu","translation_bn":"তা তোমরাই সামনে এনেছো","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54181,"position":9,"text_uthmani":"لَنَا ۖ","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَنَا ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":54183,"position":10,"text_uthmani":"فَبِئْسَ","transliteration":"fabi''sa","translation_bn":"অতএব কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"শব্দ"},{"id":54184,"position":11,"text_uthmani":"ٱلْقَرَارُ","transliteration":"l-qarāru","translation_bn":"আবাসস্থল\"","root":"قرر","lemma":"قَرَار","grammar_bn":"শব্দ"},{"id":54185,"position":12,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'qālū bal antum lā marḥaban bikum antum qaddamtumūhu lanā fabi''sa l-qarāru', 'অনুসারীরা বলবে- না, বরং তোমরাই (জ্বলে মর), তোমাদের জন্যও নেই কোন অভিনন্দন। আমাদের জন্য এ ব্যবস্থা আগে তোমরাই করে দিয়েছ। কতই না নিকৃষ্ট এই আবাসস্থল!', 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."', 'অনুসারীরা বলবে- না, বরং তোমরাই (জ্বলে মর), তোমাদের জন্যও নেই কোন অভিনন্দন। আমাদের জন্য এ ব্যবস্থা আগে তোমরাই করে দিয়েছ। কতই না নিকৃষ্ট এই আবাসস্থল!', 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038060.mp3', now()),
  (38, 61, '', '[{"id":55398,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55399,"position":2,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":55400,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":55401,"position":4,"text_uthmani":"قَدَّمَ","transliteration":"qaddama","translation_bn":"সম্মুখীন করেছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55402,"position":5,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":55403,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":55404,"position":7,"text_uthmani":"فَزِدْهُ","transliteration":"fazid''hu","translation_bn":"তাকে বাড়িয়ে দাও এজন্যে","root":"زيد","lemma":"زَادَ","grammar_bn":"শব্দ"},{"id":55405,"position":8,"text_uthmani":"عَذَابًۭا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":55406,"position":9,"text_uthmani":"ضِعْفًۭا","transliteration":"ḍiʿ''fan","translation_bn":"দ্বিগুণ","root":"ضعف","lemma":"ضِعْف","grammar_bn":"বিশেষণ (Adjective)"},{"id":55407,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55408,"position":11,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"জাহান্নামের\"","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":55409,"position":12,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'qālū rabbanā man qaddama lanā hādhā fazid''hu ʿadhāban ḍiʿ''fan fī l-nāri', 'তারা বলবে- হে আমাদের প্রতিপালক! আমাদের জন্য যে এ ব্যবস্থা এনে দিয়েছে তাকে জাহান্নামে দ্বিগুণ শাস্তি দাও।', 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."', 'তারা বলবে- হে আমাদের প্রতিপালক! আমাদের জন্য যে এ ব্যবস্থা এনে দিয়েছে তাকে জাহান্নামে দ্বিগুণ শাস্তি দাও।', 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038061.mp3', now()),
  (38, 62, '', '[{"id":55921,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55922,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"কি","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":55923,"position":3,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদের হলো (যে)","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":55924,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":55925,"position":5,"text_uthmani":"نَرَىٰ","transliteration":"narā","translation_bn":"আমরা দেখছি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":55926,"position":6,"text_uthmani":"رِجَالًۭا","transliteration":"rijālan","translation_bn":"লোকদেরকে","root":"رجل","lemma":"رِجَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":55927,"position":7,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55928,"position":8,"text_uthmani":"نَعُدُّهُم","transliteration":"naʿudduhum","translation_bn":"তাদেরকে গণ্য করতাম","root":"عدد","lemma":"عَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55929,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55930,"position":10,"text_uthmani":"ٱلْأَشْرَارِ","transliteration":"l-ashrāri","translation_bn":"খুব খারাপ (লোকদের)","root":"شرر","lemma":"شَرّ","grammar_bn":"শব্দ"},{"id":55931,"position":11,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū mā lanā lā narā rijālan kunnā naʿudduhum mina l-ashrāri', 'তারা বলবে- ব্যাপার কী! আমরা যে লোকগুলোকে (দুনিয়ায়) খুব খারাপ বলে গণ্য করতাম তাদেরকে তো দেখছি না।', 'And they will say, "Why do we not see men whom we used to count among the worst?', 'তারা বলবে- ব্যাপার কী! আমরা যে লোকগুলোকে (দুনিয়ায়) খুব খারাপ বলে গণ্য করতাম তাদেরকে তো দেখছি না।', 'And they will say, "Why do we not see men whom we used to count among the worst?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038062.mp3', now()),
  (38, 63, '', '[{"id":56436,"position":1,"text_uthmani":"أَتَّخَذْنَـٰهُمْ","transliteration":"attakhadhnāhum","translation_bn":"কি তাদেরকে আমরা বানিয়ে নিয়েছিলাম","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":56437,"position":2,"text_uthmani":"سِخْرِيًّا","transliteration":"sikh''riyyan","translation_bn":"বিদ্রুপের (ব্যক্তি হিসেবে)","root":"سخر","lemma":"سِخْرِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":56438,"position":3,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":56439,"position":4,"text_uthmani":"زَاغَتْ","transliteration":"zāghat","translation_bn":"ভুল করেছে","root":"زيغ","lemma":"زَاغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56440,"position":5,"text_uthmani":"عَنْهُمُ","transliteration":"ʿanhumu","translation_bn":"তাদের থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":56441,"position":6,"text_uthmani":"ٱلْأَبْصَـٰرُ","transliteration":"l-abṣāru","translation_bn":"(আমাদের) দৃষ্টিসমূহ\"","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":56442,"position":7,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'attakhadhnāhum sikh''riyyan am zāghat ʿanhumu l-abṣāru', 'আমরা কি তাদের সঙ্গে অযথাই ঠাট্টা-বিদ্রুপ করতাম, না তাদের ব্যাপারে আমাদের দৃষ্টিভ্রম ঘটেছে? (অর্থাৎ তারা হয়ত জাহান্নামেই আছে কিন্তু আমাদের চোখ তাদেরকে দেখতে পাচ্ছে না)', 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"', 'আমরা কি তাদের সঙ্গে অযথাই ঠাট্টা-বিদ্রুপ করতাম, না তাদের ব্যাপারে আমাদের দৃষ্টিভ্রম ঘটেছে? (অর্থাৎ তারা হয়ত জাহান্নামেই আছে কিন্তু আমাদের চোখ তাদেরকে দেখতে পাচ্ছে না)', 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038063.mp3', now()),
