, 'I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038069.mp3', now()),
  (38, 70, '', '[{"id":59810,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":59811,"position":2,"text_uthmani":"يُوحَىٰٓ","transliteration":"yūḥā","translation_bn":"ওহী করা হয়","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":59812,"position":3,"text_uthmani":"إِلَىَّ","transliteration":"ilayya","translation_bn":"আমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":59813,"position":4,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":59814,"position":5,"text_uthmani":"أَنَّمَآ","transliteration":"annamā","translation_bn":"যে মূলতঃ","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":59815,"position":6,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":59816,"position":7,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"একজন সতর্ককারী (মাত্র)","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":59817,"position":8,"text_uthmani":"مُّبِينٌ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":59818,"position":9,"text_uthmani":"٧٠","transliteration":"","translation_bn":"(৭০)","root":"—","lemma":"٧٠","grammar_bn":"মার্কার"}]'::jsonb, 'in yūḥā ilayya illā annamā anā nadhīrun mubīnun', 'আমার কাছে ওয়াহী করা হয়েছে যে, আমি কেবল একজন স্পষ্ট সতর্ককারী।', 'It has not been revealed to me except that I am a clear warner."', 'আমার কাছে ওয়াহী করা হয়েছে যে, আমি কেবল একজন স্পষ্ট সতর্ককারী।', 'It has not been revealed to me except that I am a clear warner."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038070.mp3', now()),
  (38, 71, '', '[{"id":60332,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":60333,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60334,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":60335,"position":4,"text_uthmani":"لِلْمَلَـٰٓئِكَةِ","transliteration":"lil''malāikati","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"অব্যয় (Preposition)"},{"id":60336,"position":5,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":60337,"position":6,"text_uthmani":"خَـٰلِقٌۢ","transliteration":"khāliqun","translation_bn":"সৃষ্টি করছি","root":"خلق","lemma":"خَٰلِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":60338,"position":7,"text_uthmani":"بَشَرًۭا","transliteration":"basharan","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":60339,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60340,"position":9,"text_uthmani":"طِينٍۢ","transliteration":"ṭīnin","translation_bn":"মাটি","root":"طين","lemma":"طِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":60341,"position":10,"text_uthmani":"٧١","transliteration":"","translation_bn":"(৭১)","root":"—","lemma":"٧١","grammar_bn":"মার্কার"}]'::jsonb, 'idh qāla rabbuka lil''malāikati innī khāliqun basharan min ṭīnin', 'স্মরণ কর, যখন তোমার প্রতিপালক ফেরেশতাদেরকে বললেন- আমি কাদা থেকে মানুষ সৃষ্টি করতে যাচ্ছি।', '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.', 'স্মরণ কর, যখন তোমার প্রতিপালক ফেরেশতাদেরকে বললেন- আমি কাদা থেকে মানুষ সৃষ্টি করতে যাচ্ছি।', '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038071.mp3', now()),
  (38, 72, '', '[{"id":60856,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":60857,"position":2,"text_uthmani":"سَوَّيْتُهُۥ","transliteration":"sawwaytuhu","translation_bn":"তা আমি সুঠাম করবো","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":60858,"position":3,"text_uthmani":"وَنَفَخْتُ","transliteration":"wanafakhtu","translation_bn":"ও আমি সঞ্চার করবো","root":"نفخ","lemma":"نَفَخَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":60859,"position":4,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60860,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":60861,"position":6,"text_uthmani":"رُّوحِى","transliteration":"rūḥī","translation_bn":"আমার রূহ","root":"روح","lemma":"رُوح","grammar_bn":"বিশেষ্য (Noun)"},{"id":60862,"position":7,"text_uthmani":"فَقَعُوا۟","transliteration":"faqaʿū","translation_bn":"তোমরা তখন পড়বে","root":"وقع","lemma":"وَقَعَ","grammar_bn":"শব্দ"},{"id":60863,"position":8,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার (সামনে)","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":60864,"position":9,"text_uthmani":"سَـٰجِدِينَ","transliteration":"sājidīna","translation_bn":"সিজদাকারী হয়ে\"","root":"سجد","lemma":"سَاجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":60865,"position":10,"text_uthmani":"٧٢","transliteration":"","translation_bn":"(৭২)","root":"—","lemma":"٧٢","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā sawwaytuhu wanafakhtu fīhi min rūḥī faqaʿū lahu sājidīna', 'আমি যখন তাকে সঠিকভাবে বানিয়ে ফেলব আর তার ভিতরে আমার রূহ ফুঁকে দেব, তখন তোমরা তার সামনে সাজদাহয় পড়ে যাবে।', 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', 'আমি যখন তাকে সঠিকভাবে বানিয়ে ফেলব আর তার ভিতরে আমার রূহ ফুঁকে দেব, তখন তোমরা তার সামনে সাজদাহয় পড়ে যাবে।', 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038072.mp3', now()),
  (38, 73, '', '[{"id":61338,"position":1,"text_uthmani":"فَسَجَدَ","transliteration":"fasajada","translation_bn":"অতঃপর সিজদা করলো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"শব্দ"},{"id":61339,"position":2,"text_uthmani":"ٱلْمَلَـٰٓئِكَةُ","transliteration":"l-malāikatu","translation_bn":"ফেরেশতারা","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":61340,"position":3,"text_uthmani":"كُلُّهُمْ","transliteration":"kulluhum","translation_bn":"তাদের সকলেই","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":61341,"position":4,"text_uthmani":"أَجْمَعُونَ","transliteration":"ajmaʿūna","translation_bn":"একত্রে","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":61342,"position":5,"text_uthmani":"٧٣","transliteration":"","translation_bn":"(৭৩)","root":"—","lemma":"٧٣","grammar_bn":"মার্কার"}]'::jsonb, 'fasajada l-malāikatu kulluhum ajmaʿūna', 'তখন ফেরেশতারা সবাই সেজদা করল।', 'So the angels prostrated - all of them entirely.', 'তখন ফেরেশতারা সবাই সেজদা করল।', 'So the angels prostrated - all of them entirely.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038073.mp3', now()),
