  (38, 85, '', '[{"id":66310,"position":1,"text_uthmani":"لَأَمْلَأَنَّ","transliteration":"la-amla-anna","translation_bn":"আমি অবশ্যই ভরিয়ে তুলবো","root":"ملا","lemma":"مُلِئَتْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":66311,"position":2,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নামকে","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":66312,"position":3,"text_uthmani":"مِنكَ","transliteration":"minka","translation_bn":"তোমার দ্বারা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":66313,"position":4,"text_uthmani":"وَمِمَّن","transliteration":"wamimman","translation_bn":"ও তার দ্বারা যে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":66314,"position":5,"text_uthmani":"تَبِعَكَ","transliteration":"tabiʿaka","translation_bn":"তোমার অনুসরণ করবে","root":"تبع","lemma":"تَبِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66315,"position":6,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":66316,"position":7,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সকলের (দ্বারা)\"","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":66317,"position":8,"text_uthmani":"٨٥","transliteration":"","translation_bn":"(৮৫)","root":"—","lemma":"٨٥","grammar_bn":"মার্কার"}]'::jsonb, 'la-amla-anna jahannama minka wamimman tabiʿaka min''hum ajmaʿīna', 'আমি তোমাকে আর তাদের (অর্থাৎ মানুষদের) মধ্যে যারা তোমাকে অনুসরণ করবে তাদের সব্বাইকে দিয়ে অবশ্যই জাহান্নাম পূর্ণ করব।', '[That] I will surely fill Hell with you and those of them that follow you all together."', 'আমি তোমাকে আর তাদের (অর্থাৎ মানুষদের) মধ্যে যারা তোমাকে অনুসরণ করবে তাদের সব্বাইকে দিয়ে অবশ্যই জাহান্নাম পূর্ণ করব।', '[That] I will surely fill Hell with you and those of them that follow you all together."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038085.mp3', now()),
  (38, 86, '', '[{"id":66711,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66712,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":66713,"position":3,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"তোমাদের কাছে চাই আমি","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66714,"position":4,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"এর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":66715,"position":5,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":66716,"position":6,"text_uthmani":"أَجْرٍۢ","transliteration":"ajrin","translation_bn":"পারিশ্রমিক","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":66717,"position":7,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":66718,"position":8,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":66719,"position":9,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":66720,"position":10,"text_uthmani":"ٱلْمُتَكَلِّفِينَ","transliteration":"l-mutakalifīna","translation_bn":"ভানকারীদের","root":"كلف","lemma":"مُتَكَلِّفِين","grammar_bn":"শব্দ"},{"id":66721,"position":11,"text_uthmani":"٨٦","transliteration":"","translation_bn":"(৮৬)","root":"—","lemma":"٨٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul mā asalukum ʿalayhi min ajrin wamā anā mina l-mutakalifīna', 'বল- আমি এর (অর্থাৎ সত্য-সঠিক পথের দিকে ডাকার) জন্য তোমাদের কাছে পারিশ্রমিক চাই না, আর আমি কোন ধোঁকাবাজ নই।', 'Say, [O Muhammad], "I do not ask you for the Qur''an any payment, and I am not of the pretentious', 'বল- আমি এর (অর্থাৎ সত্য-সঠিক পথের দিকে ডাকার) জন্য তোমাদের কাছে পারিশ্রমিক চাই না, আর আমি কোন ধোঁকাবাজ নই।', 'Say, [O Muhammad], "I do not ask you for the Qur''an any payment, and I am not of the pretentious', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038086.mp3', now()),
  (38, 87, '', '[{"id":66979,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":66980,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":66981,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":66982,"position":4,"text_uthmani":"ذِكْرٌۭ","transliteration":"dhik''run","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":66983,"position":5,"text_uthmani":"لِّلْعَـٰلَمِينَ","transliteration":"lil''ʿālamīna","translation_bn":"বিশ্ববাসীদের জন্যে","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":66984,"position":6,"text_uthmani":"٨٧","transliteration":"","translation_bn":"(৮৭)","root":"—","lemma":"٨٧","grammar_bn":"মার্কার"}]'::jsonb, 'in huwa illā dhik''run lil''ʿālamīna', 'এটা তো বিশ্বজগতের জন্য কেবল উপদেশ বাণী।', 'It is but a reminder to the worlds.', 'এটা তো বিশ্বজগতের জন্য কেবল উপদেশ বাণী।', 'It is but a reminder to the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038087.mp3', now()),
  (38, 88, '', '[{"id":67225,"position":1,"text_uthmani":"وَلَتَعْلَمُنَّ","transliteration":"walataʿlamunna","translation_bn":"এবং তোমরা অবশ্যই জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":67226,"position":2,"text_uthmani":"نَبَأَهُۥ","transliteration":"naba-ahu","translation_bn":"তার খবর","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":67227,"position":3,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরেই","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":67228,"position":4,"text_uthmani":"حِينٍۭ","transliteration":"ḥīnin","translation_bn":"কিছুকাল\"","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":67229,"position":5,"text_uthmani":"٨٨","transliteration":"","translation_bn":"(৮৮)","root":"—","lemma":"٨٨","grammar_bn":"মার্কার"}]'::jsonb, 'walataʿlamunna naba-ahu baʿda ḥīnin', 'কিছুকাল পরেই এর সংবাদ তোমরা অবশ্য অবশ্যই জানতে পারবে।', 'And you will surely know [the truth of] its information after a time."', 'কিছুকাল পরেই এর সংবাদ তোমরা অবশ্য অবশ্যই জানতে পারবে।', 'And you will surely know [the truth of] its information after a time."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/038088.mp3', now())
