  (39, 1, '', '[{"id":909,"position":1,"text_uthmani":"تَنزِيلُ","transliteration":"tanzīlu","translation_bn":"অবতীর্ণ করা","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":910,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এই) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":911,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":912,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":913,"position":5,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"( যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":914,"position":6,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":915,"position":7,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlu l-kitābi mina l-lahi l-ʿazīzi l-ḥakīmi', 'এ কিতাব নাযিল হয়েছে মহাপরাক্রমশালী মহাবিজ্ঞানী আল্লাহর নিকট হতে।', 'The revelation of the Qur''an is from Allah, the Exalted in Might, the Wise.', 'এ কিতাব নাযিল হয়েছে মহাপরাক্রমশালী মহাবিজ্ঞানী আল্লাহর নিকট হতে।', 'The revelation of the Qur''an is from Allah, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039001.mp3', now()),
  (39, 2, '', '[{"id":2020,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2021,"position":2,"text_uthmani":"أَنزَلْنَآ","transliteration":"anzalnā","translation_bn":"আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2022,"position":3,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2023,"position":4,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"(এই) কিতাবকে","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":2024,"position":5,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"সত্যসহকারে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2025,"position":6,"text_uthmani":"فَٱعْبُدِ","transliteration":"fa-uʿ''budi","translation_bn":"সুতরাং ইবাদাত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"শব্দ"},{"id":2026,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2027,"position":8,"text_uthmani":"مُخْلِصًۭا","transliteration":"mukh''liṣan","translation_bn":"একনিষ্ঠভাবে","root":"خلص","lemma":"مُخْلِص","grammar_bn":"বিশেষ্য (Noun)"},{"id":2028,"position":9,"text_uthmani":"لَّهُ","transliteration":"lahu","translation_bn":"তাঁরই জন্যে","root":"—","lemma":"لَّهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":2029,"position":10,"text_uthmani":"ٱلدِّينَ","transliteration":"l-dīna","translation_bn":"আনুগত্যে (নির্দিষ্ট করে)","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":2030,"position":11,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'innā anzalnā ilayka l-kitāba bil-ḥaqi fa-uʿ''budi l-laha mukh''liṣan lahu l-dīna', 'আমি তোমার প্রতি এ কিতাব অবতীর্ণ করেছি সত্যতা সহকারে, (এতে নেই কোন প্রকার মিথ্যে) কাজেই আল্লাহর ‘ইবাদাত কর দ্বীনকে (অর্থাৎ আনুগত্য, হুকুম পালন, দাসত্ব ও গোলামীকে) একমাত্র তাঁরই জন্য নির্দিষ্ট করে।', 'Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion.', 'আমি তোমার প্রতি এ কিতাব অবতীর্ণ করেছি সত্যতা সহকারে, (এতে নেই কোন প্রকার মিথ্যে) কাজেই আল্লাহর ‘ইবাদাত কর দ্বীনকে (অর্থাৎ আনুগত্য, হুকুম পালন, দাসত্ব ও গোলামীকে) একমাত্র তাঁরই জন্য নির্দিষ্ট করে।', 'Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039002.mp3', now()),
  (39, 3, '', '[{"id":3212,"position":1,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"জেনে রাখো","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":3213,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":3214,"position":3,"text_uthmani":"ٱلدِّينُ","transliteration":"l-dīnu","translation_bn":"আনুগত্য","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":3215,"position":4,"text_uthmani":"ٱلْخَالِصُ ۚ","transliteration":"l-khāliṣu","translation_bn":"একনিষ্ঠ","root":"خلص","lemma":"خَالِص","grammar_bn":"শব্দ"},{"id":3217,"position":5,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3218,"position":6,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"গ্রহণ করেছো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3219,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3220,"position":8,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":3221,"position":9,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে (অন্যদেরকে)","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3222,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"(এবং বলে) না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3223,"position":11,"text_uthmani":"نَعْبُدُهُمْ","transliteration":"naʿbuduhum","translation_bn":"তাদের পূজা করি আমরা","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3224,"position":12,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3225,"position":13,"text_uthmani":"لِيُقَرِّبُونَآ","transliteration":"liyuqarribūnā","translation_bn":"আমাদের নিকটে করে দেয় যেন","root":"قرب","lemma":"قَرَّبَ","grammar_bn":"শব্দ"},{"id":3226,"position":14,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3227,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3228,"position":16,"text_uthmani":"زُلْفَىٰٓ","transliteration":"zul''fā","translation_bn":"(তাঁর) কাছাকাছি\"","root":"زلف","lemma":"زُلْفَىٰ^","grammar_bn":"বিশেষ্য (Noun)"},{"id":3229,"position":17,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3230,"position":18,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3231,"position":19,"text_uthmani":"يَحْكُمُ","transliteration":"yaḥkumu","translation_bn":"মীমাংসা করে দিবেন","root":"حكم","lemma":"حَكَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3232,"position":20,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":3233,"position":21,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3234,"position":22,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"(ঐ বিষয়ে) যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3235,"position":23,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3236,"position":24,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"যাতে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3237,"position":25,"text_uthmani":"يَخْتَلِفُونَ ۗ","transliteration":"yakhtalifūna","translation_bn":"মতভেদ করছে","root":"خلف","lemma":"ٱخْتَلَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3239,"position":26,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3240,"position":27,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3241,"position":28,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3242,"position":29,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"সৎপথে পরিচালনা করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3243,"position":30,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"তাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3244,"position":31,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"যে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3245,"position":32,"text_uthmani":"كَـٰذِبٌۭ","transliteration":"kādhibun","translation_bn":"মিথ্যাবাদী","root":"كذب","lemma":"كَٰذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3246,"position":33,"text_uthmani":"كَفَّارٌۭ","transliteration":"kaffārun","translation_bn":"কট্টর কাফির","root":"كفر","lemma":"كَفَّار","grammar_bn":"বিশেষণ (Adjective)"},{"id":3247,"position":34,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alā lillahi l-dīnu l-khāliṣu wa-alladhīna ittakhadhū min dūnihi awliyāa mā naʿbuduhum illā liyuqarribūnā ilā l-lahi zul''fā inna l-laha yaḥkumu baynahum fī mā hum fīhi yakhtalifūna inna l-laha lā yahdī man huwa kādhibun kaffārun', 'জেনে রেখ, খালেস দ্বীন কেবল আল্লাহরই জন্য। যারা তাঁকে বাদ দিয়ে অন্যদেরকে অভিভাবক বানিয়ে নিয়েছে তারা বলে- আমরা তাদের ‘ইবাদাত একমাত্র এ উদ্দেশ্যেই করি যে, তারা আমাদেরকে আল্লাহর নৈকট্যে পৌঁছে দেবে। (সত্য পথ থেকে সরে গিয়ে মিথ্যে পথ ও মতের জন্ম দিয়ে) তারা যে মতভেদ করছে, আল্লাহ তার চূড়ান্ত ফয়সালা করে দেবেন। যে মিথ্যেবাদী ও কাফির আল্লাহ তাকে সঠিক পথ দেখান না।', 'Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allah in position." Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever.', 'জেনে রেখ, খালেস দ্বীন কেবল আল্লাহরই জন্য। যারা তাঁকে বাদ দিয়ে অন্যদেরকে অভিভাবক বানিয়ে নিয়েছে তারা বলে- আমরা তাদের ‘ইবাদাত একমাত্র এ উদ্দেশ্যেই করি যে, তারা আমাদেরকে আল্লাহর নৈকট্যে পৌঁছে দেবে। (সত্য পথ থেকে সরে গিয়ে মিথ্যে পথ ও মতের জন্ম দিয়ে) তারা যে মতভেদ করছে, আল্লাহ তার চূড়ান্ত ফয়সালা করে দেবেন। যে মিথ্যেবাদী ও কাফির আল্লাহ তাকে সঠিক পথ দেখান না।', 'Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allah in position." Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039003.mp3', now()),
  (39, 4, '', '[{"id":4555,"position":1,"text_uthmani":"لَّوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":4556,"position":2,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"ইচ্ছে করতেন","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4557,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4558,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":4559,"position":5,"text_uthmani":"يَتَّخِذَ","transliteration":"yattakhidha","translation_bn":"গ্রহণ করবেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4560,"position":6,"text_uthmani":"وَلَدًۭا","transliteration":"waladan","translation_bn":"কোনো পুত্র সন্তান","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4561,"position":7,"text_uthmani":"لَّٱصْطَفَىٰ","transliteration":"la-iṣ''ṭafā","translation_bn":"মনোনীত করতেন অবশ্যই","root":"صفو","lemma":"ٱصْطَفَىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":4562,"position":8,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4563,"position":9,"text_uthmani":"يَخْلُقُ","transliteration":"yakhluqu","translation_bn":"তিনি সৃষ্টি করেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4564,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যাকে","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4565,"position":11,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি চাইতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4567,"position":12,"text_uthmani":"سُبْحَـٰنَهُۥ ۖ","transliteration":"sub''ḥānahu","translation_bn":"(কিন্তু তা হ''তে) তিনি পবিত্র/মহান","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4569,"position":13,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4570,"position":14,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4571,"position":15,"text_uthmani":"ٱلْوَٰحِدُ","transliteration":"l-wāḥidu","translation_bn":"এক","root":"وحد","lemma":"وَٰحِد","grammar_bn":"শব্দ"},{"id":4572,"position":16,"text_uthmani":"ٱلْقَهَّارُ","transliteration":"l-qahāru","translation_bn":"প্রবল পরাক্রমশালী","root":"قهر","lemma":"قَهَّار","grammar_bn":"শব্দ"},{"id":4573,"position":17,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'law arāda l-lahu an yattakhidha waladan la-iṣ''ṭafā mimmā yakhluqu mā yashāu sub''ḥānahu huwa l-lahu l-wāḥidu l-qahāru', 'আল্লাহ সন্তান গ্রহণ করার ইচ্ছে করলে তিনি তার সৃষ্টিকুল থেকে নিজ পছন্দ মত বেছে নিতেন। এসব থেকে তিনি পবিত্র। অপ্রতিরোধ্য ক্ষমতার অধিকারী তিনি এক ও একক আল্লাহ।', 'If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing.', 'আল্লাহ সন্তান গ্রহণ করার ইচ্ছে করলে তিনি তার সৃষ্টিকুল থেকে নিজ পছন্দ মত বেছে নিতেন। এসব থেকে তিনি পবিত্র। অপ্রতিরোধ্য ক্ষমতার অধিকারী তিনি এক ও একক আল্লাহ।', 'If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039004.mp3', now()),
  (39, 5, '', '[{"id":5831,"position":1,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5832,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":5833,"position":3,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5834,"position":4,"text_uthmani":"بِٱلْحَقِّ ۖ","transliteration":"bil-ḥaqi","translation_bn":"সুপরিকল্পিতভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":5836,"position":5,"text_uthmani":"يُكَوِّرُ","transliteration":"yukawwiru","translation_bn":"তিনি ঢেকে রাখেন","root":"كور","lemma":"كُوِّرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5837,"position":6,"text_uthmani":"ٱلَّيْلَ","transliteration":"al-layla","translation_bn":"রাতকে","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":5838,"position":7,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5839,"position":8,"text_uthmani":"ٱلنَّهَارِ","transliteration":"l-nahāri","translation_bn":"দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"শব্দ"},{"id":5840,"position":9,"text_uthmani":"وَيُكَوِّرُ","transliteration":"wayukawwiru","translation_bn":"এবং ঢেকে রাখেন","root":"كور","lemma":"كُوِّرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5841,"position":10,"text_uthmani":"ٱلنَّهَارَ","transliteration":"l-nahāra","translation_bn":"দিনকে","root":"نهر","lemma":"نَهَار","grammar_bn":"শব্দ"},{"id":5842,"position":11,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5843,"position":12,"text_uthmani":"ٱلَّيْلِ ۖ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":5845,"position":13,"text_uthmani":"وَسَخَّرَ","transliteration":"wasakhara","translation_bn":"এবং নিয়ন্ত্রিত করেছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5846,"position":14,"text_uthmani":"ٱلشَّمْسَ","transliteration":"l-shamsa","translation_bn":"সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"শব্দ"},{"id":5847,"position":15,"text_uthmani":"وَٱلْقَمَرَ ۖ","transliteration":"wal-qamara","translation_bn":"ও চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5849,"position":16,"text_uthmani":"كُلٌّۭ","transliteration":"kullun","translation_bn":"প্রত্যেকেই","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5850,"position":17,"text_uthmani":"يَجْرِى","transliteration":"yajrī","translation_bn":"আবর্তন করে","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5851,"position":18,"text_uthmani":"لِأَجَلٍۢ","transliteration":"li-ajalin","translation_bn":"একটি কাল পর্যন্ত","root":"اجل","lemma":"أَجَل","grammar_bn":"অব্যয় (Preposition)"},{"id":5852,"position":19,"text_uthmani":"مُّسَمًّى ۗ","transliteration":"musamman","translation_bn":"নির্দিষ্ট","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষ্য (Noun)"},{"id":5854,"position":20,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"জেনে রেখো","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":5855,"position":21,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5856,"position":22,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":5857,"position":23,"text_uthmani":"ٱلْغَفَّـٰرُ","transliteration":"l-ghafāru","translation_bn":"পরম ক্ষমাশীল","root":"غفر","lemma":"غَفَّار","grammar_bn":"শব্দ"},{"id":5858,"position":24,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'khalaqa l-samāwāti wal-arḍa bil-ḥaqi yukawwiru al-layla ʿalā l-nahāri wayukawwiru l-nahāra ʿalā al-layli wasakhara l-shamsa wal-qamara kullun yajrī li-ajalin musamman alā huwa l-ʿazīzu l-ghafāru', 'তিনি আকাশ ও পৃথিবী সৃষ্টি করেছেন যথাযথভাবে। রাত দিনকে ঢেকে নেয়, আর দিন ঢেকে নেয় রাতকে। তিনিই নিয়ন্ত্রণ করেন সুরুজ আর চাঁদকে, প্রত্যেকেই চলছে নির্দিষ্ট সময় অনুসারে। জেনে রেখ, তিনি মহাপরাক্রমশালী, পরম ক্ষমাশীল (মহাশক্তিধর হওয়া সত্ত্বেও বার বার ক্ষমা করেন)।', 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.', 'তিনি আকাশ ও পৃথিবী সৃষ্টি করেছেন যথাযথভাবে। রাত দিনকে ঢেকে নেয়, আর দিন ঢেকে নেয় রাতকে। তিনিই নিয়ন্ত্রণ করেন সুরুজ আর চাঁদকে, প্রত্যেকেই চলছে নির্দিষ্ট সময় অনুসারে। জেনে রেখ, তিনি মহাপরাক্রমশালী, পরম ক্ষমাশীল (মহাশক্তিধর হওয়া সত্ত্বেও বার বার ক্ষমা করেন)।', 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039005.mp3', now()),
  (39, 6, '', '[{"id":7122,"position":1,"text_uthmani":"خَلَقَكُم","transliteration":"khalaqakum","translation_bn":"তোমাদের তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7123,"position":2,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7124,"position":3,"text_uthmani":"نَّفْسٍۢ","transliteration":"nafsin","translation_bn":"ব্যক্তি","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":7125,"position":4,"text_uthmani":"وَٰحِدَةٍۢ","transliteration":"wāḥidatin","translation_bn":"একই","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7126,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7127,"position":6,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7128,"position":7,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তার থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7129,"position":8,"text_uthmani":"زَوْجَهَا","transliteration":"zawjahā","translation_bn":"তার জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":7130,"position":9,"text_uthmani":"وَأَنزَلَ","transliteration":"wa-anzala","translation_bn":"ও দিয়েছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7131,"position":10,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":7132,"position":11,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্যে হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7133,"position":12,"text_uthmani":"ٱلْأَنْعَـٰمِ","transliteration":"l-anʿāmi","translation_bn":"গবাদি পশুদের","root":"نعم","lemma":"نَّعَم","grammar_bn":"শব্দ"},{"id":7134,"position":13,"text_uthmani":"ثَمَـٰنِيَةَ","transliteration":"thamāniyata","translation_bn":"আট","root":"ثمن","lemma":"ثَمَٰنِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7135,"position":14,"text_uthmani":"أَزْوَٰجٍۢ ۚ","transliteration":"azwājin","translation_bn":"জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":7137,"position":15,"text_uthmani":"يَخْلُقُكُمْ","transliteration":"yakhluqukum","translation_bn":"তোমাদেরকে সৃষ্টি করেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7138,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7139,"position":17,"text_uthmani":"بُطُونِ","transliteration":"buṭūni","translation_bn":"পেটসমূহের","root":"بطن","lemma":"بَطْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":7140,"position":18,"text_uthmani":"أُمَّهَـٰتِكُمْ","transliteration":"ummahātikum","translation_bn":"তোমাদের মায়েদের","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7141,"position":19,"text_uthmani":"خَلْقًۭا","transliteration":"khalqan","translation_bn":"সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":7142,"position":20,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7143,"position":21,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":7144,"position":22,"text_uthmani":"خَلْقٍۢ","transliteration":"khalqin","translation_bn":"সৃষ্টি","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":7145,"position":23,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7146,"position":24,"text_uthmani":"ظُلُمَـٰتٍۢ","transliteration":"ẓulumātin","translation_bn":"অন্ধকারসমূহের","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":7147,"position":25,"text_uthmani":"ثَلَـٰثٍۢ ۚ","transliteration":"thalāthin","translation_bn":"তিনটি (আবরণের)","root":"ثلث","lemma":"ثَلَٰث","grammar_bn":"বিশেষ্য (Noun)"},{"id":7149,"position":26,"text_uthmani":"ذَٰلِكُمُ","transliteration":"dhālikumu","translation_bn":"তিনিই তোমাদের","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":7150,"position":27,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7151,"position":28,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7152,"position":29,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"তাঁরই","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":7153,"position":30,"text_uthmani":"ٱلْمُلْكُ ۖ","transliteration":"l-mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":7155,"position":31,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7156,"position":32,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোনো ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":7157,"position":33,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":7158,"position":34,"text_uthmani":"هُوَ ۖ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ ۖ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":7160,"position":35,"text_uthmani":"فَأَنَّىٰ","transliteration":"fa-annā","translation_bn":"সুতরাং কোথায়","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"শব্দ"},{"id":7161,"position":36,"text_uthmani":"تُصْرَفُونَ","transliteration":"tuṣ''rafūna","translation_bn":"তোমাদের ফিরানো হচ্ছে","root":"صرف","lemma":"صَرَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7162,"position":37,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'khalaqakum min nafsin wāḥidatin thumma jaʿala min''hā zawjahā wa-anzala lakum mina l-anʿāmi thamāniyata azwājin yakhluqukum fī buṭūni ummahātikum khalqan min baʿdi khalqin fī ẓulumātin thalāthin dhālikumu l-lahu rabbukum lahu l-mul''ku lā ilāha illā huwa fa-annā tuṣ''rafūna', 'তিনি তোমাদেরকে একই ব্যক্তি থেকে সৃষ্টি করেছেন। অতঃপর তার থেকে তিনি তার জুড়ি সৃষ্টি করেছেন। তিনি তোমাদের জন্য বানিয়েছেন আট গৃহপালিত পশু (চার) জোড়ায় জোড়ায়। তিনি তোমাদেরকে সৃষ্টি করেছেন তোমাদের মায়েদের গর্ভে, এক এক পর্যায়ে এক এক আকৃতি দিয়ে, তিন তিনটি অন্ধকার আবরণের মধ্যে। এই হল তোমাদের প্রতিপালক, সর্বময় কর্তৃত্ব তাঁরই, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, কাজেই (ভুয়ো ক্ষমতার অধিকারী, দাম্ভিক ও স্বার্থান্বেষী মহল কর্তৃক) তোমাদেরকে কোন্ দিকে ফিরিয়ে নেয়া হচ্ছে?', 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?', 'তিনি তোমাদেরকে একই ব্যক্তি থেকে সৃষ্টি করেছেন। অতঃপর তার থেকে তিনি তার জুড়ি সৃষ্টি করেছেন। তিনি তোমাদের জন্য বানিয়েছেন আট গৃহপালিত পশু (চার) জোড়ায় জোড়ায়। তিনি তোমাদেরকে সৃষ্টি করেছেন তোমাদের মায়েদের গর্ভে, এক এক পর্যায়ে এক এক আকৃতি দিয়ে, তিন তিনটি অন্ধকার আবরণের মধ্যে। এই হল তোমাদের প্রতিপালক, সর্বময় কর্তৃত্ব তাঁরই, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, কাজেই (ভুয়ো ক্ষমতার অধিকারী, দাম্ভিক ও স্বার্থান্বেষী মহল কর্তৃক) তোমাদেরকে কোন্ দিকে ফিরিয়ে নেয়া হচ্ছে?', 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039006.mp3', now()),
  (39, 7, '', '[{"id":8445,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":8446,"position":2,"text_uthmani":"تَكْفُرُوا۟","transliteration":"takfurū","translation_bn":"তোমরা অকৃতজ্ঞ হও","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8447,"position":3,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"নিশ্চযই তবুও়","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":8448,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8449,"position":5,"text_uthmani":"غَنِىٌّ","transliteration":"ghaniyyun","translation_bn":"অমুখাপেক্ষী","root":"غني","lemma":"غَنِىّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":8450,"position":6,"text_uthmani":"عَنكُمْ ۖ","transliteration":"ʿankum","translation_bn":"তোমাদের থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8452,"position":7,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"কিন্তু না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8453,"position":8,"text_uthmani":"يَرْضَىٰ","transliteration":"yarḍā","translation_bn":"পছন্দ করেন তিনি","root":"رضو","lemma":"رَّضِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8454,"position":9,"text_uthmani":"لِعِبَادِهِ","transliteration":"liʿibādihi","translation_bn":"তাঁর দাসদের জন্যে","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":8455,"position":10,"text_uthmani":"ٱلْكُفْرَ ۖ","transliteration":"l-kuf''ra","translation_bn":"অকৃতজ্ঞতাকে","root":"كفر","lemma":"كُفْر","grammar_bn":"শব্দ"},{"id":8457,"position":11,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8458,"position":12,"text_uthmani":"تَشْكُرُوا۟","transliteration":"tashkurū","translation_bn":"তোমরা কৃতজ্ঞ হও","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8459,"position":13,"text_uthmani":"يَرْضَهُ","transliteration":"yarḍahu","translation_bn":"তা  তিনি পছন্দ করেন","root":"رضو","lemma":"رَّضِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8460,"position":14,"text_uthmani":"لَكُمْ ۗ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ ۗ","grammar_bn":"অব্যয় (Preposition)"},{"id":8462,"position":15,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8463,"position":16,"text_uthmani":"تَزِرُ","transliteration":"taziru","translation_bn":"বহন করবে","root":"وزر","lemma":"يَزِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8464,"position":17,"text_uthmani":"وَازِرَةٌۭ","transliteration":"wāziratun","translation_bn":"কোনো বোঝাবহনকারী","root":"وزر","lemma":"وَازِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8465,"position":18,"text_uthmani":"وِزْرَ","transliteration":"wiz''ra","translation_bn":"বোঝা","root":"وزر","lemma":"وِزْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8466,"position":19,"text_uthmani":"أُخْرَىٰ ۗ","transliteration":"ukh''rā","translation_bn":"অন্যের","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8468,"position":20,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8469,"position":21,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8470,"position":22,"text_uthmani":"رَبِّكُم","transliteration":"rabbikum","translation_bn":"তোমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8471,"position":23,"text_uthmani":"مَّرْجِعُكُمْ","transliteration":"marjiʿukum","translation_bn":"তোমাদের প্রত্যাবর্তন হবে","root":"رجع","lemma":"مَرْجِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":8472,"position":24,"text_uthmani":"فَيُنَبِّئُكُم","transliteration":"fayunabbi-ukum","translation_bn":"তোমাদেরকে অতঃপর তিনি জানিয়ে দিবেন","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"শব্দ"},{"id":8473,"position":25,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8474,"position":26,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8475,"position":27,"text_uthmani":"تَعْمَلُونَ ۚ","transliteration":"taʿmalūna","translation_bn":"কাজ করতেছিলে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8477,"position":28,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8478,"position":29,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"ভালোভাবেই জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":8479,"position":30,"text_uthmani":"بِذَاتِ","transliteration":"bidhāti","translation_bn":"অবস্থা সম্পর্কে","root":"—","lemma":"ذُو","grammar_bn":"অব্যয় (Preposition)"},{"id":8480,"position":31,"text_uthmani":"ٱلصُّدُورِ","transliteration":"l-ṣudūri","translation_bn":"অন্তরসমূহের","root":"صدر","lemma":"صَدْر","grammar_bn":"শব্দ"},{"id":8481,"position":32,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'in takfurū fa-inna l-laha ghaniyyun ʿankum walā yarḍā liʿibādihi l-kuf''ra wa-in tashkurū yarḍahu lakum walā taziru wāziratun wiz''ra ukh''rā thumma ilā rabbikum marjiʿukum fayunabbi-ukum bimā kuntum taʿmalūna innahu ʿalīmun bidhāti l-ṣudūri', 'তোমরা যদি কুফুরী কর তবে (জেনে রেখ), আল্লাহ তোমাদের মুখাপেক্ষী নন। তিনি তাঁর বান্দাহদের জন্য কুফুরী আচরণ পছন্দ করেন না, তোমরা যদি কৃতজ্ঞ হও, তবে তোমাদের জন্য তা তিনি পছন্দ করেন। একের (পাপের) বোঝা অন্যে বহন করবে না। শেষমেষ তোমাদেরকে তোমাদের পালনকর্তার কাছেই ফিরে যেতে হবে, তখন তিনি তোমাদেরকে জানিয়ে দেবেন তোমরা যা করছিলে। তিনি তো অন্তরের খবর পর্যন্ত জানেন।', 'If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.', 'তোমরা যদি কুফুরী কর তবে (জেনে রেখ), আল্লাহ তোমাদের মুখাপেক্ষী নন। তিনি তাঁর বান্দাহদের জন্য কুফুরী আচরণ পছন্দ করেন না, তোমরা যদি কৃতজ্ঞ হও, তবে তোমাদের জন্য তা তিনি পছন্দ করেন। একের (পাপের) বোঝা অন্যে বহন করবে না। শেষমেষ তোমাদেরকে তোমাদের পালনকর্তার কাছেই ফিরে যেতে হবে, তখন তিনি তোমাদেরকে জানিয়ে দেবেন তোমরা যা করছিলে। তিনি তো অন্তরের খবর পর্যন্ত জানেন।', 'If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039007.mp3', now()),
  (39, 8, '', '[{"id":9640,"position":1,"text_uthmani":"۞ وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9641,"position":2,"text_uthmani":"مَسَّ","transliteration":"massa","translation_bn":"স্পর্শ করে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9642,"position":3,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষকে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":9643,"position":4,"text_uthmani":"ضُرٌّۭ","transliteration":"ḍurrun","translation_bn":"কোনো দুঃখদৈন্য","root":"ضرر","lemma":"ضُرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9644,"position":5,"text_uthmani":"دَعَا","transliteration":"daʿā","translation_bn":"সে ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":9645,"position":6,"text_uthmani":"رَبَّهُۥ","transliteration":"rabbahu","translation_bn":"তার রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9646,"position":7,"text_uthmani":"مُنِيبًا","transliteration":"munīban","translation_bn":"একাগ্রচিত্তে","root":"نوب","lemma":"مُّنِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9647,"position":8,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁর দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9648,"position":9,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9649,"position":10,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":9650,"position":11,"text_uthmani":"خَوَّلَهُۥ","transliteration":"khawwalahu","translation_bn":"তাকে দান করেন","root":"خول","lemma":"خَوَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9651,"position":12,"text_uthmani":"نِعْمَةًۭ","transliteration":"niʿ''matan","translation_bn":"অনুগ্রহ","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9652,"position":13,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তাঁর পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9653,"position":14,"text_uthmani":"نَسِىَ","transliteration":"nasiya","translation_bn":"সে ভুলে যায়","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9654,"position":15,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যার(জন্য)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9655,"position":16,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9656,"position":17,"text_uthmani":"يَدْعُوٓا۟","transliteration":"yadʿū","translation_bn":"ডাকছিলো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":9657,"position":18,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার দিকে (একনিষ্ঠভাবে)","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9658,"position":19,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9659,"position":20,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9660,"position":21,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং দাঁড় করায়","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9661,"position":22,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহর জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":9662,"position":23,"text_uthmani":"أَندَادًۭا","transliteration":"andādan","translation_bn":"সমকক্ষ","root":"ندد","lemma":"أَندَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":9663,"position":24,"text_uthmani":"لِّيُضِلَّ","transliteration":"liyuḍilla","translation_bn":"বিভ্রান্ত করে যেন","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"শব্দ"},{"id":9664,"position":25,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9665,"position":26,"text_uthmani":"سَبِيلِهِۦ ۚ","transliteration":"sabīlihi","translation_bn":"তাঁর পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9667,"position":27,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9668,"position":28,"text_uthmani":"تَمَتَّعْ","transliteration":"tamattaʿ","translation_bn":"\"উপভোগ করো","root":"متع","lemma":"تَمَتَّعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9669,"position":29,"text_uthmani":"بِكُفْرِكَ","transliteration":"bikuf''rika","translation_bn":"তোমার অকৃতজ্ঞ অবস্থার (স্বাদ)","root":"كفر","lemma":"كُفْر","grammar_bn":"অব্যয় (Preposition)"},{"id":9670,"position":30,"text_uthmani":"قَلِيلًا ۖ","transliteration":"qalīlan","translation_bn":"কিছুক্ষণ","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":9672,"position":31,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9673,"position":32,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9674,"position":33,"text_uthmani":"أَصْحَـٰبِ","transliteration":"aṣḥābi","translation_bn":"অধিবাসীদের","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9675,"position":34,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"জাহান্নামের\"","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":9676,"position":35,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā massa l-insāna ḍurrun daʿā rabbahu munīban ilayhi thumma idhā khawwalahu niʿ''matan min''hu nasiya mā kāna yadʿū ilayhi min qablu wajaʿala lillahi andādan liyuḍilla ʿan sabīlihi qul tamattaʿ bikuf''rika qalīlan innaka min aṣḥābi l-nāri', 'দুঃখ-মুসিবত যখন মানুষকে স্পর্শ করে তখন সে তার প্রতিপালককে ডাকতে থাকে তাঁর প্রতি বড়ই একনিষ্ঠ হয়ে। অতঃপর তিনি যখন নিজ পক্ষ থেকে অনুগ্রহ দিয়ে তাকে ধন্য করেন, তখন পূর্বে সে যেজন্য তাঁকে ডেকেছিল তা ভুলে যায় এবং অন্যদেরকে আল্লাহর সমকক্ষ দাঁড় করায় তাঁর পথ থেকে পথভ্রষ্ট করার জন্য। বলে দাও, কুফুরীর জীবন কিছুকাল ভোগ করে নাও, (অতঃপর) তুমি তো হবে জাহান্নামের অধিবাসী। (এ ব্যক্তি ভাল, না ঐ ব্যক্তি)', 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."', 'দুঃখ-মুসিবত যখন মানুষকে স্পর্শ করে তখন সে তার প্রতিপালককে ডাকতে থাকে তাঁর প্রতি বড়ই একনিষ্ঠ হয়ে। অতঃপর তিনি যখন নিজ পক্ষ থেকে অনুগ্রহ দিয়ে তাকে ধন্য করেন, তখন পূর্বে সে যেজন্য তাঁকে ডেকেছিল তা ভুলে যায় এবং অন্যদেরকে আল্লাহর সমকক্ষ দাঁড় করায় তাঁর পথ থেকে পথভ্রষ্ট করার জন্য। বলে দাও, কুফুরীর জীবন কিছুকাল ভোগ করে নাও, (অতঃপর) তুমি তো হবে জাহান্নামের অধিবাসী। (এ ব্যক্তি ভাল, না ঐ ব্যক্তি)', 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039008.mp3', now()),
  (39, 9, '', '[{"id":10797,"position":1,"text_uthmani":"أَمَّنْ","transliteration":"amman","translation_bn":"সে কি সমান","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10798,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"যে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10799,"position":3,"text_uthmani":"قَـٰنِتٌ","transliteration":"qānitun","translation_bn":"আনুগত্য প্রকাশকারী","root":"قنت","lemma":"قَانِت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10800,"position":4,"text_uthmani":"ءَانَآءَ","transliteration":"ānāa","translation_bn":"বেলায়","root":"اني","lemma":"ءَانَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10801,"position":5,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":10802,"position":6,"text_uthmani":"سَاجِدًۭا","transliteration":"sājidan","translation_bn":"অথবা সিজদারত অবস্হায়","root":"سجد","lemma":"سَاجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10803,"position":7,"text_uthmani":"وَقَآئِمًۭا","transliteration":"waqāiman","translation_bn":"দাঁড়ানো অবস্হায়","root":"قوم","lemma":"قَا^ئِم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10804,"position":8,"text_uthmani":"يَحْذَرُ","transliteration":"yaḥdharu","translation_bn":"ভয় করে","root":"حذر","lemma":"يَحْذَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10805,"position":9,"text_uthmani":"ٱلْـَٔاخِرَةَ","transliteration":"l-ākhirata","translation_bn":"পরকালকে","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":10806,"position":10,"text_uthmani":"وَيَرْجُوا۟","transliteration":"wayarjū","translation_bn":"ও প্রত্যাশা করে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10807,"position":11,"text_uthmani":"رَحْمَةَ","transliteration":"raḥmata","translation_bn":"অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10808,"position":12,"text_uthmani":"رَبِّهِۦ ۗ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10810,"position":13,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10811,"position":14,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"\"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":10812,"position":15,"text_uthmani":"يَسْتَوِى","transliteration":"yastawī","translation_bn":"সমান হয়","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":10813,"position":16,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10814,"position":17,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10815,"position":18,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"ও যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10816,"position":19,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":10817,"position":20,"text_uthmani":"يَعْلَمُونَ ۗ","transliteration":"yaʿlamūna","translation_bn":"জানে\"","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10819,"position":21,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10820,"position":22,"text_uthmani":"يَتَذَكَّرُ","transliteration":"yatadhakkaru","translation_bn":"শিক্ষা গ্রহণ করে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10821,"position":23,"text_uthmani":"أُو۟لُوا۟","transliteration":"ulū","translation_bn":"সম্পন্নরাই","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":10822,"position":24,"text_uthmani":"ٱلْأَلْبَـٰبِ","transliteration":"l-albābi","translation_bn":"বোধ-বুদ্ধি","root":"لبب","lemma":"أَلْبَٰب","grammar_bn":"শব্দ"},{"id":10823,"position":25,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'amman huwa qānitun ānāa al-layli sājidan waqāiman yaḥdharu l-ākhirata wayarjū raḥmata rabbihi qul hal yastawī alladhīna yaʿlamūna wa-alladhīna lā yaʿlamūna innamā yatadhakkaru ulū l-albābi', 'যে রাত্রির বিভিন্ন প্রহরে সেজদা ও দন্ডায়মান অবস্থায় বিনয় ও শ্রদ্ধা-ভক্তি প্রকাশ করে, আখিরাতকে ভয় করে, আর তার প্রতিপালকের অনুগ্রহ প্রত্যাশা করে? বল- যারা জানে আর যারা জানে না, তারা কি সমান? বিবেক-বুদ্ধিসম্পন্ন লোকেরাই কেবল উপদেশ গ্রহণ করে থাকে।', 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.', 'যে রাত্রির বিভিন্ন প্রহরে সেজদা ও দন্ডায়মান অবস্থায় বিনয় ও শ্রদ্ধা-ভক্তি প্রকাশ করে, আখিরাতকে ভয় করে, আর তার প্রতিপালকের অনুগ্রহ প্রত্যাশা করে? বল- যারা জানে আর যারা জানে না, তারা কি সমান? বিবেক-বুদ্ধিসম্পন্ন লোকেরাই কেবল উপদেশ গ্রহণ করে থাকে।', 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039009.mp3', now()),
  (39, 10, '', '[{"id":12056,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12057,"position":2,"text_uthmani":"يَـٰعِبَادِ","transliteration":"yāʿibādi","translation_bn":"\"হে আমার দাসগণ","root":"عبد","lemma":"عَبْد","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":12058,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12059,"position":4,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12060,"position":5,"text_uthmani":"ٱتَّقُوا۟","transliteration":"ittaqū","translation_bn":"তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12061,"position":6,"text_uthmani":"رَبَّكُمْ ۚ","transliteration":"rabbakum","translation_bn":"তোমাদের রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12063,"position":7,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":12064,"position":8,"text_uthmani":"أَحْسَنُوا۟","transliteration":"aḥsanū","translation_bn":"উত্তম কাজ করেছে","root":"حسن","lemma":"أَحْسَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12065,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12066,"position":10,"text_uthmani":"هَـٰذِهِ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":12067,"position":11,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পৃথিবীতে","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":12068,"position":12,"text_uthmani":"حَسَنَةٌۭ ۗ","transliteration":"ḥasanatun","translation_bn":"কল্যাণ (রয়েছে)","root":"حسن","lemma":"حَسَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12070,"position":13,"text_uthmani":"وَأَرْضُ","transliteration":"wa-arḍu","translation_bn":"এবং পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12071,"position":14,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12072,"position":15,"text_uthmani":"وَٰسِعَةٌ ۗ","transliteration":"wāsiʿatun","translation_bn":"প্রশস্ত","root":"وسع","lemma":"وَٰسِعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12074,"position":16,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":12075,"position":17,"text_uthmani":"يُوَفَّى","transliteration":"yuwaffā","translation_bn":"পূর্ণ দেওয়া হবে","root":"وفي","lemma":"وَفَّىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":12076,"position":18,"text_uthmani":"ٱلصَّـٰبِرُونَ","transliteration":"l-ṣābirūna","translation_bn":"ধৈর্য্যশীলদেরকে","root":"صبر","lemma":"صَابِر","grammar_bn":"শব্দ"},{"id":12077,"position":19,"text_uthmani":"أَجْرَهُم","transliteration":"ajrahum","translation_bn":"প্রতিফল তাদের","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12078,"position":20,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ব্যতীতই","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":12079,"position":21,"text_uthmani":"حِسَابٍۢ","transliteration":"ḥisābin","translation_bn":"কোনো হিসাব\"","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12080,"position":22,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'qul yāʿibādi alladhīna āmanū ittaqū rabbakum lilladhīna aḥsanū fī hādhihi l-dun''yā ḥasanatun wa-arḍu l-lahi wāsiʿatun innamā yuwaffā l-ṣābirūna ajrahum bighayri ḥisābin', 'বল, হে ঈমানদারগণ! তোমরা তোমাদের প্রতিপালককে ভয় কর। এ দুনিয়ায় যারা ভাল কাজ করবে, তাদের জন্য আছে কল্যাণ। আল্লাহর যমীন প্রশস্ত (এক এলাকায় ‘ইবাদাত-বন্দেগী করা কঠিন হলে অন্যত্র চলে যাও)। আমি ধৈর্যশীলদেরকে তাদের পুরস্কার অপরিমিতভাবে দিয়ে থাকি।', 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account."', 'বল, হে ঈমানদারগণ! তোমরা তোমাদের প্রতিপালককে ভয় কর। এ দুনিয়ায় যারা ভাল কাজ করবে, তাদের জন্য আছে কল্যাণ। আল্লাহর যমীন প্রশস্ত (এক এলাকায় ‘ইবাদাত-বন্দেগী করা কঠিন হলে অন্যত্র চলে যাও)। আমি ধৈর্যশীলদেরকে তাদের পুরস্কার অপরিমিতভাবে দিয়ে থাকি।', 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/039010.mp3', now()),
