  (40, 1, '', '[{"id":98,"position":1,"text_uthmani":"حمٓ","transliteration":"hha-meem","translation_bn":"হা-মীম","root":"—","lemma":"حمٓ","grammar_bn":"শব্দ"},{"id":99,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hha-meem', 'হা-মীম।', 'Ha, Meem.', 'হা-মীম।', 'Ha, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040001.mp3', now()),
  (40, 2, '', '[{"id":935,"position":1,"text_uthmani":"تَنزِيلُ","transliteration":"tanzīlu","translation_bn":"অবতীর্ণ করা","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":936,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এই) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":937,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":938,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":939,"position":5,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"(যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":940,"position":6,"text_uthmani":"ٱلْعَلِيمِ","transliteration":"l-ʿalīmi","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":941,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlu l-kitābi mina l-lahi l-ʿazīzi l-ʿalīmi', 'এ কিতাব নাযিল হয়েছে মহা প্রতাপের অধিকারী সর্বজ্ঞ আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Knowing.', 'এ কিতাব নাযিল হয়েছে মহা প্রতাপের অধিকারী সর্বজ্ঞ আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040002.mp3', now()),
  (40, 3, '', '[{"id":2031,"position":1,"text_uthmani":"غَافِرِ","transliteration":"ghāfiri","translation_bn":"(যিনি) ক্ষমাকারী","root":"غفر","lemma":"غَافِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2032,"position":2,"text_uthmani":"ٱلذَّنۢبِ","transliteration":"l-dhanbi","translation_bn":"পাপ","root":"ذنب","lemma":"ذَنب","grammar_bn":"শব্দ"},{"id":2033,"position":3,"text_uthmani":"وَقَابِلِ","transliteration":"waqābili","translation_bn":"এবং কবুলকারী","root":"قبل","lemma":"قَابِل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2034,"position":4,"text_uthmani":"ٱلتَّوْبِ","transliteration":"l-tawbi","translation_bn":"তওবা","root":"توب","lemma":"تَّوْب","grammar_bn":"শব্দ"},{"id":2035,"position":5,"text_uthmani":"شَدِيدِ","transliteration":"shadīdi","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":2036,"position":6,"text_uthmani":"ٱلْعِقَابِ","transliteration":"l-ʿiqābi","translation_bn":"শাস্তিদানে","root":"عقب","lemma":"عِقَاب","grammar_bn":"শব্দ"},{"id":2037,"position":7,"text_uthmani":"ذِى","transliteration":"dhī","translation_bn":"মালিক","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":2038,"position":8,"text_uthmani":"ٱلطَّوْلِ ۖ","transliteration":"l-ṭawli","translation_bn":"অনুগ্রহের","root":"طول","lemma":"طَوْل","grammar_bn":"শব্দ"},{"id":2040,"position":9,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2041,"position":10,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোনো ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":2042,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2043,"position":12,"text_uthmani":"هُوَ ۖ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ ۖ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":2045,"position":13,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2046,"position":14,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন (হবে সকলের)","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":2047,"position":15,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'ghāfiri l-dhanbi waqābili l-tawbi shadīdi l-ʿiqābi dhī l-ṭawli lā ilāha illā huwa ilayhi l-maṣīru', 'যিনি পাপ ক্ষমাকারী, তাওবাহ কবূলকারী, কঠোর শাস্তিদাতা, বড়ই অনুগ্রহশীল, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, প্রত্যাবর্তন তাঁরই কাছে।', 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.', 'যিনি পাপ ক্ষমাকারী, তাওবাহ কবূলকারী, কঠোর শাস্তিদাতা, বড়ই অনুগ্রহশীল, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, প্রত্যাবর্তন তাঁরই কাছে।', 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040003.mp3', now()),
  (40, 4, '', '[{"id":3286,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3287,"position":2,"text_uthmani":"يُجَـٰدِلُ","transliteration":"yujādilu","translation_bn":"তর্ক করে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3288,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"ক্ষেত্রে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3289,"position":4,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"নিদর্শনাবলীর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3290,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3291,"position":6,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3292,"position":7,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3293,"position":8,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3294,"position":9,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"সুতরাং না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":3295,"position":10,"text_uthmani":"يَغْرُرْكَ","transliteration":"yaghrur''ka","translation_bn":"তোমাকে বিভ্রান্ত করে","root":"غرر","lemma":"غَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3296,"position":11,"text_uthmani":"تَقَلُّبُهُمْ","transliteration":"taqallubuhum","translation_bn":"তাদের বিচরণ","root":"قلب","lemma":"تَقَلُّب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3297,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3298,"position":13,"text_uthmani":"ٱلْبِلَـٰدِ","transliteration":"l-bilādi","translation_bn":"দেশে-বিদেশে","root":"بلد","lemma":"بَلَد","grammar_bn":"শব্দ"},{"id":3299,"position":14,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'mā yujādilu fī āyāti l-lahi illā alladhīna kafarū falā yaghrur''ka taqallubuhum fī l-bilādi', 'কাফিররা ছাড়া অন্য কেউ আল্লাহর আয়াত নিয়ে ঝগড়া করে না। কাজেই দেশে দেশে তাদের অবাধ বিচরণ তোমাকে যেন ধোঁকায় না ফেলে।', 'No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.', 'কাফিররা ছাড়া অন্য কেউ আল্লাহর আয়াত নিয়ে ঝগড়া করে না। কাজেই দেশে দেশে তাদের অবাধ বিচরণ তোমাকে যেন ধোঁকায় না ফেলে।', 'No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040004.mp3', now()),
  (40, 5, '', '[{"id":4628,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4629,"position":2,"text_uthmani":"قَبْلَهُمْ","transliteration":"qablahum","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":4630,"position":3,"text_uthmani":"قَوْمُ","transliteration":"qawmu","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4631,"position":4,"text_uthmani":"نُوحٍۢ","transliteration":"nūḥin","translation_bn":"নূহের","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4632,"position":5,"text_uthmani":"وَٱلْأَحْزَابُ","transliteration":"wal-aḥzābu","translation_bn":"এবং (অন্যান্য) দলসমূহও","root":"حزب","lemma":"حِزْب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4633,"position":6,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4634,"position":7,"text_uthmani":"بَعْدِهِمْ ۖ","transliteration":"baʿdihim","translation_bn":"পরে তাদের","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4636,"position":8,"text_uthmani":"وَهَمَّتْ","transliteration":"wahammat","translation_bn":"এবং অভিসন্ধি করেছিলো","root":"همم","lemma":"هَمَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4637,"position":9,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4638,"position":10,"text_uthmani":"أُمَّةٍۭ","transliteration":"ummatin","translation_bn":"জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4639,"position":11,"text_uthmani":"بِرَسُولِهِمْ","transliteration":"birasūlihim","translation_bn":"তাদের রাসূলের সম্পর্কে","root":"رسل","lemma":"رَسُول","grammar_bn":"অব্যয় (Preposition)"},{"id":4640,"position":12,"text_uthmani":"لِيَأْخُذُوهُ ۖ","transliteration":"liyakhudhūhu","translation_bn":"তাকে পাকড়াও করার জন্যে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":4642,"position":13,"text_uthmani":"وَجَـٰدَلُوا۟","transliteration":"wajādalū","translation_bn":"এবং তারা যুক্তিতর্কে মত্তে ছিলো","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4643,"position":14,"text_uthmani":"بِٱلْبَـٰطِلِ","transliteration":"bil-bāṭili","translation_bn":"অসার (অস্ত্র) দিয়ে","root":"بطل","lemma":"بَٰطِل","grammar_bn":"অব্যয় (Preposition)"},{"id":4644,"position":15,"text_uthmani":"لِيُدْحِضُوا۟","transliteration":"liyud''ḥiḍū","translation_bn":"ব্যর্থ করে দেয়ার জন্যে","root":"دحض","lemma":"يُدْحِضُ","grammar_bn":"শব্দ"},{"id":4645,"position":16,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"তা দিয়ে","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":4646,"position":17,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":4647,"position":18,"text_uthmani":"فَأَخَذْتُهُمْ ۖ","transliteration":"fa-akhadhtuhum","translation_bn":"ফলে আমি পাকড়াও করেছি তাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":4649,"position":19,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"সুতরাং (দেখো) কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"শব্দ"},{"id":4650,"position":20,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4651,"position":21,"text_uthmani":"عِقَابِ","transliteration":"ʿiqābi","translation_bn":"আমার শাস্তি","root":"عقب","lemma":"عِقَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4652,"position":22,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat qablahum qawmu nūḥin wal-aḥzābu min baʿdihim wahammat kullu ummatin birasūlihim liyakhudhūhu wajādalū bil-bāṭili liyud''ḥiḍū bihi l-ḥaqa fa-akhadhtuhum fakayfa kāna ʿiqābi', 'এদের পূর্বে নূহের জাতি আর তাদের পরে বহু দল-গোষ্ঠী (রসূলদেরকে) অস্বীকার করেছিল। প্রত্যেক জাতি তাদের রসূলের বিরুদ্ধে চক্রান্ত করেছিল তাকে পাকড়াও করার জন্য, আর অসার অস্ত্রের সাহায্যে বিরোধিতায় লিপ্ত হয়েছিল তা দিয়ে সত্যকে খন্ডন করার জন্য। ফলে আমি তাদেরকে পাকড়াও করেছিলাম। অতঃপর দেখ, কেমন কঠোর ছিল আমার শাস্তি।', 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.', 'এদের পূর্বে নূহের জাতি আর তাদের পরে বহু দল-গোষ্ঠী (রসূলদেরকে) অস্বীকার করেছিল। প্রত্যেক জাতি তাদের রসূলের বিরুদ্ধে চক্রান্ত করেছিল তাকে পাকড়াও করার জন্য, আর অসার অস্ত্রের সাহায্যে বিরোধিতায় লিপ্ত হয়েছিল তা দিয়ে সত্যকে খন্ডন করার জন্য। ফলে আমি তাদেরকে পাকড়াও করেছিলাম। অতঃপর দেখ, কেমন কঠোর ছিল আমার শাস্তি।', 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040005.mp3', now()),
  (40, 6, '', '[{"id":5878,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এরূপে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5879,"position":2,"text_uthmani":"حَقَّتْ","transliteration":"ḥaqqat","translation_bn":"সত্য হলো","root":"حقق","lemma":"حَقَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5880,"position":3,"text_uthmani":"كَلِمَتُ","transliteration":"kalimatu","translation_bn":"বাণী","root":"كلم","lemma":"كَلِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":5881,"position":4,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5882,"position":5,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5883,"position":6,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5884,"position":7,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছিলো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5885,"position":8,"text_uthmani":"أَنَّهُمْ","transliteration":"annahum","translation_bn":"তারা যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5886,"position":9,"text_uthmani":"أَصْحَـٰبُ","transliteration":"aṣḥābu","translation_bn":"অধিবাসী","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5887,"position":10,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"জাহান্নামের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":5888,"position":11,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika ḥaqqat kalimatu rabbika ʿalā alladhīna kafarū annahum aṣḥābu l-nāri', 'এভাবে কাফিরদের ব্যাপারে তোমার প্রতিপালকের বাণী সত্য প্রমাণিত হল যে, তারা জাহান্নামের অধিবাসী।', 'And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire.', 'এভাবে কাফিরদের ব্যাপারে তোমার প্রতিপালকের বাণী সত্য প্রমাণিত হল যে, তারা জাহান্নামের অধিবাসী।', 'And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040006.mp3', now()),
  (40, 7, '', '[{"id":7225,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7226,"position":2,"text_uthmani":"يَحْمِلُونَ","transliteration":"yaḥmilūna","translation_bn":"ধারণ করছে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7227,"position":3,"text_uthmani":"ٱلْعَرْشَ","transliteration":"l-ʿarsha","translation_bn":"(আল্লাহর) আরশ","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":7228,"position":4,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যারা (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7229,"position":5,"text_uthmani":"حَوْلَهُۥ","transliteration":"ḥawlahu","translation_bn":"তার চার পাশে","root":"حول","lemma":"حَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7230,"position":6,"text_uthmani":"يُسَبِّحُونَ","transliteration":"yusabbiḥūna","translation_bn":"তারা মহিমা ঘোষণা করছে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7231,"position":7,"text_uthmani":"بِحَمْدِ","transliteration":"biḥamdi","translation_bn":"প্রশংসাসহ","root":"حمد","lemma":"حَمْد","grammar_bn":"অব্যয় (Preposition)"},{"id":7232,"position":8,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7233,"position":9,"text_uthmani":"وَيُؤْمِنُونَ","transliteration":"wayu''minūna","translation_bn":"এবং তারা ঈমান রাখে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7234,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তাঁর উপর","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":7235,"position":11,"text_uthmani":"وَيَسْتَغْفِرُونَ","transliteration":"wayastaghfirūna","translation_bn":"এবং তারা ক্ষমা প্রার্থনা করছে","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7236,"position":12,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":7237,"position":13,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7238,"position":14,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"(তারা বলে) হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7239,"position":15,"text_uthmani":"وَسِعْتَ","transliteration":"wasiʿ''ta","translation_bn":"তুমি ঘিরে রেখেছো","root":"وسع","lemma":"وَسِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7240,"position":16,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7241,"position":17,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"জিনিস","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7242,"position":18,"text_uthmani":"رَّحْمَةًۭ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহে","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7243,"position":19,"text_uthmani":"وَعِلْمًۭا","transliteration":"waʿil''man","translation_bn":"ও জ্ঞানে","root":"علم","lemma":"عِلْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7244,"position":20,"text_uthmani":"فَٱغْفِرْ","transliteration":"fa-igh''fir","translation_bn":"তাই মাফ করো","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":7245,"position":21,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের)-কে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":7246,"position":22,"text_uthmani":"تَابُوا۟","transliteration":"tābū","translation_bn":"তওবা করে","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7247,"position":23,"text_uthmani":"وَٱتَّبَعُوا۟","transliteration":"wa-ittabaʿū","translation_bn":"ও অনুসরণ করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7248,"position":24,"text_uthmani":"سَبِيلَكَ","transliteration":"sabīlaka","translation_bn":"তোমার পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7249,"position":25,"text_uthmani":"وَقِهِمْ","transliteration":"waqihim","translation_bn":"এবং তাদেরকে বাঁচাও","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7250,"position":26,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি (হ''তে)","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7251,"position":27,"text_uthmani":"ٱلْجَحِيمِ","transliteration":"l-jaḥīmi","translation_bn":"জাহান্নামের","root":"جحم","lemma":"جَحِيم","grammar_bn":"শব্দ"},{"id":7252,"position":28,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yaḥmilūna l-ʿarsha waman ḥawlahu yusabbiḥūna biḥamdi rabbihim wayu''minūna bihi wayastaghfirūna lilladhīna āmanū rabbanā wasiʿ''ta kulla shayin raḥmatan waʿil''man fa-igh''fir lilladhīna tābū wa-ittabaʿū sabīlaka waqihim ʿadhāba l-jaḥīmi', 'যারা ‘আরশ বহন করে আছে, আর যারা আছে তার চারপাশে, তারা তাঁর প্রশংসার সাথে তাঁর মাহাত্ম্য ঘোষণা করে আর তাঁর প্রতি ঈমান পোষণ করে আর মু’মিনদের জন্য ক্ষমা প্রার্থনা ক’রে বলে- হে আমাদের প্রতিপালক! তুমি তোমার রহমত ও জ্ঞান দিয়ে সব কিছুকে বেষ্টন করে রেখেছ, কাজেই যারা তাওবাহ করে ও তোমার পথ অনুসরণ করে তাদেরকে ক্ষমা কর, আর জাহান্নামের ‘আযাব থেকে তাদেরকে রক্ষা কর।', 'Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.', 'যারা ‘আরশ বহন করে আছে, আর যারা আছে তার চারপাশে, তারা তাঁর প্রশংসার সাথে তাঁর মাহাত্ম্য ঘোষণা করে আর তাঁর প্রতি ঈমান পোষণ করে আর মু’মিনদের জন্য ক্ষমা প্রার্থনা ক’রে বলে- হে আমাদের প্রতিপালক! তুমি তোমার রহমত ও জ্ঞান দিয়ে সব কিছুকে বেষ্টন করে রেখেছ, কাজেই যারা তাওবাহ করে ও তোমার পথ অনুসরণ করে তাদেরকে ক্ষমা কর, আর জাহান্নামের ‘আযাব থেকে তাদেরকে রক্ষা কর।', 'Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040007.mp3', now()),
  (40, 8, '', '[{"id":8500,"position":1,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8501,"position":2,"text_uthmani":"وَأَدْخِلْهُمْ","transliteration":"wa-adkhil''hum","translation_bn":"এবং তাদের প্রবেশ করাও","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8502,"position":3,"text_uthmani":"جَنَّـٰتِ","transliteration":"jannāti","translation_bn":"জান্নাত সমূহে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8503,"position":4,"text_uthmani":"عَدْنٍ","transliteration":"ʿadnin","translation_bn":"চিরস্থায়ী","root":"—","lemma":"عَدْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8504,"position":5,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8505,"position":6,"text_uthmani":"وَعَدتَّهُمْ","transliteration":"waʿadttahum","translation_bn":"তাদের তুমি প্রতিশ্রুতি দিয়েছো","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8506,"position":7,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যারা","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8507,"position":8,"text_uthmani":"صَلَحَ","transliteration":"ṣalaḥa","translation_bn":"সৎকর্ম করেছে","root":"صلح","lemma":"صَلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8508,"position":9,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8509,"position":10,"text_uthmani":"ءَابَآئِهِمْ","transliteration":"ābāihim","translation_bn":"তাদের বাপ-দাদাদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":8510,"position":11,"text_uthmani":"وَأَزْوَٰجِهِمْ","transliteration":"wa-azwājihim","translation_bn":"ও তাদের পতি-পত্নীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8511,"position":12,"text_uthmani":"وَذُرِّيَّـٰتِهِمْ ۚ","transliteration":"wadhurriyyātihim","translation_bn":"ও তাদের বংশধরদের","root":"ذرر","lemma":"ذُرِّيَّٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8513,"position":13,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8514,"position":14,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমিই","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":8515,"position":15,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":8516,"position":16,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":8517,"position":17,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'rabbanā wa-adkhil''hum jannāti ʿadnin allatī waʿadttahum waman ṣalaḥa min ābāihim wa-azwājihim wadhurriyyātihim innaka anta l-ʿazīzu l-ḥakīmu', 'হে আমাদের প্রতিপালক! তুমি তাদেরকে আর তাদের পিতৃপুরুষ, স্বামী-স্ত্রী ও সন্তানাদির মধ্যে যারা সৎকাজ করেছে তাদেরকেও চিরস্থায়ী জান্নাতে প্রবেশ করান যার ওয়া‘দা তুমি তাদেরকে দিয়েছ; তুমি মহা পরাক্রমশালী, মহা বিজ্ঞ।', 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.', 'হে আমাদের প্রতিপালক! তুমি তাদেরকে আর তাদের পিতৃপুরুষ, স্বামী-স্ত্রী ও সন্তানাদির মধ্যে যারা সৎকাজ করেছে তাদেরকেও চিরস্থায়ী জান্নাতে প্রবেশ করান যার ওয়া‘দা তুমি তাদেরকে দিয়েছ; তুমি মহা পরাক্রমশালী, মহা বিজ্ঞ।', 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040008.mp3', now()),
  (40, 9, '', '[{"id":9705,"position":1,"text_uthmani":"وَقِهِمُ","transliteration":"waqihimu","translation_bn":"এবং বাঁচাও তাদেরকে","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9706,"position":2,"text_uthmani":"ٱلسَّيِّـَٔاتِ ۚ","transliteration":"l-sayiāti","translation_bn":"(সব) মন্দ (হ''তে)","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":9708,"position":3,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9709,"position":4,"text_uthmani":"تَقِ","transliteration":"taqi","translation_bn":"বাঁচাবে","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9710,"position":5,"text_uthmani":"ٱلسَّيِّـَٔاتِ","transliteration":"l-sayiāti","translation_bn":"(সব) মন্দ (হ''তে)","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":9711,"position":6,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":9712,"position":7,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তাহ''লে নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":9713,"position":8,"text_uthmani":"رَحِمْتَهُۥ ۚ","transliteration":"raḥim''tahu","translation_bn":"তাকে অনুগ্রহ করবে","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9715,"position":9,"text_uthmani":"وَذَٰلِكَ","transliteration":"wadhālika","translation_bn":"এবং এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9716,"position":10,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সেই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9717,"position":11,"text_uthmani":"ٱلْفَوْزُ","transliteration":"l-fawzu","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"শব্দ"},{"id":9718,"position":12,"text_uthmani":"ٱلْعَظِيمُ","transliteration":"l-ʿaẓīmu","translation_bn":"মহা\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":9719,"position":13,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'waqihimu l-sayiāti waman taqi l-sayiāti yawma-idhin faqad raḥim''tahu wadhālika huwa l-fawzu l-ʿaẓīmu', 'সমস্ত খারাবী থেকে তাদেরকে রক্ষা কর। সেদিন তুমি যাকে সমস্ত খারাবী থেকে রক্ষা করলে, তার উপর তো দয়াই করলে। ওটাই হল বিরাট সাফল্য।', 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."', 'সমস্ত খারাবী থেকে তাদেরকে রক্ষা কর। সেদিন তুমি যাকে সমস্ত খারাবী থেকে রক্ষা করলে, তার উপর তো দয়াই করলে। ওটাই হল বিরাট সাফল্য।', 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040009.mp3', now()),
  (40, 10, '', '[{"id":10839,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10840,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10841,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10842,"position":4,"text_uthmani":"يُنَادَوْنَ","transliteration":"yunādawna","translation_bn":"তাদের ডেকে বলা হবে","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10843,"position":5,"text_uthmani":"لَمَقْتُ","transliteration":"lamaqtu","translation_bn":"ক্ষোভ অবশ্যই (ছিলো)","root":"مقت","lemma":"مَقْت","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10844,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10845,"position":7,"text_uthmani":"أَكْبَرُ","transliteration":"akbaru","translation_bn":"অধিক (সেদিন)","root":"كبر","lemma":"أَكْبَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":10846,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10847,"position":9,"text_uthmani":"مَّقْتِكُمْ","transliteration":"maqtikum","translation_bn":"তোমাদের (আজকের) ক্ষোভের","root":"مقت","lemma":"مَقْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10848,"position":10,"text_uthmani":"أَنفُسَكُمْ","transliteration":"anfusakum","translation_bn":"তোমাদের নিজেদের (উপর)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":10849,"position":11,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":10850,"position":12,"text_uthmani":"تُدْعَوْنَ","transliteration":"tud''ʿawna","translation_bn":"তোমাদের ডাকা হতো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":10851,"position":13,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10852,"position":14,"text_uthmani":"ٱلْإِيمَـٰنِ","transliteration":"l-īmāni","translation_bn":"ঈমানের","root":"امن","lemma":"إِيمَٰن","grammar_bn":"শব্দ"},{"id":10853,"position":15,"text_uthmani":"فَتَكْفُرُونَ","transliteration":"fatakfurūna","translation_bn":"তখন তোমরা অস্বীকার করতে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10854,"position":16,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna kafarū yunādawna lamaqtu l-lahi akbaru min maqtikum anfusakum idh tud''ʿawna ilā l-īmāni fatakfurūna', 'যারা কুফুরী করেছিল তাদেরকে ডাক দিয়ে বলা হবে- তোমাদের নিজেদের প্রতি তোমাদের ক্ষোভের চেয়ে (তোমাদের প্রতি) আল্লাহর ক্ষোভ অধিক, (কেননা) তোমাদেরকে যখন ঈমানের দিকে আহবান করা হয়েছিল, তখন তোমরা অস্বীকার করেছিলে।', 'Indeed, those who disbelieve will be addressed, "The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused."', 'যারা কুফুরী করেছিল তাদেরকে ডাক দিয়ে বলা হবে- তোমাদের নিজেদের প্রতি তোমাদের ক্ষোভের চেয়ে (তোমাদের প্রতি) আল্লাহর ক্ষোভ অধিক, (কেননা) তোমাদেরকে যখন ঈমানের দিকে আহবান করা হয়েছিল, তখন তোমরা অস্বীকার করেছিলে।', 'Indeed, those who disbelieve will be addressed, "The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040010.mp3', now()),
  (40, 11, '', '[{"id":12091,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12092,"position":2,"text_uthmani":"رَبَّنَآ","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12093,"position":3,"text_uthmani":"أَمَتَّنَا","transliteration":"amattanā","translation_bn":"আমাদেরকে তুমি  মৃত্যু দিয়েছো","root":"موت","lemma":"أَمَاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12094,"position":4,"text_uthmani":"ٱثْنَتَيْنِ","transliteration":"ith''natayni","translation_bn":"দু''বার","root":"ثني","lemma":"ٱثْنَتَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":12095,"position":5,"text_uthmani":"وَأَحْيَيْتَنَا","transliteration":"wa-aḥyaytanā","translation_bn":"ও আমাদেরকে তুমি জীবন দিয়েছো","root":"حيي","lemma":"أَحْيَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12096,"position":6,"text_uthmani":"ٱثْنَتَيْنِ","transliteration":"ith''natayni","translation_bn":"দু''বার","root":"ثني","lemma":"ٱثْنَتَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":12097,"position":7,"text_uthmani":"فَٱعْتَرَفْنَا","transliteration":"fa-iʿ''tarafnā","translation_bn":"আমরা স্বীকার করছি এখন","root":"عرف","lemma":"ٱعْتَرَفُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12098,"position":8,"text_uthmani":"بِذُنُوبِنَا","transliteration":"bidhunūbinā","translation_bn":"আমাদের পাপসমূহকে","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":12099,"position":9,"text_uthmani":"فَهَلْ","transliteration":"fahal","translation_bn":"এখন কি  (আছে)","root":"—","lemma":"هَل\r","grammar_bn":"শব্দ"},{"id":12100,"position":10,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12101,"position":11,"text_uthmani":"خُرُوجٍۢ","transliteration":"khurūjin","translation_bn":"বের হওয়ার (পরিত্রাণের)","root":"خرج","lemma":"خُرُوج","grammar_bn":"বিশেষ্য (Noun)"},{"id":12102,"position":12,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12103,"position":13,"text_uthmani":"سَبِيلٍۢ","transliteration":"sabīlin","translation_bn":"পথ\"","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":12104,"position":14,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'qālū rabbanā amattanā ith''natayni wa-aḥyaytanā ith''natayni fa-iʿ''tarafnā bidhunūbinā fahal ilā khurūjin min sabīlin', 'তারা বলবে, হে আমাদের প্রতিপালক! তুমি দু’বার আমাদের মৃত্যু দিয়েছ (জন্মের আগের মৃত অবস্থা আর জীবন শেষের মৃত্যু) আর আমাদেরকে দু’বার জীবন দিয়েছ। আমরা আমাদের পাপ স্বীকার করছি, (এখান থেকে) বের হওয়ার কোন পথ আছে কি?', 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"', 'তারা বলবে, হে আমাদের প্রতিপালক! তুমি দু’বার আমাদের মৃত্যু দিয়েছ (জন্মের আগের মৃত অবস্থা আর জীবন শেষের মৃত্যু) আর আমাদেরকে দু’বার জীবন দিয়েছ। আমরা আমাদের পাপ স্বীকার করছি, (এখান থেকে) বের হওয়ার কোন পথ আছে কি?', 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040011.mp3', now()),
  (40, 12, '', '[{"id":13419,"position":1,"text_uthmani":"ذَٰلِكُم","transliteration":"dhālikum","translation_bn":"\"(বলা হবে) তোমাদের এ (অবস্থা)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":13420,"position":2,"text_uthmani":"بِأَنَّهُۥٓ","transliteration":"bi-annahu","translation_bn":"এ কারণে যে","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":13421,"position":3,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":13422,"position":4,"text_uthmani":"دُعِىَ","transliteration":"duʿiya","translation_bn":"ডাকা হতো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":13423,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহর (দিকে)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13424,"position":6,"text_uthmani":"وَحْدَهُۥ","transliteration":"waḥdahu","translation_bn":"তাঁর একত্বের (প্রতি)","root":"وحد","lemma":"وَحْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":13425,"position":7,"text_uthmani":"كَفَرْتُمْ ۖ","transliteration":"kafartum","translation_bn":"তোমরা অস্বীকার করতে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13427,"position":8,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13428,"position":9,"text_uthmani":"يُشْرَكْ","transliteration":"yush''rak","translation_bn":"শরিক করা হতো","root":"شرك","lemma":"أَشْرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13429,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তাঁর সাথে (অন্য কাউকে)","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":13430,"position":11,"text_uthmani":"تُؤْمِنُوا۟ ۚ","transliteration":"tu''minū","translation_bn":"তোমরা ঈমান আনতে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13432,"position":12,"text_uthmani":"فَٱلْحُكْمُ","transliteration":"fal-ḥuk''mu","translation_bn":"বস্তুতঃ কর্তৃত্ব","root":"حكم","lemma":"حُكْم","grammar_bn":"শব্দ"},{"id":13433,"position":13,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":13434,"position":14,"text_uthmani":"ٱلْعَلِىِّ","transliteration":"l-ʿaliyi","translation_bn":"(যিনি) সমুচ্চ","root":"علو","lemma":"عَلِيّ","grammar_bn":"শব্দ"},{"id":13435,"position":15,"text_uthmani":"ٱلْكَبِيرِ","transliteration":"l-kabīri","translation_bn":"মহান\"","root":"كبر","lemma":"كَبِير","grammar_bn":"শব্দ"},{"id":13436,"position":16,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'dhālikum bi-annahu idhā duʿiya l-lahu waḥdahu kafartum wa-in yush''rak bihi tu''minū fal-ḥuk''mu lillahi l-ʿaliyi l-kabīri', '(তখন তাদেরকে উত্তর দেয়া হবে) তোমাদের এ শাস্তির কারণ এই যে, যখন এক আল্লাহকে ডাকা হত, তখন তোমরা তা মেনে নিতে অস্বীকার করতে। আর যখন অন্যদেরকে তাঁর অংশীদার গণ্য করা হত, তখন তোমরা তাতে বিশ্বাস স্থাপন করতে। হুকুম দেয়ার মালিক আল্লাহ- যিনি সর্বোচ্চ, সর্বশ্রেষ্ঠ।', '[They will be told], "That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand."', '(তখন তাদেরকে উত্তর দেয়া হবে) তোমাদের এ শাস্তির কারণ এই যে, যখন এক আল্লাহকে ডাকা হত, তখন তোমরা তা মেনে নিতে অস্বীকার করতে। আর যখন অন্যদেরকে তাঁর অংশীদার গণ্য করা হত, তখন তোমরা তাতে বিশ্বাস স্থাপন করতে। হুকুম দেয়ার মালিক আল্লাহ- যিনি সর্বোচ্চ, সর্বশ্রেষ্ঠ।', '[They will be told], "That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040012.mp3', now()),
  (40, 13, '', '[{"id":14678,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই (আল্লাহ)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":14679,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14680,"position":3,"text_uthmani":"يُرِيكُمْ","transliteration":"yurīkum","translation_bn":"তোমাদেরকে দেখান","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14681,"position":4,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"নিদর্শনাবলী তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14682,"position":5,"text_uthmani":"وَيُنَزِّلُ","transliteration":"wayunazzilu","translation_bn":"ও নামান","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14683,"position":6,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":14684,"position":7,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14685,"position":8,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":14686,"position":9,"text_uthmani":"رِزْقًۭا ۚ","transliteration":"riz''qan","translation_bn":"জীবনের উপকরণ","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":14688,"position":10,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14689,"position":11,"text_uthmani":"يَتَذَكَّرُ","transliteration":"yatadhakkaru","translation_bn":"শিক্ষাগ্রহণ করে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14690,"position":12,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":14691,"position":13,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14692,"position":14,"text_uthmani":"يُنِيبُ","transliteration":"yunību","translation_bn":"মুখ করে (আল্লাহর দিকে)","root":"نوب","lemma":"أَنَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14693,"position":15,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī yurīkum āyātihi wayunazzilu lakum mina l-samāi riz''qan wamā yatadhakkaru illā man yunību', 'তিনি তাঁর নিদর্শনাবলী তোমাদেরকে দেখান আর আকাশ থেকে তোমাদের জন্য রিযক অবতীর্ণ করেন. আল্লাহ-অভিমুখীরা ছাড়া কেউ উপদেশ গ্রহণ করে না।', 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].', 'তিনি তাঁর নিদর্শনাবলী তোমাদেরকে দেখান আর আকাশ থেকে তোমাদের জন্য রিযক অবতীর্ণ করেন. আল্লাহ-অভিমুখীরা ছাড়া কেউ উপদেশ গ্রহণ করে না।', 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040013.mp3', now()),
  (40, 14, '', '[{"id":15760,"position":1,"text_uthmani":"فَٱدْعُوا۟","transliteration":"fa-id''ʿū","translation_bn":"সুতরাং তোমরা ডাকো","root":"دعو","lemma":"دَعَا","grammar_bn":"শব্দ"},{"id":15761,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15762,"position":3,"text_uthmani":"مُخْلِصِينَ","transliteration":"mukh''liṣīna","translation_bn":"একনিষ্ঠ হয়ে","root":"خلص","lemma":"مُخْلِص","grammar_bn":"বিশেষ্য (Noun)"},{"id":15763,"position":4,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"তাঁরই জন্যে","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":15764,"position":5,"text_uthmani":"ٱلدِّينَ","transliteration":"l-dīna","translation_bn":"আনুগত্যকে (নির্দিষ্ট করে)","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":15765,"position":6,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদিও","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15766,"position":7,"text_uthmani":"كَرِهَ","transliteration":"kariha","translation_bn":"অপছন্দ করে","root":"كره","lemma":"كَرِهَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15767,"position":8,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"কাফেররা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":15768,"position":9,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-id''ʿū l-laha mukh''liṣīna lahu l-dīna walaw kariha l-kāfirūna', 'কাজেই আল্লাহকে ডাক আনুগত্যকে একমাত্র তাঁরই জন্য নিদিষ্ট করো, যদিও কাফিরগণ তা অপছন্দ করে।', 'So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it.', 'কাজেই আল্লাহকে ডাক আনুগত্যকে একমাত্র তাঁরই জন্য নিদিষ্ট করো, যদিও কাফিরগণ তা অপছন্দ করে।', 'So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it.', NULL, NULL, NU