  (40, 15, '', '[{"id":16851,"position":1,"text_uthmani":"رَفِيعُ","transliteration":"rafīʿu","translation_bn":"সমুচ্চ","root":"رفع","lemma":"رَفِيع","grammar_bn":"বিশেষণ (Adjective)"},{"id":16852,"position":2,"text_uthmani":"ٱلدَّرَجَـٰتِ","transliteration":"l-darajāti","translation_bn":"মর্যাদাসমুহের (অধিকারী)","root":"درج","lemma":"دَرَجَة","grammar_bn":"শব্দ"},{"id":16853,"position":3,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"অধিপতি","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":16854,"position":4,"text_uthmani":"ٱلْعَرْشِ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":16855,"position":5,"text_uthmani":"يُلْقِى","transliteration":"yul''qī","translation_bn":"প্রেরণ করেন","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":16856,"position":6,"text_uthmani":"ٱلرُّوحَ","transliteration":"l-rūḥa","translation_bn":"রূহকে (অর্থাৎ ওহী)","root":"روح","lemma":"رُوح","grammar_bn":"শব্দ"},{"id":16857,"position":7,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16858,"position":8,"text_uthmani":"أَمْرِهِۦ","transliteration":"amrihi","translation_bn":"তাঁর নির্দেশে","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":16859,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16860,"position":10,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16861,"position":11,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16862,"position":12,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16863,"position":13,"text_uthmani":"عِبَادِهِۦ","transliteration":"ʿibādihi","translation_bn":"তাঁর দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":16864,"position":14,"text_uthmani":"لِيُنذِرَ","transliteration":"liyundhira","translation_bn":"যেন সতর্ক করে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":16865,"position":15,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিন (সম্পর্ক)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16866,"position":16,"text_uthmani":"ٱلتَّلَاقِ","transliteration":"l-talāqi","translation_bn":"সাক্ষাতের","root":"لقي","lemma":"تَّلَاق","grammar_bn":"শব্দ"},{"id":16867,"position":17,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'rafīʿu l-darajāti dhū l-ʿarshi yul''qī l-rūḥa min amrihi ʿalā man yashāu min ʿibādihi liyundhira yawma l-talāqi', 'তিনি সর্বোচ্চ মর্যাদার অধিকারী, ‘আরশের অধিপতি। তিনি তাঁর নির্দেশে তাঁর বান্দাদের যার প্রতি ইচ্ছে ওয়াহী প্রেরণ করেন যাতে সে সাক্ষাতের দিন সম্পর্কে সতর্ক করে।', '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting.', 'তিনি সর্বোচ্চ মর্যাদার অধিকারী, ‘আরশের অধিপতি। তিনি তাঁর নির্দেশে তাঁর বান্দাদের যার প্রতি ইচ্ছে ওয়াহী প্রেরণ করেন যাতে সে সাক্ষাতের দিন সম্পর্কে সতর্ক করে।', '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040015.mp3', now()),
  (40, 16, '', '[{"id":18001,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18002,"position":2,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":18003,"position":3,"text_uthmani":"بَـٰرِزُونَ ۖ","transliteration":"bārizūna","translation_bn":"বের হয়ে পড়বে","root":"برز","lemma":"بَٰرِزُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":18005,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":18006,"position":5,"text_uthmani":"يَخْفَىٰ","transliteration":"yakhfā","translation_bn":"গোপন থাকবে","root":"خفي","lemma":"يَخْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18007,"position":6,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18008,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18009,"position":8,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18010,"position":9,"text_uthmani":"شَىْءٌۭ ۚ","transliteration":"shayon","translation_bn":"কোনো কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":18012,"position":10,"text_uthmani":"لِّمَنِ","transliteration":"limani","translation_bn":"(জিজ্ঞেস করা হবে) কার","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18013,"position":11,"text_uthmani":"ٱلْمُلْكُ","transliteration":"l-mul''ku","translation_bn":"কর্তৃত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":18014,"position":12,"text_uthmani":"ٱلْيَوْمَ ۖ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":18016,"position":13,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"(সবাই বলবে) আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":18017,"position":14,"text_uthmani":"ٱلْوَٰحِدِ","transliteration":"l-wāḥidi","translation_bn":"(যিনি) এক ও একক","root":"وحد","lemma":"وَٰحِد","grammar_bn":"শব্দ"},{"id":18018,"position":15,"text_uthmani":"ٱلْقَهَّارِ","transliteration":"l-qahāri","translation_bn":"পরাক্রমশালী","root":"قهر","lemma":"قَهَّار","grammar_bn":"শব্দ"},{"id":18019,"position":16,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'yawma hum bārizūna lā yakhfā ʿalā l-lahi min''hum shayon limani l-mul''ku l-yawma lillahi l-wāḥidi l-qahāri', 'মানুষ যেদিন (ক্ববর থেকে) বের হয়ে আসবে, আল্লাহর কাছে তাদের কোন কিছুই গোপন থাকবে না। (সেদিন ঘোষণা দেয়া হবে) আজ একচ্ছত্র কর্তৃত্ব কার? (উত্তর আসবে) এক ও একক মহাপরাক্রমশালী আল্লাহর।', 'The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing.', 'মানুষ যেদিন (ক্ববর থেকে) বের হয়ে আসবে, আল্লাহর কাছে তাদের কোন কিছুই গোপন থাকবে না। (সেদিন ঘোষণা দেয়া হবে) আজ একচ্ছত্র কর্তৃত্ব কার? (উত্তর আসবে) এক ও একক মহাপরাক্রমশালী আল্লাহর।', 'The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040016.mp3', now()),
  (40, 17, '', '[{"id":19002,"position":1,"text_uthmani":"ٱلْيَوْمَ","transliteration":"al-yawma","translation_bn":"(বলা হবে) আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":19003,"position":2,"text_uthmani":"تُجْزَىٰ","transliteration":"tuj''zā","translation_bn":"প্রতিফল দেওয়া হবে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19004,"position":3,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19005,"position":4,"text_uthmani":"نَفْسٍۭ","transliteration":"nafsin","translation_bn":"ব্যক্তিকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":19006,"position":5,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ের যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19007,"position":6,"text_uthmani":"كَسَبَتْ ۚ","transliteration":"kasabat","translation_bn":"সে কামাই করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19009,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":19010,"position":8,"text_uthmani":"ظُلْمَ","transliteration":"ẓul''ma","translation_bn":"অত্যাচার","root":"ظلم","lemma":"ظُلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19011,"position":9,"text_uthmani":"ٱلْيَوْمَ ۚ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":19013,"position":10,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19014,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19015,"position":12,"text_uthmani":"سَرِيعُ","transliteration":"sarīʿu","translation_bn":"তৎপর","root":"سرع","lemma":"سَرِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19016,"position":13,"text_uthmani":"ٱلْحِسَابِ","transliteration":"l-ḥisābi","translation_bn":"হিসাব গ্রহণে","root":"حسب","lemma":"حِسَاب","grammar_bn":"শব্দ"},{"id":19017,"position":14,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'al-yawma tuj''zā kullu nafsin bimā kasabat lā ẓul''ma l-yawma inna l-laha sarīʿu l-ḥisābi', 'প্রত্যেক ব্যক্তি যে কর্ম করেছে আজ তার প্রতিফল দেয়া হবে। আজ নেই কোন যুলম। আল্লাহ অতি দ্রুত হিসাব গ্রহণকারী।', 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account.', 'প্রত্যেক ব্যক্তি যে কর্ম করেছে আজ তার প্রতিফল দেয়া হবে। আজ নেই কোন যুলম। আল্লাহ অতি দ্রুত হিসাব গ্রহণকারী।', 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040017.mp3', now()),
  (40, 18, '', '[{"id":20121,"position":1,"text_uthmani":"وَأَنذِرْهُمْ","transliteration":"wa-andhir''hum","translation_bn":"এবং (হে নাবী) তাদেরকে সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20122,"position":2,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেই দিন (সম্পর্কে)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20123,"position":3,"text_uthmani":"ٱلْـَٔازِفَةِ","transliteration":"l-āzifati","translation_bn":"(যা) আসন্ন","root":"ازف","lemma":"ءَازِفَة","grammar_bn":"শব্দ"},{"id":20124,"position":4,"text_uthmani":"إِذِ","transliteration":"idhi","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":20125,"position":5,"text_uthmani":"ٱلْقُلُوبُ","transliteration":"l-qulūbu","translation_bn":"অন্তরসমূহ (কলিজাসমূহ)","root":"قلب","lemma":"قَلْب","grammar_bn":"শব্দ"},{"id":20126,"position":6,"text_uthmani":"لَدَى","transliteration":"ladā","translation_bn":"নিকট (আসবে)","root":"—","lemma":"لَدَى\r","grammar_bn":"স্থানবাচক (Location)"},{"id":20127,"position":7,"text_uthmani":"ٱلْحَنَاجِرِ","transliteration":"l-ḥanājiri","translation_bn":"কন্ঠসমূহের","root":"حنجر","lemma":"حَنَاجِر","grammar_bn":"শব্দ"},{"id":20128,"position":8,"text_uthmani":"كَـٰظِمِينَ ۚ","transliteration":"kāẓimīna","translation_bn":"দুঃখ-কষ্টে","root":"كظم","lemma":"كَٰظِمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":20130,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20131,"position":10,"text_uthmani":"لِلظَّـٰلِمِينَ","transliteration":"lilẓẓālimīna","translation_bn":"সীমালঙ্ঘনকারীদের জন্যে (থাকবে)","root":"ظلم","lemma":"ظَالِم","grammar_bn":"অব্যয় (Preposition)"},{"id":20132,"position":11,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20133,"position":12,"text_uthmani":"حَمِيمٍۢ","transliteration":"ḥamīmin","translation_bn":"অন্তরঙ্গ","root":"حمم","lemma":"حَمِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20134,"position":13,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20135,"position":14,"text_uthmani":"شَفِيعٍۢ","transliteration":"shafīʿin","translation_bn":"কোনো সুপারিশকারী","root":"شفع","lemma":"شَفِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":20136,"position":15,"text_uthmani":"يُطَاعُ","transliteration":"yuṭāʿu","translation_bn":"মেনে নেওয়া হবে (যার কথা)","root":"طوع","lemma":"يُطَاعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20137,"position":16,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-andhir''hum yawma l-āzifati idhi l-qulūbu ladā l-ḥanājiri kāẓimīna mā lilẓẓālimīna min ḥamīmin walā shafīʿin yuṭāʿu', 'তাদেরকে সতর্ক কর সেই ঘনিয়ে আসা দিন সম্পর্কে যখন ওষ্ঠাগত প্রাণ নিয়ে তারা দুঃখ-কষ্ট সংবরণ করবে। যালিমদের জন্য কোন অন্তরঙ্গ বন্ধু থাকবে না, এমন কোন সুপারিশকারীও থাকবে না যার কথা গ্রহণ করা হবে।', 'And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.', 'তাদেরকে সতর্ক কর সেই ঘনিয়ে আসা দিন সম্পর্কে যখন ওষ্ঠাগত প্রাণ নিয়ে তারা দুঃখ-কষ্ট সংবরণ করবে। যালিমদের জন্য কোন অন্তরঙ্গ বন্ধু থাকবে না, এমন কোন সুপারিশকারীও থাকবে না যার কথা গ্রহণ করা হবে।', 'And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040018.mp3', now()),
  (40, 19, '', '[{"id":21189,"position":1,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"(আল্লাহ) জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21190,"position":2,"text_uthmani":"خَآئِنَةَ","transliteration":"khāinata","translation_bn":"প্রতারণা","root":"خون","lemma":"خَا^ئِنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21191,"position":3,"text_uthmani":"ٱلْأَعْيُنِ","transliteration":"l-aʿyuni","translation_bn":"চোখের (অর্থাৎ চোখের চুরিও)","root":"عين","lemma":"عَيْن","grammar_bn":"শব্দ"},{"id":21192,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21193,"position":5,"text_uthmani":"تُخْفِى","transliteration":"tukh''fī","translation_bn":"গোপন করে রাখে","root":"خفي","lemma":"أُخْفِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21194,"position":6,"text_uthmani":"ٱلصُّدُورُ","transliteration":"l-ṣudūru","translation_bn":"অন্তরসমূহ","root":"صدر","lemma":"صَدْر","grammar_bn":"শব্দ"},{"id":21195,"position":7,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'yaʿlamu khāinata l-aʿyuni wamā tukh''fī l-ṣudūru', 'আল্লাহ চক্ষুর অন্যায় কর্ম সম্পর্কেও অবগত, আর অন্তর যা গোপন করে সে সম্পর্কেও।', 'He knows that which deceives the eyes and what the breasts conceal.', 'আল্লাহ চক্ষুর অন্যায় কর্ম সম্পর্কেও অবগত, আর অন্তর যা গোপন করে সে সম্পর্কেও।', 'He knows that which deceives the eyes and what the breasts conceal.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040019.mp3', now()),
  (40, 20, '', '[{"id":22293,"position":1,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22294,"position":2,"text_uthmani":"يَقْضِى","transliteration":"yaqḍī","translation_bn":"মীমাংসা করবেন","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":22295,"position":3,"text_uthmani":"بِٱلْحَقِّ ۖ","transliteration":"bil-ḥaqi","translation_bn":"সঠিকভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":22297,"position":4,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":22298,"position":5,"text_uthmani":"يَدْعُونَ","transliteration":"yadʿūna","translation_bn":"তারা ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":22299,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22300,"position":7,"text_uthmani":"دُونِهِۦ","transliteration":"dūnihi","translation_bn":"তাঁকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":22301,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":22302,"position":9,"text_uthmani":"يَقْضُونَ","transliteration":"yaqḍūna","translation_bn":"মীমাংসা করবে তারা","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":22303,"position":10,"text_uthmani":"بِشَىْءٍ ۗ","transliteration":"bishayin","translation_bn":"কোনো কিছুরই","root":"شيا","lemma":"شَىْء","grammar_bn":"অব্যয় (Preposition)"},{"id":22305,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":22306,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22307,"position":13,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22308,"position":14,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":22309,"position":15,"text_uthmani":"ٱلْبَصِيرُ","transliteration":"l-baṣīru","translation_bn":"সবকিছু দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"শব্দ"},{"id":22310,"position":16,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wal-lahu yaqḍī bil-ḥaqi wa-alladhīna yadʿūna min dūnihi lā yaqḍūna bishayin inna l-laha huwa l-samīʿu l-baṣīru', 'আল্লাহ হক্ব বিচার করেন। তারা আল্লাহর পরিবর্তে যাদেরকে ডাকে তারা মোটেই বিচার করতে পারে না। আল্লাহ সব কিছু শোনেন, সব কিছু দেখেন।', 'And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing.', 'আল্লাহ হক্ব বিচার করেন। তারা আল্লাহর পরিবর্তে যাদেরকে ডাকে তারা মোটেই বিচার করতে পারে না। আল্লাহ সব কিছু শোনেন, সব কিছু দেখেন।', 'And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040020.mp3', now()),
  (40, 21, '', '[{"id":23398,"position":1,"text_uthmani":"۞ أَوَلَمْ","transliteration":"awalam","translation_bn":"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":23399,"position":2,"text_uthmani":"يَسِيرُوا۟","transliteration":"yasīrū","translation_bn":"তারা ভ্রমণ করে","root":"سير","lemma":"سَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23400,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23401,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":23402,"position":5,"text_uthmani":"فَيَنظُرُوا۟","transliteration":"fayanẓurū","translation_bn":"তাহ''লে তারা দেখতে পেতো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23403,"position":6,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":23404,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23405,"position":8,"text_uthmani":"عَـٰقِبَةُ","transliteration":"ʿāqibatu","translation_bn":"পরিণাম","root":"عقب","lemma":"عَٰقِبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23406,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23407,"position":10,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23408,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23409,"position":12,"text_uthmani":"قَبْلِهِمْ ۚ","transliteration":"qablihim","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23411,"position":13,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23412,"position":14,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":23413,"position":15,"text_uthmani":"أَشَدَّ","transliteration":"ashadda","translation_bn":"প্রবল","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23414,"position":16,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"এদের চেয়েও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23415,"position":17,"text_uthmani":"قُوَّةًۭ","transliteration":"quwwatan","translation_bn":"শক্তিতে","root":"قوي","lemma":"قُوَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23416,"position":18,"text_uthmani":"وَءَاثَارًۭا","transliteration":"waāthāran","translation_bn":"ও কীর্তিসমূহে","root":"اثر","lemma":"أَثَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23417,"position":19,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23418,"position":20,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":23419,"position":21,"text_uthmani":"فَأَخَذَهُمُ","transliteration":"fa-akhadhahumu","translation_bn":"তাদেরকে অতঃপর পাকড়াও করলেন","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":23420,"position":22,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23421,"position":23,"text_uthmani":"بِذُنُوبِهِمْ","transliteration":"bidhunūbihim","translation_bn":"তাদের পাপসমূহের কারণে","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":23422,"position":24,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23423,"position":25,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23424,"position":26,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":23425,"position":27,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23426,"position":28,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23427,"position":29,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23428,"position":30,"text_uthmani":"وَاقٍۢ","transliteration":"wāqin","translation_bn":"রক্ষাকারী","root":"وقي","lemma":"وَاق","grammar_bn":"বিশেষ্য (Noun)"},{"id":23429,"position":31,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yasīrū fī l-arḍi fayanẓurū kayfa kāna ʿāqibatu alladhīna kānū min qablihim kānū hum ashadda min''hum quwwatan waāthāran fī l-arḍi fa-akhadhahumu l-lahu bidhunūbihim wamā kāna lahum mina l-lahi min wāqin', 'তারা কি পৃথিবীতে ভ্রমণ করে না, তাহলে দেখতে পেত তাদের পূর্বে যারা ছিল তাদের পরিণাম কী হয়েছিল। তারা শক্তিতে আর স্মৃতি চিহ্নে ছিল এদের চেয়ে প্রবল। অতঃপর তাদের পাপের কারণে আল্লাহ তাদেরকে পাকড়াও করেছিলেন, আল্লাহর শাস্তি থেকে তাদেরকে বাঁচানোর কেউ ছিল না।', 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector.', 'তারা কি পৃথিবীতে ভ্রমণ করে না, তাহলে দেখতে পেত তাদের পূর্বে যারা ছিল তাদের পরিণাম কী হয়েছিল। তারা শক্তিতে আর স্মৃতি চিহ্নে ছিল এদের চেয়ে প্রবল। অতঃপর তাদের পাপের কারণে আল্লাহ তাদেরকে পাকড়াও করেছিলেন, আল্লাহর শাস্তি থেকে তাদেরকে বাঁচানোর কেউ ছিল না।', 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040021.mp3', now()),
  (40, 22, '', '[{"id":24399,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":24400,"position":2,"text_uthmani":"بِأَنَّهُمْ","transliteration":"bi-annahum","translation_bn":"এ কারণে যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":24401,"position":3,"text_uthmani":"كَانَت","transliteration":"kānat","translation_bn":"কাছে আসতো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24402,"position":4,"text_uthmani":"تَّأْتِيهِمْ","transliteration":"tatīhim","translation_bn":"তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":24403,"position":5,"text_uthmani":"رُسُلُهُم","transliteration":"rusuluhum","translation_bn":"তাদের রাসূলগণ","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":24404,"position":6,"text_uthmani":"بِٱلْبَيِّنَـٰتِ","transliteration":"bil-bayināti","translation_bn":"নিদর্শনাবলীসহ","root":"بين","lemma":"بَيِّنَة","grammar_bn":"অব্যয় (Preposition)"},{"id":24405,"position":7,"text_uthmani":"فَكَفَرُوا۟","transliteration":"fakafarū","translation_bn":"কিন্তু তারা অস্বীকার করতো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"শব্দ"},{"id":24406,"position":8,"text_uthmani":"فَأَخَذَهُمُ","transliteration":"fa-akhadhahumu","translation_bn":"তখন তাদেরকে শাস্তি দিলেন","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":24407,"position":9,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24409,"position":10,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24410,"position":11,"text_uthmani":"قَوِىٌّۭ","transliteration":"qawiyyun","translation_bn":"শক্তিশালী","root":"قوي","lemma":"قَوِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24411,"position":12,"text_uthmani":"شَدِيدُ","transliteration":"shadīdu","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":24412,"position":13,"text_uthmani":"ٱلْعِقَابِ","transliteration":"l-ʿiqābi","translation_bn":"শাস্তিদানে","root":"عقب","lemma":"عِقَاب","grammar_bn":"শব্দ"},{"id":24413,"position":14,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika bi-annahum kānat tatīhim rusuluhum bil-bayināti fakafarū fa-akhadhahumu l-lahu innahu qawiyyun shadīdu l-ʿiqābi', 'এটা এজন্য যে, রসূলগণ তাদের কাছে স্পষ্ট (নিদর্শন) নিয়ে এসেছিল। কিন্তু তারা তাদেরকে প্রত্যাখ্যান করেছিল। তখন আল্লাহ তাদেরকে পাকড়াও করেছিলেন। তিনি প্রবল শক্তিধর, শাস্তিদানে কঠোর।', 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment.', 'এটা এজন্য যে, রসূলগণ তাদের কাছে স্পষ্ট (নিদর্শন) নিয়ে এসেছিল। কিন্তু তারা তাদেরকে প্রত্যাখ্যান করেছিল। তখন আল্লাহ তাদেরকে পাকড়াও করেছিলেন। তিনি প্রবল শক্তিধর, শাস্তিদানে কঠোর।', 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040022.mp3', now()),
  (40, 23, '', '[{"id":25471,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25472,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25473,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25474,"position":4,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"আমাদের নিদর্শনাবলীসহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":25475,"position":5,"text_uthmani":"وَسُلْطَـٰنٍۢ","transliteration":"wasul''ṭānin","translation_bn":"ও প্রমাণ (সহ)","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25476,"position":6,"text_uthmani":"مُّبِينٍ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":25477,"position":7,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad arsalnā mūsā biāyātinā wasul''ṭānin mubīnin', 'আমি মূসাকে আমার নিদর্শন ও সুস্পষ্ট ফরমান দিয়ে পাঠিয়েছিলাম', 'And We did certainly send Moses with Our signs and a clear authority', 'আমি মূসাকে আমার নিদর্শন ও সুস্পষ্ট ফরমান দিয়ে পাঠিয়েছিলাম', 'And We did certainly send Moses with Our signs and a clear authority', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040023.mp3', now()),
  (40, 24, '', '[{"id":26555,"position":1,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"নিকটে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26556,"position":2,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26557,"position":3,"text_uthmani":"وَهَـٰمَـٰنَ","transliteration":"wahāmāna","translation_bn":"ও হামানের","root":"—","lemma":"هَٰمَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26558,"position":4,"text_uthmani":"وَقَـٰرُونَ","transliteration":"waqārūna","translation_bn":"ও কারূনের","root":"—","lemma":"قَٰرُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26559,"position":5,"text_uthmani":"فَقَالُوا۟","transliteration":"faqālū","translation_bn":"তারা কিন্তু বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":26560,"position":6,"text_uthmani":"سَـٰحِرٌۭ","transliteration":"sāḥirun","translation_bn":"\"(সে একজন) যাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":26561,"position":7,"text_uthmani":"كَذَّابٌۭ","transliteration":"kadhābun","translation_bn":"মিথ্যাবাদী\"","root":"كذب","lemma":"كَذَّاب","grammar_bn":"বিশেষণ (Adjective)"},{"id":26562,"position":8,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'ilā fir''ʿawna wahāmāna waqārūna faqālū sāḥirun kadhābun', 'ফেরাউন, হামান ও কারূনের কাছে। কিন্তু তারা বলল (এ লোকটা) এক যাদুকর, ঘোর মিথ্যুক।', 'To Pharaoh, Haman and Qarun; but they said, "[He is] a magician and a liar."', 'ফেরাউন, হামান ও কারূনের কাছে। কিন্তু তারা বলল (এ লোকটা) এক যাদুকর, ঘোর মিথ্যুক।', 'To Pharaoh, Haman and Qarun; but they said, "[He is] a magician and a liar."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040024.mp3', now()),
  (40, 25, '', '[{"id":27550,"position":1,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"পরে যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":27551,"position":2,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"তাদের কাছে নিয়ে এলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27552,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"প্রকৃত সত্যসহ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":27553,"position":4,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27554,"position":5,"text_uthmani":"عِندِنَا","transliteration":"ʿindinā","translation_bn":"আমাদের নিকট","root":"عند","lemma":"عِند","grammar_bn":"বিশেষ্য (Noun)"},{"id":27555,"position":6,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27556,"position":7,"text_uthmani":"ٱقْتُلُوٓا۟","transliteration":"uq''tulū","translation_bn":"\"তোমরা হত্যা করো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27557,"position":8,"text_uthmani":"أَبْنَآءَ","transliteration":"abnāa","translation_bn":"পুত্র সন্তানদেরকে","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":27558,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27559,"position":10,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27560,"position":11,"text_uthmani":"مَعَهُۥ","transliteration":"maʿahu","translation_bn":"তার সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":27561,"position":12,"text_uthmani":"وَٱسْتَحْيُوا۟","transliteration":"wa-is''taḥyū","translation_bn":"এবং তোমরা জীবিত রাখো","root":"حيي","lemma":"يَسْتَحْىِ.^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27562,"position":13,"text_uthmani":"نِسَآءَهُمْ ۚ","transliteration":"nisāahum","translation_bn":"তাদের নারীদেরকে\"","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":27564,"position":14,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নয়","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27565,"position":15,"text_uthmani":"كَيْدُ","transliteration":"kaydu","translation_bn":"ষড়যন্ত্র","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":27566,"position":16,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফেরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":27567,"position":17,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27568,"position":18,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27569,"position":19,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"ভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":27570,"position":20,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'falammā jāahum bil-ḥaqi min ʿindinā qālū uq''tulū abnāa alladhīna āmanū maʿahu wa-is''taḥyū nisāahum wamā kaydu l-kāfirīna illā fī ḍalālin', 'তারপর যখন মূসা তাদের কাছে আমার সত্যসহ আসল তখন তারা বলল- এর সঙ্গে যারা ঈমান এনেছে তাদের পুত্র সন্তানদের হত্যা কর, আর তাদের নারীদেরকে জীবিত রাখ। কাফিরদের ষড়যন্ত্র অকার্যকর ছাড়া আর কিছুই না।', 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.', 'তারপর যখন মূসা তাদের কাছে আমার সত্যসহ আসল তখন তারা বলল- এর সঙ্গে যারা ঈমান এনেছে তাদের পুত্র সন্তানদের হত্যা কর, আর তাদের নারীদেরকে জীবিত রাখ। কাফিরদের ষড়যন্ত্র অকার্যকর ছাড়া আর কিছুই না।', 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040025.mp3', now()),
  (40, 26, '', '[{"id":28538,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28539,"position":2,"text_uthmani":"فِرْعَوْنُ","transliteration":"fir''ʿawnu","translation_bn":"ফিরআউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28540,"position":3,"text_uthmani":"ذَرُونِىٓ","transliteration":"dharūnī","translation_bn":"\"আমাকে ছাড়ো","root":"وذر","lemma":"يَذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28541,"position":4,"text_uthmani":"أَقْتُلْ","transliteration":"aqtul","translation_bn":"আমি হত্যা করে ফেলি","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28542,"position":5,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28543,"position":6,"text_uthmani":"وَلْيَدْعُ","transliteration":"walyadʿu","translation_bn":"এবং সে ডাকে যেন","root":"دعو","lemma":"دَعَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28544,"position":7,"text_uthmani":"رَبَّهُۥٓ ۖ","transliteration":"rabbahu","translation_bn":"তাঁর রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28546,"position":8,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28547,"position":9,"text_uthmani":"أَخَافُ","transliteration":"akhāfu","translation_bn":"আমি আশংকা করি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28548,"position":10,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":28549,"position":11,"text_uthmani":"يُبَدِّلَ","transliteration":"yubaddila","translation_bn":"সে পাল্টে দিবে","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28550,"position":12,"text_uthmani":"دِينَكُمْ","transliteration":"dīnakum","translation_bn":"তোমাদের ধর্মকে","root":"دين","lemma":"دِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":28551,"position":13,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28552,"position":14,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":28553,"position":15,"text_uthmani":"يُظْهِرَ","transliteration":"yuẓ''hira","translation_bn":"সৃষ্টি করবে","root":"ظهر","lemma":"أَظْهَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28554,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28555,"position":17,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"দেশের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":28556,"position":18,"text_uthmani":"ٱلْفَسَادَ","transliteration":"l-fasāda","translation_bn":"বিপর্যয়\"","root":"فسد","lemma":"فَسَاد","grammar_bn":"শব্দ"},{"id":28557,"position":19,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla fir''ʿawnu dharūnī aqtul mūsā walyadʿu rabbahu innī akhāfu an yubaddila dīnakum aw an yuẓ''hira fī l-arḍi l-fasāda', 'ফিরআউন বলল- ছেড়ে দাও আমাকে, আমি মূসাকে হত্যা করব, ডাকুক সে তার রব্বকে। আমি আশঙ্কা করছি, সে তোমাদের জীবন পদ্ধতিকে বদলে দেবে কিংবা দেশে বিপর্যয় বিশৃঙ্খলা সৃষ্টি করবে।', 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."', 'ফিরআউন বলল- ছেড়ে দাও আমাকে, আমি মূসাকে হত্যা করব, ডাকুক সে তার রব্বকে। আমি আশঙ্কা করছি, সে তোমাদের জীবন পদ্ধতিকে বদলে দেবে কিংবা দেশে বিপর্যয় বিশৃঙ্খলা সৃষ্টি করবে।', 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040026.mp3', now()),
  (40, 27, '', '[{"id":29483,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29484,"position":2,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29485,"position":3,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29486,"position":4,"text_uthmani":"عُذْتُ","transliteration":"ʿudh''tu","translation_bn":"আমি আশ্রয় চাই","root":"عوذ","lemma":"عُذْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29487,"position":5,"text_uthmani":"بِرَبِّى","transliteration":"birabbī","translation_bn":"আমার রবের কাছে","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":29488,"position":6,"text_uthmani":"وَرَبِّكُم","transliteration":"warabbikum","translation_bn":"ও তোমাদের রবের (কাছে)","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29489,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29490,"position":8,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":29491,"position":9,"text_uthmani":"مُتَكَبِّرٍۢ","transliteration":"mutakabbirin","translation_bn":"অহংকারী ব্যক্তি","root":"كبر","lemma":"مُتَكَبِّر","grammar_bn":"বিশেষ্য (Noun)"},{"id":29492,"position":10,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"(যে) না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":29493,"position":11,"text_uthmani":"يُؤْمِنُ","transliteration":"yu''minu","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29494,"position":12,"text_uthmani":"بِيَوْمِ","transliteration":"biyawmi","translation_bn":"দিনের প্রতি","root":"يوم","lemma":"يَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":29495,"position":13,"text_uthmani":"ٱلْحِسَابِ","transliteration":"l-ḥisābi","translation_bn":"বিচারের\"","root":"حسب","lemma":"حِسَاب","grammar_bn":"শব্দ"},{"id":29496,"position":14,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'waqāla mūsā innī ʿudh''tu birabbī warabbikum min kulli mutakabbirin lā yu''minu biyawmi l-ḥisābi', 'মূসা বলল- আমি আমার ও তোমাদের প্রতিপালকের আশ্রয় গ্রহণ করছি সকল দাম্ভিক অহংকারীদের হতে, যারা বিচার দিবসে বিশ্বাস করে না।', 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."', 'মূসা বলল- আমি আমার ও তোমাদের প্রতিপালকের আশ্রয় গ্রহণ করছি সকল দাম্ভিক অহংকারীদের হতে, যারা বিচার দিবসে বিশ্বাস করে না।', 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/040027.mp3', now()),
  (40, 28, '', '[{"id":30484,"position":1,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30485,"position":2,"text_uthmani":"رَجُلٌۭ","transliteration":"rajulun","translation_bn":"এক ব্যক্তি","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":30486,"position":3,"text_uthmani":"مُّؤْمِنٌۭ","transliteration":"mu''minun","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":30487,"position":4,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্যে হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30488,"position":5,"text_uthmani":"ءَالِ","transliteration":"āli","translation_bn":"সম্প্রদায়ের","root":"اول","lemma":"ءَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":30489,"position":6,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30490,"position":7,"text_uthmani":"يَكْتُمُ","transliteration":"yaktumu","translation_bn":"যে গোপন রেখেছিলো","root":"كتم","lemma":"كَتَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30491,"position":8,"text_uthmani":"إِيمَـٰنَهُۥٓ","transliteration":"īmānahu","translation_bn":"তার ঈমান","root":"امن","lemma":"إِيمَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":30492,"position":9,"text_uthmani":"أَتَقْتُلُونَ","transliteration":"ataqtulūna","translation_bn":"\"তোমরা হত্যা করবে কি","root":"قتل","lemma":"قَتَلَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":30493,"position":10,"text_uthmani":"رَجُلًا","transliteration":"rajulan","translation_bn":"এক ব্যক্তিকে","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":30494,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এ কারণে) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":30495,"position":12,"text_uthmani":"يَقُولَ",