  (41, 1, '', '[{"id":106,"position":1,"text_uthmani":"حمٓ","transliteration":"hha-meem","translation_bn":"হা-মীম","root":"—","lemma":"حمٓ","grammar_bn":"শব্দ"},{"id":107,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hha-meem', 'হা-মীম।', 'Ha, Meem.', 'হা-মীম।', 'Ha, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041001.mp3', now()),
  (41, 2, '', '[{"id":956,"position":1,"text_uthmani":"تَنزِيلٌۭ","transliteration":"tanzīlun","translation_bn":"অবতরণ করা (হয়েছে এটা)","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":957,"position":2,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"(আল্লাহর) পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":958,"position":3,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"(যিনি) অশেষ দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":959,"position":4,"text_uthmani":"ٱلرَّحِيمِ","transliteration":"l-raḥīmi","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":960,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlun mina l-raḥmāni l-raḥīmi', 'পরম দয়াময়, পরম দয়ালুর নিকট হতে অবতীর্ণ।', '[This is] a revelation from the Entirely Merciful, the Especially Merciful -', 'পরম দয়াময়, পরম দয়ালুর নিকট হতে অবতীর্ণ।', '[This is] a revelation from the Entirely Merciful, the Especially Merciful -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041002.mp3', now()),
  (41, 3, '', '[{"id":2059,"position":1,"text_uthmani":"كِتَـٰبٌۭ","transliteration":"kitābun","translation_bn":"এই কিতাব (এমন যে)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":2060,"position":2,"text_uthmani":"فُصِّلَتْ","transliteration":"fuṣṣilat","translation_bn":"বিশদভাবে বিবৃত","root":"فصل","lemma":"فَصَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2061,"position":3,"text_uthmani":"ءَايَـٰتُهُۥ","transliteration":"āyātuhu","translation_bn":"তার আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2062,"position":4,"text_uthmani":"قُرْءَانًا","transliteration":"qur''ānan","translation_bn":"কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2063,"position":5,"text_uthmani":"عَرَبِيًّۭا","transliteration":"ʿarabiyyan","translation_bn":"আরবী (ভাষার)","root":"عرب","lemma":"عَرَبِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":2064,"position":6,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"(এমন) সম্প্রদায়ের জন্যে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":2065,"position":7,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"(যারা) জ্ঞান রাখে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2066,"position":8,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'kitābun fuṣṣilat āyātuhu qur''ānan ʿarabiyyan liqawmin yaʿlamūna', 'এক কিতাব, যার আয়াতগুলো বিস্তারিতভাবে ব্যাখ্যাকৃত, আরবী ভাষার কুরআন, জ্ঞানসম্পন্ন মানুষদের জন্য।', 'A Book whose verses have been detailed, an Arabic Qur''an for a people who know,', 'এক কিতাব, যার আয়াতগুলো বিস্তারিতভাবে ব্যাখ্যাকৃত, আরবী ভাষার কুরআন, জ্ঞানসম্পন্ন মানুষদের জন্য।', 'A Book whose verses have been detailed, an Arabic Qur''an for a people who know,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041003.mp3', now()),
  (41, 4, '', '[{"id":3312,"position":1,"text_uthmani":"بَشِيرًۭا","transliteration":"bashīran","translation_bn":"(এই কিতাব) সুসংবাদদাতা","root":"بشر","lemma":"بَشِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":3313,"position":2,"text_uthmani":"وَنَذِيرًۭا","transliteration":"wanadhīran","translation_bn":"ও সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3314,"position":3,"text_uthmani":"فَأَعْرَضَ","transliteration":"fa-aʿraḍa","translation_bn":"কিন্তু বিমুখ হয়েছে","root":"عرض","lemma":"أَعْرَضَ","grammar_bn":"শব্দ"},{"id":3315,"position":4,"text_uthmani":"أَكْثَرُهُمْ","transliteration":"aktharuhum","translation_bn":"তাদের অনেকেই","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":3316,"position":5,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"সুতরাং তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":3317,"position":6,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":3318,"position":7,"text_uthmani":"يَسْمَعُونَ","transliteration":"yasmaʿūna","translation_bn":"শুনে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3319,"position":8,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'bashīran wanadhīran fa-aʿraḍa aktharuhum fahum lā yasmaʿūna', 'সুসংবাদবাহী ও সাবধানকারী। কিন্তু ওদের অধিকাংশই (এ কুরআন থেকে) মুখ ফিরিয়ে নিয়েছে, কাজেই ওরা শুনবে না।', 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.', 'সুসংবাদবাহী ও সাবধানকারী। কিন্তু ওদের অধিকাংশই (এ কুরআন থেকে) মুখ ফিরিয়ে নিয়েছে, কাজেই ওরা শুনবে না।', 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041004.mp3', now()),
  (41, 5, '', '[{"id":4653,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4654,"position":2,"text_uthmani":"قُلُوبُنَا","transliteration":"qulūbunā","translation_bn":"\"আমাদের অন্তরগুলো","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4655,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4656,"position":4,"text_uthmani":"أَكِنَّةٍۢ","transliteration":"akinnatin","translation_bn":"পর্দাসমূহের","root":"كنن","lemma":"أَكِنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4657,"position":5,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"তা থেকে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4658,"position":6,"text_uthmani":"تَدْعُونَآ","transliteration":"tadʿūnā","translation_bn":"আমাদেরকে তোমরা ডাকছো","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":4659,"position":7,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4660,"position":8,"text_uthmani":"وَفِىٓ","transliteration":"wafī","translation_bn":"এবং মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4661,"position":9,"text_uthmani":"ءَاذَانِنَا","transliteration":"ādhāninā","translation_bn":"আমাদের কানসমূহের","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4662,"position":10,"text_uthmani":"وَقْرٌۭ","transliteration":"waqrun","translation_bn":"বধিরতা (রয়েছে)","root":"وقر","lemma":"وَقْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4663,"position":11,"text_uthmani":"وَمِنۢ","transliteration":"wamin","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4664,"position":12,"text_uthmani":"بَيْنِنَا","transliteration":"bayninā","translation_bn":"এবং আমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4665,"position":13,"text_uthmani":"وَبَيْنِكَ","transliteration":"wabaynika","translation_bn":"ও তোমার মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4666,"position":14,"text_uthmani":"حِجَابٌۭ","transliteration":"ḥijābun","translation_bn":"পর্দা (রয়েছে)","root":"حجب","lemma":"حِجَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4667,"position":15,"text_uthmani":"فَٱعْمَلْ","transliteration":"fa-iʿ''mal","translation_bn":"তুমি তাই কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"শব্দ"},{"id":4668,"position":16,"text_uthmani":"إِنَّنَا","transliteration":"innanā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4669,"position":17,"text_uthmani":"عَـٰمِلُونَ","transliteration":"ʿāmilūna","translation_bn":"কাজ করে যাচ্ছি\"","root":"عمل","lemma":"عَٰمِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4670,"position":18,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū qulūbunā fī akinnatin mimmā tadʿūnā ilayhi wafī ādhāninā waqrun wamin bayninā wabaynika ḥijābun fa-iʿ''mal innanā ʿāmilūna', 'তারা বলে, তুমি আমাদেরকে যার দিকে ডাক দিচ্ছ তাত্থেকে আমাদের দিল আবরণে ঢাকা আছে, আর আমাদের কানে আছে বধিরতা, আমাদের আর তোমাদের মাঝে আছে এক পর্দা (অর্থাৎ তোমার দীন প্রচারের কারণে আমাদের ও তোমাদের মাঝে বিচ্ছেদ ঘটে গেছে), কাজেই তুমি তোমার কাজ কর, আমরা আমাদের কাজ করি।', 'And they say, "Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."', 'তারা বলে, তুমি আমাদেরকে যার দিকে ডাক দিচ্ছ তাত্থেকে আমাদের দিল আবরণে ঢাকা আছে, আর আমাদের কানে আছে বধিরতা, আমাদের আর তোমাদের মাঝে আছে এক পর্দা (অর্থাৎ তোমার দীন প্রচারের কারণে আমাদের ও তোমাদের মাঝে বিচ্ছেদ ঘটে গেছে), কাজেই তুমি তোমার কাজ কর, আমরা আমাদের কাজ করি।', 'And they say, "Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041005.mp3', now()),
  (41, 6, '', '[{"id":5937,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5938,"position":2,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"\"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5939,"position":3,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5940,"position":4,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"একজন মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":5941,"position":5,"text_uthmani":"مِّثْلُكُمْ","transliteration":"mith''lukum","translation_bn":"তোমাদেরই মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5942,"position":6,"text_uthmani":"يُوحَىٰٓ","transliteration":"yūḥā","translation_bn":"ওহী করা হয়","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":5943,"position":7,"text_uthmani":"إِلَىَّ","transliteration":"ilayya","translation_bn":"আমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5944,"position":8,"text_uthmani":"أَنَّمَآ","transliteration":"annamā","translation_bn":"এই যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5945,"position":9,"text_uthmani":"إِلَـٰهُكُمْ","transliteration":"ilāhukum","translation_bn":"তোমাদের ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":5946,"position":10,"text_uthmani":"إِلَـٰهٌۭ","transliteration":"ilāhun","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":5947,"position":11,"text_uthmani":"وَٰحِدٌۭ","transliteration":"wāḥidun","translation_bn":"একই","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":5948,"position":12,"text_uthmani":"فَٱسْتَقِيمُوٓا۟","transliteration":"fa-is''taqīmū","translation_bn":"সুতরাং তোমরা দৃঢ় হয়ে থাকো","root":"قوم","lemma":"ٱسْتَقَٰمُ","grammar_bn":"শব্দ"},{"id":5949,"position":13,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁর দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5950,"position":14,"text_uthmani":"وَٱسْتَغْفِرُوهُ ۗ","transliteration":"wa-is''taghfirūhu","translation_bn":"ও তোমরা তাঁর কাছে ক্ষমা চাও\"","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5952,"position":15,"text_uthmani":"وَوَيْلٌۭ","transliteration":"wawaylun","translation_bn":"এবং দুর্ভোগ (রয়েছে)","root":"—","lemma":"وَيْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5953,"position":16,"text_uthmani":"لِّلْمُشْرِكِينَ","transliteration":"lil''mush''rikīna","translation_bn":"মুশরিকদের জন্যে","root":"شرك","lemma":"مُشْرِك","grammar_bn":"অব্যয় (Preposition)"},{"id":5954,"position":17,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul innamā anā basharun mith''lukum yūḥā ilayya annamā ilāhukum ilāhun wāḥidun fa-is''taqīmū ilayhi wa-is''taghfirūhu wawaylun lil''mush''rikīna', 'বল, আমি তোমাদের মতই একজন মানুষ। (পার্থক্য শুধু এই যে) আমার কাছে ওয়াহী করা হয় যে, তোমাদের ইলাহ কেবল এক ইলাহ; কাজেই তোমরা তাঁরই সরল সঠিক পথে চল, তাঁর কাছে ক্ষমা প্রার্থনা কর। ধ্বংস তাদের জন্য যারা আল্লাহর সাথে অন্যদেরকে শরীক গণ্য করে।', 'Say, O [Muhammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allah -', 'বল, আমি তোমাদের মতই একজন মানুষ। (পার্থক্য শুধু এই যে) আমার কাছে ওয়াহী করা হয় যে, তোমাদের ইলাহ কেবল এক ইলাহ; কাজেই তোমরা তাঁরই সরল সঠিক পথে চল, তাঁর কাছে ক্ষমা প্রার্থনা কর। ধ্বংস তাদের জন্য যারা আল্লাহর সাথে অন্যদেরকে শরীক গণ্য করে।', 'Say, O [Muhammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allah -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041006.mp3', now()),
  (41, 7, '', '[{"id":7253,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7254,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7255,"position":3,"text_uthmani":"يُؤْتُونَ","transliteration":"yu''tūna","translation_bn":"দেয়","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":7256,"position":4,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":7257,"position":5,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7258,"position":6,"text_uthmani":"بِٱلْـَٔاخِرَةِ","transliteration":"bil-ākhirati","translation_bn":"পরকালকে","root":"اخر","lemma":"ا^خِر","grammar_bn":"অব্যয় (Preposition)"},{"id":7259,"position":7,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":7260,"position":8,"text_uthmani":"كَـٰفِرُونَ","transliteration":"kāfirūna","translation_bn":"অস্বীকারকারী","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":7261,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna lā yu''tūna l-zakata wahum bil-ākhirati hum kāfirūna', 'যারা যাকাত দেয় না, আর তারা আখিরাত অমান্য করে।', 'Those who do not give zakah, and in the Hereafter they are disbelievers.', 'যারা যাকাত দেয় না, আর তারা আখিরাত অমান্য করে।', 'Those who do not give zakah, and in the Hereafter they are disbelievers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041007.mp3', now()),
  (41, 8, '', '[{"id":8532,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8533,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8534,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8535,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8536,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"নেক","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":8537,"position":6,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":8538,"position":7,"text_uthmani":"أَجْرٌ","transliteration":"ajrun","translation_bn":"পুরস্কার রয়েছে","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8539,"position":8,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"ব্যতীত","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8540,"position":9,"text_uthmani":"مَمْنُونٍۢ","transliteration":"mamnūnin","translation_bn":"শেষ হওয়া (অফুরন্ত)","root":"منن","lemma":"مَمْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":8541,"position":10,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna āmanū waʿamilū l-ṣāliḥāti lahum ajrun ghayru mamnūnin', 'যারা ঈমান আনে আর নেক কাজ করে, তাদের জন্য আছে এমন পুরস্কার যা কোন দিনও বন্ধ হবে না।', 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.', 'যারা ঈমান আনে আর নেক কাজ করে, তাদের জন্য আছে এমন পুরস্কার যা কোন দিনও বন্ধ হবে না।', 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041008.mp3', now()),
  (41, 9, '', '[{"id":9737,"position":1,"text_uthmani":"۞ قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9738,"position":2,"text_uthmani":"أَئِنَّكُمْ","transliteration":"a-innakum","translation_bn":"\"তোমরা নিশ্চিত কি","root":"—","lemma":"إِنّ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9739,"position":3,"text_uthmani":"لَتَكْفُرُونَ","transliteration":"latakfurūna","translation_bn":"অস্বীকার করছো অবশ্যই","root":"كفر","lemma":"كَفَرَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9740,"position":4,"text_uthmani":"بِٱلَّذِى","transliteration":"bi-alladhī","translation_bn":"(তাকে) যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":9741,"position":5,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9742,"position":6,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":9743,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9744,"position":8,"text_uthmani":"يَوْمَيْنِ","transliteration":"yawmayni","translation_bn":"দু''দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":9745,"position":9,"text_uthmani":"وَتَجْعَلُونَ","transliteration":"watajʿalūna","translation_bn":"অথচ তোমরা দাঁড় করাচ্ছো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9746,"position":10,"text_uthmani":"لَهُۥٓ","transliteration":"lahu","translation_bn":"তাঁর জন্যে","root":"—","lemma":"لَهُۥٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":9747,"position":11,"text_uthmani":"أَندَادًۭا ۚ","transliteration":"andādan","translation_bn":"সমকক্ষ (অন্যদেরকে)","root":"ندد","lemma":"أَندَاد","grammar_bn":"বিশেষ্য (Noun)"},{"id":9749,"position":12,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"তিনিই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":9750,"position":13,"text_uthmani":"رَبُّ","transliteration":"rabbu","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9751,"position":14,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের\"","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":9752,"position":15,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'qul a-innakum latakfurūna bi-alladhī khalaqa l-arḍa fī yawmayni watajʿalūna lahu andādan dhālika rabbu l-ʿālamīna', 'বল- তোমরা কি তাঁকে অস্বীকারই করছ যিনি যমীনকে সৃষ্টি করেছেন দু’দিনে আর তাঁর সমকক্ষ বানাচ্ছ? তিনিই তো বিশ্বজগতের রব্ব।', 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."', 'বল- তোমরা কি তাঁকে অস্বীকারই করছ যিনি যমীনকে সৃষ্টি করেছেন দু’দিনে আর তাঁর সমকক্ষ বানাচ্ছ? তিনিই তো বিশ্বজগতের রব্ব।', 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041009.mp3', now()),
  (41, 10, '', '[{"id":10870,"position":1,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং তিনি স্হাপন করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10871,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে (অর্থাৎ পৃথিবীতে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10872,"position":3,"text_uthmani":"رَوَٰسِىَ","transliteration":"rawāsiya","translation_bn":"পর্বতমালা","root":"رسو","lemma":"رَوَٰسِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":10873,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10874,"position":5,"text_uthmani":"فَوْقِهَا","transliteration":"fawqihā","translation_bn":"তার উপর","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":10875,"position":6,"text_uthmani":"وَبَـٰرَكَ","transliteration":"wabāraka","translation_bn":"এবং কল্যাণ দিয়েছেন","root":"برك","lemma":"بَٰرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10876,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10877,"position":8,"text_uthmani":"وَقَدَّرَ","transliteration":"waqaddara","translation_bn":"এবং নির্ধারণ করেছেন","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10878,"position":9,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10879,"position":10,"text_uthmani":"أَقْوَٰتَهَا","transliteration":"aqwātahā","translation_bn":"তার খাদ্য (অর্থাৎ খাদ্যসম্ভার)","root":"قوت","lemma":"أَقْوَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10880,"position":11,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10881,"position":12,"text_uthmani":"أَرْبَعَةِ","transliteration":"arbaʿati","translation_bn":"চার","root":"ربع","lemma":"أَرْبَعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10882,"position":13,"text_uthmani":"أَيَّامٍۢ","transliteration":"ayyāmin","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10883,"position":14,"text_uthmani":"سَوَآءًۭ","transliteration":"sawāan","translation_bn":"সমানভাবে","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10884,"position":15,"text_uthmani":"لِّلسَّآئِلِينَ","transliteration":"lilssāilīna","translation_bn":"প্রার্থীদের জন্যে","root":"سال","lemma":"سَا^ئِل","grammar_bn":"অব্যয় (Preposition)"},{"id":10885,"position":16,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿala fīhā rawāsiya min fawqihā wabāraka fīhā waqaddara fīhā aqwātahā fī arbaʿati ayyāmin sawāan lilssāilīna', '(যমীন সৃষ্টির পর) তার বুকে তিনি সৃদৃঢ় পর্বতমালা স্থাপন করেছেন, যমীনকে বরকতমন্ডিত করেছেন আর তাতে প্রার্থীদের প্রয়োজন মুতাবেক নির্দিষ্ট পরিমাণ খাদ্য সঞ্চিত করেছেন চার দিনে।', 'And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures''] sustenance in four days without distinction - for [the information] of those who ask.', '(যমীন সৃষ্টির পর) তার বুকে তিনি সৃদৃঢ় পর্বতমালা স্থাপন করেছেন, যমীনকে বরকতমন্ডিত করেছেন আর তাতে প্রার্থীদের প্রয়োজন মুতাবেক নির্দিষ্ট পরিমাণ খাদ্য সঞ্চিত করেছেন চার দিনে।', 'And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures''] sustenance in four days without distinction - for [the information] of those who ask.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041010.mp3', now()),
  (41, 11, '', '[{"id":12187,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12188,"position":2,"text_uthmani":"ٱسْتَوَىٰٓ","transliteration":"is''tawā","translation_bn":"মনোযোগ দিলেন","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":12189,"position":3,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12190,"position":4,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12191,"position":5,"text_uthmani":"وَهِىَ","transliteration":"wahiya","translation_bn":"তখন তা (ছিলো)","root":"—","lemma":"وَهِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":12192,"position":6,"text_uthmani":"دُخَانٌۭ","transliteration":"dukhānun","translation_bn":"ধোঁয়া","root":"دخن","lemma":"دُخَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":12193,"position":7,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"অতঃপর (আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12194,"position":8,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"তাকে","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":12195,"position":9,"text_uthmani":"وَلِلْأَرْضِ","transliteration":"walil''arḍi","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12196,"position":10,"text_uthmani":"ٱئْتِيَا","transliteration":"i''tiyā","translation_bn":"\"উভয়ে আসো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":12197,"position":11,"text_uthmani":"طَوْعًا","transliteration":"ṭawʿan","translation_bn":"ইচ্ছায়","root":"طوع","lemma":"طَوْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":12198,"position":12,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12199,"position":13,"text_uthmani":"كَرْهًۭا","transliteration":"karhan","translation_bn":"অনিচ্ছায়\"","root":"كره","lemma":"كَرْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":12200,"position":14,"text_uthmani":"قَالَتَآ","transliteration":"qālatā","translation_bn":"উভয়ে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12201,"position":15,"text_uthmani":"أَتَيْنَا","transliteration":"ataynā","translation_bn":"\"আমরা আসলাম","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":12202,"position":16,"text_uthmani":"طَآئِعِينَ","transliteration":"ṭāiʿīna","translation_bn":"স্বেচ্ছায়\"","root":"طوع","lemma":"طَا^ئِعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":12203,"position":17,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'thumma is''tawā ilā l-samāi wahiya dukhānun faqāla lahā walil''arḍi i''tiyā ṭawʿan aw karhan qālatā ataynā ṭāiʿīna', 'তারপর নজর দিয়েছেন আকাশের দিকে যখন তা ছিল ধোঁয়া (’র মত)। তখন তিনি আকাশ আর পৃথিবীকে বললেন- আমার অনুগত হও, ইচ্ছায় অথবা অনিচ্ছায়। উভয়ে বলল- আমরা স্বেচ্ছায় অনুগত হলাম।', 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."', 'তারপর নজর দিয়েছেন আকাশের দিকে যখন তা ছিল ধোঁয়া (’র মত)। তখন তিনি আকাশ আর পৃথিবীকে বললেন- আমার অনুগত হও, ইচ্ছায় অথবা অনিচ্ছায়। উভয়ে বলল- আমরা স্বেচ্ছায় অনুগত হলাম।', 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041011.mp3', now()),
  (41, 12, '', '[{"id":13543,"position":1,"text_uthmani":"فَقَضَىٰهُنَّ","transliteration":"faqaḍāhunna","translation_bn":"অতঃপর তাদেরকে পরিণত করলেন","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"শব্দ"},{"id":13544,"position":2,"text_uthmani":"سَبْعَ","transliteration":"sabʿa","translation_bn":"সাত","root":"سبع","lemma":"سَبْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":13545,"position":3,"text_uthmani":"سَمَـٰوَاتٍۢ","transliteration":"samāwātin","translation_bn":"আকাশে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":13546,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13547,"position":5,"text_uthmani":"يَوْمَيْنِ","transliteration":"yawmayni","translation_bn":"দু''দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":13548,"position":6,"text_uthmani":"وَأَوْحَىٰ","transliteration":"wa-awḥā","translation_bn":"এবং ওহী করলেন","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13549,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13550,"position":8,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13551,"position":9,"text_uthmani":"سَمَآءٍ","transliteration":"samāin","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":13552,"position":10,"text_uthmani":"أَمْرَهَا ۚ","transliteration":"amrahā","translation_bn":"তাঁর বিধিবিধান","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":13554,"position":11,"text_uthmani":"وَزَيَّنَّا","transliteration":"wazayyannā","translation_bn":"এবং আমরা সাজালাম","root":"زين","lemma":"زَيَّنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13555,"position":12,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":13556,"position":13,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"নীচের","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":13557,"position":14,"text_uthmani":"بِمَصَـٰبِيحَ","transliteration":"bimaṣābīḥa","translation_bn":"প্রদীপমালা দ্বারা","root":"صبح","lemma":"مِصْبَاح","grammar_bn":"অব্যয় (Preposition)"},{"id":13558,"position":15,"text_uthmani":"وَحِفْظًۭا ۚ","transliteration":"waḥif''ẓan","translation_bn":"এবং সংরক্ষণ (করলাম)","root":"حفظ","lemma":"حِفْظ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13560,"position":16,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":13561,"position":17,"text_uthmani":"تَقْدِيرُ","transliteration":"taqdīru","translation_bn":"ব্যবস্থাপনা","root":"قدر","lemma":"تَقْدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":13562,"position":18,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"পরাক্রমশালীর","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":13563,"position":19,"text_uthmani":"ٱلْعَلِيمِ","transliteration":"l-ʿalīmi","translation_bn":"(যিনি) সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":13564,"position":20,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'faqaḍāhunna sabʿa samāwātin fī yawmayni wa-awḥā fī kulli samāin amrahā wazayyannā l-samāa l-dun''yā bimaṣābīḥa waḥif''ẓan dhālika taqdīru l-ʿazīzi l-ʿalīmi', 'অতঃপর তিনি আকাশমন্ডলীকে সাত আকাশে বিন্যস্ত করলেন দু’দিনে আর প্রত্যেক আকাশকে তার বিধি-ব্যবস্থা ওয়াহীর মাধ্যমে প্রদান করলেন। আমি আলোকমালার সাহায্যে দুনিয়ার আকাশের শোভাবর্ধন করলাম আর সুরক্ষার (ও ব্যবস্থা করলাম)। এ হল মহা পরাক্রমশালী সর্বজ্ঞ আল্লাহর সুনির্ধারিত (ব্যবস্থাপনা)।', 'And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing.', 'অতঃপর তিনি আকাশমন্ডলীকে সাত আকাশে বিন্যস্ত করলেন দু’দিনে আর প্রত্যেক আকাশকে তার বিধি-ব্যবস্থা ওয়াহীর মাধ্যমে প্রদান করলেন। আমি আলোকমালার সাহায্যে দুনিয়ার আকাশের শোভাবর্ধন করলাম আর সুরক্ষার (ও ব্যবস্থা করলাম)। এ হল মহা পরাক্রমশালী সর্বজ্ঞ আল্লাহর সুনির্ধারিত (ব্যবস্থাপনা)।', 'And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041012.mp3', now()),
  (41, 13, '', '[{"id":14715,"position":1,"text_uthmani":"فَإِنْ","transliteration":"fa-in","translation_bn":"এখন যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":14716,"position":2,"text_uthmani":"أَعْرَضُوا۟","transliteration":"aʿraḍū","translation_bn":"তারা মুখ ফিরায়","root":"عرض","lemma":"أَعْرَضَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14717,"position":3,"text_uthmani":"فَقُلْ","transliteration":"faqul","translation_bn":"তবে বলো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":14718,"position":4,"text_uthmani":"أَنذَرْتُكُمْ","transliteration":"andhartukum","translation_bn":"\"তোমাদেরকে আমি সতর্ক করছি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14719,"position":5,"text_uthmani":"صَـٰعِقَةًۭ","transliteration":"ṣāʿiqatan","translation_bn":"বেহুশকারী শাস্তির","root":"صعق","lemma":"صَاعِقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14720,"position":6,"text_uthmani":"مِّثْلَ","transliteration":"mith''la","translation_bn":"মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":14721,"position":7,"text_uthmani":"صَـٰعِقَةِ","transliteration":"ṣāʿiqati","translation_bn":"বেহুশকারী শাস্তি (এসেছিলো)","root":"صعق","lemma":"صَاعِقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14722,"position":8,"text_uthmani":"عَادٍۢ","transliteration":"ʿādin","translation_bn":"আ''দের","root":"عود","lemma":"عَاد2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14723,"position":9,"text_uthmani":"وَثَمُودَ","transliteration":"wathamūda","translation_bn":"ও সামূদের (উপর)\"","root":"—","lemma":"ثَمُود","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14724,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'fa-in aʿraḍū faqul andhartukum ṣāʿiqatan mith''la ṣāʿiqati ʿādin wathamūda', 'এরপরও তারা যদি মুখ ফিরিয়ে নেয় তাহলে বল- আমি তোমাদেরকে অকস্মাৎ শাস্তির ভয় দেখাচ্ছি- ‘আদ ও সামূদের (উপর নেমে আসা) অকস্মাৎ-শাস্তির মত।', 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] ''Aad and Thamud.', 'এরপরও তারা যদি মুখ ফিরিয়ে নেয় তাহলে বল- আমি তোমাদেরকে অকস্মাৎ শাস্তির ভয় দেখাচ্ছি- ‘আদ ও সামূদের (উপর নেমে আসা) অকস্মাৎ-শাস্তির মত।', 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] ''Aad and Thamud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041013.mp3', now()),
  (41, 14, '', '[{"id":15783,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":15784,"position":2,"text_uthmani":"جَآءَتْهُمُ","transliteration":"jāathumu","translation_bn":"তাদের কাছে এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15785,"position":3,"text_uthmani":"ٱلرُّسُلُ","transliteration":"l-rusulu","translation_bn":"রাসূলগণ","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":15786,"position":4,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15787,"position":5,"text_uthmani":"بَيْنِ","transliteration":"bayni","translation_bn":"থেকে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":15788,"position":6,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"সামনে তাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":15789,"position":7,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"ও থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15790,"position":8,"text_uthmani":"خَلْفِهِمْ","transliteration":"khalfihim","translation_bn":"তাদের পিছন","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":15791,"position":9,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"(এই বলে) যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15792,"position":10,"text_uthmani":"تَعْبُدُوٓا۟","transliteration":"taʿbudū","translation_bn":"তোমরা ইবাদত করো","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15793,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":15794,"position":12,"text_uthmani":"ٱللَّهَ ۖ","transliteration":"l-laha","translation_bn":"আল্লাহকে\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15796,"position":13,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15797,"position":14,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"\"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":15798,"position":15,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছে করতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15799,"position":16,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15800,"position":17,"text_uthmani":"لَأَنزَلَ","transliteration":"la-anzala","translation_bn":"অবশ্যই পাঠাতেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15801,"position":18,"text_uthmani":"مَلَـٰٓئِكَةًۭ","transliteration":"malāikatan","translation_bn":"ফেরেশতাদেরকে","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":15802,"position":19,"text_uthmani":"فَإِنَّا","transliteration":"fa-innā","translation_bn":"সুতরাং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":15803,"position":20,"text_uthmani":"بِمَآ","transliteration":"bimā","translation_bn":"দিয়ে ঐ বিষয় যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15804,"position":21,"text_uthmani":"أُرْسِلْتُم","transliteration":"ur''sil''tum","translation_bn":"তোমাদেরকে পাঠানো হয়েছে","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15805,"position":22,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"প্রতি তার","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":15806,"position":23,"text_uthmani":"كَـٰفِرُونَ","transliteration":"kāfirūna","translation_bn":"তোমরা অস্বীকারকারী\"","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":15807,"position":24,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'idh jāathumu l-rusulu min bayni aydīhim wamin khalfihim allā taʿbudū illā l-laha qālū law shāa rabbunā la-anzala malāikatan fa-innā bimā ur''sil''tum bihi kāfirūna', 'তাদের কাছে যখন তাদের অগ্রে ও পশ্চাতে (একের পর এক) রসূলগণ এসেছিল (আর বলেছিল)- তোমরা আল্লাহ ছাড়া কারো ‘ইবাদাত করো না। (জবাবে) তারা বলেছিল- আমাদের প্রতিপালক ইচ্ছে করলে তো অবশ্যই ফেরেশতা নাযিল করতেন। কাজেই তোমাদেরকে যা দিয়ে পাঠানো হয়েছে আমরা তা অমান্য করছি।', '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allah." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."', 'তাদের কাছে যখন তাদের অগ্রে ও পশ্চাতে (একের পর এক) রসূলগণ এসেছিল (আর বলেছিল)- তোমরা আল্লাহ ছাড়া কারো ‘ইবাদাত করো না। (জবাবে) তারা বলেছিল- আমাদের প্রতিপালক ইচ্ছে করলে তো অবশ্যই ফেরেশতা নাযিল করতেন। কাজেই তোমাদেরকে যা দিয়ে পাঠানো হয়েছে আমরা তা অমান্য করছি।', '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allah." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041014.mp3', now()),
  (41, 15, '', '[{"id":16872,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"আর অবস্থা (ছিলো)","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":16873,"position":2,"text_uthmani":"عَادٌۭ","transliteration":"ʿādun","translation_bn":"আ''দের (এমন যে)","root":"عود","lemma":"عَاد2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16874,"position":3,"text_uthmani":"فَٱسْتَكْبَرُوا۟","transliteration":"fa-is''takbarū","translation_bn":"পরে তারা অহংকার করলো","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"শব্দ"},{"id":16875,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16876,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":16877,"position":6,"text_uthmani":"بِغَيْرِ","transliteration":"bighayri","translation_bn":"ব্যতীত","root":"غير","lemma":"غَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":16878,"position":7,"text_uthmani":"ٱلْحَقِّ","transliteration":"l-ḥaqi","translation_bn":"কোন অধিকার","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":16879,"position":8,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16880,"position":9,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"\"(আর) কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16881,"position":10,"text_uthmani":"أَشَدُّ","transliteration":"ashaddu","translation_bn":"অধিক শক্তিশালী","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16882,"position":11,"text_uthmani":"مِنَّا","transliteration":"minnā","translation_bn":"আমাদের চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16883,"position":12,"text_uthmani":"قُوَّةً ۖ","transliteration":"quwwatan","translation_bn":"শক্তিতে\"","root":"قوي","lemma":"قُوَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16885,"position":13,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"দেখে নি কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16886,"position":14,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা (ভেবে)","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":16887,"position":15,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16888,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16889,"position":17,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16890,"position":18,"text_uthmani":"خَلَقَهُمْ","transliteration":"khalaqahum","translation_bn":"তাদের সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16891,"position":19,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":16892,"position":20,"text_uthmani":"أَشَدُّ","transliteration":"ashaddu","translation_bn":"অধিক শক্তিশালী","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16893,"position":21,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16894,"position":22,"text_uthmani":"قُوَّةًۭ ۖ","transliteration":"quwwatan","translation_bn":"শক্তিতে","root":"قوي","lemma":"قُوَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16896,"position":23,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"এবং তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16897,"position":24,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"আমাদের নিদর্শনগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":16898,"position":25,"text_uthmani":"يَجْحَدُونَ","transliteration":"yajḥadūna","translation_bn":"অস্বীকার করতো","root":"جحد","lemma":"جَحَدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16899,"position":26,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā ʿādun fa-is''takbarū fī l-arḍi bighayri l-ḥaqi waqālū man ashaddu minnā quwwatan awalam yaraw anna l-laha alladhī khalaqahum huwa ashaddu min''hum quwwatan wakānū biāyātinā yajḥadūna', 'আর ‘আদ-এর অবস্থা ছিল এই যে, দুনিয়াতে তারা না-হক অহংকার করেছিল, আর বলেছিল- আমাদের চেয়ে বেশি শক্তিশালী আর কে আছে? তারা কি চিন্তা করে দেখেনি যে, আল্লাহ- যিনি তাদেরকে সৃষ্টি করেছেন- শক্তিতে তাদের চেয়ে প্রবল? কিন্তু তারা আমার আয়াতগুলো অস্বীকার করতেই থাকল।', 'As for ''Aad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs.', 'আর ‘আদ-এর অবস্থা ছিল এই যে, দুনিয়াতে তারা না-হক অহংকার করেছিল, আর বলেছিল- আমাদের চেয়ে বেশি শক্তিশালী আর কে আছে? তারা কি চিন্তা করে দেখেনি যে, আল্লাহ- যিনি তাদেরকে সৃষ্টি করেছেন- শক্তিতে তাদের চেয়ে প্রবল? কিন্তু তারা আমার আয়াতগুলো অস্বীকার করতেই থাকল।', 'As for ''Aad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041015.mp3', now()),
  (41, 16, '', '[{"id":18037,"position":1,"text_uthmani":"فَأَرْسَلْنَا","transliteration":"fa-arsalnā","translation_bn":"আমরা তাই পাঠালাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"শব্দ"},{"id":18038,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18039,"position":3,"text_uthmani":"رِيحًۭا","transliteration":"rīḥan","translation_bn":"বাতাস","root":"روح","lemma":"رِيح","grammar_bn":"বিশেষ্য (Noun)"},{"id":18040,"position":4,"text_uthmani":"صَرْصَرًۭا","transliteration":"ṣarṣaran","translation_bn":"ঝড়ো","root":"صرصر","lemma":"صَرْصَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":18041,"position":5,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18042,"position":6,"text_uthmani":"أَيَّامٍۢ","transliteration":"ayyāmin","translation_bn":"(কয়েক) দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18043,"position":7,"text_uthmani":"نَّحِسَاتٍۢ","transliteration":"naḥisātin","translation_bn":"দুর্ভোগের","root":"نحس","lemma":"نَّحِسَات","grammar_bn":"বিশেষণ (Adjective)"},{"id":18044,"position":8,"text_uthmani":"لِّنُذِيقَهُمْ","transliteration":"linudhīqahum","translation_bn":"তাদেরকে আমরা ভোগ করাই যেন","root":"ذوق","lemma":"أَذَاقَ","grammar_bn":"শব্দ"},{"id":18045,"position":9,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":18046,"position":10,"text_uthmani":"ٱلْخِزْىِ","transliteration":"l-khiz''yi","translation_bn":"লাঞ্ছনার","root":"خزي","lemma":"خِزْى","grammar_bn":"শব্দ"},{"id":18047,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18048,"position":12,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনে","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":18049,"position":13,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":18051,"position":14,"text_uthmani":"وَلَعَذَابُ","transliteration":"walaʿadhābu","translation_bn":"এবং অবশ্যই শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18052,"position":15,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":18053,"position":16,"text_uthmani":"أَخْزَىٰ ۖ","transliteration":"akhzā","translation_bn":"অধিক অপমানকর","root":"خزي","lemma":"أَخْزَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18055,"position":17,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তাদের","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18056,"position":18,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":18057,"position":19,"text_uthmani":"يُنصَرُونَ","transliteration":"yunṣarūna","translation_bn":"সাহায্য করা হবে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18058,"position":20,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-arsalnā ʿalayhim rīḥan ṣarṣaran fī ayyāmin naḥisātin linudhīqahum ʿadhāba l-khiz''yi fī l-ḥayati l-dun''yā walaʿadhābu l-ākhirati akhzā wahum lā yunṣarūna', 'অতঃপর আমি অশুভ দিনগুলোতে তাদের বিরুদ্ধে ঝাঞ্ঝা বায়ু পাঠালাম যাতে তারা দুনিয়ার জীবনে অপমানজনক শাস্তি আস্বাদন করে। আখিরাতের শাস্তি অবশ্যই অধিক লাঞ্ছনাদায়ক আর তারা সাহায্যপ্রাপ্তও হবে না।', 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.', 'অতঃপর আমি অশুভ দিনগুলোতে তাদের বিরুদ্ধে ঝাঞ্ঝা বায়ু পাঠালাম যাতে তারা দুনিয়ার জীবনে অপমানজনক শাস্তি আস্বাদন করে। আখিরাতের শাস্তি অবশ্যই অধিক লাঞ্ছনাদায়ক আর তারা সাহায্যপ্রাপ্তও হবে না।', 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041016.mp3', now()),
  (41, 17, '', '[{"id":19040,"position":1,"text_uthmani":"وَأَمَّا","transliteration":"wa-ammā","translation_bn":"আর অবস্থা (ছিলো)","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19041,"position":2,"text_uthmani":"ثَمُودُ","transliteration":"thamūdu","translation_bn":"সামূদের (এমন যে)","root":"—","lemma":"ثَمُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19042,"position":3,"text_uthmani":"فَهَدَيْنَـٰهُمْ","transliteration":"fahadaynāhum","translation_bn":"তাদেরকে আমরা অতঃপর পথ নির্দেশ করেছিলাম","root":"هدي","lemma":"هَدَى","grammar_bn":"শব্দ"},{"id":19043,"position":4,"text_uthmani":"فَٱسْتَحَبُّوا۟","transliteration":"fa-is''taḥabbū","translation_bn":"তারা কিন্তু পছন্দ করেছিলো","root":"حبب","lemma":"ٱسْتَحَبُّ","grammar_bn":"শব্দ"},{"id":19044,"position":5,"text_uthmani":"ٱلْعَمَىٰ","transliteration":"l-ʿamā","translation_bn":"অন্ধতা","root":"عمي","lemma":"عَمًى","grammar_bn":"শব্দ"},{"id":19045,"position":6,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"পরিবর্তে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19046,"position":7,"text_uthmani":"ٱلْهُدَىٰ","transliteration":"l-hudā","translation_bn":"সৎপথের","root":"هدي","lemma":"هُدًى","grammar_bn":"শব্দ"},{"id":19047,"position":8,"text_uthmani":"فَأَخَذَتْهُمْ","transliteration":"fa-akhadhathum","translation_bn":"তখন তাদেরকে পাকড়াও  করলো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":19048,"position":9,"text_uthmani":"صَـٰعِقَةُ","transliteration":"ṣāʿiqatu","translation_bn":"বেহুশকারী","root":"صعق","lemma":"صَاعِقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19049,"position":10,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":19050,"position":11,"text_uthmani":"ٱلْهُونِ","transliteration":"l-hūni","translation_bn":"অপমানকর","root":"هون","lemma":"هُون","grammar_bn":"শব্দ"},{"id":19051,"position":12,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19052,"position":13,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19053,"position":14,"text_uthmani":"يَكْسِبُونَ","transliteration":"yaksibūna","translation_bn":"কামাই করেছিলো","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19054,"position":15,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā thamūdu fahadaynāhum fa-is''taḥabbū l-ʿamā ʿalā l-hudā fa-akhadhathum ṣāʿiqatu l-ʿadhābi l-hūni bimā kānū yaksibūna', 'আর সামূদের অবস্থা এই যে, আমি তাদেরকে সঠিক পথে চলার নির্দেশ দিয়েছিলাম। কিন্তু তারা সঠিক পথে চলার পরিবর্তে অন্ধ হয়ে থাকাকেই পছন্দ করে ছিল। তখন তাদের কৃতকর্মের কারণে অপমানজনক শাস্তির বজ্রাঘাত তাদেরকে পাকড়াও করল।', 'And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.', 'আর সামূদের অবস্থা এই যে, আমি তাদেরকে সঠিক পথে চলার নির্দেশ দিয়েছিলাম। কিন্তু তারা সঠিক পথে চলার পরিবর্তে অন্ধ হয়ে থাকাকেই পছন্দ করে ছিল। তখন তাদের কৃতকর্মের কারণে অপমানজনক শাস্তির বজ্রাঘাত তাদেরকে পাকড়াও করল।', 'And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041017.mp3', now()),
  (41, 18, '', '[{"id":20138,"position":1,"text_uthmani":"وَنَجَّيْنَا","transliteration":"wanajjaynā","translation_bn":"এবং আমরা উদ্ধার করেছিলাম","root":"نجو","lemma":"نَجَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20139,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20140,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছিলো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20141,"position":4,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"ও","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20142,"position":5,"text_uthmani":"يَتَّقُونَ","transliteration":"yattaqūna","translation_bn":"(গুমরাহী হ''তে) ভয় করেছিলো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20143,"position":6,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wanajjaynā alladhīna āmanū wakānū yattaqūna', 'আর আমি তাদেরকে বাঁচিয়ে দিলাম যারা ঈমান এনেছিল আর (আল্লাহকে) ভয় করে চলত।', 'And We saved those who believed and used to fear Allah.', 'আর আমি তাদেরকে বাঁচিয়ে দিলাম যারা ঈমান এনেছিল আর (আল্লাহকে) ভয় করে চলত।', 'And We saved those who believed and used to fear Allah.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041018.mp3', now()),
  (41, 19, '', '[{"id":21247,"position":1,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং (স্মরণ করো) যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21248,"position":2,"text_uthmani":"يُحْشَرُ","transliteration":"yuḥ''sharu","translation_bn":"সমবেত করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21249,"position":3,"text_uthmani":"أَعْدَآءُ","transliteration":"aʿdāu","translation_bn":"শত্রুদের","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21250,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21251,"position":5,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21252,"position":6,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"জাহান্নামের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":21253,"position":7,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"অতঃপর তাদেরকে","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":21254,"position":8,"text_uthmani":"يُوزَعُونَ","transliteration":"yūzaʿūna","translation_bn":"নানা দলে ভাগ করা হবে","root":"وزع","lemma":"يُوزَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21255,"position":9,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wayawma yuḥ''sharu aʿdāu l-lahi ilā l-nāri fahum yūzaʿūna', 'যে দিন আল্লাহর দুশমনদেরকে জাহান্নামের দিকে সমবেত করা হবে, তাদেরকে বিভিন্ন দলে বিন্যস্ত করা হবে।', 'And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,', 'যে দিন আল্লাহর দুশমনদেরকে জাহান্নামের দিকে সমবেত করা হবে, তাদেরকে বিভিন্ন দলে বিন্যস্ত করা হবে।', 'And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041019.mp3', now()),
  (41, 20, '', '[{"id":22325,"position":1,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"অবশেষে","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":22326,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":22327,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22328,"position":4,"text_uthmani":"جَآءُوهَا","transliteration":"jāūhā","translation_bn":"সেখানে তারা আসবে (সবাই)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22329,"position":5,"text_uthmani":"شَهِدَ","transliteration":"shahida","translation_bn":"সাক্ষ্য দিবে","root":"شهد","lemma":"شَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22330,"position":6,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22331,"position":7,"text_uthmani":"سَمْعُهُمْ","transliteration":"samʿuhum","translation_bn":"তাদের কান","root":"سمع","lemma":"سَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":22332,"position":8,"text_uthmani":"وَأَبْصَـٰرُهُمْ","transliteration":"wa-abṣāruhum","translation_bn":"ও তাদের চক্ষু","root":"بصر","lemma":"بَصَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22333,"position":9,"text_uthmani":"وَجُلُودُهُم","transliteration":"wajulūduhum","translation_bn":"ও তাদের ত্বক","root":"جلد","lemma":"جُلُود","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22334,"position":10,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22335,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22336,"position":12,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"কাজ করেছিলো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22337,"position":13,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā idhā mā jāūhā shahida ʿalayhim samʿuhum wa-abṣāruhum wajulūduhum bimā kānū yaʿmalūna', 'শেষ পর্যন্ত যখন তারা জাহান্নামের নিকটে পৌঁছবে, তখন তারা যা করত সে সম্পর্কে তাদের কান, তাদের চোখ আর তাদের চামড়া তাদের বিরুদ্ধে সাক্ষ্য দেবে।', 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.', 'শেষ পর্যন্ত যখন তারা জাহান্নামের নিকটে পৌঁছবে, তখন তারা যা করত সে সম্পর্কে তাদের কান, তাদের চোখ আর তাদের চামড়া তাদের বিরুদ্ধে সাক্ষ্য দেবে।', 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041020.mp3', now()),
  (41, 21, '', '[{"id":23443,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23444,"position":2,"text_uthmani":"لِجُلُودِهِمْ","transliteration":"lijulūdihim","translation_bn":"তাদের ত্বকগুলোকে","root":"جلد","lemma":"جُلُود","grammar_bn":"অব্যয় (Preposition)"},{"id":23445,"position":3,"text_uthmani":"لِمَ","transliteration":"lima","translation_bn":"\"কেন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23446,"position":4,"text_uthmani":"شَهِدتُّمْ","transliteration":"shahidttum","translation_bn":"তোমরা সাক্ষ্য দিয়েছো","root":"شهد","lemma":"شَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23447,"position":5,"text_uthmani":"عَلَيْنَا ۖ","transliteration":"ʿalaynā","translation_bn":"আমাদের বিরুদ্ধে\"","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23449,"position":6,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23450,"position":7,"text_uthmani":"أَنطَقَنَا","transliteration":"anṭaqanā","translation_bn":"\"আমাদের বাকশক্তি দিয়েছেন","root":"نطق","lemma":"أَنطَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23451,"position":8,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"\"(সেই) আল্লাহ-ই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23452,"position":9,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23453,"position":10,"text_uthmani":"أَنطَقَ","transliteration":"anṭaqa","translation_bn":"বাকশক্তি দিয়েছেন","root":"نطق","lemma":"أَنطَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23454,"position":11,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23455,"position":12,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুকে","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23456,"position":13,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23457,"position":14,"text_uthmani":"خَلَقَكُمْ","transliteration":"khalaqakum","translation_bn":"তোমাদেরকে সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23458,"position":15,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23459,"position":16,"text_uthmani":"مَرَّةٍۢ","transliteration":"marratin","translation_bn":"বার","root":"مرر","lemma":"مَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23460,"position":17,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23461,"position":18,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমাদের ফিরিয়ে নেয়া হবে\"","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23462,"position":19,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū lijulūdihim lima shahidttum ʿalaynā qālū anṭaqanā l-lahu alladhī anṭaqa kulla shayin wahuwa khalaqakum awwala marratin wa-ilayhi tur''jaʿūna', 'তারা তাদের চামড়াকে বলবে- আমাদের বিরুদ্ধে কেন সাক্ষ্য দিচ্ছ? তারা উত্তর দিবে- আল্লাহ আমাদেরকে কথা বলার শক্তি দিয়েছেন, যিনি সব কিছুকেই (আজ) কথা বলার শক্তি দিয়েছেন। তিনিই প্রথমবার তোমাদেরকে সৃষ্টি করেছেন, আর তাঁর কাছেই তোমাদেরকে ফিরিয়ে নেয়া হবে।', 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned.', 'তারা তাদের চামড়াকে বলবে- আমাদের বিরুদ্ধে কেন সাক্ষ্য দিচ্ছ? তারা উত্তর দিবে- আল্লাহ আমাদেরকে কথা বলার শক্তি দিয়েছেন, যিনি সব কিছুকেই (আজ) কথা বলার শক্তি দিয়েছেন। তিনিই প্রথমবার তোমাদেরকে সৃষ্টি করেছেন, আর তাঁর কাছেই তোমাদেরকে ফিরিয়ে নেয়া হবে।', 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041021.mp3', now()),
  (41, 22, '', '[{"id":24428,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24429,"position":2,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24430,"position":3,"text_uthmani":"تَسْتَتِرُونَ","transliteration":"tastatirūna","translation_bn":"লুকাতে (তখন জানতেন)","root":"ستر","lemma":"تَسْتَتِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24431,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":24432,"position":5,"text_uthmani":"يَشْهَدَ","transliteration":"yashhada","translation_bn":"সাক্ষ্য দিবে","root":"شهد","lemma":"شَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24433,"position":6,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24434,"position":7,"text_uthmani":"سَمْعُكُمْ","transliteration":"samʿukum","translation_bn":"তোমাদের কান","root":"سمع","lemma":"سَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":24435,"position":8,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"এবং না (জানতে)","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24436,"position":9,"text_uthmani":"أَبْصَـٰرُكُمْ","transliteration":"abṣārukum","translation_bn":"তোমাদের চোখগুলো (সাক্ষ্য দিবে)","root":"بصر","lemma":"بَصَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24437,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না (জানতে)","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24438,"position":11,"text_uthmani":"جُلُودُكُمْ","transliteration":"julūdukum","translation_bn":"তোমাদের ত্বকগুলো (সাক্ষ্য দিবে)","root":"جلد","lemma":"جُلُود","grammar_bn":"বিশেষ্য (Noun)"},{"id":24439,"position":12,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24440,"position":13,"text_uthmani":"ظَنَنتُمْ","transliteration":"ẓanantum","translation_bn":"তোমরা মনে করতে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24441,"position":14,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24442,"position":15,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24443,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24444,"position":17,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন কিছুই","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24445,"position":18,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অনেক","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":24446,"position":19,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"ঐ বিষয়কে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24447,"position":20,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করতে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24448,"position":21,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamā kuntum tastatirūna an yashhada ʿalaykum samʿukum walā abṣārukum walā julūdukum walākin ẓanantum anna l-laha lā yaʿlamu kathīran mimmā taʿmalūna', '(দুনিয়ায় নিজেদের শরীরের অংশগুলোকে তোমরা) এই ভেবে গোপন করতে না যে, না তোমাদের কান, না তোমাদের চোখ আর না তোমাদের চামড়া তোমাদের বিরুদ্ধে সাক্ষ্য দেবে। বরং তোমরা মনে করতে যে, তোমরা যা কর তার অধিকাংশই আল্লাহ জানেন না।', 'And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do.', '(দুনিয়ায় নিজেদের শরীরের অংশগুলোকে তোমরা) এই ভেবে গোপন করতে না যে, না তোমাদের কান, না তোমাদের চোখ আর না তোমাদের চামড়া তোমাদের বিরুদ্ধে সাক্ষ্য দেবে। বরং তোমরা মনে করতে যে, তোমরা যা কর তার অধিকাংশই আল্লাহ জানেন না।', 'And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041022.mp3', now()),
  (41, 23, '', '[{"id":25506,"position":1,"text_uthmani":"وَذَٰلِكُمْ","transliteration":"wadhālikum","translation_bn":"এবং সেটা (ছিলো)","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25507,"position":2,"text_uthmani":"ظَنُّكُمُ","transliteration":"ẓannukumu","translation_bn":"তোমাদের ধারণা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25508,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25509,"position":4,"text_uthmani":"ظَنَنتُم","transliteration":"ẓanantum","translation_bn":"তোমরা ধারণা করেছিলে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25510,"position":5,"text_uthmani":"بِرَبِّكُمْ","transliteration":"birabbikum","translation_bn":"সম্পর্কে রব তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":25511,"position":6,"text_uthmani":"أَرْدَىٰكُمْ","transliteration":"ardākum","translation_bn":"(এটাই) তোমাদেরকে ধ্বংস করেছে","root":"ردي","lemma":"أَرْدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25512,"position":7,"text_uthmani":"فَأَصْبَحْتُم","transliteration":"fa-aṣbaḥtum","translation_bn":"এখন তোমরা হয়েছো","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25513,"position":8,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25514,"position":9,"text_uthmani":"ٱلْخَـٰسِرِينَ","transliteration":"l-khāsirīna","translation_bn":"ক্ষতিগ্রস্তদের","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"শব্দ"},{"id":25515,"position":10,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'wadhālikum ẓannukumu alladhī ẓanantum birabbikum ardākum fa-aṣbaḥtum mina l-khāsirīna', 'তোমাদের এই (ভুল) ধারণাই- যা তোমরা তোমাদের প্রতিপালক সম্পর্কে পোষণ করতে- তোমাদেরকে ধ্বংস করেছে, ফলে তোমরা ক্ষতিগ্রস্তদের দলে শামিল হয়ে গেছ।', 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."', 'তোমাদের এই (ভুল) ধারণাই- যা তোমরা তোমাদের প্রতিপালক সম্পর্কে পোষণ করতে- তোমাদেরকে ধ্বংস করেছে, ফলে তোমরা ক্ষতিগ্রস্তদের দলে শামিল হয়ে গেছ।', 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041023.mp3', now()),
  (41, 24, '', '[{"id":26576,"position":1,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"সুতরাং যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":26577,"position":2,"text_uthmani":"يَصْبِرُوا۟","transliteration":"yaṣbirū","translation_bn":"তারা ধৈর্য্য ধরে (আর নাই ধরে)","root":"صبر","lemma":"صَبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26578,"position":3,"text_uthmani":"فَٱلنَّارُ","transliteration":"fal-nāru","translation_bn":"জাহান্নাম তবুও","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":26579,"position":4,"text_uthmani":"مَثْوًۭى","transliteration":"mathwan","translation_bn":"আবাস","root":"ثوي","lemma":"مَثْوًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":26580,"position":5,"text_uthmani":"لَّهُمْ ۖ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَّهُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":26582,"position":6,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26583,"position":7,"text_uthmani":"يَسْتَعْتِبُوا۟","transliteration":"yastaʿtibū","translation_bn":"তারা অনুগ্রহ করতে চায়ও","root":"عتب","lemma":"يَسْتَعْتِبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26584,"position":8,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"তবুও না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":26585,"position":9,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা (হবে)","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26586,"position":10,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26587,"position":11,"text_uthmani":"ٱلْمُعْتَبِينَ","transliteration":"l-muʿ''tabīna","translation_bn":"অনুগ্রহ প্রাপ্তদের","root":"عتب","lemma":"مُعْتَبِين","grammar_bn":"শব্দ"},{"id":26588,"position":12,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-in yaṣbirū fal-nāru mathwan lahum wa-in yastaʿtibū famā hum mina l-muʿ''tabīna', 'এখন যদি তারা ধৈর্য ধারণ করে তবুও জাহান্নামই হবে তাদের আবাস, আর যদি তারা ক্ষমা প্রার্থনা করে তবুও তারা ক্ষমাপ্রাপ্ত হবে না।', 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease.', 'এখন যদি তারা ধৈর্য ধারণ করে তবুও জাহান্নামই হবে তাদের আবাস, আর যদি তারা ক্ষমা প্রার্থনা করে তবুও তারা ক্ষমাপ্রাপ্ত হবে না।', 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/041024.mp3', now()),
  (41, 25, '', '[{"id":27586,"position":1,"text_uthmani":"۞ وَقَيَّضْنَا","transliteration":"waqayyaḍnā","translation_bn":"এবং আমরা নির্ধারণ করেছি","root":"قيض","lemma":"قَيَّضْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27587,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":27588,"position":3,"text_uthmani":"قُرَنَآءَ","transliteration":"quranāa","translation_bn":"(পথভ্রষ্ট) সঙ্গীদেরকে","root":"قرن","lemma":"قَرِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":27589,"position":4,"text_uthmani":"فَزَيَّنُوا۟","transliteration":"fazayyanū","translation_bn":"আর তারা শোভন করে দেখায়","root":"زين","lemma":"زَيَّنَ","grammar_bn":"শব্দ"},{"id":27590,"position":5,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":27591,"position":6,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা কিছু (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27592,"position":7,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"সামনে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":27593,"position":8,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"তাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":27594,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু আছে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27595,"position":10,"text_uthmani":"خَلْفَهُمْ","transliteration":"khalfahum","translation_bn":"তাদের পিছনে","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":27596,"position":11,"text_uthmani":"وَحَقَّ","transliteration":"waḥaqqa","translation_bn":"এবং বাস্তব হলো","root":"حقق","lemma":"حَقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27597,"position":12,"text_ut