  (42, 3, '', '[{"id":2048,"position":1,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":2049,"position":2,"text_uthmani":"يُوحِىٓ","transliteration":"yūḥī","translation_bn":"ওহী পাঠান (আল্লাহ)","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":2050,"position":3,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2051,"position":4,"text_uthmani":"وَإِلَى","transliteration":"wa-ilā","translation_bn":"এবং প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2052,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2053,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2054,"position":7,"text_uthmani":"قَبْلِكَ","transliteration":"qablika","translation_bn":"তোমার পূর্বে (নাবী-রাসূল ছিলো)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2055,"position":8,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2056,"position":9,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":2057,"position":10,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":2058,"position":11,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'kadhālika yūḥī ilayka wa-ilā alladhīna min qablika l-lahu l-ʿazīzu l-ḥakīmu', 'এভাবেই মহাপরাক্রমশালী মহাজ্ঞানী আল্লাহ তোমার প্রতি এবং তোমার পূর্বে যারা ছিল তাদের প্রতি ওয়াহী নাযিল করেন।', 'Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise.', 'এভাবেই মহাপরাক্রমশালী মহাজ্ঞানী আল্লাহ তোমার প্রতি এবং তোমার পূর্বে যারা ছিল তাদের প্রতি ওয়াহী নাযিল করেন।', 'Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042003.mp3', now()),
  (42, 4, '', '[{"id":3320,"position":1,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাঁরই","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":3321,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3322,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3323,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3324,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3325,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3326,"position":7,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":3328,"position":8,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3329,"position":9,"text_uthmani":"ٱلْعَلِىُّ","transliteration":"l-ʿaliyu","translation_bn":"সমুন্নত","root":"علو","lemma":"عَلِيّ","grammar_bn":"শব্দ"},{"id":3330,"position":10,"text_uthmani":"ٱلْعَظِيمُ","transliteration":"l-ʿaẓīmu","translation_bn":"সুমহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":3331,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'lahu mā fī l-samāwāti wamā fī l-arḍi wahuwa l-ʿaliyu l-ʿaẓīmu', 'আকাশ ও যমীনে যা কিছু আছে সবই তাঁর, তিনি সর্বোচ্চ, মহান।', 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.', 'আকাশ ও যমীনে যা কিছু আছে সবই তাঁর, তিনি সর্বোচ্চ, মহান।', 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042004.mp3', now()),
  (42, 5, '', '[{"id":4676,"position":1,"text_uthmani":"تَكَادُ","transliteration":"takādu","translation_bn":"(তাঁর সাথে শরিক করায়) উপক্রম হয়","root":"كود","lemma":"كَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4677,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتُ","transliteration":"l-samāwātu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":4678,"position":3,"text_uthmani":"يَتَفَطَّرْنَ","transliteration":"yatafaṭṭarna","translation_bn":"ভেঙে পড়ার","root":"فطر","lemma":"فَطَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4679,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4680,"position":5,"text_uthmani":"فَوْقِهِنَّ ۚ","transliteration":"fawqihinna","translation_bn":"তাদের উপর","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":4682,"position":6,"text_uthmani":"وَٱلْمَلَـٰٓئِكَةُ","transliteration":"wal-malāikatu","translation_bn":"এবং ফেরেশতারা","root":"ملك","lemma":"مَلَك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4683,"position":7,"text_uthmani":"يُسَبِّحُونَ","transliteration":"yusabbiḥūna","translation_bn":"পবিত্রতা ঘোষণা করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4684,"position":8,"text_uthmani":"بِحَمْدِ","transliteration":"biḥamdi","translation_bn":"প্রশংসাসহ","root":"حمد","lemma":"حَمْد","grammar_bn":"অব্যয় (Preposition)"},{"id":4685,"position":9,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4686,"position":10,"text_uthmani":"وَيَسْتَغْفِرُونَ","transliteration":"wayastaghfirūna","translation_bn":"এবং ক্ষমা প্রার্থনা করে","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4687,"position":11,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4688,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4689,"position":13,"text_uthmani":"ٱلْأَرْضِ ۗ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":4691,"position":14,"text_uthmani":"أَلَآ","transliteration":"alā","translation_bn":"জেনে রাখো","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":4692,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4693,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4694,"position":17,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4695,"position":18,"text_uthmani":"ٱلْغَفُورُ","transliteration":"l-ghafūru","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"শব্দ"},{"id":4696,"position":19,"text_uthmani":"ٱلرَّحِيمُ","transliteration":"l-raḥīmu","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":4697,"position":20,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'takādu l-samāwātu yatafaṭṭarna min fawqihinna wal-malāikatu yusabbiḥūna biḥamdi rabbihim wayastaghfirūna liman fī l-arḍi alā inna l-laha huwa l-ghafūru l-raḥīmu', 'আকাশ উপর থেকে ফেটে পড়ার উপক্রম হয় (সুমহান আল্লাহর প্রতি শ্রদ্ধাপূর্ণ ভয়ভীতিতে) আর ফেরেশতারা তাদের প্রতিপালকের প্রশংসা ও মহিমা ঘোষণা করে এবং যারা পৃথিবীতে আছে তাদের জন্য (আল্লাহর নিকট) ক্ষমা প্রার্থনা করে। জেনে রেখ, আল্লাহ, তিনি বড়ই ক্ষমাশীল, অতি দয়ালু।', 'The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful.', 'আকাশ উপর থেকে ফেটে পড়ার উপক্রম হয় (সুমহান আল্লাহর প্রতি শ্রদ্ধাপূর্ণ ভয়ভীতিতে) আর ফেরেশতারা তাদের প্রতিপালকের প্রশংসা ও মহিমা ঘোষণা করে এবং যারা পৃথিবীতে আছে তাদের জন্য (আল্লাহর নিকট) ক্ষমা প্রার্থনা করে। জেনে রেখ, আল্লাহ, তিনি বড়ই ক্ষমাশীল, অতি দয়ালু।', 'The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042005.mp3', now()),
  (42, 6, '', '[{"id":5955,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5956,"position":2,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5957,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5958,"position":4,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":5959,"position":5,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5960,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ-ই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5961,"position":7,"text_uthmani":"حَفِيظٌ","transliteration":"ḥafīẓun","translation_bn":"সংরক্ষক","root":"حفظ","lemma":"حَفِيظ","grammar_bn":"বিশেষণ (Adjective)"},{"id":5962,"position":8,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5963,"position":9,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং নও","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5964,"position":10,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5965,"position":11,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"তাদের উপর (নিযুক্ত হয়েছে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5966,"position":12,"text_uthmani":"بِوَكِيلٍۢ","transliteration":"biwakīlin","translation_bn":"কর্ম বিধায়ক","root":"وكل","lemma":"وَكِيل","grammar_bn":"অব্যয় (Preposition)"},{"id":5967,"position":13,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna ittakhadhū min dūnihi awliyāa l-lahu ḥafīẓun ʿalayhim wamā anta ʿalayhim biwakīlin', 'যারা আল্লাহর পরিবর্তে অন্যদেরকে অভিভাবকরূপে গ্রহণ করে, আল্লাহ তাদের প্রতি নযর রাখছেন, তাদের (কাজের) দায়-দায়িত্ব তোমার উপর নেই।', 'And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.', 'যারা আল্লাহর পরিবর্তে অন্যদেরকে অভিভাবকরূপে গ্রহণ করে, আল্লাহ তাদের প্রতি নযর রাখছেন, তাদের (কাজের) দায়-দায়িত্ব তোমার উপর নেই।', 'And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042006.mp3', now()),
  (42, 7, '', '[{"id":7262,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7263,"position":2,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ওহী করেছি","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":7264,"position":3,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7265,"position":4,"text_uthmani":"قُرْءَانًا","transliteration":"qur''ānan","translation_bn":"কুরআনকে","root":"قرا","lemma":"قُرْءَان","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7266,"position":5,"text_uthmani":"عَرَبِيًّۭا","transliteration":"ʿarabiyyan","translation_bn":"আরবী (ভাষায়)","root":"عرب","lemma":"عَرَبِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":7267,"position":6,"text_uthmani":"لِّتُنذِرَ","transliteration":"litundhira","translation_bn":"সতর্ক করো তুমি যেনো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":7268,"position":7,"text_uthmani":"أُمَّ","transliteration":"umma","translation_bn":"কেন্দ্রকে","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7269,"position":8,"text_uthmani":"ٱلْقُرَىٰ","transliteration":"l-qurā","translation_bn":"জনপদসমূহের (অর্থাৎ মাক্কাবাসীদেরকে)","root":"قري","lemma":"قَرْيَة","grammar_bn":"শব্দ"},{"id":7270,"position":9,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যারা","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7271,"position":10,"text_uthmani":"حَوْلَهَا","transliteration":"ḥawlahā","translation_bn":"তার চার পাশে (আছে)","root":"حول","lemma":"حَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7272,"position":11,"text_uthmani":"وَتُنذِرَ","transliteration":"watundhira","translation_bn":"এবং সতর্ক করো তুমি (যেনো)","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7273,"position":12,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিন (সম্পর্কে)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7274,"position":13,"text_uthmani":"ٱلْجَمْعِ","transliteration":"l-jamʿi","translation_bn":"সমবেত হওয়ার (অর্থাৎ ক্বিয়ামাতের)","root":"جمع","lemma":"جَمْع","grammar_bn":"শব্দ"},{"id":7275,"position":14,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7276,"position":15,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"কোনো সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7277,"position":16,"text_uthmani":"فِيهِ ۚ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7279,"position":17,"text_uthmani":"فَرِيقٌۭ","transliteration":"farīqun","translation_bn":"একদল (সেদিন হবে)","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":7280,"position":18,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7281,"position":19,"text_uthmani":"ٱلْجَنَّةِ","transliteration":"l-janati","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":7282,"position":20,"text_uthmani":"وَفَرِيقٌۭ","transliteration":"wafarīqun","translation_bn":"এবং একদল (হবে)","root":"فرق","lemma":"فَرِيق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7283,"position":21,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7284,"position":22,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"জাহান্নামের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":7285,"position":23,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wakadhālika awḥaynā ilayka qur''ānan ʿarabiyyan litundhira umma l-qurā waman ḥawlahā watundhira yawma l-jamʿi lā rayba fīhi farīqun fī l-janati wafarīqun fī l-saʿīri', 'এভাবে আমি তোমার প্রতি কুরআন আরবী ভাষায় নাযিল করেছি যাতে তুমি উম্মুল কুরা (মক্কা শহর) ও তার চার পাশে যারা আছে তাদেরকে সতর্ক করতে পার, আর সতর্ক কর একত্রিত হওয়ার দিন সম্পর্কে যে বিষয়ে কোন সন্দেহ নেই। (একত্রিত হওয়ার পর) এক দল যাবে জান্নাতে, আরেক দল যাবে জাহান্নামে।', 'And thus We have revealed to you an Arabic Qur''an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.', 'এভাবে আমি তোমার প্রতি কুরআন আরবী ভাষায় নাযিল করেছি যাতে তুমি উম্মুল কুরা (মক্কা শহর) ও তার চার পাশে যারা আছে তাদেরকে সতর্ক করতে পার, আর সতর্ক কর একত্রিত হওয়ার দিন সম্পর্কে যে বিষয়ে কোন সন্দেহ নেই। (একত্রিত হওয়ার পর) এক দল যাবে জান্নাতে, আরেক দল যাবে জাহান্নামে।', 'And thus We have revealed to you an Arabic Qur''an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042007.mp3', now()),
  (42, 8, '', '[{"id":8542,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8543,"position":2,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চাইতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8544,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8545,"position":4,"text_uthmani":"لَجَعَلَهُمْ","transliteration":"lajaʿalahum","translation_bn":"তাদেরকে অবশ্যই করতেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8546,"position":5,"text_uthmani":"أُمَّةًۭ","transliteration":"ummatan","translation_bn":"জাতি","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8547,"position":6,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একই","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8548,"position":7,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8549,"position":8,"text_uthmani":"يُدْخِلُ","transliteration":"yud''khilu","translation_bn":"প্রবেশ করান","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8550,"position":9,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8551,"position":10,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন (আল্লাহ)","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8552,"position":11,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8553,"position":12,"text_uthmani":"رَحْمَتِهِۦ ۚ","transliteration":"raḥmatihi","translation_bn":"তাঁর অনুগ্রহের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8555,"position":13,"text_uthmani":"وَٱلظَّـٰلِمُونَ","transliteration":"wal-ẓālimūna","translation_bn":"এবং সীমালঙ্ঘনকারীদের (অবস্থা হলো)","root":"ظلم","lemma":"ظَالِم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8556,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8557,"position":15,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":8558,"position":16,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8559,"position":17,"text_uthmani":"وَلِىٍّۢ","transliteration":"waliyyin","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8560,"position":18,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর নেই","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8561,"position":19,"text_uthmani":"نَصِيرٍ","transliteration":"naṣīrin","translation_bn":"কোনো সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":8562,"position":20,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'walaw shāa l-lahu lajaʿalahum ummatan wāḥidatan walākin yud''khilu man yashāu fī raḥmatihi wal-ẓālimūna mā lahum min waliyyin walā naṣīrin', 'আল্লাহ ইচ্ছে করলে তাদেরকে একই উম্মত করতেন, কিন্তু তিনি যাকে ইচ্ছে তাঁর রহমাতের মধ্যে দাখিল করেন, আর যালিমদের জন্য নেই কোন অভিভাবক, নেই কোন সাহায্যকারী।', 'And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.', 'আল্লাহ ইচ্ছে করলে তাদেরকে একই উম্মত করতেন, কিন্তু তিনি যাকে ইচ্ছে তাঁর রহমাতের মধ্যে দাখিল করেন, আর যালিমদের জন্য নেই কোন অভিভাবক, নেই কোন সাহায্যকারী।', 'And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042008.mp3', now()),
  (42, 9, '', '[{"id":9753,"position":1,"text_uthmani":"أَمِ","transliteration":"ami","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9754,"position":2,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9755,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9756,"position":4,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাঁকে ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":9757,"position":5,"text_uthmani":"أَوْلِيَآءَ ۖ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে (অন্যান্যদেরকে)","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9759,"position":6,"text_uthmani":"فَٱللَّهُ","transliteration":"fal-lahu","translation_bn":"অথচ আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":9760,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9761,"position":8,"text_uthmani":"ٱلْوَلِىُّ","transliteration":"l-waliyu","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"শব্দ"},{"id":9762,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9763,"position":10,"text_uthmani":"يُحْىِ","transliteration":"yuḥ''yī","translation_bn":"জীবিত করেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":9764,"position":11,"text_uthmani":"ٱلْمَوْتَىٰ","transliteration":"l-mawtā","translation_bn":"মৃতদেরকে","root":"موت","lemma":"مَّيِّت","grammar_bn":"শব্দ"},{"id":9765,"position":12,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9766,"position":13,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9767,"position":14,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9768,"position":15,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুরই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":9769,"position":16,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":9770,"position":17,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'ami ittakhadhū min dūnihi awliyāa fal-lahu huwa l-waliyu wahuwa yuḥ''yī l-mawtā wahuwa ʿalā kulli shayin qadīrun', 'কী! তারা কি আল্লাহর পরিবর্তে অন্যদেরকে অভিভাবক গ্রহণ করে নিয়েছে? আল্লাহই তো একমাত্র অভিভাবক, তিনিই মৃতকে জীবিত করেন আর তিনি সব কিছুর উপর ক্ষমতাবান।', 'Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent.', 'কী! তারা কি আল্লাহর পরিবর্তে অন্যদেরকে অভিভাবক গ্রহণ করে নিয়েছে? আল্লাহই তো একমাত্র অভিভাবক, তিনিই মৃতকে জীবিত করেন আর তিনি সব কিছুর উপর ক্ষমতাবান।', 'Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042009.mp3', now()),
  (42, 10, '', '[{"id":10886,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10887,"position":2,"text_uthmani":"ٱخْتَلَفْتُمْ","transliteration":"ikh''talaftum","translation_bn":"তোমরা মতভেদ করো","root":"خلف","lemma":"ٱخْتَلَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10888,"position":3,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"সেক্ষেত্রে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10889,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10890,"position":5,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10891,"position":6,"text_uthmani":"فَحُكْمُهُۥٓ","transliteration":"faḥuk''muhu","translation_bn":"তার অতঃপর  মীমাংসা (হবে)","root":"حكم","lemma":"حُكْم","grammar_bn":"শব্দ"},{"id":10892,"position":7,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10893,"position":8,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10895,"position":9,"text_uthmani":"ذَٰلِكُمُ","transliteration":"dhālikumu","translation_bn":"তিনিই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10896,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ-ই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10897,"position":11,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10898,"position":12,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তাঁর উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10899,"position":13,"text_uthmani":"تَوَكَّلْتُ","transliteration":"tawakkaltu","translation_bn":"আমি নির্ভর করি","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10900,"position":14,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10901,"position":15,"text_uthmani":"أُنِيبُ","transliteration":"unību","translation_bn":"মুখ ফিরিয়েছি আমি","root":"نوب","lemma":"أَنَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10902,"position":16,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā ikh''talaftum fīhi min shayin faḥuk''muhu ilā l-lahi dhālikumu l-lahu rabbī ʿalayhi tawakkaltu wa-ilayhi unību', 'তোমরা যে সব বিষয়ে মতভেদ কর তার মীমাংসা আল্লাহর উপর সোপর্দ. সেই আল্লাহই আমার প্রতিপালক, আমি তাঁর উপরই নির্ভর করি, আর তাঁরই অভিমুখী হই।', 'And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], "That is Allah, my Lord; upon Him I have relied, and to Him I turn back."', 'তোমরা যে সব বিষয়ে মতভেদ কর তার মীমাংসা আল্লাহর উপর সোপর্দ. সেই আল্লাহই আমার প্রতিপালক, আমি তাঁর উপরই নির্ভর করি, আর তাঁরই অভিমুখী হই।', 'And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], "That is Allah, my Lord; upon Him I have relied, and to Him I turn back."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042010.mp3', now()),
  (42, 11, '', '[{"id":12204,"position":1,"text_uthmani":"فَاطِرُ","transliteration":"fāṭiru","translation_bn":"(আল্লাহ-ই) সৃষ্টিকর্তা","root":"فطر","lemma":"فَاطِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12205,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12206,"position":3,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12208,"position":4,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"তিনি সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12209,"position":5,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":12210,"position":6,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12211,"position":7,"text_uthmani":"أَنفُسِكُمْ","transliteration":"anfusikum","translation_bn":"তোমাদের নিজেদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":12212,"position":8,"text_uthmani":"أَزْوَٰجًۭا","transliteration":"azwājan","translation_bn":"জোড়া জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":12213,"position":9,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"এবং মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12214,"position":10,"text_uthmani":"ٱلْأَنْعَـٰمِ","transliteration":"l-anʿāmi","translation_bn":"গবাদি পশুর","root":"نعم","lemma":"نَّعَم","grammar_bn":"শব্দ"},{"id":12215,"position":11,"text_uthmani":"أَزْوَٰجًۭا ۖ","transliteration":"azwājan","translation_bn":"জোড়া জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":12217,"position":12,"text_uthmani":"يَذْرَؤُكُمْ","transliteration":"yadhra-ukum","translation_bn":"তোমাদের বিস্তার করেন (বংশ)","root":"ذرا","lemma":"ذَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12218,"position":13,"text_uthmani":"فِيهِ ۚ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12220,"position":14,"text_uthmani":"لَيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12221,"position":15,"text_uthmani":"كَمِثْلِهِۦ","transliteration":"kamith''lihi","translation_bn":"তাঁর মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"অব্যয় (Preposition)"},{"id":12222,"position":16,"text_uthmani":"شَىْءٌۭ ۖ","transliteration":"shayon","translation_bn":"কোনো কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12224,"position":17,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12225,"position":18,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":12226,"position":19,"text_uthmani":"ٱلْبَصِيرُ","transliteration":"l-baṣīru","translation_bn":"সবকিছুই দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"শব্দ"},{"id":12227,"position":20,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'fāṭiru l-samāwāti wal-arḍi jaʿala lakum min anfusikum azwājan wamina l-anʿāmi azwājan yadhra-ukum fīhi laysa kamith''lihi shayon wahuwa l-samīʿu l-baṣīru', 'আকাশসমূহ ও যমীনের স্রষ্টা। তিনি তোমাদের জন্য তোমাদের মধ্য হতে যুগল সৃষ্টি করেছেন, চতুস্পদ জন্তুদের মধ্যেও সৃষ্টি করেছেন জোড়া, এভাবেই তিনি তোমাদের বংশধারা বিস্তৃত করেন, কোন কিছুই তাঁর সদৃশ নয়, তিনি সব শোনেন, সব দেখেন।', '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.', 'আকাশসমূহ ও যমীনের স্রষ্টা। তিনি তোমাদের জন্য তোমাদের মধ্য হতে যুগল সৃষ্টি করেছেন, চতুস্পদ জন্তুদের মধ্যেও সৃষ্টি করেছেন জোড়া, এভাবেই তিনি তোমাদের বংশধারা বিস্তৃত করেন, কোন কিছুই তাঁর সদৃশ নয়, তিনি সব শোনেন, সব দেখেন।', '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042011.mp3', now()),
  (42, 12, '', '[{"id":13565,"position":1,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাঁরই (নিয়ন্ত্রণে)","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":13566,"position":2,"text_uthmani":"مَقَالِيدُ","transliteration":"maqālīdu","translation_bn":"চাবিসমূহ","root":"قلد","lemma":"مَقَالِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":13567,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":13568,"position":4,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13570,"position":5,"text_uthmani":"يَبْسُطُ","transliteration":"yabsuṭu","translation_bn":"প্রশস্ত করে দেন","root":"بسط","lemma":"بَسَطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13571,"position":6,"text_uthmani":"ٱلرِّزْقَ","transliteration":"l-riz''qa","translation_bn":"জীবনের উপকরণ","root":"رزق","lemma":"رِزْق","grammar_bn":"শব্দ"},{"id":13572,"position":7,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"(তার) জন্যে যাকে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13573,"position":8,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13574,"position":9,"text_uthmani":"وَيَقْدِرُ ۚ","transliteration":"wayaqdiru","translation_bn":"এবং পরিমিত দেন (যাকে ইচ্ছে করেন)","root":"قدر","lemma":"قَدَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13576,"position":10,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13577,"position":11,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"সম্পর্কে সব","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":13578,"position":12,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":13579,"position":13,"text_uthmani":"عَلِيمٌۭ","transliteration":"ʿalīmun","translation_bn":"খুব অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":13580,"position":14,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'lahu maqālīdu l-samāwāti wal-arḍi yabsuṭu l-riz''qa liman yashāu wayaqdiru innahu bikulli shayin ʿalīmun', 'আসমান ও যমীনের চাবিকাঠি তাঁরই হাতে নিবদ্ধ। যার জন্য ইচ্ছে তিনি রিযক প্রশস্ত করেন ও (যার জন্য ইচ্ছে) সীমিত করেন। সব বিষয়েই তিনি সবচেয়ে জ্ঞানী।', 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.', 'আসমান ও যমীনের চাবিকাঠি তাঁরই হাতে নিবদ্ধ। যার জন্য ইচ্ছে তিনি রিযক প্রশস্ত করেন ও (যার জন্য ইচ্ছে) সীমিত করেন। সব বিষয়েই তিনি সবচেয়ে জ্ঞানী।', 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042012.mp3', now()),
  (42, 13, '', '[{"id":14726,"position":1,"text_uthmani":"۞ شَرَعَ","transliteration":"sharaʿa","translation_bn":"তিনি বিধান দিয়েছেন","root":"شرع","lemma":"شَرَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14727,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে (একমাত্র)","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":14728,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14729,"position":4,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"দ্বীনের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":14730,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14731,"position":6,"text_uthmani":"وَصَّىٰ","transliteration":"waṣṣā","translation_bn":"আদেশ দিয়েছিলেন","root":"وصي","lemma":"وَصَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14732,"position":7,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সে সম্পর্কে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":14733,"position":8,"text_uthmani":"نُوحًۭا","transliteration":"nūḥan","translation_bn":"নূহকে","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14734,"position":9,"text_uthmani":"وَٱلَّذِىٓ","transliteration":"wa-alladhī","translation_bn":"এবং (হে নাবী) যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14735,"position":10,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ওহী করেছি","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":14736,"position":11,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতিও","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14737,"position":12,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14738,"position":13,"text_uthmani":"وَصَّيْنَا","transliteration":"waṣṣaynā","translation_bn":"আমরা আদেশ দিয়েছি","root":"وصي","lemma":"وَصَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14739,"position":14,"text_uthmani":"بِهِۦٓ","transliteration":"bihi","translation_bn":"সে সম্পর্কে","root":"—","lemma":"بِهِۦٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":14740,"position":15,"text_uthmani":"إِبْرَٰهِيمَ","transliteration":"ib''rāhīma","translation_bn":"ইব্রাহীমকে","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14741,"position":16,"text_uthmani":"وَمُوسَىٰ","transliteration":"wamūsā","translation_bn":"ও মূসাকে","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14742,"position":17,"text_uthmani":"وَعِيسَىٰٓ ۖ","transliteration":"waʿīsā","translation_bn":"ও ঈসাকে","root":"—","lemma":"عِيسَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14744,"position":18,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"(এ তাগিদসহ) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":14745,"position":19,"text_uthmani":"أَقِيمُوا۟","transliteration":"aqīmū","translation_bn":"তোমরা প্রতিষ্ঠিত করো","root":"قوم","lemma":"أَقَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14746,"position":20,"text_uthmani":"ٱلدِّينَ","transliteration":"l-dīna","translation_bn":"দ্বীনকে","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":14747,"position":21,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14748,"position":22,"text_uthmani":"تَتَفَرَّقُوا۟","transliteration":"tatafarraqū","translation_bn":"তোমরা মতবিরোধ করো","root":"فرق","lemma":"تَفَرَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14749,"position":23,"text_uthmani":"فِيهِ ۚ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14751,"position":24,"text_uthmani":"كَبُرَ","transliteration":"kabura","translation_bn":"বড় কঠিন হয়েছে","root":"كبر","lemma":"كَبُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14752,"position":25,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14753,"position":26,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":14754,"position":27,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যার","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14755,"position":28,"text_uthmani":"تَدْعُوهُمْ","transliteration":"tadʿūhum","translation_bn":"তুমি আহবান করছো তাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":14756,"position":29,"text_uthmani":"إِلَيْهِ ۚ","transliteration":"ilayhi","translation_bn":"তাঁর দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14758,"position":30,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14759,"position":31,"text_uthmani":"يَجْتَبِىٓ","transliteration":"yajtabī","translation_bn":"বেছে নেন","root":"جبي","lemma":"ٱجْتَبَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14760,"position":32,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁর দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14761,"position":33,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14762,"position":34,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14763,"position":35,"text_uthmani":"وَيَهْدِىٓ","transliteration":"wayahdī","translation_bn":"এবং পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14764,"position":36,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তাঁর দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14765,"position":37,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14766,"position":38,"text_uthmani":"يُنِيبُ","transliteration":"yunību","translation_bn":"মুখ ফিরায় (তাঁর দিকে)","root":"نوب","lemma":"أَنَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14767,"position":39,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'sharaʿa lakum mina l-dīni mā waṣṣā bihi nūḥan wa-alladhī awḥaynā ilayka wamā waṣṣaynā bihi ib''rāhīma wamūsā waʿīsā an aqīmū l-dīna walā tatafarraqū fīhi kabura ʿalā l-mush''rikīna mā tadʿūhum ilayhi l-lahu yajtabī ilayhi man yashāu wayahdī ilayhi man yunību', 'তিনি তোমাদের জন্য দ্বীনের সেই বিধি-ব্যবস্থাই দিয়েছেন যার হুকুম তিনি দিয়েছিলেন নূহকে। আর সেই (বিধি ব্যবস্থাই) তোমাকে ওয়াহীর মাধ্যমে দিলাম যার হুকুম দিয়েছিলাম ইবরাহীম, মূসা ও ‘ঈসাকে- তা এই যে, তোমরা দ্বীন প্রতিষ্ঠিত কর, আর তাতে বিভক্তি সৃষ্টি করো না, ব্যাপারটি মুশরিকদের জন্য কঠিন হয়ে দাঁড়িয়েছে যার দিকে তুমি তাদেরকে আহবান জানাচ্ছ। আল্লাহ যাকে ইচ্ছে করেন তাঁর পথে বেছে নেন, আর তিনি তাঁর পথে পরিচালিত করেন তাকে, যে তাঁর অভিমুখী হয়।', 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].', 'তিনি তোমাদের জন্য দ্বীনের সেই বিধি-ব্যবস্থাই দিয়েছেন যার হুকুম তিনি দিয়েছিলেন নূহকে। আর সেই (বিধি ব্যবস্থাই) তোমাকে ওয়াহীর মাধ্যমে দিলাম যার হুকুম দিয়েছিলাম ইবরাহীম, মূসা ও ‘ঈসাকে- তা এই যে, তোমরা দ্বীন প্রতিষ্ঠিত কর, আর তাতে বিভক্তি সৃষ্টি করো না, ব্যাপারটি মুশরিকদের জন্য কঠিন হয়ে দাঁড়িয়েছে যার দিকে তুমি তাদেরকে আহবান জানাচ্ছ। আল্লাহ যাকে ইচ্ছে করেন তাঁর পথে বেছে নেন, আর তিনি তাঁর পথে পরিচালিত করেন তাকে, যে তাঁর অভিমুখী হয়।', 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042013.mp3', now()),
  (42, 14, '', '[{"id":15808,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15809,"position":2,"text_uthmani":"تَفَرَّقُوٓا۟","transliteration":"tafarraqū","translation_bn":"তারা মতবিরোধ করেছে","root":"فرق","lemma":"تَفَرَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15810,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":15811,"position":4,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15812,"position":5,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":15813,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":15814,"position":7,"text_uthmani":"جَآءَهُمُ","transliteration":"jāahumu","translation_bn":"(কাছে) এসেছিলো তাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15815,"position":8,"text_uthmani":"ٱلْعِلْمُ","transliteration":"l-ʿil''mu","translation_bn":"(অর্থাৎ) জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"শব্দ"},{"id":15816,"position":9,"text_uthmani":"بَغْيًۢا","transliteration":"baghyan","translation_bn":"(এমন করেছে) বিদ্বেষ বশতঃ","root":"بغي","lemma":"بَغْي","grammar_bn":"বিশেষ্য (Noun)"},{"id":15817,"position":10,"text_uthmani":"بَيْنَهُمْ ۚ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":15819,"position":11,"text_uthmani":"وَلَوْلَا","transliteration":"walawlā","translation_bn":"এবং যদি না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15820,"position":12,"text_uthmani":"كَلِمَةٌۭ","transliteration":"kalimatun","translation_bn":"একটি বাণী (ফায়সালার)","root":"كلم","lemma":"كَلِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15821,"position":13,"text_uthmani":"سَبَقَتْ","transliteration":"sabaqat","translation_bn":"অতীতে সিদ্ধান্ত করা হতো","root":"سبق","lemma":"سَبَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15822,"position":14,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15823,"position":15,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15824,"position":16,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15825,"position":17,"text_uthmani":"أَجَلٍۢ","transliteration":"ajalin","translation_bn":"সময় (অবকাশের)","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15826,"position":18,"text_uthmani":"مُّسَمًّۭى","transliteration":"musamman","translation_bn":"নির্ধারিত","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষ্য (Noun)"},{"id":15827,"position":19,"text_uthmani":"لَّقُضِىَ","transliteration":"laquḍiya","translation_bn":"মীমাংসা অবশ্যই করে দেওয়া হতো","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15828,"position":20,"text_uthmani":"بَيْنَهُمْ ۚ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":15830,"position":21,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15831,"position":22,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":15832,"position":23,"text_uthmani":"أُورِثُوا۟","transliteration":"ūrithū","translation_bn":"উত্তরাধিকারী করা হয়েছিলো","root":"ورث","lemma":"أَوْرَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15833,"position":24,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":15834,"position":25,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15835,"position":26,"text_uthmani":"بَعْدِهِمْ","transliteration":"baʿdihim","translation_bn":"তাদের পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":15836,"position":27,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15837,"position":28,"text_uthmani":"شَكٍّۢ","transliteration":"shakkin","translation_bn":"সন্দেহের","root":"شكك","lemma":"شَكّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15838,"position":29,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তা সম্পর্কে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15839,"position":30,"text_uthmani":"مُرِيبٍۢ","transliteration":"murībin","translation_bn":"বিভ্রান্তিকর","root":"ريب","lemma":"مُرِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":15840,"position":31,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā tafarraqū illā min baʿdi mā jāahumu l-ʿil''mu baghyan baynahum walawlā kalimatun sabaqat min rabbika ilā ajalin musamman laquḍiya baynahum wa-inna alladhīna ūrithū l-kitāba min baʿdihim lafī shakkin min''hu murībin', 'মানুষের কাছে ইলম আসার পর (বিভিন্ন অংশে) বিভক্ত হয়ে গেল নিজেদের মধ্যে বাড়াবাড়ি করার কারণে। পূর্বেই যদি তোমার প্রতিপালকের পক্ষ হতে একটা নির্দিষ্ট মেয়াদ পর্যন্ত ফয়সালা মূলতবী রাখার কথা ঘোষিত না হত, তাহলে তাদের মধ্যে (পূর্বেই) ফয়সালা করে দেয়া হত। আগেকার লোকেদের পরে যারা (তাওরাত ও ইঞ্জিল এ দু’) কিতাব উত্তরাধিকার সূত্রে পাপ্ত হয়েছে, তারা অস্বস্তিকর সন্দেহে পতিত হয়েছে।', 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.', 'মানুষের কাছে ইলম আসার পর (বিভিন্ন অংশে) বিভক্ত হয়ে গেল নিজেদের মধ্যে বাড়াবাড়ি করার কারণে। পূর্বেই যদি তোমার প্রতিপালকের পক্ষ হতে একটা নির্দিষ্ট মেয়াদ পর্যন্ত ফয়সালা মূলতবী রাখার কথা ঘোষিত না হত, তাহলে তাদের মধ্যে (পূর্বেই) ফয়সালা করে দেয়া হত। আগেকার লোকেদের পরে যারা (তাওরাত ও ইঞ্জিল এ দু’) কিতাব উত্তরাধিকার সূত্রে পাপ্ত হয়েছে, তারা অস্বস্তিকর সন্দেহে পতিত হয়েছে।', 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042014.mp3', now()),
  (42, 15, '', '[{"id":16924,"position":1,"text_uthmani":"فَلِذَٰلِكَ","transliteration":"falidhālika","translation_bn":"(হে নাবী) এজন্যে","root":"—","lemma":"ذَٰلِك","grammar_bn":"শব্দ"},{"id":16925,"position":2,"text_uthmani":"فَٱدْعُ ۖ","transliteration":"fa-ud''ʿu","translation_bn":"তাই আহবান করো","root":"دعو","lemma":"دَعَا","grammar_bn":"শব্দ"},{"id":16927,"position":3,"text_uthmani":"وَٱسْتَقِمْ","transliteration":"wa-is''taqim","translation_bn":"এবং অবিচল থাকো","root":"قوم","lemma":"ٱسْتَقَٰمُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16928,"position":4,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16929,"position":5,"text_uthmani":"أُمِرْتَ ۖ","transliteration":"umir''ta","translation_bn":"তোমাকে আদেশ করা হয়েছে","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16931,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16932,"position":7,"text_uthmani":"تَتَّبِعْ","transliteration":"tattabiʿ","translation_bn":"অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16933,"position":8,"text_uthmani":"أَهْوَآءَهُمْ ۖ","transliteration":"ahwāahum","translation_bn":"তাদের খেয়ালখুশীর","root":"هوي","lemma":"أَهْوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":16935,"position":9,"text_uthmani":"وَقُلْ","transliteration":"waqul","translation_bn":"এবং বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16936,"position":10,"text_uthmani":"ءَامَنتُ","transliteration":"āmantu","translation_bn":"\"আমি ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16937,"position":11,"text_uthmani":"بِمَآ","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16938,"position":12,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16939,"position":13,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16940,"position":14,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16941,"position":15,"text_uthmani":"كِتَـٰبٍۢ ۖ","transliteration":"kitābin","translation_bn":"(অর্থাৎ) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":16943,"position":16,"text_uthmani":"وَأُمِرْتُ","transliteration":"wa-umir''tu","translation_bn":"এবং আমাকে আদেশ করা হয়েছে","root":"امر","lemma":"أَمَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16944,"position":17,"text_uthmani":"لِأَعْدِلَ","transliteration":"li-aʿdila","translation_bn":"আমি যেন ন্যায় বিচার করি","root":"عدل","lemma":"عَدَلَ","grammar_bn":"শব্দ"},{"id":16945,"position":18,"text_uthmani":"بَيْنَكُمُ ۖ","transliteration":"baynakumu","translation_bn":"তোমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":16947,"position":19,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16948,"position":20,"text_uthmani":"رَبُّنَا","transliteration":"rabbunā","translation_bn":"আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16949,"position":21,"text_uthmani":"وَرَبُّكُمْ ۖ","transliteration":"warabbukum","translation_bn":"ও তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16951,"position":22,"text_uthmani":"لَنَآ","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَنَآ","grammar_bn":"অব্যয় (Preposition)"},{"id":16952,"position":23,"text_uthmani":"أَعْمَـٰلُنَا","transliteration":"aʿmālunā","translation_bn":"আমাদের কাজসমূহ","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16953,"position":24,"text_uthmani":"وَلَكُمْ","transliteration":"walakum","translation_bn":"ও তোমাদের জন্যে","root":"—","lemma":"وَلَكُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16954,"position":25,"text_uthmani":"أَعْمَـٰلُكُمْ ۖ","transliteration":"aʿmālukum","translation_bn":"তোমাদের কাজসমূহ","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16956,"position":26,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":16957,"position":27,"text_uthmani":"حُجَّةَ","transliteration":"ḥujjata","translation_bn":"কোনো বিবাদ","root":"حجج","lemma":"حُجَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16958,"position":28,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"আমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":16959,"position":29,"text_uthmani":"وَبَيْنَكُمُ ۖ","transliteration":"wabaynakumu","translation_bn":"ও তোমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16961,"position":30,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16962,"position":31,"text_uthmani":"يَجْمَعُ","transliteration":"yajmaʿu","translation_bn":"একত্র করবেন","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16963,"position":32,"text_uthmani":"بَيْنَنَا ۖ","transliteration":"baynanā","translation_bn":"আমাদেরকে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":16965,"position":33,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16966,"position":34,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন (হবে সবার)\"","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":16967,"position":35,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'falidhālika fa-ud''ʿu wa-is''taqim kamā umir''ta walā tattabiʿ ahwāahum waqul āmantu bimā anzala l-lahu min kitābin wa-umir''tu li-aʿdila baynakumu l-lahu rabbunā warabbukum lanā aʿmālunā walakum aʿmālukum lā ḥujjata baynanā wabaynakumu l-lahu yajmaʿu baynanā wa-ilayhi l-maṣīru', 'অবস্থার এই প্রেক্ষাপটে (হে নবী!) তাদেরকে আহবান কর (দ্বীনের প্রতি), আর তোমাকে যে হুকুম দেয়া হয়েছে তুমি তার প্রতি সুদৃঢ় থাক, আর তাদের খেয়াল খুশির অনুসরণ করো না। আর বল, আল্লাহ যে কিতাবই অবতীর্ণ করেছেন আমি তার প্রতি ঈমান এনেছি। তোমাদের মাঝে ইনসাফ করার জন্য আমাকে নির্দেশ দেয়া হয়েছে। আল্লাহ আমাদেরও প্রতিপালক, তোমাদেরও প্রতিপালক। আমাদের কাজের প্রতিফল আমরা ভোগ করব। আর তোমাদের কাজের প্রতিফল তোমরা ভোগ করবে। আমাদের আর তোমাদের মাঝে কোন ঝগড়া নেই। আল্লাহ আমাদের সবাইকে (একদিন) একত্রিত করবেন, আর তাঁর কাছেই (সকলকে) ফিরে যেতে হবে।', 'So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allah has revealed of the Qur''an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination."', 'অবস্থার এই প্রেক্ষাপটে (হে নবী!) তাদেরকে আহবান কর (দ্বীনের প্রতি), আর তোমাকে যে হুকুম দেয়া হয়েছে তুমি তার প্রতি সুদৃঢ় থাক, আর তাদের খেয়াল খুশির অনুসরণ করো না। আর বল, আল্লাহ যে কিতাবই অবতীর্ণ করেছেন আমি তার প্রতি ঈমান এনেছি। তোমাদের মাঝে ইনসাফ করার জন্য আমাকে নির্দেশ দেয়া হয়েছে। আল্লাহ আমাদেরও প্রতিপালক, তোমাদেরও প্রতিপালক। আমাদের কাজের প্রতিফল আমরা ভোগ করব। আর তোমাদের কাজের প্রতিফল তোমরা ভোগ করবে। আমাদের আর তোমাদের মাঝে কোন ঝগড়া নেই। আল্লাহ আমাদের সবাইকে (একদিন) একত্রিত করবেন, আর তাঁর কাছেই (সকলকে) ফিরে যেতে হবে।', 'So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allah has revealed of the Qur''an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042015.mp3', now()),
  (42, 16, '', '[{"id":18059,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18060,"position":2,"text_uthmani":"يُحَآجُّونَ","transliteration":"yuḥājjūna","translation_bn":"বিতর্ক করে","root":"حجج","lemma":"حَا^جَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18061,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সম্পর্কে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18062,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র দ্বীনের","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18063,"position":5,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18064,"position":6,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পরেও","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":18065,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18066,"position":8,"text_uthmani":"ٱسْتُجِيبَ","transliteration":"us''tujība","translation_bn":"সাড়া দেওয়া হয়েছে (অর্থাৎ দ্বীন গ্রহণের পরেও)","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18067,"position":9,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":18068,"position":10,"text_uthmani":"حُجَّتُهُمْ","transliteration":"ḥujjatuhum","translation_bn":"তাদের যুক্তিতর্ক","root":"حجج","lemma":"حُجَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18069,"position":11,"text_uthmani":"دَاحِضَةٌ","transliteration":"dāḥiḍatun","translation_bn":"নিরর্থক","root":"دحض","lemma":"دَاحِضَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18070,"position":12,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":18071,"position":13,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18072,"position":14,"text_uthmani":"وَعَلَيْهِمْ","transliteration":"waʿalayhim","translation_bn":"এবং তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18073,"position":15,"text_uthmani":"غَضَبٌۭ","transliteration":"ghaḍabun","translation_bn":"অভিসম্পাত","root":"غضب","lemma":"غَضَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":18074,"position":16,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদের জন্যে","root":"—","lemma":"وَلَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18075,"position":17,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি (রয়েছে)","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":18076,"position":18,"text_uthmani":"شَدِيدٌ","transliteration":"shadīdun","translation_bn":"কঠিন","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":18077,"position":19,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna yuḥājjūna fī l-lahi min baʿdi mā us''tujība lahu ḥujjatuhum dāḥiḍatun ʿinda rabbihim waʿalayhim ghaḍabun walahum ʿadhābun shadīdun', 'আল্লাহর আহবানে সাড়া দেয়ার পর সে সম্পর্কে যারা বিতর্কে লিপ্ত হয়, তাদের দলীল প্রমাণ তাদের রব্ব-এর কাছে বাতিল। তাদের প্রতি (আল্লাহর) গযব আর তাদের জন্য আছে কঠিন শাস্তি।', 'And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.', 'আল্লাহর আহবানে সাড়া দেয়ার পর সে সম্পর্কে যারা বিতর্কে লিপ্ত হয়, তাদের দলীল প্রমাণ তাদের রব্ব-এর কাছে বাতিল। তাদের প্রতি (আল্লাহর) গযব আর তাদের জন্য আছে কঠিন শাস্তি।', 'And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042016.mp3', now()),
  (42, 17, '', '[{"id":19066,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"(তিনিই) আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19067,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19068,"position":3,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19069,"position":4,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":19070,"position":5,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"সত্যসহ","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":19071,"position":6,"text_uthmani":"وَٱلْمِيزَانَ ۗ","transliteration":"wal-mīzāna","translation_bn":"এবং মীযান","root":"وزن","lemma":"مِيزَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19073,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং কিসে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19074,"position":8,"text_uthmani":"يُدْرِيكَ","transliteration":"yud''rīka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19075,"position":9,"text_uthmani":"لَعَلَّ","transliteration":"laʿalla","translation_bn":"সম্ভবতঃ","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19076,"position":10,"text_uthmani":"ٱلسَّاعَةَ","transliteration":"l-sāʿata","translation_bn":"ক্বিয়ামাত","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":19077,"position":11,"text_uthmani":"قَرِيبٌۭ","transliteration":"qarībun","translation_bn":"আসন্ন","root":"قرب","lemma":"قَرِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":19078,"position":12,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu alladhī anzala l-kitāba bil-ḥaqi wal-mīzāna wamā yud''rīka laʿalla l-sāʿata qarībun', 'তিনিই আল্লাহ যিনি সত্য ও ইনসাফের মানদন্ড সহকারে কিতাব অবতীর্ণ করেছেন। তুমি কি জান, সম্ভবতঃ চূড়ান্ত ফয়সালার সময় নিকটবর্তী হয়ে গেছে।', 'It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.', 'তিনিই আল্লাহ যিনি সত্য ও ইনসাফের মানদন্ড সহকারে কিতাব অবতীর্ণ করেছেন। তুমি কি জান, সম্ভবতঃ চূড়ান্ত ফয়সালার সময় নিকটবর্তী হয়ে গেছে।', 'It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042017.mp3', now()),
  (42, 18, '', '[{"id":20170,"position":1,"text_uthmani":"يَسْتَعْجِلُ","transliteration":"yastaʿjilu","translation_bn":"তাড়াহুড়া করে","root":"عجل","lemma":"ٱسْتَعْجَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20171,"position":2,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"তা সম্পর্কে","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":20172,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারাই) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20173,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20174,"position":5,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20175,"position":6,"text_uthmani":"بِهَا ۖ","transliteration":"bihā","translation_bn":"তা সম্পর্কে","root":"—","lemma":"بِهَا ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":20177,"position":7,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"কিন্তু যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20178,"position":8,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20179,"position":9,"text_uthmani":"مُشْفِقُونَ","transliteration":"mush''fiqūna","translation_bn":"তারা ভয় করে","root":"شفق","lemma":"مُشْفِقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":20180,"position":10,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20181,"position":11,"text_uthmani":"وَيَعْلَمُونَ","transliteration":"wayaʿlamūna","translation_bn":"এবং তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20182,"position":12,"text_uthmani":"أَنَّهَا","transliteration":"annahā","translation_bn":"তা যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20183,"position":13,"text_uthmani":"ٱلْحَقُّ ۗ","transliteration":"l-ḥaqu","translation_bn":"মহাসত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":20185,"position":14,"text_uthmani":"أَلَآ","transliteration":"alā","translation_bn":"জেনে রাখো","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":20186,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20187,"position":16,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20188,"position":17,"text_uthmani":"يُمَارُونَ","transliteration":"yumārūna","translation_bn":"কুতর্ক করে","root":"مري","lemma":"تَمَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20189,"position":18,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সম্পর্কে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20190,"position":19,"text_uthmani":"ٱلسَّاعَةِ","transliteration":"l-sāʿati","translation_bn":"ক্বিয়ামাতের","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":20191,"position":20,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20192,"position":21,"text_uthmani":"ضَلَـٰلٍۭ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":20193,"position":22,"text_uthmani":"بَعِيدٍ","transliteration":"baʿīdin","translation_bn":"বহুদূরে (চলে গিয়েছে)","root":"بعد","lemma":"بَعِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":20194,"position":23,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'yastaʿjilu bihā alladhīna lā yu''minūna bihā wa-alladhīna āmanū mush''fiqūna min''hā wayaʿlamūna annahā l-ḥaqu alā inna alladhīna yumārūna fī l-sāʿati lafī ḍalālin baʿīdin', 'যে সব লোক তাতে বিশ্বাস করে না, তারাই তার (অর্থাৎ ক্বিয়ামতের) আগমনকে তরান্বিত করতে চায়। কিন্তু যারা বিশ্বাসী তারা তাকে ভয় করে আর তারা জানে যে, তা সত্য। জেনে রেখ, যারা ক্বিয়ামত সম্পর্কে বিতর্ক করে, তারা স্পষ্টতই সত্য পথ হতে বহু দূরে চলে গেছে।', 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.', 'যে সব লোক তাতে বিশ্বাস করে না, তারাই তার (অর্থাৎ ক্বিয়ামতের) আগমনকে তরান্বিত করতে চায়। কিন্তু যারা বিশ্বাসী তারা তাকে ভয় করে আর তারা জানে যে, তা সত্য। জেনে রেখ, যারা ক্বিয়ামত সম্পর্কে বিতর্ক করে, তারা স্পষ্টতই সত্য পথ হতে বহু দূরে চলে গেছে।', 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042018.mp3', now()),
  (42, 19, '', '[{"id":21256,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21257,"position":2,"text_uthmani":"لَطِيفٌۢ","transliteration":"laṭīfun","translation_bn":"অতি দয়ালু","root":"لطف","lemma":"لَطِيف","grammar_bn":"বিশেষণ (Adjective)"},{"id":21258,"position":3,"text_uthmani":"بِعِبَادِهِۦ","transliteration":"biʿibādihi","translation_bn":"তার দাসদের উপর","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":21259,"position":4,"text_uthmani":"يَرْزُقُ","transliteration":"yarzuqu","translation_bn":"তিনি জীবিকা দান করেন","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21260,"position":5,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":21261,"position":6,"text_uthmani":"يَشَآءُ ۖ","transliteration":"yashāu","translation_bn":"ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21263,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21264,"position":8,"text_uthmani":"ٱلْقَوِىُّ","transliteration":"l-qawiyu","translation_bn":"প্রবল শক্তিমান","root":"قوي","lemma":"قَوِىّ","grammar_bn":"শব্দ"},{"id":21265,"position":9,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":21266,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu laṭīfun biʿibādihi yarzuqu man yashāu wahuwa l-qawiyu l-ʿazīzu', 'আল্লাহ তাঁর বান্দাহদের প্রতি মেহেরবান, তিনি যাকে যা ইচ্ছে রিযক দেন। তিনি প্রবল, মহাপরাক্রমশালী।', 'Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.', 'আল্লাহ তাঁর বান্দাহদের প্রতি মেহেরবান, তিনি যাকে যা ইচ্ছে রিযক দেন। তিনি প্রবল, মহাপরাক্রমশালী।', 'Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042019.mp3', now()),
  (42, 20, '', '[{"id":22345,"position":1,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22346,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22347,"position":3,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"কামনা করে","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22348,"position":4,"text_uthmani":"حَرْثَ","transliteration":"ḥartha","translation_bn":"ফসল","root":"حرث","lemma":"حَرْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":22349,"position":5,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":22350,"position":6,"text_uthmani":"نَزِدْ","transliteration":"nazid","translation_bn":"বাড়িয়ে দিই আমরা","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22351,"position":7,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":22352,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22353,"position":9,"text_uthmani":"حَرْثِهِۦ ۖ","transliteration":"ḥarthihi","translation_bn":"তার ফসলের","root":"حرث","lemma":"حَرْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":22355,"position":10,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22356,"position":11,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22357,"position":12,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"কামনা করে","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22358,"position":13,"text_uthmani":"حَرْثَ","transliteration":"ḥartha","translation_bn":"ফসল","root":"حرث","lemma":"حَرْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":22359,"position":14,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":22360,"position":15,"text_uthmani":"نُؤْتِهِۦ","transliteration":"nu''tihi","translation_bn":"তাকে দিই আমরা","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":22361,"position":16,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22362,"position":17,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নেই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22363,"position":18,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":22364,"position":19,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22365,"position":20,"text_uthmani":"ٱلْـَٔاخِرَةِ","transliteration":"l-ākhirati","translation_bn":"পরকালের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":22366,"position":21,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22367,"position":22,"text_uthmani":"نَّصِيبٍ","transliteration":"naṣībin","translation_bn":"অংশ","root":"نصب","lemma":"نَصِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":22368,"position":23,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'man kāna yurīdu ḥartha l-ākhirati nazid lahu fī ḥarthihi waman kāna yurīdu ḥartha l-dun''yā nu''tihi min''hā wamā lahu fī l-ākhirati min naṣībin', 'যে লোক পরকালের ক্ষেত করতে চায়, আমি তার জন্য তার ক্ষেতে বৃদ্ধি দান করি। আর যে লোক দুনিয়ার ক্ষেত চায়, আমি তাকে তাত্থেকে দেই, কিন্তু পরকালে তার অংশে (বা ভাগ্যে) কিছুই নেই।', 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share.', 'যে লোক পরকালের ক্ষেত করতে চায়, আমি তার জন্য তার ক্ষেতে বৃদ্ধি দান করি। আর যে লোক দুনিয়ার ক্ষেত চায়, আমি তাকে তাত্থেকে দেই, কিন্তু পরকালে তার অংশে (বা ভাগ্যে) কিছুই নেই।', 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042020.mp3', now()),
  (42, 21, '', '[{"id":23463,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23464,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে আছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":23465,"position":3,"text_uthmani":"شُرَكَـٰٓؤُا۟","transliteration":"shurakāu","translation_bn":"(কতক) শরিক","root":"شرك","lemma":"شَرِيك","grammar_bn":"বিশেষ্য (Noun)"},{"id":23466,"position":4,"text_uthmani":"شَرَعُوا۟","transliteration":"sharaʿū","translation_bn":"(যারা) বিধান দিয়েছে","root":"شرع","lemma":"شَرَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23467,"position":5,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে (ভিন্ন কিছু)","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":23468,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23469,"position":7,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"ধর্মের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":23470,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যার","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23471,"position":9,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":23472,"position":10,"text_uthmani":"يَأْذَنۢ","transliteration":"yadhan","translation_bn":"অনুমতি দেন নি","root":"اذن","lemma":"أَذِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23473,"position":11,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"সে সম্পর্কে","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":23474,"position":12,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23476,"position":13,"text_uthmani":"وَلَوْلَا","transliteration":"walawlā","translation_bn":"এবং যদি না (নির্ধারিত হতো)","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23477,"position":14,"text_uthmani":"كَلِمَةُ","transliteration":"kalimatu","translation_bn":"একটি কথা","root":"كلم","lemma":"كَلِمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23478,"position":15,"text_uthmani":"ٱلْفَصْلِ","transliteration":"l-faṣli","translation_bn":"মীমাংসার","root":"فصل","lemma":"فَصْل","grammar_bn":"শব্দ"},{"id":23479,"position":16,"text_uthmani":"لَقُضِىَ","transliteration":"laquḍiya","translation_bn":"চুড়ান্ত করে দেওয়া হতো অবশ্যই","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":23480,"position":17,"text_uthmani":"بَيْنَهُمْ ۗ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":23482,"position":18,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23483,"position":19,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারীরা","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":23484,"position":20,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":23485,"position":21,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23486,"position":22,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":23487,"position":23,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'am lahum shurakāu sharaʿū lahum mina l-dīni mā lam yadhan bihi l-lahu walawlā kalimatu l-faṣli laquḍiya baynahum wa-inna l-ẓālimīna lahum ʿadhābun alīmun', 'কী! তাদের কি এমন শরীক আছে যারা তাদের জন্য দ্বীনের বিধি-বিধান দিয়েছে যার অনুমতি আল্লাহ দেননি? ফয়সালা সম্পর্কিত (পূর্ব) ঘোষণা দেয়া না হলে তাদের মধ্যে (তৎক্ষণাৎ) ফয়সালা করে দেয়া হত। যালিমদের জন্য আছে যন্ত্রণাদায়ক শাস্তি।', 'Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.', 'কী! তাদের কি এমন শরীক আছে যারা তাদের জন্য দ্বীনের বিধি-বিধান দিয়েছে যার অনুমতি আল্লাহ দেননি? ফয়সালা সম্পর্কিত (পূর্ব) ঘোষণা দেয়া না হলে তাদের মধ্যে (তৎক্ষণাৎ) ফয়সালা করে দেয়া হত। যালিমদের জন্য আছে যন্ত্রণাদায়ক শাস্তি।', 'Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042021.mp3', now()),
  (42, 22, '', '[{"id":24491,"position":1,"text_uthmani":"تَرَى","transliteration":"tarā","translation_bn":"দেখবে তুমি","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":24492,"position":2,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারীদেরকে","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":24493,"position":3,"text_uthmani":"مُشْفِقِينَ","transliteration":"mush''fiqīna","translation_bn":"ভীত অবস্থায়","root":"شفق","lemma":"مُشْفِقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":24494,"position":4,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24495,"position":5,"text_uthmani":"كَسَبُوا۟","transliteration":"kasabū","translation_bn":"তারা কামাই করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24496,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তা","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24497,"position":7,"text_uthmani":"وَاقِعٌۢ","transliteration":"wāqiʿun","translation_bn":"পতিত হবেই","root":"وقع","lemma":"وَاقِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":24498,"position":8,"text_uthmani":"بِهِمْ ۗ","transliteration":"bihim","translation_bn":"তাদের উপর","root":"—","lemma":"بِهِمْ ۗ","grammar_bn":"অব্যয় (Preposition)"},{"id":24500,"position":9,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24501,"position":10,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24502,"position":11,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24503,"position":12,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":24504,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (হবে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24505,"position":14,"text_uthmani":"رَوْضَاتِ","transliteration":"rawḍāti","translation_bn":"বাগানসমূহের","root":"روض","lemma":"رَوْضَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":24506,"position":15,"text_uthmani":"ٱلْجَنَّاتِ ۖ","transliteration":"l-janāti","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":24508,"position":16,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে রয়েছে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":24509,"position":17,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24510,"position":18,"text_uthmani":"يَشَآءُونَ","transliteration":"yashāūna","translation_bn":"তারা ইচ্ছে করবে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24511,"position":19,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":24512,"position":20,"text_uthmani":"رَبِّهِمْ ۚ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24514,"position":21,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":24515,"position":22,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সেই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":24516,"position":23,"text_uthmani":"ٱلْفَضْلُ","transliteration":"l-faḍlu","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"শব্দ"},{"id":24517,"position":24,"text_uthmani":"ٱلْكَبِيرُ","transliteration":"l-kabīru","translation_bn":"মহা","root":"كبر","lemma":"كَبِير","grammar_bn":"শব্দ"},{"id":24518,"position":25,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'tarā l-ẓālimīna mush''fiqīna mimmā kasabū wahuwa wāqiʿun bihim wa-alladhīna āmanū waʿamilū l-ṣāliḥāti fī rawḍāti l-janāti lahum mā yashāūna ʿinda rabbihim dhālika huwa l-faḍlu l-kabīru', 'যালিমদেরকে তুমি তাদের কৃতকর্মের কারণে ভীত-সন্ত্রস্ত দেখতে পাবে। তাদের কর্মের শাস্তি অবশ্যই তাদের উপর পতিত হবে। আর যারা ঈমান এনেছে আর সৎকর্ম করেছে তারা জান্নাতের বাগিচায় অবস্থান করবে। তারা যা ইচ্ছে করবে, তাদের জন্য তাদের প্রতিপালকের নিকট তা-ই আছে। ওটাই অতি বড় অনুগ্রহ।', 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.', 'যালিমদেরকে তুমি তাদের কৃতকর্মের কারণে ভীত-সন্ত্রস্ত দেখতে পাবে। তাদের কর্মের শাস্তি অবশ্যই তাদের উপর পতিত হবে। আর যারা ঈমান এনেছে আর সৎকর্ম করেছে তারা জান্নাতের বাগিচায় অবস্থান করবে। তারা যা ইচ্ছে করবে, তাদের জন্য তাদের প্রতিপালকের নিকট তা-ই আছে। ওটাই অতি বড় অনুগ্রহ।', 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042022.mp3', now()),
  (42, 23, '', '[{"id":25572,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25573,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25574,"position":3,"text_uthmani":"يُبَشِّرُ","transliteration":"yubashiru","translation_bn":"সুসংবাদ দিয়েছেন","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25575,"position":4,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25576,"position":5,"text_uthmani":"عِبَادَهُ","transliteration":"ʿibādahu","translation_bn":"তাঁর দাসদেরকে","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":25577,"position":6,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25578,"position":7,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25579,"position":8,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25580,"position":9,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ ۗ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":25582,"position":10,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25583,"position":11,"text_uthmani":"لَّآ","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25584,"position":12,"text_uthmani":"أَسْـَٔلُكُمْ","transliteration":"asalukum","translation_bn":"তোমাদের কাছে চাই আমি","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25585,"position":13,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25586,"position":14,"text_uthmani":"أَجْرًا","transliteration":"ajran","translation_bn":"কোনো পারিশ্রমিক","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25587,"position":15,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":25588,"position":16,"text_uthmani":"ٱلْمَوَدَّةَ","transliteration":"l-mawadata","translation_bn":"ভালোবাসা","root":"ودد","lemma":"مَّوَدَّة","grammar_bn":"শব্দ"},{"id":25589,"position":17,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25590,"position":18,"text_uthmani":"ٱلْقُرْبَىٰ ۗ","transliteration":"l-qur''bā","translation_bn":"আত্মীয়ের\"","root":"قرب","lemma":"قُرْبَىٰ","grammar_bn":"শব্দ"},{"id":25592,"position":19,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25593,"position":20,"text_uthmani":"يَقْتَرِفْ","transliteration":"yaqtarif","translation_bn":"অর্জন করবে","root":"قرف","lemma":"ٱقْتَرَفْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25594,"position":21,"text_uthmani":"حَسَنَةًۭ","transliteration":"ḥasanatan","translation_bn":"ভালো কাজ","root":"حسن","lemma":"حَسَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25595,"position":22,"text_uthmani":"نَّزِدْ","transliteration":"nazid","translation_bn":"বাড়িয়ে দিই আমরা","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25596,"position":23,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":25597,"position":24,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25598,"position":25,"text_uthmani":"حُسْنًا ۚ","transliteration":"ḥus''nan","translation_bn":"কল্যাণ","root":"حسن","lemma":"حُسْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":25600,"position":26,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25601,"position":27,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25602,"position":28,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":25603,"position":29,"text_uthmani":"شَكُورٌ","transliteration":"shakūrun","translation_bn":"গুণগ্রাহী","root":"شكر","lemma":"شَكُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":25604,"position":30,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika alladhī yubashiru l-lahu ʿibādahu alladhīna āmanū waʿamilū l-ṣāliḥāti qul lā asalukum ʿalayhi ajran illā l-mawadata fī l-qur''bā waman yaqtarif ḥasanatan nazid lahu fīhā ḥus''nan inna l-laha ghafūrun shakūrun', 'এটা হল তাই আল্লাহ যার সুসংবাদ দিয়েছেন তাঁর সে সব বান্দাহদের জন্য যারা ঈমান আনে আর সৎ কাজ করে। বল, এ কাজের জন্য আত্মীয়তার ভালবাসা ছাড়া তোমাদের কাছে কিছুই চাই না। যে কেউ উত্তম কাজ করে, আমি তার জন্য তাতে পুণ্য বাড়িয়ে দেই। আল্লাহ বড়ই ক্ষমাশীল, ভাল কাজের বড়ই মর্যাদাদানকারী।', 'It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], "I do not ask you for this message any payment [but] only good will through kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative.', 'এটা হল তাই আল্লাহ যার সুসংবাদ দিয়েছেন তাঁর সে সব বান্দাহদের জন্য যারা ঈমান আনে আর সৎ কাজ করে। বল, এ কাজের জন্য আত্মীয়তার ভালবাসা ছাড়া তোমাদের কাছে কিছুই চাই না। যে কেউ উত্তম কাজ করে, আমি তার জন্য তাতে পুণ্য বাড়িয়ে দেই। আল্লাহ বড়ই ক্ষমাশীল, ভাল কাজের বড়ই মর্যাদাদানকারী।', 'It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], "I do not ask you for this message any payment [but] only good will through kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042023.mp3', now()),
  (42, 24, '', '[{"id":26646,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26647,"position":2,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"(এই লোকেরা) বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26648,"position":3,"text_uthmani":"ٱفْتَرَىٰ","transliteration":"if''tarā","translation_bn":"\"সে রচনা করেছে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26649,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26650,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26651,"position":6,"text_uthmani":"كَذِبًۭا ۖ","transliteration":"kadhiban","translation_bn":"মিথ্যা\"","root":"كذب","lemma":"كَذِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26653,"position":7,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"তবে যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":26654,"position":8,"text_uthmani":"يَشَإِ","transliteration":"yasha-i","translation_bn":"ইচ্ছে করতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26655,"position":9,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26656,"position":10,"text_uthmani":"يَخْتِمْ","transliteration":"yakhtim","translation_bn":"সীল করে দিতেন","root":"ختم","lemma":"خَتَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26657,"position":11,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26658,"position":12,"text_uthmani":"قَلْبِكَ ۗ","transliteration":"qalbika","translation_bn":"তোমার অন্তরের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26660,"position":13,"text_uthmani":"وَيَمْحُ","transliteration":"wayamḥu","translation_bn":"আর মুছে দেন","root":"محو","lemma":"مَحَوْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26661,"position":14,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26662,"position":15,"text_uthmani":"ٱلْبَـٰطِلَ","transliteration":"l-bāṭila","translation_bn":"অসত্যকে","root":"بطل","lemma":"بَٰطِل","grammar_bn":"শব্দ"},{"id":26663,"position":16,"text_uthmani":"وَيُحِقُّ","transliteration":"wayuḥiqqu","translation_bn":"এবং প্রতিষ্ঠিত করেন","root":"حقق","lemma":"يُحِقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26664,"position":17,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":26665,"position":18,"text_uthmani":"بِكَلِمَـٰتِهِۦٓ ۚ","transliteration":"bikalimātihi","translation_bn":"তাঁর বাণী দিয়ে","root":"كلم","lemma":"كَلِمَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":26667,"position":19,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26668,"position":20,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুব অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26669,"position":21,"text_uthmani":"بِذَاتِ","transliteration":"bidhāti","translation_bn":"অবস্থা সম্পর্কে","root":"—","lemma":"ذُو","grammar_bn":"অব্যয় (Preposition)"},{"id":26670,"position":22,"text_uthmani":"ٱلصُّدُورِ","transliteration":"l-ṣudūri","translation_bn":"অন্তরসমূহের","root":"صدر","lemma":"صَدْر","grammar_bn":"শব্দ"},{"id":26671,"position":23,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'am yaqūlūna if''tarā ʿalā l-lahi kadhiban fa-in yasha-i l-lahu yakhtim ʿalā qalbika wayamḥu l-lahu l-bāṭila wayuḥiqqu l-ḥaqa bikalimātihi innahu ʿalīmun bidhāti l-ṣudūri', 'তারা কি বলে যে, এ লোক আল্লাহর নামে মিথ্যা রচনা করেছে? আল্লাহ চাইলে তোমার হৃদয়ে মোহর মেরে দিতেন। বস্তুতঃ তিনি মিথ্যাকে মিটিয়ে দেন এবং নিজ বাক্য দ্বারা সত্যকে প্রতিষ্ঠিত করেন। তিনি (সকলের) অন্তরে নিহিত বিষয় সম্পর্কে খুবই অবগত।', 'Or do they say, "He has invented about Allah a lie"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.', 'তারা কি বলে যে, এ লোক আল্লাহর নামে মিথ্যা রচনা করেছে? আল্লাহ চাইলে তোমার হৃদয়ে মোহর মেরে দিতেন। বস্তুতঃ তিনি মিথ্যাকে মিটিয়ে দেন এবং নিজ বাক্য দ্বারা সত্যকে প্রতিষ্ঠিত করেন। তিনি (সকলের) অন্তরে নিহিত বিষয় সম্পর্কে খুবই অবগত।', 'Or do they say, "He has invented about Allah a lie"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042024.mp3', now()),
  (42, 25, '', '[{"id":27679,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই (আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27680,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27681,"position":3,"text_uthmani":"يَقْبَلُ","transliteration":"yaqbalu","translation_bn":"কবুল করেন","root":"قبل","lemma":"يَقْبَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27682,"position":4,"text_uthmani":"ٱلتَّوْبَةَ","transliteration":"l-tawbata","translation_bn":"তওবা","root":"توب","lemma":"تَوْبَة","grammar_bn":"শব্দ"},{"id":27683,"position":5,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27684,"position":6,"text_uthmani":"عِبَادِهِۦ","transliteration":"ʿibādihi","translation_bn":"তাঁর দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":27685,"position":7,"text_uthmani":"وَيَعْفُوا۟","transliteration":"wayaʿfū","translation_bn":"এবং মোচন করেন","root":"عفو","lemma":"عَفَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27686,"position":8,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27687,"position":9,"text_uthmani":"ٱلسَّيِّـَٔاتِ","transliteration":"l-sayiāti","translation_bn":"পাপসমূহ","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":27688,"position":10,"text_uthmani":"وَيَعْلَمُ","transliteration":"wayaʿlamu","translation_bn":"অথচ তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27689,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27690,"position":12,"text_uthmani":"تَفْعَلُونَ","transliteration":"tafʿalūna","translation_bn":"তোমরা করছো","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27691,"position":13,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī yaqbalu l-tawbata ʿan ʿibādihi wayaʿfū ʿani l-sayiāti wayaʿlamu mā tafʿalūna', 'তিনি তাঁর বান্দাহদের তাওবাহ ক্ববূল করেন, পাপ ক্ষমা করেন আর তিনি জানেন তোমরা যা কর।', 'And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.', 'তিনি তাঁর বান্দাহদের তাওবাহ ক্ববূল করেন, পাপ ক্ষমা করেন আর তিনি জানেন তোমরা যা কর।', 'And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042025.mp3', now()),
  (42, 26, '', '[{"id":28647,"position":1,"text_uthmani":"وَيَسْتَجِيبُ","transliteration":"wayastajību","translation_bn":"এবং তিনি ডাকে সাড়া দেন","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28648,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28649,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28650,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28651,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":28652,"position":6,"text_uthmani":"وَيَزِيدُهُم","transliteration":"wayazīduhum","translation_bn":"এবং বৃদ্ধি করেন তাদেরকে","root":"زيد","lemma":"زَادَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28653,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28654,"position":8,"text_uthmani":"فَضْلِهِۦ ۚ","transliteration":"faḍlihi","translation_bn":"তাঁর অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":28656,"position":9,"text_uthmani":"وَٱلْكَـٰفِرُونَ","transliteration":"wal-kāfirūna","translation_bn":"এবং কাফেরদের (অবস্থা হলো)","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28657,"position":10,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে রয়েছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":28658,"position":11,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":28659,"position":12,"text_uthmani":"شَدِيدٌۭ","transliteration":"shadīdun","translation_bn":"কঠিন","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":28660,"position":13,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'wayastajību alladhīna āmanū waʿamilū l-ṣāliḥāti wayazīduhum min faḍlihi wal-kāfirūna lahum ʿadhābun shadīdun', 'যারা ঈমান আনে আর সৎকর্ম করে তিনি তাদের আহবান শুনেন, আর তিনি তাদের প্রতি নিজ অনুগ্রহ বাড়িয়ে দেন আর কাফিরদের জন্য আছে কঠিন শাস্তি।', 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.', 'যারা ঈমান আনে আর সৎকর্ম করে তিনি তাদের আহবান শুনেন, আর তিনি তাদের প্রতি নিজ অনুগ্রহ বাড়িয়ে দেন আর কাফিরদের জন্য আছে কঠিন শাস্তি।', 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042026.mp3', now()),
  (42, 27, '', '[{"id":29540,"position":1,"text_uthmani":"۞ وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29541,"position":2,"text_uthmani":"بَسَطَ","transliteration":"basaṭa","translation_bn":"প্রচুর দিতেন","root":"بسط","lemma":"بَسَطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29542,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29543,"position":4,"text_uthmani":"ٱلرِّزْقَ","transliteration":"l-riz''qa","translation_bn":"জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"শব্দ"},{"id":29544,"position":5,"text_uthmani":"لِعِبَادِهِۦ","transliteration":"liʿibādihi","translation_bn":"তাঁর দাসদের জন্যে","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":29545,"position":6,"text_uthmani":"لَبَغَوْا۟","transliteration":"labaghaw","translation_bn":"তারা অবশ্যই বিপর্যয় সৃষ্টি করতো","root":"بغي","lemma":"بَغَىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":29546,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29547,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":29548,"position":9,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29549,"position":10,"text_uthmani":"يُنَزِّلُ","transliteration":"yunazzilu","translation_bn":"দেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29550,"position":11,"text_uthmani":"بِقَدَرٍۢ","transliteration":"biqadarin","translation_bn":"একটি পরিমাণ মত","root":"قدر","lemma":"قَدَر","grammar_bn":"অব্যয় (Preposition)"},{"id":29551,"position":12,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29552,"position":13,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29554,"position":14,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29555,"position":15,"text_uthmani":"بِعِبَادِهِۦ","transliteration":"biʿibādihi","translation_bn":"তাঁর দাসদের সম্পর্কে","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":29556,"position":16,"text_uthmani":"خَبِيرٌۢ","transliteration":"khabīrun","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":29557,"position":17,"text_uthmani":"بَصِيرٌۭ","transliteration":"baṣīrun","translation_bn":"সবকিছুই দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":29558,"position":18,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaw basaṭa l-lahu l-riz''qa liʿibādihi labaghaw fī l-arḍi walākin yunazzilu biqadarin mā yashāu innahu biʿibādihi khabīrun baṣīrun', 'আল্লাহ যদি তাঁর সকল বান্দাহদের জন্য রিযক পর্যাপ্ত করে দিতেন, তাহলে তারা অবশ্যই যমীনে বিদ্রোহ সৃষ্টি করত; কিন্তু তিনি একটা নির্দিষ্ট পরিমাণে যতটুকু ইচ্ছে নাযিল করেন। তিনি তাঁর বান্দাহ্দের সম্পর্কে পূর্ণ ওয়াকিফহাল, তিনি তাদের প্রতি সর্বদা দৃষ্টি রাখেন।', 'And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing.', 'আল্লাহ যদি তাঁর সকল বান্দাহদের জন্য রিযক পর্যাপ্ত করে দিতেন, তাহলে তারা অবশ্যই যমীনে বিদ্রোহ সৃষ্টি করত; কিন্তু তিনি একটা নির্দিষ্ট পরিমাণে যতটুকু ইচ্ছে নাযিল করেন। তিনি তাঁর বান্দাহ্দের সম্পর্কে পূর্ণ ওয়াকিফহাল, তিনি তাদের প্রতি সর্বদা দৃষ্টি রাখেন।', 'And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042027.mp3', now()),
  (42, 28, '', '[{"id":30874,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই(আল্লাহ)","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30875,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30876,"position":3,"text_uthmani":"يُنَزِّلُ","transliteration":"yunazzilu","translation_bn":"বর্ষণ করেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30877,"position":4,"text_uthmani":"ٱلْغَيْثَ","transliteration":"l-ghaytha","translation_bn":"বৃষ্টি","root":"غيث","lemma":"غَيْث","grammar_bn":"শব্দ"},{"id":30878,"position":5,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30879,"position":6,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":30880,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যখন","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":30881,"position":8,"text_uthmani":"قَنَطُوا۟","transliteration":"qanaṭū","translation_bn":"তারা নিরাশ হয়","root":"قنط","lemma":"قَنَطُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30882,"position":9,"text_uthmani":"وَيَنشُرُ","transliteration":"wayanshuru","translation_bn":"এবং বিস্তার করেন","root":"نشر","lemma":"نُشِرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30883,"position":10,"text_uthmani":"رَحْمَتَهُۥ ۚ","transliteration":"raḥmatahu","translation_bn":"তাঁর করুণা","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":30885,"position":11,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30886,"position":12,"text_uthmani":"ٱلْوَلِىُّ","transliteration":"l-waliyu","translation_bn":"অভিভাবক (ওলী)","root":"ولي","lemma":"وَلِىّ","grammar_bn":"শব্দ"},{"id":30887,"position":13,"text_uthmani":"ٱلْحَمِيدُ","transliteration":"l-ḥamīdu","translation_bn":"প্রশংসিত","root":"حمد","lemma":"حَمِيد","grammar_bn":"শব্দ"},{"id":30888,"position":14,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī yunazzilu l-ghaytha min baʿdi mā qanaṭū wayanshuru raḥmatahu wahuwa l-waliyu l-ḥamīdu', 'মানুষ নিরাশ হয়ে যাওয়ার পর তিনিই বৃষ্টি বর্ষণ করেন, আর স্বীয় রহমত ছড়িয়ে দেন, তিনি-ই সকল গুণে প্রশংসিত প্রকৃত অভিভাবক।', 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.', 'মানুষ নিরাশ হয়ে যাওয়ার পর তিনিই বৃষ্টি বর্ষণ করেন, আর স্বীয় রহমত ছড়িয়ে দেন, তিনি-ই সকল গুণে প্রশংসিত প্রকৃত অভিভাবক।', 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042028.mp3', now()),
  (42, 29, '', '[{"id":31549,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্য হ''তে (রয়েছে)","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31550,"position":2,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"তাঁর নিদর্শনাবলীর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31551,"position":3,"text_uthmani":"خَلْقُ","transliteration":"khalqu","translation_bn":"সৃষ্টি","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":31552,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":31553,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31554,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31555,"position":7,"text_uthmani":"بَثَّ","transliteration":"batha","translation_bn":"ছড়িয়ে দিয়েছেন","root":"بثث","lemma":"بَثَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31556,"position":8,"text_uthmani":"فِيهِمَا","transliteration":"fīhimā","translation_bn":"তার উভয়ের মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31557,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"(বিভিন্ন) ধরণের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31558,"position":10,"text_uthmani":"دَآبَّةٍۢ ۚ","transliteration":"dābbatin","translation_bn":"জীবজন্তু","root":"دبب","lemma":"دَا^بَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31560,"position":11,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31561,"position":12,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31562,"position":13,"text_uthmani":"جَمْعِهِمْ","transliteration":"jamʿihim","translation_bn":"তাদের একত্রিত করার","root":"جمع","lemma":"جَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":31563,"position":14,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":31564,"position":15,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করবেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31565,"position":16,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সক্ষম","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":31566,"position":17,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi khalqu l-samāwāti wal-arḍi wamā batha fīhimā min dābbatin wahuwa ʿalā jamʿihim idhā yashāu qadīrun', 'তাঁর নিদর্শনসমূহের অন্তর্গত হল আসমান ও যমীনের সৃষ্টি, আর এ দু’য়ের ভিতর যে প্রাণীকুল ছড়িয়ে দিয়েছেন তিনি। আর যখন ইচ্ছে তিনি তাদেরকে একত্রিত করতে সক্ষম।', 'And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.', 'তাঁর নিদর্শনসমূহের অন্তর্গত হল আসমান ও যমীনের সৃষ্টি, আর এ দু’য়ের ভিতর যে প্রাণীকুল ছড়িয়ে দিয়েছেন তিনি। আর যখন ইচ্ছে তিনি তাদেরকে একত্রিত করতে সক্ষম।', 'And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042029.mp3', now()),
  (42, 30, '', '[{"id":32475,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32476,"position":2,"text_uthmani":"أَصَـٰبَكُم","transliteration":"aṣābakum","translation_bn":"তোমাদের পৌঁছে","root":"صوب","lemma":"أَصَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32477,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32478,"position":4,"text_uthmani":"مُّصِيبَةٍۢ","transliteration":"muṣībatin","translation_bn":"বিপদ","root":"صوب","lemma":"مُّصِيبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":32479,"position":5,"text_uthmani":"فَبِمَا","transliteration":"fabimā","translation_bn":"তা এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":32480,"position":6,"text_uthmani":"كَسَبَتْ","transliteration":"kasabat","translation_bn":"কামাই করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32481,"position":7,"text_uthmani":"أَيْدِيكُمْ","transliteration":"aydīkum","translation_bn":"তোমাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":32482,"position":8,"text_uthmani":"وَيَعْفُوا۟","transliteration":"wayaʿfū","translation_bn":"এবং তিনি ক্ষমা করেন","root":"عفو","lemma":"عَفَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32483,"position":9,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32484,"position":10,"text_uthmani":"كَثِيرٍۢ","transliteration":"kathīrin","translation_bn":"অনেককিছু (নিজের থেকে)","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":32485,"position":11,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā aṣābakum min muṣībatin fabimā kasabat aydīkum wayaʿfū ʿan kathīrin', 'তোমাদের উপর যে বিপদই উপনীত হয় তা তোমাদের হাতের উপার্জনের কারণেই, তিনি অনেক অপরাধই ক্ষমা করে দেন।', 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.', 'তোমাদের উপর যে বিপদই উপনীত হয় তা তোমাদের হাতের উপার্জনের কারণেই, তিনি অনেক অপরাধই ক্ষমা করে দেন।', 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042030.mp3', now()),
  (42, 31, '', '[{"id":33323,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং নও","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33324,"position":2,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":33325,"position":3,"text_uthmani":"بِمُعْجِزِينَ","transliteration":"bimuʿ''jizīna","translation_bn":"অক্ষমকারী (আল্লাহকে)","root":"عجز","lemma":"مُعْجِز","grammar_bn":"অব্যয় (Preposition)"},{"id":33326,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33327,"position":5,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":33329,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর নেই (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33330,"position":7,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":33331,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33332,"position":9,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":33333,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":33334,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33335,"position":12,"text_uthmani":"وَلِىٍّۢ","transliteration":"waliyyin","translation_bn":"অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":33336,"position":13,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর নেই","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33337,"position":14,"text_uthmani":"نَصِيرٍۢ","transliteration":"naṣīrin","translation_bn":"কোন সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":33338,"position":15,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'wamā antum bimuʿ''jizīna fī l-arḍi wamā lakum min dūni l-lahi min waliyyin walā naṣīrin', 'তোমরা যমীনে (আল্লাহর কর্ম ও পরিকল্পনাকে) ভন্ডুল (অক্ষম) করতে পারবে না। আল্লাহ ছাড়া তোমাদের না আছে কোন অভিভাবক, আর না আছে সাহায্যকারী।', 'And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper.', 'তোমরা যমীনে (আল্লাহর কর্ম ও পরিকল্পনাকে) ভন্ডুল (অক্ষম) করতে পারবে না। আল্লাহ ছাড়া তোমাদের না আছে কোন অভিভাবক, আর না আছে সাহায্যকারী।', 'And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042031.mp3', now()),
  (42, 32, '', '[{"id":34647,"position":1,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"এবং মধ্যে রয়েছে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34648,"position":2,"text_uthmani":"ءَايَـٰتِهِ","transliteration":"āyātihi","translation_bn":"তাঁর নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":34649,"position":3,"text_uthmani":"ٱلْجَوَارِ","transliteration":"l-jawāri","translation_bn":"নৌযানসমূহ","root":"جري","lemma":"جَوَار","grammar_bn":"শব্দ"},{"id":34650,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34651,"position":5,"text_uthmani":"ٱلْبَحْرِ","transliteration":"l-baḥri","translation_bn":"সাগরের","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":34652,"position":6,"text_uthmani":"كَٱلْأَعْلَـٰمِ","transliteration":"kal-aʿlāmi","translation_bn":"পাহাড়ের মতো","root":"علم","lemma":"أَعْلَٰم","grammar_bn":"অব্যয় (Preposition)"},{"id":34653,"position":7,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamin āyātihi l-jawāri fī l-baḥri kal-aʿlāmi', 'তাঁর নিদর্শনসমূহের মধ্যে হল সমুদ্রে নির্বিঘ্নে চলমান জাহাজ- পাহাড়ের মত।', 'And of His signs are the ships in the sea, like mountains.', 'তাঁর নিদর্শনসমূহের মধ্যে হল সমুদ্রে নির্বিঘ্নে চলমান জাহাজ- পাহাড়ের মত।', 'And of His signs are the ships in the sea, like mountains.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042032.mp3', now()),
  (42, 33, '', '[{"id":35258,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":35259,"position":2,"text_uthmani":"يَشَأْ","transliteration":"yasha","translation_bn":"ইচ্ছে করেন তিনি","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35260,"position":3,"text_uthmani":"يُسْكِنِ","transliteration":"yus''kini","translation_bn":"(থামিয়ে দিবেন) ধরে রাখবেন","root":"سكن","lemma":"أَسْكَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":35261,"position":4,"text_uthmani":"ٱلرِّيحَ","transliteration":"l-rīḥa","translation_bn":"বাতাসকে","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":35262,"position":5,"text_uthmani":"فَيَظْلَلْنَ","transliteration":"fayaẓlalna","translation_bn":"ফলে তা হয়ে যাবে","root":"ظلل","lemma":"ظَلَّ","grammar_bn":"শব্দ"},{"id":35263,"position":6,"text_uthmani":"رَوَاكِدَ","transliteration":"rawākida","translation_bn":"নিশ্চল","root":"ركد","lemma":"رَوَاكِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":35264,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35265,"position":8,"text_uthmani":"ظَهْرِهِۦٓ ۚ","transliteration":"ẓahrihi","translation_bn":"তার উপরিভাগের","root":"ظهر","lemma":"ظَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":35267,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":35268,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে রয়েছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35269,"position":11,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":35270,"position":12,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":35271,"position":13,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"জন্যে প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":35272,"position":14,"text_uthmani":"صَبَّارٍۢ","transliteration":"ṣabbārin","translation_bn":"পূর্ণ ধৈর্য্যশীলের","root":"صبر","lemma":"صَبَّار","grammar_bn":"বিশেষণ (Adjective)"},{"id":35273,"position":15,"text_uthmani":"شَكُورٍ","transliteration":"shakūrin","translation_bn":"কৃতজ্ঞতা প্রকাশকারীর","root":"شكر","lemma":"شَكُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":35274,"position":16,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'in yasha yus''kini l-rīḥa fayaẓlalna rawākida ʿalā ẓahrihi inna fī dhālika laāyātin likulli ṣabbārin shakūrin', 'তিনি যদি ইচ্ছে করেন বাতাসকে থামিয়ে দিতে পারেন, তখন জাহাজগুলো সমুদ্র পৃষ্ঠে গতিহীন হয়ে পড়বে। এতে প্রত্যেক অতি ধৈর্যশীল শুকর আদায়কারীর জন্য অবশ্যই নিদর্শন রয়েছে।', 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.', 'তিনি যদি ইচ্ছে করেন বাতাসকে থামিয়ে দিতে পারেন, তখন জাহাজগুলো সমুদ্র পৃষ্ঠে গতিহীন হয়ে পড়বে। এতে প্রত্যেক অতি ধৈর্যশীল শুকর আদায়কারীর জন্য অবশ্যই নিদর্শন রয়েছে।', 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042033.mp3', now()),
  (42, 34, '', '[{"id":36150,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36151,"position":2,"text_uthmani":"يُوبِقْهُنَّ","transliteration":"yūbiq''hunna","translation_bn":"সেগুলো (ডুবিয়ে দিতে) ধ্বংস করতে পারেন","root":"وبق","lemma":"يُوبِقْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36152,"position":3,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36153,"position":4,"text_uthmani":"كَسَبُوا۟","transliteration":"kasabū","translation_bn":"তারা কামাই করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36154,"position":5,"text_uthmani":"وَيَعْفُ","transliteration":"wayaʿfu","translation_bn":"এ অবস্থায় যখন মাফ করেও দেন","root":"عفو","lemma":"عَفَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36155,"position":6,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36156,"position":7,"text_uthmani":"كَثِيرٍۢ","transliteration":"kathīrin","translation_bn":"অনেক কিছু","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":36157,"position":8,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'aw yūbiq''hunna bimā kasabū wayaʿfu ʿan kathīrin', 'কিংবা তিনি ওগুলোকে ধ্বংস করে দিতে পারেন তাদের উপার্জিত পাপের কারণে, আর প্রকৃতপক্ষে তিনি তো (তাদের) অনেক দোষ-ত্রুটিই ক্ষমা করে দেন।', 'Or He could destroy them for what they earned; but He pardons much.', 'কিংবা তিনি ওগুলোকে ধ্বংস করে দিতে পারেন তাদের উপার্জিত পাপের কারণে, আর প্রকৃতপক্ষে তিনি তো (তাদের) অনেক দোষ-ত্রুটিই ক্ষমা করে দেন।', 'Or He could destroy them for what they earned; but He pardons much.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042034.mp3', now()),
  (42, 35, '', '[{"id":36945,"position":1,"text_uthmani":"وَيَعْلَمَ","transliteration":"wayaʿlama","translation_bn":"এবং (তখন) জানতে পারবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36946,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":36947,"position":3,"text_uthmani":"يُجَـٰدِلُونَ","transliteration":"yujādilūna","translation_bn":"বিতর্ক করে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36948,"position":4,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"সম্পর্কে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36949,"position":5,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"আমাদের নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":36950,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":36951,"position":7,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":36952,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36953,"position":9,"text_uthmani":"مَّحِيصٍۢ","transliteration":"maḥīṣin","translation_bn":"আশ্রয়স্থল","root":"حيص","lemma":"مَّحِيص","grammar_bn":"বিশেষ্য (Noun)"},{"id":36954,"position":10,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'wayaʿlama alladhīna yujādilūna fī āyātinā mā lahum min maḥīṣin', '(আর ওগুলোকে ধ্বংস করা হয়) এজন্যও যে, আমার আয়াত নিয়ে যারা বিতর্ক করে তারা যেন জেনে নেয় যে, তাদের (আল্লাহর কাছ থেকে পালিয়ে অন্যত্র আশ্রয় নেয়ার জন্য) কোন আশ্রয়স্থল নেই।', 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.', '(আর ওগুলোকে ধ্বংস করা হয়) এজন্যও যে, আমার আয়াত নিয়ে যারা বিতর্ক করে তারা যেন জেনে নেয় যে, তাদের (আল্লাহর কাছ থেকে পালিয়ে অন্যত্র আশ্রয় নেয়ার জন্য) কোন আশ্রয়স্থল নেই।', 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042035.mp3', now()),
  (42, 36, '', '[{"id":38002,"position":1,"text_uthmani":"فَمَآ","transliteration":"famā","translation_bn":"বস্তুতঃ যা","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":38003,"position":2,"text_uthmani":"أُوتِيتُم","transliteration":"ūtītum","translation_bn":"তোমাদের দেওয়া হয়েছে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":38004,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38005,"position":4,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":38006,"position":5,"text_uthmani":"فَمَتَـٰعُ","transliteration":"famatāʿu","translation_bn":"তা ভোগসামগ্রী","root":"متع","lemma":"مَتَٰع","grammar_bn":"শব্দ"},{"id":38007,"position":6,"text_uthmani":"ٱلْحَيَوٰةِ","transliteration":"l-ḥayati","translation_bn":"জীবনের","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":38008,"position":7,"text_uthmani":"ٱلدُّنْيَا ۖ","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":38010,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছূ","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38011,"position":9,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে আছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":38012,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":38013,"position":11,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"(তাই) উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":38014,"position":12,"text_uthmani":"وَأَبْقَىٰ","transliteration":"wa-abqā","translation_bn":"এবং অধিক স্থায়ী","root":"بقي","lemma":"أَبْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38015,"position":13,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":38016,"position":14,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38017,"position":15,"text_uthmani":"وَعَلَىٰ","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38018,"position":16,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":38019,"position":17,"text_uthmani":"يَتَوَكَّلُونَ","transliteration":"yatawakkalūna","translation_bn":"তারা নির্ভর করে","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38020,"position":18,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'famā ūtītum min shayin famatāʿu l-ḥayati l-dun''yā wamā ʿinda l-lahi khayrun wa-abqā lilladhīna āmanū waʿalā rabbihim yatawakkalūna', '(এখানে) তোমাদেরকে যা কিছু দেয়া হয়েছে তা অস্থায়ী দুনিয়ার জীবনের (সামান্য) ভোগ্যবস্তু মাত্র। আল্লাহর নিকট যা আছে তা উৎকৃষ্ট এবং স্থায়ী (আর তা হল) তাদের জন্য যারা ঈমান আনে এবং তাদের প্রতিপালকের উপর নির্ভর করে।', 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely', '(এখানে) তোমাদেরকে যা কিছু দেয়া হয়েছে তা অস্থায়ী দুনিয়ার জীবনের (সামান্য) ভোগ্যবস্তু মাত্র। আল্লাহর নিকট যা আছে তা উৎকৃষ্ট এবং স্থায়ী (আর তা হল) তাদের জন্য যারা ঈমান আনে এবং তাদের প্রতিপালকের উপর নির্ভর করে।', 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/042036.mp3', now()),
