  (43, 2, '', '[{"id":974,"position":1,"text_uthmani":"وَٱلْكِتَـٰبِ","transliteration":"wal-kitābi","translation_bn":"শপথ (এই) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"অব্যয় (Preposition)"},{"id":975,"position":2,"text_uthmani":"ٱلْمُبِينِ","transliteration":"l-mubīni","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":976,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-kitābi l-mubīni', 'শপথ সুস্পষ্ট কিতাবের।', 'By the clear Book,', 'শপথ সুস্পষ্ট কিতাবের।', 'By the clear Book,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043002.mp3', now()),
  (43, 3, '', '[{"id":2076,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2077,"position":2,"text_uthmani":"جَعَلْنَـٰهُ","transliteration":"jaʿalnāhu","translation_bn":"তা আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2078,"position":3,"text_uthmani":"قُرْءَٰنًا","transliteration":"qur''ānan","translation_bn":"(অর্থাৎ) কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2079,"position":4,"text_uthmani":"عَرَبِيًّۭا","transliteration":"ʿarabiyyan","translation_bn":"আরবী (ভাষায়)","root":"عرب","lemma":"عَرَبِيّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":2080,"position":5,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"তোমরা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2081,"position":6,"text_uthmani":"تَعْقِلُونَ","transliteration":"taʿqilūna","translation_bn":"বুঝতে পারো","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2082,"position":7,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'innā jaʿalnāhu qur''ānan ʿarabiyyan laʿallakum taʿqilūna', 'আমি ওটাকে করেছি আরবী ভাষার কুরআন যাতে তোমরা বুঝতে পারে।', 'Indeed, We have made it an Arabic Qur''an that you might understand.', 'আমি ওটাকে করেছি আরবী ভাষার কুরআন যাতে তোমরা বুঝতে পারে।', 'Indeed, We have made it an Arabic Qur''an that you might understand.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043003.mp3', now()),
  (43, 4, '', '[{"id":3343,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"এবং তা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3344,"position":2,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3345,"position":3,"text_uthmani":"أُمِّ","transliteration":"ummi","translation_bn":"মূল","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3346,"position":4,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":3347,"position":5,"text_uthmani":"لَدَيْنَا","transliteration":"ladaynā","translation_bn":"আমাদের কাছে","root":"—","lemma":"لَدَي\r","grammar_bn":"স্থানবাচক (Location)"},{"id":3348,"position":6,"text_uthmani":"لَعَلِىٌّ","transliteration":"laʿaliyyun","translation_bn":"অতীব উচ্চ মর্যাদার","root":"علو","lemma":"عَلِيّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3349,"position":7,"text_uthmani":"حَكِيمٌ","transliteration":"ḥakīmun","translation_bn":"অবশ্যই মহান","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":3350,"position":8,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu fī ummi l-kitābi ladaynā laʿaliyyun ḥakīmun', 'আমার কাছে তা উম্মুল কিতাবে (লাওহে মাহফুজে) সংরক্ষিত আছে, আর তা হল অতি উচ্চ মর্যাদাসম্পন্ন জ্ঞান-বিজ্ঞানে পূর্ণ।', 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.', 'আমার কাছে তা উম্মুল কিতাবে (লাওহে মাহফুজে) সংরক্ষিত আছে, আর তা হল অতি উচ্চ মর্যাদাসম্পন্ন জ্ঞান-বিজ্ঞানে পূর্ণ।', 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043004.mp3', now()),
  (43, 5, '', '[{"id":4710,"position":1,"text_uthmani":"أَفَنَضْرِبُ","transliteration":"afanaḍribu","translation_bn":"তবে কি আমরা করবো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":4711,"position":2,"text_uthmani":"عَنكُمُ","transliteration":"ʿankumu","translation_bn":"তোমাদের থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4712,"position":3,"text_uthmani":"ٱلذِّكْرَ","transliteration":"l-dhik''ra","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":4713,"position":4,"text_uthmani":"صَفْحًا","transliteration":"ṣafḥan","translation_bn":"প্রত্যাহার","root":"صفح","lemma":"صَفْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":4714,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এ জন্যে) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":4715,"position":6,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হ''লে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4716,"position":7,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4717,"position":8,"text_uthmani":"مُّسْرِفِينَ","transliteration":"mus''rifīna","translation_bn":"অসংযমী","root":"سرف","lemma":"مُسْرِف","grammar_bn":"বিশেষণ (Adjective)"},{"id":4718,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'afanaḍribu ʿankumu l-dhik''ra ṣafḥan an kuntum qawman mus''rifīna', 'তোমরা এক সীমালঙ্ঘনকারী জাতি- এ কারণে কি আমি তোমাদের কাছ থেকে কুরআন প্রত্যাহার করে নেব?', 'Then should We turn the message away, disregarding you, because you are a transgressing people?', 'তোমরা এক সীমালঙ্ঘনকারী জাতি- এ কারণে কি আমি তোমাদের কাছ থেকে কুরআন প্রত্যাহার করে নেব?', 'Then should We turn the message away, disregarding you, because you are a transgressing people?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043005.mp3', now()),
  (43, 6, '', '[{"id":5980,"position":1,"text_uthmani":"وَكَمْ","transliteration":"wakam","translation_bn":"এবং কত (বার)","root":"—","lemma":"كَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5981,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5982,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5983,"position":4,"text_uthmani":"نَّبِىٍّۢ","transliteration":"nabiyyin","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5984,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5985,"position":6,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্ববর্তীদের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":5986,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wakam arsalnā min nabiyyin fī l-awalīna', 'পূর্বেকার জাতিগুলোর মধ্যে আমি বহু রসূল পাঠিয়েছিলাম।', 'And how many a prophet We sent among the former peoples,', 'পূর্বেকার জাতিগুলোর মধ্যে আমি বহু রসূল পাঠিয়েছিলাম।', 'And how many a prophet We sent among the former peoples,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043006.mp3', now()),
  (43, 7, '', '[{"id":7292,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7293,"position":2,"text_uthmani":"يَأْتِيهِم","transliteration":"yatīhim","translation_bn":"তাদের কাছে এসেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":7294,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"(এমন) কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7295,"position":4,"text_uthmani":"نَّبِىٍّ","transliteration":"nabiyyin","translation_bn":"নাবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7296,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":7297,"position":6,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7298,"position":7,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তার সাথে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":7299,"position":8,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"ঠাট্টা-বিদ্রুপ করতো","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7300,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yatīhim min nabiyyin illā kānū bihi yastahziūna', 'তাদের কাছে এমন কোন নবী আসেনি যাকে তারা ঠাট্টা-বিদ্রূপ করেনি।', 'But there would not come to them a prophet except that they used to ridicule him.', 'তাদের কাছে এমন কোন নবী আসেনি যাকে তারা ঠাট্টা-বিদ্রূপ করেনি।', 'But there would not come to them a prophet except that they used to ridicule him.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043007.mp3', now()),
  (43, 8, '', '[{"id":8563,"position":1,"text_uthmani":"فَأَهْلَكْنَآ","transliteration":"fa-ahlaknā","translation_bn":"আমরা তাই ধ্বংস করে দিয়েছি","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"শব্দ"},{"id":8564,"position":2,"text_uthmani":"أَشَدَّ","transliteration":"ashadda","translation_bn":"(যারা ছিলো) প্রবল","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8565,"position":3,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"তাদের মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8566,"position":4,"text_uthmani":"بَطْشًۭا","transliteration":"baṭshan","translation_bn":"শক্তিতে","root":"بطش","lemma":"بَطْش","grammar_bn":"বিশেষ্য (Noun)"},{"id":8567,"position":5,"text_uthmani":"وَمَضَىٰ","transliteration":"wamaḍā","translation_bn":"এবং অতীত হয়েছে","root":"مضي","lemma":"مَضَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8568,"position":6,"text_uthmani":"مَثَلُ","transliteration":"mathalu","translation_bn":"অনুরূপ দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":8569,"position":7,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্ববর্তীদের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":8570,"position":8,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ahlaknā ashadda min''hum baṭshan wamaḍā mathalu l-awalīna', 'আমি তাদেরকে ধ্বংস করেছি- যারা ছিল এদের চেয়ে অনেক বেশি শক্তিশালী। পূর্বের জাতিগুলোর উদাহরণ অতীত হয়ে গেছে।', 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.', 'আমি তাদেরকে ধ্বংস করেছি- যারা ছিল এদের চেয়ে অনেক বেশি শক্তিশালী। পূর্বের জাতিগুলোর উদাহরণ অতীত হয়ে গেছে।', 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043008.mp3', now()),
  (43, 9, '', '[{"id":9771,"position":1,"text_uthmani":"وَلَئِن","transliteration":"wala-in","translation_bn":"এবং অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9772,"position":2,"text_uthmani":"سَأَلْتَهُم","transliteration":"sa-altahum","translation_bn":"তাদের তুমি প্রশ্ন করো","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9773,"position":3,"text_uthmani":"مَّنْ","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9774,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9775,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":9776,"position":6,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে\"","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9777,"position":7,"text_uthmani":"لَيَقُولُنَّ","transliteration":"layaqūlunna","translation_bn":"তারা বলবে অবশ্যই","root":"قول","lemma":"قَالَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9778,"position":8,"text_uthmani":"خَلَقَهُنَّ","transliteration":"khalaqahunna","translation_bn":"\"তাদের সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9779,"position":9,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":9780,"position":10,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"মহাজ্ঞানী (আল্লাহ)\"","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":9781,"position":11,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wala-in sa-altahum man khalaqa l-samāwāti wal-arḍa layaqūlunna khalaqahunna l-ʿazīzu l-ʿalīmu', 'তুমি যদি তাদেরকে জিজ্ঞেস কর- আকাশ ও যমীন কে সৃষ্টি করেছে? তারা অবশ্য অবশ্যই বলবে- ওগুলো প্রবল পরাক্রমশালী মহাজ্ঞানী আল্লাহ সৃষ্টি করেছেন,', 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing."', 'তুমি যদি তাদেরকে জিজ্ঞেস কর- আকাশ ও যমীন কে সৃষ্টি করেছে? তারা অবশ্য অবশ্যই বলবে- ওগুলো প্রবল পরাক্রমশালী মহাজ্ঞানী আল্লাহ সৃষ্টি করেছেন,', 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043009.mp3', now()),
  (43, 10, '', '[{"id":10903,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10904,"position":2,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10905,"position":3,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":10906,"position":4,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"জমিকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":10907,"position":5,"text_uthmani":"مَهْدًۭا","transliteration":"mahdan","translation_bn":"শয্যা (আশ্রয়স্থল)","root":"مهد","lemma":"مَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10908,"position":6,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং করে দিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10909,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":10910,"position":8,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10911,"position":9,"text_uthmani":"سُبُلًۭا","transliteration":"subulan","translation_bn":"পথসমূহ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10912,"position":10,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"তোমরা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10913,"position":11,"text_uthmani":"تَهْتَدُونَ","transliteration":"tahtadūna","translation_bn":"(গন্তব্যস্থলের) পথ পেতে পারো","root":"هدي","lemma":"ٱهْتَدَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10914,"position":12,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī jaʿala lakumu l-arḍa mahdan wajaʿala lakum fīhā subulan laʿallakum tahtadūna', 'যিনি তোমাদের জন্য যমীনকে করেছেন বিস্তৃত, আর তাতে তোমাদের জন্য বানিয়েছেন চলার পথ- যাতে তোমরা সঠিক পথ পেতে পার।', '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided', 'যিনি তোমাদের জন্য যমীনকে করেছেন বিস্তৃত, আর তাতে তোমাদের জন্য বানিয়েছেন চলার পথ- যাতে তোমরা সঠিক পথ পেতে পার।', '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043010.mp3', now()),
  (43, 11, '', '[{"id":12233,"position":1,"text_uthmani":"وَٱلَّذِى","transliteration":"wa-alladhī","translation_bn":"এবং যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12234,"position":2,"text_uthmani":"نَزَّلَ","transliteration":"nazzala","translation_bn":"বর্ষণ করেছেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12235,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12236,"position":4,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12237,"position":5,"text_uthmani":"مَآءًۢ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12238,"position":6,"text_uthmani":"بِقَدَرٍۢ","transliteration":"biqadarin","translation_bn":"পরিমিতভাবে","root":"قدر","lemma":"قَدَر","grammar_bn":"অব্যয় (Preposition)"},{"id":12239,"position":7,"text_uthmani":"فَأَنشَرْنَا","transliteration":"fa-ansharnā","translation_bn":"আমরা অতঃপর জীবিত করি","root":"نشر","lemma":"أَنشَرَ","grammar_bn":"শব্দ"},{"id":12240,"position":8,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তা দিয়ে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":12241,"position":9,"text_uthmani":"بَلْدَةًۭ","transliteration":"baldatan","translation_bn":"ভূমিকে","root":"بلد","lemma":"بَلْدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12242,"position":10,"text_uthmani":"مَّيْتًۭا ۚ","transliteration":"maytan","translation_bn":"মৃত (নিষ্প্রাণ)","root":"موت","lemma":"مَّيْت","grammar_bn":"বিশেষণ (Adjective)"},{"id":12244,"position":11,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":12245,"position":12,"text_uthmani":"تُخْرَجُونَ","transliteration":"tukh''rajūna","translation_bn":"তোমাদের ওঠানো হবে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12246,"position":13,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī nazzala mina l-samāi māan biqadarin fa-ansharnā bihi baldatan maytan kadhālika tukh''rajūna', 'যিনি আকাশ থেকে পরিমিত পানি বর্ষণ করেন যা দিয়ে তিনি মৃত ভূ-ভাগকে সঞ্জীবিত করেন। এভাবেই তোমাদেরকে বের করা হবে।', 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -', 'যিনি আকাশ থেকে পরিমিত পানি বর্ষণ করেন যা দিয়ে তিনি মৃত ভূ-ভাগকে সঞ্জীবিত করেন। এভাবেই তোমাদেরকে বের করা হবে।', 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043011.mp3', now()),
  (43, 12, '', '[{"id":13581,"position":1,"text_uthmani":"وَٱلَّذِى","transliteration":"wa-alladhī","translation_bn":"এবং যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13582,"position":2,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13583,"position":3,"text_uthmani":"ٱلْأَزْوَٰجَ","transliteration":"l-azwāja","translation_bn":"জোড়া জোড়া","root":"زوج","lemma":"زَوْج","grammar_bn":"শব্দ"},{"id":13584,"position":4,"text_uthmani":"كُلَّهَا","transliteration":"kullahā","translation_bn":"তার প্রত্যেকটি (জিনিসকে)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13585,"position":5,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং সৃষ্টি করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13586,"position":6,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":13587,"position":7,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13588,"position":8,"text_uthmani":"ٱلْفُلْكِ","transliteration":"l-ful''ki","translation_bn":"নৌযান","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":13589,"position":9,"text_uthmani":"وَٱلْأَنْعَـٰمِ","transliteration":"wal-anʿāmi","translation_bn":"ও চতুষ্পদ জন্তু","root":"نعم","lemma":"نَّعَم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13590,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যার (উপর)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13591,"position":11,"text_uthmani":"تَرْكَبُونَ","transliteration":"tarkabūna","translation_bn":"তোমরা চড়তে পারো","root":"ركب","lemma":"رَكِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13592,"position":12,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī khalaqa l-azwāja kullahā wajaʿala lakum mina l-ful''ki wal-anʿāmi mā tarkabūna', 'তিনি সব কিছুকে জোড়া জোড়া সৃষ্টি করেছেন, আর তোমাদের জন্য নৌযান ও গবাদি পশু সৃষ্টি করেছেন যাতে তোমরা আরোহণ কর,', 'And who created the species, all of them, and has made for you of ships and animals those which you mount.', 'তিনি সব কিছুকে জোড়া জোড়া সৃষ্টি করেছেন, আর তোমাদের জন্য নৌযান ও গবাদি পশু সৃষ্টি করেছেন যাতে তোমরা আরোহণ কর,', 'And who created the species, all of them, and has made for you of ships and animals those which you mount.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043012.mp3', now()),
  (43, 13, '', '[{"id":14768,"position":1,"text_uthmani":"لِتَسْتَوُۥا۟","transliteration":"litastawū","translation_bn":"তোমরা যেন স্হির হয়ে বসতে পারো","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"শব্দ"},{"id":14769,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14770,"position":3,"text_uthmani":"ظُهُورِهِۦ","transliteration":"ẓuhūrihi","translation_bn":"তাদের পিঠের","root":"ظهر","lemma":"ظَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14771,"position":4,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14772,"position":5,"text_uthmani":"تَذْكُرُوا۟","transliteration":"tadhkurū","translation_bn":"তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14773,"position":6,"text_uthmani":"نِعْمَةَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহের (কথা)","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14774,"position":7,"text_uthmani":"رَبِّكُمْ","transliteration":"rabbikum","translation_bn":"তোমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14775,"position":8,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":14776,"position":9,"text_uthmani":"ٱسْتَوَيْتُمْ","transliteration":"is''tawaytum","translation_bn":"তোমরা চড়ে বসো","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":14777,"position":10,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14778,"position":11,"text_uthmani":"وَتَقُولُوا۟","transliteration":"wataqūlū","translation_bn":"এবং তোমরা বলো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14779,"position":12,"text_uthmani":"سُبْحَـٰنَ","transliteration":"sub''ḥāna","translation_bn":"\"মহান পবিত্র (আল্লাহ)","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":14780,"position":13,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14781,"position":14,"text_uthmani":"سَخَّرَ","transliteration":"sakhara","translation_bn":"বশ করে দিয়েছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14782,"position":15,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদের জন্যে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":14783,"position":16,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":14784,"position":17,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14785,"position":18,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14786,"position":19,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":14787,"position":20,"text_uthmani":"مُقْرِنِينَ","transliteration":"muq''rinīna","translation_bn":"বশীভূতকারী","root":"قرن","lemma":"مُقْرِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":14788,"position":21,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'litastawū ʿalā ẓuhūrihi thumma tadhkurū niʿ''mata rabbikum idhā is''tawaytum ʿalayhi wataqūlū sub''ḥāna alladhī sakhara lanā hādhā wamā kunnā lahu muq''rinīna', 'যাতে তোমরা যখন তাদের পিঠে স্থির হয়ে বস, তখন যেন তোমাদের প্রতিপালকের অনুগ্রহের কথা স্মরণ কর আর বল- মহান ও পবিত্র তিনি যিনি, এগুলোকে আমাদের (ব্যবহারের জন্য) বশীভূত করে দিয়েছেন, আমরা এগুলোকে বশীভূত করতে সক্ষম ছিলাম না।', 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.', 'যাতে তোমরা যখন তাদের পিঠে স্থির হয়ে বস, তখন যেন তোমাদের প্রতিপালকের অনুগ্রহের কথা স্মরণ কর আর বল- মহান ও পবিত্র তিনি যিনি, এগুলোকে আমাদের (ব্যবহারের জন্য) বশীভূত করে দিয়েছেন, আমরা এগুলোকে বশীভূত করতে সক্ষম ছিলাম না।', 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043013.mp3', now()),
  (43, 14, '', '[{"id":15849,"position":1,"text_uthmani":"وَإِنَّآ","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15850,"position":2,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15851,"position":3,"text_uthmani":"رَبِّنَا","transliteration":"rabbinā","translation_bn":"আমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15852,"position":4,"text_uthmani":"لَمُنقَلِبُونَ","transliteration":"lamunqalibūna","translation_bn":"অবশ্যই প্রত্যাবর্তনকারী\"","root":"قلب","lemma":"مُنقَلِبُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":15853,"position":5,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innā ilā rabbinā lamunqalibūna', 'আর আমাদেরকে অবশ্যই আমাদের প্রতিপালকের দিকে ফিরে যেতে হবে।', 'And indeed we, to our Lord, will [surely] return."', 'আর আমাদেরকে অবশ্যই আমাদের প্রতিপালকের দিকে ফিরে যেতে হবে।', 'And indeed we, to our Lord, will [surely] return."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043014.mp3', now()),
  (43, 15, '', '[{"id":16968,"position":1,"text_uthmani":"وَجَعَلُوا۟","transliteration":"wajaʿalū","translation_bn":"এবং (এ সত্ত্বেও) সাব্যস্ত করেছে তারা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16969,"position":2,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাঁর জন্যে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":16970,"position":3,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য হ''তে (কতককে)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16971,"position":4,"text_uthmani":"عِبَادِهِۦ","transliteration":"ʿibādihi","translation_bn":"তাঁর দাসদের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":16972,"position":5,"text_uthmani":"جُزْءًا ۚ","transliteration":"juz''an","translation_bn":"একটি অংশ","root":"جزا","lemma":"جُزْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":16974,"position":6,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16975,"position":7,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":16976,"position":8,"text_uthmani":"لَكَفُورٌۭ","transliteration":"lakafūrun","translation_bn":"অকৃতজ্ঞ অবশ্যই","root":"كفر","lemma":"كَفُور","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":16977,"position":9,"text_uthmani":"مُّبِينٌ","transliteration":"mubīnun","translation_bn":"স্পষ্টই","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":16978,"position":10,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalū lahu min ʿibādihi juz''an inna l-insāna lakafūrun mubīnun', 'আর তারা আল্লাহর বান্দাদের মধ্য হতে কতককে আল্লাহর অংশ মনে করে নিয়েছে (যেমন ‘ঈসা (আঃ)-কে তারা আল্লাহর পুত্র মনে করে)। মানুষ অবশ্যই স্পষ্টতঃ অকৃতজ্ঞ।', 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.', 'আর তারা আল্লাহর বান্দাদের মধ্য হতে কতককে আল্লাহর অংশ মনে করে নিয়েছে (যেমন ‘ঈসা (আঃ)-কে তারা আল্লাহর পুত্র মনে করে)। মানুষ অবশ্যই স্পষ্টতঃ অকৃতজ্ঞ।', 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043015.mp3', now()),
  (43, 16, '', '[{"id":18078,"position":1,"text_uthmani":"أَمِ","transliteration":"ami","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18079,"position":2,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"তিনি গ্রহণ করেছেন","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18080,"position":3,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হ''তে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18081,"position":4,"text_uthmani":"يَخْلُقُ","transliteration":"yakhluqu","translation_bn":"তিনি সৃষ্টি করেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18082,"position":5,"text_uthmani":"بَنَاتٍۢ","transliteration":"banātin","translation_bn":"অথচ কন্যারূপে","root":"بني","lemma":"بَنَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":18083,"position":6,"text_uthmani":"وَأَصْفَىٰكُم","transliteration":"wa-aṣfākum","translation_bn":"তোমাদেরকে নির্ধারণ করেছেন","root":"صفو","lemma":"أَصْفَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18084,"position":7,"text_uthmani":"بِٱلْبَنِينَ","transliteration":"bil-banīna","translation_bn":"পুত্রদের দিয়ে","root":"بني","lemma":"بُنَىّ","grammar_bn":"অব্যয় (Preposition)"},{"id":18085,"position":8,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'ami ittakhadha mimmā yakhluqu banātin wa-aṣfākum bil-banīna', 'কি! তিনি তাঁরই সৃষ্টি হতে কন্যা সন্তান গ্রহণ করেছেন আর তোমাদের জন্য মনোনীত করেছেন পুত্র সন্তান?', 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?', 'কি! তিনি তাঁরই সৃষ্টি হতে কন্যা সন্তান গ্রহণ করেছেন আর তোমাদের জন্য মনোনীত করেছেন পুত্র সন্তান?', 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043016.mp3', now()),
  (43, 17, '', '[{"id":19079,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"অথচ যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19080,"position":2,"text_uthmani":"بُشِّرَ","transliteration":"bushira","translation_bn":"সুসংবাদ দেওয়া হয়","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19081,"position":3,"text_uthmani":"أَحَدُهُم","transliteration":"aḥaduhum","translation_bn":"তাদের কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19082,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19083,"position":5,"text_uthmani":"ضَرَبَ","transliteration":"ḍaraba","translation_bn":"সে আরোপ করে","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19084,"position":6,"text_uthmani":"لِلرَّحْمَـٰنِ","transliteration":"lilrraḥmāni","translation_bn":"দয়াময়ের জন্যে","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":19085,"position":7,"text_uthmani":"مَثَلًۭا","transliteration":"mathalan","translation_bn":"(কন্যা গ্রহণের) দৃষ্টান্ত হিসেবে","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":19086,"position":8,"text_uthmani":"ظَلَّ","transliteration":"ẓalla","translation_bn":"হয়ে যায়","root":"ظلل","lemma":"ظَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19087,"position":9,"text_uthmani":"وَجْهُهُۥ","transliteration":"wajhuhu","translation_bn":"তার মুখমন্ডল","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":19088,"position":10,"text_uthmani":"مُسْوَدًّۭا","transliteration":"mus''waddan","translation_bn":"কালো","root":"سود","lemma":"مُسْوَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19089,"position":11,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এ অবস্থায় সে","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19090,"position":12,"text_uthmani":"كَظِيمٌ","transliteration":"kaẓīmun","translation_bn":"দুশ্চিন্তাগ্রস্তও (হয়ে যায়)","root":"كظم","lemma":"كَظِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19091,"position":13,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā bushira aḥaduhum bimā ḍaraba lilrraḥmāni mathalan ẓalla wajhuhu mus''waddan wahuwa kaẓīmun', 'তাদের কাউকে যখন সংবাদ দেয়া হয় সেই সন্তানের যা তারা দয়াময় আল্লাহর প্রতি আরোপ করে, তখন তার মুখ মন্ডলে কালিমা ছেয়ে যায়, আর মন দুঃখ বেদনায় ভরে যায়।', 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief.', 'তাদের কাউকে যখন সংবাদ দেয়া হয় সেই সন্তানের যা তারা দয়াময় আল্লাহর প্রতি আরোপ করে, তখন তার মুখ মন্ডলে কালিমা ছেয়ে যায়, আর মন দুঃখ বেদনায় ভরে যায়।', 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043017.mp3', now()),
  (43, 18, '', '[{"id":20199,"position":1,"text_uthmani":"أَوَمَن","transliteration":"awaman","translation_bn":"কি (আল্লাহর ভাগে সে সন্তান) যে","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":20200,"position":2,"text_uthmani":"يُنَشَّؤُا۟","transliteration":"yunasha-u","translation_bn":"লালিত পালিত হয়","root":"نشا","lemma":"يُنَشَّؤُا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":20201,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20202,"position":4,"text_uthmani":"ٱلْحِلْيَةِ","transliteration":"l-ḥil''yati","translation_bn":"অলংকারের","root":"حلي","lemma":"حِلْيَة","grammar_bn":"শব্দ"},{"id":20203,"position":5,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং সে","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20204,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20205,"position":7,"text_uthmani":"ٱلْخِصَامِ","transliteration":"l-khiṣāmi","translation_bn":"বিতর্কের","root":"خصم","lemma":"خَصِيم","grammar_bn":"শব্দ"},{"id":20206,"position":8,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"নয়","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":20207,"position":9,"text_uthmani":"مُبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":20208,"position":10,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'awaman yunasha-u fī l-ḥil''yati wahuwa fī l-khiṣāmi ghayru mubīnin', 'তারা কি আল্লাহর জন্য নির্ধারিত করে এমন সন্তান যে অলংকারে লালিত পালিত হয়, আর বিতর্ককালে বক্তব্যকে স্পষ্ট করতে অসমর্থ?', 'So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?', 'তারা কি আল্লাহর জন্য নির্ধারিত করে এমন সন্তান যে অলংকারে লালিত পালিত হয়, আর বিতর্ককালে বক্তব্যকে স্পষ্ট করতে অসমর্থ?', 'So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043018.mp3', now()),
  (43, 19, '', '[{"id":21267,"position":1,"text_uthmani":"وَجَعَلُوا۟","transliteration":"wajaʿalū","translation_bn":"এবং তারা গণ্য করে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21268,"position":2,"text_uthmani":"ٱلْمَلَـٰٓئِكَةَ","transliteration":"l-malāikata","translation_bn":"ফেরেশতাগণকে","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":21269,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা (এমন যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":21270,"position":4,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":21271,"position":5,"text_uthmani":"عِبَـٰدُ","transliteration":"ʿibādu","translation_bn":"দাস","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21272,"position":6,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"দয়াময়ের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":21273,"position":7,"text_uthmani":"إِنَـٰثًا ۚ","transliteration":"ināthan","translation_bn":"নারীরূপে","root":"انث","lemma":"أُنثَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21275,"position":8,"text_uthmani":"أَشَهِدُوا۟","transliteration":"ashahidū","translation_bn":"কি তারা প্রত্যক্ষ করেছে","root":"شهد","lemma":"شَهِدَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":21276,"position":9,"text_uthmani":"خَلْقَهُمْ ۚ","transliteration":"khalqahum","translation_bn":"তাদের সৃষ্টি","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":21278,"position":10,"text_uthmani":"سَتُكْتَبُ","transliteration":"satuk''tabu","translation_bn":"অচিরেই লিখে রাখা হবে","root":"كتب","lemma":"كَتَبَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":21279,"position":11,"text_uthmani":"شَهَـٰدَتُهُمْ","transliteration":"shahādatuhum","translation_bn":"তাদের সাক্ষ্য","root":"شهد","lemma":"شَهَٰدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21280,"position":12,"text_uthmani":"وَيُسْـَٔلُونَ","transliteration":"wayus''alūna","translation_bn":"এবং তাদের জিজ্ঞেস করা হবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21281,"position":13,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalū l-malāikata alladhīna hum ʿibādu l-raḥmāni ināthan ashahidū khalqahum satuk''tabu shahādatuhum wayus''alūna', 'তারা দয়াময়ের বান্দাহ্ ফেরেশতাদেরকে নারী গণ্য করে। তারা কি ফেরেশতাদেরকে সৃষ্টি সরাসরি দেখেছে? তাদের সাক্ষ্য লিখে রাখা হবে এবং তারা জিজ্ঞাসিত হবে।', 'And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.', 'তারা দয়াময়ের বান্দাহ্ ফেরেশতাদেরকে নারী গণ্য করে। তারা কি ফেরেশতাদেরকে সৃষ্টি সরাসরি দেখেছে? তাদের সাক্ষ্য লিখে রাখা হবে এবং তারা জিজ্ঞাসিত হবে।', 'And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043019.mp3', now()),
  (43, 20, '', '[{"id":22369,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22370,"position":2,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"\"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":22371,"position":3,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছে করতেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22372,"position":4,"text_uthmani":"ٱلرَّحْمَـٰنُ","transliteration":"l-raḥmānu","translation_bn":"দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":22373,"position":5,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না\"","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":22374,"position":6,"text_uthmani":"عَبَدْنَـٰهُم ۗ","transliteration":"ʿabadnāhum","translation_bn":"তাদের আমরা পূজা করতাম\"","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22376,"position":7,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":22377,"position":8,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":22378,"position":9,"text_uthmani":"بِذَٰلِكَ","transliteration":"bidhālika","translation_bn":"এই সম্পর্কে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":22379,"position":10,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22380,"position":11,"text_uthmani":"عِلْمٍ ۖ","transliteration":"ʿil''min","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22382,"position":12,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":22383,"position":13,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22384,"position":14,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":22385,"position":15,"text_uthmani":"يَخْرُصُونَ","transliteration":"yakhruṣūna","translation_bn":"আন্দাজ অনুমান করে","root":"خرص","lemma":"يَخْرُصُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22386,"position":16,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū law shāa l-raḥmānu mā ʿabadnāhum mā lahum bidhālika min ʿil''min in hum illā yakhruṣūna', 'তারা আরো বলে- দয়াময় আল্লাহ ইচ্ছে করলে আমরা ওদের পূঁজা করতাম না। এ বিষয়ে তাদের কোন জ্ঞানই নেই। তারা শুধু আন্দাজ অনুমানে কথা বলে।', 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but falsifying.', 'তারা আরো বলে- দয়াময় আল্লাহ ইচ্ছে করলে আমরা ওদের পূঁজা করতাম না। এ বিষয়ে তাদের কোন জ্ঞানই নেই। তারা শুধু আন্দাজ অনুমানে কথা বলে।', 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but falsifying.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043020.mp3', now()),
  (43, 21, '', '[{"id":23488,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"তবে কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23489,"position":2,"text_uthmani":"ءَاتَيْنَـٰهُمْ","transliteration":"ātaynāhum","translation_bn":"তাদেরকে আমরা দিয়েছি","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":23490,"position":3,"text_uthmani":"كِتَـٰبًۭا","transliteration":"kitāban","translation_bn":"কোন কিতাব (তার স্বপক্ষে)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23491,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23492,"position":5,"text_uthmani":"قَبْلِهِۦ","transliteration":"qablihi","translation_bn":"এর পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23493,"position":6,"text_uthmani":"فَهُم","transliteration":"fahum","translation_bn":"অতঃপর তারা","root":"—","lemma":"فَهُم","grammar_bn":"শব্দ"},{"id":23494,"position":7,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তাকে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":23495,"position":8,"text_uthmani":"مُسْتَمْسِكُونَ","transliteration":"mus''tamsikūna","translation_bn":"দৃঢ়ভাবে ধারণকারী","root":"مسك","lemma":"مُسْتَمْسِكُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":23496,"position":9,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'am ātaynāhum kitāban min qablihi fahum bihi mus''tamsikūna', 'আমি কি তাদেরকে এর (অর্থাৎ কুরআনের) আগে কোন কিতাব দিয়েছি অতঃপর তারা তা অাঁকড়ে ধরে আছে?', 'Or have We given them a book before the Qur''an to which they are adhering?', 'আমি কি তাদেরকে এর (অর্থাৎ কুরআনের) আগে কোন কিতাব দিয়েছি অতঃপর তারা তা অাঁকড়ে ধরে আছে?', 'Or have We given them a book before the Qur''an to which they are adhering?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043021.mp3', now()),
  (43, 22, '', '[{"id":24519,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"(না) বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":24520,"position":2,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24521,"position":3,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"\"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24522,"position":4,"text_uthmani":"وَجَدْنَآ","transliteration":"wajadnā","translation_bn":"আমরা পেয়েছি","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24523,"position":5,"text_uthmani":"ءَابَآءَنَا","transliteration":"ābāanā","translation_bn":"আমাদের বাপ-দাদাদেরকে","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":24524,"position":6,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24525,"position":7,"text_uthmani":"أُمَّةٍۢ","transliteration":"ummatin","translation_bn":"(এই) মতাদর্শের","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24526,"position":8,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"ও নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24527,"position":9,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24528,"position":10,"text_uthmani":"ءَاثَـٰرِهِم","transliteration":"āthārihim","translation_bn":"তাদের পদাঙ্কসমূহের","root":"اثر","lemma":"أَثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24529,"position":11,"text_uthmani":"مُّهْتَدُونَ","transliteration":"muh''tadūna","translation_bn":"সঠিক পথপ্রাপ্ত\"","root":"هدي","lemma":"مُّهْتَدُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":24530,"position":12,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'bal qālū innā wajadnā ābāanā ʿalā ummatin wa-innā ʿalā āthārihim muh''tadūna', 'বরং তারা বলে- আমরা আমাদের পূর্ব পুরুষদেরকে এক ধর্মমত পালনরত পেয়েছি আর আমরা তাদের পদাঙ্ক অনুসরণ করে পথপ্রাপ্ত হয়েছি।', 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."', 'বরং তারা বলে- আমরা আমাদের পূর্ব পুরুষদেরকে এক ধর্মমত পালনরত পেয়েছি আর আমরা তাদের পদাঙ্ক অনুসরণ করে পথপ্রাপ্ত হয়েছি।', 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/043022.mp3', now()),
  (43, 23, '', '[{"id":25609,"position":1,"text_uthmani":"وَكَذَٰلِكَ","transliteration":"wakadhālika","translation_bn":"এবং এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25610,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":25611,"position":3,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25612,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25613,"position":5,"text_uthmani":"قَبْلِكَ","transliteration":"qablika","translation_bn":"তোমার পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":25614,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25615,"position":7,"text_uthmani":"قَرْيَةٍۢ","transliteration":"qaryatin","translation_bn":"কোন জনপদের","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25616,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25617,"position":9,"text_uthmani":"نَّذِيرٍ","transliteration":"nadhīrin","translation_bn":"সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":25618,"position":10,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":25619,"position":11,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25620,"position":12,"text_uthmani":"مُتْرَفُوهَآ","transliteration":"mut''rafūhā","translation_bn":"তার বিত্তশালীরা","root":"