  (44, 6, '', '[{"id":5999,"position":1,"text_uthmani":"رَحْمَةًۭ","transliteration":"raḥmatan","translation_bn":"অনুগ্রহস্বরূপ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6000,"position":2,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হ''তে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6001,"position":3,"text_uthmani":"رَّبِّكَ ۚ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6003,"position":4,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6004,"position":5,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":6005,"position":6,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সব কিছুই শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":6006,"position":7,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":6007,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'raḥmatan min rabbika innahu huwa l-samīʿu l-ʿalīmu', 'তোমার প্রতিপালকের অনুগ্রহ স্বরূপ তিনি সর্বশ্রোতা, সর্বজ্ঞ।', 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing.', 'তোমার প্রতিপালকের অনুগ্রহ স্বরূপ তিনি সর্বশ্রোতা, সর্বজ্ঞ।', 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044006.mp3', now()),
  (44, 7, '', '[{"id":7313,"position":1,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(তিনি) রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7314,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":7315,"position":3,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7316,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7317,"position":5,"text_uthmani":"بَيْنَهُمَآ ۖ","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে আছে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":7319,"position":6,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":7320,"position":7,"text_uthmani":"كُنتُم","transliteration":"kuntum","translation_bn":"তোমরা হয়ে থাকো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7321,"position":8,"text_uthmani":"مُّوقِنِينَ","transliteration":"mūqinīna","translation_bn":"নিশ্চিত বিশ্বাসী","root":"يقن","lemma":"مُّوقِنِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":7322,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi l-samāwāti wal-arḍi wamā baynahumā in kuntum mūqinīna', 'আকাশ ও পৃথিবী এবং এ দু’য়ের মাঝে যা কিছু আছে সব কিছুর যিনি প্রতিপালক, (তাঁর মর্যাদা যে কত মহান এ কথা উপলব্ধি করে নাও) যদি তোমরা সত্যিকারই বিশ্বাসী হয়ে থাক।', 'Lord of the heavens and the earth and that between them, if you would be certain.', 'আকাশ ও পৃথিবী এবং এ দু’য়ের মাঝে যা কিছু আছে সব কিছুর যিনি প্রতিপালক, (তাঁর মর্যাদা যে কত মহান এ কথা উপলব্ধি করে নাও) যদি তোমরা সত্যিকারই বিশ্বাসী হয়ে থাক।', 'Lord of the heavens and the earth and that between them, if you would be certain.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044007.mp3', now()),
  (44, 8, '', '[{"id":8578,"position":1,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8579,"position":2,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"কোনো ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":8580,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":8581,"position":4,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":8582,"position":5,"text_uthmani":"يُحْىِۦ","transliteration":"yuḥ''yī","translation_bn":"তিনি জীবন দেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":8583,"position":6,"text_uthmani":"وَيُمِيتُ ۖ","transliteration":"wayumītu","translation_bn":"এবং মৃত্যুও ঘটান","root":"موت","lemma":"أَمَاتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8585,"position":7,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8586,"position":8,"text_uthmani":"وَرَبُّ","transliteration":"warabbu","translation_bn":"ও রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8587,"position":9,"text_uthmani":"ءَابَآئِكُمُ","transliteration":"ābāikumu","translation_bn":"তোমাদের পিতৃপুরুষদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":8588,"position":10,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বকালের","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":8589,"position":11,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'lā ilāha illā huwa yuḥ''yī wayumītu rabbukum warabbu ābāikumu l-awalīna', 'তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, তিনিই জীবিত করেন ও মৃত্যু ঘটান। তিনিই তোমাদের প্রতিপালক এবং তোমাদের পূর্ববর্তী তোমাদের পিতৃপুরুষদেরও প্রতিপালক।', 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.', 'তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, তিনিই জীবিত করেন ও মৃত্যু ঘটান। তিনিই তোমাদের প্রতিপালক এবং তোমাদের পূর্ববর্তী তোমাদের পিতৃপুরুষদেরও প্রতিপালক।', 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044008.mp3', now()),
  (44, 9, '', '[{"id":9796,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":9797,"position":2,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9798,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9799,"position":4,"text_uthmani":"شَكٍّۢ","transliteration":"shakkin","translation_bn":"সন্দেহের","root":"شكك","lemma":"شَكّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9800,"position":5,"text_uthmani":"يَلْعَبُونَ","transliteration":"yalʿabūna","translation_bn":"খেলা করছে","root":"لعب","lemma":"يَلْعَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9801,"position":6,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'bal hum fī shakkin yalʿabūna', 'কিন্তু তারা সংশয়ের মাঝে খেলায় মত্ত।', 'But they are in doubt, amusing themselves.', 'কিন্তু তারা সংশয়ের মাঝে খেলায় মত্ত।', 'But they are in doubt, amusing themselves.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044009.mp3', now()),
  (44, 10, '', '[{"id":10946,"position":1,"text_uthmani":"فَٱرْتَقِبْ","transliteration":"fa-ir''taqib","translation_bn":"সুতরাং অপেক্ষা করো","root":"رقب","lemma":"ٱرْتَقِبْ","grammar_bn":"শব্দ"},{"id":10947,"position":2,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেই দিনের (যখন)","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10948,"position":3,"text_uthmani":"تَأْتِى","transliteration":"tatī","translation_bn":"আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":10949,"position":4,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":10950,"position":5,"text_uthmani":"بِدُخَانٍۢ","transliteration":"bidukhānin","translation_bn":"নিয়ে ধোঁয়া (আচ্ছন্ন হয়ে)","root":"دخن","lemma":"دُخَان","grammar_bn":"অব্যয় (Preposition)"},{"id":10951,"position":6,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":10952,"position":7,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ir''taqib yawma tatī l-samāu bidukhānin mubīnin', 'অতএব তুমি অপেক্ষা কর সে দিনের যেদিন আকাশ ধোঁয়ায় আচ্ছন্ন হবে যা সুস্পষ্ট (ভাবে দেখা যাবে)।', 'Then watch for the Day when the sky will bring a visible smoke.', 'অতএব তুমি অপেক্ষা কর সে দিনের যেদিন আকাশ ধোঁয়ায় আচ্ছন্ন হবে যা সুস্পষ্ট (ভাবে দেখা যাবে)।', 'Then watch for the Day when the sky will bring a visible smoke.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044010.mp3', now()),
  (44, 11, '', '[{"id":12265,"position":1,"text_uthmani":"يَغْشَى","transliteration":"yaghshā","translation_bn":"ঢেকে নিবে","root":"غشو","lemma":"غَشِيَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12266,"position":2,"text_uthmani":"ٱلنَّاسَ ۖ","transliteration":"l-nāsa","translation_bn":"মানুষকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":12268,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটাই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":12269,"position":4,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12270,"position":5,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":12271,"position":6,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'yaghshā l-nāsa hādhā ʿadhābun alīmun', '(যা) মানুষকে ঢেকে নেবে, তা হবে ভয়াবহ শাস্তি।', 'Covering the people; this is a painful torment.', '(যা) মানুষকে ঢেকে নেবে, তা হবে ভয়াবহ শাস্তি।', 'Covering the people; this is a painful torment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044011.mp3', now()),
  (44, 12, '', '[{"id":13603,"position":1,"text_uthmani":"رَّبَّنَا","transliteration":"rabbanā","translation_bn":"\"(এখন তারা বলে) হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13604,"position":2,"text_uthmani":"ٱكْشِفْ","transliteration":"ik''shif","translation_bn":"দূর করো","root":"كشف","lemma":"كَشَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13605,"position":3,"text_uthmani":"عَنَّا","transliteration":"ʿannā","translation_bn":"আমাদের থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13606,"position":4,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":13607,"position":5,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13608,"position":6,"text_uthmani":"مُؤْمِنُونَ","transliteration":"mu''minūna","translation_bn":"বিশ্বাসী হবো (ঈমান আনবো)\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":13609,"position":7,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'rabbanā ik''shif ʿannā l-ʿadhāba innā mu''minūna', '(তখন তারা আরয করবে)- হে আমাদের পালনকর্তা! আমাদের থেকে শাস্তি সরিয়ে দিন, আমরা ঈমান আনলাম।', '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."', '(তখন তারা আরয করবে)- হে আমাদের পালনকর্তা! আমাদের থেকে শাস্তি সরিয়ে দিন, আমরা ঈমান আনলাম।', '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044012.mp3', now()),
  (44, 13, '', '[{"id":14802,"position":1,"text_uthmani":"أَنَّىٰ","transliteration":"annā","translation_bn":"কেমন করে হবে","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":14803,"position":2,"text_uthmani":"لَهُمُ","transliteration":"lahumu","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":14804,"position":3,"text_uthmani":"ٱلذِّكْرَىٰ","transliteration":"l-dhik''rā","translation_bn":"উপদেশ গ্রহণ (সম্ভব হবে)","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"শব্দ"},{"id":14805,"position":4,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"অথচ নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14806,"position":5,"text_uthmani":"جَآءَهُمْ","transliteration":"jāahum","translation_bn":"তাদের কাছে এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14807,"position":6,"text_uthmani":"رَسُولٌۭ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":14808,"position":7,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":14809,"position":8,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'annā lahumu l-dhik''rā waqad jāahum rasūlun mubīnun', 'তারা কীভাবে উপদেশ গ্রহণ করবে? তাদের কাছে তো এসেছে সুস্পষ্ট বর্ণনাকারী এক রসূল।', 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.', 'তারা কীভাবে উপদেশ গ্রহণ করবে? তাদের কাছে তো এসেছে সুস্পষ্ট বর্ণনাকারী এক রসূল।', 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044013.mp3', now()),
  (44, 14, '', '[{"id":15880,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপরও","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15881,"position":2,"text_uthmani":"تَوَلَّوْا۟","transliteration":"tawallaw","translation_bn":"তারা ফিরে যায়","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15882,"position":3,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"তা হ''তে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15883,"position":4,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15884,"position":5,"text_uthmani":"مُعَلَّمٌۭ","transliteration":"muʿallamun","translation_bn":"\"(সে একজন) প্রশিক্ষণপ্রাপ্ত","root":"علم","lemma":"مُعَلَّم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15885,"position":6,"text_uthmani":"مَّجْنُونٌ","transliteration":"majnūnun","translation_bn":"পাগল\"","root":"جنن","lemma":"مَجْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":15886,"position":7,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma tawallaw ʿanhu waqālū muʿallamun majnūnun', 'এখন তারা তার থেকে মুখ ফিরিয়ে নিচ্ছে আর তারা বলছে (সে হল এক) পাগল- যাকে শিখিয়ে দেয়া হয়েছে।', 'Then they turned away from him and said, "[He was] taught [and is] a madman."', 'এখন তারা তার থেকে মুখ ফিরিয়ে নিচ্ছে আর তারা বলছে (সে হল এক) পাগল- যাকে শিখিয়ে দেয়া হয়েছে।', 'Then they turned away from him and said, "[He was] taught [and is] a madman."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044014.mp3', now()),
  (44, 15, '', '[{"id":17000,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17001,"position":2,"text_uthmani":"كَاشِفُوا۟","transliteration":"kāshifū","translation_bn":"দূর করে দিই","root":"كشف","lemma":"كَاشِف","grammar_bn":"বিশেষ্য (Noun)"},{"id":17002,"position":3,"text_uthmani":"ٱلْعَذَابِ","transliteration":"l-ʿadhābi","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":17003,"position":4,"text_uthmani":"قَلِيلًا ۚ","transliteration":"qalīlan","translation_bn":"কিছুটা (তবুও)","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":17005,"position":5,"text_uthmani":"إِنَّكُمْ","transliteration":"innakum","translation_bn":"তোমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17006,"position":6,"text_uthmani":"عَآئِدُونَ","transliteration":"ʿāidūna","translation_bn":"আগের অবস্হায় ফিরে যাও (যা পূর্বে করতে)","root":"عود","lemma":"عَا^ئِدُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":17007,"position":7,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'innā kāshifū l-ʿadhābi qalīlan innakum ʿāidūna', 'আমি কিছুকালের জন্য ‘আযাব সরিয়ে নেব, তখন তোমরা আগে যা করছিলে তাই আবার করবে।', 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].', 'আমি কিছুকালের জন্য ‘আযাব সরিয়ে নেব, তখন তোমরা আগে যা করছিলে তাই আবার করবে।', 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044015.mp3', now()),
  (44, 16, '', '[{"id":18106,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18107,"position":2,"text_uthmani":"نَبْطِشُ","transliteration":"nabṭishu","translation_bn":"আমরা পাকড়াও করবো","root":"بطش","lemma":"بَطَشْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18108,"position":3,"text_uthmani":"ٱلْبَطْشَةَ","transliteration":"l-baṭshata","translation_bn":"পাকড়াও","root":"بطش","lemma":"بَطْشَة","grammar_bn":"শব্দ"},{"id":18109,"position":4,"text_uthmani":"ٱلْكُبْرَىٰٓ","transliteration":"l-kub''rā","translation_bn":"কঠিনভাবে","root":"كبر","lemma":"كُبْرَىٰ","grammar_bn":"শব্দ"},{"id":18110,"position":5,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":18111,"position":6,"text_uthmani":"مُنتَقِمُونَ","transliteration":"muntaqimūna","translation_bn":"প্রতিশোধ গ্রহণকারী(সেহদিন)","root":"نقم","lemma":"مُنتَقِمُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":18112,"position":7,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'yawma nabṭishu l-baṭshata l-kub''rā innā muntaqimūna', 'যেদিন আমি তোমাদেরকে ভীষণভাবে পাকড়াও করব, সেদিন আমি আবশ্যই প্রতিশোধ নেব।', 'The Day We will strike with the greatest assault, indeed, We will take retribution.', 'যেদিন আমি তোমাদেরকে ভীষণভাবে পাকড়াও করব, সেদিন আমি আবশ্যই প্রতিশোধ নেব।', 'The Day We will strike with the greatest assault, indeed, We will take retribution.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044016.mp3', now()),
  (44, 17, '', '[{"id":19132,"position":1,"text_uthmani":"۞ وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19133,"position":2,"text_uthmani":"فَتَنَّا","transliteration":"fatannā","translation_bn":"আমরা পরীক্ষা করেছি","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19134,"position":3,"text_uthmani":"قَبْلَهُمْ","transliteration":"qablahum","translation_bn":"তাদের পুর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":19135,"position":4,"text_uthmani":"قَوْمَ","transliteration":"qawma","translation_bn":"জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19136,"position":5,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19137,"position":6,"text_uthmani":"وَجَآءَهُمْ","transliteration":"wajāahum","translation_bn":"এবং তাদের কাছে এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19138,"position":7,"text_uthmani":"رَسُولٌۭ","transliteration":"rasūlun","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":19139,"position":8,"text_uthmani":"كَرِيمٌ","transliteration":"karīmun","translation_bn":"মহান","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":19140,"position":9,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad fatannā qablahum qawma fir''ʿawna wajāahum rasūlun karīmun', 'তাদের পূর্বে আমি ফেরাউন জাতিকে পরীক্ষা করেছিলাম। তাদের কাছে এসেছিল এক সম্মানিত রসূল।', 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,', 'তাদের পূর্বে আমি ফেরাউন জাতিকে পরীক্ষা করেছিলাম। তাদের কাছে এসেছিল এক সম্মানিত রসূল।', 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044017.mp3', now()),
  (44, 18, '', '[{"id":20244,"position":1,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"(সে বলেছিলো) যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":20245,"position":2,"text_uthmani":"أَدُّوٓا۟","transliteration":"addū","translation_bn":"\"তোমরা সমর্পণ করো","root":"ادي","lemma":"يُؤَدِّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20246,"position":3,"text_uthmani":"إِلَىَّ","transliteration":"ilayya","translation_bn":"আমার কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20247,"position":4,"text_uthmani":"عِبَادَ","transliteration":"ʿibāda","translation_bn":"দাসদেরকে","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20248,"position":5,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20250,"position":6,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20251,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":20252,"position":8,"text_uthmani":"رَسُولٌ","transliteration":"rasūlun","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":20253,"position":9,"text_uthmani":"أَمِينٌۭ","transliteration":"amīnun","translation_bn":"বিশ্বস্ত","root":"امن","lemma":"أَمِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":20254,"position":10,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'an addū ilayya ʿibāda l-lahi innī lakum rasūlun amīnun', 'সে বলেছিল- আল্লাহর বান্দাদেরকে আমার কাছে অর্পণ কর। আমি তোমাদের জন্য প্রেরিত বিশ্বস্ত রসূল।', '[Saying], "Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,"', 'সে বলেছিল- আল্লাহর বান্দাদেরকে আমার কাছে অর্পণ কর। আমি তোমাদের জন্য প্রেরিত বিশ্বস্ত রসূল।', '[Saying], "Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044018.mp3', now()),
  (44, 19, '', '[{"id":21347,"position":1,"text_uthmani":"وَأَن","transliteration":"wa-an","translation_bn":"এবং (এও বলেছিল) যে","root":"—","lemma":"أَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21348,"position":2,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":21349,"position":3,"text_uthmani":"تَعْلُوا۟","transliteration":"taʿlū","translation_bn":"বড়াই করো","root":"علو","lemma":"تَعَٰلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21350,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21351,"position":5,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21353,"position":6,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"আমি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21354,"position":7,"text_uthmani":"ءَاتِيكُم","transliteration":"ātīkum","translation_bn":"তোমাদের কাছে এসেছি","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":21355,"position":8,"text_uthmani":"بِسُلْطَـٰنٍۢ","transliteration":"bisul''ṭānin","translation_bn":"নিয়ে প্রমাণ","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":21356,"position":9,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":21357,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-an lā taʿlū ʿalā l-lahi innī ātīkum bisul''ṭānin mubīnin', 'আর আল্লাহর বিরুদ্ধে ঔদ্ধত্য দেখাইও না, আমি তোমাদের কাছে (আমার রসূল হওয়ার) সুস্পষ্ট প্রমাণ পেশ করছি।', 'And [saying], "Be not haughty with Allah. Indeed, I have come to you with clear authority.', 'আর আল্লাহর বিরুদ্ধে ঔদ্ধত্য দেখাইও না, আমি তোমাদের কাছে (আমার রসূল হওয়ার) সুস্পষ্ট প্রমাণ পেশ করছি।', 'And [saying], "Be not haughty with Allah. Indeed, I have come to you with clear authority.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044019.mp3', now()),
  (44, 20, '', '[{"id":22401,"position":1,"text_uthmani":"وَإِنِّى","transliteration":"wa-innī","translation_bn":"এবং নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22402,"position":2,"text_uthmani":"عُذْتُ","transliteration":"ʿudh''tu","translation_bn":"আশ্রয় নিয়েছি","root":"عوذ","lemma":"عُذْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22403,"position":3,"text_uthmani":"بِرَبِّى","transliteration":"birabbī","translation_bn":"আমার রবের (কাছে)","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":22404,"position":4,"text_uthmani":"وَرَبِّكُمْ","transliteration":"warabbikum","translation_bn":"এবং তোমাদের (প্রকৃত রবের)","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22405,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এ হ''তে) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":22406,"position":6,"text_uthmani":"تَرْجُمُونِ","transliteration":"tarjumūni","translation_bn":"আমাকে তোমরা পাথর মেরে হত্যা করবে","root":"رجم","lemma":"رَجَمْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22407,"position":7,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innī ʿudh''tu birabbī warabbikum an tarjumūni', 'আমি আমার ও তোমাদের প্রতিপালকের নিকট আশ্রয় গ্রহণ করছি যাতে তোমরা আমাকে পাথরের আঘাতে হত্যা না কর।', 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.', 'আমি আমার ও তোমাদের প্রতিপালকের নিকট আশ্রয় গ্রহণ করছি যাতে তোমরা আমাকে পাথরের আঘাতে হত্যা না কর।', 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044020.mp3', now()),
  (44, 21, '', '[{"id":23533,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23534,"position":2,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":23535,"position":3,"text_uthmani":"تُؤْمِنُوا۟","transliteration":"tu''minū","translation_bn":"তোমরা ঈমান আনো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23536,"position":4,"text_uthmani":"لِى","transliteration":"lī","translation_bn":"আমার উপর","root":"—","lemma":"لِى","grammar_bn":"অব্যয় (Preposition)"},{"id":23537,"position":5,"text_uthmani":"فَٱعْتَزِلُونِ","transliteration":"fa-iʿ''tazilūni","translation_bn":"তবে আমার থেকে দূরে থাকো\"","root":"عزل","lemma":"ٱعْتَزَلَ","grammar_bn":"শব্দ"},{"id":23538,"position":6,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in lam tu''minū lī fa-iʿ''tazilūni', 'তোমরা যদি আমার প্রতি বিশ্বাস না আনো, কমপক্ষে আমার কাছ থেকে দূরে থাক।', 'But if you do not believe me, then leave me alone."', 'তোমরা যদি আমার প্রতি বিশ্বাস না আনো, কমপক্ষে আমার কাছ থেকে দূরে থাক।', 'But if you do not believe me, then leave me alone."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044021.mp3', now()),
  (44, 22, '', '[{"id":24568,"position":1,"text_uthmani":"فَدَعَا","transliteration":"fadaʿā","translation_bn":"অবশেষে সে ডাকলো","root":"دعو","lemma":"دَعَا","grammar_bn":"শব্দ"},{"id":24569,"position":2,"text_uthmani":"رَبَّهُۥٓ","transliteration":"rabbahu","translation_bn":"তার রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24570,"position":3,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"\"(এবং বললো) যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24571,"position":4,"text_uthmani":"هَـٰٓؤُلَآءِ","transliteration":"hāulāi","translation_bn":"এসব","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":24572,"position":5,"text_uthmani":"قَوْمٌۭ","transliteration":"qawmun","translation_bn":"সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":24573,"position":6,"text_uthmani":"مُّجْرِمُونَ","transliteration":"muj''rimūna","translation_bn":"অপরাধী (তাদের মীমাংসা করো)\"","root":"جرم","lemma":"مُجْرِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":24574,"position":7,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'fadaʿā rabbahu anna hāulāi qawmun muj''rimūna', '(কিন্তু তারা ছিল আক্রমণমুখী) তখন সে তার পালনকর্তার নিকট দু‘আ করল- এরা অপরাধী জাতি।', 'And [finally] he called to his Lord that these were a criminal people.', '(কিন্তু তারা ছিল আক্রমণমুখী) তখন সে তার পালনকর্তার নিকট দু‘আ করল- এরা অপরাধী জাতি।', 'And [finally] he called to his Lord that these were a criminal people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044022.mp3', now()),
  (44, 23, '', '[{"id":25639,"position":1,"text_uthmani":"فَأَسْرِ","transliteration":"fa-asri","translation_bn":"(বলা হলো) রওনা হও তাহ''লে","root":"سري","lemma":"أَسْرَىٰ","grammar_bn":"শব্দ"},{"id":25640,"position":2,"text_uthmani":"بِعِبَادِى","transliteration":"biʿibādī","translation_bn":"আমার দাসদের নিয়ে","root":"عبد","lemma":"عَبْد","grammar_bn":"অব্যয় (Preposition)"},{"id":25641,"position":3,"text_uthmani":"لَيْلًا","transliteration":"laylan","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":25642,"position":4,"text_uthmani":"إِنَّكُم","transliteration":"innakum","translation_bn":"নিশ্চয়ই তোমাদের","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25643,"position":5,"text_uthmani":"مُّتَّبَعُونَ","transliteration":"muttabaʿūna","translation_bn":"পিছনে (ধাওয়া) করা হবে","root":"تبع","lemma":"مُّتَّبَعُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":25644,"position":6,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'fa-asri biʿibādī laylan innakum muttabaʿūna', '(তখন আমি বললাম) তুমি আমার বান্দাহদেরকে নিয়ে রাতের বেলায় বের হয়ে পড়, তোমাদের পিছু ধাওয়া করা হবে।', '[Allah said], "Then set out with My servants by night. Indeed, you are to be pursued.', '(তখন আমি বললাম) তুমি আমার বান্দাহদেরকে নিয়ে রাতের বেলায় বের হয়ে পড়, তোমাদের পিছু ধাওয়া করা হবে।', '[Allah said], "Then set out with My servants by night. Indeed, you are to be pursued.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044023.mp3', now()),
  (44, 24, '', '[{"id":26708,"position":1,"text_uthmani":"وَٱتْرُكِ","transliteration":"wa-ut''ruki","translation_bn":"এবং ছেড়ে দাও","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26709,"position":2,"text_uthmani":"ٱلْبَحْرَ","transliteration":"l-baḥra","translation_bn":"সাগরকে","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":26710,"position":3,"text_uthmani":"رَهْوًا ۖ","transliteration":"rahwan","translation_bn":"শান্ত অবস্হায়","root":"رهو","lemma":"رَهْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":26712,"position":4,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26713,"position":5,"text_uthmani":"جُندٌۭ","transliteration":"jundun","translation_bn":"(অর্থাৎ ধাওয়াকারী) সৈন্যবাহিনী","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":26714,"position":6,"text_uthmani":"مُّغْرَقُونَ","transliteration":"mugh''raqūna","translation_bn":"ডুবে যাবে\"","root":"غرق","lemma":"مُّغْرَقُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":26715,"position":7,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ut''ruki l-baḥra rahwan innahum jundun mugh''raqūna', '(মূসা বানী ইসরাঈলকে নিয়ে সমুদ্র পার হয়ে গিয়ে সমুদ্রকে আবার প্রবহমান করার জন্য স্বীয় লাঠি নিক্ষেপ করলে আল্লাহ বললেন) সমুদ্রকে স্থির থাকতে দাও, তারা (অর্থাৎ ফেরাউনী দল) এমন এক বাহিনী যারা নিমজ্জিত হবে।', 'And leave the sea in stillness. Indeed, they are an army to be drowned."', '(মূসা বানী ইসরাঈলকে নিয়ে সমুদ্র পার হয়ে গিয়ে সমুদ্রকে আবার প্রবহমান করার জন্য স্বীয় লাঠি নিক্ষেপ করলে আল্লাহ বললেন) সমুদ্রকে স্থির থাকতে দাও, তারা (অর্থাৎ ফেরাউনী দল) এমন এক বাহিনী যারা নিমজ্জিত হবে।', 'And leave the sea in stillness. Indeed, they are an army to be drowned."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044024.mp3', now()),
  (44, 25, '', '[{"id":27726,"position":1,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"কতই না","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":27727,"position":2,"text_uthmani":"تَرَكُوا۟","transliteration":"tarakū","translation_bn":"তারা ছেড়েছিলো","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27728,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27729,"position":4,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"বাগান","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27730,"position":5,"text_uthmani":"وَعُيُونٍۢ","transliteration":"waʿuyūnin","translation_bn":"ও ঝর্ণাসমূহ","root":"عين","lemma":"عَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27731,"position":6,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'kam tarakū min jannātin waʿuyūnin', 'তারা ছেড়ে গিয়েছিল কত উদ্যান আর ঝর্ণা,', 'How much they left behind of gardens and springs', 'তারা ছেড়ে গিয়েছিল কত উদ্যান আর ঝর্ণা,', 'How much they left behind of gardens and springs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/044025.mp3', now()),
