  (45, 1, '', '[{"id":167,"position":1,"text_uthmani":"حمٓ","transliteration":"hha-meem","translation_bn":"হা-মীম","root":"—","lemma":"حمٓ","grammar_bn":"শব্দ"},{"id":168,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hha-meem', 'হা-মীম।', 'Ha, Meem.', 'হা-মীম।', 'Ha, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045001.mp3', now()),
  (45, 2, '', '[{"id":1000,"position":1,"text_uthmani":"تَنزِيلُ","transliteration":"tanzīlu","translation_bn":"অবতীর্ণ করা","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1001,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"এই কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1002,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1003,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1004,"position":5,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"(যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":1005,"position":6,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1006,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlu l-kitābi mina l-lahi l-ʿazīzi l-ḥakīmi', 'এ কিতাব অবতীর্ণ হয়েছে মহা পরাক্রমশালী প্রজ্ঞাময় আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', 'এ কিতাব অবতীর্ণ হয়েছে মহা পরাক্রমশালী প্রজ্ঞাময় আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045002.mp3', now()),
  (45, 3, '', '[{"id":2097,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2098,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে রয়েছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2099,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশমণ্ডলীর","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":2100,"position":4,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2101,"position":5,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নির্দশনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":2102,"position":6,"text_uthmani":"لِّلْمُؤْمِنِينَ","transliteration":"lil''mu''minīna","translation_bn":"মু''মিনদের জন্যে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":2103,"position":7,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī l-samāwāti wal-arḍi laāyātin lil''mu''minīna', 'আকাশে এবং যমীনে মু’মিনদের (শিক্ষার) জন্য অবশ্যই নিদর্শন আছে।', 'Indeed, within the heavens and earth are signs for the believers.', 'আকাশে এবং যমীনে মু’মিনদের (শিক্ষার) জন্য অবশ্যই নিদর্শন আছে।', 'Indeed, within the heavens and earth are signs for the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045003.mp3', now()),
  (45, 4, '', '[{"id":3363,"position":1,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং মধ্যেও","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3364,"position":2,"text_uthmani":"خَلْقِكُمْ","transliteration":"khalqikum","translation_bn":"তোমাদের সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":3365,"position":3,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3366,"position":4,"text_uthmani":"يَبُثُّ","transliteration":"yabuthu","translation_bn":"তিনি (যমীনে) ছড়িয়ে দিয়েছেন","root":"بثث","lemma":"بَثَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3367,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3368,"position":6,"text_uthmani":"دَآبَّةٍ","transliteration":"dābbatin","translation_bn":"জীবজন্তু","root":"دبب","lemma":"دَا^بَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3369,"position":7,"text_uthmani":"ءَايَـٰتٌۭ","transliteration":"āyātun","translation_bn":"নিদর্শনাবলী (রয়েছে)","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3370,"position":8,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"লোকদের জন্যে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":3371,"position":9,"text_uthmani":"يُوقِنُونَ","transliteration":"yūqinūna","translation_bn":"(যারা) দৃঢ় বিশ্বাস করে","root":"يقن","lemma":"يُوقِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3372,"position":10,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wafī khalqikum wamā yabuthu min dābbatin āyātun liqawmin yūqinūna', 'তোমাদের সৃষ্টিতে, আর প্রাণীকুল ছড়িয়ে দেয়ার মাঝে নিদর্শন আছে নিশ্চিত বিশ্বাসীদের জন্য।', 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].', 'তোমাদের সৃষ্টিতে, আর প্রাণীকুল ছড়িয়ে দেয়ার মাঝে নিদর্শন আছে নিশ্চিত বিশ্বাসীদের জন্য।', 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045004.mp3', now()),
  (45, 5, '', '[{"id":4751,"position":1,"text_uthmani":"وَٱخْتِلَـٰفِ","transliteration":"wa-ikh''tilāfi","translation_bn":"এবং পরিবর্তনে","root":"خلف","lemma":"ٱخْتِلَٰف","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4752,"position":2,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":4753,"position":3,"text_uthmani":"وَٱلنَّهَارِ","transliteration":"wal-nahāri","translation_bn":"ও দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4754,"position":4,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4755,"position":5,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4756,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4757,"position":7,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4758,"position":8,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":4759,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4760,"position":10,"text_uthmani":"رِّزْقٍۢ","transliteration":"riz''qin","translation_bn":"আহার্য (অর্থাৎ পানি)","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":4761,"position":11,"text_uthmani":"فَأَحْيَا","transliteration":"fa-aḥyā","translation_bn":"অতঃপর জীবন্ত করেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4762,"position":12,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"তা দিয়ে","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":4763,"position":13,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":4764,"position":14,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":4765,"position":15,"text_uthmani":"مَوْتِهَا","transliteration":"mawtihā","translation_bn":"তার মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":4766,"position":16,"text_uthmani":"وَتَصْرِيفِ","transliteration":"wataṣrīfi","translation_bn":"এবং আবর্তনে","root":"صرف","lemma":"تَصْرِيف","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4767,"position":17,"text_uthmani":"ٱلرِّيَـٰحِ","transliteration":"l-riyāḥi","translation_bn":"বায়ুর","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":4768,"position":18,"text_uthmani":"ءَايَـٰتٌۭ","transliteration":"āyātun","translation_bn":"নির্দশনাবলী (রয়েছে)","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4769,"position":19,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"লোকদের জন্যে (যারা)","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":4770,"position":20,"text_uthmani":"يَعْقِلُونَ","transliteration":"yaʿqilūna","translation_bn":"বুদ্ধিবিবেক কাজে লাগায়","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4771,"position":21,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ikh''tilāfi al-layli wal-nahāri wamā anzala l-lahu mina l-samāi min riz''qin fa-aḥyā bihi l-arḍa baʿda mawtihā wataṣrīfi l-riyāḥi āyātun liqawmin yaʿqilūna', 'রাত ও দিনের আবর্তনে, আর আল্লাহ আকাশ থেকে যে বৃষ্টি বর্ষণ করেন তা দিয়ে যমীনকে তার মৃত্যুর পর আবার জীবিত করেন আর বায়ুর পরিবর্তনে জ্ঞানী সম্প্রদায়ের জন্য নিদর্শন রয়েছে।', 'And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.', 'রাত ও দিনের আবর্তনে, আর আল্লাহ আকাশ থেকে যে বৃষ্টি বর্ষণ করেন তা দিয়ে যমীনকে তার মৃত্যুর পর আবার জীবিত করেন আর বায়ুর পরিবর্তনে জ্ঞানী সম্প্রদায়ের জন্য নিদর্শন রয়েছে।', 'And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045005.mp3', now()),
  (45, 6, '', '[{"id":6008,"position":1,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এসব","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6009,"position":2,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"নির্দশনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6010,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6011,"position":4,"text_uthmani":"نَتْلُوهَا","transliteration":"natlūhā","translation_bn":"তার আবৃত্তি/ তিলাওয়াত করছি আমরা","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6012,"position":5,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6013,"position":6,"text_uthmani":"بِٱلْحَقِّ ۖ","transliteration":"bil-ḥaqi","translation_bn":"যথাযথভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6015,"position":7,"text_uthmani":"فَبِأَىِّ","transliteration":"fabi-ayyi","translation_bn":"সুতরাং কোন","root":"—","lemma":"أَىّ","grammar_bn":"শব্দ"},{"id":6016,"position":8,"text_uthmani":"حَدِيثٍۭ","transliteration":"ḥadīthin","translation_bn":"কথার (উপর)","root":"حدث","lemma":"حَدِيث","grammar_bn":"বিশেষ্য (Noun)"},{"id":6017,"position":9,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":6018,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6019,"position":11,"text_uthmani":"وَءَايَـٰتِهِۦ","transliteration":"waāyātihi","translation_bn":"ও তাঁর আয়াত গুলোর","root":"ايي","lemma":"ءَايَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6020,"position":12,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"তারা বিশ্বাস করবে?","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6021,"position":13,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'til''ka āyātu l-lahi natlūhā ʿalayka bil-ḥaqi fabi-ayyi ḥadīthin baʿda l-lahi waāyātihi yu''minūna', 'এগুলো হল আল্লাহর আয়াত যা সত্যতা সহকারে তোমার কাছে তিলাওয়াত করা হচ্ছে। কাজেই তারা আল্লাহ এবং তাঁর আয়াতের (উপর বিশ্বাস না করলে এর) পর আর কোন্ কথায় বিশ্বাস করবে?', 'These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?', 'এগুলো হল আল্লাহর আয়াত যা সত্যতা সহকারে তোমার কাছে তিলাওয়াত করা হচ্ছে। কাজেই তারা আল্লাহ এবং তাঁর আয়াতের (উপর বিশ্বাস না করলে এর) পর আর কোন্ কথায় বিশ্বাস করবে?', 'These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045006.mp3', now()),
  (45, 7, '', '[{"id":7323,"position":1,"text_uthmani":"وَيْلٌۭ","transliteration":"waylun","translation_bn":"দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7324,"position":2,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"প্রত্যেকের জন্য","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":7325,"position":3,"text_uthmani":"أَفَّاكٍ","transliteration":"affākin","translation_bn":"ঘোর মিথ্যাবাদীর","root":"افك","lemma":"أَفَّاك","grammar_bn":"বিশেষ্য (Noun)"},{"id":7326,"position":4,"text_uthmani":"أَثِيمٍۢ","transliteration":"athīmin","translation_bn":"পাপীর","root":"اثم","lemma":"أَثِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":7327,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'waylun likulli affākin athīmin', 'ধ্বংস প্রত্যেক মিথ্যাবাদী পাপাচারীর জন্য', 'Woe to every sinful liar', 'ধ্বংস প্রত্যেক মিথ্যাবাদী পাপাচারীর জন্য', 'Woe to every sinful liar', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045007.mp3', now()),
  (45, 8, '', '[{"id":8599,"position":1,"text_uthmani":"يَسْمَعُ","transliteration":"yasmaʿu","translation_bn":"(যে) শুনে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8600,"position":2,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"আয়াত সমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8601,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8602,"position":4,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"পাঠ করা হয় (যা)","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8603,"position":5,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8604,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8605,"position":7,"text_uthmani":"يُصِرُّ","transliteration":"yuṣirru","translation_bn":"অটল থাকে","root":"صرر","lemma":"أَصَرُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8606,"position":8,"text_uthmani":"مُسْتَكْبِرًۭا","transliteration":"mus''takbiran","translation_bn":"ঔদ্ধত্যের সাথে","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8607,"position":9,"text_uthmani":"كَأَن","transliteration":"ka-an","translation_bn":"যেন","root":"—","lemma":"أَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8608,"position":10,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":8609,"position":11,"text_uthmani":"يَسْمَعْهَا ۖ","transliteration":"yasmaʿhā","translation_bn":"তা শুনেই","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8611,"position":12,"text_uthmani":"فَبَشِّرْهُ","transliteration":"fabashir''hu","translation_bn":"তাই তাকে সুসংবাদ দাও","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"শব্দ"},{"id":8612,"position":13,"text_uthmani":"بِعَذَابٍ","transliteration":"biʿadhābin","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":8613,"position":14,"text_uthmani":"أَلِيمٍۢ","transliteration":"alīmin","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":8614,"position":15,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'yasmaʿu āyāti l-lahi tut''lā ʿalayhi thumma yuṣirru mus''takbiran ka-an lam yasmaʿhā fabashir''hu biʿadhābin alīmin', 'যে আল্লাহর আয়াত শোনে যা তার সামনে পাঠ করা হয়, অতঃপর অহমিকার সাথে (কুফুরীর উপর) থাকে যেন সে তা শোনেইনি; কাজেই তাকে ভয়াবহ শাস্তির সংবাদ দাও।', 'Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.', 'যে আল্লাহর আয়াত শোনে যা তার সামনে পাঠ করা হয়, অতঃপর অহমিকার সাথে (কুফুরীর উপর) থাকে যেন সে তা শোনেইনি; কাজেই তাকে ভয়াবহ শাস্তির সংবাদ দাও।', 'Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045008.mp3', now()),
  (45, 9, '', '[{"id":9802,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9803,"position":2,"text_uthmani":"عَلِمَ","transliteration":"ʿalima","translation_bn":"সে অবগত হয়","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9804,"position":3,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9805,"position":4,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"আমাদের আয়াত সমূহের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9806,"position":5,"text_uthmani":"شَيْـًٔا","transliteration":"shayan","translation_bn":"কোনো কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":9807,"position":6,"text_uthmani":"ٱتَّخَذَهَا","transliteration":"ittakhadhahā","translation_bn":"সে গ্রহণ করে তা","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9808,"position":7,"text_uthmani":"هُزُوًا ۚ","transliteration":"huzuwan","translation_bn":"বিদ্রুপ রূপে","root":"هزا","lemma":"هُزُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":9810,"position":8,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":9811,"position":9,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে রয়েছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":9812,"position":10,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9813,"position":11,"text_uthmani":"مُّهِينٌۭ","transliteration":"muhīnun","translation_bn":"অপমানকর","root":"هون","lemma":"مُّهِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":9814,"position":12,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ʿalima min āyātinā shayan ittakhadhahā huzuwan ulāika lahum ʿadhābun muhīnun', 'আমার আয়াতগুলোর কোন কথা যখন সে অবগত হয় তখন তাকে ঠাট্টা বিদ্রূপের বিষয় বানিয়ে নেয়, তাদের জন্য আছে অপমানজনক শাস্তি।', 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.', 'আমার আয়াতগুলোর কোন কথা যখন সে অবগত হয় তখন তাকে ঠাট্টা বিদ্রূপের বিষয় বানিয়ে নেয়, তাদের জন্য আছে অপমানজনক শাস্তি।', 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045009.mp3', now()),
  (45, 10, '', '[{"id":10968,"position":1,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10969,"position":2,"text_uthmani":"وَرَآئِهِمْ","transliteration":"warāihim","translation_bn":"তাদের পিছনে (রয়েছে)","root":"وري","lemma":"وَرَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10970,"position":3,"text_uthmani":"جَهَنَّمُ ۖ","transliteration":"jahannamu","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10972,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10973,"position":5,"text_uthmani":"يُغْنِى","transliteration":"yugh''nī","translation_bn":"কাজে আসবে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10974,"position":6,"text_uthmani":"عَنْهُم","transliteration":"ʿanhum","translation_bn":"তাদের জন্যে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10975,"position":7,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10976,"position":8,"text_uthmani":"كَسَبُوا۟","transliteration":"kasabū","translation_bn":"তারা অর্জন করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10977,"position":9,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"(তার) কোন কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10978,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10979,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10980,"position":12,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10981,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10982,"position":14,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া/ পরিবর্তে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":10983,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10984,"position":16,"text_uthmani":"أَوْلِيَآءَ ۖ","transliteration":"awliyāa","translation_bn":"অভিভাবক রূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10986,"position":17,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদের জন্যে রয়েছে","root":"—","lemma":"وَلَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10987,"position":18,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":10988,"position":19,"text_uthmani":"عَظِيمٌ","transliteration":"ʿaẓīmun","translation_bn":"ভয়ানক","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":10989,"position":20,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'min warāihim jahannamu walā yugh''nī ʿanhum mā kasabū shayan walā mā ittakhadhū min dūni l-lahi awliyāa walahum ʿadhābun ʿaẓīmun', 'তাদের আড়ালে আছে জাহান্নাম, তাদের কৃতকর্ম তাদের কোন কাজে আসবে না। আর আল্লাহর পরিবর্তে তারা যেগুলোকে অভিভাবক হিসেবে গ্রহণ করেছে সেগুলোও (কাজে আসবে) না। তাদের জন্য আছে মহা শাস্তি।', 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment.', 'তাদের আড়ালে আছে জাহান্নাম, তাদের কৃতকর্ম তাদের কোন কাজে আসবে না। আর আল্লাহর পরিবর্তে তারা যেগুলোকে অভিভাবক হিসেবে গ্রহণ করেছে সেগুলোও (কাজে আসবে) না। তাদের জন্য আছে মহা শাস্তি।', 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045010.mp3', now()),
  (45, 11, '', '[{"id":12272,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই (কুরআন)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":12273,"position":2,"text_uthmani":"هُدًۭى ۖ","transliteration":"hudan","translation_bn":"সৎপথের দিশারি","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":12275,"position":3,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12276,"position":4,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12277,"position":5,"text_uthmani":"بِـَٔايَـٰتِ","transliteration":"biāyāti","translation_bn":"নিদর্শনাবলীকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":12278,"position":6,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12279,"position":7,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে রয়েছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12280,"position":8,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12281,"position":9,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12282,"position":10,"text_uthmani":"رِّجْزٍ","transliteration":"rij''zin","translation_bn":"(বড় কঠিন) শাস্তি","root":"رجز","lemma":"رِجْز","grammar_bn":"বিশেষ্য (Noun)"},{"id":12283,"position":11,"text_uthmani":"أَلِيمٌ","transliteration":"alīmun","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":12284,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā hudan wa-alladhīna kafarū biāyāti rabbihim lahum ʿadhābun min rij''zin alīmun', 'এ (কুরআন) সঠিক পথের দিশারী। যারা তাদের পালনকর্তার নিদর্শনগুলোকে প্রত্যাখ্যান করে, তাদের জন্য আছে কঠোর যন্ত্রণাদায়ক শাস্তি।', 'This [Qur''an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.', 'এ (কুরআন) সঠিক পথের দিশারী। যারা তাদের পালনকর্তার নিদর্শনগুলোকে প্রত্যাখ্যান করে, তাদের জন্য আছে কঠোর যন্ত্রণাদায়ক শাস্তি।', 'This [Qur''an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045011.mp3', now()),
  (45, 12, '', '[{"id":13615,"position":1,"text_uthmani":"۞ ٱللَّهُ","transliteration":"al-lahu","translation_bn":"(তিনিই) আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13616,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13617,"position":3,"text_uthmani":"سَخَّرَ","transliteration":"sakhara","translation_bn":"অধীন করে দিয়েছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13618,"position":4,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":13619,"position":5,"text_uthmani":"ٱلْبَحْرَ","transliteration":"l-baḥra","translation_bn":"সমুদ্রকে","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":13620,"position":6,"text_uthmani":"لِتَجْرِىَ","transliteration":"litajriya","translation_bn":"যেন চলাচল করতে থাকে","root":"جري","lemma":"جَرَيْ","grammar_bn":"শব্দ"},{"id":13621,"position":7,"text_uthmani":"ٱلْفُلْكُ","transliteration":"l-ful''ku","translation_bn":"নৌযানসমূহ","root":"فلك","lemma":"فُلْك","grammar_bn":"শব্দ"},{"id":13622,"position":8,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13623,"position":9,"text_uthmani":"بِأَمْرِهِۦ","transliteration":"bi-amrihi","translation_bn":"তাঁর নির্দেশের মাধ্যমে","root":"امر","lemma":"أَمْر","grammar_bn":"অব্যয় (Preposition)"},{"id":13624,"position":10,"text_uthmani":"وَلِتَبْتَغُوا۟","transliteration":"walitabtaghū","translation_bn":"এবং যেন তোমরা সন্ধান করতে পার","root":"بغي","lemma":"ٱبْتَغَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13625,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13626,"position":12,"text_uthmani":"فَضْلِهِۦ","transliteration":"faḍlihi","translation_bn":"তাঁর অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":13627,"position":13,"text_uthmani":"وَلَعَلَّكُمْ","transliteration":"walaʿallakum","translation_bn":"এবং যাতে তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13628,"position":14,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"কৃতজ্ঞ হও","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13629,"position":15,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu alladhī sakhara lakumu l-baḥra litajriya l-ful''ku fīhi bi-amrihi walitabtaghū min faḍlihi walaʿallakum tashkurūna', 'আল্লাহ- যিনি সমুদ্রকে তোমাদের কল্যাণে নিয়োজিত করেছেন যাতে তাঁর হুকুমে তোমাদের নৌযানসমূহ তাতে চলাচল করতে পারে, আর যাতে তোমরা তাঁর অনুগ্রহ তালাশ কর এবং তোমরা (তাঁর) শোকর আদায় কর।', 'It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.', 'আল্লাহ- যিনি সমুদ্রকে তোমাদের কল্যাণে নিয়োজিত করেছেন যাতে তাঁর হুকুমে তোমাদের নৌযানসমূহ তাতে চলাচল করতে পারে, আর যাতে তোমরা তাঁর অনুগ্রহ তালাশ কর এবং তোমরা (তাঁর) শোকর আদায় কর।', 'It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045012.mp3', now()),
  (45, 13, '', '[{"id":14810,"position":1,"text_uthmani":"وَسَخَّرَ","transliteration":"wasakhara","translation_bn":"এবং অধীন করে দিয়েছেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14811,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":14812,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14813,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14814,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":14815,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14816,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14817,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":14818,"position":9,"text_uthmani":"جَمِيعًۭا","transliteration":"jamīʿan","translation_bn":"সবকিছুকেই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":14819,"position":10,"text_uthmani":"مِّنْهُ ۚ","transliteration":"min''hu","translation_bn":"তাঁর নিকট হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14821,"position":11,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14822,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে রয়েছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14823,"position":13,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এর","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":14824,"position":14,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":14825,"position":15,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"লোকদের জন্যে (যারা)","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":14826,"position":16,"text_uthmani":"يَتَفَكَّرُونَ","transliteration":"yatafakkarūna","translation_bn":"চিন্তাভাবনা করে","root":"فكر","lemma":"يَتَفَكَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14827,"position":17,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wasakhara lakum mā fī l-samāwāti wamā fī l-arḍi jamīʿan min''hu inna fī dhālika laāyātin liqawmin yatafakkarūna', 'আর তিনি তোমাদের কল্যাণে নিয়োজিত রেখেছেন যা আছে আকাশে আর যা আছে যমীনে সেগুলোর সব কিছুকে। এতে চিন্তাশীল মানুষদের জন্য অবশ্যই অনেক নিদর্শন আছে।', 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.', 'আর তিনি তোমাদের কল্যাণে নিয়োজিত রেখেছেন যা আছে আকাশে আর যা আছে যমীনে সেগুলোর সব কিছুকে। এতে চিন্তাশীল মানুষদের জন্য অবশ্যই অনেক নিদর্শন আছে।', 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045013.mp3', now()),
  (45, 14, '', '[{"id":15887,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15888,"position":2,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের)-কে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":15889,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15890,"position":4,"text_uthmani":"يَغْفِرُوا۟","transliteration":"yaghfirū","translation_bn":"তারা যেন ক্ষমা করে","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15891,"position":5,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের)-কে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":15892,"position":6,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15893,"position":7,"text_uthmani":"يَرْجُونَ","transliteration":"yarjūna","translation_bn":"প্রত্যাশা করে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":15894,"position":8,"text_uthmani":"أَيَّامَ","transliteration":"ayyāma","translation_bn":"(খারাপ) দিনগুলোর","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15895,"position":9,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15896,"position":10,"text_uthmani":"لِيَجْزِىَ","transliteration":"liyajziya","translation_bn":"যেন প্রতিদান দেন তিনি","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"শব্দ"},{"id":15897,"position":11,"text_uthmani":"قَوْمًۢا","transliteration":"qawman","translation_bn":"লোকদেরকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15898,"position":12,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15899,"position":13,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15900,"position":14,"text_uthmani":"يَكْسِبُونَ","transliteration":"yaksibūna","translation_bn":"অর্জন করছিল","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15901,"position":15,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qul lilladhīna āmanū yaghfirū lilladhīna lā yarjūna ayyāma l-lahi liyajziya qawman bimā kānū yaksibūna', 'মু’মিনদেরকে বল ঐ লোকদেরকে ক্ষমা করতে যারা আল্লাহর ‘আযাবের দিন আসার ব্যাপারে কোন আশংকাবোধ করে না। কেননা আল্লাহই (ভাল বা মন্দ) প্রত্যেক সম্প্রদায়কে তাদের কৃতকর্ম অনুসারে প্রতিফল দিবেন।', 'Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn.', 'মু’মিনদেরকে বল ঐ লোকদেরকে ক্ষমা করতে যারা আল্লাহর ‘আযাবের দিন আসার ব্যাপারে কোন আশংকাবোধ করে না। কেননা আল্লাহই (ভাল বা মন্দ) প্রত্যেক সম্প্রদায়কে তাদের কৃতকর্ম অনুসারে প্রতিফল দিবেন।', 'Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045014.mp3', now()),
  (45, 15, '', '[{"id":17008,"position":1,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17009,"position":2,"text_uthmani":"عَمِلَ","transliteration":"ʿamila","translation_bn":"কাজ করবে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17010,"position":3,"text_uthmani":"صَـٰلِحًۭا","transliteration":"ṣāliḥan","translation_bn":"সৎ","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":17011,"position":4,"text_uthmani":"فَلِنَفْسِهِۦ ۖ","transliteration":"falinafsihi","translation_bn":"তা তার নিজের জন্যে","root":"نفس","lemma":"نَفْس","grammar_bn":"শব্দ"},{"id":17013,"position":5,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17014,"position":6,"text_uthmani":"أَسَآءَ","transliteration":"asāa","translation_bn":"মন্দ করবে","root":"سوا","lemma":"أَسَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17015,"position":7,"text_uthmani":"فَعَلَيْهَا ۖ","transliteration":"faʿalayhā","translation_bn":"তা তার উপর পড়বে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"শব্দ"},{"id":17017,"position":8,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17018,"position":9,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17019,"position":10,"text_uthmani":"رَبِّكُمْ","transliteration":"rabbikum","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17020,"position":11,"text_uthmani":"تُرْجَعُونَ","transliteration":"tur''jaʿūna","translation_bn":"তোমাদেরকে ফিরিয়ে আনা হবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17021,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'man ʿamila ṣāliḥan falinafsihi waman asāa faʿalayhā thumma ilā rabbikum tur''jaʿūna', 'যে লোক ভাল কাজ করবে, সে তার নিজের কল্যাণেই তা করবে আর যে মন্দ কাজ করবে তার কুফল সে-ই ভোগ করবে। অতঃপর তোমাদেরকে তোমাদের প্রতিপালকের নিকট ফিরিয়ে নেয়া হবে।', 'Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned.', 'যে লোক ভাল কাজ করবে, সে তার নিজের কল্যাণেই তা করবে আর যে মন্দ কাজ করবে তার কুফল সে-ই ভোগ করবে। অতঃপর তোমাদেরকে তোমাদের প্রতিপালকের নিকট ফিরিয়ে নেয়া হবে।', 'Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045015.mp3', now()),
  (45, 16, '', '[{"id":18113,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18114,"position":2,"text_uthmani":"ءَاتَيْنَا","transliteration":"ātaynā","translation_bn":"আমরা দিয়েছিলাম","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":18115,"position":3,"text_uthmani":"بَنِىٓ","transliteration":"banī","translation_bn":"বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18116,"position":4,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাইলকে","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18117,"position":5,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":18118,"position":6,"text_uthmani":"وَٱلْحُكْمَ","transliteration":"wal-ḥuk''ma","translation_bn":"ও কর্তৃত্ব","root":"حكم","lemma":"حُكْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18119,"position":7,"text_uthmani":"وَٱلنُّبُوَّةَ","transliteration":"wal-nubuwata","translation_bn":"ও নবুয়ত","root":"نبا","lemma":"نُّبُوَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18120,"position":8,"text_uthmani":"وَرَزَقْنَـٰهُم","transliteration":"warazaqnāhum","translation_bn":"এবং তাদের আমরা জীবিকা দিয়েছিলাম","root":"رزق","lemma":"رَزَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18121,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18122,"position":10,"text_uthmani":"ٱلطَّيِّبَـٰتِ","transliteration":"l-ṭayibāti","translation_bn":"উত্তম বস্তু","root":"طيب","lemma":"طَيِّبَٰت","grammar_bn":"শব্দ"},{"id":18123,"position":11,"text_uthmani":"وَفَضَّلْنَـٰهُمْ","transliteration":"wafaḍḍalnāhum","translation_bn":"এবং আমরা তাদেরকে মর্যাদা দিয়েছিলাম","root":"فضل","lemma":"فَضَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18124,"position":12,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18125,"position":13,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"সারা দুনিয়ার (মানুষের)","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":18126,"position":14,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ātaynā banī is''rāīla l-kitāba wal-ḥuk''ma wal-nubuwata warazaqnāhum mina l-ṭayibāti wafaḍḍalnāhum ʿalā l-ʿālamīna', 'আমি বানী ইসরাঈলকে কিতাব, রাজত্ব ও নুবুওয়াত দিয়েছিলাম আর তাদেরকে দিয়েছিলাম উত্তম রিযক, আর তাদেরকে বিশ্ববাসীর উপর শ্রেষ্ঠত্ব দিয়েছিলাম।', 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.', 'আমি বানী ইসরাঈলকে কিতাব, রাজত্ব ও নুবুওয়াত দিয়েছিলাম আর তাদেরকে দিয়েছিলাম উত্তম রিযক, আর তাদেরকে বিশ্ববাসীর উপর শ্রেষ্ঠত্ব দিয়েছিলাম।', 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045016.mp3', now()),
  (45, 17, '', '[{"id":19141,"position":1,"text_uthmani":"وَءَاتَيْنَـٰهُم","transliteration":"waātaynāhum","translation_bn":"এবং তাদেরকে আমরা দিয়েছি","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19142,"position":2,"text_uthmani":"بَيِّنَـٰتٍۢ","transliteration":"bayyinātin","translation_bn":"সুস্পষ্ট প্রমাণ","root":"بين","lemma":"بَيِّنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19143,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"সম্পর্কে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19144,"position":4,"text_uthmani":"ٱلْأَمْرِ ۖ","transliteration":"l-amri","translation_bn":"(দ্বীনের) নির্দেশ","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":19146,"position":5,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর নি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19147,"position":6,"text_uthmani":"ٱخْتَلَفُوٓا۟","transliteration":"ikh''talafū","translation_bn":"(মতবিরোধ করেছিল) বাড়াবাড়ি করে","root":"خلف","lemma":"ٱخْتَلَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19148,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"কিন্তু","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":19149,"position":8,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19150,"position":9,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"এরপরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19151,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19152,"position":11,"text_uthmani":"جَآءَهُمُ","transliteration":"jāahumu","translation_bn":"তাদের কাছে এসেছিল","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19153,"position":12,"text_uthmani":"ٱلْعِلْمُ","transliteration":"l-ʿil''mu","translation_bn":"(নির্ভুল) জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"শব্দ"},{"id":19154,"position":13,"text_uthmani":"بَغْيًۢا","transliteration":"baghyan","translation_bn":"বাড়াবাড়ি করে","root":"بغي","lemma":"بَغْي","grammar_bn":"বিশেষ্য (Noun)"},{"id":19155,"position":14,"text_uthmani":"بَيْنَهُمْ ۚ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":19157,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19158,"position":16,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19159,"position":17,"text_uthmani":"يَقْضِى","transliteration":"yaqḍī","translation_bn":"মীমাংসা করে দিবেন","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":19160,"position":18,"text_uthmani":"بَيْنَهُمْ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":19161,"position":19,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19162,"position":20,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"কিয়ামতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":19163,"position":21,"text_uthmani":"فِيمَا","transliteration":"fīmā","translation_bn":"সে বিষয়ে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19164,"position":22,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19165,"position":23,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"যার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19166,"position":24,"text_uthmani":"يَخْتَلِفُونَ","transliteration":"yakhtalifūna","translation_bn":"মতবিরোধ করত","root":"خلف","lemma":"ٱخْتَلَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19167,"position":25,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'waātaynāhum bayyinātin mina l-amri famā ikh''talafū illā min baʿdi mā jāahumu l-ʿil''mu baghyan baynahum inna rabbaka yaqḍī baynahum yawma l-qiyāmati fīmā kānū fīhi yakhtalifūna', 'আর দ্বীনের ব্যাপারে তাদেরকে দিয়েছিলাম সুস্পষ্ট নিদর্শন। কিন্তু তাদের কাছে (সত্য মিথ্যা সম্পর্কিত নির্ভুল) জ্ঞান আসার পরও শুধু নিজেদের মধ্যে বাড়াবাড়ির কারণে তারা মতভেদ করেছিল। তারা যে বিষয়ে মতভেদ করত, তোমার প্রতিপালক কিয়ামাতের দিন সে বিষয়ে তাদের মধ্যে ফয়সালা করে দেবেন।', 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', 'আর দ্বীনের ব্যাপারে তাদেরকে দিয়েছিলাম সুস্পষ্ট নিদর্শন। কিন্তু তাদের কাছে (সত্য মিথ্যা সম্পর্কিত নির্ভুল) জ্ঞান আসার পরও শুধু নিজেদের মধ্যে বাড়াবাড়ির কারণে তারা মতভেদ করেছিল। তারা যে বিষয়ে মতভেদ করত, তোমার প্রতিপালক কিয়ামাতের দিন সে বিষয়ে তাদের মধ্যে ফয়সালা করে দেবেন।', 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045017.mp3', now()),
  (45, 18, '', '[{"id":20255,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20256,"position":2,"text_uthmani":"جَعَلْنَـٰكَ","transliteration":"jaʿalnāka","translation_bn":"তোমাকে আমরা প্রতিষ্ঠিত করেছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20257,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20258,"position":4,"text_uthmani":"شَرِيعَةٍۢ","transliteration":"sharīʿatin","translation_bn":"শরীয়তের","root":"شرع","lemma":"شَرِيعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":20259,"position":5,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"সম্পর্কিত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20260,"position":6,"text_uthmani":"ٱلْأَمْرِ","transliteration":"l-amri","translation_bn":"(দ্বীনের) নির্দেশ","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":20261,"position":7,"text_uthmani":"فَٱتَّبِعْهَا","transliteration":"fa-ittabiʿ''hā","translation_bn":"তাই তার অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"শব্দ"},{"id":20262,"position":8,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20263,"position":9,"text_uthmani":"تَتَّبِعْ","transliteration":"tattabiʿ","translation_bn":"অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20264,"position":10,"text_uthmani":"أَهْوَآءَ","transliteration":"ahwāa","translation_bn":"খেয়াল খুশির","root":"هوي","lemma":"أَهْوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":20265,"position":11,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20266,"position":12,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20267,"position":13,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20268,"position":14,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma jaʿalnāka ʿalā sharīʿatin mina l-amri fa-ittabiʿ''hā walā tattabiʿ ahwāa alladhīna lā yaʿlamūna', 'অতঃপর (হে নবী সা.!) আমি তোমাকে দ্বীনের (সঠিক) পথের উপর প্রতিষ্ঠিত করেছি, কাজেই তুমি তারই অনুসরণ কর, আর যারা (দ্বীনের বিধি-বিধান) জানেনা তাদের খেয়ালখুশির অনুসরণ করো না।', 'Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.', 'অতঃপর (হে নবী সা.!) আমি তোমাকে দ্বীনের (সঠিক) পথের উপর প্রতিষ্ঠিত করেছি, কাজেই তুমি তারই অনুসরণ কর, আর যারা (দ্বীনের বিধি-বিধান) জানেনা তাদের খেয়ালখুশির অনুসরণ করো না।', 'Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045018.mp3', now()),
  (45, 19, '', '[{"id":21358,"position":1,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21359,"position":2,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":21360,"position":3,"text_uthmani":"يُغْنُوا۟","transliteration":"yugh''nū","translation_bn":"তারা কাজে আসবে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21361,"position":4,"text_uthmani":"عَنكَ","transliteration":"ʿanka","translation_bn":"তোমার জন্যে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21362,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"(পাকড়াও) হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21363,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21364,"position":7,"text_uthmani":"شَيْـًۭٔا ۚ","transliteration":"shayan","translation_bn":"কিছুমাত্র","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":21366,"position":8,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21367,"position":9,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারীরা","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":21368,"position":10,"text_uthmani":"بَعْضُهُمْ","transliteration":"baʿḍuhum","translation_bn":"তাদের একে","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":21369,"position":11,"text_uthmani":"أَوْلِيَآءُ","transliteration":"awliyāu","translation_bn":"বন্ধু","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21370,"position":12,"text_uthmani":"بَعْضٍۢ ۖ","transliteration":"baʿḍin","translation_bn":"অপরের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":21372,"position":13,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21373,"position":14,"text_uthmani":"وَلِىُّ","transliteration":"waliyyu","translation_bn":"বন্ধু","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21374,"position":15,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীদের","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":21375,"position":16,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'innahum lan yugh''nū ʿanka mina l-lahi shayan wa-inna l-ẓālimīna baʿḍuhum awliyāu baʿḍin wal-lahu waliyyu l-mutaqīna', 'আল্লাহ হতে তারা তোমার কোনই উপকার করতে পারবে না। যালিমরা একে অপরের বন্ধু, আর আল্লাহ মুত্তাকীদের বন্ধু।', 'Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous.', 'আল্লাহ হতে তারা তোমার কোনই উপকার করতে পারবে না। যালিমরা একে অপরের বন্ধু, আর আল্লাহ মুত্তাকীদের বন্ধু।', 'Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045019.mp3', now()),
  (45, 20, '', '[{"id":22408,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22409,"position":2,"text_uthmani":"بَصَـٰٓئِرُ","transliteration":"baṣāiru","translation_bn":"(সঠিক পথের) আলো","root":"بصر","lemma":"بَصِيرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22410,"position":3,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"সব লোকের জন্যে","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":22411,"position":4,"text_uthmani":"وَهُدًۭى","transliteration":"wahudan","translation_bn":"এবং পথনির্দেশ","root":"هدي","lemma":"هُدًى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22412,"position":5,"text_uthmani":"وَرَحْمَةٌۭ","transliteration":"waraḥmatun","translation_bn":"ও অনুগ্রহ","root":"رحم","lemma":"رَحْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22413,"position":6,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"(এমন) লোকদের জন্যে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":22414,"position":7,"text_uthmani":"يُوقِنُونَ","transliteration":"yūqinūna","translation_bn":"(যারা) দৃঢ় বিশ্বাস করে","root":"يقن","lemma":"يُوقِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22415,"position":8,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā baṣāiru lilnnāsi wahudan waraḥmatun liqawmin yūqinūna', 'এ (কুরআন) মানুষের জন্য জ্ঞানের আলো, আর নিশ্চিত বিশ্বাসীদের জন্য পথের দিশারী এবং রহমত স্বরূপ।', 'This [Qur''an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].', 'এ (কুরআন) মানুষের জন্য জ্ঞানের আলো, আর নিশ্চিত বিশ্বাসীদের জন্য পথের দিশারী এবং রহমত স্বরূপ।', 'This [Qur''an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045020.mp3', now()),
  (45, 21, '', '[{"id":23539,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23540,"position":2,"text_uthmani":"حَسِبَ","transliteration":"ḥasiba","translation_bn":"মনে করেছে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23541,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23542,"position":4,"text_uthmani":"ٱجْتَرَحُوا۟","transliteration":"ij''taraḥū","translation_bn":"লিপ্ত রয়েছে","root":"جرح","lemma":"ٱجْتَرَحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23543,"position":5,"text_uthmani":"ٱلسَّيِّـَٔاتِ","transliteration":"l-sayiāti","translation_bn":"পাপকাজ","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"শব্দ"},{"id":23544,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":23545,"position":7,"text_uthmani":"نَّجْعَلَهُمْ","transliteration":"najʿalahum","translation_bn":"তাদেরকে করব আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23546,"position":8,"text_uthmani":"كَٱلَّذِينَ","transliteration":"ka-alladhīna","translation_bn":"(তাদের) মতো যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":23547,"position":9,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23548,"position":10,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23549,"position":11,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":23550,"position":12,"text_uthmani":"سَوَآءًۭ","transliteration":"sawāan","translation_bn":"(উভয়ে) সমান","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23551,"position":13,"text_uthmani":"مَّحْيَاهُمْ","transliteration":"maḥyāhum","translation_bn":"তাদের জীবন","root":"حيي","lemma":"مَّحْيَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":23552,"position":14,"text_uthmani":"وَمَمَاتُهُمْ ۚ","transliteration":"wamamātuhum","translation_bn":"ও তাদের মৃত্যু (এক রকম হবে)","root":"موت","lemma":"مَمَات","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23554,"position":15,"text_uthmani":"سَآءَ","transliteration":"sāa","translation_bn":"কত মন্দ","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23555,"position":16,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23556,"position":17,"text_uthmani":"يَحْكُمُونَ","transliteration":"yaḥkumūna","translation_bn":"তারা মীমাংসা করে","root":"حكم","lemma":"حَكَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23557,"position":18,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'am ḥasiba alladhīna ij''taraḥū l-sayiāti an najʿalahum ka-alladhīna āmanū waʿamilū l-ṣāliḥāti sawāan maḥyāhum wamamātuhum sāa mā yaḥkumūna', 'যারা অন্যায় কাজ করে তারা কি এ কথা ভেবে নিয়েছে যে, আমি তাদেরকে আর ঈমান গ্রহণকারী সৎকর্মশীলদেরকে সমান গণ্য করব যার ফলে তাদের উভয় দলের জীবন ও মৃত্যু সমান হয়ে যাবে? কতই না মন্দ তাদের ফয়সালা!', 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge.', 'যারা অন্যায় কাজ করে তারা কি এ কথা ভেবে নিয়েছে যে, আমি তাদেরকে আর ঈমান গ্রহণকারী সৎকর্মশীলদেরকে সমান গণ্য করব যার ফলে তাদের উভয় দলের জীবন ও মৃত্যু সমান হয়ে যাবে? কতই না মন্দ তাদের ফয়সালা!', 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045021.mp3', now()),
  (45, 22, '', '[{"id":24575,"position":1,"text_uthmani":"وَخَلَقَ","transliteration":"wakhalaqa","translation_bn":"এবং সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24576,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24577,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":24578,"position":4,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24579,"position":5,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"যথাযথভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":24580,"position":6,"text_uthmani":"وَلِتُجْزَىٰ","transliteration":"walituj''zā","translation_bn":"এবং যেন প্রতিদান দেওয়া যায়","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24581,"position":7,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24582,"position":8,"text_uthmani":"نَفْسٍۭ","transliteration":"nafsin","translation_bn":"ব্যক্তিকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":24583,"position":9,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24584,"position":10,"text_uthmani":"كَسَبَتْ","transliteration":"kasabat","translation_bn":"সে অর্জন করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24585,"position":11,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তাদের (উপর)","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24586,"position":12,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24587,"position":13,"text_uthmani":"يُظْلَمُونَ","transliteration":"yuẓ''lamūna","translation_bn":"যুলুম করা হবে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24588,"position":14,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wakhalaqa l-lahu l-samāwāti wal-arḍa bil-ḥaqi walituj''zā kullu nafsin bimā kasabat wahum lā yuẓ''lamūna', 'আল্লাহ আকাশ ও যমীন সৃষ্টি করেছেন এক সত্যিকার লক্ষ্যে যাতে প্রত্যেক ব্যক্তিকে তার কৃতকর্ম অনুযায়ী প্রতিফল দেয়া যেতে পারে, আর তাদের প্রতি কোন যুলম করা হবে না।', 'And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.', 'আল্লাহ আকাশ ও যমীন সৃষ্টি করেছেন এক সত্যিকার লক্ষ্যে যাতে প্রত্যেক ব্যক্তিকে তার কৃতকর্ম অনুযায়ী প্রতিফল দেয়া যেতে পারে, আর তাদের প্রতি কোন যুলম করা হবে না।', 'And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045022.mp3', now()),
  (45, 23, '', '[{"id":25645,"position":1,"text_uthmani":"أَفَرَءَيْتَ","transliteration":"afara-ayta","translation_bn":"তুমি (ভেবে) দেখেছ কি","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":25646,"position":2,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25647,"position":3,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"বানিয়েছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25648,"position":4,"text_uthmani":"إِلَـٰهَهُۥ","transliteration":"ilāhahu","translation_bn":"তার ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":25649,"position":5,"text_uthmani":"هَوَىٰهُ","transliteration":"hawāhu","translation_bn":"নিজ প্রবৃত্তিকে","root":"هوي","lemma":"هَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":25650,"position":6,"text_uthmani":"وَأَضَلَّهُ","transliteration":"wa-aḍallahu","translation_bn":"এবং তাকে পথভ্রষ্ট করেছে","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25651,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25652,"position":8,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"ভিত্তিতে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25653,"position":9,"text_uthmani":"عِلْمٍۢ","transliteration":"ʿil''min","translation_bn":"জ্ঞানের","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":25654,"position":10,"text_uthmani":"وَخَتَمَ","transliteration":"wakhatama","translation_bn":"এবং মোহর মেরে দিয়েছেন","root":"ختم","lemma":"خَتَمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25655,"position":11,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25656,"position":12,"text_uthmani":"سَمْعِهِۦ","transliteration":"samʿihi","translation_bn":"তার কানের","root":"سمع","lemma":"سَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":25657,"position":13,"text_uthmani":"وَقَلْبِهِۦ","transliteration":"waqalbihi","translation_bn":"ও তার অন্তরের","root":"قلب","lemma":"قَلْب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25658,"position":14,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"ও রেখে দিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25659,"position":15,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25660,"position":16,"text_uthmani":"بَصَرِهِۦ","transliteration":"baṣarihi","translation_bn":"তার চোখের","root":"بصر","lemma":"بَصَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25661,"position":17,"text_uthmani":"غِشَـٰوَةًۭ","transliteration":"ghishāwatan","translation_bn":"আবরণ","root":"غشو","lemma":"غِشَٰوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25662,"position":18,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"সুতরাং কে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":25663,"position":19,"text_uthmani":"يَهْدِيهِ","transliteration":"yahdīhi","translation_bn":"তাকে সৎপথ দেখাবে","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":25664,"position":20,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25665,"position":21,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":25666,"position":22,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25668,"position":23,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"তবুও কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":25669,"position":24,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"তোমরা শিক্ষা গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25670,"position":25,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'afara-ayta mani ittakhadha ilāhahu hawāhu wa-aḍallahu l-lahu ʿalā ʿil''min wakhatama ʿalā samʿihi waqalbihi wajaʿala ʿalā baṣarihi ghishāwatan faman yahdīhi min baʿdi l-lahi afalā tadhakkarūna', 'তুমি কি লক্ষ্য করেছ তার প্রতি যে তার খেয়াল-খুশিকে ইলাহ বানিয়ে নিয়েছে? আল্লাহ জেনে শুনেই তাকে পথভ্রষ্ট করেছেন আর তার কানে ও দিলে মোহর মেরে দিয়েছেন আর তার চোখের উপর টেনে দিয়েছেন পর্দা। অতঃপর আল্লাহর পর আর কে (আছে যে) তাকে সঠিক পথ দেখাবে? এরপরও কি তোমরা শিক্ষাগ্রহণ করবে না?', 'Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?', 'তুমি কি লক্ষ্য করেছ তার প্রতি যে তার খেয়াল-খুশিকে ইলাহ বানিয়ে নিয়েছে? আল্লাহ জেনে শুনেই তাকে পথভ্রষ্ট করেছেন আর তার কানে ও দিলে মোহর মেরে দিয়েছেন আর তার চোখের উপর টেনে দিয়েছেন পর্দা। অতঃপর আল্লাহর পর আর কে (আছে যে) তাকে সঠিক পথ দেখাবে? এরপরও কি তোমরা শিক্ষাগ্রহণ করবে না?', 'Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045023.mp3', now()),
  (45, 24, '', '[{"id":26716,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26717,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":26718,"position":3,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"সেটা (অর্থাৎ পূনরুত্থান)","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26719,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"(যদি থাকে) তবে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26720,"position":5,"text_uthmani":"حَيَاتُنَا","transliteration":"ḥayātunā","translation_bn":"আমাদের এ জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"বিশেষ্য (Noun)"},{"id":26721,"position":6,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":26722,"position":7,"text_uthmani":"نَمُوتُ","transliteration":"namūtu","translation_bn":"আমরা মরি","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26723,"position":8,"text_uthmani":"وَنَحْيَا","transliteration":"wanaḥyā","translation_bn":"ও আমরা বাঁচি (তা সব এখানেই)","root":"حيي","lemma":"حَىَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26724,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26725,"position":10,"text_uthmani":"يُهْلِكُنَآ","transliteration":"yuh''likunā","translation_bn":"আমাদের ধ্বংস করে","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26726,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26727,"position":12,"text_uthmani":"ٱلدَّهْرُ ۚ","transliteration":"l-dahru","translation_bn":"কালের (আবর্তন)\"","root":"دهر","lemma":"دَّهْر","grammar_bn":"শব্দ"},{"id":26729,"position":13,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নেই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26730,"position":14,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের কাছে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":26731,"position":15,"text_uthmani":"بِذَٰلِكَ","transliteration":"bidhālika","translation_bn":"এ সম্বন্ধে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":26732,"position":16,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26733,"position":17,"text_uthmani":"عِلْمٍ ۖ","transliteration":"ʿil''min","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26735,"position":18,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":26736,"position":19,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26737,"position":20,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":26738,"position":21,"text_uthmani":"يَظُنُّونَ","transliteration":"yaẓunnūna","translation_bn":"অনুমান করে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26739,"position":22,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū mā hiya illā ḥayātunā l-dun''yā namūtu wanaḥyā wamā yuh''likunā illā l-dahru wamā lahum bidhālika min ʿil''min in hum illā yaẓunnūna', 'তারা বলে- জীবন বলতে তো শুধু আমাদের এ দুনিয়ারই জীবন, আমরা মরি আর বেঁচে থাকি (এখানেই)। কালের প্রবাহ ছাড়া অন্য কিছুই আমাদেরকে ধ্বংস করে না। আসলে এ ব্যাপারে তাদের কোন জ্ঞানই নেই। তারা শুধু ধারণা করে।', 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.', 'তারা বলে- জীবন বলতে তো শুধু আমাদের এ দুনিয়ারই জীবন, আমরা মরি আর বেঁচে থাকি (এখানেই)। কালের প্রবাহ ছাড়া অন্য কিছুই আমাদেরকে ধ্বংস করে না। আসলে এ ব্যাপারে তাদের কোন জ্ঞানই নেই। তারা শুধু ধারণা করে।', 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045024.mp3', now()),
  (45, 25, '', '[{"id":27732,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27733,"position":2,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"আবৃত্তি করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27734,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27735,"position":4,"text_uthmani":"ءَايَـٰتُنَا","transliteration":"āyātunā","translation_bn":"আমাদের আয়াতসমূহকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27736,"position":5,"text_uthmani":"بَيِّنَـٰتٍۢ","transliteration":"bayyinātin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"بَيِّنَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":27737,"position":6,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":27738,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"থাকে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27739,"position":8,"text_uthmani":"حُجَّتَهُمْ","transliteration":"ḥujjatahum","translation_bn":"তাদের যুক্তি","root":"حجج","lemma":"حُجَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27740,"position":9,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":27741,"position":10,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":27742,"position":11,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27743,"position":12,"text_uthmani":"ٱئْتُوا۟","transliteration":"i''tū","translation_bn":"\"তোমরা উপস্থিত হও","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":27744,"position":13,"text_uthmani":"بِـَٔابَآئِنَآ","transliteration":"biābāinā","translation_bn":"আমাদের পিতৃপুরুষদেরকে নিয়ে","root":"ابو","lemma":"ا^بَاء","grammar_bn":"অব্যয় (Preposition)"},{"id":27745,"position":14,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":27746,"position":15,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27747,"position":16,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"সত্যবাদী\"","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":27748,"position":17,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā tut''lā ʿalayhim āyātunā bayyinātin mā kāna ḥujjatahum illā an qālū i''tū biābāinā in kuntum ṣādiqīna', 'তাদের সামনে যখন আমার সুস্পষ্ট আয়াতগুলো পাঠ করা হয়, তখন তাদের কাছে এ কথা বলা ছাড়া আর কোন যুক্তি থাকে না যে, তোমরা যদি সত্যবাদীই হয়ে থাক, তাহলে আমাদের পূর্বপুরুষদেরকে হাজির কর।', 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."', 'তাদের সামনে যখন আমার সুস্পষ্ট আয়াতগুলো পাঠ করা হয়, তখন তাদের কাছে এ কথা বলা ছাড়া আর কোন যুক্তি থাকে না যে, তোমরা যদি সত্যবাদীই হয়ে থাক, তাহলে আমাদের পূর্বপুরুষদেরকে হাজির কর।', 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045025.mp3', now()),
  (45, 26, '', '[{"id":28698,"position":1,"text_uthmani":"قُلِ","transliteration":"quli","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28699,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"\"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":28700,"position":3,"text_uthmani":"يُحْيِيكُمْ","transliteration":"yuḥ''yīkum","translation_bn":"তোমাদেরকে জীবন দেন","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":28701,"position":4,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28702,"position":5,"text_uthmani":"يُمِيتُكُمْ","transliteration":"yumītukum","translation_bn":"তোমাদেরকে মৃত্যু দেন","root":"موت","lemma":"أَمَاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28703,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28704,"position":7,"text_uthmani":"يَجْمَعُكُمْ","transliteration":"yajmaʿukum","translation_bn":"তোমাদেরকে একত্র করবেন","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28705,"position":8,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28706,"position":9,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28707,"position":10,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"কিয়ামতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":28708,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":28709,"position":12,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"কোন সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":28710,"position":13,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে\"","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28711,"position":14,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28712,"position":15,"text_uthmani":"أَكْثَرَ","transliteration":"akthara","translation_bn":"অধিকাংশ","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":28713,"position":16,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষই","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":28714,"position":17,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":28715,"position":18,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28716,"position":19,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'quli l-lahu yuḥ''yīkum thumma yumītukum thumma yajmaʿukum ilā yawmi l-qiyāmati lā rayba fīhi walākinna akthara l-nāsi lā yaʿlamūna', 'বল- আল্লাহই তোমাদেরকে জীবন দান করেন অতঃপর তোমাদের মৃত্যু ঘটান। অতঃপর তিনি তোমাদেরকে ক্বিয়ামতের দিন একত্রিত করবেন যাতে কোন সন্দেহ নেই। কিন্তু অধিকাংশ মানুষ তা জানে না।', 'Say, "Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."', 'বল- আল্লাহই তোমাদেরকে জীবন দান করেন অতঃপর তোমাদের মৃত্যু ঘটান। অতঃপর তিনি তোমাদেরকে ক্বিয়ামতের দিন একত্রিত করবেন যাতে কোন সন্দেহ নেই। কিন্তু অধিকাংশ মানুষ তা জানে না।', 'Say, "Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045026.mp3', now()),
  (45, 27, '', '[{"id":29587,"position":1,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং আল্লাহরই জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29588,"position":2,"text_uthmani":"مُلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":29589,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":29590,"position":4,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29592,"position":5,"text_uthmani":"وَيَوْمَ","transliteration":"wayawma","translation_bn":"এবং যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29593,"position":6,"text_uthmani":"تَقُومُ","transliteration":"taqūmu","translation_bn":"সংঘটিত হবে","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29594,"position":7,"text_uthmani":"ٱلسَّاعَةُ","transliteration":"l-sāʿatu","translation_bn":"কিয়ামত","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":29595,"position":8,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":29596,"position":9,"text_uthmani":"يَخْسَرُ","transliteration":"yakhsaru","translation_bn":"ক্ষতিগ্রস্ত হবে","root":"خسر","lemma":"خَسِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29597,"position":10,"text_uthmani":"ٱلْمُبْطِلُونَ","transliteration":"l-mub''ṭilūna","translation_bn":"মিথ্যাশ্রয়ীরা","root":"بطل","lemma":"مُبْطِلُون","grammar_bn":"শব্দ"},{"id":29598,"position":11,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'walillahi mul''ku l-samāwāti wal-arḍi wayawma taqūmu l-sāʿatu yawma-idhin yakhsaru l-mub''ṭilūna', 'আকাশ ও যমীনের রাজত্ব আল্লাহরই, যে দিন ক্বিয়ামত সংঘটিত হবে, সেদিন মিথ্যার অনুসারীরা ধ্বংস হয়ে যাবে।', 'And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.', 'আকাশ ও যমীনের রাজত্ব আল্লাহরই, যে দিন ক্বিয়ামত সংঘটিত হবে, সেদিন মিথ্যার অনুসারীরা ধ্বংস হয়ে যাবে।', 'And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045027.mp3', now()),
  (45, 28, '', '[{"id":31331,"position":1,"text_uthmani":"وَتَرَىٰ","transliteration":"watarā","translation_bn":"এবং তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31332,"position":2,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31333,"position":3,"text_uthmani":"أُمَّةٍۢ","transliteration":"ummatin","translation_bn":"দলকে","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31334,"position":4,"text_uthmani":"جَاثِيَةًۭ ۚ","transliteration":"jāthiyatan","translation_bn":"নতজানু অবস্থায়","root":"جثو","lemma":"جَاثِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31336,"position":5,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31337,"position":6,"text_uthmani":"أُمَّةٍۢ","transliteration":"ummatin","translation_bn":"দলকে","root":"امم","lemma":"أُمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31338,"position":7,"text_uthmani":"تُدْعَىٰٓ","transliteration":"tud''ʿā","translation_bn":"ডাকা হবে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":31339,"position":8,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31340,"position":9,"text_uthmani":"كِتَـٰبِهَا","transliteration":"kitābihā","translation_bn":"তার আমলনামার","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":31341,"position":10,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"\"(বলা হবে) আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":31342,"position":11,"text_uthmani":"تُجْزَوْنَ","transliteration":"tuj''zawna","translation_bn":"তোমাদের প্রতিফল দেওয়া হবে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31343,"position":12,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31344,"position":13,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31345,"position":14,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"কাজ করছিলে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31346,"position":15,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'watarā kulla ummatin jāthiyatan kullu ummatin tud''ʿā ilā kitābihā l-yawma tuj''zawna mā kuntum taʿmalūna', 'আর প্রত্যেক সম্প্রদায়কে দেখবে নতজানু হয়ে আছে। প্রত্যেক সম্প্রদায়কে তার ‘আমালনামার পানে আহবান করা হবে। (আর বলা হবে) তোমরা যা করতে আজ তার প্রতিফল দেয়া হবে।', 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.', 'আর প্রত্যেক সম্প্রদায়কে দেখবে নতজানু হয়ে আছে। প্রত্যেক সম্প্রদায়কে তার ‘আমালনামার পানে আহবান করা হবে। (আর বলা হবে) তোমরা যা করতে আজ তার প্রতিফল দেয়া হবে।', 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045028.mp3', now()),
  (45, 29, '', '[{"id":31645,"position":1,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":31646,"position":2,"text_uthmani":"كِتَـٰبُنَا","transliteration":"kitābunā","translation_bn":"আমাদের (তৈরী করা) আমলনামা","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":31647,"position":3,"text_uthmani":"يَنطِقُ","transliteration":"yanṭiqu","translation_bn":"কথা বলছে","root":"نطق","lemma":"يَنطِقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31648,"position":4,"text_uthmani":"عَلَيْكُم","transliteration":"ʿalaykum","translation_bn":"তোমাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31649,"position":5,"text_uthmani":"بِٱلْحَقِّ ۚ","transliteration":"bil-ḥaqi","translation_bn":"যথাযথভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":31651,"position":6,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":31652,"position":7,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31653,"position":8,"text_uthmani":"نَسْتَنسِخُ","transliteration":"nastansikhu","translation_bn":"আমরা সংরক্ষণ করি","root":"نسخ","lemma":"نَسْتَنسِخُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31654,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31655,"position":10,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31656,"position":11,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করতে\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31657,"position":12,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'hādhā kitābunā yanṭiqu ʿalaykum bil-ḥaqi innā kunnā nastansikhu mā kuntum taʿmalūna', 'আমার এ কিতাব তোমাদের ব্যাপারে সত্য কথাই বলবে, তোমরা যা করতে আমি তাই-ই লিখে রাখতাম।', 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."', 'আমার এ কিতাব তোমাদের ব্যাপারে সত্য কথাই বলবে, তোমরা যা করতে আমি তাই-ই লিখে রাখতাম।', 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045029.mp3', now()),
  (45, 30, '', '[{"id":32522,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"আর","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":32523,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শর্তবাচক (Conditional)"},{"id":32524,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32525,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করবে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32526,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"নেকীর","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":32527,"position":6,"text_uthmani":"فَيُدْخِلُهُمْ","transliteration":"fayud''khiluhum","translation_bn":"তখন তাদের প্রবেশ করাবেন","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"শব্দ"},{"id":32528,"position":7,"text_uthmani":"رَبُّهُمْ","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":32529,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32530,"position":9,"text_uthmani":"رَحْمَتِهِۦ ۚ","transliteration":"raḥmatihi","translation_bn":"তাঁর রহমতের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":32532,"position":10,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটাাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":32533,"position":11,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সেই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":32534,"position":12,"text_uthmani":"ٱلْفَوْزُ","transliteration":"l-fawzu","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"শব্দ"},{"id":32535,"position":13,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":32536,"position":14,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā alladhīna āmanū waʿamilū l-ṣāliḥāti fayud''khiluhum rabbuhum fī raḥmatihi dhālika huwa l-fawzu l-mubīnu', 'যারা ঈমান আনে আর সৎকর্ম করে তাদের প্রতিপালক তাদেরকে তাঁর রহমাতের মধ্যে দাখিল করবেন। ওটাই সুস্পষ্ট সাফল্য।', 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.', 'যারা ঈমান আনে আর সৎকর্ম করে তাদের প্রতিপালক তাদেরকে তাঁর রহমাতের মধ্যে দাখিল করবেন। ওটাই সুস্পষ্ট সাফল্য।', 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045030.mp3', now()),
  (45, 31, '', '[{"id":33402,"position":1,"text_uthmani":"وَأَمَّا","transliteration":"wa-ammā","translation_bn":"আর","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33403,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শর্তবাচক (Conditional)"},{"id":33404,"position":3,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছিল","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33405,"position":4,"text_uthmani":"أَفَلَمْ","transliteration":"afalam","translation_bn":"\"(তাদের বলা হবে) তবে কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":33406,"position":5,"text_uthmani":"تَكُنْ","transliteration":"takun","translation_bn":"\"হয় নি","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33407,"position":6,"text_uthmani":"ءَايَـٰتِى","transliteration":"āyātī","translation_bn":"আমার নিদর্শনগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33408,"position":7,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"পঠিত","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33409,"position":8,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33410,"position":9,"text_uthmani":"فَٱسْتَكْبَرْتُمْ","transliteration":"fa-is''takbartum","translation_bn":"কিন্তু তোমরা অহংকার করেছিলে","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"শব্দ"},{"id":33411,"position":10,"text_uthmani":"وَكُنتُمْ","transliteration":"wakuntum","translation_bn":"এবং তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33412,"position":11,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":33413,"position":12,"text_uthmani":"مُّجْرِمِينَ","transliteration":"muj''rimīna","translation_bn":"অপরাধী\"","root":"جرم","lemma":"مُجْرِم","grammar_bn":"বিশেষণ (Adjective)"},{"id":33414,"position":13,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā alladhīna kafarū afalam takun āyātī tut''lā ʿalaykum fa-is''takbartum wakuntum qawman muj''rimīna', 'আর যারা কুফরী করেছিল তাদেরকে বলা হবে- আমার আয়াতগুলো কি তোমাদের কাছে পাঠ করা হয়নি? তখন তোমরা অহঙ্কার করেছিলে আর তোমরা ছিলে এক অপরাধী জাতি।', 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a people of criminals?', 'আর যারা কুফরী করেছিল তাদেরকে বলা হবে- আমার আয়াতগুলো কি তোমাদের কাছে পাঠ করা হয়নি? তখন তোমরা অহঙ্কার করেছিলে আর তোমরা ছিলে এক অপরাধী জাতি।', 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a people of criminals?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045031.mp3', now()),
  (45, 32, '', '[{"id":34934,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34935,"position":2,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হতো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34936,"position":3,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":34937,"position":4,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"ওয়াদা","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":34938,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":34939,"position":6,"text_uthmani":"حَقٌّۭ","transliteration":"ḥaqqun","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":34940,"position":7,"text_uthmani":"وَٱلسَّاعَةُ","transliteration":"wal-sāʿatu","translation_bn":"এবং কিয়ামত (এমন যে)","root":"سوع","lemma":"سَاعَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34941,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":34942,"position":9,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"কোনো সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":34943,"position":10,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34944,"position":11,"text_uthmani":"قُلْتُم","transliteration":"qul''tum","translation_bn":"তোমরা বলতে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34945,"position":12,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":34946,"position":13,"text_uthmani":"نَدْرِى","transliteration":"nadrī","translation_bn":"আমরা জানি","root":"دري","lemma":"تَدْرِى","grammar_bn":"ক্রিয়া (Verb)"},{"id":34947,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি (জিনিস)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":34948,"position":15,"text_uthmani":"ٱلسَّاعَةُ","transliteration":"l-sāʿatu","translation_bn":"কিয়ামত","root":"سوع","lemma":"سَاعَة","grammar_bn":"শব্দ"},{"id":34949,"position":16,"text_uthmani":"إِن","transliteration":"in","translation_bn":"না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":34950,"position":17,"text_uthmani":"نَّظُنُّ","transliteration":"naẓunnu","translation_bn":"আমরা ধারণা করি","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34951,"position":18,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":34952,"position":19,"text_uthmani":"ظَنًّۭا","transliteration":"ẓannan","translation_bn":"(সাধারণ) অনুমান নির্ভর কথা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":34953,"position":20,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34954,"position":21,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":34955,"position":22,"text_uthmani":"بِمُسْتَيْقِنِينَ","transliteration":"bimus''tayqinīna","translation_bn":"দৃঢ় বিশ্বাসী\"","root":"يقن","lemma":"مُسْتَيْقِنِين","grammar_bn":"অব্যয় (Preposition)"},{"id":34956,"position":23,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā qīla inna waʿda l-lahi ḥaqqun wal-sāʿatu lā rayba fīhā qul''tum mā nadrī mā l-sāʿatu in naẓunnu illā ẓannan wamā naḥnu bimus''tayqinīna', 'যখন বলা হয়- আল্লাহর প্রতিশ্রুতি সত্য আর ক্বিয়ামতের আগমনে কোনই সন্দেহ নেই, তখন তোমরা বলতে- ‘আমরা জানি না ক্বিয়ামত কী? আমরা মনে করি তা শুধু ধারণা মাত্র, আর (তাতে) আমরা নিশ্চিত বিশ্বাসী নই’।', 'And when it was said, ''Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,'' you said, ''We know not what is the Hour. We assume only assumption, and we are not convinced.'' "', 'যখন বলা হয়- আল্লাহর প্রতিশ্রুতি সত্য আর ক্বিয়ামতের আগমনে কোনই সন্দেহ নেই, তখন তোমরা বলতে- ‘আমরা জানি না ক্বিয়ামত কী? আমরা মনে করি তা শুধু ধারণা মাত্র, আর (তাতে) আমরা নিশ্চিত বিশ্বাসী নই’।', 'And when it was said, ''Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,'' you said, ''We know not what is the Hour. We assume only assumption, and we are not convinced.'' "', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045032.mp3', now()),
  (45, 33, '', '[{"id":35362,"position":1,"text_uthmani":"وَبَدَا","transliteration":"wabadā","translation_bn":"এবং প্রকাশ হবে","root":"بدو","lemma":"بَدَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35363,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের কাছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":35364,"position":3,"text_uthmani":"سَيِّـَٔاتُ","transliteration":"sayyiātu","translation_bn":"মন্দ কাজগুলো","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":35365,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":35366,"position":5,"text_uthmani":"عَمِلُوا۟","transliteration":"ʿamilū","translation_bn":"তারা করেছিলো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35367,"position":6,"text_uthmani":"وَحَاقَ","transliteration":"waḥāqa","translation_bn":"এবং ঘিরে ফেলবে","root":"حيق","lemma":"حَاقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35368,"position":7,"text_uthmani":"بِهِم","transliteration":"bihim","translation_bn":"তাদেরকে","root":"—","lemma":"بِهِم","grammar_bn":"অব্যয় (Preposition)"},{"id":35369,"position":8,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":35370,"position":9,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35371,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সে সম্বন্ধে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":35372,"position":11,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"বিদ্রুপ করত","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35373,"position":12,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'wabadā lahum sayyiātu mā ʿamilū waḥāqa bihim mā kānū bihi yastahziūna', 'তারা যে সব মন্দ কাজ করত সেগুলো তাদের কাছে প্রকাশ হয়ে পড়বে আর তারা যা নিয়ে ঠাট্টা বিদ্রূপ করত তা তাদেরকে ঘিরে ফেলবে।', 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.', 'তারা যে সব মন্দ কাজ করত সেগুলো তাদের কাছে প্রকাশ হয়ে পড়বে আর তারা যা নিয়ে ঠাট্টা বিদ্রূপ করত তা তাদেরকে ঘিরে ফেলবে।', 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045033.mp3', now()),
  (45, 34, '', '[{"id":36252,"position":1,"text_uthmani":"وَقِيلَ","transliteration":"waqīla","translation_bn":"এবং বলা হবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36253,"position":2,"text_uthmani":"ٱلْيَوْمَ","transliteration":"l-yawma","translation_bn":"\"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":36254,"position":3,"text_uthmani":"نَنسَىٰكُمْ","transliteration":"nansākum","translation_bn":"তোমাদেরকে ভুলে যাব আমরা","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36255,"position":4,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36256,"position":5,"text_uthmani":"نَسِيتُمْ","transliteration":"nasītum","translation_bn":"তোমরা ভুলে গিয়েছিলে","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36257,"position":6,"text_uthmani":"لِقَآءَ","transliteration":"liqāa","translation_bn":"সাক্ষাতকে","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":36258,"position":7,"text_uthmani":"يَوْمِكُمْ","transliteration":"yawmikum","translation_bn":"তোমাদের দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":36259,"position":8,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":36260,"position":9,"text_uthmani":"وَمَأْوَىٰكُمُ","transliteration":"wamawākumu","translation_bn":"এবং তোমাদের আশ্রয়স্থল","root":"اوي","lemma":"مَأْوَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36261,"position":10,"text_uthmani":"ٱلنَّارُ","transliteration":"l-nāru","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":36262,"position":11,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং নেই","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":36263,"position":12,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":36264,"position":13,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কেউ","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36265,"position":14,"text_uthmani":"نَّـٰصِرِينَ","transliteration":"nāṣirīna","translation_bn":"সাহায্যকারীদের","root":"نصر","lemma":"نَاصِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36266,"position":15,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'waqīla l-yawma nansākum kamā nasītum liqāa yawmikum hādhā wamawākumu l-nāru wamā lakum min nāṣirīna', 'আর বলা হবে- ‘আজ আমি তোমাদেরকে ভুলে যাব যেমন করে তোমরা এ দিনের সাক্ষাৎকে ভুলে গিয়েছিলে। তোমাদের বাসস্থান হবে জাহান্নাম আর তোমাদের কোন সাহায্যকারী থাকবে না।', 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.', 'আর বলা হবে- ‘আজ আমি তোমাদেরকে ভুলে যাব যেমন করে তোমরা এ দিনের সাক্ষাৎকে ভুলে গিয়েছিলে। তোমাদের বাসস্থান হবে জাহান্নাম আর তোমাদের কোন সাহায্যকারী থাকবে না।', 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045034.mp3', now()),
  (45, 35, '', '[{"id":37046,"position":1,"text_uthmani":"ذَٰلِكُم","transliteration":"dhālikum","translation_bn":"এটা তোমাদের","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":37047,"position":2,"text_uthmani":"بِأَنَّكُمُ","transliteration":"bi-annakumu","translation_bn":"এ কারণে যে","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":37048,"position":3,"text_uthmani":"ٱتَّخَذْتُمْ","transliteration":"ittakhadhtum","translation_bn":"তোমরা গ্রহণ করেছিলে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37049,"position":4,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"নিদর্শনাবলীকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":37050,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":37051,"position":6,"text_uthmani":"هُزُوًۭا","transliteration":"huzuwan","translation_bn":"বিদ্রুপরূপে","root":"هزا","lemma":"هُزُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":37052,"position":7,"text_uthmani":"وَغَرَّتْكُمُ","transliteration":"wagharratkumu","translation_bn":"ও তোমাদেরকে ধোঁকা দিয়েছিল","root":"غرر","lemma":"غَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37053,"position":8,"text_uthmani":"ٱلْحَيَوٰةُ","transliteration":"l-ḥayatu","translation_bn":"জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":37054,"position":9,"text_uthmani":"ٱلدُّنْيَا ۚ","transliteration":"l-dun''yā","translation_bn":"পার্থিব\"","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":37056,"position":10,"text_uthmani":"فَٱلْيَوْمَ","transliteration":"fal-yawma","translation_bn":"সুতরাং আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":37057,"position":11,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":37058,"position":12,"text_uthmani":"يُخْرَجُونَ","transliteration":"yukh''rajūna","translation_bn":"তাদের বের করা হবে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37059,"position":13,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37060,"position":14,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37061,"position":15,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তাদেরকে","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":37062,"position":16,"text_uthmani":"يُسْتَعْتَبُونَ","transliteration":"yus''taʿtabūna","translation_bn":"সন্তুষ্টি লাভের সুযোগ দেওয়া হবে","root":"عتب","lemma":"يَسْتَعْتِبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37063,"position":17,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'dhālikum bi-annakumu ittakhadhtum āyāti l-lahi huzuwan wagharratkumu l-ḥayatu l-dun''yā fal-yawma lā yukh''rajūna min''hā walā hum yus''taʿtabūna', 'এটা এজন্য যে, তোমরা আল্লাহর আয়াতগুলোকে ঠাট্টা বিদ্রূপের বিষয় বানিয়ে নিয়েছিলে, আর দুনিয়ার জীবন তোমাদেরকে ধোঁকায় ফেলে রেখেছিল। কাজেই আজ তাদেরকে জাহান্নাম থেকে বের করা হবে না আর তাওবাহ করার সুযোগ দেয়া হবে না।', 'That is because you took the verses of Allah in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allah].', 'এটা এজন্য যে, তোমরা আল্লাহর আয়াতগুলোকে ঠাট্টা বিদ্রূপের বিষয় বানিয়ে নিয়েছিলে, আর দুনিয়ার জীবন তোমাদেরকে ধোঁকায় ফেলে রেখেছিল। কাজেই আজ তাদেরকে জাহান্নাম থেকে বের করা হবে না আর তাওবাহ করার সুযোগ দেয়া হবে না।', 'That is because you took the verses of Allah in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045035.mp3', now()),
  (45, 36, '', '[{"id":37888,"position":1,"text_uthmani":"فَلِلَّهِ","transliteration":"falillahi","translation_bn":"সুতরাং আল্লাহর জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":37889,"position":2,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":37890,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(যিনি) রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37891,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":37892,"position":5,"text_uthmani":"وَرَبِّ","transliteration":"warabbi","translation_bn":"ও রব","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37893,"position":6,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":37894,"position":7,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":37895,"position":8,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":37896,"position":9,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'falillahi l-ḥamdu rabbi l-samāwāti warabbi l-arḍi rabbi l-ʿālamīna', 'অতএব প্রশংসা আল্লাহরই জন্য যিনি আসমানের প্রতিপালনকারী, যমীনের প্রতিপালনকারী, বিশ্বজগতের প্রতিপালনকারী।', 'Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.', 'অতএব প্রশংসা আল্লাহরই জন্য যিনি আসমানের প্রতিপালনকারী, যমীনের প্রতিপালনকারী, বিশ্বজগতের প্রতিপালনকারী।', 'Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045036.mp3', now()),
  (45, 37, '', '[{"id":38727,"position":1,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"এবং তাঁরই জন্যে","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38728,"position":2,"text_uthmani":"ٱلْكِبْرِيَآءُ","transliteration":"l-kib''riyāu","translation_bn":"গৌরব-গরিমা","root":"كبر","lemma":"كِبْرِيَا^ء","grammar_bn":"শব্দ"},{"id":38729,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38730,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":38731,"position":5,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38733,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38734,"position":7,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":38735,"position":8,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":38736,"position":9,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'walahu l-kib''riyāu fī l-samāwāti wal-arḍi wahuwa l-ʿazīzu l-ḥakīmu', 'আকাশ ও যমীনে তাঁরই শ্রেষ্ঠত্ব ও প্রাধান্য, আর তিনি মহাপরাক্রমশালী, প্রজ্ঞাময়।', 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.', 'আকাশ ও যমীনে তাঁরই শ্রেষ্ঠত্ব ও প্রাধান্য, আর তিনি মহাপরাক্রমশালী, প্রজ্ঞাময়।', 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/045037.mp3', now())
