  (46, 1, '', '[{"id":175,"position":1,"text_uthmani":"حمٓ","transliteration":"hha-meem","translation_bn":"হা-মীম","root":"—","lemma":"حمٓ","grammar_bn":"শব্দ"},{"id":176,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hha-meem', 'হা-মীম।', 'Ha, Meem.', 'হা-মীম।', 'Ha, Meem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046001.mp3', now()),
  (46, 2, '', '[{"id":1012,"position":1,"text_uthmani":"تَنزِيلُ","transliteration":"tanzīlu","translation_bn":"অবতীর্ণ করা","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1013,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"এই কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1014,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1015,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1016,"position":5,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"(যিনি) পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":1017,"position":6,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"মহাবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1018,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'tanzīlu l-kitābi mina l-lahi l-ʿazīzi l-ḥakīmi', 'কিতাব অবতীর্ণ হয়েছে মহা পরাক্রমশালী প্রজ্ঞাময় আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', 'কিতাব অবতীর্ণ হয়েছে মহা পরাক্রমশালী প্রজ্ঞাময় আল্লাহর নিকট হতে।', 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046002.mp3', now()),
  (46, 3, '', '[{"id":2104,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2105,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2106,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":2107,"position":4,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"আর (না)পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2108,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু (আছে)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2109,"position":6,"text_uthmani":"بَيْنَهُمَآ","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":2110,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2111,"position":8,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"যথাযথভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2112,"position":9,"text_uthmani":"وَأَجَلٍۢ","transliteration":"wa-ajalin","translation_bn":"এবং একটা সময়ের (জন্যে)","root":"اجل","lemma":"أَجَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2113,"position":10,"text_uthmani":"مُّسَمًّۭى ۚ","transliteration":"musamman","translation_bn":"সুনির্দিষ্ট","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষ্য (Noun)"},{"id":2115,"position":11,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"কিন্তু যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2116,"position":12,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2117,"position":13,"text_uthmani":"عَمَّآ","transliteration":"ʿammā","translation_bn":"সে সম্পর্কে যার","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2118,"position":14,"text_uthmani":"أُنذِرُوا۟","transliteration":"undhirū","translation_bn":"তাদেরকে সতর্ক করা হয়েছে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2119,"position":15,"text_uthmani":"مُعْرِضُونَ","transliteration":"muʿ''riḍūna","translation_bn":"(তা হতে) তারা মুখ ফিরিয়ে নিয়েছে","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":2120,"position":16,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'mā khalaqnā l-samāwāti wal-arḍa wamā baynahumā illā bil-ḥaqi wa-ajalin musamman wa-alladhīna kafarū ʿammā undhirū muʿ''riḍūna', 'আমি আকাশ, যমীন ও এ দু’য়ের মাঝে যা আছে তা প্রকৃত উদ্দেশ্যে একটা নির্দিষ্ট সময়ের জন্য সৃষ্টি করেছি। কিন্তু কাফিরগণ, যে বিষয়ে তাদেরকে সতর্ক করা হয় তাত্থেকে মুখ ফিরিয়ে নেয়।', 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.', 'আমি আকাশ, যমীন ও এ দু’য়ের মাঝে যা আছে তা প্রকৃত উদ্দেশ্যে একটা নির্দিষ্ট সময়ের জন্য সৃষ্টি করেছি। কিন্তু কাফিরগণ, যে বিষয়ে তাদেরকে সতর্ক করা হয় তাত্থেকে মুখ ফিরিয়ে নেয়।', 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046003.mp3', now()),
  (46, 4, '', '[{"id":3373,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3374,"position":2,"text_uthmani":"أَرَءَيْتُم","transliteration":"ara-aytum","translation_bn":"\"তোমরা কি (ভেবে) দেখেছ","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":3375,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যাদেরকে","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3376,"position":4,"text_uthmani":"تَدْعُونَ","transliteration":"tadʿūna","translation_bn":"তোমরা ডাক","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":3377,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3378,"position":6,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":3379,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহকে (তারা কারা?)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3380,"position":8,"text_uthmani":"أَرُونِى","transliteration":"arūnī","translation_bn":"আমাকে দেখাও","root":"راي","lemma":"أَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3381,"position":9,"text_uthmani":"مَاذَا","transliteration":"mādhā","translation_bn":"কি","root":"—","lemma":"مَاذَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":3382,"position":10,"text_uthmani":"خَلَقُوا۟","transliteration":"khalaqū","translation_bn":"তারা সৃষ্টি করেছে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3383,"position":11,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3384,"position":12,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":3385,"position":13,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3386,"position":14,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে আছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":3387,"position":15,"text_uthmani":"شِرْكٌۭ","transliteration":"shir''kun","translation_bn":"কোন অংশ","root":"شرك","lemma":"شِرْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":3388,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3389,"position":17,"text_uthmani":"ٱلسَّمَـٰوَٰتِ ۖ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3391,"position":18,"text_uthmani":"ٱئْتُونِى","transliteration":"i''tūnī","translation_bn":"আমার কাছে আন","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3392,"position":19,"text_uthmani":"بِكِتَـٰبٍۢ","transliteration":"bikitābin","translation_bn":"কোন বই নিয়ে (এর সমর্থনে)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"অব্যয় (Preposition)"},{"id":3393,"position":20,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3394,"position":21,"text_uthmani":"قَبْلِ","transliteration":"qabli","translation_bn":"পূর্বের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3395,"position":22,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এর","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3396,"position":23,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3397,"position":24,"text_uthmani":"أَثَـٰرَةٍۢ","transliteration":"athāratin","translation_bn":"ঐতিহ্যগত","root":"اثر","lemma":"أَثَٰرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3398,"position":25,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3399,"position":26,"text_uthmani":"عِلْمٍ","transliteration":"ʿil''min","translation_bn":"জ্ঞান","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3400,"position":27,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":3401,"position":28,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3402,"position":29,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"সত্যবাদী\"","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":3403,"position":30,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'qul ara-aytum mā tadʿūna min dūni l-lahi arūnī mādhā khalaqū mina l-arḍi am lahum shir''kun fī l-samāwāti i''tūnī bikitābin min qabli hādhā aw athāratin min ʿil''min in kuntum ṣādiqīna', 'বল- তোমরা আল্লাহর পরিবর্তে যাদেরকে ডাক, তাদের বিষয়ে চিন্তা করে দেখেছ কি? দেখাও আমাকে তারা যমীনে কী সৃষ্টি করেছে অথবা আকাশমন্ডলে তাদের কোন অংশীদারিত্ব আছে কি? এর আগের কোন কিতাব অথবা পরম্পরাগত কোন জ্ঞান আমার কাছে উপস্থিত কর যদি তোমরা সত্যবাদী হও।', 'Say, [O Muhammad], "Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."', 'বল- তোমরা আল্লাহর পরিবর্তে যাদেরকে ডাক, তাদের বিষয়ে চিন্তা করে দেখেছ কি? দেখাও আমাকে তারা যমীনে কী সৃষ্টি করেছে অথবা আকাশমন্ডলে তাদের কোন অংশীদারিত্ব আছে কি? এর আগের কোন কিতাব অথবা পরম্পরাগত কোন জ্ঞান আমার কাছে উপস্থিত কর যদি তোমরা সত্যবাদী হও।', 'Say, [O Muhammad], "Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046004.mp3', now()),
  (46, 5, '', '[{"id":4772,"position":1,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং কে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4773,"position":2,"text_uthmani":"أَضَلُّ","transliteration":"aḍallu","translation_bn":"অধিক বিভ্রান্ত (হতে পারে)","root":"ضلل","lemma":"أَضَلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4774,"position":3,"text_uthmani":"مِمَّن","transliteration":"mimman","translation_bn":"তার চেয়ে যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4775,"position":4,"text_uthmani":"يَدْعُوا۟","transliteration":"yadʿū","translation_bn":"ডাকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":4776,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4777,"position":6,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":4778,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4779,"position":8,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(এমন সত্তাকে) যা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4780,"position":9,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4781,"position":10,"text_uthmani":"يَسْتَجِيبُ","transliteration":"yastajību","translation_bn":"ডাকে সাড়া দেবে","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4782,"position":11,"text_uthmani":"لَهُۥٓ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":4783,"position":12,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4784,"position":13,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4785,"position":14,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"কিয়ামতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":4786,"position":15,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4787,"position":16,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"সম্বন্ধে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4788,"position":17,"text_uthmani":"دُعَآئِهِمْ","transliteration":"duʿāihim","translation_bn":"তাদের প্রার্থনা","root":"دعو","lemma":"دُعَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":4789,"position":18,"text_uthmani":"غَـٰفِلُونَ","transliteration":"ghāfilūna","translation_bn":"অনবহিত","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4790,"position":19,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'waman aḍallu mimman yadʿū min dūni l-lahi man lā yastajību lahu ilā yawmi l-qiyāmati wahum ʿan duʿāihim ghāfilūna', 'তার চেয়ে অধিক গুমরাহ কে, যে আল্লাহর পরিবর্তে এমন কিছুকে ডাকে যা ক্বিয়ামত পর্যন্ত তাকে সাড়া দেবে না, আর তাদের ডাকাডাকি সম্পর্কেও তারা (একদম) বেখবর?', 'And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware.', 'তার চেয়ে অধিক গুমরাহ কে, যে আল্লাহর পরিবর্তে এমন কিছুকে ডাকে যা ক্বিয়ামত পর্যন্ত তাকে সাড়া দেবে না, আর তাদের ডাকাডাকি সম্পর্কেও তারা (একদম) বেখবর?', 'And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046005.mp3', now()),
  (46, 6, '', '[{"id":6022,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6023,"position":2,"text_uthmani":"حُشِرَ","transliteration":"ḥushira","translation_bn":"একত্র করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6024,"position":3,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"সব মানুষকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":6025,"position":4,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6026,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6027,"position":6,"text_uthmani":"أَعْدَآءًۭ","transliteration":"aʿdāan","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6028,"position":7,"text_uthmani":"وَكَانُوا۟","transliteration":"wakānū","translation_bn":"এবং তারা হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6029,"position":8,"text_uthmani":"بِعِبَادَتِهِمْ","transliteration":"biʿibādatihim","translation_bn":"তাদের উপাসনা সম্বন্ধে","root":"عبد","lemma":"عِبَادَت","grammar_bn":"অব্যয় (Preposition)"},{"id":6030,"position":9,"text_uthmani":"كَـٰفِرِينَ","transliteration":"kāfirīna","translation_bn":"অস্বীকারকারী","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":6031,"position":10,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ḥushira l-nāsu kānū lahum aʿdāan wakānū biʿibādatihim kāfirīna', 'ক্বিয়ামতের দিন মানুষকে যখন একত্রিত করা হবে, তখন ঐগুলো (অর্থাৎ উপাস্যরা) হবে মানুষের শত্রু আর মানুষ যে তাদের ‘ইবাদাত করেছিল তা তারা অস্বীকার করবে।', 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.', 'ক্বিয়ামতের দিন মানুষকে যখন একত্রিত করা হবে, তখন ঐগুলো (অর্থাৎ উপাস্যরা) হবে মানুষের শত্রু আর মানুষ যে তাদের ‘ইবাদাত করেছিল তা তারা অস্বীকার করবে।', 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/046006.mp3', now()),
