  (47, 1, '', '[{"id":179,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":180,"position":2,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":181,"position":3,"text_uthmani":"وَصَدُّوا۟","transliteration":"waṣaddū","translation_bn":"ও বাধা দিয়েছে (লোকদেরকে)","root":"صدد","lemma":"صَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":182,"position":4,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":183,"position":5,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":184,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":185,"position":7,"text_uthmani":"أَضَلَّ","transliteration":"aḍalla","translation_bn":"ব্যর্থ করে দিয়েছেন তিনি","root":"ضلل","lemma":"أَضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":186,"position":8,"text_uthmani":"أَعْمَـٰلَهُمْ","transliteration":"aʿmālahum","translation_bn":"তাদের কর্ম সমূহকে","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":187,"position":9,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna kafarū waṣaddū ʿan sabīli l-lahi aḍalla aʿmālahum', 'যারা কুফুরী করে এবং আল্লাহর পথে বাধা সৃষ্টি করে, আল্লাহ তাদের সকল কর্ম ব্যর্থ করে দেন।', 'Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds.', 'যারা কুফুরী করে এবং আল্লাহর পথে বাধা সৃষ্টি করে, আল্লাহ তাদের সকল কর্ম ব্যর্থ করে দেন।', 'Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/047001.mp3', now()),
  (47, 2, '', '[{"id":1036,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"আর যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1037,"position":2,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1038,"position":3,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1039,"position":4,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকর্মের","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":1040,"position":5,"text_uthmani":"وَءَامَنُوا۟","transliteration":"waāmanū","translation_bn":"এবং ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1041,"position":6,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"(তার উপর) যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1042,"position":7,"text_uthmani":"نُزِّلَ","transliteration":"nuzzila","translation_bn":"অবতীর্ণ করা হয়েছে","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1043,"position":8,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1044,"position":9,"text_uthmani":"مُحَمَّدٍۢ","transliteration":"muḥammadin","translation_bn":"মুহাম্মাদের","root":"—","lemma":"مُحَمَّد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1045,"position":10,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তা","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1046,"position":11,"text_uthmani":"ٱلْحَقُّ","transliteration":"l-ḥaqu","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":1047,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1048,"position":13,"text_uthmani":"رَّبِّهِمْ ۙ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1050,"position":14,"text_uthmani":"كَفَّرَ","transliteration":"kaffara","translation_bn":"(আল্লাহ্‌) মিটিয়ে দিয়েছেন","root":"كفر","lemma":"كَفَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1051,"position":15,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"তাদের হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1052,"position":16,"text_uthmani":"سَيِّـَٔاتِهِمْ","transliteration":"sayyiātihim","translation_bn":"তাদের ত্রুটি সমুহ","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":1053,"position":17,"text_uthmani":"وَأَصْلَحَ","transliteration":"wa-aṣlaḥa","translation_bn":"ও শুধরে দিবেন","root":"صلح","lemma":"أَصْلَحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1054,"position":18,"text_uthmani":"بَالَهُمْ","transliteration":"bālahum","translation_bn":"তাদের অবস্থা","root":"بول","lemma":"بَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":1055,"position":19,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna āmanū waʿamilū l-ṣāliḥāti waāmanū bimā nuzzila ʿalā muḥammadin wahuwa l-ḥaqu min rabbihim kaffara ʿanhum sayyiātihim wa-aṣlaḥa bālahum', 'আর যারা ঈমান আনে ও সৎকর্ম করে আর মুহাম্মাদের প্রতি যা অবতীর্ণ হয়েছে তাতে বিশ্বাস স্থাপন করে- কারণ তা তাদের প্রতিপালকের প্রেরিত সত্য- তিনি তাদের মন্দ কাজগুলো মুছে দেবেন, আর তাদের অবস্থার উন্নতি ঘটাবেন।', 'And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.', 'আর যারা ঈমান আনে ও সৎকর্ম করে আর মুহাম্মাদের প্রতি যা অবতীর্ণ হয়েছে তাতে বিশ্বাস স্থাপন করে- কারণ তা তাদের প্রতিপালকের প্রেরিত সত্য- তিনি তাদের মন্দ কাজগুলো মুছে দেবেন, আর তাদের অবস্থার উন্নতি ঘটাবেন।', 'And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/047002.mp3', now()),
  (47, 3, '', '[{"id":2126,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2127,"position":2,"text_uthmani":"بِأَنَّ","transliteration":"bi-anna","translation_bn":"এ কারণে যে","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2128,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2129,"position":4,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2130,"position":5,"text_uthmani":"ٱتَّبَعُوا۟","transliteration":"ittabaʿū","translation_bn":"তারা অনুসরণ করেছে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2131,"position":6,"text_uthmani":"ٱلْبَـٰطِلَ","transliteration":"l-bāṭila","translation_bn":"মিথ্যাকে","root":"بطل","lemma":"بَٰطِل","grammar_bn":"শব্দ"},{"id":2132,"position":7,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"আর নিশ্চয়ই","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2133,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2134,"position":9,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2135,"position":10,"text_uthmani":"ٱتَّبَعُوا۟","transliteration":"ittabaʿū","translation_bn":"তারা অনুসরণ করেছে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2136,"position":11,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":2137,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"(আগত) পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2138,"position":13,"text_uthmani":"رَّبِّهِمْ ۚ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2140,"position":14,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":2141,"position":15,"text_uthmani":"يَضْرِبُ","transliteration":"yaḍribu","translation_bn":"বর্ণনা করেন","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2142,"position":16,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2143,"position":17,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"লোকদের জন্যে","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":2144,"position":18,"text_uthmani":"أَمْثَـٰلَهُمْ","transliteration":"amthālahum","translation_bn":"তাদের দৃষ্টান্ত সমুহ","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2145,"position":19,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika bi-anna alladhīna kafarū ittabaʿū l-bāṭila wa-anna alladhīna āmanū ittabaʿū l-ḥaqa min rabbihim kadhālika yaḍribu l-lahu lilnnāsi amthālahum', 'এর কারণ এই যে, যারা কুফুরী করে তারা মিথ্যার অনুসরণ করে, আর যারা ঈমান আনে তারা তাদের প্রতিপালকের প্রেরিত সত্যের অনুসরণ করে। এমনিভাবে আল্লাহ মানুষের জন্য তাদের (মধ্যেকার পাপী এবং পুণ্যবানের) দৃষ্টান্ত বর্ণনা করেন।', 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons.', 'এর কারণ এই যে, যারা কুফুরী করে তারা মিথ্যার অনুসরণ করে, আর যারা ঈমান আনে তারা তাদের প্রতিপালকের প্রেরিত সত্যের অনুসরণ করে। এমনিভাবে আল্লাহ মানুষের জন্য তাদের (মধ্যেকার পাপী এবং পুণ্যবানের) দৃষ্টান্ত বর্ণনা করেন।', 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/047003.mp3', now()),
