  (48, 1, '', '[{"id":226,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":227,"position":2,"text_uthmani":"فَتَحْنَا","transliteration":"fataḥnā","translation_bn":"আমরা বিজয় দিয়েছি","root":"فتح","lemma":"فَتَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":228,"position":3,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমাকে (হে নবী)","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":229,"position":4,"text_uthmani":"فَتْحًۭا","transliteration":"fatḥan","translation_bn":"বিজয়","root":"فتح","lemma":"فَتْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":230,"position":5,"text_uthmani":"مُّبِينًۭا","transliteration":"mubīnan","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":231,"position":6,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'innā fataḥnā laka fatḥan mubīnan', 'আমি তোমাকে দিয়েছি স্পষ্ট বিজয়।', 'Indeed, We have given you, [O Muhammad], a clear conquest', 'আমি তোমাকে দিয়েছি স্পষ্ট বিজয়।', 'Indeed, We have given you, [O Muhammad], a clear conquest', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048001.mp3', now()),
  (48, 2, '', '[{"id":1099,"position":1,"text_uthmani":"لِّيَغْفِرَ","transliteration":"liyaghfira","translation_bn":"তিনি ক্ষমা করেন যেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":1100,"position":2,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমাকে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":1101,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1102,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1103,"position":5,"text_uthmani":"تَقَدَّمَ","transliteration":"taqaddama","translation_bn":"পূর্বে হয়েছে","root":"قدم","lemma":"تَقَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1104,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1105,"position":7,"text_uthmani":"ذَنۢبِكَ","transliteration":"dhanbika","translation_bn":"তোমার পাপ","root":"ذنب","lemma":"ذَنب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1106,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1107,"position":9,"text_uthmani":"تَأَخَّرَ","transliteration":"ta-akhara","translation_bn":"পরে হয়েছে","root":"اخر","lemma":"تَأَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1108,"position":10,"text_uthmani":"وَيُتِمَّ","transliteration":"wayutimma","translation_bn":"এবং সম্পূর্ণ করেন (যেন)","root":"تمم","lemma":"أَتَمَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1109,"position":11,"text_uthmani":"نِعْمَتَهُۥ","transliteration":"niʿ''matahu","translation_bn":"তাঁর অনুগ্রহ","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1110,"position":12,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1111,"position":13,"text_uthmani":"وَيَهْدِيَكَ","transliteration":"wayahdiyaka","translation_bn":"ও তোমাকে পরিচালনা করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1112,"position":14,"text_uthmani":"صِرَٰطًۭا","transliteration":"ṣirāṭan","translation_bn":"পথে","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":1113,"position":15,"text_uthmani":"مُّسْتَقِيمًۭا","transliteration":"mus''taqīman","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":1114,"position":16,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'liyaghfira laka l-lahu mā taqaddama min dhanbika wamā ta-akhara wayutimma niʿ''matahu ʿalayka wayahdiyaka ṣirāṭan mus''taqīman', 'যাতে আল্লাহ তোমার আগের ও পিছের যাবতীয় ভুলভ্রান্তি ক্ষমা করেন, তোমার উপর তাঁর নি‘মাত পূর্ণ করেন এবং তোমাকে সরল সঠিক পথে পরিচালিত করেন।', 'That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path', 'যাতে আল্লাহ তোমার আগের ও পিছের যাবতীয় ভুলভ্রান্তি ক্ষমা করেন, তোমার উপর তাঁর নি‘মাত পূর্ণ করেন এবং তোমাকে সরল সঠিক পথে পরিচালিত করেন।', 'That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048002.mp3', now()),
  (48, 3, '', '[{"id":2152,"position":1,"text_uthmani":"وَيَنصُرَكَ","transliteration":"wayanṣuraka","translation_bn":"এবং তোমাকে সাহায্য করেন যেন","root":"نصر","lemma":"نَصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2153,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2154,"position":3,"text_uthmani":"نَصْرًا","transliteration":"naṣran","translation_bn":"সাহায্য","root":"نصر","lemma":"نَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2155,"position":4,"text_uthmani":"عَزِيزًا","transliteration":"ʿazīzan","translation_bn":"বলিষ্ঠ/ জোর","root":"عزز","lemma":"عَزِيز","grammar_bn":"বিশেষণ (Adjective)"},{"id":2156,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wayanṣuraka l-lahu naṣran ʿazīzan', 'আর আল্লাহ তোমাকে প্রবল পরাক্রান্ত সাহায্য দান করেন।', 'And [that] Allah may aid you with a mighty victory.', 'আর আল্লাহ তোমাকে প্রবল পরাক্রান্ত সাহায্য দান করেন।', 'And [that] Allah may aid you with a mighty victory.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048003.mp3', now()),
  (48, 4, '', '[{"id":3464,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই (আল্লাহ)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3465,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3466,"position":3,"text_uthmani":"أَنزَلَ","transliteration":"anzala","translation_bn":"অবতীর্ণ করেছেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3467,"position":4,"text_uthmani":"ٱلسَّكِينَةَ","transliteration":"l-sakīnata","translation_bn":"প্রশান্তি","root":"سكن","lemma":"سَكِينَة","grammar_bn":"শব্দ"},{"id":3468,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3469,"position":6,"text_uthmani":"قُلُوبِ","transliteration":"qulūbi","translation_bn":"অন্তর সমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3470,"position":7,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":3471,"position":8,"text_uthmani":"لِيَزْدَادُوٓا۟","transliteration":"liyazdādū","translation_bn":"তারা বৃদ্ধি করে যেন","root":"زيد","lemma":"ٱزْدَادُ","grammar_bn":"শব্দ"},{"id":3472,"position":9,"text_uthmani":"إِيمَـٰنًۭا","transliteration":"īmānan","translation_bn":"(আরও) ঈমান","root":"امن","lemma":"إِيمَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":3473,"position":10,"text_uthmani":"مَّعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":3474,"position":11,"text_uthmani":"إِيمَـٰنِهِمْ ۗ","transliteration":"īmānihim","translation_bn":"তাদের ঈমানের","root":"امن","lemma":"إِيمَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":3476,"position":12,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং আল্লাহরই জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3477,"position":13,"text_uthmani":"جُنُودُ","transliteration":"junūdu","translation_bn":"সৈন্যসমূহ","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":3478,"position":14,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3479,"position":15,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3481,"position":16,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3482,"position":17,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3483,"position":18,"text_uthmani":"عَلِيمًا","transliteration":"ʿalīman","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3484,"position":19,"text_uthmani":"حَكِيمًۭا","transliteration":"ḥakīman","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":3485,"position":20,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī anzala l-sakīnata fī qulūbi l-mu''minīna liyazdādū īmānan maʿa īmānihim walillahi junūdu l-samāwāti wal-arḍi wakāna l-lahu ʿalīman ḥakīman', 'তিনিই মু’মিনদের দিলে প্রশান্তি নাযিল করেন যাতে তারা তাদের ঈমানের সাথে আরো ঈমান বাড়িয়ে নেয়। আসমান ও যমীনের যাবতীয় বাহিনী আল্লাহর কর্তৃত্বের অধীন। আল্লাহ সর্বজ্ঞ ও প্রজ্ঞাময়।', 'It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise.', 'তিনিই মু’মিনদের দিলে প্রশান্তি নাযিল করেন যাতে তারা তাদের ঈমানের সাথে আরো ঈমান বাড়িয়ে নেয়। আসমান ও যমীনের যাবতীয় বাহিনী আল্লাহর কর্তৃত্বের অধীন। আল্লাহ সর্বজ্ঞ ও প্রজ্ঞাময়।', 'It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048004.mp3', now()),
  (48, 5, '', '[{"id":4819,"position":1,"text_uthmani":"لِّيُدْخِلَ","transliteration":"liyud''khila","translation_bn":"প্রবেশ করান যেন","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"শব্দ"},{"id":4820,"position":2,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিন পুরুষদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":4821,"position":3,"text_uthmani":"وَٱلْمُؤْمِنَـٰتِ","transliteration":"wal-mu''mināti","translation_bn":"ও মু''মিন নারীদেরকে","root":"امن","lemma":"مُّؤْمِنَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4822,"position":4,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4823,"position":5,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4824,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4825,"position":7,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার (যার) নিচ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":4826,"position":8,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারা সমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":4827,"position":9,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"তারা চিরস্থায়ী হবে","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4828,"position":10,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4829,"position":11,"text_uthmani":"وَيُكَفِّرَ","transliteration":"wayukaffira","translation_bn":"এবং মিটিয়ে দেবেন","root":"كفر","lemma":"كَفَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4830,"position":12,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"তাদের হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4831,"position":13,"text_uthmani":"سَيِّـَٔاتِهِمْ ۚ","transliteration":"sayyiātihim","translation_bn":"তাদের দোষত্রুটি সমূহকে","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":4833,"position":14,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হল","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4834,"position":15,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":4835,"position":16,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"নিকট","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":4836,"position":17,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4837,"position":18,"text_uthmani":"فَوْزًا","transliteration":"fawzan","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"বিশেষ্য (Noun)"},{"id":4838,"position":19,"text_uthmani":"عَظِيمًۭا","transliteration":"ʿaẓīman","translation_bn":"বিরাট","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":4839,"position":20,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'liyud''khila l-mu''minīna wal-mu''mināti jannātin tajrī min taḥtihā l-anhāru khālidīna fīhā wayukaffira ʿanhum sayyiātihim wakāna dhālika ʿinda l-lahi fawzan ʿaẓīman', '(তিনি এ কাজ করেন এজন্য) যাতে তিনি মু’মিন পুরুষ ও মু’মিনা নারীকে জান্নাতে প্রবিষ্ট করেন যার তলদেশে ঝর্ণাধারা প্রবাহিত। তাতে তারা চিরকাল থাকবে। তিনি তাদের পাপ মোচন করে দিবেন। আল্লাহর দৃষ্টিতে এটাই বিরাট সাফল্য।', '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -', '(তিনি এ কাজ করেন এজন্য) যাতে তিনি মু’মিন পুরুষ ও মু’মিনা নারীকে জান্নাতে প্রবিষ্ট করেন যার তলদেশে ঝর্ণাধারা প্রবাহিত। তাতে তারা চিরকাল থাকবে। তিনি তাদের পাপ মোচন করে দিবেন। আল্লাহর দৃষ্টিতে এটাই বিরাট সাফল্য।', '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048005.mp3', now()),
  (48, 6, '', '[{"id":6052,"position":1,"text_uthmani":"وَيُعَذِّبَ","transliteration":"wayuʿadhiba","translation_bn":"এবং তিনি শাস্তি দেবেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6053,"position":2,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফেক পুরুষদেরকে","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":6054,"position":3,"text_uthmani":"وَٱلْمُنَـٰفِقَـٰتِ","transliteration":"wal-munāfiqāti","translation_bn":"ও মুনাফেক নারীদেরকে","root":"نفق","lemma":"مُنَٰفِقَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6055,"position":4,"text_uthmani":"وَٱلْمُشْرِكِينَ","transliteration":"wal-mush''rikīna","translation_bn":"এবং মুশরিক পুরুষদেরকে","root":"شرك","lemma":"مُشْرِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6056,"position":5,"text_uthmani":"وَٱلْمُشْرِكَـٰتِ","transliteration":"wal-mush''rikāti","translation_bn":"ও মুশরিক নারীদেরকে","root":"شرك","lemma":"مُشْرِكَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6057,"position":6,"text_uthmani":"ٱلظَّآنِّينَ","transliteration":"l-ẓānīna","translation_bn":"(যারা) ধারণাকারী","root":"ظنن","lemma":"ظَّا^نِّين","grammar_bn":"শব্দ"},{"id":6058,"position":7,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহ সম্পর্কে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":6059,"position":8,"text_uthmani":"ظَنَّ","transliteration":"ẓanna","translation_bn":"ধারণা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6060,"position":9,"text_uthmani":"ٱلسَّوْءِ ۚ","transliteration":"l-sawi","translation_bn":"খারাপ/ ভ্রান্ত","root":"سوا","lemma":"سَوْء","grammar_bn":"শব্দ"},{"id":6062,"position":10,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর (পড়েছে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6063,"position":11,"text_uthmani":"دَآئِرَةُ","transliteration":"dāiratu","translation_bn":"আবর্তন","root":"دور","lemma":"دَا^ئِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6064,"position":12,"text_uthmani":"ٱلسَّوْءِ ۖ","transliteration":"l-sawi","translation_bn":"অকল্যাণকর","root":"سوا","lemma":"سَوْء","grammar_bn":"শব্দ"},{"id":6066,"position":13,"text_uthmani":"وَغَضِبَ","transliteration":"waghaḍiba","translation_bn":"এবং রুষ্ট হয়েছেন","root":"غضب","lemma":"غَضِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6067,"position":14,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6068,"position":15,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6069,"position":16,"text_uthmani":"وَلَعَنَهُمْ","transliteration":"walaʿanahum","translation_bn":"ও তাদেরকে অভিশাপ দিয়েছেন","root":"لعن","lemma":"لَعَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6070,"position":17,"text_uthmani":"وَأَعَدَّ","transliteration":"wa-aʿadda","translation_bn":"এবং প্রস্তুত করে রেখেছেন","root":"عدد","lemma":"أَعَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6071,"position":18,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6072,"position":19,"text_uthmani":"جَهَنَّمَ ۖ","transliteration":"jahannama","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6074,"position":20,"text_uthmani":"وَسَآءَتْ","transliteration":"wasāat","translation_bn":"এবং তা অতিনিকৃষ্ট","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6075,"position":21,"text_uthmani":"مَصِيرًۭا","transliteration":"maṣīran","translation_bn":"গন্তব্য","root":"صير","lemma":"مَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":6076,"position":22,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wayuʿadhiba l-munāfiqīna wal-munāfiqāti wal-mush''rikīna wal-mush''rikāti l-ẓānīna bil-lahi ẓanna l-sawi ʿalayhim dāiratu l-sawi waghaḍiba l-lahu ʿalayhim walaʿanahum wa-aʿadda lahum jahannama wasāat maṣīran', 'আর তিনি মুনাফিক পুরুষ ও মুনাফিকা নারী, মুশরিক পুরুষ ও মুশরিকা নারীকে শাস্তি দিবেন যারা আল্লাহ সম্পর্কে খারাপ ধারণা পোষণ করে। তাদের জন্য আছে অশুভ চক্র। আল্লাহ তাদের উপর রাগান্বিত হয়েছেন আর তাদেরকে লা‘নাত করেছেন। তাদের জন্য প্রস্তুত করে রেখেছেন জাহান্নাম। তা কতই না নিকৃষ্ট আবাসস্থল!', 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.', 'আর তিনি মুনাফিক পুরুষ ও মুনাফিকা নারী, মুশরিক পুরুষ ও মুশরিকা নারীকে শাস্তি দিবেন যারা আল্লাহ সম্পর্কে খারাপ ধারণা পোষণ করে। তাদের জন্য আছে অশুভ চক্র। আল্লাহ তাদের উপর রাগান্বিত হয়েছেন আর তাদেরকে লা‘নাত করেছেন। তাদের জন্য প্রস্তুত করে রেখেছেন জাহান্নাম। তা কতই না নিকৃষ্ট আবাসস্থল!', 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048006.mp3', now()),
  (48, 7, '', '[{"id":7383,"position":1,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7384,"position":2,"text_uthmani":"جُنُودُ","transliteration":"junūdu","translation_bn":"সৈন্যসমূহ","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":7385,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":7386,"position":4,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7388,"position":5,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7389,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7390,"position":7,"text_uthmani":"عَزِيزًا","transliteration":"ʿazīzan","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"বিশেষণ (Adjective)"},{"id":7391,"position":8,"text_uthmani":"حَكِيمًا","transliteration":"ḥakīman","translation_bn":"মহাজ্ঞানী","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":7392,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'walillahi junūdu l-samāwāti wal-arḍi wakāna l-lahu ʿazīzan ḥakīman', 'আসমান ও যমীনের যাবতীয় বাহিনী আল্লাহর কর্তৃত্বের অধীন। আল্লাহ মহা পরাক্রমশালী, মহা প্রজ্ঞাময়।', 'And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise.', 'আসমান ও যমীনের যাবতীয় বাহিনী আল্লাহর কর্তৃত্বের অধীন। আল্লাহ মহা পরাক্রমশালী, মহা প্রজ্ঞাময়।', 'And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048007.mp3', now()),
  (48, 8, '', '[{"id":8672,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8673,"position":2,"text_uthmani":"أَرْسَلْنَـٰكَ","transliteration":"arsalnāka","translation_bn":"তোমাকে আমরা প্রেরণ করেছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8674,"position":3,"text_uthmani":"شَـٰهِدًۭا","transliteration":"shāhidan","translation_bn":"সাক্ষ্যদাতা","root":"شهد","lemma":"شَاهِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":8675,"position":4,"text_uthmani":"وَمُبَشِّرًۭا","transliteration":"wamubashiran","translation_bn":"ও সুসংবাদদাতা হিসেবে","root":"بشر","lemma":"مُبَشِّر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8676,"position":5,"text_uthmani":"وَنَذِيرًۭا","transliteration":"wanadhīran","translation_bn":"এবং সতর্ককারীরূপে","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8677,"position":6,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'innā arsalnāka shāhidan wamubashiran wanadhīran', '(হে রাসূল) আমি তোমাকে (সত্যের) সাক্ষ্যদাতা. (বিশ্বাসীদের জন্য) সুসংবাদদাতা ও (অবিশ্বাসীদের জন্য) সতর্ককারী হিসেবে পাঠিয়েছি।', 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner', '(হে রাসূল) আমি তোমাকে (সত্যের) সাক্ষ্যদাতা. (বিশ্বাসীদের জন্য) সুসংবাদদাতা ও (অবিশ্বাসীদের জন্য) সতর্ককারী হিসেবে পাঠিয়েছি।', 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048008.mp3', now()),
  (48, 9, '', '[{"id":9868,"position":1,"text_uthmani":"لِّتُؤْمِنُوا۟","transliteration":"litu''minū","translation_bn":"যাতে তোমরা ঈমান আন","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":9869,"position":2,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহর উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":9870,"position":3,"text_uthmani":"وَرَسُولِهِۦ","transliteration":"warasūlihi","translation_bn":"ও তাঁর রাসূলের উপর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9871,"position":4,"text_uthmani":"وَتُعَزِّرُوهُ","transliteration":"watuʿazzirūhu","translation_bn":"এবং তাঁকে তোমরা সাহায্য কর","root":"عزر","lemma":"عَزَّرُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9872,"position":5,"text_uthmani":"وَتُوَقِّرُوهُ","transliteration":"watuwaqqirūhu","translation_bn":"ও তাঁকে তোমরা সম্মান কর","root":"وقر","lemma":"تُوَقِّرُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9873,"position":6,"text_uthmani":"وَتُسَبِّحُوهُ","transliteration":"watusabbiḥūhu","translation_bn":"এবং তাঁর (অর্থাৎ আল্লাহর) পবিত্রতা ঘোষণা কর","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9874,"position":7,"text_uthmani":"بُكْرَةًۭ","transliteration":"buk''ratan","translation_bn":"সকালে","root":"بكر","lemma":"بُكْرَة","grammar_bn":"কালবাচক (Time)"},{"id":9875,"position":8,"text_uthmani":"وَأَصِيلًا","transliteration":"wa-aṣīlan","translation_bn":"ও সন্ধ্যায়","root":"اصل","lemma":"أَصِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9876,"position":9,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'litu''minū bil-lahi warasūlihi watuʿazzirūhu watuwaqqirūhu watusabbiḥūhu buk''ratan wa-aṣīlan', 'যেন (ওহে মানুষেরা) তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আন, রসূলকে শক্তি যোগাও আর তাকে সম্মান কর, আর সকাল-সন্ধ্যায় আল্লাহর মহিমা ঘোষণা কর।', 'That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon.', 'যেন (ওহে মানুষেরা) তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আন, রসূলকে শক্তি যোগাও আর তাকে সম্মান কর, আর সকাল-সন্ধ্যায় আল্লাহর মহিমা ঘোষণা কর।', 'That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048009.mp3', now()),
  (48, 10, '', '[{"id":11063,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11064,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11065,"position":3,"text_uthmani":"يُبَايِعُونَكَ","transliteration":"yubāyiʿūnaka","translation_bn":"তোমার কাছে আনুগত্যের শপথ নেয়","root":"بيع","lemma":"بَايَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11066,"position":4,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11067,"position":5,"text_uthmani":"يُبَايِعُونَ","transliteration":"yubāyiʿūna","translation_bn":"তারা আনুগত্যের শপথ নেয়","root":"بيع","lemma":"بَايَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11068,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর (নিকট)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11069,"position":7,"text_uthmani":"يَدُ","transliteration":"yadu","translation_bn":"(ছিল) হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11070,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11071,"position":9,"text_uthmani":"فَوْقَ","transliteration":"fawqa","translation_bn":"উপর","root":"فوق","lemma":"فَوْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":11072,"position":10,"text_uthmani":"أَيْدِيهِمْ ۚ","transliteration":"aydīhim","translation_bn":"তাদের হাতগুলোর","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11074,"position":11,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"সুতরাং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":11075,"position":12,"text_uthmani":"نَّكَثَ","transliteration":"nakatha","translation_bn":"ভঙ্গ করবে (তার ওয়াদা)","root":"نكث","lemma":"نَّكَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11076,"position":13,"text_uthmani":"فَإِنَّمَا","transliteration":"fa-innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":11077,"position":14,"text_uthmani":"يَنكُثُ","transliteration":"yankuthu","translation_bn":"সে ভঙ্গ করবে","root":"نكث","lemma":"نَّكَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11078,"position":15,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11079,"position":16,"text_uthmani":"نَفْسِهِۦ ۖ","transliteration":"nafsihi","translation_bn":"তার নিজের (কৃত ওয়াদা)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":11081,"position":17,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11082,"position":18,"text_uthmani":"أَوْفَىٰ","transliteration":"awfā","translation_bn":"পূর্ণ করবে","root":"وفي","lemma":"أَوْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11083,"position":19,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11084,"position":20,"text_uthmani":"عَـٰهَدَ","transliteration":"ʿāhada","translation_bn":"সে অঙ্গীকার করেছে","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11085,"position":21,"text_uthmani":"عَلَيْهُ","transliteration":"ʿalayhu","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11086,"position":22,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর সাথে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11087,"position":23,"text_uthmani":"فَسَيُؤْتِيهِ","transliteration":"fasayu''tīhi","translation_bn":"তবে তাকে শীঘ্রই দিবেন তিনি","root":"اتي","lemma":"ا^تَى","grammar_bn":"শব্দ"},{"id":11088,"position":24,"text_uthmani":"أَجْرًا","transliteration":"ajran","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11089,"position":25,"text_uthmani":"عَظِيمًۭا","transliteration":"ʿaẓīman","translation_bn":"বিরাট","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":11090,"position":26,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna yubāyiʿūnaka innamā yubāyiʿūna l-laha yadu l-lahi fawqa aydīhim faman nakatha fa-innamā yankuthu ʿalā nafsihi waman awfā bimā ʿāhada ʿalayhu l-laha fasayu''tīhi ajran ʿaẓīman', 'যারা তোমার কাছে বাই‘আত (অর্থাৎ আনুগত্য করার শপথ) করে আসলে তারা আল্লাহর কাছে বাই‘আত করে। তাদের হাতের উপর আছে আল্লাহর হাত। এক্ষণে যে এ ও‘য়াদা ভঙ্গ করে, এ ও‘য়াদা ভঙ্গের কুফল তার নিজেরই উপর পড়বে। আর যে ও‘য়াদা পূর্ণ করবে- যা সে আল্লাহর সঙ্গে করেছে- তিনি অচিরেই তাকে মহা পুরস্কার দান করবেন।', 'Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward.', 'যারা তোমার কাছে বাই‘আত (অর্থাৎ আনুগত্য করার শপথ) করে আসলে তারা আল্লাহর কাছে বাই‘আত করে। তাদের হাতের উপর আছে আল্লাহর হাত। এক্ষণে যে এ ও‘য়াদা ভঙ্গ করে, এ ও‘য়াদা ভঙ্গের কুফল তার নিজেরই উপর পড়বে। আর যে ও‘য়াদা পূর্ণ করবে- যা সে আল্লাহর সঙ্গে করেছে- তিনি অচিরেই তাকে মহা পুরস্কার দান করবেন।', 'Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048010.mp3', now()),
  (48, 11, '', '[{"id":12342,"position":1,"text_uthmani":"سَيَقُولُ","transliteration":"sayaqūlu","translation_bn":"(হে নবী) বলবে শীঘ্রই","root":"قول","lemma":"قَالَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":12343,"position":2,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমাকে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":12344,"position":3,"text_uthmani":"ٱلْمُخَلَّفُونَ","transliteration":"l-mukhalafūna","translation_bn":"পিছনে থেকে যাওয়া লোকেরা","root":"خلف","lemma":"مُخَلَّفُون","grammar_bn":"শব্দ"},{"id":12345,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্যহতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12346,"position":5,"text_uthmani":"ٱلْأَعْرَابِ","transliteration":"l-aʿrābi","translation_bn":"মরুবাসীদের","root":"عرب","lemma":"أَعْرَاب","grammar_bn":"শব্দ"},{"id":12347,"position":6,"text_uthmani":"شَغَلَتْنَآ","transliteration":"shaghalatnā","translation_bn":"\"আমাদেরকে ব্যস্ত রেখেছিল","root":"شغل","lemma":"شَغَلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12348,"position":7,"text_uthmani":"أَمْوَٰلُنَا","transliteration":"amwālunā","translation_bn":"আমাদের ধনসম্পদ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":12349,"position":8,"text_uthmani":"وَأَهْلُونَا","transliteration":"wa-ahlūnā","translation_bn":"ও পরিবার পরিজন","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12350,"position":9,"text_uthmani":"فَٱسْتَغْفِرْ","transliteration":"fa-is''taghfir","translation_bn":"তাই ক্ষমাপ্রার্থনা করুন","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"শব্দ"},{"id":12351,"position":10,"text_uthmani":"لَنَا ۚ","transliteration":"lanā","translation_bn":"আমাদের জন্যে\"","root":"—","lemma":"لَنَا ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":12353,"position":11,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12354,"position":12,"text_uthmani":"بِأَلْسِنَتِهِم","transliteration":"bi-alsinatihim","translation_bn":"তাদের জিহ্বা দিয়ে (এমন কথা)","root":"لسن","lemma":"لِسَان","grammar_bn":"অব্যয় (Preposition)"},{"id":12355,"position":13,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12356,"position":14,"text_uthmani":"لَيْسَ","transliteration":"laysa","translation_bn":"না","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12357,"position":15,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12358,"position":16,"text_uthmani":"قُلُوبِهِمْ ۚ","transliteration":"qulūbihim","translation_bn":"তাদের অন্তরে","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12360,"position":17,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12361,"position":18,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"\"কে তবে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":12362,"position":19,"text_uthmani":"يَمْلِكُ","transliteration":"yamliku","translation_bn":"ক্ষমতা রাখে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12363,"position":20,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":12364,"position":21,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12365,"position":22,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12366,"position":23,"text_uthmani":"شَيْـًٔا","transliteration":"shayan","translation_bn":"কিছুমাত্র (বাঁচাতে)","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12367,"position":24,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":12368,"position":25,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"ইচ্ছে করেন তিনি","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12369,"position":26,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"তোমাদেরকে","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12370,"position":27,"text_uthmani":"ضَرًّا","transliteration":"ḍarran","translation_bn":"ক্ষতি করতে","root":"ضرر","lemma":"ضَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12371,"position":28,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12372,"position":29,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"ইচ্ছে করেন","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12373,"position":30,"text_uthmani":"بِكُمْ","transliteration":"bikum","translation_bn":"তোমাদেরকে","root":"—","lemma":"بِكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12374,"position":31,"text_uthmani":"نَفْعًۢا ۚ","transliteration":"nafʿan","translation_bn":"কল্যাণের (কে রুখতে পারে)","root":"نفع","lemma":"نَفْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":12376,"position":32,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":12377,"position":33,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12378,"position":34,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12379,"position":35,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12380,"position":36,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজকর্ম করছ","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12381,"position":37,"text_uthmani":"خَبِيرًۢا","transliteration":"khabīran","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":12382,"position":38,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'sayaqūlu laka l-mukhalafūna mina l-aʿrābi shaghalatnā amwālunā wa-ahlūnā fa-is''taghfir lanā yaqūlūna bi-alsinatihim mā laysa fī qulūbihim qul faman yamliku lakum mina l-lahi shayan in arāda bikum ḍarran aw arāda bikum nafʿan bal kāna l-lahu bimā taʿmalūna khabīran', '(যুদ্ধ থেকে) পিছ-পড়া বেদুঈনরা তোমাকে বলবে- আমাদের মালধন আর আমাদের পরিবার-পরিজন আমাদেরকে ব্যস্ত রেখেছিল, কাজেই (হে নবী) আপনি আমাদের জন্য ক্ষমা প্রার্থনা করুন। তারা মুখে এমন কথা বলে যা তাদের অন্তরে নেই। (তাদেরকে) বল, আল্লাহ তোমাদের কোন ক্ষতি বা কোন কল্যাণ করার ইচ্ছে করলে তাঁর বিপক্ষে তোমাদের জন্য কিছু করার ক্ষমতা কার আছে? (কারো কোন ওকালতির দরকার নেই) বরং তোমরা যা কর সে বিষয়ে আল্লাহই খবর রাখেন।', 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted.', '(যুদ্ধ থেকে) পিছ-পড়া বেদুঈনরা তোমাকে বলবে- আমাদের মালধন আর আমাদের পরিবার-পরিজন আমাদেরকে ব্যস্ত রেখেছিল, কাজেই (হে নবী) আপনি আমাদের জন্য ক্ষমা প্রার্থনা করুন। তারা মুখে এমন কথা বলে যা তাদের অন্তরে নেই। (তাদেরকে) বল, আল্লাহ তোমাদের কোন ক্ষতি বা কোন কল্যাণ করার ইচ্ছে করলে তাঁর বিপক্ষে তোমাদের জন্য কিছু করার ক্ষমতা কার আছে? (কারো কোন ওকালতির দরকার নেই) বরং তোমরা যা কর সে বিষয়ে আল্লাহই খবর রাখেন।', 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048011.mp3', now()),
  (48, 12, '', '[{"id":13687,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":13688,"position":2,"text_uthmani":"ظَنَنتُمْ","transliteration":"ẓanantum","translation_bn":"তোমরা ধারণা করেছিলে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13689,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":13690,"position":4,"text_uthmani":"لَّن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":13691,"position":5,"text_uthmani":"يَنقَلِبَ","transliteration":"yanqaliba","translation_bn":"ফিরে আসতে পারবে","root":"قلب","lemma":"ٱنقَلَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13692,"position":6,"text_uthmani":"ٱلرَّسُولُ","transliteration":"l-rasūlu","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":13693,"position":7,"text_uthmani":"وَٱلْمُؤْمِنُونَ","transliteration":"wal-mu''minūna","translation_bn":"ও মু''মিনরা","root":"امن","lemma":"مُؤْمِن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13694,"position":8,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13695,"position":9,"text_uthmani":"أَهْلِيهِمْ","transliteration":"ahlīhim","translation_bn":"তাদের পরিবারের","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":13696,"position":10,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"কখনও","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":13697,"position":11,"text_uthmani":"وَزُيِّنَ","transliteration":"wazuyyina","translation_bn":"এবং সুখকর লেগেছিল","root":"زين","lemma":"زَيَّنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13698,"position":12,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":13699,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13700,"position":14,"text_uthmani":"قُلُوبِكُمْ","transliteration":"qulūbikum","translation_bn":"তোমাদের অন্তরের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":13701,"position":15,"text_uthmani":"وَظَنَنتُمْ","transliteration":"waẓanantum","translation_bn":"এবং তোমরা ধারণা করেছিলে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13702,"position":16,"text_uthmani":"ظَنَّ","transliteration":"ẓanna","translation_bn":"একটা ধারণা","root":"ظنن","lemma":"ظَنّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13703,"position":17,"text_uthmani":"ٱلسَّوْءِ","transliteration":"l-sawi","translation_bn":"খারাপ/ ভুল","root":"سوا","lemma":"سَوْء","grammar_bn":"শব্দ"},{"id":13704,"position":18,"text_uthmani":"وَكُنتُمْ","transliteration":"wakuntum","translation_bn":"এবং তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13705,"position":19,"text_uthmani":"قَوْمًۢا","transliteration":"qawman","translation_bn":"সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":13706,"position":20,"text_uthmani":"بُورًۭا","transliteration":"būran","translation_bn":"বড় (খারাপ মানসিকতার)\"","root":"بور","lemma":"بُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":13707,"position":21,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'bal ẓanantum an lan yanqaliba l-rasūlu wal-mu''minūna ilā ahlīhim abadan wazuyyina dhālika fī qulūbikum waẓanantum ẓanna l-sawi wakuntum qawman būran', 'বরং তোমরা ধারণা করেছিলে যে, রসূল ও মু’মিনগণ কক্ষনো তাদের পরিবার পরিজনের কাছে ফিরে আসতে পারবে না, আর এ খেয়ালটা তোমাদের মনে খুবই চমৎকার ক’রে দেয়া হয়েছিল। তোমরা ধারণা করেছিলে বড়ই কু-ধারণা, আসলে তোমরা হলে ধ্বংসের যোগ্য একটা সম্প্রদায়।', 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."', 'বরং তোমরা ধারণা করেছিলে যে, রসূল ও মু’মিনগণ কক্ষনো তাদের পরিবার পরিজনের কাছে ফিরে আসতে পারবে না, আর এ খেয়ালটা তোমাদের মনে খুবই চমৎকার ক’রে দেয়া হয়েছিল। তোমরা ধারণা করেছিলে বড়ই কু-ধারণা, আসলে তোমরা হলে ধ্বংসের যোগ্য একটা সম্প্রদায়।', 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048012.mp3', now()),
  (48, 13, '', '[{"id":14865,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14866,"position":2,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":14867,"position":3,"text_uthmani":"يُؤْمِنۢ","transliteration":"yu''min","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14868,"position":4,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহর উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":14869,"position":5,"text_uthmani":"وَرَسُولِهِۦ","transliteration":"warasūlihi","translation_bn":"ও তাঁর রাসূলের উপর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14870,"position":6,"text_uthmani":"فَإِنَّآ","transliteration":"fa-innā","translation_bn":"নিশ্চয়ই সেক্ষেত্রে আমরা","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":14871,"position":7,"text_uthmani":"أَعْتَدْنَا","transliteration":"aʿtadnā","translation_bn":"আমরা প্রস্তুত করে রেখেছি","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14872,"position":8,"text_uthmani":"لِلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"কাফেরদের জন্য","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":14873,"position":9,"text_uthmani":"سَعِيرًۭا","transliteration":"saʿīran","translation_bn":"জ্বলন্ত আগুন","root":"سعر","lemma":"سَعِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":14874,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'waman lam yu''min bil-lahi warasūlihi fa-innā aʿtadnā lil''kāfirīna saʿīran', 'যারা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করে না, আমি (সে সব) কাফিরদের জন্য প্রস্তুত করে রেখেছি জ্বলন্ত আগুন।', 'And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.', 'যারা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করে না, আমি (সে সব) কাফিরদের জন্য প্রস্তুত করে রেখেছি জ্বলন্ত আগুন।', 'And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048013.mp3', now()),
  (48, 14, '', '[{"id":15929,"position":1,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং আল্লাহরই জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15930,"position":2,"text_uthmani":"مُلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":15931,"position":3,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":15932,"position":4,"text_uthmani":"وَٱلْأَرْضِ ۚ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15934,"position":5,"text_uthmani":"يَغْفِرُ","transliteration":"yaghfiru","translation_bn":"তিনি মাফ করেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15935,"position":6,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15936,"position":7,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15937,"position":8,"text_uthmani":"وَيُعَذِّبُ","transliteration":"wayuʿadhibu","translation_bn":"ও তিনি শাস্তি দেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15938,"position":9,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":15939,"position":10,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15941,"position":11,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"আর হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15942,"position":12,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15943,"position":13,"text_uthmani":"غَفُورًۭا","transliteration":"ghafūran","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":15944,"position":14,"text_uthmani":"رَّحِيمًۭا","transliteration":"raḥīman","translation_bn":"দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":15945,"position":15,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'walillahi mul''ku l-samāwāti wal-arḍi yaghfiru liman yashāu wayuʿadhibu man yashāu wakāna l-lahu ghafūran raḥīman', 'আসমান যমীনের রাজত্ব আল্লাহর; যাকে চান তিনি ক্ষমা করেন, যাকে ইচ্ছে ‘আযাব দেন। আল্লাহ বড়ই ক্ষমাশীল, অতি দয়ালু।', 'And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful.', 'আসমান যমীনের রাজত্ব আল্লাহর; যাকে চান তিনি ক্ষমা করেন, যাকে ইচ্ছে ‘আযাব দেন। আল্লাহ বড়ই ক্ষমাশীল, অতি দয়ালু।', 'And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048014.mp3', now()),
  (48, 15, '', '[{"id":17157,"position":1,"text_uthmani":"سَيَقُولُ","transliteration":"sayaqūlu","translation_bn":"বলবে শীঘ্রই","root":"قول","lemma":"قَالَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":17158,"position":2,"text_uthmani":"ٱلْمُخَلَّفُونَ","transliteration":"l-mukhalafūna","translation_bn":"পিছনে থেকে যাওয়া লোকেরা","root":"خلف","lemma":"مُخَلَّفُون","grammar_bn":"শব্দ"},{"id":17159,"position":3,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":17160,"position":4,"text_uthmani":"ٱنطَلَقْتُمْ","transliteration":"inṭalaqtum","translation_bn":"তোমরা চলবে","root":"طلق","lemma":"ٱنطَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17161,"position":5,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17162,"position":6,"text_uthmani":"مَغَانِمَ","transliteration":"maghānima","translation_bn":"যুদ্ধলব্ধ সম্পদের","root":"غنم","lemma":"مَغَانِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":17163,"position":7,"text_uthmani":"لِتَأْخُذُوهَا","transliteration":"litakhudhūhā","translation_bn":"তা গ্রহণ করার জন্য","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":17164,"position":8,"text_uthmani":"ذَرُونَا","transliteration":"dharūnā","translation_bn":"\"আমাদেরও যেতে দাও","root":"وذر","lemma":"يَذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17165,"position":9,"text_uthmani":"نَتَّبِعْكُمْ ۖ","transliteration":"nattabiʿ''kum","translation_bn":"তোমাদেরকে অনুসরণ করব আমরা\"","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17167,"position":10,"text_uthmani":"يُرِيدُونَ","transliteration":"yurīdūna","translation_bn":"তারা চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17168,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":17169,"position":12,"text_uthmani":"يُبَدِّلُوا۟","transliteration":"yubaddilū","translation_bn":"পরিবর্তন করতে","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17170,"position":13,"text_uthmani":"كَلَـٰمَ","transliteration":"kalāma","translation_bn":"প্রতিশ্রুতি","root":"كلم","lemma":"كَلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":17171,"position":14,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17173,"position":15,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো (তাদেরকে)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17174,"position":16,"text_uthmani":"لَّن","transliteration":"lan","translation_bn":"\"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":17175,"position":17,"text_uthmani":"تَتَّبِعُونَا","transliteration":"tattabiʿūnā","translation_bn":"আমাদের অনুসরণ করবে তোমরা","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17176,"position":18,"text_uthmani":"كَذَٰلِكُمْ","transliteration":"kadhālikum","translation_bn":"তোমাদের সম্পর্কে এরূপ","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":17177,"position":19,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলে দিয়েছেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17178,"position":20,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17179,"position":21,"text_uthmani":"مِن","transliteration":"min","translation_bn":"\"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17180,"position":22,"text_uthmani":"قَبْلُ ۖ","transliteration":"qablu","translation_bn":"পূর্বেই (একথা)\"","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":17182,"position":23,"text_uthmani":"فَسَيَقُولُونَ","transliteration":"fasayaqūlūna","translation_bn":"অতঃপর তারা বলবে অবশ্যই","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":17183,"position":24,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"\"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":17184,"position":25,"text_uthmani":"تَحْسُدُونَنَا ۚ","transliteration":"taḥsudūnanā","translation_bn":"আমাদেরকে তোমরা হিংসা করছ\"","root":"حسد","lemma":"حَسَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17186,"position":26,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"আসলে","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":17187,"position":27,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হলো (এমন লোক যে)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17188,"position":28,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17189,"position":29,"text_uthmani":"يَفْقَهُونَ","transliteration":"yafqahūna","translation_bn":"তারা বুঝে","root":"فقه","lemma":"يَفْقَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17190,"position":30,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":17191,"position":31,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"অতি সামান্য","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":17192,"position":32,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'sayaqūlu l-mukhalafūna idhā inṭalaqtum ilā maghānima litakhudhūhā dharūnā nattabiʿ''kum yurīdūna an yubaddilū kalāma l-lahi qul lan tattabiʿūnā kadhālikum qāla l-lahu min qablu fasayaqūlūna bal taḥsudūnanā bal kānū lā yafqahūna illā qalīlan', 'তোমরা যখন গানীমাতের মাল সংগ্রহ করার জন্য যেতে থাকবে তখন পিছনে থেকে যাওয়া লোকগুলো বলবে- ‘আমাদেরকেও তোমাদের সঙ্গে যেতে দাও। তারা আল্লাহর ফরমানকে বদলে দিতে চায়। বল ‘তোমরা কিছুতেই আমাদের সঙ্গে যেতে পারবে না, (খাইবার অভিযানে অংশগ্রহণ এবং সেখানে পাওয়া গানীমাত কেবল তাদের জন্য যারা ইতোপূর্বে হুদাইবিয়ার সফর ও বাই‘আতে রিয্ওয়ানে অংশ নিয়েছে) এমন কথা আল্লাহ পূর্বেই বলে দিয়েছেন। তখন তারা বলবে- ‘তোমরা বরং আমাদের প্রতি হিংসা পোষণ করছ।’ (এটা যে আল্লাহর হুকুম তা তারা বুঝছে না) বরং তারা খুব কমই বুঝে।', 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allah. Say, "Never will you follow us. Thus did Allah say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.', 'তোমরা যখন গানীমাতের মাল সংগ্রহ করার জন্য যেতে থাকবে তখন পিছনে থেকে যাওয়া লোকগুলো বলবে- ‘আমাদেরকেও তোমাদের সঙ্গে যেতে দাও। তারা আল্লাহর ফরমানকে বদলে দিতে চায়। বল ‘তোমরা কিছুতেই আমাদের সঙ্গে যেতে পারবে না, (খাইবার অভিযানে অংশগ্রহণ এবং সেখানে পাওয়া গানীমাত কেবল তাদের জন্য যারা ইতোপূর্বে হুদাইবিয়ার সফর ও বাই‘আতে রিয্ওয়ানে অংশ নিয়েছে) এমন কথা আল্লাহ পূর্বেই বলে দিয়েছেন। তখন তারা বলবে- ‘তোমরা বরং আমাদের প্রতি হিংসা পোষণ করছ।’ (এটা যে আল্লাহর হুকুম তা তারা বুঝছে না) বরং তারা খুব কমই বুঝে।', 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allah. Say, "Never will you follow us. Thus did Allah say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048015.mp3', now()),
  (48, 16, '', '[{"id":18184,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18185,"position":2,"text_uthmani":"لِّلْمُخَلَّفِينَ","transliteration":"lil''mukhallafīna","translation_bn":"পিছে থেকে যাওয়া লোকদেরকে","root":"خلف","lemma":"مُخَلَّفُون","grammar_bn":"অব্যয় (Preposition)"},{"id":18186,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18187,"position":4,"text_uthmani":"ٱلْأَعْرَابِ","transliteration":"l-aʿrābi","translation_bn":"মরুবাসীদের","root":"عرب","lemma":"أَعْرَاب","grammar_bn":"শব্দ"},{"id":18188,"position":5,"text_uthmani":"سَتُدْعَوْنَ","transliteration":"satud''ʿawna","translation_bn":"\"তোমাদের ডাকা হবে শীঘ্রই (যুদ্ধ করতে)","root":"دعو","lemma":"دَعَا","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":18189,"position":6,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18190,"position":7,"text_uthmani":"قَوْمٍ","transliteration":"qawmin","translation_bn":"এক জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":18191,"position":8,"text_uthmani":"أُو۟لِى","transliteration":"ulī","translation_bn":"সম্পন্ন","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":18192,"position":9,"text_uthmani":"بَأْسٍۢ","transliteration":"basin","translation_bn":"শক্তি","root":"باس","lemma":"بَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":18193,"position":10,"text_uthmani":"شَدِيدٍۢ","transliteration":"shadīdin","translation_bn":"প্রবল","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":18194,"position":11,"text_uthmani":"تُقَـٰتِلُونَهُمْ","transliteration":"tuqātilūnahum","translation_bn":"তাদের সাথে তোমাদের যুদ্ধ করতে হবে","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18195,"position":12,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18196,"position":13,"text_uthmani":"يُسْلِمُونَ ۖ","transliteration":"yus''limūna","translation_bn":"তারা আত্নসমর্পণ করবে","root":"سلم","lemma":"أَسْلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18198,"position":14,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"যদি অতঃপর","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":18199,"position":15,"text_uthmani":"تُطِيعُوا۟","transliteration":"tuṭīʿū","translation_bn":"তোমরা আনুগত্য কর","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18200,"position":16,"text_uthmani":"يُؤْتِكُمُ","transliteration":"yu''tikumu","translation_bn":"তোমাদেরকে দিবেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":18201,"position":17,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18202,"position":18,"text_uthmani":"أَجْرًا","transliteration":"ajran","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18203,"position":19,"text_uthmani":"حَسَنًۭا ۖ","transliteration":"ḥasanan","translation_bn":"উত্তম","root":"حسن","lemma":"حَسَن","grammar_bn":"বিশেষণ (Adjective)"},{"id":18205,"position":20,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18206,"position":21,"text_uthmani":"تَتَوَلَّوْا۟","transliteration":"tatawallaw","translation_bn":"তোমরা পিছে ফের","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18207,"position":22,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18208,"position":23,"text_uthmani":"تَوَلَّيْتُم","transliteration":"tawallaytum","translation_bn":"তোমরা পিছে ফিরেছ","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18209,"position":24,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18210,"position":25,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18211,"position":26,"text_uthmani":"يُعَذِّبْكُمْ","transliteration":"yuʿadhib''kum","translation_bn":"তিনি তোমাদের শাস্তি দিবেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18212,"position":27,"text_uthmani":"عَذَابًا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":18213,"position":28,"text_uthmani":"أَلِيمًۭا","transliteration":"alīman","translation_bn":"যন্ত্রণাদায়ক\"","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":18214,"position":29,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul lil''mukhallafīna mina l-aʿrābi satud''ʿawna ilā qawmin ulī basin shadīdin tuqātilūnahum aw yus''limūna fa-in tuṭīʿū yu''tikumu l-lahu ajran ḥasanan wa-in tatawallaw kamā tawallaytum min qablu yuʿadhib''kum ʿadhāban alīman', 'বেদুঈনদের যারা পেছনে রয়ে গিয়েছিল তাদেরকে বল- ‘তোমাদেরকে যুদ্ধ করতে ডাকা হবে খুবই শক্তিশালী এক জাতির বিরুদ্ধে, তোমরা তাদের বিরুদ্ধে যুদ্ধ করবে অথবা তারা আত্মসমর্পণ করবে। তোমরা যদি তখন তা মান্য কর, আল্লাহ তোমাদেরকে উত্তম পুরস্কার দিবেন। আর যদি পিঠ ফিরিয়ে নাও যেমন তোমরা আগে পিঠ ফিরিয়ে নিয়েছিলে, তাহলে আল্লাহ তোমাদেরকে কষ্টদায়ক শাস্তি দিবেন।', 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."', 'বেদুঈনদের যারা পেছনে রয়ে গিয়েছিল তাদেরকে বল- ‘তোমাদেরকে যুদ্ধ করতে ডাকা হবে খুবই শক্তিশালী এক জাতির বিরুদ্ধে, তোমরা তাদের বিরুদ্ধে যুদ্ধ করবে অথবা তারা আত্মসমর্পণ করবে। তোমরা যদি তখন তা মান্য কর, আল্লাহ তোমাদেরকে উত্তম পুরস্কার দিবেন। আর যদি পিঠ ফিরিয়ে নাও যেমন তোমরা আগে পিঠ ফিরিয়ে নিয়েছিলে, তাহলে আল্লাহ তোমাদেরকে কষ্টদায়ক শাস্তি দিবেন।', 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048016.mp3', now()),
  (48, 17, '', '[{"id":19221,"position":1,"text_uthmani":"لَّيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19222,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19223,"position":3,"text_uthmani":"ٱلْأَعْمَىٰ","transliteration":"l-aʿmā","translation_bn":"অন্ধের","root":"عمي","lemma":"أَعْمَىٰ","grammar_bn":"শব্দ"},{"id":19224,"position":4,"text_uthmani":"حَرَجٌۭ","transliteration":"ḥarajun","translation_bn":"কোনো অপরাধ (জিহাদে না গেলে)","root":"حرج","lemma":"حَرَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":19225,"position":5,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর নেই","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19226,"position":6,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19227,"position":7,"text_uthmani":"ٱلْأَعْرَجِ","transliteration":"l-aʿraji","translation_bn":"পঙ্গুর","root":"عرج","lemma":"أَعْرَج","grammar_bn":"শব্দ"},{"id":19228,"position":8,"text_uthmani":"حَرَجٌۭ","transliteration":"ḥarajun","translation_bn":"কোনো অপরাধ","root":"حرج","lemma":"حَرَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":19229,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19230,"position":10,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19231,"position":11,"text_uthmani":"ٱلْمَرِيضِ","transliteration":"l-marīḍi","translation_bn":"রোগীর","root":"مرض","lemma":"مَّرِيض","grammar_bn":"শব্দ"},{"id":19232,"position":12,"text_uthmani":"حَرَجٌۭ ۗ","transliteration":"ḥarajun","translation_bn":"কোনো অপরাধ","root":"حرج","lemma":"حَرَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":19234,"position":13,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19235,"position":14,"text_uthmani":"يُطِعِ","transliteration":"yuṭiʿi","translation_bn":"আনুগত্য করে","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19236,"position":15,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19237,"position":16,"text_uthmani":"وَرَسُولَهُۥ","transliteration":"warasūlahu","translation_bn":"ও তাঁর রাসুলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19238,"position":17,"text_uthmani":"يُدْخِلْهُ","transliteration":"yud''khil''hu","translation_bn":"তাকে প্রবেশ করাবেন তিনি","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19239,"position":18,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19240,"position":19,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19241,"position":20,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19242,"position":21,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার নিচ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":19243,"position":22,"text_uthmani":"ٱلْأَنْهَـٰرُ ۖ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":19245,"position":23,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19246,"position":24,"text_uthmani":"يَتَوَلَّ","transliteration":"yatawalla","translation_bn":"পিঠ ফিরাবে","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19247,"position":25,"text_uthmani":"يُعَذِّبْهُ","transliteration":"yuʿadhib''hu","translation_bn":"তাকে তিনি শাস্তি দিবেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19248,"position":26,"text_uthmani":"عَذَابًا","transliteration":"ʿadhāban","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":19249,"position":27,"text_uthmani":"أَلِيمًۭا","transliteration":"alīman","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":19250,"position":28,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'laysa ʿalā l-aʿmā ḥarajun walā ʿalā l-aʿraji ḥarajun walā ʿalā l-marīḍi ḥarajun waman yuṭiʿi l-laha warasūlahu yud''khil''hu jannātin tajrī min taḥtihā l-anhāru waman yatawalla yuʿadhib''hu ʿadhāban alīman', 'অন্ধের উপর কোন দোষ নেই, খোঁড়ার উপর কোন দোষ নেই, রোগীর উপর কোন দোষ নেই। আর যে কেউই আল্লাহ ও তাঁর রসূলের আনুগত্য করবে, আল্লাহ তাকে জান্নাতে প্রবিষ্ট করবেন, যার নীচ দিয়ে ঝর্ণাধারা প্রবাহিত। আর যে ব্যক্তি পিঠ ফিরিয়ে নিবে, তিনি তাকে কষ্টদায়ক শাস্তি দিবেন।', 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.', 'অন্ধের উপর কোন দোষ নেই, খোঁড়ার উপর কোন দোষ নেই, রোগীর উপর কোন দোষ নেই। আর যে কেউই আল্লাহ ও তাঁর রসূলের আনুগত্য করবে, আল্লাহ তাকে জান্নাতে প্রবিষ্ট করবেন, যার নীচ দিয়ে ঝর্ণাধারা প্রবাহিত। আর যে ব্যক্তি পিঠ ফিরিয়ে নিবে, তিনি তাকে কষ্টদায়ক শাস্তি দিবেন।', 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048017.mp3', now()),
  (48, 18, '', '[{"id":20316,"position":1,"text_uthmani":"۞ لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20317,"position":2,"text_uthmani":"رَضِىَ","transliteration":"raḍiya","translation_bn":"সন্তুষ্ট হয়েছেন","root":"رضو","lemma":"رَّضِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20318,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20319,"position":4,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"প্রতি","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20320,"position":5,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":20321,"position":6,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":20322,"position":7,"text_uthmani":"يُبَايِعُونَكَ","transliteration":"yubāyiʿūnaka","translation_bn":"তোমার কাছে বায়''আত গ্রহণ করে তারা","root":"بيع","lemma":"بَايَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20323,"position":8,"text_uthmani":"تَحْتَ","transliteration":"taḥta","translation_bn":"নিচে","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":20324,"position":9,"text_uthmani":"ٱلشَّجَرَةِ","transliteration":"l-shajarati","translation_bn":"গাছটির","root":"شجر","lemma":"شَجَرَة","grammar_bn":"শব্দ"},{"id":20325,"position":10,"text_uthmani":"فَعَلِمَ","transliteration":"faʿalima","translation_bn":"তিনি তখন জানতেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20326,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20327,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (ছিল)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20328,"position":13,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"তাদের অন্তরসমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20329,"position":14,"text_uthmani":"فَأَنزَلَ","transliteration":"fa-anzala","translation_bn":"অতঃপর অবতীর্ণ করলেন","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"শব্দ"},{"id":20330,"position":15,"text_uthmani":"ٱلسَّكِينَةَ","transliteration":"l-sakīnata","translation_bn":"প্রশান্তি","root":"سكن","lemma":"سَكِينَة","grammar_bn":"শব্দ"},{"id":20331,"position":16,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20332,"position":17,"text_uthmani":"وَأَثَـٰبَهُمْ","transliteration":"wa-athābahum","translation_bn":"এবং তাদের পুরস্কার দিলেন","root":"ثوب","lemma":"أَثَٰبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20333,"position":18,"text_uthmani":"فَتْحًۭا","transliteration":"fatḥan","translation_bn":"বিজয়ের","root":"فتح","lemma":"فَتْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":20334,"position":19,"text_uthmani":"قَرِيبًۭا","transliteration":"qarīban","translation_bn":"আসন্ন","root":"قرب","lemma":"قَرِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":20335,"position":20,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'laqad raḍiya l-lahu ʿani l-mu''minīna idh yubāyiʿūnaka taḥta l-shajarati faʿalima mā fī qulūbihim fa-anzala l-sakīnata ʿalayhim wa-athābahum fatḥan qarīban', 'মু’মিনদের প্রতি আল্লাহ সন্তুষ্ট হলেন যখন তারা (হুদাইবিয়ায়) গাছের তলে তোমার কাছে বায়‘আত নিল। আল্লাহ জানতেন তাদের অন্তরে কী আছে, এজন্য তিনি তাদের উপর প্রশান্তি অবতীর্ণ করলেন আর পুরস্কার হিসেবে তাদেরকে দিলেন নিকট আসন্ন বিজয়।', 'Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest', 'মু’মিনদের প্রতি আল্লাহ সন্তুষ্ট হলেন যখন তারা (হুদাইবিয়ায়) গাছের তলে তোমার কাছে বায়‘আত নিল। আল্লাহ জানতেন তাদের অন্তরে কী আছে, এজন্য তিনি তাদের উপর প্রশান্তি অবতীর্ণ করলেন আর পুরস্কার হিসেবে তাদেরকে দিলেন নিকট আসন্ন বিজয়।', 'Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048018.mp3', now()),
  (48, 19, '', '[{"id":21413,"position":1,"text_uthmani":"وَمَغَانِمَ","transliteration":"wamaghānima","translation_bn":"এবং যুদ্ধলব্ধ সম্পদসমূহ","root":"غنم","lemma":"مَغَانِم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21414,"position":2,"text_uthmani":"كَثِيرَةًۭ","transliteration":"kathīratan","translation_bn":"বিপুল পরিমাণে","root":"كثر","lemma":"كَثِيرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":21415,"position":3,"text_uthmani":"يَأْخُذُونَهَا ۗ","transliteration":"yakhudhūnahā","translation_bn":"তা তারা গ্রহণ করবে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21417,"position":4,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21418,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21419,"position":6,"text_uthmani":"عَزِيزًا","transliteration":"ʿazīzan","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"বিশেষণ (Adjective)"},{"id":21420,"position":7,"text_uthmani":"حَكِيمًۭا","transliteration":"ḥakīman","translation_bn":"মহাবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":21421,"position":8,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamaghānima kathīratan yakhudhūnahā wakāna l-lahu ʿazīzan ḥakīman', 'আর বিপুল পরিমাণ গানীমাত যা তারা লাভ করবে। আল্লাহ মহা পরাক্রান্ত প্রজ্ঞাময়।', 'And much war booty which they will take. And ever is Allah Exalted in Might and Wise.', 'আর বিপুল পরিমাণ গানীমাত যা তারা লাভ করবে। আল্লাহ মহা পরাক্রান্ত প্রজ্ঞাময়।', 'And much war booty which they will take. And ever is Allah Exalted in Might and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048019.mp3', now()),
  (48, 20, '', '[{"id":22507,"position":1,"text_uthmani":"وَعَدَكُمُ","transliteration":"waʿadakumu","translation_bn":"তোমাদেরকে প্রতিশ্রুতি দিয়েছেন","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22508,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22509,"position":3,"text_uthmani":"مَغَانِمَ","transliteration":"maghānima","translation_bn":"যুদ্ধলব্ধ সম্পদ সমুহের","root":"غنم","lemma":"مَغَانِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22510,"position":4,"text_uthmani":"كَثِيرَةًۭ","transliteration":"kathīratan","translation_bn":"বিপুল পরিমাণ","root":"كثر","lemma":"كَثِيرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":22511,"position":5,"text_uthmani":"تَأْخُذُونَهَا","transliteration":"takhudhūnahā","translation_bn":"তা তোমরা গ্রহণ করবে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22512,"position":6,"text_uthmani":"فَعَجَّلَ","transliteration":"faʿajjala","translation_bn":"এখন তিনি ত্বরান্বিত করেছেন","root":"عجل","lemma":"عَجَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22513,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":22514,"position":8,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22515,"position":9,"text_uthmani":"وَكَفَّ","transliteration":"wakaffa","translation_bn":"এবং বিরত রাখলেন","root":"كفف","lemma":"كَفَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22516,"position":10,"text_uthmani":"أَيْدِىَ","transliteration":"aydiya","translation_bn":"হাতগুলোকে","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":22517,"position":11,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"লোকদের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":22518,"position":12,"text_uthmani":"عَنكُمْ","transliteration":"ʿankum","translation_bn":"তোমাদের থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22519,"position":13,"text_uthmani":"وَلِتَكُونَ","transliteration":"walitakūna","translation_bn":"এবং এটা হয় যেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22520,"position":14,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22521,"position":15,"text_uthmani":"لِّلْمُؤْمِنِينَ","transliteration":"lil''mu''minīna","translation_bn":"মু''মিনদের জন্যে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":22522,"position":16,"text_uthmani":"وَيَهْدِيَكُمْ","transliteration":"wayahdiyakum","translation_bn":"ও তিনি তোমাদের পরিচালনা করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22523,"position":17,"text_uthmani":"صِرَٰطًۭا","transliteration":"ṣirāṭan","translation_bn":"পথে","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":22524,"position":18,"text_uthmani":"مُّسْتَقِيمًۭا","transliteration":"mus''taqīman","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":22525,"position":19,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'waʿadakumu l-lahu maghānima kathīratan takhudhūnahā faʿajjala lakum hādhihi wakaffa aydiya l-nāsi ʿankum walitakūna āyatan lil''mu''minīna wayahdiyakum ṣirāṭan mus''taqīman', 'আল্লাহ তোমাদেরকে বিপুল পরিমাণ গানীমাতের ও‘য়াদা দিয়েছেন যা তোমরা লাভ করবে। এটা তিনি তোমাদেরকে আগেই দিলেন আর মানুষদের (অর্থাৎ মাক্কার কুরায়শদের) হাতকে তোমাদের (উপর পতিত হওয়া) থেকে সংযত করে রাখলেন যাতে তা মু’মিনদের জন্য একটা নিদর্শন হয় (যে প্রকৃত মু’মিনদেরকে আল্লাহ অতি সংকটময় মুহূর্তেও রক্ষা করতে পারেন), আর তিনি তোমাদেরকে সরল সঠিক পথে পরিচালিত করেন।', 'Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.', 'আল্লাহ তোমাদেরকে বিপুল পরিমাণ গানীমাতের ও‘য়াদা দিয়েছেন যা তোমরা লাভ করবে। এটা তিনি তোমাদেরকে আগেই দিলেন আর মানুষদের (অর্থাৎ মাক্কার কুরায়শদের) হাতকে তোমাদের (উপর পতিত হওয়া) থেকে সংযত করে রাখলেন যাতে তা মু’মিনদের জন্য একটা নিদর্শন হয় (যে প্রকৃত মু’মিনদেরকে আল্লাহ অতি সংকটময় মুহূর্তেও রক্ষা করতে পারেন), আর তিনি তোমাদেরকে সরল সঠিক পথে পরিচালিত করেন।', 'Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048020.mp3', now()),
  (48, 21, '', '[{"id":23661,"position":1,"text_uthmani":"وَأُخْرَىٰ","transliteration":"wa-ukh''rā","translation_bn":"এবং অন্যটি","root":"اخر","lemma":"ا^خَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23662,"position":2,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":23663,"position":3,"text_uthmani":"تَقْدِرُوا۟","transliteration":"taqdirū","translation_bn":"তোমরা সক্ষম হও","root":"قدر","lemma":"قَدَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23664,"position":4,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23665,"position":5,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":23666,"position":6,"text_uthmani":"أَحَاطَ","transliteration":"aḥāṭa","translation_bn":"পরিবেষ্টন করে রেখেছেন","root":"حوط","lemma":"أَحَاطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23667,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23668,"position":8,"text_uthmani":"بِهَا ۚ","transliteration":"bihā","translation_bn":"তা","root":"—","lemma":"بِهَا ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":23670,"position":9,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23671,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":23672,"position":11,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23673,"position":12,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23674,"position":13,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুরই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23675,"position":14,"text_uthmani":"قَدِيرًۭا","transliteration":"qadīran","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":23676,"position":15,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ukh''rā lam taqdirū ʿalayhā qad aḥāṭa l-lahu bihā wakāna l-lahu ʿalā kulli shayin qadīran', 'এবং আরো অন্য (সাহায্য, সম্পদ ও বিজয়) যা এখনও তোমাদের অধিকারে আসেনি, আল্লাহ তা স্বীয় আয়ত্তে রেখেছেন, আল্লাহ সকল বিষয়ে ক্ষমতাবান।', 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent.', 'এবং আরো অন্য (সাহায্য, সম্পদ ও বিজয়) যা এখনও তোমাদের অধিকারে আসেনি, আল্লাহ তা স্বীয় আয়ত্তে রেখেছেন, আল্লাহ সকল বিষয়ে ক্ষমতাবান।', 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048021.mp3', now()),
  (48, 22, '', '[{"id":24620,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24621,"position":2,"text_uthmani":"قَـٰتَلَكُمُ","transliteration":"qātalakumu","translation_bn":"তোমাদের সাথে যুদ্ধ করত","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24622,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24623,"position":4,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24624,"position":5,"text_uthmani":"لَوَلَّوُا۟","transliteration":"lawallawū","translation_bn":"অবশ্যই ফিরত তারা","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24625,"position":6,"text_uthmani":"ٱلْأَدْبَـٰرَ","transliteration":"l-adbāra","translation_bn":"পিঠ সমূহকে","root":"دبر","lemma":"دُبُر","grammar_bn":"শব্দ"},{"id":24626,"position":7,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24627,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24628,"position":9,"text_uthmani":"يَجِدُونَ","transliteration":"yajidūna","translation_bn":"তারা পেত","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24629,"position":10,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"কোনো অভিভাবক","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24630,"position":11,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24631,"position":12,"text_uthmani":"نَصِيرًۭا","transliteration":"naṣīran","translation_bn":"কোনো সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":24632,"position":13,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'walaw qātalakumu alladhīna kafarū lawallawū l-adbāra thumma lā yajidūna waliyyan walā naṣīran', 'কাফিরগণ যদি তোমাদের সাথে যুদ্ধ বাঁধাত, তাহলে তারা অবশ্যই পিঠ ফিরিয়ে নিত, সে অবস্থায় তারা কোন পৃষ্ঠপোষক ও সাহায্যকারী পেত না।', 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.', 'কাফিরগণ যদি তোমাদের সাথে যুদ্ধ বাঁধাত, তাহলে তারা অবশ্যই পিঠ ফিরিয়ে নিত, সে অবস্থায় তারা কোন পৃষ্ঠপোষক ও সাহায্যকারী পেত না।', 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048022.mp3', now()),
  (48, 23, '', '[{"id":25707,"position":1,"text_uthmani":"سُنَّةَ","transliteration":"sunnata","translation_bn":"বিধান","root":"سنن","lemma":"سُنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":25708,"position":2,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25709,"position":3,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25710,"position":4,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":25711,"position":5,"text_uthmani":"خَلَتْ","transliteration":"khalat","translation_bn":"অতীত হয়েছে","root":"خلو","lemma":"خَلَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":25712,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25713,"position":7,"text_uthmani":"قَبْلُ ۖ","transliteration":"qablu","translation_bn":"পূর্বেও","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":25715,"position":8,"text_uthmani":"وَلَن","transliteration":"walan","translation_bn":"এবং কখনো না","root":"—","lemma":"لَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25716,"position":9,"text_uthmani":"تَجِدَ","transliteration":"tajida","translation_bn":"পাবে তুমি","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25717,"position":10,"text_uthmani":"لِسُنَّةِ","transliteration":"lisunnati","translation_bn":"বিধানে","root":"سنن","lemma":"سُنَّة","grammar_bn":"অব্যয় (Preposition)"},{"id":25718,"position":11,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25719,"position":12,"text_uthmani":"تَبْدِيلًۭا","transliteration":"tabdīlan","translation_bn":"কোনো পরিবর্তন","root":"بدل","lemma":"تَبْدِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":25720,"position":13,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'sunnata l-lahi allatī qad khalat min qablu walan tajida lisunnati l-lahi tabdīlan', '(এটাই) আল্লাহর বিধান, অতীতেও তাই হয়েছে, তুমি আল্লাহর বিধানে কক্ষনো কোন পরিবর্তন পাবে না।', '[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change.', '(এটাই) আল্লাহর বিধান, অতীতেও তাই হয়েছে, তুমি আল্লাহর বিধানে কক্ষনো কোন পরিবর্তন পাবে না।', '[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048023.mp3', now()),
  (48, 24, '', '[{"id":26772,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26773,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26774,"position":3,"text_uthmani":"كَفَّ","transliteration":"kaffa","translation_bn":"বিরত রেখেছিলেন","root":"كفف","lemma":"كَفَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26775,"position":4,"text_uthmani":"أَيْدِيَهُمْ","transliteration":"aydiyahum","translation_bn":"তাদের হাতগুলোকে","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":26776,"position":5,"text_uthmani":"عَنكُمْ","transliteration":"ʿankum","translation_bn":"তোমাদের হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26777,"position":6,"text_uthmani":"وَأَيْدِيَكُمْ","transliteration":"wa-aydiyakum","translation_bn":"ও তোমাদের হাতগুলোকে","root":"يدي","lemma":"يَد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26778,"position":7,"text_uthmani":"عَنْهُم","transliteration":"ʿanhum","translation_bn":"তাদের হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26779,"position":8,"text_uthmani":"بِبَطْنِ","transliteration":"bibaṭni","translation_bn":"উপকণ্ঠে","root":"بطن","lemma":"بَطْن","grammar_bn":"অব্যয় (Preposition)"},{"id":26780,"position":9,"text_uthmani":"مَكَّةَ","transliteration":"makkata","translation_bn":"মক্কার","root":"—","lemma":"مَكَّة","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26781,"position":10,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26782,"position":11,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"এরপরেও","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":26783,"position":12,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":26784,"position":13,"text_uthmani":"أَظْفَرَكُمْ","transliteration":"aẓfarakum","translation_bn":"তোমাদের বিজয় দিয়েছিলেন","root":"ظفر","lemma":"أَظْفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26785,"position":14,"text_uthmani":"عَلَيْهِمْ ۚ","transliteration":"ʿalayhim","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26787,"position":15,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26788,"position":16,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26789,"position":17,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26790,"position":18,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ কর","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26791,"position":19,"text_uthmani":"بَصِيرًا","transliteration":"baṣīran","translation_bn":"খুব দেখছেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":26792,"position":20,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa alladhī kaffa aydiyahum ʿankum wa-aydiyakum ʿanhum bibaṭni makkata min baʿdi an aẓfarakum ʿalayhim wakāna l-lahu bimā taʿmalūna baṣīran', 'মক্কা উপত্যকায় তিনিই তাদের হাত তোমাদের থেকে আর তোমাদের হাত তাদের থেকে বিরত রেখেছিলেন তোমাদেরকে তাদের উপর বিজয়ী করার পর। তোমরা যা কিছু কর আল্লাহ তা দেখেন।', 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing.', 'মক্কা উপত্যকায় তিনিই তাদের হাত তোমাদের থেকে আর তোমাদের হাত তাদের থেকে বিরত রেখেছিলেন তোমাদেরকে তাদের উপর বিজয়ী করার পর। তোমরা যা কিছু কর আল্লাহ তা দেখেন।', 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/048024.mp3', now()),
