  (51, 34, '', '[{"id":36323,"position":1,"text_uthmani":"مُّسَوَّمَةً","transliteration":"musawwamatan","translation_bn":"চিহ্নিত (হয়ে আছে)","root":"سوم","lemma":"مُّسَوَّمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":36324,"position":2,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":36325,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36326,"position":4,"text_uthmani":"لِلْمُسْرِفِينَ","transliteration":"lil''mus''rifīna","translation_bn":"সীমা লঙ্ঘনকারীদের জন্যে\"","root":"سرف","lemma":"مُسْرِف","grammar_bn":"অব্যয় (Preposition)"},{"id":36327,"position":5,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'musawwamatan ʿinda rabbika lil''mus''rifīna', 'যা তোমার প্রতিপালকের নিকট চিহ্নিত হয়ে আছে সীমালঙ্ঘনকারীদের জন্য।', 'Marked in the presence of your Lord for the transgressors."', 'যা তোমার প্রতিপালকের নিকট চিহ্নিত হয়ে আছে সীমালঙ্ঘনকারীদের জন্য।', 'Marked in the presence of your Lord for the transgressors."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051034.mp3', now()),
  (51, 35, '', '[{"id":37013,"position":1,"text_uthmani":"فَأَخْرَجْنَا","transliteration":"fa-akhrajnā","translation_bn":"এরপর আমরা বের করলাম","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"শব্দ"},{"id":37014,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":37015,"position":3,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37016,"position":4,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37017,"position":5,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37018,"position":6,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":37019,"position":7,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-akhrajnā man kāna fīhā mina l-mu''minīna', 'সেখানে যারা মু’মিন ছিল আমি তাদেরকে বের করে এনেছিলাম,', 'So We brought out whoever was in the cities of the believers.', 'সেখানে যারা মু’মিন ছিল আমি তাদেরকে বের করে এনেছিলাম,', 'So We brought out whoever was in the cities of the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051035.mp3', now()),
