  (51, 37, '', '[{"id":38741,"position":1,"text_uthmani":"وَتَرَكْنَا","transliteration":"wataraknā","translation_bn":"এবং আমরা রেখেছি","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38742,"position":2,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"সেখানে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38743,"position":3,"text_uthmani":"ءَايَةًۭ","transliteration":"āyatan","translation_bn":"একটি নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":38744,"position":4,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":38745,"position":5,"text_uthmani":"يَخَافُونَ","transliteration":"yakhāfūna","translation_bn":"ভয় করে","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38746,"position":6,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":38747,"position":7,"text_uthmani":"ٱلْأَلِيمَ","transliteration":"l-alīma","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"শব্দ"},{"id":38748,"position":8,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'wataraknā fīhā āyatan lilladhīna yakhāfūna l-ʿadhāba l-alīma', 'আর তাদের জন্য সেখানে একটা নিদর্শন রেখে দিলাম যারা অত্যন্ত পীড়াদায়ক ‘আযাবের ভয় করে।', 'And We left therein a sign for those who fear the painful punishment.', 'আর তাদের জন্য সেখানে একটা নিদর্শন রেখে দিলাম যারা অত্যন্ত পীড়াদায়ক ‘আযাবের ভয় করে।', 'And We left therein a sign for those who fear the painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051037.mp3', now()),
  (51, 38, '', '[{"id":39672,"position":1,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং মধ্যে ( নিদর্শন আছে)","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39673,"position":2,"text_uthmani":"مُوسَىٰٓ","transliteration":"mūsā","translation_bn":"মুসার (কাহিনীর)","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":39674,"position":3,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":39675,"position":4,"text_uthmani":"أَرْسَلْنَـٰهُ","transliteration":"arsalnāhu","translation_bn":"তাকে আমরা প্রেরণ করেছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39676,"position":5,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39677,"position":6,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":39678,"position":7,"text_uthmani":"بِسُلْطَـٰنٍۢ","transliteration":"bisul''ṭānin","translation_bn":"প্রমাণসহ","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":39679,"position":8,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":39680,"position":9,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'wafī mūsā idh arsalnāhu ilā fir''ʿawna bisul''ṭānin mubīnin', 'আর মূসার ঘটনাতেও (নিদর্শন আছে) যখন আমি তাকে স্পষ্ট প্রমাণসহ ফেরাউনের কাছে পাঠিয়েছিলাম,', 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.', 'আর মূসার ঘটনাতেও (নিদর্শন আছে) যখন আমি তাকে স্পষ্ট প্রমাণসহ ফেরাউনের কাছে পাঠিয়েছিলাম,', 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051038.mp3', now()),
  (51, 39, '', '[{"id":40464,"position":1,"text_uthmani":"فَتَوَلَّىٰ","transliteration":"fatawallā","translation_bn":"অতঃপর সে মুখ ফিরায়","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"শব্দ"},{"id":40465,"position":2,"text_uthmani":"بِرُكْنِهِۦ","transliteration":"biruk''nihi","translation_bn":"তার সভাসদগণসহ","root":"ركن","lemma":"رُكْن","grammar_bn":"অব্যয় (Preposition)"},{"id":40466,"position":3,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40467,"position":4,"text_uthmani":"سَـٰحِرٌ","transliteration":"sāḥirun","translation_bn":"\"(সে একজন) জাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":40468,"position":5,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40469,"position":6,"text_uthmani":"مَجْنُونٌۭ","transliteration":"majnūnun","translation_bn":"পাগল (জ্বিন আশ্রিত)\"","root":"جنن","lemma":"مَجْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":40470,"position":7,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'fatawallā biruk''nihi waqāla sāḥirun aw majnūnun', 'তখন সে তার ক্ষমতার দাপটে মুখ ফিরিয়ে নিল আর বলল- ‘এ লোক একটা যাদুকর না হয় পাগল।’', 'But he turned away with his supporters and said," A magician or a madman."', 'তখন সে তার ক্ষমতার দাপটে মুখ ফিরিয়ে নিল আর বলল- ‘এ লোক একটা যাদুকর না হয় পাগল।’', 'But he turned away with his supporters and said," A magician or a madman."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051039.mp3', now()),
  (51, 40, '', '[{"id":41163,"position":1,"text_uthmani":"فَأَخَذْنَـٰهُ","transliteration":"fa-akhadhnāhu","translation_bn":"অবশেষে তাকে আমরা পাকড়াও করলাম","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":41164,"position":2,"text_uthmani":"وَجُنُودَهُۥ","transliteration":"wajunūdahu","translation_bn":"ও তার সৈন্যদেরকে","root":"جند","lemma":"جُند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41165,"position":3,"text_uthmani":"فَنَبَذْنَـٰهُمْ","transliteration":"fanabadhnāhum","translation_bn":"এরপর তাদের আমরা নিক্ষেপ করেছিলাম","root":"نبذ","lemma":"نَبَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41166,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":41167,"position":5,"text_uthmani":"ٱلْيَمِّ","transliteration":"l-yami","translation_bn":"সমুদ্রের","root":"يمم","lemma":"يَمّ","grammar_bn":"শব্দ"},{"id":41168,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং সে (হয়েছিল)","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":41169,"position":7,"text_uthmani":"مُلِيمٌۭ","transliteration":"mulīmun","translation_bn":"নিন্দিত","root":"لوم","lemma":"مُلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":41170,"position":8,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-akhadhnāhu wajunūdahu fanabadhnāhum fī l-yami wahuwa mulīmun', 'শেষে আমি তাকে আর তার সৈন্য সামন্তকে পাকড়াও করলাম আর তাদেরকে সমুদ্রে নিক্ষেপ করলাম। সে ছিল ধিকৃত নিন্দিত।', 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.', 'শেষে আমি তাকে আর তার সৈন্য সামন্তকে পাকড়াও করলাম আর তাদেরকে সমুদ্রে নিক্ষেপ করলাম। সে ছিল ধিকৃত নিন্দিত।', 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051040.mp3', now()),
  (51, 41, '', '[{"id":42063,"position":1,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং (আছে) মধ্যে (নিদর্শন)","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42064,"position":2,"text_uthmani":"عَادٍ","transliteration":"ʿādin","translation_bn":"আ''দ জাতির (ঘটনায়)","root":"عود","lemma":"عَاد2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":42065,"position":3,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":42066,"position":4,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়ে ছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42067,"position":5,"text_uthmani":"عَلَيْهِمُ","transliteration":"ʿalayhimu","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42068,"position":6,"text_uthmani":"ٱلرِّيحَ","transliteration":"l-rīḥa","translation_bn":"বায়ুপ্রবাহ","root":"روح","lemma":"رِيح","grammar_bn":"শব্দ"},{"id":42069,"position":7,"text_uthmani":"ٱلْعَقِيمَ","transliteration":"l-ʿaqīma","translation_bn":"অকল্যাণকর/ বিধ্বংসী","root":"عقم","lemma":"عَقِيم","grammar_bn":"শব্দ"},{"id":42070,"position":8,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'wafī ʿādin idh arsalnā ʿalayhimu l-rīḥa l-ʿaqīma', 'আর ‘আদ-এর ঘটনাতেও (নিদর্শন আছে)। আমি তাদের কাছে পাঠিয়েছিলাম অকল্যাণের বাতাস।', 'And in ''Aad [was a sign], when We sent against them the barren wind.', 'আর ‘আদ-এর ঘটনাতেও (নিদর্শন আছে)। আমি তাদের কাছে পাঠিয়েছিলাম অকল্যাণের বাতাস।', 'And in ''Aad [was a sign], when We sent against them the barren wind.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051041.mp3', now()),
  (51, 42, '', '[{"id":42805,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":42806,"position":2,"text_uthmani":"تَذَرُ","transliteration":"tadharu","translation_bn":"ছেড়েছিল","root":"وذر","lemma":"يَذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42807,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42808,"position":4,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":42809,"position":5,"text_uthmani":"أَتَتْ","transliteration":"atat","translation_bn":"বয়ে গিয়েছিল","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":42810,"position":6,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"যার উপর (দিয়ে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42811,"position":7,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":42812,"position":8,"text_uthmani":"جَعَلَتْهُ","transliteration":"jaʿalathu","translation_bn":"তাকে করেছিল","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42813,"position":9,"text_uthmani":"كَٱلرَّمِيمِ","transliteration":"kal-ramīmi","translation_bn":"যেন চূর্ণবিচূর্ণ","root":"رمم","lemma":"رَمِيم","grammar_bn":"অব্যয় (Preposition)"},{"id":42814,"position":10,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā tadharu min shayin atat ʿalayhi illā jaʿalathu kal-ramīmi', 'তা যা কিছুর উপর দিয়ে বয়ে গিয়েছিল তাকে চূর্ণ-বিচূর্ণ ও ধ্বংসস্তুপে পরিণত না করে ছাড়েনি।', 'It left nothing of what it came upon but that it made it like disintegrated ruins.', 'তা যা কিছুর উপর দিয়ে বয়ে গিয়েছিল তাকে চূর্ণ-বিচূর্ণ ও ধ্বংসস্তুপে পরিণত না করে ছাড়েনি।', 'It left nothing of what it came upon but that it made it like disintegrated ruins.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051042.mp3', now()),
  (51, 43, '', '[{"id":43593,"position":1,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং (আছে) মধ্যে (নিদর্শন)","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43594,"position":2,"text_uthmani":"ثَمُودَ","transliteration":"thamūda","translation_bn":"সামূদ জাতির (ঘটনায়)","root":"—","lemma":"ثَمُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":43595,"position":3,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":43596,"position":4,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হয়েছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43597,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":43598,"position":6,"text_uthmani":"تَمَتَّعُوا۟","transliteration":"tamattaʿū","translation_bn":"\"তোমরা উপভোগ করো","root":"متع","lemma":"تَمَتَّعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43599,"position":7,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43600,"position":8,"text_uthmani":"حِينٍۢ","transliteration":"ḥīnin","translation_bn":"একটি নির্দিষ্ট সময়\"","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":43601,"position":9,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'wafī thamūda idh qīla lahum tamattaʿū ḥattā ḥīnin', 'আর সামূদের ঘটনাতেও (নিদর্শন আছে) যখন তাদেরকে বলা হয়েছিল, ‘একটা নির্দিষ্ট সময় পর্যন্ত ভোগ করে লও।’', 'And in Thamud, when it was said to them, "Enjoy yourselves for a time."', 'আর সামূদের ঘটনাতেও (নিদর্শন আছে) যখন তাদেরকে বলা হয়েছিল, ‘একটা নির্দিষ্ট সময় পর্যন্ত ভোগ করে লও।’', 'And in Thamud, when it was said to them, "Enjoy yourselves for a time."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051043.mp3', now()),
  (51, 44, '', '[{"id":44396,"position":1,"text_uthmani":"فَعَتَوْا۟","transliteration":"faʿataw","translation_bn":"এরপরও তারা সীমালংঘন করল","root":"عتو","lemma":"عَتَ","grammar_bn":"শব্দ"},{"id":44397,"position":2,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"ব্যাপারে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":44398,"position":3,"text_uthmani":"أَمْرِ","transliteration":"amri","translation_bn":"নির্দেশের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":44399,"position":4,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":44400,"position":5,"text_uthmani":"فَأَخَذَتْهُمُ","transliteration":"fa-akhadhathumu","translation_bn":"অবশেষে তাদেরকে পাকড়াও করল","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"শব্দ"},{"id":44401,"position":6,"text_uthmani":"ٱلصَّـٰعِقَةُ","transliteration":"l-ṣāʿiqatu","translation_bn":"(আমার) বজ্রাঘাতে","root":"صعق","lemma":"صَاعِقَة","grammar_bn":"শব্দ"},{"id":44402,"position":7,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এ অবস্থায় যে তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":44403,"position":8,"text_uthmani":"يَنظُرُونَ","transliteration":"yanẓurūna","translation_bn":"দেখছিল","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44404,"position":9,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'faʿataw ʿan amri rabbihim fa-akhadhathumu l-ṣāʿiqatu wahum yanẓurūna', 'কিন্তু তারা ধৃষ্টতার সঙ্গে তাদের প্রতিপালকের আদেশ অমান্য করল। ফলে বজ্রাঘাত তাদেরকে পাকড়াও করল যা তারা চেয়ে চেয়ে দেখছিল।', 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.', 'কিন্তু তারা ধৃষ্টতার সঙ্গে তাদের প্রতিপালকের আদেশ অমান্য করল। ফলে বজ্রাঘাত তাদেরকে পাকড়াও করল যা তারা চেয়ে চেয়ে দেখছিল।', 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051044.mp3', now()),
  (51, 45, '', '[{"id":45105,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":45106,"position":2,"text_uthmani":"ٱسْتَطَـٰعُوا۟","transliteration":"is''taṭāʿū","translation_bn":"তারা পেরেছিল","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45107,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45108,"position":4,"text_uthmani":"قِيَامٍۢ","transliteration":"qiyāmin","translation_bn":"উঠে দাঁড়াতে","root":"قوم","lemma":"قَا^ئِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":45109,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45110,"position":6,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45111,"position":7,"text_uthmani":"مُنتَصِرِينَ","transliteration":"muntaṣirīna","translation_bn":"আত্মরক্ষা করতে সক্ষম","root":"نصر","lemma":"مُّنتَصِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":45112,"position":8,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'famā is''taṭāʿū min qiyāmin wamā kānū muntaṣirīna', 'তারা (পায়ের ভরে) উঠে দাঁড়াতেও পারল না আর আত্মরক্ষা করতেও পারল না।', 'And they were unable to arise, nor could they defend themselves.', 'তারা (পায়ের ভরে) উঠে দাঁড়াতেও পারল না আর আত্মরক্ষা করতেও পারল না।', 'And they were unable to arise, nor could they defend themselves.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051045.mp3', now()),
  (51, 46, '', '[{"id":45839,"position":1,"text_uthmani":"وَقَوْمَ","transliteration":"waqawma","translation_bn":"এবং জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45840,"position":2,"text_uthmani":"نُوحٍۢ","transliteration":"nūḥin","translation_bn":"নূহের","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":45841,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45842,"position":4,"text_uthmani":"قَبْلُ ۖ","transliteration":"qablu","translation_bn":"ইতিপূর্বে (ধ্বংস করেছি)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":45844,"position":5,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":45845,"position":6,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":45846,"position":7,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":45847,"position":8,"text_uthmani":"فَـٰسِقِينَ","transliteration":"fāsiqīna","translation_bn":"সত্যত্যাগী","root":"فسق","lemma":"فَاسِق","grammar_bn":"বিশেষণ (Adjective)"},{"id":45848,"position":9,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'waqawma nūḥin min qablu innahum kānū qawman fāsiqīna', 'ইতোপূর্বে আমি নূহের জাতিকে ধ্বংস করেছিলাম, তারা ছিল এক পাপাচারী জাতি।', 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.', 'ইতোপূর্বে আমি নূহের জাতিকে ধ্বংস করেছিলাম, তারা ছিল এক পাপাচারী জাতি।', 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051046.mp3', now()),
  (51, 47, '', '[{"id":46488,"position":1,"text_uthmani":"وَٱلسَّمَآءَ","transliteration":"wal-samāa","translation_bn":"এবং আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46489,"position":2,"text_uthmani":"بَنَيْنَـٰهَا","transliteration":"banaynāhā","translation_bn":"তা আমরা সৃষ্টি করেছি","root":"بني","lemma":"بَنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46490,"position":3,"text_uthmani":"بِأَيْي۟دٍۢ","transliteration":"bi-aydin","translation_bn":"(নিজের) হাত দিয়ে","root":"ايد","lemma":"أَيْيد","grammar_bn":"অব্যয় (Preposition)"},{"id":46491,"position":4,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":46492,"position":5,"text_uthmani":"لَمُوسِعُونَ","transliteration":"lamūsiʿūna","translation_bn":"অবশ্যই সপ্রসারণকারী","root":"وسع","lemma":"مُوسِع","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":46493,"position":6,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-samāa banaynāhā bi-aydin wa-innā lamūsiʿūna', 'আমি নিজ হাত দ্বারা আসমান সৃষ্টি করেছি আর আমি অবশ্যই মহা প্রশস্তকারী।', 'And the heaven We constructed with strength, and indeed, We are [its] expander.', 'আমি নিজ হাত দ্বারা আসমান সৃষ্টি করেছি আর আমি অবশ্যই মহা প্রশস্তকারী।', 'And the heaven We constructed with strength, and indeed, We are [its] expander.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051047.mp3', now()),
  (51, 48, '', '[{"id":47227,"position":1,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"এবং ভূমিকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47228,"position":2,"text_uthmani":"فَرَشْنَـٰهَا","transliteration":"farashnāhā","translation_bn":"তা আমরা সমতল করে দিয়েছি","root":"فرش","lemma":"فَرَشْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47229,"position":3,"text_uthmani":"فَنِعْمَ","transliteration":"faniʿ''ma","translation_bn":"আর কতই না উত্তম","root":"نعم","lemma":"نِعْمَ","grammar_bn":"শব্দ"},{"id":47230,"position":4,"text_uthmani":"ٱلْمَـٰهِدُونَ","transliteration":"l-māhidūna","translation_bn":"সমতলকারী (আমরা)","root":"مهد","lemma":"مَٰهِدُون","grammar_bn":"শব্দ"},{"id":47231,"position":5,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'wal-arḍa farashnāhā faniʿ''ma l-māhidūna', 'আর যমীন- তাকে আমিই বিছিয়েছি, আমি কতই না সুন্দর (সমতল) প্রসারণকারী!', 'And the earth We have spread out, and excellent is the preparer.', 'আর যমীন- তাকে আমিই বিছিয়েছি, আমি কতই না সুন্দর (সমতল) প্রসারণকারী!', 'And the earth We have spread out, and excellent is the preparer.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051048.mp3', now()),
  (51, 49, '', '[{"id":47837,"position":1,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47838,"position":2,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":47839,"position":3,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"বস্তুকে","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":47840,"position":4,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47841,"position":5,"text_uthmani":"زَوْجَيْنِ","transliteration":"zawjayni","translation_bn":"জোড়ায় জোড়ায়","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":47842,"position":6,"text_uthmani":"لَعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"তোমরা যাতে","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":47843,"position":7,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"শিক্ষা গ্রহণ কর","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":47844,"position":8,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamin kulli shayin khalaqnā zawjayni laʿallakum tadhakkarūna', 'আমি প্রত্যেকটি বস্তু সৃষ্টি করেছি জোড়ায় জোড়ায়, যাতে তোমরা শিক্ষা গ্রহণ কর।', 'And of all things We created two mates; perhaps you will remember.', 'আমি প্রত্যেকটি বস্তু সৃষ্টি করেছি জোড়ায় জোড়ায়, যাতে তোমরা শিক্ষা গ্রহণ কর।', 'And of all things We created two mates; perhaps you will remember.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051049.mp3', now()),
  (51, 50, '', '[{"id":48517,"position":1,"text_uthmani":"فَفِرُّوٓا۟","transliteration":"fafirrū","translation_bn":"অতএব তোমরা দৌড়াও","root":"فرر","lemma":"فَرَّتْ","grammar_bn":"শব্দ"},{"id":48518,"position":2,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48519,"position":3,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":48521,"position":4,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":48522,"position":5,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":48523,"position":6,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তার পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48524,"position":7,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"একজন সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":48525,"position":8,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":48526,"position":9,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'fafirrū ilā l-lahi innī lakum min''hu nadhīrun mubīnun', 'অতএব দৌড়াও আল্লাহর দিকে, আমি তোমাদের জন্য তাঁর পক্ষ হতে স্পষ্ট সতর্ককারী।', 'So flee to Allah. Indeed, I am to you from Him a clear warner.', 'অতএব দৌড়াও আল্লাহর দিকে, আমি তোমাদের জন্য তাঁর পক্ষ হতে স্পষ্ট সতর্ককারী।', 'So flee to Allah. Indeed, I am to you from Him a clear warner.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051050.mp3', now()),
  (51, 51, '', '[{"id":49164,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49165,"position":2,"text_uthmani":"تَجْعَلُوا۟","transliteration":"tajʿalū","translation_bn":"তোমরা বানাবে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49166,"position":3,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":49167,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":49168,"position":5,"text_uthmani":"إِلَـٰهًا","transliteration":"ilāhan","translation_bn":"উপাস্য","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":49169,"position":6,"text_uthmani":"ءَاخَرَ ۖ","transliteration":"ākhara","translation_bn":"অন্য কোনো","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":49171,"position":7,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":49172,"position":8,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":49173,"position":9,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তাঁর পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49174,"position":10,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"একজন সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":49175,"position":11,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":49176,"position":12,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'walā tajʿalū maʿa l-lahi ilāhan ākhara innī lakum min''hu nadhīrun mubīnun', 'তোমরা আল্লাহর সঙ্গে কোন ইলাহ স্থির করো না, আমি তাঁর পক্ষ থেকে তোমাদের জন্য স্পষ্ট সতর্ককারী।', 'And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner.', 'তোমরা আল্লাহর সঙ্গে কোন ইলাহ স্থির করো না, আমি তাঁর পক্ষ থেকে তোমাদের জন্য স্পষ্ট সতর্ককারী।', 'And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051051.mp3', now()),
  (51, 52, '', '[{"id":49830,"position":1,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":49831,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":49832,"position":3,"text_uthmani":"أَتَى","transliteration":"atā","translation_bn":"এসেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":49833,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের কাছে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":49834,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49835,"position":6,"text_uthmani":"قَبْلِهِم","transliteration":"qablihim","translation_bn":"তাদের পূর্বে (ছিল)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":49836,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49837,"position":8,"text_uthmani":"رَّسُولٍ","transliteration":"rasūlin","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":49838,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":49839,"position":10,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে ছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49840,"position":11,"text_uthmani":"سَاحِرٌ","transliteration":"sāḥirun","translation_bn":"\"(সে একজন) জাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":49841,"position":12,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49842,"position":13,"text_uthmani":"مَجْنُونٌ","transliteration":"majnūnun","translation_bn":"পাগল\"","root":"جنن","lemma":"مَجْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":49843,"position":14,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'kadhālika mā atā alladhīna min qablihim min rasūlin illā qālū sāḥirun aw majnūnun', 'এভাবে যখনই তাদের আগের লোকেদের মধ্যে কোন রসূল এসেছে, তখনই তারা বলেছে- ‘সে যাদুকর না হয় উন্মাদ।’', 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."', 'এভাবে যখনই তাদের আগের লোকেদের মধ্যে কোন রসূল এসেছে, তখনই তারা বলেছে- ‘সে যাদুকর না হয় উন্মাদ।’', 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051052.mp3', now()),
  (51, 53, '', '[{"id":50463,"position":1,"text_uthmani":"أَتَوَاصَوْا۟","transliteration":"atawāṣaw","translation_bn":"তারা পরস্পরে কি পরামর্শ করে নিয়েছে","root":"وصي","lemma":"تَوَاصَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":50464,"position":2,"text_uthmani":"بِهِۦ ۚ","transliteration":"bihi","translation_bn":"সে বিষয়ে","root":"—","lemma":"بِهِۦ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":50466,"position":3,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"(না) বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":50467,"position":4,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা(ছিল)","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":50468,"position":5,"text_uthmani":"قَوْمٌۭ","transliteration":"qawmun","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":50469,"position":6,"text_uthmani":"طَاغُونَ","transliteration":"ṭāghūna","translation_bn":"দুর্বিনীত","root":"طغي","lemma":"طَٰغِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":50470,"position":7,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'atawāṣaw bihi bal hum qawmun ṭāghūna', 'তারা কি বংশ পরম্পরায় এরই অসিয়ত (অর্থাৎ অন্তিম সবক) দিয়ে আসছে, বরং তারা সীমালঙ্ঘনকারী জাতি।', 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.', 'তারা কি বংশ পরম্পরায় এরই অসিয়ত (অর্থাৎ অন্তিম সবক) দিয়ে আসছে, বরং তারা সীমালঙ্ঘনকারী জাতি।', 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051053.mp3', now()),
  (51, 54, '', '[{"id":51119,"position":1,"text_uthmani":"فَتَوَلَّ","transliteration":"fatawalla","translation_bn":"তাই তুমি উপেক্ষা করো","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"শব্দ"},{"id":51120,"position":2,"text_uthmani":"عَنْهُمْ","transliteration":"ʿanhum","translation_bn":"তাদের হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":51121,"position":3,"text_uthmani":"فَمَآ","transliteration":"famā","translation_bn":"আর নও","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":51122,"position":4,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":51123,"position":5,"text_uthmani":"بِمَلُومٍۢ","transliteration":"bimalūmin","translation_bn":"তিরস্কৃত","root":"لوم","lemma":"مَلُوم","grammar_bn":"অব্যয় (Preposition)"},{"id":51124,"position":6,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'fatawalla ʿanhum famā anta bimalūmin', 'কাজেই তুমি তাদের দিক থেকে মুখ ফিরিয়ে লও, তার জন্য তুমি তিরস্কৃত হবে না।', 'So leave them, [O Muhammad], for you are not to be blamed.', 'কাজেই তুমি তাদের দিক থেকে মুখ ফিরিয়ে লও, তার জন্য তুমি তিরস্কৃত হবে না।', 'So leave them, [O Muhammad], for you are not to be blamed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051054.mp3', now()),
  (51, 55, '', '[{"id":51663,"position":1,"text_uthmani":"وَذَكِّرْ","transliteration":"wadhakkir","translation_bn":"এবং উপদেশ দাও","root":"ذكر","lemma":"ذُكِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":51664,"position":2,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"কেননা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":51665,"position":3,"text_uthmani":"ٱلذِّكْرَىٰ","transliteration":"l-dhik''rā","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"শব্দ"},{"id":51666,"position":4,"text_uthmani":"تَنفَعُ","transliteration":"tanfaʿu","translation_bn":"উপকার দিবে","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51667,"position":5,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":51668,"position":6,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'wadhakkir fa-inna l-dhik''rā tanfaʿu l-mu''minīna', 'আর তুমি উপদেশ দিতে থাক, কেননা উপদেশ মু’মিনদের উপকার করবে।', 'And remind, for indeed, the reminder benefits the believers.', 'আর তুমি উপদেশ দিতে থাক, কেননা উপদেশ মু’মিনদের উপকার করবে।', 'And remind, for indeed, the reminder benefits the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051055.mp3', now()),
  (51, 56, '', '[{"id":52169,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52170,"position":2,"text_uthmani":"خَلَقْتُ","transliteration":"khalaqtu","translation_bn":"আমি সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52171,"position":3,"text_uthmani":"ٱلْجِنَّ","transliteration":"l-jina","translation_bn":"জিনকে","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":52172,"position":4,"text_uthmani":"وَٱلْإِنسَ","transliteration":"wal-insa","translation_bn":"ও মানুষকে","root":"انس","lemma":"إِنس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52173,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":52174,"position":6,"text_uthmani":"لِيَعْبُدُونِ","transliteration":"liyaʿbudūni","translation_bn":"যেন আমাকে তারা ইবাদত করে","root":"عبد","lemma":"عَبَدَ","grammar_bn":"শব্দ"},{"id":52175,"position":7,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā khalaqtu l-jina wal-insa illā liyaʿbudūni', 'আমি জ্বিন ও মানবকে সৃষ্টি করেছি একমাত্র এ কারণে যে, তারা আমারই ‘ইবাদাত করবে।', 'And I did not create the jinn and mankind except to worship Me.', 'আমি জ্বিন ও মানবকে সৃষ্টি করেছি একমাত্র এ কারণে যে, তারা আমারই ‘ইবাদাত করবে।', 'And I did not create the jinn and mankind except to worship Me.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051056.mp3', now()),
  (51, 57, '', '[{"id":52743,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":52744,"position":2,"text_uthmani":"أُرِيدُ","transliteration":"urīdu","translation_bn":"চাই আমি","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52745,"position":3,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"তাদের নিকট হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52746,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":52747,"position":5,"text_uthmani":"رِّزْقٍۢ","transliteration":"riz''qin","translation_bn":"জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":52748,"position":6,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52749,"position":7,"text_uthmani":"أُرِيدُ","transliteration":"urīdu","translation_bn":"চাই আমি","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52750,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":52751,"position":9,"text_uthmani":"يُطْعِمُونِ","transliteration":"yuṭ''ʿimūni","translation_bn":"আমাকে তারা খাওয়াবে","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52752,"position":10,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'mā urīdu min''hum min riz''qin wamā urīdu an yuṭ''ʿimūni', 'আমি তাদের থেকে রিযক চাই না, আর আমি এও চাই না যে, তারা আমাকে খাওয়াবে।', 'I do not want from them any provision, nor do I want them to feed Me.', 'আমি তাদের থেকে রিযক চাই না, আর আমি এও চাই না যে, তারা আমাকে খাওয়াবে।', 'I do not want from them any provision, nor do I want them to feed Me.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051057.mp3', now()),
  (51, 58, '', '[{"id":53583,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":53584,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":53585,"position":3,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":53586,"position":4,"text_uthmani":"ٱلرَّزَّاقُ","transliteration":"l-razāqu","translation_bn":"রিযকদাতা","root":"رزق","lemma":"رَّزَّاق","grammar_bn":"শব্দ"},{"id":53587,"position":5,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"আছে","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":53588,"position":6,"text_uthmani":"ٱلْقُوَّةِ","transliteration":"l-quwati","translation_bn":"শক্তিসম্পন্ন","root":"قوي","lemma":"قُوَّة","grammar_bn":"শব্দ"},{"id":53589,"position":7,"text_uthmani":"ٱلْمَتِينُ","transliteration":"l-matīnu","translation_bn":"প্রবল পরাক্রান্ত","root":"متن","lemma":"مَتِين","grammar_bn":"শব্দ"},{"id":53590,"position":8,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-laha huwa l-razāqu dhū l-quwati l-matīnu', 'আল্লাহই তো রিযকদাতা, মহা শক্তিধর, প্রবল পরাক্রান্ত।', 'Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength.', 'আল্লাহই তো রিযকদাতা, মহা শক্তিধর, প্রবল পরাক্রান্ত।', 'Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051058.mp3', now()),
  (51, 59, '', '[{"id":54149,"position":1,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"অতএব নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":54150,"position":2,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"তাদের জন্যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":54151,"position":3,"text_uthmani":"ظَلَمُوا۟","transliteration":"ẓalamū","translation_bn":"(যারা) সীমালঙ্ঘন করেছে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54152,"position":4,"text_uthmani":"ذَنُوبًۭا","transliteration":"dhanūban","translation_bn":"(তাদের আছে) শাস্তির অংশ","root":"ذنب","lemma":"ذَنُوب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54153,"position":5,"text_uthmani":"مِّثْلَ","transliteration":"mith''la","translation_bn":"যেমনি","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":54154,"position":6,"text_uthmani":"ذَنُوبِ","transliteration":"dhanūbi","translation_bn":"(প্রাপ্য ছিল) শাস্তির অংশ","root":"ذنب","lemma":"ذَنُوب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54155,"position":7,"text_uthmani":"أَصْحَـٰبِهِمْ","transliteration":"aṣḥābihim","translation_bn":"তাদের সাথীদের","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54156,"position":8,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"না তাই (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":54157,"position":9,"text_uthmani":"يَسْتَعْجِلُونِ","transliteration":"yastaʿjilūni","translation_bn":"আমার কাছে তারা তাড়াহুড়া করে","root":"عجل","lemma":"ٱسْتَعْجَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54158,"position":10,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-inna lilladhīna ẓalamū dhanūban mith''la dhanūbi aṣḥābihim falā yastaʿjilūni', 'কাজেই যারা যুলম করেছে তাদের প্রাপ্য তাই যে প্রাপ্য পূর্বে ছিল তাদের মত লোকেদের; কাজেই (নিজেদের প্রাপ্য পাওয়ার জন্য) তারা যেন তাড়াহুড়া না করে।', 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me.', 'কাজেই যারা যুলম করেছে তাদের প্রাপ্য তাই যে প্রাপ্য পূর্বে ছিল তাদের মত লোকেদের; কাজেই (নিজেদের প্রাপ্য পাওয়ার জন্য) তারা যেন তাড়াহুড়া না করে।', 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051059.mp3', now()),
  (51, 60, '', '[{"id":54318,"position":1,"text_uthmani":"فَوَيْلٌۭ","transliteration":"fawaylun","translation_bn":"অতঃপর দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"শব্দ"},{"id":54319,"position":2,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":54320,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54321,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ব্যাপারে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":54322,"position":5,"text_uthmani":"يَوْمِهِمُ","transliteration":"yawmihimu","translation_bn":"তাদের (সেই) দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":54323,"position":6,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":54324,"position":7,"text_uthmani":"يُوعَدُونَ","transliteration":"yūʿadūna","translation_bn":"ভয় তাদের দেখান হয়েছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54325,"position":8,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'fawaylun lilladhīna kafarū min yawmihimu alladhī yūʿadūna', 'কাফিরদের জন্য ধ্বংস (নেমে আসবে) তাদের সেদিনের যেদিনের ভয় তাদেরকে দেখানো হয়েছে।', 'And woe to those who have disbelieved from their Day which they are promised.', 'কাফিরদের জন্য ধ্বংস (নেমে আসবে) তাদের সেদিনের যেদিনের ভয় তাদেরকে দেখানো হয়েছে।', 'And woe to those who have disbelieved from their Day which they are promised.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/051060.mp3', now())
