  (52, 15, '', '[{"id":17222,"position":1,"text_uthmani":"أَفَسِحْرٌ","transliteration":"afasiḥ''run","translation_bn":"জাদু তবে কি","root":"سحر","lemma":"سِحْر","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":17223,"position":2,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":17224,"position":3,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"নাকি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17225,"position":4,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":17226,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17227,"position":6,"text_uthmani":"تُبْصِرُونَ","transliteration":"tub''ṣirūna","translation_bn":"চোখে দেখছ","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17228,"position":7,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'afasiḥ''run hādhā am antum lā tub''ṣirūna', 'এটা কি যাদু, নাকি তোমরা দেখতে পাচ্ছ না?', 'Then is this magic, or do you not see?', 'এটা কি যাদু, নাকি তোমরা দেখতে পাচ্ছ না?', 'Then is this magic, or do you not see?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052015.mp3', now()),
  (52, 16, '', '[{"id":18267,"position":1,"text_uthmani":"ٱصْلَوْهَا","transliteration":"iṣ''lawhā","translation_bn":"তাতে তোমরা প্রবেশ করো","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":18268,"position":2,"text_uthmani":"فَٱصْبِرُوٓا۟","transliteration":"fa-iṣ''birū","translation_bn":"অতঃপর তোমরা সহ্য করতে পার","root":"صبر","lemma":"صَبَرَ","grammar_bn":"শব্দ"},{"id":18269,"position":3,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18270,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":18271,"position":5,"text_uthmani":"تَصْبِرُوا۟","transliteration":"taṣbirū","translation_bn":"তোমরা সহ্য করতে পার","root":"صبر","lemma":"صَبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18272,"position":6,"text_uthmani":"سَوَآءٌ","transliteration":"sawāon","translation_bn":"(সবই) সমান","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":18273,"position":7,"text_uthmani":"عَلَيْكُمْ ۖ","transliteration":"ʿalaykum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18275,"position":8,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে (আজ)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":18276,"position":9,"text_uthmani":"تُجْزَوْنَ","transliteration":"tuj''zawna","translation_bn":"তোমাদেরকে প্রতিফল দেয়া হচ্ছে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18277,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18278,"position":11,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18279,"position":12,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"কাজ করছ\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18280,"position":13,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'iṣ''lawhā fa-iṣ''birū aw lā taṣbirū sawāon ʿalaykum innamā tuj''zawna mā kuntum taʿmalūna', 'এখন এর ভিতর জ্বলতে থাক, অতঃপর ধৈর্য ধর কিংবা ধৈর্য না ধর, তোমাদের জন্য দুই-ই সমান। তোমাদেরকে সেই প্রতিফলই দেয়া হবে যা তোমরা ‘আমাল করতে।', '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."', 'এখন এর ভিতর জ্বলতে থাক, অতঃপর ধৈর্য ধর কিংবা ধৈর্য না ধর, তোমাদের জন্য দুই-ই সমান। তোমাদেরকে সেই প্রতিফলই দেয়া হবে যা তোমরা ‘আমাল করতে।', '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052016.mp3', now()),
  (52, 17, '', '[{"id":19299,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19300,"position":2,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীরা (অবস্থিত হবে)","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":19301,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19302,"position":4,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19303,"position":5,"text_uthmani":"وَنَعِيمٍۢ","transliteration":"wanaʿīmin","translation_bn":"ও আরাম আয়েশে","root":"نعم","lemma":"نَعِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19304,"position":6,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-mutaqīna fī jannātin wanaʿīmin', 'মুত্তাক্বীরা থাকবে জান্নাতে আর নি‘মাত সম্ভারের মাঝে,', 'Indeed, the righteous will be in gardens and pleasure,', 'মুত্তাক্বীরা থাকবে জান্নাতে আর নি‘মাত সম্ভারের মাঝে,', 'Indeed, the righteous will be in gardens and pleasure,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052017.mp3', now()),
  (52, 18, '', '[{"id":20366,"position":1,"text_uthmani":"فَـٰكِهِينَ","transliteration":"fākihīna","translation_bn":"সানন্দে উপভোগকারী হবে তারা","root":"فكه","lemma":"فَٰكِهِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":20367,"position":2,"text_uthmani":"بِمَآ","transliteration":"bimā","translation_bn":"ঐ জিনিসের যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20368,"position":3,"text_uthmani":"ءَاتَىٰهُمْ","transliteration":"ātāhum","translation_bn":"তাদের দান করবেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":20369,"position":4,"text_uthmani":"رَبُّهُمْ","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20370,"position":5,"text_uthmani":"وَوَقَىٰهُمْ","transliteration":"wawaqāhum","translation_bn":"এবং তাদের রক্ষা করবেন","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20371,"position":6,"text_uthmani":"رَبُّهُمْ","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20372,"position":7,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি (হতে)","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":20373,"position":8,"text_uthmani":"ٱلْجَحِيمِ","transliteration":"l-jaḥīmi","translation_bn":"জাহান্নামের","root":"جحم","lemma":"جَحِيم","grammar_bn":"শব্দ"},{"id":20374,"position":9,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'fākihīna bimā ātāhum rabbuhum wawaqāhum rabbuhum ʿadhāba l-jaḥīmi', 'তারা ভোগ করবে তাদের প্রতিপালক যা তাদেরকে দিবেন, আর তাদের প্রতিপালক তাদেরকে জাহান্নামের ‘আযাব থেকে রক্ষা করবেন।', 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.', 'তারা ভোগ করবে তাদের প্রতিপালক যা তাদেরকে দিবেন, আর তাদের প্রতিপালক তাদেরকে জাহান্নামের ‘আযাব থেকে রক্ষা করবেন।', 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052018.mp3', now()),
  (52, 19, '', '[{"id":21444,"position":1,"text_uthmani":"كُلُوا۟","transliteration":"kulū","translation_bn":"\"(বলা হবে) তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21445,"position":2,"text_uthmani":"وَٱشْرَبُوا۟","transliteration":"wa-ish''rabū","translation_bn":"ও তোমরা পান করো","root":"شرب","lemma":"شَرِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21446,"position":3,"text_uthmani":"هَنِيٓـًٔۢا","transliteration":"hanīan","translation_bn":"তৃপ্তির সাথে","root":"هنا","lemma":"هَنِي^ـ#","grammar_bn":"বিশেষ্য (Noun)"},{"id":21447,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"তার বদলে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21448,"position":5,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা করছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21449,"position":6,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করছিলে\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21450,"position":7,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'kulū wa-ish''rabū hanīan bimā kuntum taʿmalūna', '(তাদেরকে বলা হবে) খাও আর পান কর খুব মজা করে- তোমরা যে ‘আমাল করতে তার প্রতিফল হিসেবে।', '[They will be told], "Eat and drink in satisfaction for what you used to do."', '(তাদেরকে বলা হবে) খাও আর পান কর খুব মজা করে- তোমরা যে ‘আমাল করতে তার প্রতিফল হিসেবে।', '[They will be told], "Eat and drink in satisfaction for what you used to do."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052019.mp3', now()),
  (52, 20, '', '[{"id":22539,"position":1,"text_uthmani":"مُتَّكِـِٔينَ","transliteration":"muttakiīna","translation_bn":"তারা হেলান দিয়ে বসবে","root":"وكا","lemma":"مُتَّكِـ#ِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":22540,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22541,"position":3,"text_uthmani":"سُرُرٍۢ","transliteration":"sururin","translation_bn":"আসনসমূহের","root":"سرر","lemma":"سُرُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":22542,"position":4,"text_uthmani":"مَّصْفُوفَةٍۢ ۖ","transliteration":"maṣfūfatin","translation_bn":"সারিবদ্ধভাবে","root":"صفف","lemma":"مَصْفُوفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22544,"position":5,"text_uthmani":"وَزَوَّجْنَـٰهُم","transliteration":"wazawwajnāhum","translation_bn":"এবং তাদেরকে আমরা বিয়ে দিব","root":"زوج","lemma":"زُوِّجَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22545,"position":6,"text_uthmani":"بِحُورٍ","transliteration":"biḥūrin","translation_bn":"হূরদের সাথে","root":"حور","lemma":"حُور","grammar_bn":"অব্যয় (Preposition)"},{"id":22546,"position":7,"text_uthmani":"عِينٍۢ","transliteration":"ʿīnin","translation_bn":"(যারা হবে) আয়তলোচনা","root":"عين","lemma":"عِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":22547,"position":8,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'muttakiīna ʿalā sururin maṣfūfatin wazawwajnāhum biḥūrin ʿīnin', 'তারা সারিবদ্ধভাবে সাজানো আসনে হেলান দিয়ে বসবে, আর আমি তাদের বিয়ে দিয়ে দেব সুন্দর বড় বড় উজ্জ্বল চক্ষু বিশিষ্টা কুমারীদের সঙ্গে।', 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.', 'তারা সারিবদ্ধভাবে সাজানো আসনে হেলান দিয়ে বসবে, আর আমি তাদের বিয়ে দিয়ে দেব সুন্দর বড় বড় উজ্জ্বল চক্ষু বিশিষ্টা কুমারীদের সঙ্গে।', 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052020.mp3', now()),
  (52, 21, '', '[{"id":23690,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23691,"position":2,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23692,"position":3,"text_uthmani":"وَٱتَّبَعَتْهُمْ","transliteration":"wa-ittabaʿathum","translation_bn":"ও তাদেরকে অনুসরণ করেছে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23693,"position":4,"text_uthmani":"ذُرِّيَّتُهُم","transliteration":"dhurriyyatuhum","translation_bn":"তাদের সন্তানরা","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23694,"position":5,"text_uthmani":"بِإِيمَـٰنٍ","transliteration":"biīmānin","translation_bn":"ঈমানসহ","root":"امن","lemma":"إِيمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":23695,"position":6,"text_uthmani":"أَلْحَقْنَا","transliteration":"alḥaqnā","translation_bn":"আমরা মিলিত করব","root":"لحق","lemma":"أَلْحَقْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23696,"position":7,"text_uthmani":"بِهِمْ","transliteration":"bihim","translation_bn":"তাদের সাথে","root":"—","lemma":"بِهِمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":23697,"position":8,"text_uthmani":"ذُرِّيَّتَهُمْ","transliteration":"dhurriyyatahum","translation_bn":"তাদের সন্তানদেরকে","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23698,"position":9,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23699,"position":10,"text_uthmani":"أَلَتْنَـٰهُم","transliteration":"alatnāhum","translation_bn":"তাদের আমরা কম করব","root":"الت","lemma":"أَلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23700,"position":11,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23701,"position":12,"text_uthmani":"عَمَلِهِم","transliteration":"ʿamalihim","translation_bn":"তাদের আমল","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":23702,"position":13,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23703,"position":14,"text_uthmani":"شَىْءٍۢ ۚ","transliteration":"shayin","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":23705,"position":15,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23706,"position":16,"text_uthmani":"ٱمْرِئٍۭ","transliteration":"im''ri-in","translation_bn":"ব্যক্তি","root":"مرا","lemma":"ٱمْرِئ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23707,"position":17,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23708,"position":18,"text_uthmani":"كَسَبَ","transliteration":"kasaba","translation_bn":"সে অর্জন করেছে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23709,"position":19,"text_uthmani":"رَهِينٌۭ","transliteration":"rahīnun","translation_bn":"দায়ী/ বন্ধক (আছে)","root":"رهن","lemma":"رَهِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":23710,"position":20,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna āmanū wa-ittabaʿathum dhurriyyatuhum biīmānin alḥaqnā bihim dhurriyyatahum wamā alatnāhum min ʿamalihim min shayin kullu im''ri-in bimā kasaba rahīnun', 'যারা ঈমান আনে আর তাদের সন্তান সন্ততিরা ঈমানের সাথে পিতামাতাকে অনুসরণ করে, আমি তাদের সাথে তাদের সন্তান সন্ততিকে মিলিত করব। তাদের ‘আমালের কোন কিছু থেকেই আমি তাদেরকে বঞ্চিত করব না। প্রত্যেক ব্যক্তিই নিজ কৃতকর্মের জন্য দায়বদ্ধ।', 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.', 'যারা ঈমান আনে আর তাদের সন্তান সন্ততিরা ঈমানের সাথে পিতামাতাকে অনুসরণ করে, আমি তাদের সাথে তাদের সন্তান সন্ততিকে মিলিত করব। তাদের ‘আমালের কোন কিছু থেকেই আমি তাদেরকে বঞ্চিত করব না। প্রত্যেক ব্যক্তিই নিজ কৃতকর্মের জন্য দায়বদ্ধ।', 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052021.mp3', now()),
  (52, 22, '', '[{"id":24664,"position":1,"text_uthmani":"وَأَمْدَدْنَـٰهُم","transliteration":"wa-amdadnāhum","translation_bn":"এবং তাদেরকে আমরা বেশি করে দেব","root":"مدد","lemma":"أَمَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24665,"position":2,"text_uthmani":"بِفَـٰكِهَةٍۢ","transliteration":"bifākihatin","translation_bn":"ফল মূল","root":"فكه","lemma":"فَٰكِهَة","grammar_bn":"অব্যয় (Preposition)"},{"id":24666,"position":3,"text_uthmani":"وَلَحْمٍۢ","transliteration":"walaḥmin","translation_bn":"ও গোশত","root":"لحم","lemma":"لَحْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24667,"position":4,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"তা হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24668,"position":5,"text_uthmani":"يَشْتَهُونَ","transliteration":"yashtahūna","translation_bn":"তারা পছন্দ করবে","root":"شهو","lemma":"ٱشْتَهَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24669,"position":6,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-amdadnāhum bifākihatin walaḥmin mimmā yashtahūna', 'আমি তাদেরকে দিব ফলমূল আর গোশত যা তারা পছন্দ করবে।', 'And We will provide them with fruit and meat from whatever they desire.', 'আমি তাদেরকে দিব ফলমূল আর গোশত যা তারা পছন্দ করবে।', 'And We will provide them with fruit and meat from whatever they desire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052022.mp3', now()),
  (52, 23, '', '[{"id":26136,"position":1,"text_uthmani":"يَتَنَـٰزَعُونَ","transliteration":"yatanāzaʿūna","translation_bn":"তারা পরস্পরে নেবে","root":"نزع","lemma":"تَنَٰزَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26137,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26138,"position":3,"text_uthmani":"كَأْسًۭا","transliteration":"kasan","translation_bn":"পানপাত্র","root":"كاس","lemma":"كَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":26139,"position":4,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":26140,"position":5,"text_uthmani":"لَغْوٌۭ","transliteration":"laghwun","translation_bn":"অসার কথা (হবে)","root":"لغو","lemma":"لَغْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":26141,"position":6,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26142,"position":7,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26143,"position":8,"text_uthmani":"تَأْثِيمٌۭ","transliteration":"tathīmun","translation_bn":"পাপকর্ম","root":"اثم","lemma":"تَأْثِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26144,"position":9,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'yatanāzaʿūna fīhā kasan lā laghwun fīhā walā tathīmun', 'তারা সেখানে পরস্পরের মধ্যে বিনিময় করবে পানপাত্র, থাকবে না সেখানে কোন বেহুদা বকবকানি, থাকবে না কোন পাপের কাজ।', 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.', 'তারা সেখানে পরস্পরের মধ্যে বিনিময় করবে পানপাত্র, থাকবে না সেখানে কোন বেহুদা বকবকানি, থাকবে না কোন পাপের কাজ।', 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/052023.mp3', now()),
  (52, 24, '', '[{"id":26808,"position":1,"text_uthmani":"۞ وَيَطُوفُ","transliteration":"wayaṭūfu","translation_bn":"এবং ঘুরতে থাকবে","root":"طوف","lemma":"طَافَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26809,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26810,"position":3,"text_uthmani":"غِلْمَانٌۭ","transliteration":"ghil''mānun","translation_bn":"কিশোরেরা (সেবা করতে)","root":"غلم","lemma":"غُلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26811,"position":4,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":26812,"position":5,"text_uthmani":"كَأَنَّهُمْ","transliteration":"ka-annahum","translation_bn":"(এত সুন্দর হবে) তারা যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26813,"position":6,"text_uthmani":"لُؤْلُؤٌۭ","transliteration":"lu''lu-on","translation_bn":"মুক্তা","root":"لالا","lemma":"لُؤْلُؤ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26814,"position":7,"text_uthmani":"مَّكْنُونٌۭ","transliteration":"maknūnun","translation_bn":"লুকিয়ে রাখা","root":"كنن","lemma":"مَّكْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":26815,"position":8,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wayaṭūfu ʿalayhim ghil''mānun lahum ka-annahum lu''lu-on maknūnun', 'তাদের চতুর্দিকে ঘুর ঘুর ক’রে তাদের সেবায় নিয়োজিত থাকবে কিশোরেরা (যারা এতই সুন্দর) যেন সযত্নে লুকিয়ে রাখা মণিমুক্তা।', 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.', 'তাদের চতুর্দিকে ঘুর ঘুর ক’রে তাদের সেবায় নিয়োজিত থাকবে কিশোরেরা (যারা এতই সুন্দর) যেন সযত্নে লুকিয়ে রাখা মণিমুক্তা।', 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.', NULL, NULL, NULL, NULL, NULL, 