  (53, 1, '', '[{"id":280,"position":1,"text_uthmani":"وَٱلنَّجْمِ","transliteration":"wal-najmi","translation_bn":"শপথ তারকার","root":"نجم","lemma":"نَّجْم","grammar_bn":"অব্যয় (Preposition)"},{"id":281,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":282,"position":3,"text_uthmani":"هَوَىٰ","transliteration":"hawā","translation_bn":"অস্তমিত হয়","root":"هوي","lemma":"هَوَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":283,"position":4,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-najmi idhā hawā', 'শপথ তারকার যখন তা অস্ত যায়,', 'By the star when it descends,', 'শপথ তারকার যখন তা অস্ত যায়,', 'By the star when it descends,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053001.mp3', now()),
  (53, 2, '', '[{"id":1162,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1163,"position":2,"text_uthmani":"ضَلَّ","transliteration":"ḍalla","translation_bn":"পথভ্রষ্ট হয়েছে","root":"ضلل","lemma":"ضَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1164,"position":3,"text_uthmani":"صَاحِبُكُمْ","transliteration":"ṣāḥibukum","translation_bn":"তোমাদের সঙ্গী","root":"صحب","lemma":"صَاحِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1165,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1166,"position":5,"text_uthmani":"غَوَىٰ","transliteration":"ghawā","translation_bn":"বিপথগামী হয়েছে","root":"غوي","lemma":"غَوَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1167,"position":6,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā ḍalla ṣāḥibukum wamā ghawā', 'তোমাদের (মাঝে ছোট থেকে বড় হয়েছে সেই) সঙ্গী গুমরাহও নয় আর ভুলপথে পরিচালিতও নয়,', 'Your companion [Muhammad] has not strayed, nor has he erred,', 'তোমাদের (মাঝে ছোট থেকে বড় হয়েছে সেই) সঙ্গী গুমরাহও নয় আর ভুলপথে পরিচালিতও নয়,', 'Your companion [Muhammad] has not strayed, nor has he erred,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053002.mp3', now()),
  (53, 3, '', '[{"id":2208,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2209,"position":2,"text_uthmani":"يَنطِقُ","transliteration":"yanṭiqu","translation_bn":"সে কথা বলে","root":"نطق","lemma":"يَنطِقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2210,"position":3,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2211,"position":4,"text_uthmani":"ٱلْهَوَىٰٓ","transliteration":"l-hawā","translation_bn":"প্রবৃত্তির তাড়না","root":"هوي","lemma":"هَوَا^ء","grammar_bn":"শব্দ"},{"id":2212,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yanṭiqu ʿani l-hawā', 'আর সে মনগড়া কথাও বলে না।', 'Nor does he speak from [his own] inclination.', 'আর সে মনগড়া কথাও বলে না।', 'Nor does he speak from [his own] inclination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053003.mp3', now()),
  (53, 4, '', '[{"id":3538,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":3539,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3540,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3541,"position":4,"text_uthmani":"وَحْىٌۭ","transliteration":"waḥyun","translation_bn":"ওহী","root":"وحي","lemma":"وَحْى","grammar_bn":"বিশেষ্য (Noun)"},{"id":3542,"position":5,"text_uthmani":"يُوحَىٰ","transliteration":"yūḥā","translation_bn":"অবতীর্ণ করা হয় (যা)","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":3543,"position":6,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'in huwa illā waḥyun yūḥā', 'তাতো ওয়াহী যা তার প্রতি প্রত্যাদেশ করা হয়,', 'It is not but a revelation revealed,', 'তাতো ওয়াহী যা তার প্রতি প্রত্যাদেশ করা হয়,', 'It is not but a revelation revealed,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053004.mp3', now()),
  (53, 5, '', '[{"id":4898,"position":1,"text_uthmani":"عَلَّمَهُۥ","transliteration":"ʿallamahu","translation_bn":"তাকে শিক্ষা দিয়েছে","root":"علم","lemma":"عَلَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4899,"position":2,"text_uthmani":"شَدِيدُ","transliteration":"shadīdu","translation_bn":"(জিবরাইল) অত্যন্তপ্রবল","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4900,"position":3,"text_uthmani":"ٱلْقُوَىٰ","transliteration":"l-quwā","translation_bn":"শক্তিতে","root":"قوي","lemma":"قُوَّة","grammar_bn":"শব্দ"},{"id":4901,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ʿallamahu shadīdu l-quwā', 'তাকে শিক্ষা দেয় শক্তিশালী,', 'Taught to him by one intense in strength -', 'তাকে শিক্ষা দেয় শক্তিশালী,', 'Taught to him by one intense in strength -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053005.mp3', now()),
  (53, 6, '', '[{"id":6144,"position":1,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"আছে","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":6145,"position":2,"text_uthmani":"مِرَّةٍۢ","transliteration":"mirratin","translation_bn":"কৌশলসম্পন্ন","root":"مرر","lemma":"مِرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6146,"position":3,"text_uthmani":"فَٱسْتَوَىٰ","transliteration":"fa-is''tawā","translation_bn":"অতঃপর সে স্থির হয়ে (দাঁড়িয়ে) ছিল","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6147,"position":4,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'dhū mirratin fa-is''tawā', 'প্রজ্ঞার অধিকারী (জিবরাঈল) সে নিজ আকৃতিতে স্থির হয়ে ছিল,', 'One of soundness. And he rose to [his] true form', 'প্রজ্ঞার অধিকারী (জিবরাঈল) সে নিজ আকৃতিতে স্থির হয়ে ছিল,', 'One of soundness. And he rose to [his] true form', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053006.mp3', now()),
  (53, 7, '', '[{"id":7482,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এমতাবস্থায় সে (ছিল)","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":7483,"position":2,"text_uthmani":"بِٱلْأُفُقِ","transliteration":"bil-ufuqi","translation_bn":"দিগন্তে","root":"افق","lemma":"أُفُق","grammar_bn":"অব্যয় (Preposition)"},{"id":7484,"position":3,"text_uthmani":"ٱلْأَعْلَىٰ","transliteration":"l-aʿlā","translation_bn":"ঊর্ধ্ব","root":"علو","lemma":"أَعْلَىٰ","grammar_bn":"শব্দ"},{"id":7485,"position":4,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa bil-ufuqi l-aʿlā', 'আর সে ছিল ঊর্ধ্ব দিগন্তে,', 'While he was in the higher [part of the] horizon.', 'আর সে ছিল ঊর্ধ্ব দিগন্তে,', 'While he was in the higher [part of the] horizon.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053007.mp3', now()),
  (53, 8, '', '[{"id":8727,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8728,"position":2,"text_uthmani":"دَنَا","transliteration":"danā","translation_bn":"সে কাছে এল","root":"دنو","lemma":"دَنَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":8729,"position":3,"text_uthmani":"فَتَدَلَّىٰ","transliteration":"fatadallā","translation_bn":"অতঃপর শূন্যে ভেসে রইল","root":"دلو","lemma":"تَدَلَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8730,"position":4,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma danā fatadallā', 'অতঃপর সে (নবীর) নিকটবর্তী হল, অতঃপর আসলো আরো নিকটে,', 'Then he approached and descended', 'অতঃপর সে (নবীর) নিকটবর্তী হল, অতঃপর আসলো আরো নিকটে,', 'Then he approached and descended', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053008.mp3', now()),
  (53, 9, '', '[{"id":9952,"position":1,"text_uthmani":"فَكَانَ","transliteration":"fakāna","translation_bn":"ফলে সে হল","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9953,"position":2,"text_uthmani":"قَابَ","transliteration":"qāba","translation_bn":"দূরত্বে","root":"قوب","lemma":"قَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":9954,"position":3,"text_uthmani":"قَوْسَيْنِ","transliteration":"qawsayni","translation_bn":"দুই ধনুকের","root":"قوس","lemma":"قَوْسَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":9955,"position":4,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9956,"position":5,"text_uthmani":"أَدْنَىٰ","transliteration":"adnā","translation_bn":"(তারও) কিছু কম","root":"دنو","lemma":"أَدْنَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9957,"position":6,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'fakāna qāba qawsayni aw adnā', 'ফলে [নবী (সাঃ) ও জিবরাঈলের মাঝে] দুই ধনুকের ব্যবধান রইল অথবা আরো কম।', 'And was at a distance of two bow lengths or nearer.', 'ফলে [নবী (সাঃ) ও জিবরাঈলের মাঝে] দুই ধনুকের ব্যবধান রইল অথবা আরো কম।', 'And was at a distance of two bow lengths or nearer.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053009.mp3', now()),
  (53, 10, '', '[{"id":11155,"position":1,"text_uthmani":"فَأَوْحَىٰٓ","transliteration":"fa-awḥā","translation_bn":"অতঃপর সে ওহী পৌঁছাল","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"শব্দ"},{"id":11156,"position":2,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11157,"position":3,"text_uthmani":"عَبْدِهِۦ","transliteration":"ʿabdihi","translation_bn":"তাঁর (অর্থাৎ আল্লাহর) বান্দার/ দাসের","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11158,"position":4,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11159,"position":5,"text_uthmani":"أَوْحَىٰ","transliteration":"awḥā","translation_bn":"ওহী পৌঁছানোর","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":11160,"position":6,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-awḥā ilā ʿabdihi mā awḥā', 'তখন (আল্লাহ) তাঁর বান্দাহর প্রতি ওয়াহী করলেন যা ওয়াহী করার ছিল।', 'And he revealed to His Servant what he revealed.', 'তখন (আল্লাহ) তাঁর বান্দাহর প্রতি ওয়াহী করলেন যা ওয়াহী করার ছিল।', 'And he revealed to His Servant what he revealed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053010.mp3', now()),
  (53, 11, '', '[{"id":12481,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":12482,"position":2,"text_uthmani":"كَذَبَ","transliteration":"kadhaba","translation_bn":"মিথ্যা বলেছে","root":"كذب","lemma":"كَذَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12483,"position":3,"text_uthmani":"ٱلْفُؤَادُ","transliteration":"l-fuādu","translation_bn":"(তার) অন্তর","root":"فاد","lemma":"فُؤَاد","grammar_bn":"শব্দ"},{"id":12484,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12485,"position":5,"text_uthmani":"رَأَىٰٓ","transliteration":"raā","translation_bn":"সে দেখেছে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":12486,"position":6,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'mā kadhaba l-fuādu mā raā', '(নবীর) অন্তঃকরণ মিথ্যে মনে করেনি যা সে দেখে ছিল।', 'The heart did not lie [about] what it saw.', '(নবীর) অন্তঃকরণ মিথ্যে মনে করেনি যা সে দেখে ছিল।', 'The heart did not lie [about] what it saw.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053011.mp3', now()),
  (53, 12, '', '[{"id":13797,"position":1,"text_uthmani":"أَفَتُمَـٰرُونَهُۥ","transliteration":"afatumārūnahu","translation_bn":"তার সাথে তোমরা এখন কি তর্ক করছ","root":"مري","lemma":"تَمَارَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":13798,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"(তার) উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13799,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13800,"position":4,"text_uthmani":"يَرَىٰ","transliteration":"yarā","translation_bn":"সে দেখেছে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":13801,"position":5,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'afatumārūnahu ʿalā mā yarā', 'সে যা দেখেছে সে বিষয়ে তোমরা কি তার সঙ্গে বিতর্ক করবে?', 'So will you dispute with him over what he saw?', 'সে যা দেখেছে সে বিষয়ে তোমরা কি তার সঙ্গে বিতর্ক করবে?', 'So will you dispute with him over what he saw?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053012.mp3', now()),
