  (53, 14, '', '[{"id":16023,"position":1,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":16024,"position":2,"text_uthmani":"سِدْرَةِ","transliteration":"sid''rati","translation_bn":"কুলগাছের","root":"سدر","lemma":"سِدْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16025,"position":3,"text_uthmani":"ٱلْمُنتَهَىٰ","transliteration":"l-muntahā","translation_bn":"(জড়জগতের) শেষপ্রান্তে","root":"نهي","lemma":"مُنتَهَىٰ","grammar_bn":"শব্দ"},{"id":16026,"position":4,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'ʿinda sid''rati l-muntahā', 'শেষসীমার বরই গাছের কাছে,', 'At the Lote Tree of the Utmost Boundary -', 'শেষসীমার বরই গাছের কাছে,', 'At the Lote Tree of the Utmost Boundary -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/053014.mp3', now()),
