  (54, 21, '', '[{"id":23734,"position":1,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"কেমন অতএব","root":"كيف\r","lemma":"كَيْف","grammar_bn":"শব্দ"},{"id":23735,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23736,"position":3,"text_uthmani":"عَذَابِى","transliteration":"ʿadhābī","translation_bn":"আমার শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23737,"position":4,"text_uthmani":"وَنُذُرِ","transliteration":"wanudhuri","translation_bn":"ও আমার সতর্কবাণী (লক্ষ্যকর)","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23738,"position":5,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'fakayfa kāna ʿadhābī wanudhuri', 'ফলে কত ভয়ংকর ছিল আমার ‘আযাব ও ভীতি প্রদর্শন।', 'And how [severe] were My punishment and warning.', 'ফলে কত ভয়ংকর ছিল আমার ‘আযাব ও ভীতি প্রদর্শন।', 'And how [severe] were My punishment and warning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054021.mp3', now()),
  (54, 22, '', '[{"id":24694,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24695,"position":2,"text_uthmani":"يَسَّرْنَا","transliteration":"yassarnā","translation_bn":"আমরা সহজ করেছি","root":"يسر","lemma":"يَسَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24696,"position":3,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুরআনকে","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":24697,"position":4,"text_uthmani":"لِلذِّكْرِ","transliteration":"lildhik''ri","translation_bn":"উপদেশ গ্রহণের জন্যে","root":"ذكر","lemma":"ذِكْر","grammar_bn":"অব্যয় (Preposition)"},{"id":24698,"position":5,"text_uthmani":"فَهَلْ","transliteration":"fahal","translation_bn":"তবে কি (আছে)","root":"—","lemma":"هَل\r","grammar_bn":"শব্দ"},{"id":24699,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24700,"position":7,"text_uthmani":"مُّدَّكِرٍۢ","transliteration":"muddakirin","translation_bn":"উপদেশ গ্রহণকারী","root":"ذكر","lemma":"مُّدَّكِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24701,"position":8,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad yassarnā l-qur''āna lildhik''ri fahal min muddakirin', 'আমি কুরআনকে সহজ করে দিয়েছি উপদেশ গ্রহণের জন্য, উপদেশ গ্রহণের কেউ আছে কি?', 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', 'আমি কুরআনকে সহজ করে দিয়েছি উপদেশ গ্রহণের জন্য, উপদেশ গ্রহণের কেউ আছে কি?', 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054022.mp3', now()),
  (54, 23, '', '[{"id":26023,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিল","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26024,"position":2,"text_uthmani":"ثَمُودُ","transliteration":"thamūdu","translation_bn":"সামুদ''","root":"—","lemma":"ثَمُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26025,"position":3,"text_uthmani":"بِٱلنُّذُرِ","transliteration":"bil-nudhuri","translation_bn":"সতর্ককারীদেরকে","root":"نذر","lemma":"نَذِير","grammar_bn":"অব্যয় (Preposition)"},{"id":26026,"position":4,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat thamūdu bil-nudhuri', 'সামূদ জাতিও ভয়প্রদর্শনকারীদেরকে অস্বীকার করেছিল,', 'Thamud denied the warning', 'সামূদ জাতিও ভয়প্রদর্শনকারীদেরকে অস্বীকার করেছিল,', 'Thamud denied the warning', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054023.mp3', now()),
  (54, 24, '', '[{"id":26858,"position":1,"text_uthmani":"فَقَالُوٓا۟","transliteration":"faqālū","translation_bn":"তারা তখন বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26859,"position":2,"text_uthmani":"أَبَشَرًۭا","transliteration":"abasharan","translation_bn":"\"মানুষ কি","root":"بشر","lemma":"بَشَر","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":26860,"position":3,"text_uthmani":"مِّنَّا","transliteration":"minnā","translation_bn":"আমাদের মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26861,"position":4,"text_uthmani":"وَٰحِدًۭا","transliteration":"wāḥidan","translation_bn":"একজন","root":"وحد","lemma":"وَٰحِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":26862,"position":5,"text_uthmani":"نَّتَّبِعُهُۥٓ","transliteration":"nattabiʿuhu","translation_bn":"যাকে আমরা অনুসরণ করবো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26863,"position":6,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26864,"position":7,"text_uthmani":"إِذًۭا","transliteration":"idhan","translation_bn":"তখন (হব)","root":"—","lemma":"إِذًا\r","grammar_bn":"আশ্চর্যসূচক (Surprise)"},{"id":26865,"position":8,"text_uthmani":"لَّفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":26866,"position":9,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"ভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26867,"position":10,"text_uthmani":"وَسُعُرٍ","transliteration":"wasuʿurin","translation_bn":"ও বিকৃতবুদ্ধির","root":"سعر","lemma":"سُعُر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26868,"position":11,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'faqālū abasharan minnā wāḥidan nattabiʿuhu innā idhan lafī ḍalālin wasuʿurin', 'তারা বলেছিল, ‘আমরা কি আমাদেরই মধ্যেকার মাত্র একটা লোকের অনুসরণ করব? তাহলে তো আমরা গুমরাহী আর পাগলামিতে পড়ে যাব।', 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.', 'তারা বলেছিল, ‘আমরা কি আমাদেরই মধ্যেকার মাত্র একটা লোকের অনুসরণ করব? তাহলে তো আমরা গুমরাহী আর পাগলামিতে পড়ে যাব।', 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054024.mp3', now()),
  (54, 25, '', '[{"id":27888,"position":1,"text_uthmani":"أَءُلْقِىَ","transliteration":"a-ul''qiya","translation_bn":"অবতীর্ণ করা হয়েছে কি","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":27889,"position":2,"text_uthmani":"ٱلذِّكْرُ","transliteration":"l-dhik''ru","translation_bn":"উপদেশ (আল্লাহর বিধান)","root":"ذكر","lemma":"ذِكْر","grammar_bn":"শব্দ"},{"id":27890,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27891,"position":4,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27892,"position":5,"text_uthmani":"بَيْنِنَا","transliteration":"bayninā","translation_bn":"আমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":27893,"position":6,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":27894,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":27895,"position":8,"text_uthmani":"كَذَّابٌ","transliteration":"kadhābun","translation_bn":"খুব মিথ্যাবাদী","root":"كذب","lemma":"كَذَّاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":27896,"position":9,"text_uthmani":"أَشِرٌۭ","transliteration":"ashirun","translation_bn":"দাম্ভিক\"","root":"اشر","lemma":"أَشِر","grammar_bn":"বিশেষণ (Adjective)"},{"id":27897,"position":10,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'a-ul''qiya l-dhik''ru ʿalayhi min bayninā bal huwa kadhābun ashirun', 'আমাদের (এত মানুষের) মধ্যে শুধু কি তার উপরই বাণী পাঠানো হয়েছে? না, বরং সে বড়ই মিথ্যুক, দাম্ভিক।', 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."', 'আমাদের (এত মানুষের) মধ্যে শুধু কি তার উপরই বাণী পাঠানো হয়েছে? না, বরং সে বড়ই মিথ্যুক, দাম্ভিক।', 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054025.mp3', now()),
  (54, 26, '', '[{"id":29053,"position":1,"text_uthmani":"سَيَعْلَمُونَ","transliteration":"sayaʿlamūna","translation_bn":"(বলা হল) অচিরেই তারা জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":29054,"position":2,"text_uthmani":"غَدًۭا","transliteration":"ghadan","translation_bn":"আগামীকালই","root":"غدو","lemma":"غَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":29055,"position":3,"text_uthmani":"مَّنِ","transliteration":"mani","translation_bn":"কে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29056,"position":4,"text_uthmani":"ٱلْكَذَّابُ","transliteration":"l-kadhābu","translation_bn":"খুব মিথ্যাবাদী","root":"كذب","lemma":"كَذَّاب","grammar_bn":"শব্দ"},{"id":29057,"position":5,"text_uthmani":"ٱلْأَشِرُ","transliteration":"l-ashiru","translation_bn":"দাম্ভিক","root":"اشر","lemma":"أَشِر","grammar_bn":"শব্দ"},{"id":29058,"position":6,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'sayaʿlamūna ghadan mani l-kadhābu l-ashiru', 'আগামীকালই তারা জানতে পারবে কে বড়ই মিথ্যুক, দাম্ভিক', 'They will know tomorrow who is the insolent liar.', 'আগামীকালই তারা জানতে পারবে কে বড়ই মিথ্যুক, দাম্ভিক', 'They will know tomorrow who is the insolent liar.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054026.mp3', now()),
  (54, 27, '', '[{"id":29669,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29670,"position":2,"text_uthmani":"مُرْسِلُوا۟","transliteration":"mur''silū","translation_bn":"প্রেরণকারী","root":"رسل","lemma":"مُرْسِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":29671,"position":3,"text_uthmani":"ٱلنَّاقَةِ","transliteration":"l-nāqati","translation_bn":"একটি উটনী","root":"نوق","lemma":"نَاقَة","grammar_bn":"শব্দ"},{"id":29672,"position":4,"text_uthmani":"فِتْنَةًۭ","transliteration":"fit''natan","translation_bn":"পরীক্ষা হিসেবে","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":29673,"position":5,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":29674,"position":6,"text_uthmani":"فَٱرْتَقِبْهُمْ","transliteration":"fa-ir''taqib''hum","translation_bn":"অতএব তুমি তাদের প্রতি লক্ষ্য রাখ","root":"رقب","lemma":"ٱرْتَقِبْ","grammar_bn":"শব্দ"},{"id":29675,"position":7,"text_uthmani":"وَٱصْطَبِرْ","transliteration":"wa-iṣ''ṭabir","translation_bn":"ও ধৈর্য ধরো","root":"صبر","lemma":"ٱصْطَبِرْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29676,"position":8,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'innā mur''silū l-nāqati fit''natan lahum fa-ir''taqib''hum wa-iṣ''ṭabir', 'আমি একটা উষ্ট্রী পাঠাচ্ছি, তাদেরকে পরীক্ষা করার জন্য, কাজেই (হে সালিহ!) তুমি তাদের আচরণ লক্ষ্য কর আর ধৈর্য ধর।', 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.', 'আমি একটা উষ্ট্রী পাঠাচ্ছি, তাদেরকে পরীক্ষা করার জন্য, কাজেই (হে সালিহ!) তুমি তাদের আচরণ লক্ষ্য কর আর ধৈর্য ধর।', 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054027.mp3', now()),
  (54, 28, '', '[{"id":30749,"position":1,"text_uthmani":"وَنَبِّئْهُمْ","transliteration":"wanabbi''hum","translation_bn":"এবং তাদের জানিয়ে দাও","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30750,"position":2,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":30751,"position":3,"text_uthmani":"ٱلْمَآءَ","transliteration":"l-māa","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"শব্দ"},{"id":30752,"position":4,"text_uthmani":"قِسْمَةٌۢ","transliteration":"qis''matun","translation_bn":"পালা করে দেওয়া হলো (হয়েছে)","root":"قسم","lemma":"قِسْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":30753,"position":5,"text_uthmani":"بَيْنَهُمْ ۖ","transliteration":"baynahum","translation_bn":"তাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":30755,"position":6,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেকে","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30756,"position":7,"text_uthmani":"شِرْبٍۢ","transliteration":"shir''bin","translation_bn":"পান করতে","root":"شرب","lemma":"شِرْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":30757,"position":8,"text_uthmani":"مُّحْتَضَرٌۭ","transliteration":"muḥ''taḍarun","translation_bn":"উপস্থিত হবে (পালাক্রমে)","root":"حضر","lemma":"مُّحْتَضَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":30758,"position":9,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wanabbi''hum anna l-māa qis''matun baynahum kullu shir''bin muḥ''taḍarun', 'আর তাদেরকে জানিয়ে দাও যে, তাদের মধ্যে (ও উষ্ট্রীর মধ্যে) পানি বণ্টিত হবে, প্রত্যেকের পানি পানের পালা আসবে।', 'And inform them that the water is shared between them, each [day of] drink attended [by turn].', 'আর তাদেরকে জানিয়ে দাও যে, তাদের মধ্যে (ও উষ্ট্রীর মধ্যে) পানি বণ্টিত হবে, প্রত্যেকের পানি পানের পালা আসবে।', 'And inform them that the water is shared between them, each [day of] drink attended [by turn].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054028.mp3', now()),
  (54, 29, '', '[{"id":31830,"position":1,"text_uthmani":"فَنَادَوْا۟","transliteration":"fanādaw","translation_bn":"তারা অতঃপর ডাকল","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"শব্দ"},{"id":31831,"position":2,"text_uthmani":"صَاحِبَهُمْ","transliteration":"ṣāḥibahum","translation_bn":"তাদের এক সঙ্গীকে","root":"صحب","lemma":"صَاحِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":31832,"position":3,"text_uthmani":"فَتَعَاطَىٰ","transliteration":"fataʿāṭā","translation_bn":"সে তখন হস্তক্ষেপ করল","root":"عطو","lemma":"تَعَاطَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31833,"position":4,"text_uthmani":"فَعَقَرَ","transliteration":"faʿaqara","translation_bn":"সে অতঃপর উটনী মেরে ফেলল","root":"عقر","lemma":"عَقَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31834,"position":5,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'fanādaw ṣāḥibahum fataʿāṭā faʿaqara', 'শেষে তারা তাদের এক সঙ্গীকে ডাকল আর সে তাকে (অর্থাৎ উষ্ট্রীটিকে) ধরে হত্যা করল।', 'But they called their companion, and he dared and hamstrung [her].', 'শেষে তারা তাদের এক সঙ্গীকে ডাকল আর সে তাকে (অর্থাৎ উষ্ট্রীটিকে) ধরে হত্যা করল।', 'But they called their companion, and he dared and hamstrung [her].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054029.mp3', now()),
  (54, 30, '', '[{"id":32681,"position":1,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"তখন কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"শব্দ"},{"id":32682,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32683,"position":3,"text_uthmani":"عَذَابِى","transliteration":"ʿadhābī","translation_bn":"আমার শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":32684,"position":4,"text_uthmani":"وَنُذُرِ","transliteration":"wanudhuri","translation_bn":"ও আমার সতর্কবাণী (তা লক্ষ্যকর)","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32685,"position":5,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'fakayfa kāna ʿadhābī wanudhuri', 'ফলে কত ভয়ংকর হয়েছিল আমার ‘আযাব ও ভীতি প্রদর্শন।', 'And how [severe] were My punishment and warning.', 'ফলে কত ভয়ংকর হয়েছিল আমার ‘আযাব ও ভীতি প্রদর্শন।', 'And how [severe] were My punishment and warning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054030.mp3', now()),
  (54, 31, '', '[{"id":33536,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":33537,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠালাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33538,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33539,"position":4,"text_uthmani":"صَيْحَةًۭ","transliteration":"ṣayḥatan","translation_bn":"প্রচণ্ড গর্জন","root":"صيح","lemma":"صَيْحَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33540,"position":5,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একটি (মাত্র)","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33541,"position":6,"text_uthmani":"فَكَانُوا۟","transliteration":"fakānū","translation_bn":"ফলে তারা হয়ে গেল","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33542,"position":7,"text_uthmani":"كَهَشِيمِ","transliteration":"kahashīmi","translation_bn":"শুকনা খড়্রের মতো","root":"هشم","lemma":"هَشِيم","grammar_bn":"অব্যয় (Preposition)"},{"id":33543,"position":8,"text_uthmani":"ٱلْمُحْتَظِرِ","transliteration":"l-muḥ''taẓiri","translation_bn":"খোঁয়াড় প্রস্তুতকারীর","root":"حظر","lemma":"مُحْتَظِر","grammar_bn":"শব্দ"},{"id":33544,"position":9,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'innā arsalnā ʿalayhim ṣayḥatan wāḥidatan fakānū kahashīmi l-muḥ''taẓiri', 'আমি তাদের উপর পাঠিয়েছিলাম একটি মাত্র প্রচন্ড ধ্বনি। ফলে তারা খোঁয়াড়ওয়ালাদের (নির্মিত) ভেঙ্গে চুরে যাওয়া শুকনা ডালপালার মত গুঁড়িয়ে গেল।', 'Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen.', 'আমি তাদের উপর পাঠিয়েছিলাম একটি মাত্র প্রচন্ড ধ্বনি। ফলে তারা খোঁয়াড়ওয়ালাদের (নির্মিত) ভেঙ্গে চুরে যাওয়া শুকনা ডালপালার মত গুঁড়িয়ে গেল।', 'Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054031.mp3', now()),
  (54, 32, '', '[{"id":34630,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34631,"position":2,"text_uthmani":"يَسَّرْنَا","transliteration":"yassarnā","translation_bn":"আমরা সহজ করেছি","root":"يسر","lemma":"يَسَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34632,"position":3,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুরআনকে","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":34633,"position":4,"text_uthmani":"لِلذِّكْرِ","transliteration":"lildhik''ri","translation_bn":"উপদেশ গ্রহনের জন্যে","root":"ذكر","lemma":"ذِكْر","grammar_bn":"অব্যয় (Preposition)"},{"id":34634,"position":5,"text_uthmani":"فَهَلْ","transliteration":"fahal","translation_bn":"কি তবে (আছে)","root":"—","lemma":"هَل\r","grammar_bn":"শব্দ"},{"id":34635,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34636,"position":7,"text_uthmani":"مُّدَّكِرٍۢ","transliteration":"muddakirin","translation_bn":"উপদেশ গ্রহণকারী","root":"ذكر","lemma":"مُّدَّكِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":34637,"position":8,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad yassarnā l-qur''āna lildhik''ri fahal min muddakirin', 'আমি কুরআনকে সহজ করে দিয়েছি উপদেশ গ্রহণের জন্য, উপদেশ গ্রহণের কেউ আছে কি?', 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', 'আমি কুরআনকে সহজ করে দিয়েছি উপদেশ গ্রহণের জন্য, উপদেশ গ্রহণের কেউ আছে কি?', 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054032.mp3', now()),
  (54, 33, '', '[{"id":35421,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিল","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35422,"position":2,"text_uthmani":"قَوْمُ","transliteration":"qawmu","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":35423,"position":3,"text_uthmani":"لُوطٍۭ","transliteration":"lūṭin","translation_bn":"লূতের","root":"—","lemma":"لُوط","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":35424,"position":4,"text_uthmani":"بِٱلنُّذُرِ","transliteration":"bil-nudhuri","translation_bn":"সতর্কবাণীকে","root":"نذر","lemma":"نَذِير","grammar_bn":"অব্যয় (Preposition)"},{"id":35425,"position":5,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat qawmu lūṭin bil-nudhuri', 'লূতের জাতি সতর্কবাণী প্রত্যাখ্যান করেছিল,', 'The people of Lot denied the warning.', 'লূতের জাতি সতর্কবাণী প্রত্যাখ্যান করেছিল,', 'The people of Lot denied the warning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054033.mp3', now()),
