  (54, 39, '', '[{"id":40518,"position":1,"text_uthmani":"فَذُوقُوا۟","transliteration":"fadhūqū","translation_bn":"তোমরা এখন স্বাদ নাও","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"শব্দ"},{"id":40519,"position":2,"text_uthmani":"عَذَابِى","transliteration":"ʿadhābī","translation_bn":"আমার শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":40520,"position":3,"text_uthmani":"وَنُذُرِ","transliteration":"wanudhuri","translation_bn":"ও আমার সতর্কবাণীর","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40521,"position":4,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'fadhūqū ʿadhābī wanudhuri', 'তখন আমি বললাম- ‘আমার শাস্তি ও সতর্কবাণীর স্বাদ গ্রহণ কর।', 'So taste My punishment and warning.', 'তখন আমি বললাম- ‘আমার শাস্তি ও সতর্কবাণীর স্বাদ গ্রহণ কর।', 'So taste My punishment and warning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/054039.mp3', now()),
