  (55, 7, '', '[{"id":7495,"position":1,"text_uthmani":"وَٱلسَّمَآءَ","transliteration":"wal-samāa","translation_bn":"এবং আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7496,"position":2,"text_uthmani":"رَفَعَهَا","transliteration":"rafaʿahā","translation_bn":"তা সমুন্নত করেছেন তিনি","root":"رفع","lemma":"رَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7497,"position":3,"text_uthmani":"وَوَضَعَ","transliteration":"wawaḍaʿa","translation_bn":"ও স্থাপন করেছেন","root":"وضع","lemma":"وَضَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7498,"position":4,"text_uthmani":"ٱلْمِيزَانَ","transliteration":"l-mīzāna","translation_bn":"মানদণ্ড","root":"وزن","lemma":"مِيزَان","grammar_bn":"শব্দ"},{"id":7499,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-samāa rafaʿahā wawaḍaʿa l-mīzāna', 'তিনি আকাশকে করেছেন সমুন্নত, আর স্থাপন করেছেন (ন্যায়ের) মানদন্ড,', 'And the heaven He raised and imposed the balance', 'তিনি আকাশকে করেছেন সমুন্নত, আর স্থাপন করেছেন (ন্যায়ের) মানদন্ড,', 'And the heaven He raised and imposed the balance', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055007.mp3', now()),
  (55, 8, '', '[{"id":8741,"position":1,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"(ঐকান্তিক দাবি) না যেন","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":8742,"position":2,"text_uthmani":"تَطْغَوْا۟","transliteration":"taṭghaw","translation_bn":"তোমরা সীমা লঙ্ঘন কর","root":"طغي","lemma":"طَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8743,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8744,"position":4,"text_uthmani":"ٱلْمِيزَانِ","transliteration":"l-mīzāni","translation_bn":"মানদণ্ডের","root":"وزن","lemma":"مِيزَان","grammar_bn":"শব্দ"},{"id":8745,"position":5,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'allā taṭghaw fī l-mīzāni', 'যাতে তোমরা মানদন্ডে সীমালঙ্ঘন না কর,', 'That you not transgress within the balance.', 'যাতে তোমরা মানদন্ডে সীমালঙ্ঘন না কর,', 'That you not transgress within the balance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055008.mp3', now()),
  (55, 9, '', '[{"id":9969,"position":1,"text_uthmani":"وَأَقِيمُوا۟","transliteration":"wa-aqīmū","translation_bn":"এবং তোমরা প্রতিষ্ঠা করো","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9970,"position":2,"text_uthmani":"ٱلْوَزْنَ","transliteration":"l-wazna","translation_bn":"ওজন","root":"وزن","lemma":"وَزْن","grammar_bn":"শব্দ"},{"id":9971,"position":3,"text_uthmani":"بِٱلْقِسْطِ","transliteration":"bil-qis''ṭi","translation_bn":"ন্যায্য ভাবে","root":"قسط","lemma":"قِسْط","grammar_bn":"অব্যয় (Preposition)"},{"id":9972,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9973,"position":5,"text_uthmani":"تُخْسِرُوا۟","transliteration":"tukh''sirū","translation_bn":"তোমরা কম দিয়ো","root":"خسر","lemma":"يُخْسِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9974,"position":6,"text_uthmani":"ٱلْمِيزَانَ","transliteration":"l-mīzāna","translation_bn":"দাঁড়িপাল্লায়/ পরিমাপে","root":"وزن","lemma":"مِيزَان","grammar_bn":"শব্দ"},{"id":9975,"position":7,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-aqīmū l-wazna bil-qis''ṭi walā tukh''sirū l-mīzāna', 'সুবিচারের সঙ্গে ওজন প্রতিষ্ঠা কর আর ওজনে কম দিও না,', 'And establish weight in justice and do not make deficient the balance.', 'সুবিচারের সঙ্গে ওজন প্রতিষ্ঠা কর আর ওজনে কম দিও না,', 'And establish weight in justice and do not make deficient the balance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055009.mp3', now()),
