  (55, 22, '', '[{"id":24746,"position":1,"text_uthmani":"يَخْرُجُ","transliteration":"yakhruju","translation_bn":"বের হয়","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24747,"position":2,"text_uthmani":"مِنْهُمَا","transliteration":"min''humā","translation_bn":"তাদের উভয় হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24748,"position":3,"text_uthmani":"ٱللُّؤْلُؤُ","transliteration":"l-lu''lu-u","translation_bn":"মুক্তা","root":"لالا","lemma":"لُؤْلُؤ","grammar_bn":"শব্দ"},{"id":24749,"position":4,"text_uthmani":"وَٱلْمَرْجَانُ","transliteration":"wal-marjānu","translation_bn":"ও প্রবাল","root":"مرج","lemma":"مَرْجَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24750,"position":5,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'yakhruju min''humā l-lu''lu-u wal-marjānu', 'এ সব দরিয়া হতে বের হয় মুক্তা ও প্রবাল,', 'From both of them emerge pearl and coral.', 'এ সব দরিয়া হতে বের হয় মুক্তা ও প্রবাল,', 'From both of them emerge pearl and coral.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055022.mp3', now()),
