  (55, 26, '', '[{"id":28868,"position":1,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক (জিনিস)","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28869,"position":2,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28870,"position":3,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"তার উপর (আছে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28871,"position":4,"text_uthmani":"فَانٍۢ","transliteration":"fānin","translation_bn":"নশ্বর","root":"فني","lemma":"فَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":28872,"position":5,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'kullu man ʿalayhā fānin', 'পৃথিবী পৃষ্ঠে যা আছে সবই ধ্বংসশীল,', 'Everyone upon the earth will perish,', 'পৃথিবী পৃষ্ঠে যা আছে সবই ধ্বংসশীল,', 'Everyone upon the earth will perish,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055026.mp3', now()),
