  (55, 33, '', '[{"id":35426,"position":1,"text_uthmani":"يَـٰمَعْشَرَ","transliteration":"yāmaʿshara","translation_bn":"হে সম্প্রদায়","root":"عشر","lemma":"مَعْشَر","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":35427,"position":2,"text_uthmani":"ٱلْجِنِّ","transliteration":"l-jini","translation_bn":"জিনের","root":"جنن","lemma":"جِنّ","grammar_bn":"শব্দ"},{"id":35428,"position":3,"text_uthmani":"وَٱلْإِنسِ","transliteration":"wal-insi","translation_bn":"ও মানবের","root":"انس","lemma":"إِنس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35429,"position":4,"text_uthmani":"إِنِ","transliteration":"ini","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":35430,"position":5,"text_uthmani":"ٱسْتَطَعْتُمْ","transliteration":"is''taṭaʿtum","translation_bn":"তোমরা পার","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35431,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":35432,"position":7,"text_uthmani":"تَنفُذُوا۟","transliteration":"tanfudhū","translation_bn":"তোমরা অতিক্রম করে পালাও","root":"نفذ","lemma":"تَنفُذُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35433,"position":8,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35434,"position":9,"text_uthmani":"أَقْطَارِ","transliteration":"aqṭāri","translation_bn":"সীমা সমূহ","root":"قطر","lemma":"أَقْطَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":35435,"position":10,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":35436,"position":11,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35437,"position":12,"text_uthmani":"فَٱنفُذُوا۟ ۚ","transliteration":"fa-unfudhū","translation_bn":"তবে তোমরা অতিক্রম করো","root":"نفذ","lemma":"تَنفُذُ","grammar_bn":"শব্দ"},{"id":35439,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":35440,"position":14,"text_uthmani":"تَنفُذُونَ","transliteration":"tanfudhūna","translation_bn":"তোমরা অতিক্রম করে পালাতে পারবে","root":"نفذ","lemma":"تَنفُذُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35441,"position":15,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":35442,"position":16,"text_uthmani":"بِسُلْطَـٰنٍۢ","transliteration":"bisul''ṭānin","translation_bn":"শক্তি দিয়ে (যা তোমাদের নেই)","root":"سلط","lemma":"سُلْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":35443,"position":17,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'yāmaʿshara l-jini wal-insi ini is''taṭaʿtum an tanfudhū min aqṭāri l-samāwāti wal-arḍi fa-unfudhū lā tanfudhūna illā bisul''ṭānin', 'হে জ্বিন ও মানুষ জাতি! তোমরা যদি আকাশ ও পৃথিবীর সীমানা অতিক্রম করতে পার তাহলে অতিক্রম কর, কিন্তু (আল্লাহর) প্রমাণপত্র ছাড়া তোমরা তা অতিক্রম করতে পারবে না।', 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah].', 'হে জ্বিন ও মানুষ জাতি! তোমরা যদি আকাশ ও পৃথিবীর সীমানা অতিক্রম করতে পার তাহলে অতিক্রম কর, কিন্তু (আল্লাহর) প্রমাণপত্র ছাড়া তোমরা তা অতিক্রম করতে পারবে না।', 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055033.mp3', now()),
  (55, 34, '', '[{"id":36349,"position":1,"text_uthmani":"فَبِأَىِّ","transliteration":"fabi-ayyi","translation_bn":"অতএব কোন কোন","root":"—","lemma":"أَىّ","grammar_bn":"শব্দ"},{"id":36350,"position":2,"text_uthmani":"ءَالَآءِ","transliteration":"ālāi","translation_bn":"অনুগ্রহকে","root":"الو","lemma":"ءَالَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":36351,"position":3,"text_uthmani":"رَبِّكُمَا","transliteration":"rabbikumā","translation_bn":"তোমাদের উভয়ের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36352,"position":4,"text_uthmani":"تُكَذِّبَانِ","transliteration":"tukadhibāni","translation_bn":"উভয়ে অস্বীকার করবে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36353,"position":5,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'fabi-ayyi ālāi rabbikumā tukadhibāni', 'অতএব (হে জ্বিন ও মানুষ!) তোমরা তোমাদের প্রতিপালকের কোন্ কোন্ নি‘মাতকে অস্বীকার করবে?', 'So which of the favors of your Lord would you deny?', 'অতএব (হে জ্বিন ও মানুষ!) তোমরা তোমাদের প্রতিপালকের কোন্ কোন্ নি‘মাতকে অস্বীকার করবে?', 'So which of the favors of your Lord would you deny?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055034.mp3', now()),
