  (55, 43, '', '[{"id":43641,"position":1,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"(বলা হবে) এই সেই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":43642,"position":2,"text_uthmani":"جَهَنَّمُ","transliteration":"jahannamu","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":43643,"position":3,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":43644,"position":4,"text_uthmani":"يُكَذِّبُ","transliteration":"yukadhibu","translation_bn":"মিথ্যা মনে করত","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43645,"position":5,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"যাকে","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":43646,"position":6,"text_uthmani":"ٱلْمُجْرِمُونَ","transliteration":"l-muj''rimūna","translation_bn":"অপরাধীরা","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":43647,"position":7,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'hādhihi jahannamu allatī yukadhibu bihā l-muj''rimūna', 'এটা সেই জাহান্নাম যাকে অপরাধীরা মিথ্যে মনে করেছিল।', 'This is Hell, which the criminals deny.', 'এটা সেই জাহান্নাম যাকে অপরাধীরা মিথ্যে মনে করেছিল।', 'This is Hell, which the criminals deny.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055043.mp3', now()),
  (55, 44, '', '[{"id":44390,"position":1,"text_uthmani":"يَطُوفُونَ","transliteration":"yaṭūfūna","translation_bn":"তারা ছুটোছুটি করবে","root":"طوف","lemma":"طَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44391,"position":2,"text_uthmani":"بَيْنَهَا","transliteration":"baynahā","translation_bn":"তার মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":44392,"position":3,"text_uthmani":"وَبَيْنَ","transliteration":"wabayna","translation_bn":"ও মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":44393,"position":4,"text_uthmani":"حَمِيمٍ","transliteration":"ḥamīmin","translation_bn":"গরম পানির","root":"حمم","lemma":"حَمِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":44394,"position":5,"text_uthmani":"ءَانٍۢ","transliteration":"ānin","translation_bn":"ফুটন্ত","root":"اني","lemma":"ءَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":44395,"position":6,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'yaṭūfūna baynahā wabayna ḥamīmin ānin', 'সেই জাহান্নাম আর ফুটন্ত পানিতে তারা ঘুরপাক খেতে থাকবে।', 'They will go around between it and scalding water, heated [to the utmost degree].', 'সেই জাহান্নাম আর ফুটন্ত পানিতে তারা ঘুরপাক খেতে থাকবে।', 'They will go around between it and scalding water, heated [to the utmost degree].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/055044.mp3', now()),
