  (56, 57, '', '[{"id":52801,"position":1,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":52802,"position":2,"text_uthmani":"خَلَقْنَـٰكُمْ","transliteration":"khalaqnākum","translation_bn":"তোমাদেরকে সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52803,"position":3,"text_uthmani":"فَلَوْلَا","transliteration":"falawlā","translation_bn":"কেন তবুও না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"শব্দ"},{"id":52804,"position":4,"text_uthmani":"تُصَدِّقُونَ","transliteration":"tuṣaddiqūna","translation_bn":"তোমার বিশ্বাস কর","root":"صدق","lemma":"صَدَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52805,"position":5,"text_uthmani":"٥٧","transliteration":"","translation_bn":"(৫৭)","root":"—","lemma":"٥٧","grammar_bn":"মার্কার"}]'::jsonb, 'naḥnu khalaqnākum falawlā tuṣaddiqūna', 'আমিই তো তোমাদেরকে সৃষ্টি করেছি, তাহলে তোমরা সত্যকে বিশ্বাস করবে না কেন?', 'We have created you, so why do you not believe?', 'আমিই তো তোমাদেরকে সৃষ্টি করেছি, তাহলে তোমরা সত্যকে বিশ্বাস করবে না কেন?', 'We have created you, so why do you not believe?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056057.mp3', now()),
  (56, 58, '', '[{"id":53393,"position":1,"text_uthmani":"أَفَرَءَيْتُم","transliteration":"afara-aytum","translation_bn":"তোমরা (ভেবে) দেখেছ কি তাহলে","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":53394,"position":2,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":53395,"position":3,"text_uthmani":"تُمْنُونَ","transliteration":"tum''nūna","translation_bn":"তোমরা বীর্যপাত কর","root":"مني","lemma":"يُمْنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53396,"position":4,"text_uthmani":"٥٨","transliteration":"","translation_bn":"(৫৮)","root":"—","lemma":"٥٨","grammar_bn":"মার্কার"}]'::jsonb, 'afara-aytum mā tum''nūna', 'তোমরা কি ভেবে দেখেছ- তোমরা যে বীর্য নিক্ষেপ কর,', 'Have you seen that which you emit?', 'তোমরা কি ভেবে দেখেছ- তোমরা যে বীর্য নিক্ষেপ কর,', 'Have you seen that which you emit?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056058.mp3', now()),
  (56, 59, '', '[{"id":53814,"position":1,"text_uthmani":"ءَأَنتُمْ","transliteration":"a-antum","translation_bn":"তোমরা কি","root":"—","lemma":"ءَأَنتُمْ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":53815,"position":2,"text_uthmani":"تَخْلُقُونَهُۥٓ","transliteration":"takhluqūnahu","translation_bn":"তা সৃষ্টি কর","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":53816,"position":3,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"না","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":53817,"position":4,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":53818,"position":5,"text_uthmani":"ٱلْخَـٰلِقُونَ","transliteration":"l-khāliqūna","translation_bn":"সৃষ্টিকারী","root":"خلق","lemma":"خَٰلِق","grammar_bn":"শব্দ"},{"id":53819,"position":6,"text_uthmani":"٥٩","transliteration":"","translation_bn":"(৫৯)","root":"—","lemma":"٥٩","grammar_bn":"মার্কার"}]'::jsonb, 'a-antum takhluqūnahu am naḥnu l-khāliqūna', 'তা কি তোমরা সৃষ্টি কর, না তার সৃষ্টিকর্তা আমিই।', 'Is it you who creates it, or are We the Creator?', 'তা কি তোমরা সৃষ্টি কর, না তার সৃষ্টিকর্তা আমিই।', 'Is it you who creates it, or are We the Creator?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056059.mp3', now()),
  (56, 60, '', '[{"id":54557,"position":1,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":54558,"position":2,"text_uthmani":"قَدَّرْنَا","transliteration":"qaddarnā","translation_bn":"নির্ধারণ করেছি","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":54559,"position":3,"text_uthmani":"بَيْنَكُمُ","transliteration":"baynakumu","translation_bn":"তোমাদের মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":54560,"position":4,"text_uthmani":"ٱلْمَوْتَ","transliteration":"l-mawta","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":54561,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":54562,"position":6,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":54563,"position":7,"text_uthmani":"بِمَسْبُوقِينَ","transliteration":"bimasbūqīna","translation_bn":"অক্ষম","root":"سبق","lemma":"مَسْبُوقِين","grammar_bn":"অব্যয় (Preposition)"},{"id":54564,"position":8,"text_uthmani":"٦٠","transliteration":"","translation_bn":"(৬০)","root":"—","lemma":"٦٠","grammar_bn":"মার্কার"}]'::jsonb, 'naḥnu qaddarnā baynakumu l-mawta wamā naḥnu bimasbūqīna', 'তোমাদের মধ্যে মৃত্যু আমিই নির্ধারণ করি, আর আমি কিছুমাত্র অক্ষম নই', 'We have decreed death among you, and We are not to be outdone', 'তোমাদের মধ্যে মৃত্যু আমিই নির্ধারণ করি, আর আমি কিছুমাত্র অক্ষম নই', 'We have decreed death among you, and We are not to be outdone', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056060.mp3', now()),
  (56, 61, '', '[{"id":55004,"position":1,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"এক্ষেত্রে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55005,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":55006,"position":3,"text_uthmani":"نُّبَدِّلَ","transliteration":"nubaddila","translation_bn":"পরিবর্তন করব আমরা","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55007,"position":4,"text_uthmani":"أَمْثَـٰلَكُمْ","transliteration":"amthālakum","translation_bn":"তোমাদের আকৃতি","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":55008,"position":5,"text_uthmani":"وَنُنشِئَكُمْ","transliteration":"wanunshi-akum","translation_bn":"এবং তোমাদের সৃষ্টি করব আমরা","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55009,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(এমন আকৃতির) মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":55010,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":55011,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":55012,"position":9,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জান","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55013,"position":10,"text_uthmani":"٦١","transliteration":"","translation_bn":"(৬১)","root":"—","lemma":"٦١","grammar_bn":"মার্কার"}]'::jsonb, 'ʿalā an nubaddila amthālakum wanunshi-akum fī mā lā taʿlamūna', 'তোমাদের আকার আকৃতি পরিবর্তন করতে আর তোমাদেরকে (নতুনভাবে) এমন এক আকৃতিতে সৃষ্টি করতে যা তোমরা জান না।', 'In that We will change your likenesses and produce you in that [form] which you do not know.', 'তোমাদের আকার আকৃতি পরিবর্তন করতে আর তোমাদেরকে (নতুনভাবে) এমন এক আকৃতিতে সৃষ্টি করতে যা তোমরা জান না।', 'In that We will change your likenesses and produce you in that [form] which you do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056061.mp3', now()),
  (56, 62, '', '[{"id":55553,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":55554,"position":2,"text_uthmani":"عَلِمْتُمُ","transliteration":"ʿalim''tumu","translation_bn":"তোমরা জেনেছ","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55555,"position":3,"text_uthmani":"ٱلنَّشْأَةَ","transliteration":"l-nashata","translation_bn":"সৃষ্টিকে","root":"نشا","lemma":"نَّشْأَة","grammar_bn":"শব্দ"},{"id":55556,"position":4,"text_uthmani":"ٱلْأُولَىٰ","transliteration":"l-ūlā","translation_bn":"প্রথমবার","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":55557,"position":5,"text_uthmani":"فَلَوْلَا","transliteration":"falawlā","translation_bn":"কেন তবে না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"শব্দ"},{"id":55558,"position":6,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"তোমরা শিক্ষা গ্রহণ কর","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":55559,"position":7,"text_uthmani":"٦٢","transliteration":"","translation_bn":"(৬২)","root":"—","lemma":"٦٢","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ʿalim''tumu l-nashata l-ūlā falawlā tadhakkarūna', 'তোমরা তোমাদের প্রথম সৃষ্টি সম্বন্ধে অবশ্যই জান তাহলে (আল্লাহ যে তোমাদেরকে পুনরায় সৃষ্টি করতে সক্ষম এ কথা) তোমরা অনুধাবন কর না কেন?', 'And you have already known the first creation, so will you not remember?', 'তোমরা তোমাদের প্রথম সৃষ্টি সম্বন্ধে অবশ্যই জান তাহলে (আল্লাহ যে তোমাদেরকে পুনরায় সৃষ্টি করতে সক্ষম এ কথা) তোমরা অনুধাবন কর না কেন?', 'And you have already known the first creation, so will you not remember?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056062.mp3', now()),
  (56, 63, '', '[{"id":56163,"position":1,"text_uthmani":"أَفَرَءَيْتُم","transliteration":"afara-aytum","translation_bn":"তোমরা তবে কি (ভেবে) দেখেছ","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":56164,"position":2,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":56165,"position":3,"text_uthmani":"تَحْرُثُونَ","transliteration":"taḥruthūna","translation_bn":"তোমরা বীজবপণ কর","root":"حرث","lemma":"تَحْرُثُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":56166,"position":4,"text_uthmani":"٦٣","transliteration":"","translation_bn":"(৬৩)","root":"—","lemma":"٦٣","grammar_bn":"মার্কার"}]'::jsonb, 'afara-aytum mā taḥruthūna', 'তোমরা কি ভেবে দেখেছ তোমরা যে বীজ বপন কর সে সম্পর্কে?', 'And have you seen that [seed] which you sow?', 'তোমরা কি ভেবে দেখেছ তোমরা যে বীজ বপন কর সে সম্পর্কে?', 'And have you seen that [seed] which you sow?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056063.mp3', now()),
