  (56, 87, '', '[{"id":66807,"position":1,"text_uthmani":"تَرْجِعُونَهَآ","transliteration":"tarjiʿūnahā","translation_bn":"তা তোমরা ফিরিয়ে আন","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66808,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":66809,"position":3,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":66810,"position":4,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"সত্যবাদী","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":66811,"position":5,"text_uthmani":"٨٧","transliteration":"","translation_bn":"(৮৭)","root":"—","lemma":"٨٧","grammar_bn":"মার্কার"}]'::jsonb, 'tarjiʿūnahā in kuntum ṣādiqīna', 'তাহলে তোমরা তাকে (অর্থাৎ তোমাদের প্রাণকে মৃত্যুর সময়) ফিরিয়ে নাও না কেন যদি তোমরা (তোমাদের দাবীতে) সত্যবাদী হয়েই থাক?', 'Bring it back, if you should be truthful?', 'তাহলে তোমরা তাকে (অর্থাৎ তোমাদের প্রাণকে মৃত্যুর সময়) ফিরিয়ে নাও না কেন যদি তোমরা (তোমাদের দাবীতে) সত্যবাদী হয়েই থাক?', 'Bring it back, if you should be truthful?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056087.mp3', now()),
  (56, 88, '', '[{"id":67400,"position":1,"text_uthmani":"فَأَمَّآ","transliteration":"fa-ammā","translation_bn":"আর","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":67401,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":67402,"position":3,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"সে হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67403,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":67404,"position":5,"text_uthmani":"ٱلْمُقَرَّبِينَ","transliteration":"l-muqarabīna","translation_bn":"নৈকট্য প্রাপ্তদের","root":"قرب","lemma":"مُقَرَّبُون","grammar_bn":"শব্দ"},{"id":67405,"position":6,"text_uthmani":"٨٨","transliteration":"","translation_bn":"(৮৮)","root":"—","lemma":"٨٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā in kāna mina l-muqarabīna', 'অতএব সে যদি (আল্লাহর) নৈকট্য প্রাপ্তদের একজন হয়', 'And if the deceased was of those brought near to Allah,', 'অতএব সে যদি (আল্লাহর) নৈকট্য প্রাপ্তদের একজন হয়', 'And if the deceased was of those brought near to Allah,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056088.mp3', now()),
  (56, 89, '', '[{"id":67613,"position":1,"text_uthmani":"فَرَوْحٌۭ","transliteration":"farawḥun","translation_bn":"(তার জন্যে) তবে আরাম","root":"روح","lemma":"رَّوْح","grammar_bn":"শব্দ"},{"id":67614,"position":2,"text_uthmani":"وَرَيْحَانٌۭ","transliteration":"warayḥānun","translation_bn":"ও উত্তম জীবনোপকরণ","root":"روح","lemma":"رَّيْحَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":67615,"position":3,"text_uthmani":"وَجَنَّتُ","transliteration":"wajannatu","translation_bn":"এবং জন্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":67616,"position":4,"text_uthmani":"نَعِيمٍۢ","transliteration":"naʿīmin","translation_bn":"সুখকর","root":"نعم","lemma":"نَعِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":67617,"position":5,"text_uthmani":"٨٩","transliteration":"","translation_bn":"(৮৯)","root":"—","lemma":"٨٩","grammar_bn":"মার্কার"}]'::jsonb, 'farawḥun warayḥānun wajannatu naʿīmin', 'তাহলে (তার জন্য আছে) আরাম-শান্তি, উত্তম রিযক আর নি‘মাতে-ভরা জান্নাত।', 'Then [for him is] rest and bounty and a garden of pleasure.', 'তাহলে (তার জন্য আছে) আরাম-শান্তি, উত্তম রিযক আর নি‘মাতে-ভরা জান্নাত।', 'Then [for him is] rest and bounty and a garden of pleasure.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056089.mp3', now()),
