  (56, 95, '', '[{"id":69740,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":69741,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":69742,"position":3,"text_uthmani":"لَهُوَ","transliteration":"lahuwa","translation_bn":"তা অবশ্যই","root":"—","lemma":"لَهُوَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":69743,"position":4,"text_uthmani":"حَقُّ","transliteration":"ḥaqqu","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":69744,"position":5,"text_uthmani":"ٱلْيَقِينِ","transliteration":"l-yaqīni","translation_bn":"ধ্রুব","root":"يقن","lemma":"يَقِين","grammar_bn":"শব্দ"},{"id":69745,"position":6,"text_uthmani":"٩٥","transliteration":"","translation_bn":"(৯৫)","root":"—","lemma":"٩٥","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā lahuwa ḥaqqu l-yaqīni', 'এটা সুনিশ্চিত সত্য।', 'Indeed, this is the true certainty,', 'এটা সুনিশ্চিত সত্য।', 'Indeed, this is the true certainty,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056095.mp3', now()),
  (56, 96, '', '[{"id":70238,"position":1,"text_uthmani":"فَسَبِّحْ","transliteration":"fasabbiḥ","translation_bn":"সুতরাং পবিত্রতা ঘোষণা করো","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"শব্দ"},{"id":70239,"position":2,"text_uthmani":"بِٱسْمِ","transliteration":"bi-is''mi","translation_bn":"নামের","root":"سمو","lemma":"ٱسْم","grammar_bn":"অব্যয় (Preposition)"},{"id":70240,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":70241,"position":4,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"(যিনি) মহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":70242,"position":5,"text_uthmani":"٩٦","transliteration":"","translation_bn":"(৯৬)","root":"—","lemma":"٩٦","grammar_bn":"মার্কার"}]'::jsonb, 'fasabbiḥ bi-is''mi rabbika l-ʿaẓīmi', 'কাজেই তুমি তোমার মহান প্রতিপালকের গৌরব ও মহিমা ঘোষণা কর।', 'So exalt the name of your Lord, the Most Great.', 'কাজেই তুমি তোমার মহান প্রতিপালকের গৌরব ও মহিমা ঘোষণা কর।', 'So exalt the name of your Lord, the Most Great.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/056096.mp3', now())
