  (58, 1, '', '[{"id":358,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":359,"position":2,"text_uthmani":"سَمِعَ","transliteration":"samiʿa","translation_bn":"শুনেছেন","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":360,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":361,"position":4,"text_uthmani":"قَوْلَ","transliteration":"qawla","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":362,"position":5,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"(সেই নারীর) যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":363,"position":6,"text_uthmani":"تُجَـٰدِلُكَ","transliteration":"tujādiluka","translation_bn":"তোমার সাথে তর্কবিতর্ক করছে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":364,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":365,"position":8,"text_uthmani":"زَوْجِهَا","transliteration":"zawjihā","translation_bn":"তার স্বামীর","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":366,"position":9,"text_uthmani":"وَتَشْتَكِىٓ","transliteration":"watashtakī","translation_bn":"এবং অভিযোগ করছে","root":"شكو","lemma":"تَشْتَكِى^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":367,"position":10,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":368,"position":11,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":369,"position":12,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":370,"position":13,"text_uthmani":"يَسْمَعُ","transliteration":"yasmaʿu","translation_bn":"শুনছেন","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":371,"position":14,"text_uthmani":"تَحَاوُرَكُمَآ ۚ","transliteration":"taḥāwurakumā","translation_bn":"তোমাদের দুজনের কথাবার্তা","root":"حور","lemma":"تَحَاوُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":373,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":374,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":375,"position":17,"text_uthmani":"سَمِيعٌۢ","transliteration":"samīʿun","translation_bn":"সবকিছু শোনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"বিশেষণ (Adjective)"},{"id":376,"position":18,"text_uthmani":"بَصِيرٌ","transliteration":"baṣīrun","translation_bn":"সবকিছু দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":377,"position":19,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'qad samiʿa l-lahu qawla allatī tujādiluka fī zawjihā watashtakī ilā l-lahi wal-lahu yasmaʿu taḥāwurakumā inna l-laha samīʿun baṣīrun', 'আল্লাহ তার কথা শুনেছেন যে নারী (খাওলাহ বিনত সা‘লাবাহ) তার স্বামীর বিষয়ে তোমার সাথে বাদানুবাদ করছে আর আল্লাহর কাছে ফরিয়াদ জানাচ্ছে, আল্লাহ তোমাদের দু’জনের কথা শুনছেন, আল্লাহ সর্বশ্রোতা, সর্বদ্রষ্টা।', 'Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing.', 'আল্লাহ তার কথা শুনেছেন যে নারী (খাওলাহ বিনত সা‘লাবাহ) তার স্বামীর বিষয়ে তোমার সাথে বাদানুবাদ করছে আর আল্লাহর কাছে ফরিয়াদ জানাচ্ছে, আল্লাহ তোমাদের দু’জনের কথা শুনছেন, আল্লাহ সর্বশ্রোতা, সর্বদ্রষ্টা।', 'Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058001.mp3', now()),
  (58, 2, '', '[{"id":1632,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1633,"position":2,"text_uthmani":"يُظَـٰهِرُونَ","transliteration":"yuẓāhirūna","translation_bn":"যিহার করে","root":"ظهر","lemma":"ظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1634,"position":3,"text_uthmani":"مِنكُم","transliteration":"minkum","translation_bn":"তোমাদের মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1635,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"সাথে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1636,"position":5,"text_uthmani":"نِّسَآئِهِم","transliteration":"nisāihim","translation_bn":"তাদের স্ত্রীদের","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":1637,"position":6,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1638,"position":7,"text_uthmani":"هُنَّ","transliteration":"hunna","translation_bn":"তারা","root":"—","lemma":"هُنَّ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1639,"position":8,"text_uthmani":"أُمَّهَـٰتِهِمْ ۖ","transliteration":"ummahātihim","translation_bn":"তাদের মা (হয়ে যায়)","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1641,"position":9,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয় (অন্যরা)","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":1642,"position":10,"text_uthmani":"أُمَّهَـٰتُهُمْ","transliteration":"ummahātuhum","translation_bn":"তাদের মা","root":"امم","lemma":"أُمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1643,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":1644,"position":12,"text_uthmani":"ٱلَّـٰٓـِٔى","transliteration":"allāī","translation_bn":"যারা","root":"—","lemma":"ٱلَّٰ^ـ#ِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1645,"position":13,"text_uthmani":"وَلَدْنَهُمْ ۚ","transliteration":"waladnahum","translation_bn":"তাদের জন্ম দিয়েছে","root":"ولد","lemma":"وَلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1647,"position":14,"text_uthmani":"وَإِنَّهُمْ","transliteration":"wa-innahum","translation_bn":"এবং তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1648,"position":15,"text_uthmani":"لَيَقُولُونَ","transliteration":"layaqūlūna","translation_bn":"বলে অবশ্যই","root":"قول","lemma":"قَالَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":1649,"position":16,"text_uthmani":"مُنكَرًۭا","transliteration":"munkaran","translation_bn":"অসঙ্গত","root":"نكر","lemma":"مُنكَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1650,"position":17,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1651,"position":18,"text_uthmani":"ٱلْقَوْلِ","transliteration":"l-qawli","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"শব্দ"},{"id":1652,"position":19,"text_uthmani":"وَزُورًۭا ۚ","transliteration":"wazūran","translation_bn":"ও মিথ্যা","root":"زور","lemma":"زُّور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1654,"position":20,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1655,"position":21,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1656,"position":22,"text_uthmani":"لَعَفُوٌّ","transliteration":"laʿafuwwun","translation_bn":"অবশ্যই মার্জনাকারী","root":"عفو","lemma":"عَفُوّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":1657,"position":23,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":1658,"position":24,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yuẓāhirūna minkum min nisāihim mā hunna ummahātihim in ummahātuhum illā allāī waladnahum wa-innahum layaqūlūna munkaran mina l-qawli wazūran wa-inna l-laha laʿafuwwun ghafūrun', 'তোমাদের মধ্যে যারা তাদের স্ত্রীদের সাথে জিহার করে (অর্থাৎ স্ত্রীকে বলে যে, তুমি আমার জন্য আমার মায়ের পিঠের মত) তাদের স্ত্রীরা তাদের মা নয়। তাদের মা তো কেবল তারাই যারা তাদের জন্ম দিয়েছে। তারা অবশ্যই ঘৃণ্য ও মিথ্যে কথা বলে, নিশ্চয়ই আল্লাহ পাপ মোচনকারী, বড়ই ক্ষমাশীল।', 'Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving.', 'তোমাদের মধ্যে যারা তাদের স্ত্রীদের সাথে জিহার করে (অর্থাৎ স্ত্রীকে বলে যে, তুমি আমার জন্য আমার মায়ের পিঠের মত) তাদের স্ত্রীরা তাদের মা নয়। তাদের মা তো কেবল তারাই যারা তাদের জন্ম দিয়েছে। তারা অবশ্যই ঘৃণ্য ও মিথ্যে কথা বলে, নিশ্চয়ই আল্লাহ পাপ মোচনকারী, বড়ই ক্ষমাশীল।', 'Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058002.mp3', now()),
  (58, 3, '', '[{"id":2337,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং তারা যখন","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2338,"position":2,"text_uthmani":"يُظَـٰهِرُونَ","transliteration":"yuẓāhirūna","translation_bn":"যিহার করে","root":"ظهر","lemma":"ظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2339,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"সাথে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2340,"position":4,"text_uthmani":"نِّسَآئِهِمْ","transliteration":"nisāihim","translation_bn":"তাদের স্ত্রীদের","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":2341,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2342,"position":6,"text_uthmani":"يَعُودُونَ","transliteration":"yaʿūdūna","translation_bn":"ফিরে যায়","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2343,"position":7,"text_uthmani":"لِمَا","transliteration":"limā","translation_bn":"(তা হতে) যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2344,"position":8,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2345,"position":9,"text_uthmani":"فَتَحْرِيرُ","transliteration":"fataḥrīru","translation_bn":"মুক্ত করতে হবে","root":"حرر","lemma":"تَحْرِير","grammar_bn":"শব্দ"},{"id":2346,"position":10,"text_uthmani":"رَقَبَةٍۢ","transliteration":"raqabatin","translation_bn":"একজন দাস","root":"رقب","lemma":"رَقَبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2347,"position":11,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2348,"position":12,"text_uthmani":"قَبْلِ","transliteration":"qabli","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2349,"position":13,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2350,"position":14,"text_uthmani":"يَتَمَآسَّا ۚ","transliteration":"yatamāssā","translation_bn":"পরস্পরকে স্পর্শ করার","root":"مسس","lemma":"يَتَمَا^سَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2352,"position":15,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এসব","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2353,"position":16,"text_uthmani":"تُوعَظُونَ","transliteration":"tūʿaẓūna","translation_bn":"তোমাদের উপদেশ দেয়া হচ্ছে","root":"وعظ","lemma":"وَعَظْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2354,"position":17,"text_uthmani":"بِهِۦ ۚ","transliteration":"bihi","translation_bn":"এদ্বারা","root":"—","lemma":"بِهِۦ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":2356,"position":18,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2357,"position":19,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2358,"position":20,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ কর","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2359,"position":21,"text_uthmani":"خَبِيرٌۭ","transliteration":"khabīrun","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":2360,"position":22,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna yuẓāhirūna min nisāihim thumma yaʿūdūna limā qālū fataḥrīru raqabatin min qabli an yatamāssā dhālikum tūʿaẓūna bihi wal-lahu bimā taʿmalūna khabīrun', 'যারা নিজেদের স্ত্রীদের সাথে জিহার করে, অতঃপর তারা যে কথা বলেছে তা প্রত্যাহার করে নেয় তবে পরস্পরকে স্পর্শ করার পূর্বে তাদেরকে একটি দাস মুক্ত করতে হবে, এর দ্বারা তোমাদেরকে উপদেশ দেয়া হচ্ছে। তোমরা যা কর, আল্লাহ তার খবর রাখেন।', 'And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do.', 'যারা নিজেদের স্ত্রীদের সাথে জিহার করে, অতঃপর তারা যে কথা বলেছে তা প্রত্যাহার করে নেয় তবে পরস্পরকে স্পর্শ করার পূর্বে তাদেরকে একটি দাস মুক্ত করতে হবে, এর দ্বারা তোমাদেরকে উপদেশ দেয়া হচ্ছে। তোমরা যা কর, আল্লাহ তার খবর রাখেন।', 'And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058003.mp3', now()),
  (58, 4, '', '[{"id":3692,"position":1,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"যে অতঃপর","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":3693,"position":2,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":3694,"position":3,"text_uthmani":"يَجِدْ","transliteration":"yajid","translation_bn":"পায় (কোন দাস)","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3695,"position":4,"text_uthmani":"فَصِيَامُ","transliteration":"faṣiyāmu","translation_bn":"তবে রোজা রাখবে","root":"صوم","lemma":"صِيَام","grammar_bn":"শব্দ"},{"id":3696,"position":5,"text_uthmani":"شَهْرَيْنِ","transliteration":"shahrayni","translation_bn":"দু''মাস","root":"شهر","lemma":"شَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":3697,"position":6,"text_uthmani":"مُتَتَابِعَيْنِ","transliteration":"mutatābiʿayni","translation_bn":"একটানা","root":"تبع","lemma":"مُتَتَابِعَيْن","grammar_bn":"বিশেষণ (Adjective)"},{"id":3698,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3699,"position":8,"text_uthmani":"قَبْلِ","transliteration":"qabli","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3700,"position":9,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":3701,"position":10,"text_uthmani":"يَتَمَآسَّا ۖ","transliteration":"yatamāssā","translation_bn":"পরস্পরে স্পর্শ করার","root":"مسس","lemma":"يَتَمَا^سَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3703,"position":11,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"যে অতঃপর","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":3704,"position":12,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":3705,"position":13,"text_uthmani":"يَسْتَطِعْ","transliteration":"yastaṭiʿ","translation_bn":"সমর্থ হবে","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3706,"position":14,"text_uthmani":"فَإِطْعَامُ","transliteration":"fa-iṭ''ʿāmu","translation_bn":"তবে খানা খাওয়াবে","root":"طعم","lemma":"إِطْعَٰم","grammar_bn":"শব্দ"},{"id":3707,"position":15,"text_uthmani":"سِتِّينَ","transliteration":"sittīna","translation_bn":"ষাটজন","root":"ستت","lemma":"سِتِّين","grammar_bn":"বিশেষ্য (Noun)"},{"id":3708,"position":16,"text_uthmani":"مِسْكِينًۭا ۚ","transliteration":"mis''kīnan","translation_bn":"নিঃস্বকে","root":"سكن","lemma":"مِسْكِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":3710,"position":17,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা (এজন্যে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3711,"position":18,"text_uthmani":"لِتُؤْمِنُوا۟","transliteration":"litu''minū","translation_bn":"যেন তোমরা ঈমান আন","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":3712,"position":19,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহ্‌র উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":3713,"position":20,"text_uthmani":"وَرَسُولِهِۦ ۚ","transliteration":"warasūlihi","translation_bn":"এবং তাঁর রাসূলের (উপর)","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3715,"position":21,"text_uthmani":"وَتِلْكَ","transliteration":"watil''ka","translation_bn":"এবং এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3716,"position":22,"text_uthmani":"حُدُودُ","transliteration":"ḥudūdu","translation_bn":"নির্ধারিত সীমাসমূহ","root":"حدد","lemma":"حُدُود","grammar_bn":"বিশেষ্য (Noun)"},{"id":3717,"position":23,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3719,"position":24,"text_uthmani":"وَلِلْكَـٰفِرِينَ","transliteration":"walil''kāfirīna","translation_bn":"এবং কাফিরদের জন্য (রয়েছে)","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3720,"position":25,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3721,"position":26,"text_uthmani":"أَلِيمٌ","transliteration":"alīmun","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":3722,"position":27,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'faman lam yajid faṣiyāmu shahrayni mutatābiʿayni min qabli an yatamāssā faman lam yastaṭiʿ fa-iṭ''ʿāmu sittīna mis''kīnan dhālika litu''minū bil-lahi warasūlihi watil''ka ḥudūdu l-lahi walil''kāfirīna ʿadhābun alīmun', 'কিন্তু যার (দাস সংগ্রহ করার) সামর্থ্য নেই, সে এক নাগাড়ে দু’মাস রোযা রাখবে পরস্পরকে স্পর্শ করার পূর্বে। আর যে তা করতে পারবে না, সে ষাট জন মিসকীনকে খাবার খাওয়াবে। এ নির্দেশ দেয়া হচ্ছে এ জন্য যাতে তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আনো। এগুলো আল্লাহর নির্ধারিত সীমা। (যারা এটা অস্বীকার করবে সেই) কাফিরদের জন্য আছে মর্মান্তিক শাস্তি।', 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment.', 'কিন্তু যার (দাস সংগ্রহ করার) সামর্থ্য নেই, সে এক নাগাড়ে দু’মাস রোযা রাখবে পরস্পরকে স্পর্শ করার পূর্বে। আর যে তা করতে পারবে না, সে ষাট জন মিসকীনকে খাবার খাওয়াবে। এ নির্দেশ দেয়া হচ্ছে এ জন্য যাতে তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আনো। এগুলো আল্লাহর নির্ধারিত সীমা। (যারা এটা অস্বীকার করবে সেই) কাফিরদের জন্য আছে মর্মান্তিক শাস্তি।', 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058004.mp3', now()),
  (58, 5, '', '[{"id":5004,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5005,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5006,"position":3,"text_uthmani":"يُحَآدُّونَ","transliteration":"yuḥāddūna","translation_bn":"বিরোধিতা করে","root":"حدد","lemma":"يُحَا^دُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5007,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5008,"position":5,"text_uthmani":"وَرَسُولَهُۥ","transliteration":"warasūlahu","translation_bn":"তাঁর রাসুলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5009,"position":6,"text_uthmani":"كُبِتُوا۟","transliteration":"kubitū","translation_bn":"তাদের লাঞ্ছিত করা হবে","root":"كبت","lemma":"كُبِتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5010,"position":7,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5011,"position":8,"text_uthmani":"كُبِتَ","transliteration":"kubita","translation_bn":"লাঞ্ছিত করা হয়েছিল","root":"كبت","lemma":"كُبِتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5012,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5013,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5014,"position":11,"text_uthmani":"قَبْلِهِمْ ۚ","transliteration":"qablihim","translation_bn":"তাদের পূর্বে (ছিল)","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5016,"position":12,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5017,"position":13,"text_uthmani":"أَنزَلْنَآ","transliteration":"anzalnā","translation_bn":"আমরা অবতীর্ণ করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5018,"position":14,"text_uthmani":"ءَايَـٰتٍۭ","transliteration":"āyātin","translation_bn":"আয়াতসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":5019,"position":15,"text_uthmani":"بَيِّنَـٰتٍۢ ۚ","transliteration":"bayyinātin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"بَيِّنَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":5021,"position":16,"text_uthmani":"وَلِلْكَـٰفِرِينَ","transliteration":"walil''kāfirīna","translation_bn":"এবং কাফিরদের জন্যে রয়েছে","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5022,"position":17,"text_uthmani":"عَذَابٌۭ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5023,"position":18,"text_uthmani":"مُّهِينٌۭ","transliteration":"muhīnun","translation_bn":"অপমানকর","root":"هون","lemma":"مُّهِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":5024,"position":19,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna yuḥāddūna l-laha warasūlahu kubitū kamā kubita alladhīna min qablihim waqad anzalnā āyātin bayyinātin walil''kāfirīna ʿadhābun muhīnun', 'যারা আল্লাহ ও তাঁর রসূলের বিরোধিতা করে তাদেরকে লাঞ্ছিত করা হবে যেমন লাঞ্ছিত করা হয়েছিল তাদের পূর্ববর্তীদেরকে। আমি সুস্পষ্ট আয়াত অবতীর্ণ করেছি আর (অস্বীকারকারী) কাফিরদের জন্য আছে অপমানজনক শাস্তি,', 'Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment.', 'যারা আল্লাহ ও তাঁর রসূলের বিরোধিতা করে তাদেরকে লাঞ্ছিত করা হবে যেমন লাঞ্ছিত করা হয়েছিল তাদের পূর্ববর্তীদেরকে। আমি সুস্পষ্ট আয়াত অবতীর্ণ করেছি আর (অস্বীকারকারী) কাফিরদের জন্য আছে অপমানজনক শাস্তি,', 'Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058005.mp3', now()),
  (58, 6, '', '[{"id":6229,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6230,"position":2,"text_uthmani":"يَبْعَثُهُمُ","transliteration":"yabʿathuhumu","translation_bn":"তাদের উত্থিত করবেন","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6231,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6232,"position":4,"text_uthmani":"جَمِيعًۭا","transliteration":"jamīʿan","translation_bn":"সকলকেই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":6233,"position":5,"text_uthmani":"فَيُنَبِّئُهُم","transliteration":"fayunabbi-uhum","translation_bn":"অতঃপর তাদের জানিয়ে দিবেন","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6234,"position":6,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6235,"position":7,"text_uthmani":"عَمِلُوٓا۟ ۚ","transliteration":"ʿamilū","translation_bn":"তারা কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6237,"position":8,"text_uthmani":"أَحْصَىٰهُ","transliteration":"aḥṣāhu","translation_bn":"তা গুণে রেখেছেন","root":"حصي","lemma":"أَحْصَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6238,"position":9,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6239,"position":10,"text_uthmani":"وَنَسُوهُ ۚ","transliteration":"wanasūhu","translation_bn":"অথচ তা তারা ভুলে গেছে","root":"نسي","lemma":"نَسِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":6241,"position":11,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6242,"position":12,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6243,"position":13,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6244,"position":14,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুরই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":6245,"position":15,"text_uthmani":"شَهِيدٌ","transliteration":"shahīdun","translation_bn":"সাক্ষী","root":"شهد","lemma":"شَهِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":6246,"position":16,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yawma yabʿathuhumu l-lahu jamīʿan fayunabbi-uhum bimā ʿamilū aḥṣāhu l-lahu wanasūhu wal-lahu ʿalā kulli shayin shahīdun', 'সেদিন, যেদিন আল্লাহ তাদের সকলকে আবার জীবিত করে উঠাবেন এবং তাদের কৃতকর্মের সংবাদ তাদেরকে জানিয়ে দিবেন, আল্লাহ তা হিসেব করে রেখেছেন যদিও তারা (নিজেরা) ভুলে গেছে। আল্লাহ প্রতিটি বিষয়ের প্রত্যক্ষদর্শী।', 'On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness.', 'সেদিন, যেদিন আল্লাহ তাদের সকলকে আবার জীবিত করে উঠাবেন এবং তাদের কৃতকর্মের সংবাদ তাদেরকে জানিয়ে দিবেন, আল্লাহ তা হিসেব করে রেখেছেন যদিও তারা (নিজেরা) ভুলে গেছে। আল্লাহ প্রতিটি বিষয়ের প্রত্যক্ষদর্শী।', 'On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/058006.mp3', now()),
