  (59, 1, '', '[{"id":378,"position":1,"text_uthmani":"سَبَّحَ","transliteration":"sabbaḥa","translation_bn":"তাসবিহ করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":379,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহর জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":380,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":381,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":382,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":383,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":384,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":385,"position":8,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":387,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":388,"position":10,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":389,"position":11,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"মহাবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":390,"position":12,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sabbaḥa lillahi mā fī l-samāwāti wamā fī l-arḍi wahuwa l-ʿazīzu l-ḥakīmu', 'আসমান ও যমীনে যা কিছু আছে সবই আল্লাহর গৌরব ও মহিমা ঘোষণা করে। আর তিনি (আল্লাহ) পরাক্রমশালী প্রজ্ঞাময়।', 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', 'আসমান ও যমীনে যা কিছু আছে সবই আল্লাহর গৌরব ও মহিমা ঘোষণা করে। আর তিনি (আল্লাহ) পরাক্রমশালী প্রজ্ঞাময়।', 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/059001.mp3', now()),
  (59, 2, '', '[{"id":1271,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1272,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1273,"position":3,"text_uthmani":"أَخْرَجَ","transliteration":"akhraja","translation_bn":"বের করেছেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1274,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1275,"position":5,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"কুফুরি করেছিল","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1276,"position":6,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1277,"position":7,"text_uthmani":"أَهْلِ","transliteration":"ahli","translation_bn":"আহলে","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1278,"position":8,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবদের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1279,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1280,"position":10,"text_uthmani":"دِيَـٰرِهِمْ","transliteration":"diyārihim","translation_bn":"ঘরবাড়ি গুলো তাদের","root":"دور","lemma":"دَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":1281,"position":11,"text_uthmani":"لِأَوَّلِ","transliteration":"li-awwali","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"অব্যয় (Preposition)"},{"id":1282,"position":12,"text_uthmani":"ٱلْحَشْرِ ۚ","transliteration":"l-ḥashri","translation_bn":"সমাবেশেই","root":"حشر","lemma":"حَشْر","gram