  (61, 1, '', '[{"id":443,"position":1,"text_uthmani":"سَبَّحَ","transliteration":"sabbaḥa","translation_bn":"তসবীহ করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":444,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":445,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":446,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":447,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আসমানসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":448,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":449,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":450,"position":8,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":452,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":453,"position":10,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":454,"position":11,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":455,"position":12,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sabbaḥa lillahi mā fī l-samāwāti wamā fī l-arḍi wahuwa l-ʿazīzu l-ḥakīmu', 'আসমানে যা কিছু আছে আর যমীনে যা কিছু আছে (সবই) আল্লাহর প্রশংসা ও মহিমা ঘোষণা করে; তিনি মহাপরাক্রান্ত মহাবিজ্ঞানী।', 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', 'আসমানে যা কিছু আছে আর যমীনে যা কিছু আছে (সবই) আল্লাহর প্রশংসা ও মহিমা ঘোষণা করে; তিনি মহাপরাক্রান্ত মহাবিজ্ঞানী।', 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061001.mp3', now()),
  (61, 2, '', '[{"id":1352,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":1353,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1354,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1355,"position":4,"text_uthmani":"لِمَ","transliteration":"lima","translation_bn":"কেন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1356,"position":5,"text_uthmani":"تَقُولُونَ","transliteration":"taqūlūna","translation_bn":"তোমরা বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1357,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1358,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":1359,"position":8,"text_uthmani":"تَفْعَلُونَ","transliteration":"tafʿalūna","translation_bn":"তোমরা করো","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1360,"position":9,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū lima taqūlūna mā lā tafʿalūna', 'হে মু’মিনগণ! তোমরা এমন কথা কেন বল যা তোমরা কর না।', 'O you who have believed, why do you say what you do not do?', 'হে মু’মিনগণ! তোমরা এমন কথা কেন বল যা তোমরা কর না।', 'O you who have believed, why do you say what you do not do?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061002.mp3', now()),
  (61, 3, '', '[{"id":2398,"position":1,"text_uthmani":"كَبُرَ","transliteration":"kabura","translation_bn":"অতিশয়","root":"كبر","lemma":"كَبُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2399,"position":2,"text_uthmani":"مَقْتًا","transliteration":"maqtan","translation_bn":"ক্রোধজনক","root":"مقت","lemma":"مَقْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":2400,"position":3,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":2401,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2402,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2403,"position":6,"text_uthmani":"تَقُولُوا۟","transliteration":"taqūlū","translation_bn":"তোমরা বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2404,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2405,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2406,"position":9,"text_uthmani":"تَفْعَلُونَ","transliteration":"tafʿalūna","translation_bn":"তোমরা করো","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2407,"position":10,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'kabura maqtan ʿinda l-lahi an taqūlū mā lā tafʿalūna', 'আল্লাহর দৃষ্টিতে এটা অত্যন্ত নিন্দনীয় ব্যাপার যে, তোমরা বলবে এমন কথা যা তোমরা কর না।', 'Great is hatred in the sight of Allah that you say what you do not do.', 'আল্লাহর দৃষ্টিতে এটা অত্যন্ত নিন্দনীয় ব্যাপার যে, তোমরা বলবে এমন কথা যা তোমরা কর না।', 'Great is hatred in the sight of Allah that you say what you do not do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061003.mp3', now()),
  (61, 4, '', '[{"id":3793,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3794,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3795,"position":3,"text_uthmani":"يُحِبُّ","transliteration":"yuḥibbu","translation_bn":"পছন্দ করেন","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3796,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3797,"position":5,"text_uthmani":"يُقَـٰتِلُونَ","transliteration":"yuqātilūna","translation_bn":"লড়াই করে","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3798,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(পথে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3799,"position":7,"text_uthmani":"سَبِيلِهِۦ","transliteration":"sabīlihi","translation_bn":"তাঁর পথে","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3800,"position":8,"text_uthmani":"صَفًّۭا","transliteration":"ṣaffan","translation_bn":"সারিবদ্ধ হয়ে","root":"صفف","lemma":"صَفّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3801,"position":9,"text_uthmani":"كَأَنَّهُم","transliteration":"ka-annahum","translation_bn":"তারা যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3802,"position":10,"text_uthmani":"بُنْيَـٰنٌۭ","transliteration":"bun''yānun","translation_bn":"প্রাচীর","root":"بني","lemma":"بُنْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":3803,"position":11,"text_uthmani":"مَّرْصُوصٌۭ","transliteration":"marṣūṣun","translation_bn":"সুদৃঢ়","root":"رصص","lemma":"مَّرْصُوص","grammar_bn":"বিশেষণ (Adjective)"},{"id":3804,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-laha yuḥibbu alladhīna yuqātilūna fī sabīlihi ṣaffan ka-annahum bun''yānun marṣūṣun', 'আল্লাহ তাদেরকে ভালবাসেন যারা তাঁর পথে সারিবদ্ধ হয়ে যুদ্ধ করে- যেন তারা সীসা-গলানো প্রাচীর।', 'Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly.', 'আল্লাহ তাদেরকে ভালবাসেন যারা তাঁর পথে সারিবদ্ধ হয়ে যুদ্ধ করে- যেন তারা সীসা-গলানো প্রাচীর।', 'Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061004.mp3', now()),
  (61, 5, '', '[{"id":5040,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":5041,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5042,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5043,"position":4,"text_uthmani":"لِقَوْمِهِۦ","transliteration":"liqawmihi","translation_bn":"তার জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":5044,"position":5,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"হে আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":5045,"position":6,"text_uthmani":"لِمَ","transliteration":"lima","translation_bn":"কেন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5046,"position":7,"text_uthmani":"تُؤْذُونَنِى","transliteration":"tu''dhūnanī","translation_bn":"তোমরা আমাকে কষ্ট দাও","root":"اذي","lemma":"أُوذِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5047,"position":8,"text_uthmani":"وَقَد","transliteration":"waqad","translation_bn":"অথচ নিশ্চয়","root":"—","lemma":"قَد\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":5048,"position":9,"text_uthmani":"تَّعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5049,"position":10,"text_uthmani":"أَنِّى","transliteration":"annī","translation_bn":"যে আমি","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5050,"position":11,"text_uthmani":"رَسُولُ","transliteration":"rasūlu","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":5051,"position":12,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5052,"position":13,"text_uthmani":"إِلَيْكُمْ ۖ","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি\"","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5054,"position":14,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":5055,"position":15,"text_uthmani":"زَاغُوٓا۟","transliteration":"zāghū","translation_bn":"তারা বক্রতা অবলম্বন করল","root":"زيغ","lemma":"زَاغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5056,"position":16,"text_uthmani":"أَزَاغَ","transliteration":"azāgha","translation_bn":"বক্র করে দিলেন","root":"زيغ","lemma":"أَزَاغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5057,"position":17,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5058,"position":18,"text_uthmani":"قُلُوبَهُمْ ۚ","transliteration":"qulūbahum","translation_bn":"তাদের অন্তরসমূহকে","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5060,"position":19,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":5061,"position":20,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":5062,"position":21,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":5063,"position":22,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":5064,"position":23,"text_uthmani":"ٱلْفَـٰسِقِينَ","transliteration":"l-fāsiqīna","translation_bn":"ফাসেক","root":"فسق","lemma":"فَاسِق","grammar_bn":"শব্দ"},{"id":5065,"position":24,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qāla mūsā liqawmihi yāqawmi lima tu''dhūnanī waqad taʿlamūna annī rasūlu l-lahi ilaykum falammā zāghū azāgha l-lahu qulūbahum wal-lahu lā yahdī l-qawma l-fāsiqīna', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, ‘হে আমার সম্প্রদায়! তোমরা আমাকে কেন কষ্ট দিচ্ছ, তোমরা তো জানই যে, আমি তোমাদের নিকট আল্লাহর রসূল!’ অতঃপর তারা যখন বাঁকা পথ ধরল, আল্লাহ তাদের হৃদয়কে বাঁকা করে দিলেন। আল্লাহ পাপাচারীদেরকে সঠিক পথে পরিচালিত করেন না।', 'And [mention, O Muhammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people.', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, ‘হে আমার সম্প্রদায়! তোমরা আমাকে কেন কষ্ট দিচ্ছ, তোমরা তো জানই যে, আমি তোমাদের নিকট আল্লাহর রসূল!’ অতঃপর তারা যখন বাঁকা পথ ধরল, আল্লাহ তাদের হৃদয়কে বাঁকা করে দিলেন। আল্লাহ পাপাচারীদেরকে সঠিক পথে পরিচালিত করেন না।', 'And [mention, O Muhammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061005.mp3', now()),
  (61, 6, '', '[{"id":6295,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":6296,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6297,"position":3,"text_uthmani":"عِيسَى","transliteration":"ʿīsā","translation_bn":"ঈসা","root":"—","lemma":"عِيسَى","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6298,"position":4,"text_uthmani":"ٱبْنُ","transliteration":"ub''nu","translation_bn":"পুত্র","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6299,"position":5,"text_uthmani":"مَرْيَمَ","transliteration":"maryama","translation_bn":"মারয়ামের","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6300,"position":6,"text_uthmani":"يَـٰبَنِىٓ","transliteration":"yābanī","translation_bn":"\"হে বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":6301,"position":7,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"\"ইসরাইল","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6302,"position":8,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6303,"position":9,"text_uthmani":"رَسُولُ","transliteration":"rasūlu","translation_bn":"রাসূূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":6304,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6305,"position":11,"text_uthmani":"إِلَيْكُم","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6306,"position":12,"text_uthmani":"مُّصَدِّقًۭا","transliteration":"muṣaddiqan","translation_bn":"সত্যায়নকারী","root":"صدق","lemma":"مُصَدِّق","grammar_bn":"বিশেষ্য (Noun)"},{"id":6307,"position":13,"text_uthmani":"لِّمَا","transliteration":"limā","translation_bn":"যা জন্যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6308,"position":14,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"আমার পূর্বে (এসেছে)","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":6309,"position":15,"text_uthmani":"يَدَىَّ","transliteration":"yadayya","translation_bn":"আমার পূর্বে (এসেছে)","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6310,"position":16,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6311,"position":17,"text_uthmani":"ٱلتَّوْرَىٰةِ","transliteration":"l-tawrāti","translation_bn":"তাওরাত","root":"—","lemma":"تَّوْرَىٰة","grammar_bn":"শব্দ"},{"id":6312,"position":18,"text_uthmani":"وَمُبَشِّرًۢا","transliteration":"wamubashiran","translation_bn":"এবং সুসংবাদদাতা","root":"بشر","lemma":"مُبَشِّر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6313,"position":19,"text_uthmani":"بِرَسُولٍۢ","transliteration":"birasūlin","translation_bn":"একজন রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"অব্যয় (Preposition)"},{"id":6314,"position":20,"text_uthmani":"يَأْتِى","transliteration":"yatī","translation_bn":"আসবেন","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":6315,"position":21,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6316,"position":22,"text_uthmani":"بَعْدِى","transliteration":"baʿdī","translation_bn":"আমার পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6317,"position":23,"text_uthmani":"ٱسْمُهُۥٓ","transliteration":"us''muhu","translation_bn":"তার নাম (হবে)","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6318,"position":24,"text_uthmani":"أَحْمَدُ ۖ","transliteration":"aḥmadu","translation_bn":"আহ্‌মদ\"","root":"—","lemma":"أَحْمَد","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6320,"position":25,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":6321,"position":26,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"তাদের তিনি (কাছে) আসলেন","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6322,"position":27,"text_uthmani":"بِٱلْبَيِّنَـٰتِ","transliteration":"bil-bayināti","translation_bn":"সুস্পষ্ট প্রমাণাদিসহ","root":"بين","lemma":"بَيِّنَة","grammar_bn":"অব্যয় (Preposition)"},{"id":6323,"position":28,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6324,"position":29,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"\"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6325,"position":30,"text_uthmani":"سِحْرٌۭ","transliteration":"siḥ''run","translation_bn":"জাদু","root":"سحر","lemma":"سِحْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":6326,"position":31,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"প্রকাশ্য\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":6327,"position":32,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qāla ʿīsā ub''nu maryama yābanī is''rāīla innī rasūlu l-lahi ilaykum muṣaddiqan limā bayna yadayya mina l-tawrāti wamubashiran birasūlin yatī min baʿdī us''muhu aḥmadu falammā jāahum bil-bayināti qālū hādhā siḥ''run mubīnun', 'স্মরণ কর, যখন মারইয়ামের পুত্র ‘ঈসা বলেছিল, ‘হে বানী ইসরাঈল! আমি তোমাদের প্রতি আল্লাহর রসূল, আমার পূর্ববর্তী তাওরাতের আমি সত্যায়নকারী এবং আমি একজন রসূলের সুসংবাদদাতা যিনি আমার পরে আসবেন, যার নাম আহমাদ।’ অতঃপর সে [অর্থাৎ ‘ঈসা (আঃ) যাঁর সম্পর্কে সুসংবাদ দিয়ে ছিলেন সেই নবী] যখন তাদের কাছে সুস্পষ্ট নিদর্শন নিয়ে আসল, তখন তারা বলল, ‘এটা তো স্পষ্ট যাদু।’', 'And [mention] when Jesus, the son of Mary, said, "O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad." But when he came to them with clear evidences, they said, "This is obvious magic."', 'স্মরণ কর, যখন মারইয়ামের পুত্র ‘ঈসা বলেছিল, ‘হে বানী ইসরাঈল! আমি তোমাদের প্রতি আল্লাহর রসূল, আমার পূর্ববর্তী তাওরাতের আমি সত্যায়নকারী এবং আমি একজন রসূলের সুসংবাদদাতা যিনি আমার পরে আসবেন, যার নাম আহমাদ।’ অতঃপর সে [অর্থাৎ ‘ঈসা (আঃ) যাঁর সম্পর্কে সুসংবাদ দিয়ে ছিলেন সেই নবী] যখন তাদের কাছে সুস্পষ্ট নিদর্শন নিয়ে আসল, তখন তারা বলল, ‘এটা তো স্পষ্ট যাদু।’', 'And [mention] when Jesus, the son of Mary, said, "O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad." But when he came to them with clear evidences, they said, "This is obvious magic."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061006.mp3', now()),
  (61, 7, '', '[{"id":7736,"position":1,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং কে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":7737,"position":2,"text_uthmani":"أَظْلَمُ","transliteration":"aẓlamu","translation_bn":"অধিক যালেম","root":"ظلم","lemma":"أَظْلَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7738,"position":3,"text_uthmani":"مِمَّنِ","transliteration":"mimmani","translation_bn":"(তার) অপেক্ষা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7739,"position":4,"text_uthmani":"ٱفْتَرَىٰ","transliteration":"if''tarā","translation_bn":"যে রচনা করে","root":"فري","lemma":"ٱفْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7740,"position":5,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7741,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7742,"position":7,"text_uthmani":"ٱلْكَذِبَ","transliteration":"l-kadhiba","translation_bn":"মিথ্যা","root":"كذب","lemma":"كَذِب","grammar_bn":"শব্দ"},{"id":7743,"position":8,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"অথচ তাকে","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":7744,"position":9,"text_uthmani":"يُدْعَىٰٓ","transliteration":"yud''ʿā","translation_bn":"আহ্বান করা হয়","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":7745,"position":10,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7746,"position":11,"text_uthmani":"ٱلْإِسْلَـٰمِ ۚ","transliteration":"l-is''lāmi","translation_bn":"ইসলামের","root":"سلم","lemma":"إِسْلَٰم","grammar_bn":"শব্দ"},{"id":7748,"position":12,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":7749,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7750,"position":14,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":7751,"position":15,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":7752,"position":16,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"যালেম","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":7753,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'waman aẓlamu mimmani if''tarā ʿalā l-lahi l-kadhiba wahuwa yud''ʿā ilā l-is''lāmi wal-lahu lā yahdī l-qawma l-ẓālimīna', 'তার চেয়ে অধিক যালিম আর কে যে আল্লাহ সম্বন্ধে মিথ্যে রচনা করে- অথচ তাকে ইসলামের পথ অবলম্বন করার জন্য আহবান জানানো হয়। (এ রকম) যালিম সম্প্রদায়কে আল্লাহ সঠিক পথে চালিত করেন না।', 'And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people.', 'তার চেয়ে অধিক যালিম আর কে যে আল্লাহ সম্বন্ধে মিথ্যে রচনা করে- অথচ তাকে ইসলামের পথ অবলম্বন করার জন্য আহবান জানানো হয়। (এ রকম) যালিম সম্প্রদায়কে আল্লাহ সঠিক পথে চালিত করেন না।', 'And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061007.mp3', now()),
  (61, 8, '', '[{"id":8908,"position":1,"text_uthmani":"يُرِيدُونَ","transliteration":"yurīdūna","translation_bn":"তারা চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8909,"position":2,"text_uthmani":"لِيُطْفِـُٔوا۟","transliteration":"liyuṭ''fiū","translation_bn":"নিভিয়ে দিতে","root":"طفا","lemma":"أَطْفَأَ","grammar_bn":"শব্দ"},{"id":8910,"position":3,"text_uthmani":"نُورَ","transliteration":"nūra","translation_bn":"নূর","root":"نور","lemma":"نُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":8911,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8912,"position":5,"text_uthmani":"بِأَفْوَٰهِهِمْ","transliteration":"bi-afwāhihim","translation_bn":"তাদের মুখের (ফুঁৎকার) দিয়ে","root":"فوه","lemma":"أَفْوَٰه","grammar_bn":"অব্যয় (Preposition)"},{"id":8913,"position":6,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":8914,"position":7,"text_uthmani":"مُتِمُّ","transliteration":"mutimmu","translation_bn":"সম্পূর্নকারী","root":"تمم","lemma":"مُتِمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8915,"position":8,"text_uthmani":"نُورِهِۦ","transliteration":"nūrihi","translation_bn":"তাঁর নূর","root":"نور","lemma":"نُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":8916,"position":9,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদিও","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":8917,"position":10,"text_uthmani":"كَرِهَ","transliteration":"kariha","translation_bn":"অপছন্দ করে","root":"كره","lemma":"كَرِهَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8918,"position":11,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"কাফিররা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":8919,"position":12,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'yurīdūna liyuṭ''fiū nūra l-lahi bi-afwāhihim wal-lahu mutimmu nūrihi walaw kariha l-kāfirūna', 'তারা তাদের মুখের ফুঁৎকারে আল্লাহর নূরকে নিভিয়ে দিতে চায়, কিন্তু আল্লাহ তাঁর নূরকে পরিপূর্ণ করবেনই যদিও কাফিররা (তা) অপছন্দ করে।', 'They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.', 'তারা তাদের মুখের ফুঁৎকারে আল্লাহর নূরকে নিভিয়ে দিতে চায়, কিন্তু আল্লাহ তাঁর নূরকে পরিপূর্ণ করবেনই যদিও কাফিররা (তা) অপছন্দ করে।', 'They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061008.mp3', now()),
  (61, 9, '', '[{"id":10121,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10122,"position":2,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10123,"position":3,"text_uthmani":"أَرْسَلَ","transliteration":"arsala","translation_bn":"পাঠিয়েছেন","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10124,"position":4,"text_uthmani":"رَسُولَهُۥ","transliteration":"rasūlahu","translation_bn":"তাঁর রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":10125,"position":5,"text_uthmani":"بِٱلْهُدَىٰ","transliteration":"bil-hudā","translation_bn":"হেদায়াতসহ","root":"هدي","lemma":"هُدًى","grammar_bn":"অব্যয় (Preposition)"},{"id":10126,"position":6,"text_uthmani":"وَدِينِ","transliteration":"wadīni","translation_bn":"ও দ্বীন","root":"دين","lemma":"دِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10127,"position":7,"text_uthmani":"ٱلْحَقِّ","transliteration":"l-ḥaqi","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":10128,"position":8,"text_uthmani":"لِيُظْهِرَهُۥ","transliteration":"liyuẓ''hirahu","translation_bn":"তা বিজয়ী করে যেন","root":"ظهر","lemma":"أَظْهَرَ","grammar_bn":"শব্দ"},{"id":10129,"position":9,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10130,"position":10,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"দ্বীনের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":10131,"position":11,"text_uthmani":"كُلِّهِۦ","transliteration":"kullihi","translation_bn":"সর্বপ্রকারের","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10132,"position":12,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদিও","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":10133,"position":13,"text_uthmani":"كَرِهَ","transliteration":"kariha","translation_bn":"অপছন্দ করে","root":"كره","lemma":"كَرِهَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10134,"position":14,"text_uthmani":"ٱلْمُشْرِكُونَ","transliteration":"l-mush''rikūna","translation_bn":"মুশরিকরা","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":10135,"position":15,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī arsala rasūlahu bil-hudā wadīni l-ḥaqi liyuẓ''hirahu ʿalā l-dīni kullihi walaw kariha l-mush''rikūna', 'তিনিই তাঁর রসূলকে হিদায়াত ও সত্য দীনসহ পাঠিয়েছেন তাকে সকল দীনের উপর বিজয়ী করার জন্য- যদিও মুশরিকরা (তা) অপছন্দ করে।', 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it.', 'তিনিই তাঁর রসূলকে হিদায়াত ও সত্য দীনসহ পাঠিয়েছেন তাকে সকল দীনের উপর বিজয়ী করার জন্য- যদিও মুশরিকরা (তা) অপছন্দ করে।', 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061009.mp3', now()),
  (61, 10, '', '[{"id":11364,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":11365,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11366,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11367,"position":4,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":11368,"position":5,"text_uthmani":"أَدُلُّكُمْ","transliteration":"adullukum","translation_bn":"আমি তোমাদের সন্ধান দিবো","root":"دلل","lemma":"دَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11369,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"সম্বন্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11370,"position":7,"text_uthmani":"تِجَـٰرَةٍۢ","transliteration":"tijāratin","translation_bn":"ব্যবসা (যা)","root":"تجر","lemma":"تِجَٰرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11371,"position":8,"text_uthmani":"تُنجِيكُم","transliteration":"tunjīkum","translation_bn":"তোমাদের মুক্তি দিবে","root":"نجو","lemma":"أَنجَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11372,"position":9,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11373,"position":10,"text_uthmani":"عَذَابٍ","transliteration":"ʿadhābin","translation_bn":"আযাব","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11374,"position":11,"text_uthmani":"أَلِيمٍۢ","transliteration":"alīmin","translation_bn":"কষ্টদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":11375,"position":12,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū hal adullukum ʿalā tijāratin tunjīkum min ʿadhābin alīmin', 'হে মু’মিনগণ! আমি কি তোমাদেরকে এমন এক ব্যবসায়ের সন্ধান দেব যা তোমাদেরকে মর্মান্তিক ‘আযাব থেকে রক্ষা করবে?', 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?', 'হে মু’মিনগণ! আমি কি তোমাদেরকে এমন এক ব্যবসায়ের সন্ধান দেব যা তোমাদেরকে মর্মান্তিক ‘আযাব থেকে রক্ষা করবে?', 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061010.mp3', now()),
  (61, 11, '', '[{"id":12656,"position":1,"text_uthmani":"تُؤْمِنُونَ","transliteration":"tu''minūna","translation_bn":"তোমরা ঈমান আনো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12657,"position":2,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহর উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":12658,"position":3,"text_uthmani":"وَرَسُولِهِۦ","transliteration":"warasūlihi","translation_bn":"ও তাঁর রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12659,"position":4,"text_uthmani":"وَتُجَـٰهِدُونَ","transliteration":"watujāhidūna","translation_bn":"এবং তোমরা জিহাদ করো","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12660,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"(মধ্যে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12661,"position":6,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথে","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":12662,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12663,"position":8,"text_uthmani":"بِأَمْوَٰلِكُمْ","transliteration":"bi-amwālikum","translation_bn":"তোমাদের মালসমূহ দিয়ে","root":"مول","lemma":"مَال","grammar_bn":"অব্যয় (Preposition)"},{"id":12664,"position":9,"text_uthmani":"وَأَنفُسِكُمْ ۚ","transliteration":"wa-anfusikum","translation_bn":"ও তোমাদের জানপ্রাণ (দিয়ে)","root":"نفس","lemma":"نَفْس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12666,"position":10,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":12667,"position":11,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12668,"position":12,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12669,"position":13,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":12670,"position":14,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12671,"position":15,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12672,"position":16,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'tu''minūna bil-lahi warasūlihi watujāhidūna fī sabīli l-lahi bi-amwālikum wa-anfusikum dhālikum khayrun lakum in kuntum taʿlamūna', '(তা এই যে) তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আনো আর তোমরা তোমাদের মাল ও জান দিয়ে আল্লাহর পথে জিহাদ কর; এটাই তোমাদের জন্য অতি উত্তম, যদি তোমরা জানতে!', '[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know.', '(তা এই যে) তোমরা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আনো আর তোমরা তোমাদের মাল ও জান দিয়ে আল্লাহর পথে জিহাদ কর; এটাই তোমাদের জন্য অতি উত্তম, যদি তোমরা জানতে!', '[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061011.mp3', now()),
  (61, 12, '', '[{"id":13998,"position":1,"text_uthmani":"يَغْفِرْ","transliteration":"yaghfir","translation_bn":"তিনি মাফ করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13999,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":14000,"position":3,"text_uthmani":"ذُنُوبَكُمْ","transliteration":"dhunūbakum","translation_bn":"তোমাদের গুনাহসমূহকে","root":"ذنب","lemma":"ذَنب","grammar_bn":"বিশেষ্য (Noun)"},{"id":14001,"position":4,"text_uthmani":"وَيُدْخِلْكُمْ","transliteration":"wayud''khil''kum","translation_bn":"ও তোমাদের প্রবেশ করাবেন","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14002,"position":5,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14003,"position":6,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14004,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14005,"position":8,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার পাদদেশে","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":14006,"position":9,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":14007,"position":10,"text_uthmani":"وَمَسَـٰكِنَ","transliteration":"wamasākina","translation_bn":"এবং বাসগৃহসমূহ","root":"سكن","lemma":"مَسْكَن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14008,"position":11,"text_uthmani":"طَيِّبَةًۭ","transliteration":"ṭayyibatan","translation_bn":"উত্তম","root":"طيب","lemma":"طَيِّبَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":14009,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14010,"position":13,"text_uthmani":"جَنَّـٰتِ","transliteration":"jannāti","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14011,"position":14,"text_uthmani":"عَدْنٍۢ ۚ","transliteration":"ʿadnin","translation_bn":"চিরস্থায়ী","root":"—","lemma":"عَدْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14013,"position":15,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":14014,"position":16,"text_uthmani":"ٱلْفَوْزُ","transliteration":"l-fawzu","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"শব্দ"},{"id":14015,"position":17,"text_uthmani":"ٱلْعَظِيمُ","transliteration":"l-ʿaẓīmu","translation_bn":"মহা","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":14016,"position":18,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'yaghfir lakum dhunūbakum wayud''khil''kum jannātin tajrī min taḥtihā l-anhāru wamasākina ṭayyibatan fī jannāti ʿadnin dhālika l-fawzu l-ʿaẓīmu', '(তোমরা যদি আল্লাহর সন্ধান দেয়া ব্যবসা কর তাহলে) তিনি তোমাদের পাপ ক্ষমা করে দেবেন আর তোমাদেরকে দাখিল করবেন জান্নাতে যার তলদেশে ঝর্ণাধারা প্রবাহিত। আর চিরস্থায়ী আবাসস্থল জান্নাতে অতি উত্তম ঘর তোমাদেরকে দান করবেন। এটাই বিরাট সাফল্য।', 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.', '(তোমরা যদি আল্লাহর সন্ধান দেয়া ব্যবসা কর তাহলে) তিনি তোমাদের পাপ ক্ষমা করে দেবেন আর তোমাদেরকে দাখিল করবেন জান্নাতে যার তলদেশে ঝর্ণাধারা প্রবাহিত। আর চিরস্থায়ী আবাসস্থল জান্নাতে অতি উত্তম ঘর তোমাদেরকে দান করবেন। এটাই বিরাট সাফল্য।', 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061012.mp3', now()),
  (61, 13, '', '[{"id":15113,"position":1,"text_uthmani":"وَأُخْرَىٰ","transliteration":"wa-ukh''rā","translation_bn":"এবং অন্যটি","root":"اخر","lemma":"ا^خَر","grammar_bn":"শব্দ"},{"id":15114,"position":2,"text_uthmani":"تُحِبُّونَهَا ۖ","transliteration":"tuḥibbūnahā","translation_bn":"যা তোমরা পছন্দ করো","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15116,"position":3,"text_uthmani":"نَصْرٌۭ","transliteration":"naṣrun","translation_bn":"সাহায্য","root":"نصر","lemma":"نَصْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":15117,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15118,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15119,"position":6,"text_uthmani":"وَفَتْحٌۭ","transliteration":"wafatḥun","translation_bn":"ও বিজয়","root":"فتح","lemma":"فَتْح","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15120,"position":7,"text_uthmani":"قَرِيبٌۭ ۗ","transliteration":"qarībun","translation_bn":"আসন্ন","root":"قرب","lemma":"قَرِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":15122,"position":8,"text_uthmani":"وَبَشِّرِ","transliteration":"wabashiri","translation_bn":"এবং সুসংবাদ দাও","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15123,"position":9,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":15124,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ukh''rā tuḥibbūnahā naṣrun mina l-lahi wafatḥun qarībun wabashiri l-mu''minīna', 'আর অন্য আরেকটিও (তিনি তোমাদেরকে দিবেন) যা তোমরা পছন্দ কর (আর তা হল) আল্লাহর সাহায্য ও আসন্ন বিজয়। (হে নবী!) ঈমানদার লোকেদেরকে তুমি সুসংবাদ দাও।', 'And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.', 'আর অন্য আরেকটিও (তিনি তোমাদেরকে দিবেন) যা তোমরা পছন্দ কর (আর তা হল) আল্লাহর সাহায্য ও আসন্ন বিজয়। (হে নবী!) ঈমানদার লোকেদেরকে তুমি সুসংবাদ দাও।', 'And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061013.mp3', now()),
  (61, 14, '', '[{"id":16163,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":16164,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16165,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16166,"position":4,"text_uthmani":"كُونُوٓا۟","transliteration":"kūnū","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16167,"position":5,"text_uthmani":"أَنصَارَ","transliteration":"anṣāra","translation_bn":"সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":16168,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16169,"position":7,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16170,"position":8,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16171,"position":9,"text_uthmani":"عِيسَى","transliteration":"ʿīsā","translation_bn":"ঈসা","root":"—","lemma":"عِيسَى","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16172,"position":10,"text_uthmani":"ٱبْنُ","transliteration":"ub''nu","translation_bn":"তনয়","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":16173,"position":11,"text_uthmani":"مَرْيَمَ","transliteration":"maryama","translation_bn":"মারয়ামের","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16174,"position":12,"text_uthmani":"لِلْحَوَارِيِّـۧنَ","transliteration":"lil''ḥawāriyyīna","translation_bn":"হাওয়ারীদেরকে","root":"حور","lemma":"حَوَارِيُّون","grammar_bn":"অব্যয় (Preposition)"},{"id":16175,"position":13,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16176,"position":14,"text_uthmani":"أَنصَارِىٓ","transliteration":"anṣārī","translation_bn":"আমার সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":16177,"position":15,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16178,"position":16,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহর\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16180,"position":17,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16181,"position":18,"text_uthmani":"ٱلْحَوَارِيُّونَ","transliteration":"l-ḥawāriyūna","translation_bn":"হাওয়ারীরা","root":"حور","lemma":"حَوَارِيُّون","grammar_bn":"শব্দ"},{"id":16182,"position":19,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"\"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":16183,"position":20,"text_uthmani":"أَنصَارُ","transliteration":"anṣāru","translation_bn":"সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":16184,"position":21,"text_uthmani":"ٱللَّهِ ۖ","transliteration":"l-lahi","translation_bn":"আল্লাহর\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16186,"position":22,"text_uthmani":"فَـَٔامَنَت","transliteration":"faāmanat","translation_bn":"অতঃপর ঈমান আনল","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":16187,"position":23,"text_uthmani":"طَّآئِفَةٌۭ","transliteration":"ṭāifatun","translation_bn":"এক দল","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16188,"position":24,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16189,"position":25,"text_uthmani":"بَنِىٓ","transliteration":"banī","translation_bn":"বনী","root":"بني","lemma":"بُنَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16190,"position":26,"text_uthmani":"إِسْرَٰٓءِيلَ","transliteration":"is''rāīla","translation_bn":"ইসরাইল","root":"—","lemma":"إِسْرَائِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16191,"position":27,"text_uthmani":"وَكَفَرَت","transliteration":"wakafarat","translation_bn":"এবং কুফরি করল","root":"كفر","lemma":"كَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16192,"position":28,"text_uthmani":"طَّآئِفَةٌۭ ۖ","transliteration":"ṭāifatun","translation_bn":"এক দল","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16194,"position":29,"text_uthmani":"فَأَيَّدْنَا","transliteration":"fa-ayyadnā","translation_bn":"অতঃপর আমরা সাহায্য করলাম","root":"ايد","lemma":"أَيَّدَ","grammar_bn":"কারণবাচক (Cause)"},{"id":16195,"position":30,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16196,"position":31,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছিল","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16197,"position":32,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16198,"position":33,"text_uthmani":"عَدُوِّهِمْ","transliteration":"ʿaduwwihim","translation_bn":"তাদের দুশমনের","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16199,"position":34,"text_uthmani":"فَأَصْبَحُوا۟","transliteration":"fa-aṣbaḥū","translation_bn":"অতঃপর তারা হলো","root":"صبح","lemma":"أَصْبَحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16200,"position":35,"text_uthmani":"ظَـٰهِرِينَ","transliteration":"ẓāhirīna","translation_bn":"বিজয়ী","root":"ظهر","lemma":"ظَٰهِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":16201,"position":36,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū kūnū anṣāra l-lahi kamā qāla ʿīsā ub''nu maryama lil''ḥawāriyyīna man anṣārī ilā l-lahi qāla l-ḥawāriyūna naḥnu anṣāru l-lahi faāmanat ṭāifatun min banī is''rāīla wakafarat ṭāifatun fa-ayyadnā alladhīna āmanū ʿalā ʿaduwwihim fa-aṣbaḥū ẓāhirīna', 'হে মু’মিনগণ! তোমরা আল্লাহর সাহায্যকারী হও, যেমন মারইয়ামের পুত্র ‘ঈসা হাওয়ারীদেরকে বলেছিল- ‘আল্লাহর পথে কে আমার সাহায্যকারী হবে?’ হাওয়ারীরা উত্তরে বলেছিল- ‘আমরাই আল্লাহর সাহায্যকারী (হব)।’ অতঃপর বানী ইসরাঈলের একদল ঈমান আনল, আরেক দল প্রত্যাখ্যান করল। তখন যারা ঈমান আনল তাদেরকে আমি তাদের শত্রুদের উপর শক্তিশালী করলাম। ফলে তারা বিজয়ী হল।', 'O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allah?" The disciples said, "We are supporters of Allah." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.', 'হে মু’মিনগণ! তোমরা আল্লাহর সাহায্যকারী হও, যেমন মারইয়ামের পুত্র ‘ঈসা হাওয়ারীদেরকে বলেছিল- ‘আল্লাহর পথে কে আমার সাহায্যকারী হবে?’ হাওয়ারীরা উত্তরে বলেছিল- ‘আমরাই আল্লাহর সাহায্যকারী (হব)।’ অতঃপর বানী ইসরাঈলের একদল ঈমান আনল, আরেক দল প্রত্যাখ্যান করল। তখন যারা ঈমান আনল তাদেরকে আমি তাদের শত্রুদের উপর শক্তিশালী করলাম। ফলে তারা বিজয়ী হল।', 'O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allah?" The disciples said, "We are supporters of Allah." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/061014.mp3', now())
