  (62, 1, '', '[{"id":456,"position":1,"text_uthmani":"يُسَبِّحُ","transliteration":"yusabbiḥu","translation_bn":"মহিমা ঘোষণা করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":457,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":458,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":459,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":460,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ জগতের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":461,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":462,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":463,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":464,"position":9,"text_uthmani":"ٱلْمَلِكِ","transliteration":"l-maliki","translation_bn":"অধিপতি","root":"ملك","lemma":"مَلِك","grammar_bn":"শব্দ"},{"id":465,"position":10,"text_uthmani":"ٱلْقُدُّوسِ","transliteration":"l-qudūsi","translation_bn":"মহান পবিত্র","root":"قدس","lemma":"قُدُّوس","grammar_bn":"শব্দ"},{"id":466,"position":11,"text_uthmani":"ٱلْعَزِيزِ","transliteration":"l-ʿazīzi","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":467,"position":12,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":468,"position":13,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yusabbiḥu lillahi mā fī l-samāwāti wamā fī l-arḍi l-maliki l-qudūsi l-ʿazīzi l-ḥakīmi', 'যা কিছু আসমানে আছে আর যা কিছু যমীনে আছে সব কিছুই প্রশংসা ও মহিমা ঘোষণা করে আল্লাহর যিনি সর্বময় ক্ষমতার অধিকারী, অতি পবিত্র, মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise.', 'যা কিছু আসমানে আছে আর যা কিছু যমীনে আছে সব কিছুই প্রশংসা ও মহিমা ঘোষণা করে আল্লাহর যিনি সর্বময় ক্ষমতার অধিকারী, অতি পবিত্র, মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062001.mp3', now()),
  (62, 2, '', '[{"id":1330,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1331,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1332,"position":3,"text_uthmani":"بَعَثَ","transliteration":"baʿatha","translation_bn":"পাঠিয়েছেন","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1333,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1334,"position":5,"text_uthmani":"ٱلْأُمِّيِّـۧنَ","transliteration":"l-umiyīna","translation_bn":"নিরক্ষরদের","root":"امم","lemma":"أُمِّىّ","grammar_bn":"শব্দ"},{"id":1335,"position":6,"text_uthmani":"رَسُولًۭا","transliteration":"rasūlan","translation_bn":"একজন রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":1336,"position":7,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্য থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1337,"position":8,"text_uthmani":"يَتْلُوا۟","transliteration":"yatlū","translation_bn":"যে আবৃত্তি করে","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1338,"position":9,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1339,"position":10,"text_uthmani":"ءَايَـٰتِهِۦ","transliteration":"āyātihi","translation_bn":"তাঁর আয়াতগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1340,"position":11,"text_uthmani":"وَيُزَكِّيهِمْ","transliteration":"wayuzakkīhim","translation_bn":"ও তাদের পরিশুদ্ধ করে","root":"زكو","lemma":"زَكَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1341,"position":12,"text_uthmani":"وَيُعَلِّمُهُمُ","transliteration":"wayuʿallimuhumu","translation_bn":"ও তাদের শিক্ষা দেয়","root":"علم","lemma":"عَلَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1342,"position":13,"text_uthmani":"ٱلْكِتَـٰبَ","transliteration":"l-kitāba","translation_bn":"কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1343,"position":14,"text_uthmani":"وَٱلْحِكْمَةَ","transliteration":"wal-ḥik''mata","translation_bn":"হিকমত","root":"حكم","lemma":"حِكْمَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1344,"position":15,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদিও","root":"—","lemma":"إِن\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":1345,"position":16,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1346,"position":17,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1347,"position":18,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1348,"position":19,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"মধ্যে অবশ্যই","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":1349,"position":20,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"বিভ্রান্তির","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1350,"position":21,"text_uthmani":"مُّبِينٍۢ","transliteration":"mubīnin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":1351,"position":22,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī baʿatha fī l-umiyīna rasūlan min''hum yatlū ʿalayhim āyātihi wayuzakkīhim wayuʿallimuhumu l-kitāba wal-ḥik''mata wa-in kānū min qablu lafī ḍalālin mubīnin', 'তিনিই নিরক্ষরদের মাঝে পাঠিয়েছেন তাঁর রসূলকে তাদেরই মধ্য হতে, যে তাদের কাছে আল্লাহর আয়াত পাঠ করে, তাদেরকে পবিত্র করে, আর তাদেরকে কিতাব ও হিকমত শিক্ষা দেয় অথচ ইতোপূর্বে তারা ছিল স্পষ্ট গুমরাহীতে নিমজ্জিত।', 'It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -', 'তিনিই নিরক্ষরদের মাঝে পাঠিয়েছেন তাঁর রসূলকে তাদেরই মধ্য হতে, যে তাদের কাছে আল্লাহর আয়াত পাঠ করে, তাদেরকে পবিত্র করে, আর তাদেরকে কিতাব ও হিকমত শিক্ষা দেয় অথচ ইতোপূর্বে তারা ছিল স্পষ্ট গুমরাহীতে নিমজ্জিত।', 'It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062002.mp3', now()),
  (62, 3, '', '[{"id":2416,"position":1,"text_uthmani":"وَءَاخَرِينَ","transliteration":"waākharīna","translation_bn":"এবং অন্যান্যদের (জন্যেও)","root":"اخر","lemma":"ا^خَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2417,"position":2,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের থেকে (যারা)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2418,"position":3,"text_uthmani":"لَمَّا","transliteration":"lammā","translation_bn":"নাই এখনও","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":2419,"position":4,"text_uthmani":"يَلْحَقُوا۟","transliteration":"yalḥaqū","translation_bn":"মিলে","root":"لحق","lemma":"يَلْحَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2420,"position":5,"text_uthmani":"بِهِمْ ۚ","transliteration":"bihim","translation_bn":"তাদের সাথে","root":"—","lemma":"بِهِمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":2422,"position":6,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":2423,"position":7,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশীল","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":2424,"position":8,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":2425,"position":9,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'waākharīna min''hum lammā yalḥaqū bihim wahuwa l-ʿazīzu l-ḥakīmu', 'আর (এই রসূলকে পাঠানো হয়েছে) তাদের অন্যান্যদের জন্যও যারা এখনও তাদের সাথে মিলিত হয়নি (কিন্তু তারা ভবিষ্যতে আসবে)। আল্লাহ মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.', 'আর (এই রসূলকে পাঠানো হয়েছে) তাদের অন্যান্যদের জন্যও যারা এখনও তাদের সাথে মিলিত হয়নি (কিন্তু তারা ভবিষ্যতে আসবে)। আল্লাহ মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062003.mp3', now()),
  (62, 4, '', '[{"id":3805,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3806,"position":2,"text_uthmani":"فَضْلُ","transliteration":"faḍlu","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3807,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3808,"position":4,"text_uthmani":"يُؤْتِيهِ","transliteration":"yu''tīhi","translation_bn":"তাকে দেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3809,"position":5,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3810,"position":6,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3812,"position":7,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":3813,"position":8,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"(আছে)","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":3814,"position":9,"text_uthmani":"ٱلْفَضْلِ","transliteration":"l-faḍli","translation_bn":"অনুগ্রহকারী","root":"فضل","lemma":"فَضْل","grammar_bn":"শব্দ"},{"id":3815,"position":10,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":3816,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika faḍlu l-lahi yu''tīhi man yashāu wal-lahu dhū l-faḍli l-ʿaẓīmi', 'ওটা আল্লাহর অনুগ্রহ যা তিনি যাকে ইচ্ছে দান করেন; আল্লাহ মহা অনুগ্রহের অধিকারী।', 'That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty.', 'ওটা আল্লাহর অনুগ্রহ যা তিনি যাকে ইচ্ছে দান করেন; আল্লাহ মহা অনুগ্রহের অধিকারী।', 'That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062004.mp3', now()),
  (62, 5, '', '[{"id":5066,"position":1,"text_uthmani":"مَثَلُ","transliteration":"mathalu","translation_bn":"দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5067,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5068,"position":3,"text_uthmani":"حُمِّلُوا۟","transliteration":"ḥummilū","translation_bn":"ভার দেয়া হয়েছিল","root":"حمل","lemma":"حُمِّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5069,"position":4,"text_uthmani":"ٱلتَّوْرَىٰةَ","transliteration":"l-tawrāta","translation_bn":"তাওরাতের (দায়িত্ব)","root":"—","lemma":"تَّوْرَىٰة","grammar_bn":"শব্দ"},{"id":5070,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5071,"position":6,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নাই","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":5072,"position":7,"text_uthmani":"يَحْمِلُوهَا","transliteration":"yaḥmilūhā","translation_bn":"তা বহন করে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5073,"position":8,"text_uthmani":"كَمَثَلِ","transliteration":"kamathali","translation_bn":"দৃষ্টান্ত যেমন","root":"مثل","lemma":"مَثَل","grammar_bn":"অব্যয় (Preposition)"},{"id":5074,"position":9,"text_uthmani":"ٱلْحِمَارِ","transliteration":"l-ḥimāri","translation_bn":"গাধার","root":"حمر","lemma":"حِمَار","grammar_bn":"শব্দ"},{"id":5075,"position":10,"text_uthmani":"يَحْمِلُ","transliteration":"yaḥmilu","translation_bn":"বহন করে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5076,"position":11,"text_uthmani":"أَسْفَارًۢا ۚ","transliteration":"asfāran","translation_bn":"কিতাবসমূহ","root":"سفر","lemma":"أَسْفَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":5078,"position":12,"text_uthmani":"بِئْسَ","transliteration":"bi''sa","translation_bn":"কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5079,"position":13,"text_uthmani":"مَثَلُ","transliteration":"mathalu","translation_bn":"দৃষ্টান্ত","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5080,"position":14,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"(সেই) লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":5081,"position":15,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5082,"position":16,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5083,"position":17,"text_uthmani":"بِـَٔايَـٰتِ","transliteration":"biāyāti","translation_bn":"আয়াতগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":5084,"position":18,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5086,"position":19,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":5087,"position":20,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":5088,"position":21,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"হেদায়াত দেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":5089,"position":22,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":5090,"position":23,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"যালেম","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":5091,"position":24,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'mathalu alladhīna ḥummilū l-tawrāta thumma lam yaḥmilūhā kamathali l-ḥimāri yaḥmilu asfāran bi''sa mathalu l-qawmi alladhīna kadhabū biāyāti l-lahi wal-lahu lā yahdī l-qawma l-ẓālimīna', 'যাদের উপর তাওরাতের দায়িত্বভার দেয়া হয়েছিল, অতঃপর তা তারা বহন করেনি (অর্থাৎ তারা তাদের উপর ন্যস্ত দায়িত্ব পালন করেনি) তাদের দৃষ্টান্ত হল গাধার মত, যে বহু কিতাবের বোঝা বহন করে (কিন্তু তা বুঝে না)। যে সম্প্রদায় আল্লাহর আয়াতগুলোকে অস্বীকার করে, তাদের দৃষ্টান্ত কতইনা নিকৃষ্ট! যালিম সম্প্রদায়কে আল্লাহ সঠিক পথে পরিচালিত করেন না।', 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.', 'যাদের উপর তাওরাতের দায়িত্বভার দেয়া হয়েছিল, অতঃপর তা তারা বহন করেনি (অর্থাৎ তারা তাদের উপর ন্যস্ত দায়িত্ব পালন করেনি) তাদের দৃষ্টান্ত হল গাধার মত, যে বহু কিতাবের বোঝা বহন করে (কিন্তু তা বুঝে না)। যে সম্প্রদায় আল্লাহর আয়াতগুলোকে অস্বীকার করে, তাদের দৃষ্টান্ত কতইনা নিকৃষ্ট! যালিম সম্প্রদায়কে আল্লাহ সঠিক পথে পরিচালিত করেন না।', 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062005.mp3', now()),
  (62, 6, '', '[{"id":6328,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6329,"position":2,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"\"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":6330,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"\"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6331,"position":4,"text_uthmani":"هَادُوٓا۟","transliteration":"hādū","translation_bn":"\"ইহুদী হয়েছো","root":"هود","lemma":"هَادُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6332,"position":5,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":6333,"position":6,"text_uthmani":"زَعَمْتُمْ","transliteration":"zaʿamtum","translation_bn":"তোমরা দাবি করো","root":"زعم","lemma":"زَعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6334,"position":7,"text_uthmani":"أَنَّكُمْ","transliteration":"annakum","translation_bn":"তোমরাই যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6335,"position":8,"text_uthmani":"أَوْلِيَآءُ","transliteration":"awliyāu","translation_bn":"বন্ধু","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6336,"position":9,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":6337,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6338,"position":11,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":6339,"position":12,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"(অন্য) মানবগোষ্ঠী","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":6340,"position":13,"text_uthmani":"فَتَمَنَّوُا۟","transliteration":"fatamannawū","translation_bn":"তবে তোমরা কামনা করো","root":"مني","lemma":"يَتَمَنَّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":6341,"position":14,"text_uthmani":"ٱلْمَوْتَ","transliteration":"l-mawta","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":6342,"position":15,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":6343,"position":16,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হও","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6344,"position":17,"text_uthmani":"صَـٰدِقِينَ","transliteration":"ṣādiqīna","translation_bn":"সত্যবাদী\"","root":"صدق","lemma":"صَادِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":6345,"position":18,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'qul yāayyuhā alladhīna hādū in zaʿamtum annakum awliyāu lillahi min dūni l-nāsi fatamannawū l-mawta in kuntum ṣādiqīna', 'বল- ‘হে ইয়াহূদী হয়ে যাওয়া লোকেরা! তোমরা যদি মনে কর যে, অন্য সব লোককে বাদ দিয়ে কেবল তোমরাই আল্লাহর বন্ধু, তাহলে তোমরা মৃত্যু কামনা কর, যদি তোমরা সত্যবাদী হয়ে থাকো।', 'Say, "O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful."', 'বল- ‘হে ইয়াহূদী হয়ে যাওয়া লোকেরা! তোমরা যদি মনে কর যে, অন্য সব লোককে বাদ দিয়ে কেবল তোমরাই আল্লাহর বন্ধু, তাহলে তোমরা মৃত্যু কামনা কর, যদি তোমরা সত্যবাদী হয়ে থাকো।', 'Say, "O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062006.mp3', now()),
  (62, 7, '', '[{"id":7754,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":7755,"position":2,"text_uthmani":"يَتَمَنَّوْنَهُۥٓ","transliteration":"yatamannawnahu","translation_bn":"তারা তা কামনা করবে","root":"مني","lemma":"يَتَمَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7756,"position":3,"text_uthmani":"أَبَدًۢا","transliteration":"abadan","translation_bn":"কখনও","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":7757,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7758,"position":5,"text_uthmani":"قَدَّمَتْ","transliteration":"qaddamat","translation_bn":"আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7759,"position":6,"text_uthmani":"أَيْدِيهِمْ ۚ","transliteration":"aydīhim","translation_bn":"তাদের হাতগুলো","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":7761,"position":7,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":7762,"position":8,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুব অবহিত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7763,"position":9,"text_uthmani":"بِٱلظَّـٰلِمِينَ","transliteration":"bil-ẓālimīna","translation_bn":"যালিমদের সম্পর্কে","root":"ظلم","lemma":"ظَالِم","grammar_bn":"অব্যয় (Preposition)"},{"id":7764,"position":10,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'walā yatamannawnahu abadan bimā qaddamat aydīhim wal-lahu ʿalīmun bil-ẓālimīna', 'কিন্তু তাদের হাত যে সব (কৃতকর্ম) আগে পাঠিয়েছে, সে কারণে তারা কক্ষনো মৃত্যুর কামনা করবে না। আর আল্লাহ যালিমদেরকে খুব ভাল করেই জানেন।', 'But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.', 'কিন্তু তাদের হাত যে সব (কৃতকর্ম) আগে পাঠিয়েছে, সে কারণে তারা কক্ষনো মৃত্যুর কামনা করবে না। আর আল্লাহ যালিমদেরকে খুব ভাল করেই জানেন।', 'But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062007.mp3', now()),
  (62, 8, '', '[{"id":8920,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8921,"position":2,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8922,"position":3,"text_uthmani":"ٱلْمَوْتَ","transliteration":"l-mawta","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":8923,"position":4,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যা (থেকে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8924,"position":5,"text_uthmani":"تَفِرُّونَ","transliteration":"tafirrūna","translation_bn":"তোমরা পলায়ন কর","root":"فرر","lemma":"فَرَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8925,"position":6,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8926,"position":7,"text_uthmani":"فَإِنَّهُۥ","transliteration":"fa-innahu","translation_bn":"অতঃপর নিশ্চয় তা","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":8927,"position":8,"text_uthmani":"مُلَـٰقِيكُمْ ۖ","transliteration":"mulāqīkum","translation_bn":"তোমাদের মিলবে","root":"لقي","lemma":"مُلَٰقِي","grammar_bn":"বিশেষ্য (Noun)"},{"id":8929,"position":9,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8930,"position":10,"text_uthmani":"تُرَدُّونَ","transliteration":"turaddūna","translation_bn":"তোমরা প্রত্যানীত হবে","root":"ردد","lemma":"رَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8931,"position":11,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8932,"position":12,"text_uthmani":"عَـٰلِمِ","transliteration":"ʿālimi","translation_bn":"পরিজ্ঞাতার","root":"علم","lemma":"عَٰلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":8933,"position":13,"text_uthmani":"ٱلْغَيْبِ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":8934,"position":14,"text_uthmani":"وَٱلشَّهَـٰدَةِ","transliteration":"wal-shahādati","translation_bn":"ও দৃশ্যের","root":"شهد","lemma":"شَهَٰدَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8935,"position":15,"text_uthmani":"فَيُنَبِّئُكُم","transliteration":"fayunabbi-ukum","translation_bn":"অতঃপর তোমাদের জানিয়ে দিবেন","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8936,"position":16,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8937,"position":17,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8938,"position":18,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"কাজ করতেছিলে\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8939,"position":19,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'qul inna l-mawta alladhī tafirrūna min''hu fa-innahu mulāqīkum thumma turaddūna ilā ʿālimi l-ghaybi wal-shahādati fayunabbi-ukum bimā kuntum taʿmalūna', 'বল- ‘তোমরা যে মৃত্যু থেকে পালাচ্ছ তা অবশ্যই তোমাদের সাথে সাক্ষাৎ করবে। অতঃপর তোমাদেরকে দৃশ্য ও অদৃশ্যের জ্ঞানের অধিকারী (আল্লাহ)’র নিকট ফিরিয়ে নেয়া হবে; অতঃপর তোমাদেরকে জানিয়ে দেয়া হবে যা তোমরা করতে।', 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."', 'বল- ‘তোমরা যে মৃত্যু থেকে পালাচ্ছ তা অবশ্যই তোমাদের সাথে সাক্ষাৎ করবে। অতঃপর তোমাদেরকে দৃশ্য ও অদৃশ্যের জ্ঞানের অধিকারী (আল্লাহ)’র নিকট ফিরিয়ে নেয়া হবে; অতঃপর তোমাদেরকে জানিয়ে দেয়া হবে যা তোমরা করতে।', 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062008.mp3', now()),
  (62, 9, '', '[{"id":10136,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":10137,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10138,"position":3,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10139,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":10140,"position":5,"text_uthmani":"نُودِىَ","transliteration":"nūdiya","translation_bn":"ডাকা হয়","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10141,"position":6,"text_uthmani":"لِلصَّلَوٰةِ","transliteration":"lilṣṣalati","translation_bn":"নামাজের জন্যে","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"অব্যয় (Preposition)"},{"id":10142,"position":7,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10143,"position":8,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10144,"position":9,"text_uthmani":"ٱلْجُمُعَةِ","transliteration":"l-jumuʿati","translation_bn":"জুমুয়া''র","root":"جمع","lemma":"جُمُعَة","grammar_bn":"শব্দ"},{"id":10145,"position":10,"text_uthmani":"فَٱسْعَوْا۟","transliteration":"fa-is''ʿaw","translation_bn":"তখন তোমরা ধাবিত  হও","root":"سعي","lemma":"سَعَىٰ","grammar_bn":"ফলাফল পদ (Result)"},{"id":10146,"position":11,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10147,"position":12,"text_uthmani":"ذِكْرِ","transliteration":"dhik''ri","translation_bn":"স্মরণের","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":10148,"position":13,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10149,"position":14,"text_uthmani":"وَذَرُوا۟","transliteration":"wadharū","translation_bn":"ও ত্যাগ করো","root":"وذر","lemma":"يَذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10150,"position":15,"text_uthmani":"ٱلْبَيْعَ ۚ","transliteration":"l-bayʿa","translation_bn":"কেনাবেচা","root":"بيع","lemma":"بَيْع","grammar_bn":"শব্দ"},{"id":10152,"position":16,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10153,"position":17,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":10154,"position":18,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":10155,"position":19,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":10156,"position":20,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10157,"position":21,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10158,"position":22,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū idhā nūdiya lilṣṣalati min yawmi l-jumuʿati fa-is''ʿaw ilā dhik''ri l-lahi wadharū l-bayʿa dhālikum khayrun lakum in kuntum taʿlamūna', 'হে মু’মিনগণ! জুমু‘আহর দিনে যখন নামাযের জন্য ডাকা হয়, তখন আল্লাহর স্মরণের দিকে শীঘ্র ধাবিত হও, ক্রয়-বিক্রয় পরিত্যাগ কর, এটাই তোমাদের জন্য অতি উত্তম, যদি তোমরা জানতে!', 'O you who have believed, when [the adhan] is called for the prayer on the day of Jumu''ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.', 'হে মু’মিনগণ! জুমু‘আহর দিনে যখন নামাযের জন্য ডাকা হয়, তখন আল্লাহর স্মরণের দিকে শীঘ্র ধাবিত হও, ক্রয়-বিক্রয় পরিত্যাগ কর, এটাই তোমাদের জন্য অতি উত্তম, যদি তোমরা জানতে!', 'O you who have believed, when [the adhan] is called for the prayer on the day of Jumu''ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062009.mp3', now()),
  (62, 10, '', '[{"id":11381,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":11382,"position":2,"text_uthmani":"قُضِيَتِ","transliteration":"quḍiyati","translation_bn":"সমাপ্ত হয়","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":11383,"position":3,"text_uthmani":"ٱلصَّلَوٰةُ","transliteration":"l-ṣalatu","translation_bn":"নামাজ","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":11384,"position":4,"text_uthmani":"فَٱنتَشِرُوا۟","transliteration":"fa-intashirū","translation_bn":"তখন তোমরা ছড়িয়ে পড়ো","root":"نشر","lemma":"تَنتَشِرُ","grammar_bn":"ফলাফল পদ (Result)"},{"id":11385,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11386,"position":6,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":11387,"position":7,"text_uthmani":"وَٱبْتَغُوا۟","transliteration":"wa-ib''taghū","translation_bn":"ও তোমরা সন্ধান করো","root":"بغي","lemma":"ٱبْتَغَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11388,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11389,"position":9,"text_uthmani":"فَضْلِ","transliteration":"faḍli","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11390,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11391,"position":11,"text_uthmani":"وَٱذْكُرُوا۟","transliteration":"wa-udh''kurū","translation_bn":"এবং তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11392,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11393,"position":13,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অধিক","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":11394,"position":14,"text_uthmani":"لَّعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"সম্ভবতঃ","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11395,"position":15,"text_uthmani":"تُفْلِحُونَ","transliteration":"tuf''liḥūna","translation_bn":"তোমরা সফল হবে","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11396,"position":16,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā quḍiyati l-ṣalatu fa-intashirū fī l-arḍi wa-ib''taghū min faḍli l-lahi wa-udh''kurū l-laha kathīran laʿallakum tuf''liḥūna', 'অতঃপর যখন নামায সমাপ্ত হয়, তখন যমীনে ছড়িয়ে পড়, আর আল্লাহর অনুগ্রহ সন্ধান কর এবং আল্লাহকে বেশি বেশি স্মরণ করতে থাক- যাতে তোমরা সাফল্য লাভ করতে পার।', 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed.', 'অতঃপর যখন নামায সমাপ্ত হয়, তখন যমীনে ছড়িয়ে পড়, আর আল্লাহর অনুগ্রহ সন্ধান কর এবং আল্লাহকে বেশি বেশি স্মরণ করতে থাক- যাতে তোমরা সাফল্য লাভ করতে পার।', 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062010.mp3', now()),
  (62, 11, '', '[{"id":12677,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12678,"position":2,"text_uthmani":"رَأَوْا۟","transliteration":"ra-aw","translation_bn":"তারা দেখল","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":12679,"position":3,"text_uthmani":"تِجَـٰرَةً","transliteration":"tijāratan","translation_bn":"ব্যবসা","root":"تجر","lemma":"تِجَٰرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12680,"position":4,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12681,"position":5,"text_uthmani":"لَهْوًا","transliteration":"lahwan","translation_bn":"খেলা-তামাশা","root":"لهو","lemma":"لَهْو","grammar_bn":"বিশেষ্য (Noun)"},{"id":12682,"position":6,"text_uthmani":"ٱنفَضُّوٓا۟","transliteration":"infaḍḍū","translation_bn":"তারা ছুটে গেল","root":"فضض","lemma":"ٱنفَضُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12683,"position":7,"text_uthmani":"إِلَيْهَا","transliteration":"ilayhā","translation_bn":"তার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12684,"position":8,"text_uthmani":"وَتَرَكُوكَ","transliteration":"watarakūka","translation_bn":"ও তোমাকে ছেড়ে গেল","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12685,"position":9,"text_uthmani":"قَآئِمًۭا ۚ","transliteration":"qāiman","translation_bn":"দাঁড়ানো অবস্থায়","root":"قوم","lemma":"قَا^ئِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":12687,"position":10,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12688,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"যা কিছুু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12689,"position":12,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":12690,"position":13,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12691,"position":14,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12692,"position":15,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অপেক্ষা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12693,"position":16,"text_uthmani":"ٱللَّهْوِ","transliteration":"l-lahwi","translation_bn":"খেলা-তামাশা","root":"لهو","lemma":"لَهْو","grammar_bn":"শব্দ"},{"id":12694,"position":17,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"ও থেকে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12695,"position":18,"text_uthmani":"ٱلتِّجَـٰرَةِ ۚ","transliteration":"l-tijārati","translation_bn":"ব্যবসা","root":"تجر","lemma":"تِجَٰرَة","grammar_bn":"শব্দ"},{"id":12697,"position":19,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12698,"position":20,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12699,"position":21,"text_uthmani":"ٱلرَّٰزِقِينَ","transliteration":"l-rāziqīna","translation_bn":"রিযিকদাতাদের\"","root":"رزق","lemma":"رَّٰزِقِين","grammar_bn":"শব্দ"},{"id":12700,"position":22,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ra-aw tijāratan aw lahwan infaḍḍū ilayhā watarakūka qāiman qul mā ʿinda l-lahi khayrun mina l-lahwi wamina l-tijārati wal-lahu khayru l-rāziqīna', 'তারা যখন ব্যবসায় অথবা ক্রীড়া কৌতুক দেখে তখন তারা সেদিকে ছুটে যায় আর তোমাকে রেখে যায় দাঁড়ানো অবস্থায়। বল- ‘আল্লাহর কাছে যা আছে তা ক্রীড়া-কৌতুক ও ব্যবসার চেয়ে উত্তম।’ আর আল্লাহ সর্বাপেক্ষা উত্তম রিযকদাতা।', 'But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, "What is with Allah is better than diversion and than a transaction, and Allah is the best of providers."', 'তারা যখন ব্যবসায় অথবা ক্রীড়া কৌতুক দেখে তখন তারা সেদিকে ছুটে যায় আর তোমাকে রেখে যায় দাঁড়ানো অবস্থায়। বল- ‘আল্লাহর কাছে যা আছে তা ক্রীড়া-কৌতুক ও ব্যবসার চেয়ে উত্তম।’ আর আল্লাহ সর্বাপেক্ষা উত্তম রিযকদাতা।', 'But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, "What is with Allah is better than diversion and than a transaction, and Allah is the best of providers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/062011.mp3', now())
