  (63, 1, '', '[{"id":469,"position":1,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":470,"position":2,"text_uthmani":"جَآءَكَ","transliteration":"jāaka","translation_bn":"তোমার  কাছে আসে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":471,"position":3,"text_uthmani":"ٱلْمُنَـٰفِقُونَ","transliteration":"l-munāfiqūna","translation_bn":"মুনাফিকরা","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":472,"position":4,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":473,"position":5,"text_uthmani":"نَشْهَدُ","transliteration":"nashhadu","translation_bn":"\"আমরা সাক্ষ্য দিচ্ছি","root":"شهد","lemma":"شَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":474,"position":6,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"আপনি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":475,"position":7,"text_uthmani":"لَرَسُولُ","transliteration":"larasūlu","translation_bn":"অবশ্যই রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":476,"position":8,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহর\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":478,"position":9,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":479,"position":10,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":480,"position":11,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"তুমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":481,"position":12,"text_uthmani":"لَرَسُولُهُۥ","transliteration":"larasūluhu","translation_bn":"অবশ্যই তাঁর রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":482,"position":13,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":483,"position":14,"text_uthmani":"يَشْهَدُ","transliteration":"yashhadu","translation_bn":"সাক্ষ্য দিচ্ছেন","root":"شهد","lemma":"شَهِدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":484,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":485,"position":16,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফিকরা","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":486,"position":17,"text_uthmani":"لَكَـٰذِبُونَ","transliteration":"lakādhibūna","translation_bn":"অবশ্যই মিথ্যাবাদী","root":"كذب","lemma":"كَٰذِب","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":487,"position":18,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'idhā jāaka l-munāfiqūna qālū nashhadu innaka larasūlu l-lahi wal-lahu yaʿlamu innaka larasūluhu wal-lahu yashhadu inna l-munāfiqīna lakādhibūna', 'মুনাফিকরা যখন তোমার কাছে আসে তখন তারা বলে- ‘আমরা সাক্ষ্য দিচ্ছি যে, আপনি অবশ্যই আল্লাহর রসূল।’ আল্লাহ জানেন, অবশ্যই তুমি তাঁর রসূল আর আল্লাহ সাক্ষ্য দিচ্ছেন যে, মুনাফিকরা অবশ্যই মিথ্যেবাদী।', 'When the hypocrites come to you, [O Muhammad], they say, "We testify that you are the Messenger of Allah." And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars.', 'মুনাফিকরা যখন তোমার কাছে আসে তখন তারা বলে- ‘আমরা সাক্ষ্য দিচ্ছি যে, আপনি অবশ্যই আল্লাহর রসূল।’ আল্লাহ জানেন, অবশ্যই তুমি তাঁর রসূল আর আল্লাহ সাক্ষ্য দিচ্ছেন যে, মুনাফিকরা অবশ্যই মিথ্যেবাদী।', 'When the hypocrites come to you, [O Muhammad], they say, "We testify that you are the Messenger of Allah." And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063001.mp3', now()),
  (63, 2, '', '[{"id":1365,"position":1,"text_uthmani":"ٱتَّخَذُوٓا۟","transliteration":"ittakhadhū","translation_bn":"তারা গ্রহণ করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1366,"position":2,"text_uthmani":"أَيْمَـٰنَهُمْ","transliteration":"aymānahum","translation_bn":"তাদের শপথগুলোকে","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":1367,"position":3,"text_uthmani":"جُنَّةًۭ","transliteration":"junnatan","translation_bn":"ঢাল (স্বরূপ)","root":"جنن","lemma":"جُنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1368,"position":4,"text_uthmani":"فَصَدُّوا۟","transliteration":"faṣaddū","translation_bn":"অতঃপর তারা বাধা সৃষ্টি করে","root":"صدد","lemma":"صَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1369,"position":5,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1370,"position":6,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1371,"position":7,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1373,"position":8,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1374,"position":9,"text_uthmani":"سَآءَ","transliteration":"sāa","translation_bn":"কত মন্দ","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1375,"position":10,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1376,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"(ছিল)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1377,"position":12,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা করছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1378,"position":13,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'ittakhadhū aymānahum junnatan faṣaddū ʿan sabīli l-lahi innahum sāa mā kānū yaʿmalūna', 'তারা তাদের শপথগুলোকে ঢাল হিসেবে ব্যবহার করে আর এ উপায়ে তারা মানুষকে আল্লাহর পথ থেকে নিবৃত্ত করে। তারা যা করে তা কতই না মন্দ!', 'They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.', 'তারা তাদের শপথগুলোকে ঢাল হিসেবে ব্যবহার করে আর এ উপায়ে তারা মানুষকে আল্লাহর পথ থেকে নিবৃত্ত করে। তারা যা করে তা কতই না মন্দ!', 'They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063002.mp3', now()),
  (63, 3, '', '[{"id":2426,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2427,"position":2,"text_uthmani":"بِأَنَّهُمْ","transliteration":"bi-annahum","translation_bn":"এ কারণে যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2428,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2429,"position":4,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"আবার তোমাদের মধ্যে","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2430,"position":5,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"কুফুরি করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2431,"position":6,"text_uthmani":"فَطُبِعَ","transliteration":"faṭubiʿa","translation_bn":"অতঃপর মোহর করা হয়েছে","root":"طبع","lemma":"طَبَعَ","grammar_bn":"কারণবাচক (Cause)"},{"id":2432,"position":7,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2433,"position":8,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"তাদের অন্তরসমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":2434,"position":9,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"অতঃপর তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2435,"position":10,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2436,"position":11,"text_uthmani":"يَفْقَهُونَ","transliteration":"yafqahūna","translation_bn":"তারা বুঝে","root":"فقه","lemma":"يَفْقَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2437,"position":12,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika bi-annahum āmanū thumma kafarū faṭubiʿa ʿalā qulūbihim fahum lā yafqahūna', 'তার কারণ এই যে, তারা ঈমান আনে, অতঃপর কুফুরী করে। এজন্য তাদের অন্তরে মোহর লাগিয়ে দেয়া হয়েছে। যার ফলে তারা কিছুই বুঝে না', 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.', 'তার কারণ এই যে, তারা ঈমান আনে, অতঃপর কুফুরী করে। এজন্য তাদের অন্তরে মোহর লাগিয়ে দেয়া হয়েছে। যার ফলে তারা কিছুই বুঝে না', 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063003.mp3', now()),
  (63, 4, '', '[{"id":3822,"position":1,"text_uthmani":"۞ وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3823,"position":2,"text_uthmani":"رَأَيْتَهُمْ","transliteration":"ra-aytahum","translation_bn":"তাদের তুমি দেখ","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":3824,"position":3,"text_uthmani":"تُعْجِبُكَ","transliteration":"tuʿ''jibuka","translation_bn":"তোমার প্রীতিকর মনে হয়","root":"عجب","lemma":"أَعْجَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3825,"position":4,"text_uthmani":"أَجْسَامُهُمْ ۖ","transliteration":"ajsāmuhum","translation_bn":"তাদের দেহগুলো","root":"جسم","lemma":"جِسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3827,"position":5,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3828,"position":6,"text_uthmani":"يَقُولُوا۟","transliteration":"yaqūlū","translation_bn":"তারা কথা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3829,"position":7,"text_uthmani":"تَسْمَعْ","transliteration":"tasmaʿ","translation_bn":"তুমি শুনবে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3830,"position":8,"text_uthmani":"لِقَوْلِهِمْ ۖ","transliteration":"liqawlihim","translation_bn":"তাদের কথাকে","root":"قول","lemma":"قَوْل","grammar_bn":"অব্যয় (Preposition)"},{"id":3832,"position":9,"text_uthmani":"كَأَنَّهُمْ","transliteration":"ka-annahum","translation_bn":"তারা যেন (আসলে)","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3833,"position":10,"text_uthmani":"خُشُبٌۭ","transliteration":"khushubun","translation_bn":"কাষ্ঠখণ্ডসমূহ","root":"خشب","lemma":"خُشُب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3834,"position":11,"text_uthmani":"مُّسَنَّدَةٌۭ ۖ","transliteration":"musannadatun","translation_bn":"ঠেকান দেয়া","root":"سند","lemma":"مُّسَنَّدَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":3836,"position":12,"text_uthmani":"يَحْسَبُونَ","transliteration":"yaḥsabūna","translation_bn":"তারা মনে করে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3837,"position":13,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3838,"position":14,"text_uthmani":"صَيْحَةٍ","transliteration":"ṣayḥatin","translation_bn":"উঁচু আওয়াজ","root":"صيح","lemma":"صَيْحَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3839,"position":15,"text_uthmani":"عَلَيْهِمْ ۚ","transliteration":"ʿalayhim","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3841,"position":16,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3842,"position":17,"text_uthmani":"ٱلْعَدُوُّ","transliteration":"l-ʿaduwu","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"শব্দ"},{"id":3843,"position":18,"text_uthmani":"فَٱحْذَرْهُمْ ۚ","transliteration":"fa-iḥ''dharhum","translation_bn":"অতএব সতর্ক হও তাদের (থেকে)","root":"حذر","lemma":"يَحْذَرُ","grammar_bn":"শব্দ"},{"id":3845,"position":19,"text_uthmani":"قَـٰتَلَهُمُ","transliteration":"qātalahumu","translation_bn":"তাদের উপর মার","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3846,"position":20,"text_uthmani":"ٱللَّهُ ۖ","transliteration":"l-lahu","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3848,"position":21,"text_uthmani":"أَنَّىٰ","transliteration":"annā","translation_bn":"কোথায়","root":"اني\r","lemma":"أَنَّىٰ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":3849,"position":22,"text_uthmani":"يُؤْفَكُونَ","transliteration":"yu''fakūna","translation_bn":"তাদের ফিরিয়ে নেয়া হচ্ছে","root":"افك","lemma":"أُفِكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3850,"position":23,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ra-aytahum tuʿ''jibuka ajsāmuhum wa-in yaqūlū tasmaʿ liqawlihim ka-annahum khushubun musannadatun yaḥsabūna kulla ṣayḥatin ʿalayhim humu l-ʿaduwu fa-iḥ''dharhum qātalahumu l-lahu annā yu''fakūna', 'তুমি যখন তাদের দিকে তাকাও তখন তাদের শারীরিক গঠন তোমাকে চমৎকৃত করে। আর যখন তারা কথা বলে তখন তুমি তাদের কথা আগ্রহ ভরে শুন, অথচ তারা দেয়ালে ঠেস দেয়া কাঠের মত (দেখন- সুরত, কিন্ত কার্যক্ষেত্রে কিছুই না)। কোন শোরগোল হলেই তারা সেটাকে নিজেদের বিরুদ্ধে মনে করে (কারণ তাদের অপরাধী মন সব সময়ে শঙ্কিত থাকে- এই বুঝি তাদের কুকীর্তি ফাঁস হয়ে গেল)। এরাই শত্রু, কাজেই তাদের ব্যাপারে সতর্ক থাক। এদের উপর আছে আল্লাহর গযব, তাদেরকে কীভাবে (সত্য পথ থেকে) ফিরিয়ে নেয়া হচ্ছে!', 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?', 'তুমি যখন তাদের দিকে তাকাও তখন তাদের শারীরিক গঠন তোমাকে চমৎকৃত করে। আর যখন তারা কথা বলে তখন তুমি তাদের কথা আগ্রহ ভরে শুন, অথচ তারা দেয়ালে ঠেস দেয়া কাঠের মত (দেখন- সুরত, কিন্ত কার্যক্ষেত্রে কিছুই না)। কোন শোরগোল হলেই তারা সেটাকে নিজেদের বিরুদ্ধে মনে করে (কারণ তাদের অপরাধী মন সব সময়ে শঙ্কিত থাকে- এই বুঝি তাদের কুকীর্তি ফাঁস হয়ে গেল)। এরাই শত্রু, কাজেই তাদের ব্যাপারে সতর্ক থাক। এদের উপর আছে আল্লাহর গযব, তাদেরকে কীভাবে (সত্য পথ থেকে) ফিরিয়ে নেয়া হচ্ছে!', 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063004.mp3', now()),
  (63, 5, '', '[{"id":5096,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5097,"position":2,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হয়","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5098,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5099,"position":4,"text_uthmani":"تَعَالَوْا۟","transliteration":"taʿālaw","translation_bn":"\"তোমরা আসো","root":"علو","lemma":"تَعَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5100,"position":5,"text_uthmani":"يَسْتَغْفِرْ","transliteration":"yastaghfir","translation_bn":"ক্ষমা প্রার্থনা করবেন","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5101,"position":6,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5102,"position":7,"text_uthmani":"رَسُولُ","transliteration":"rasūlu","translation_bn":"রাসূূল\"","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":5103,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5104,"position":9,"text_uthmani":"لَوَّوْا۟","transliteration":"lawwaw","translation_bn":"তারা ফিরিয়ে নেয়","root":"لوي","lemma":"لَوَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5105,"position":10,"text_uthmani":"رُءُوسَهُمْ","transliteration":"ruūsahum","translation_bn":"তাদের মাথাগুলো","root":"راس","lemma":"رَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":5106,"position":11,"text_uthmani":"وَرَأَيْتَهُمْ","transliteration":"wara-aytahum","translation_bn":"এবং তুমি তাদের দেখো","root":"راي","lemma":"رَءَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5107,"position":12,"text_uthmani":"يَصُدُّونَ","transliteration":"yaṣuddūna","translation_bn":"বিরত থাকে (আসা থেকে)","root":"صدد","lemma":"صَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5108,"position":13,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"এবং তারা","root":"—","lemma":"وَهُم","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":5109,"position":14,"text_uthmani":"مُّسْتَكْبِرُونَ","transliteration":"mus''takbirūna","translation_bn":"অহংকারী","root":"كبر","lemma":"مُسْتَكْبِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":5110,"position":15,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā qīla lahum taʿālaw yastaghfir lakum rasūlu l-lahi lawwaw ruūsahum wara-aytahum yaṣuddūna wahum mus''takbirūna', 'তাদেরকে যখন বলা হয়, ‘এসো, আল্লাহর রসূল তোমাদের জন্য ক্ষমা প্রার্থনা করবেন, তখন তারা মাথা নেড়ে অস্বীকৃতি জানায়, তখন তুমি দেখতে পাও তারা সদম্ভে তাদের মুখ ফিরিয়ে নেয়।', 'And when it is said to them, "Come, the Messenger of Allah will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.', 'তাদেরকে যখন বলা হয়, ‘এসো, আল্লাহর রসূল তোমাদের জন্য ক্ষমা প্রার্থনা করবেন, তখন তারা মাথা নেড়ে অস্বীকৃতি জানায়, তখন তুমি দেখতে পাও তারা সদম্ভে তাদের মুখ ফিরিয়ে নেয়।', 'And when it is said to them, "Come, the Messenger of Allah will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063005.mp3', now()),
  (63, 6, '', '[{"id":6353,"position":1,"text_uthmani":"سَوَآءٌ","transliteration":"sawāon","translation_bn":"সমান","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":6354,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6355,"position":3,"text_uthmani":"أَسْتَغْفَرْتَ","transliteration":"astaghfarta","translation_bn":"তুমি ক্ষমা প্রার্থনা কর","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"সমতাবাচক (Equalization)"},{"id":6356,"position":4,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্য","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6357,"position":5,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6358,"position":6,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"প্রার্থনা নাই করো","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":6359,"position":7,"text_uthmani":"تَسْتَغْفِرْ","transliteration":"tastaghfir","translation_bn":"তুমি ক্ষমা","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6360,"position":8,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6361,"position":9,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কক্ষনো না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":6362,"position":10,"text_uthmani":"يَغْفِرَ","transliteration":"yaghfira","translation_bn":"ক্ষমা করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6363,"position":11,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6364,"position":12,"text_uthmani":"لَهُمْ ۚ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":6366,"position":13,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6367,"position":14,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6368,"position":15,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6369,"position":16,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":6370,"position":17,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"লোকদের","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":6371,"position":18,"text_uthmani":"ٱلْفَـٰسِقِينَ","transliteration":"l-fāsiqīna","translation_bn":"ফাসেক","root":"فسق","lemma":"فَاسِق","grammar_bn":"শব্দ"},{"id":6372,"position":19,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'sawāon ʿalayhim astaghfarta lahum am lam tastaghfir lahum lan yaghfira l-lahu lahum inna l-laha lā yahdī l-qawma l-fāsiqīna', 'তুমি তাদের জন্য ক্ষমা প্রার্থনা কর আর না কর, উভয়ই তাদের জন্য সমান। আল্লাহ তাদেরকে কক্ষনো ক্ষমা করবেন না। আল্লাহ পাপাচারী জাতিকে কক্ষনো সঠিক পথে পরিচালিত করেন না।', 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people.', 'তুমি তাদের জন্য ক্ষমা প্রার্থনা কর আর না কর, উভয়ই তাদের জন্য সমান। আল্লাহ তাদেরকে কক্ষনো ক্ষমা করবেন না। আল্লাহ পাপাচারী জাতিকে কক্ষনো সঠিক পথে পরিচালিত করেন না।', 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063006.mp3', now()),
  (63, 7, '', '[{"id":7769,"position":1,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারা (ঐ লোক)","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":7770,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7771,"position":3,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7772,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"\"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":7773,"position":5,"text_uthmani":"تُنفِقُوا۟","transliteration":"tunfiqū","translation_bn":"তোমরা খরচ করো","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7774,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"(তাদের) জন্য","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7775,"position":7,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যারা (আছে)","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7776,"position":8,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":7777,"position":9,"text_uthmani":"رَسُولِ","transliteration":"rasūli","translation_bn":"রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":7778,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7779,"position":11,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7780,"position":12,"text_uthmani":"يَنفَضُّوا۟ ۗ","transliteration":"yanfaḍḍū","translation_bn":"তারা ছিন্নভিন্ন হয়ে যায়\"","root":"فضض","lemma":"ٱنفَضُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7782,"position":13,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"অথচ আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":7783,"position":14,"text_uthmani":"خَزَآئِنُ","transliteration":"khazāinu","translation_bn":"ধনভাণ্ডারসমূহ","root":"خزن","lemma":"خَزَا^ئِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":7784,"position":15,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আসমানসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":7785,"position":16,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও যমীনের","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7786,"position":17,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"শব্দ"},{"id":7787,"position":18,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফিকরা","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":7788,"position":19,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7789,"position":20,"text_uthmani":"يَفْقَهُونَ","transliteration":"yafqahūna","translation_bn":"তারা বুঝে","root":"فقه","lemma":"يَفْقَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7790,"position":21,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'humu alladhīna yaqūlūna lā tunfiqū ʿalā man ʿinda rasūli l-lahi ḥattā yanfaḍḍū walillahi khazāinu l-samāwāti wal-arḍi walākinna l-munāfiqīna lā yafqahūna', 'তারা বলে- ‘রসূলের সঙ্গী সাথীদের জন্য অর্থ ব্যয় করো না, শেষে তারা এমনিতেই সরে পড়বে।’ আসমান ও যমীনের ধন ভান্ডার তো আল্লাহরই, কিন্তু মুনাফিকরা তা বুঝে না।', 'They are the ones who say, "Do not spend on those who are with the Messenger of Allah until they disband." And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand.', 'তারা বলে- ‘রসূলের সঙ্গী সাথীদের জন্য অর্থ ব্যয় করো না, শেষে তারা এমনিতেই সরে পড়বে।’ আসমান ও যমীনের ধন ভান্ডার তো আল্লাহরই, কিন্তু মুনাফিকরা তা বুঝে না।', 'They are the ones who say, "Do not spend on those who are with the Messenger of Allah until they disband." And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063007.mp3', now()),
  (63, 8, '', '[{"id":8940,"position":1,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8941,"position":2,"text_uthmani":"لَئِن","transliteration":"la-in","translation_bn":"\"অবশ্যই যদি","root":"—","lemma":"إِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8942,"position":3,"text_uthmani":"رَّجَعْنَآ","transliteration":"rajaʿnā","translation_bn":"আমরা ফিরে যেতে পারি","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8943,"position":4,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8944,"position":5,"text_uthmani":"ٱلْمَدِينَةِ","transliteration":"l-madīnati","translation_bn":"মদীনার","root":"مدن","lemma":"مَدِينَة","grammar_bn":"শব্দ"},{"id":8945,"position":6,"text_uthmani":"لَيُخْرِجَنَّ","transliteration":"layukh''rijanna","translation_bn":"বহিস্কার করবেই","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8946,"position":7,"text_uthmani":"ٱلْأَعَزُّ","transliteration":"l-aʿazu","translation_bn":"অধিক সম্মানিত","root":"عزز","lemma":"أَعَزّ","grammar_bn":"শব্দ"},{"id":8947,"position":8,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8948,"position":9,"text_uthmani":"ٱلْأَذَلَّ ۚ","transliteration":"l-adhala","translation_bn":"হীনতরকে\"","root":"ذلل","lemma":"أَذَلّ","grammar_bn":"শব্দ"},{"id":8950,"position":10,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"অথচ আল্লাহরই জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":8951,"position":11,"text_uthmani":"ٱلْعِزَّةُ","transliteration":"l-ʿizatu","translation_bn":"সম্মান","root":"عزز","lemma":"عِزَّة","grammar_bn":"শব্দ"},{"id":8952,"position":12,"text_uthmani":"وَلِرَسُولِهِۦ","transliteration":"walirasūlihi","translation_bn":"ও তাঁর রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8953,"position":13,"text_uthmani":"وَلِلْمُؤْمِنِينَ","transliteration":"walil''mu''minīna","translation_bn":"ও মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8954,"position":14,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"শব্দ"},{"id":8955,"position":15,"text_uthmani":"ٱلْمُنَـٰفِقِينَ","transliteration":"l-munāfiqīna","translation_bn":"মুনাফিকরা","root":"نفق","lemma":"مُنَٰفِقُون","grammar_bn":"শব্দ"},{"id":8956,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8957,"position":17,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8958,"position":18,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'yaqūlūna la-in rajaʿnā ilā l-madīnati layukh''rijanna l-aʿazu min''hā l-adhala walillahi l-ʿizatu walirasūlihi walil''mu''minīna walākinna l-munāfiqīna lā yaʿlamūna', 'তারা বলে- ‘আমরা যদি মাদীনায় প্রত্যাবর্তন করি, তাহলে সম্মানীরা অবশ্য অবশ্যই হীনদেরকে সেখানে থেকে বহিষ্কার করবে।’ কিন্তু সমস্ত মান মর্যাদা তো আল্লাহর, তাঁর রসূলের এবং মু’মিনদের; কিন্তু মুনাফিকরা তা জানে না।', 'They say, "If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble." And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.', 'তারা বলে- ‘আমরা যদি মাদীনায় প্রত্যাবর্তন করি, তাহলে সম্মানীরা অবশ্য অবশ্যই হীনদেরকে সেখানে থেকে বহিষ্কার করবে।’ কিন্তু সমস্ত মান মর্যাদা তো আল্লাহর, তাঁর রসূলের এবং মু’মিনদের; কিন্তু মুনাফিকরা তা জানে না।', 'They say, "If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble." And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063008.mp3', now()),
  (63, 9, '', '[{"id":10163,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":10164,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10165,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10166,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":10167,"position":5,"text_uthmani":"تُلْهِكُمْ","transliteration":"tul''hikum","translation_bn":"তোমাদের (যেন) গাফিল করে","root":"لهو","lemma":"أَلْهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10168,"position":6,"text_uthmani":"أَمْوَٰلُكُمْ","transliteration":"amwālukum","translation_bn":"তোমাদের সম্পদগুলো","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":10169,"position":7,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"ও না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10170,"position":8,"text_uthmani":"أَوْلَـٰدُكُمْ","transliteration":"awlādukum","translation_bn":"তোমাদের সন্তানরা","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10171,"position":9,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10172,"position":10,"text_uthmani":"ذِكْرِ","transliteration":"dhik''ri","translation_bn":"স্মরণ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":10173,"position":11,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10175,"position":12,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":10176,"position":13,"text_uthmani":"يَفْعَلْ","transliteration":"yafʿal","translation_bn":"করবে","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10177,"position":14,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10178,"position":15,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"অতঃপর ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"ফলাফল পদ (Result)"},{"id":10179,"position":16,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10180,"position":17,"text_uthmani":"ٱلْخَـٰسِرُونَ","transliteration":"l-khāsirūna","translation_bn":"ক্ষতিগ্রস্ত","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"শব্দ"},{"id":10181,"position":18,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū lā tul''hikum amwālukum walā awlādukum ʿan dhik''ri l-lahi waman yafʿal dhālika fa-ulāika humu l-khāsirūna', 'হে মু’মিনগণ! তোমাদের ধন-সম্পদ আর তোমাদের সন্তানাদি তোমাদেরকে যেন আল্লাহর স্মরণ হতে গাফিল করে না দেয়। যারা এমন করবে তারাই ক্ষতিগ্রস্ত।', 'O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers.', 'হে মু’মিনগণ! তোমাদের ধন-সম্পদ আর তোমাদের সন্তানাদি তোমাদেরকে যেন আল্লাহর স্মরণ হতে গাফিল করে না দেয়। যারা এমন করবে তারাই ক্ষতিগ্রস্ত।', 'O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063009.mp3', now()),
  (63, 10, '', '[{"id":11404,"position":1,"text_uthmani":"وَأَنفِقُوا۟","transliteration":"wa-anfiqū","translation_bn":"এবং তোমরা খরচ করো","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"শব্দ"},{"id":11405,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11406,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"তা (যা)","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11407,"position":4,"text_uthmani":"رَزَقْنَـٰكُم","transliteration":"razaqnākum","translation_bn":"তোমাদের আমরা রিজিক দিয়েছি","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11408,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11409,"position":6,"text_uthmani":"قَبْلِ","transliteration":"qabli","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11410,"position":7,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":11411,"position":8,"text_uthmani":"يَأْتِىَ","transliteration":"yatiya","translation_bn":"আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":11412,"position":9,"text_uthmani":"أَحَدَكُمُ","transliteration":"aḥadakumu","translation_bn":"তোমাদের কারও","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11413,"position":10,"text_uthmani":"ٱلْمَوْتُ","transliteration":"l-mawtu","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":11414,"position":11,"text_uthmani":"فَيَقُولَ","transliteration":"fayaqūla","translation_bn":"অতঃপর সে বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11415,"position":12,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11416,"position":13,"text_uthmani":"لَوْلَآ","transliteration":"lawlā","translation_bn":"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":11417,"position":14,"text_uthmani":"أَخَّرْتَنِىٓ","transliteration":"akhartanī","translation_bn":"তুমি আমাকে অবকাশ দিলে","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11418,"position":15,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11419,"position":16,"text_uthmani":"أَجَلٍۢ","transliteration":"ajalin","translation_bn":"কাল","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11420,"position":17,"text_uthmani":"قَرِيبٍۢ","transliteration":"qarībin","translation_bn":"কিছু","root":"قرب","lemma":"قَرِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":11421,"position":18,"text_uthmani":"فَأَصَّدَّقَ","transliteration":"fa-aṣṣaddaqa","translation_bn":"আমি তা হলে সদকা করতাম","root":"صدق","lemma":"تَصَدَّقَ","grammar_bn":"কারণবাচক (Cause)"},{"id":11422,"position":19,"text_uthmani":"وَأَكُن","transliteration":"wa-akun","translation_bn":"এবং হতাম আমি","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11423,"position":20,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11424,"position":21,"text_uthmani":"ٱلصَّـٰلِحِينَ","transliteration":"l-ṣāliḥīna","translation_bn":"সৎকর্মশীলদের\"","root":"صلح","lemma":"صَٰلِح","grammar_bn":"শব্দ"},{"id":11425,"position":22,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-anfiqū min mā razaqnākum min qabli an yatiya aḥadakumu l-mawtu fayaqūla rabbi lawlā akhartanī ilā ajalin qarībin fa-aṣṣaddaqa wa-akun mina l-ṣāliḥīna', 'যে রিযক আমি তোমাদেরকে দিয়েছি তাত্থেকে (আল্লাহর পথে) ব্যয় কর তোমাদের কারো মৃত্যু আসার পূর্বে। নচেৎ (মৃত্যু এসে গেলে) সে বলবে, ‘হে আমার প্রতিপালক! তুমি আমাকে আরো কিছুকালের অবকাশ দিলে না কেন? তাহলে আমি সদাক্বাহ করতাম আর সৎকর্মশীলদের মধ্যে শামিল হয়ে যেতাম।’', 'And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous."', 'যে রিযক আমি তোমাদেরকে দিয়েছি তাত্থেকে (আল্লাহর পথে) ব্যয় কর তোমাদের কারো মৃত্যু আসার পূর্বে। নচেৎ (মৃত্যু এসে গেলে) সে বলবে, ‘হে আমার প্রতিপালক! তুমি আমাকে আরো কিছুকালের অবকাশ দিলে না কেন? তাহলে আমি সদাক্বাহ করতাম আর সৎকর্মশীলদের মধ্যে শামিল হয়ে যেতাম।’', 'And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063010.mp3', now()),
  (63, 11, '', '[{"id":12701,"position":1,"text_uthmani":"وَلَن","transliteration":"walan","translation_bn":"অথচ কক্ষনো না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":12702,"position":2,"text_uthmani":"يُؤَخِّرَ","transliteration":"yu-akhira","translation_bn":"অবকাশ দেন","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12703,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12704,"position":4,"text_uthmani":"نَفْسًا","transliteration":"nafsan","translation_bn":"কোন ব্যক্তিকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":12705,"position":5,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":12706,"position":6,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12707,"position":7,"text_uthmani":"أَجَلُهَا ۚ","transliteration":"ajaluhā","translation_bn":"তার নির্ধারিত মেয়াদ","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":12709,"position":8,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"আর আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":12710,"position":9,"text_uthmani":"خَبِيرٌۢ","transliteration":"khabīrun","translation_bn":"সবিশেষ অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":12711,"position":10,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12712,"position":11,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12713,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'walan yu-akhira l-lahu nafsan idhā jāa ajaluhā wal-lahu khabīrun bimā taʿmalūna', 'আল্লাহ কাউকে কক্ষনো অবকাশ দেন না যখন তার নির্ধারিত সময় এসে যায়। তোমরা যা কর সে সম্পর্কে আল্লাহ পুরোপুরি খবর রাখেন।', 'But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do.', 'আল্লাহ কাউকে কক্ষনো অবকাশ দেন না যখন তার নির্ধারিত সময় এসে যায়। তোমরা যা কর সে সম্পর্কে আল্লাহ পুরোপুরি খবর রাখেন।', 'But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/063011.mp3', now())
