  (64, 1, '', '[{"id":488,"position":1,"text_uthmani":"يُسَبِّحُ","transliteration":"yusabbiḥu","translation_bn":"মহিমা ঘোষণা করে","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":489,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহ্‌র জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":490,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":491,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":492,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আসমানসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":493,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":494,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":495,"position":8,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":497,"position":9,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"তাঁরই জন্যে","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":498,"position":10,"text_uthmani":"ٱلْمُلْكُ","transliteration":"l-mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":499,"position":11,"text_uthmani":"وَلَهُ","transliteration":"walahu","translation_bn":"ও তাঁর জন্যেই","root":"—","lemma":"وَلَهُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":500,"position":12,"text_uthmani":"ٱلْحَمْدُ ۖ","transliteration":"l-ḥamdu","translation_bn":"সব প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":502,"position":13,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"ও তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":503,"position":14,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":504,"position":15,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":505,"position":16,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":506,"position":17,"text_uthmani":"قَدِيرٌ","transliteration":"qadīrun","translation_bn":"ক্ষমতাবান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":507,"position":18,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yusabbiḥu lillahi mā fī l-samāwāti wamā fī l-arḍi lahu l-mul''ku walahu l-ḥamdu wahuwa ʿalā kulli shayin qadīrun', 'যা কিছু আসমানে আছে আর যা কিছু যমীনে আছে সবই আল্লাহর প্রশংসা ও মহিমা ঘোষণা করছে। রাজত্ব তাঁরই, প্রশংসা তাঁরই, আর তিনি সব কিছুর উপর ক্ষমতাবান।', 'Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.', 'যা কিছু আসমানে আছে আর যা কিছু যমীনে আছে সবই আল্লাহর প্রশংসা ও মহিমা ঘোষণা করছে। রাজত্ব তাঁরই, প্রশংসা তাঁরই, আর তিনি সব কিছুর উপর ক্ষমতাবান।', 'Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064001.mp3', now()),
  (64, 2, '', '[{"id":1379,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1380,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1381,"position":3,"text_uthmani":"خَلَقَكُمْ","transliteration":"khalaqakum","translation_bn":"তোমাদের সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1382,"position":4,"text_uthmani":"فَمِنكُمْ","transliteration":"faminkum","translation_bn":"অতঃপর তোমাদের  মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"শব্দ"},{"id":1383,"position":5,"text_uthmani":"كَافِرٌۭ","transliteration":"kāfirun","translation_bn":"(কেউ) কাফির","root":"كفر","lemma":"كَافِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1384,"position":6,"text_uthmani":"وَمِنكُم","transliteration":"waminkum","translation_bn":"আবার তোমাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1385,"position":7,"text_uthmani":"مُّؤْمِنٌۭ ۚ","transliteration":"mu''minun","translation_bn":"(কেউ) মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":1387,"position":8,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":1388,"position":9,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1389,"position":10,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ কর","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1390,"position":11,"text_uthmani":"بَصِيرٌ","transliteration":"baṣīrun","translation_bn":"সব দেখেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":1391,"position":12,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī khalaqakum faminkum kāfirun waminkum mu''minun wal-lahu bimā taʿmalūna baṣīrun', 'তিনিই তোমাদেরকে সৃষ্টি করেছেন, অতঃপর তোমাদের মধ্যে কেউ কাফির, কেউ মু’মিন; তোমরা যা কর আল্লাহ তা দেখেন।', 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing.', 'তিনিই তোমাদেরকে সৃষ্টি করেছেন, অতঃপর তোমাদের মধ্যে কেউ কাফির, কেউ মু’মিন; তোমরা যা কর আল্লাহ তা দেখেন।', 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064002.mp3', now()),
  (64, 3, '', '[{"id":2438,"position":1,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2439,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":2440,"position":3,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2441,"position":4,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"যথাযথভাবে","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2442,"position":5,"text_uthmani":"وَصَوَّرَكُمْ","transliteration":"waṣawwarakum","translation_bn":"ও তোমাদের আকৃতি দিয়েছেন","root":"صور","lemma":"صَوَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2443,"position":6,"text_uthmani":"فَأَحْسَنَ","transliteration":"fa-aḥsana","translation_bn":"অতঃপর অতি উত্তম  করেছেন","root":"حسن","lemma":"أَحْسَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2444,"position":7,"text_uthmani":"صُوَرَكُمْ ۖ","transliteration":"ṣuwarakum","translation_bn":"তোমাদের আকৃতি গুলো","root":"صور","lemma":"صُورَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2446,"position":8,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই নিকট","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"শব্দ"},{"id":2447,"position":9,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন স্থল","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":2448,"position":10,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'khalaqa l-samāwāti wal-arḍa bil-ḥaqi waṣawwarakum fa-aḥsana ṣuwarakum wa-ilayhi l-maṣīru', 'তিনি (বিশেষ উদ্দেশ্যে) সত্যিকারভাবে আসমান ও যমীন সৃষ্টি করেছেন, তিনি তোমাদেরকে আকৃতি দিয়েছেন, অতঃপর তোমাদের আকৃতি সুন্দর করেছেন আর (সব্বাইকে) ফিরে যেতে হবে তাঁরই দিকে।', 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.', 'তিনি (বিশেষ উদ্দেশ্যে) সত্যিকারভাবে আসমান ও যমীন সৃষ্টি করেছেন, তিনি তোমাদেরকে আকৃতি দিয়েছেন, অতঃপর তোমাদের আকৃতি সুন্দর করেছেন আর (সব্বাইকে) ফিরে যেতে হবে তাঁরই দিকে।', 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064003.mp3', now()),
  (64, 4, '', '[{"id":3851,"position":1,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3852,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3853,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3854,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশ জগতের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":3855,"position":5,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3856,"position":6,"text_uthmani":"وَيَعْلَمُ","transliteration":"wayaʿlamu","translation_bn":"ও তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3857,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3858,"position":8,"text_uthmani":"تُسِرُّونَ","transliteration":"tusirrūna","translation_bn":"তোমরা গোপন","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3859,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3860,"position":10,"text_uthmani":"تُعْلِنُونَ ۚ","transliteration":"tuʿ''linūna","translation_bn":"তোমরা প্রকাশ কর","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":3862,"position":11,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":3863,"position":12,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুব জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3864,"position":13,"text_uthmani":"بِذَاتِ","transliteration":"bidhāti","translation_bn":"অবস্থা সম্পর্কে","root":"—","lemma":"ذُو","grammar_bn":"অব্যয় (Preposition)"},{"id":3865,"position":14,"text_uthmani":"ٱلصُّدُورِ","transliteration":"l-ṣudūri","translation_bn":"অন্তরসমূহের","root":"صدر","lemma":"صَدْر","grammar_bn":"শব্দ"},{"id":3866,"position":15,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'yaʿlamu mā fī l-samāwāti wal-arḍi wayaʿlamu mā tusirrūna wamā tuʿ''linūna wal-lahu ʿalīmun bidhāti l-ṣudūri', 'তিনি জানেন যা কিছু আসমান ও যমীনে আছে, আর তিনি জানেন যা তোমরা গোপন কর আর প্রকাশ কর। অন্তরের বিষয়াদি সম্পর্কে তিনি পূর্ণরূপে অবগত।', 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts.', 'তিনি জানেন যা কিছু আসমান ও যমীনে আছে, আর তিনি জানেন যা তোমরা গোপন কর আর প্রকাশ কর। অন্তরের বিষয়াদি সম্পর্কে তিনি পূর্ণরূপে অবগত।', 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064004.mp3', now()),
  (64, 5, '', '[{"id":5111,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"নাই কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":5112,"position":2,"text_uthmani":"يَأْتِكُمْ","transliteration":"yatikum","translation_bn":"তোমাদের কাছে আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":5113,"position":3,"text_uthmani":"نَبَؤُا۟","transliteration":"naba-u","translation_bn":"খবর","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5114,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5115,"position":5,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"কুফরি করেছিল","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5116,"position":6,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5117,"position":7,"text_uthmani":"قَبْلُ","transliteration":"qablu","translation_bn":"ইতিপূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5118,"position":8,"text_uthmani":"فَذَاقُوا۟","transliteration":"fadhāqū","translation_bn":"অতঃপর তারা স্বাদ নিয়েছে","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"কারণবাচক (Cause)"},{"id":5119,"position":9,"text_uthmani":"وَبَالَ","transliteration":"wabāla","translation_bn":"কুফল","root":"وبل","lemma":"وَبَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":5120,"position":10,"text_uthmani":"أَمْرِهِمْ","transliteration":"amrihim","translation_bn":"তাদের কাজের","root":"امر","lemma":"أَمْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":5121,"position":11,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদের জন্যে","root":"—","lemma":"وَلَهُمْ","grammar_bn":"শব্দ"},{"id":5122,"position":12,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"আযাব","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5123,"position":13,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"যন্ত্রনাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":5124,"position":14,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'alam yatikum naba-u alladhīna kafarū min qablu fadhāqū wabāla amrihim walahum ʿadhābun alīmun', 'ইতোপূর্বে যারা কুফরী করেছিল তাদের খবর কি তোমার কাছে পৌঁছেছে? তারা তাদের মন্দ কর্মের ফল আস্বাদন করেছে, আর তাদের জন্য আছে মর্মান্তিক ‘আযাব।', 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.', 'ইতোপূর্বে যারা কুফরী করেছিল তাদের খবর কি তোমার কাছে পৌঁছেছে? তারা তাদের মন্দ কর্মের ফল আস্বাদন করেছে, আর তাদের জন্য আছে মর্মান্তিক ‘আযাব।', 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064005.mp3', now()),
  (64, 6, '', '[{"id":6373,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6374,"position":2,"text_uthmani":"بِأَنَّهُۥ","transliteration":"bi-annahu","translation_bn":"এ জন্যে যে","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6375,"position":3,"text_uthmani":"كَانَت","transliteration":"kānat","translation_bn":"(ছিল)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6376,"position":4,"text_uthmani":"تَّأْتِيهِمْ","transliteration":"tatīhim","translation_bn":"তাদের কাছে আসতো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":6377,"position":5,"text_uthmani":"رُسُلُهُم","transliteration":"rusuluhum","translation_bn":"তাদের রাসূলগণ","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":6378,"position":6,"text_uthmani":"بِٱلْبَيِّنَـٰتِ","transliteration":"bil-bayināti","translation_bn":"স্পষ্ট নিদর্শনাদিসহ","root":"بين","lemma":"بَيِّنَة","grammar_bn":"অব্যয় (Preposition)"},{"id":6379,"position":7,"text_uthmani":"فَقَالُوٓا۟","transliteration":"faqālū","translation_bn":"অতঃপর তারা বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6380,"position":8,"text_uthmani":"أَبَشَرٌۭ","transliteration":"abasharun","translation_bn":"\"মানুষই কি","root":"بشر","lemma":"بَشَر","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":6381,"position":9,"text_uthmani":"يَهْدُونَنَا","transliteration":"yahdūnanā","translation_bn":"আমাদেরকে পথ দেখাবে\"","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":6382,"position":10,"text_uthmani":"فَكَفَرُوا۟","transliteration":"fakafarū","translation_bn":"এভাবে তারা কুফরি  করল","root":"كفر","lemma":"كَفَرَ","grammar_bn":"কারণবাচক (Cause)"},{"id":6383,"position":11,"text_uthmani":"وَتَوَلَّوا۟ ۚ","transliteration":"watawallaw","translation_bn":"ও তারা মুখ ফিরালো","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6385,"position":12,"text_uthmani":"وَّٱسْتَغْنَى","transliteration":"wa-is''taghnā","translation_bn":"ও বেপরোয়া হলেন","root":"غني","lemma":"ٱسْتَغْنَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6386,"position":13,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6388,"position":14,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":6389,"position":15,"text_uthmani":"غَنِىٌّ","transliteration":"ghaniyyun","translation_bn":"পরোয়াহীন","root":"غني","lemma":"غَنِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6390,"position":16,"text_uthmani":"حَمِيدٌۭ","transliteration":"ḥamīdun","translation_bn":"সুপ্রশংসিত","root":"حمد","lemma":"حَمِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":6391,"position":17,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika bi-annahu kānat tatīhim rusuluhum bil-bayināti faqālū abasharun yahdūnanā fakafarū watawallaw wa-is''taghnā l-lahu wal-lahu ghaniyyun ḥamīdun', 'এর কারণ এই যে, তাদের কাছে তাদের রসূলগণ স্পষ্ট নিদর্শনসহ এসেছিল, তখন তারা বলেছিল, ‘(আমাদের মতই) মানুষ কি আমাদেরকে সঠিক পথ দেখাবে?’ কাজেই তারা অস্বীকার করল আর মুখ ফিরিয়ে নিল। তখন আল্লাহও তাদের ব্যাপারে বেপরোয়া হয়ে গেলেন, আল্লাহ অমুখাপেক্ষী, প্রশংসিত।', 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy.', 'এর কারণ এই যে, তাদের কাছে তাদের রসূলগণ স্পষ্ট নিদর্শনসহ এসেছিল, তখন তারা বলেছিল, ‘(আমাদের মতই) মানুষ কি আমাদেরকে সঠিক পথ দেখাবে?’ কাজেই তারা অস্বীকার করল আর মুখ ফিরিয়ে নিল। তখন আল্লাহও তাদের ব্যাপারে বেপরোয়া হয়ে গেলেন, আল্লাহ অমুখাপেক্ষী, প্রশংসিত।', 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064006.mp3', now()),
  (64, 7, '', '[{"id":7791,"position":1,"text_uthmani":"زَعَمَ","transliteration":"zaʿama","translation_bn":"দাবী করে","root":"زعم","lemma":"زَعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7792,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7793,"position":3,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"কুফরি করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7794,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":7795,"position":5,"text_uthmani":"لَّن","transliteration":"lan","translation_bn":"কক্ষনো না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":7796,"position":6,"text_uthmani":"يُبْعَثُوا۟ ۚ","transliteration":"yub''ʿathū","translation_bn":"তাদের পুনরায় উঠানো হবে","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7798,"position":7,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7799,"position":8,"text_uthmani":"بَلَىٰ","transliteration":"balā","translation_bn":"\"অবশ্যই হবে","root":"—","lemma":"بَلَىٰ\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":7800,"position":9,"text_uthmani":"وَرَبِّى","transliteration":"warabbī","translation_bn":"কসম আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":7801,"position":10,"text_uthmani":"لَتُبْعَثُنَّ","transliteration":"latub''ʿathunna","translation_bn":"অবশ্যই তোমাদের  উঠানো হবে","root":"بعث","lemma":"بَعَثَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":7802,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7803,"position":12,"text_uthmani":"لَتُنَبَّؤُنَّ","transliteration":"latunabba-unna","translation_bn":"অবশ্যই তোমাদের খবর দেয়া হবে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":7804,"position":13,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছুু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7805,"position":14,"text_uthmani":"عَمِلْتُمْ ۚ","transliteration":"ʿamil''tum","translation_bn":"তোমরা কাজ করেছো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7807,"position":15,"text_uthmani":"وَذَٰلِكَ","transliteration":"wadhālika","translation_bn":"এবং এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"শব্দ"},{"id":7808,"position":16,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"পক্ষে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7809,"position":17,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7810,"position":18,"text_uthmani":"يَسِيرٌۭ","transliteration":"yasīrun","translation_bn":"সহজ\"","root":"يسر","lemma":"يَسِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":7811,"position":19,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'zaʿama alladhīna kafarū an lan yub''ʿathū qul balā warabbī latub''ʿathunna thumma latunabba-unna bimā ʿamil''tum wadhālika ʿalā l-lahi yasīrun', 'কাফিররা ধারণা করে যে, তাদেরকে কক্ষনো আবার জীবিত করে উঠানো হবে না। বল, নিশ্চয়ই (উঠানো) হবে, আমার প্রতিপালকের শপথ! তোমাদেরকে অবশ্য অবশ্যই আবার জীবিত করে উঠানো হবে, অতঃপর তোমাদেরকে অবশ্য অবশ্যই জানিয়ে দেয়া হবে তোমরা (দুনিয়ায়) কী কাজ করেছ। এ কাজ (করা) আল্লাহর জন্য খুবই সহজ।', 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy."', 'কাফিররা ধারণা করে যে, তাদেরকে কক্ষনো আবার জীবিত করে উঠানো হবে না। বল, নিশ্চয়ই (উঠানো) হবে, আমার প্রতিপালকের শপথ! তোমাদেরকে অবশ্য অবশ্যই আবার জীবিত করে উঠানো হবে, অতঃপর তোমাদেরকে অবশ্য অবশ্যই জানিয়ে দেয়া হবে তোমরা (দুনিয়ায়) কী কাজ করেছ। এ কাজ (করা) আল্লাহর জন্য খুবই সহজ।', 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064007.mp3', now()),
  (64, 8, '', '[{"id":8959,"position":1,"text_uthmani":"فَـَٔامِنُوا۟","transliteration":"faāminū","translation_bn":"অতএব তোমরা ঈমান আনো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":8960,"position":2,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহ্‌র উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":8961,"position":3,"text_uthmani":"وَرَسُولِهِۦ","transliteration":"warasūlihi","translation_bn":"ও তাঁর রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8962,"position":4,"text_uthmani":"وَٱلنُّورِ","transliteration":"wal-nūri","translation_bn":"ও নূরের (কোরানের)","root":"نور","lemma":"نُور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8963,"position":5,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8964,"position":6,"text_uthmani":"أَنزَلْنَا ۚ","transliteration":"anzalnā","translation_bn":"আমরা নাযিল করেছি","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8966,"position":7,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":8967,"position":8,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8968,"position":9,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করছ","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8969,"position":10,"text_uthmani":"خَبِيرٌۭ","transliteration":"khabīrun","translation_bn":"খুব অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":8970,"position":11,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'faāminū bil-lahi warasūlihi wal-nūri alladhī anzalnā wal-lahu bimā taʿmalūna khabīrun', 'কাজেই (এ অবস্থার কথা চিন্তা ক’রে) তোমরা ঈমান আনো আল্লাহর প্রতি ও তাঁর রসূলের প্রতি আর সেই নূর (কুরআন)-এর প্রতি যা আমি অবতীর্ণ করেছি। তোমরা যা কর সে ব্যাপারে আল্লাহ পুরোপুরি অবগত।', 'So believe in Allah and His Messenger and the Qur''an which We have sent down. And Allah is Acquainted with what you do.', 'কাজেই (এ অবস্থার কথা চিন্তা ক’রে) তোমরা ঈমান আনো আল্লাহর প্রতি ও তাঁর রসূলের প্রতি আর সেই নূর (কুরআন)-এর প্রতি যা আমি অবতীর্ণ করেছি। তোমরা যা কর সে ব্যাপারে আল্লাহ পুরোপুরি অবগত।', 'So believe in Allah and His Messenger and the Qur''an which We have sent down. And Allah is Acquainted with what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064008.mp3', now()),
  (64, 9, '', '[{"id":10187,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":10188,"position":2,"text_uthmani":"يَجْمَعُكُمْ","transliteration":"yajmaʿukum","translation_bn":"তোমাদের একত্রিত করবেন","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10189,"position":3,"text_uthmani":"لِيَوْمِ","transliteration":"liyawmi","translation_bn":"দিনের জন্যে","root":"يوم","lemma":"يَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":10190,"position":4,"text_uthmani":"ٱلْجَمْعِ ۖ","transliteration":"l-jamʿi","translation_bn":"সমাবেশের","root":"جمع","lemma":"جَمْع","grammar_bn":"শব্দ"},{"id":10192,"position":5,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"সেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10193,"position":6,"text_uthmani":"يَوْمُ","transliteration":"yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10194,"position":7,"text_uthmani":"ٱلتَّغَابُنِ ۗ","transliteration":"l-taghābuni","translation_bn":"হার-জিতের","root":"غبن","lemma":"تَّغَابُن","grammar_bn":"শব্দ"},{"id":10196,"position":8,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":10197,"position":9,"text_uthmani":"يُؤْمِنۢ","transliteration":"yu''min","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10198,"position":10,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহ্‌র উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":10199,"position":11,"text_uthmani":"وَيَعْمَلْ","transliteration":"wayaʿmal","translation_bn":"ও কাজ করে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10200,"position":12,"text_uthmani":"صَـٰلِحًۭا","transliteration":"ṣāliḥan","translation_bn":"নেক","root":"صلح","lemma":"صَٰلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":10201,"position":13,"text_uthmani":"يُكَفِّرْ","transliteration":"yukaffir","translation_bn":"মোচন করবেন","root":"كفر","lemma":"كَفَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10202,"position":14,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"তার থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10203,"position":15,"text_uthmani":"سَيِّـَٔاتِهِۦ","transliteration":"sayyiātihi","translation_bn":"তার গুনাহগুলো","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":10204,"position":16,"text_uthmani":"وَيُدْخِلْهُ","transliteration":"wayud''khil''hu","translation_bn":"এবং তাকে প্রবেশ করাবেন","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10205,"position":17,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10206,"position":18,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10207,"position":19,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10208,"position":20,"text_uthmani":"تَحْتِهَا","transliteration":"taḥtihā","translation_bn":"তার পাদদেশ","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10209,"position":21,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারাগুলো","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":10210,"position":22,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"বসবাসকারী স্থায়ী","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10211,"position":23,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10212,"position":24,"text_uthmani":"أَبَدًۭا ۚ","transliteration":"abadan","translation_bn":"চিরকাল","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":10214,"position":25,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":10215,"position":26,"text_uthmani":"ٱلْفَوْزُ","transliteration":"l-fawzu","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"শব্দ"},{"id":10216,"position":27,"text_uthmani":"ٱلْعَظِيمُ","transliteration":"l-ʿaẓīmu","translation_bn":"বড়","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":10217,"position":28,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yawma yajmaʿukum liyawmi l-jamʿi dhālika yawmu l-taghābuni waman yu''min bil-lahi wayaʿmal ṣāliḥan yukaffir ʿanhu sayyiātihi wayud''khil''hu jannātin tajrī min taḥtihā l-anhāru khālidīna fīhā abadan dhālika l-fawzu l-ʿaẓīmu', 'যখন একত্র করার দিন তিনি তোমাদেরকে একত্রিত করবেন, সে দিনটি হবে তোমাদের হার জিতের দিন। যারা আল্লাহর প্রতি ঈমান আনবে আর সৎ কাজ করবে, আল্লাহ তার পাপ মোচন করে দিবেন, আর তাকে জান্নাতে দাখিল করবেন যার নীচ দিয়ে নির্ঝরিণী প্রবাহিত। সেখানে তারা থাকবে চিরকাল সর্বকাল। এটাই মহা সাফল্য।', 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', 'যখন একত্র করার দিন তিনি তোমাদেরকে একত্রিত করবেন, সে দিনটি হবে তোমাদের হার জিতের দিন। যারা আল্লাহর প্রতি ঈমান আনবে আর সৎ কাজ করবে, আল্লাহ তার পাপ মোচন করে দিবেন, আর তাকে জান্নাতে দাখিল করবেন যার নীচ দিয়ে নির্ঝরিণী প্রবাহিত। সেখানে তারা থাকবে চিরকাল সর্বকাল। এটাই মহা সাফল্য।', 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064009.mp3', now()),
  (64, 10, '', '[{"id":11426,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শব্দ"},{"id":11427,"position":2,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"কুফরি করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11428,"position":3,"text_uthmani":"وَكَذَّبُوا۟","transliteration":"wakadhabū","translation_bn":"ও মিথ্যারোপ করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11429,"position":4,"text_uthmani":"بِـَٔايَـٰتِنَآ","transliteration":"biāyātinā","translation_bn":"আমাদের আয়াত গুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":11430,"position":5,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":11431,"position":6,"text_uthmani":"أَصْحَـٰبُ","transliteration":"aṣḥābu","translation_bn":"অধিবাসী","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11432,"position":7,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"দোজখের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":11433,"position":8,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"বসবাসকারী স্থায়ী","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":11434,"position":9,"text_uthmani":"فِيهَا ۖ","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11436,"position":10,"text_uthmani":"وَبِئْسَ","transliteration":"wabi''sa","translation_bn":"এবং কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"শব্দ"},{"id":11437,"position":11,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন স্থল","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":11438,"position":12,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna kafarū wakadhabū biāyātinā ulāika aṣḥābu l-nāri khālidīna fīhā wabi''sa l-maṣīru', 'আর যারা কুফুরী করে আর আমার নিদর্শনগুলোকে অস্বীকার করে, তারাই জাহান্নামের অধিবাসী, তাতে তারা চিরকাল থাকবে। কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল!', 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.', 'আর যারা কুফুরী করে আর আমার নিদর্শনগুলোকে অস্বীকার করে, তারাই জাহান্নামের অধিবাসী, তাতে তারা চিরকাল থাকবে। কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল!', 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064010.mp3', now()),
  (64, 11, '', '[{"id":12714,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":12715,"position":2,"text_uthmani":"أَصَابَ","transliteration":"aṣāba","translation_bn":"আপতিত হয়","root":"صوب","lemma":"أَصَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12716,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12717,"position":4,"text_uthmani":"مُّصِيبَةٍ","transliteration":"muṣībatin","translation_bn":"মুসিবত","root":"صوب","lemma":"مُّصِيبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12718,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতিরেকে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":12719,"position":6,"text_uthmani":"بِإِذْنِ","transliteration":"bi-idh''ni","translation_bn":"অনুমতি","root":"اذن","lemma":"إِذْن","grammar_bn":"অব্যয় (Preposition)"},{"id":12720,"position":7,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12722,"position":8,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":12723,"position":9,"text_uthmani":"يُؤْمِنۢ","transliteration":"yu''min","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12724,"position":10,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহ্‌র উপরে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":12725,"position":11,"text_uthmani":"يَهْدِ","transliteration":"yahdi","translation_bn":"হেদায়াত দেন তিনি","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":12726,"position":12,"text_uthmani":"قَلْبَهُۥ ۚ","transliteration":"qalbahu","translation_bn":"তার অন্তরকে","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12728,"position":13,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":12729,"position":14,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":12730,"position":15,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছু (সম্পর্কে)","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12731,"position":16,"text_uthmani":"عَلِيمٌۭ","transliteration":"ʿalīmun","translation_bn":"খুব অবগত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":12732,"position":17,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'mā aṣāba min muṣībatin illā bi-idh''ni l-lahi waman yu''min bil-lahi yahdi qalbahu wal-lahu bikulli shayin ʿalīmun', 'আল্লাহর অনুমতি ছাড়া কোন বিপদ আসে না। যে ব্যক্তি আল্লাহর প্রতি ঈমান আনে, আল্লাহ তার অন্তরকে সঠিক পথে পরিচালিত করেন। আল্লাহ সকল বিষয়ের সর্বশ্রেষ্ঠ জ্ঞানী।', 'No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things.', 'আল্লাহর অনুমতি ছাড়া কোন বিপদ আসে না। যে ব্যক্তি আল্লাহর প্রতি ঈমান আনে, আল্লাহ তার অন্তরকে সঠিক পথে পরিচালিত করেন। আল্লাহ সকল বিষয়ের সর্বশ্রেষ্ঠ জ্ঞানী।', 'No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064011.mp3', now()),
  (64, 12, '', '[{"id":14017,"position":1,"text_uthmani":"وَأَطِيعُوا۟","transliteration":"wa-aṭīʿū","translation_bn":"এবং তোমরা আনুগত্য কর","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"শব্দ"},{"id":14018,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14019,"position":3,"text_uthmani":"وَأَطِيعُوا۟","transliteration":"wa-aṭīʿū","translation_bn":"ও আনুগত্য কর","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14020,"position":4,"text_uthmani":"ٱلرَّسُولَ ۚ","transliteration":"l-rasūla","translation_bn":"রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":14022,"position":5,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":14023,"position":6,"text_uthmani":"تَوَلَّيْتُمْ","transliteration":"tawallaytum","translation_bn":"তোমরা ফিরে যাও","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14024,"position":7,"text_uthmani":"فَإِنَّمَا","transliteration":"fa-innamā","translation_bn":"তবে মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":14025,"position":8,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14026,"position":9,"text_uthmani":"رَسُولِنَا","transliteration":"rasūlinā","translation_bn":"আমাদের রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":14027,"position":10,"text_uthmani":"ٱلْبَلَـٰغُ","transliteration":"l-balāghu","translation_bn":"পৌঁছান (দায়িত্ব)","root":"بلغ","lemma":"بَلَٰغ","grammar_bn":"শব্দ"},{"id":14028,"position":11,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্টভাবে","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":14029,"position":12,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-aṭīʿū l-laha wa-aṭīʿū l-rasūla fa-in tawallaytum fa-innamā ʿalā rasūlinā l-balāghu l-mubīnu', 'তোমরা আল্লাহর আনুগত্য কর ও রসূলের আনুগত্য কর। অতঃপর যদি তোমরা মুখ ফিরিয়ে লও (তাহলে তোমাদেরকে সঠিক পথে ফিরিয়ে আনার জন্য জোর জবরদস্তি করা হবে না) কেননা, আমার রসূলের দায়িত্ব কেবল (আমার বাণী) স্পষ্টভাবে পৌঁছে দেয়া।', 'And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.', 'তোমরা আল্লাহর আনুগত্য কর ও রসূলের আনুগত্য কর। অতঃপর যদি তোমরা মুখ ফিরিয়ে লও (তাহলে তোমাদেরকে সঠিক পথে ফিরিয়ে আনার জন্য জোর জবরদস্তি করা হবে না) কেননা, আমার রসূলের দায়িত্ব কেবল (আমার বাণী) স্পষ্টভাবে পৌঁছে দেয়া।', 'And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064012.mp3', now()),
  (64, 13, '', '[{"id":15169,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15170,"position":2,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا","grammar_bn":"না-বোধক (Negative)"},{"id":15171,"position":3,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":15172,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":15173,"position":5,"text_uthmani":"هُوَ ۚ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ ۚ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":15175,"position":6,"text_uthmani":"وَعَلَى","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"শব্দ"},{"id":15176,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15177,"position":8,"text_uthmani":"فَلْيَتَوَكَّلِ","transliteration":"falyatawakkali","translation_bn":"সুতরাং ভরসা করুক","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"শব্দ"},{"id":15178,"position":9,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু''মিনগণ","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":15179,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu lā ilāha illā huwa waʿalā l-lahi falyatawakkali l-mu''minūna', 'আল্লাহ তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই। কাজেই মু’মিনরা আল্লাহরই উপর নির্ভর করুক।', 'Allah - there is no deity except Him. And upon Allah let the believers rely.', 'আল্লাহ তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই। কাজেই মু’মিনরা আল্লাহরই উপর নির্ভর করুক।', 'Allah - there is no deity except Him. And upon Allah let the believers rely.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064013.mp3', now()),
  (64, 14, '', '[{"id":16210,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":16211,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16212,"position":3,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16213,"position":4,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16214,"position":5,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16215,"position":6,"text_uthmani":"أَزْوَٰجِكُمْ","transliteration":"azwājikum","translation_bn":"তোমাদের স্ত্রীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":16216,"position":7,"text_uthmani":"وَأَوْلَـٰدِكُمْ","transliteration":"wa-awlādikum","translation_bn":"ও তোমাদের সন্তান সন্ততিদের (কেউ কেউ)","root":"ولد","lemma":"وَلَد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16217,"position":8,"text_uthmani":"عَدُوًّۭا","transliteration":"ʿaduwwan","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16218,"position":9,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":16219,"position":10,"text_uthmani":"فَٱحْذَرُوهُمْ ۚ","transliteration":"fa-iḥ''dharūhum","translation_bn":"অতএব তাদের থেকে সতর্ক হও","root":"حذر","lemma":"يَحْذَرُ","grammar_bn":"কারণবাচক (Cause)"},{"id":16221,"position":11,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":16222,"position":12,"text_uthmani":"تَعْفُوا۟","transliteration":"taʿfū","translation_bn":"তোমরা মার্জনা কর","root":"عفو","lemma":"عَفَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":16223,"position":13,"text_uthmani":"وَتَصْفَحُوا۟","transliteration":"wataṣfaḥū","translation_bn":"ও তোমরা উপেক্ষা কর","root":"صفح","lemma":"يَصْفَحُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16224,"position":14,"text_uthmani":"وَتَغْفِرُوا۟","transliteration":"wataghfirū","translation_bn":"এবং তোমরা মাফ কর","root":"غفر","lemma":"غَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16225,"position":15,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"তবে নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":16226,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16227,"position":17,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":16228,"position":18,"text_uthmani":"رَّحِيمٌ","transliteration":"raḥīmun","translation_bn":"মেহেরবান","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":16229,"position":19,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū inna min azwājikum wa-awlādikum ʿaduwwan lakum fa-iḥ''dharūhum wa-in taʿfū wataṣfaḥū wataghfirū fa-inna l-laha ghafūrun raḥīmun', 'হে মু’মিনগণ! তোমাদের স্ত্রী আর সন্তানদের মধ্যে কতক তোমাদের শত্রু। কাজেই তোমরা তাদের হতে সতর্ক হও। তোমরা যদি তাদের প্রতি ক্ষমাসুলভ আচরণ কর, তাদের দোষ-ত্রুটি উপেক্ষা কর, আর তাদেরকে ক্ষমা কর, তাহলে (তোমাদের সে কাজ হবে আল্লাহর নিকট পছন্দীয় কারণ) আল্লাহ অতি ক্ষমাশীল, বড়ই দয়ালু।', 'O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful.', 'হে মু’মিনগণ! তোমাদের স্ত্রী আর সন্তানদের মধ্যে কতক তোমাদের শত্রু। কাজেই তোমরা তাদের হতে সতর্ক হও। তোমরা যদি তাদের প্রতি ক্ষমাসুলভ আচরণ কর, তাদের দোষ-ত্রুটি উপেক্ষা কর, আর তাদেরকে ক্ষমা কর, তাহলে (তোমাদের সে কাজ হবে আল্লাহর নিকট পছন্দীয় কারণ) আল্লাহ অতি ক্ষমাশীল, বড়ই দয়ালু।', 'O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064014.mp3', now()),
  (64, 15, '', '[{"id":17379,"position":1,"text_uthmani":"إِنَّمَآ","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17380,"position":2,"text_uthmani":"أَمْوَٰلُكُمْ","transliteration":"amwālukum","translation_bn":"তোমাদের মালগুলো","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":17381,"position":3,"text_uthmani":"وَأَوْلَـٰدُكُمْ","transliteration":"wa-awlādukum","translation_bn":"ও তোমাদের সন্তান সন্ততিরা","root":"ولد","lemma":"وَلَد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17382,"position":4,"text_uthmani":"فِتْنَةٌۭ ۚ","transliteration":"fit''natun","translation_bn":"পরীক্ষা","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17384,"position":5,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":17385,"position":6,"text_uthmani":"عِندَهُۥٓ","transliteration":"ʿindahu","translation_bn":"তাঁর কাছে (আছে)","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":17386,"position":7,"text_uthmani":"أَجْرٌ","transliteration":"ajrun","translation_bn":"প্রতিফল","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":17387,"position":8,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"বড়","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":17388,"position":9,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'innamā amwālukum wa-awlādukum fit''natun wal-lahu ʿindahu ajrun ʿaẓīmun', 'তোমাদের ধন-সম্পদ আর সন্তানাদি পরীক্ষা (’র বস্তু) মাত্র (যারা এ দু’টিকে সঠিকভাবে ব্যবহার ক’রে আল্লাহর পথে অটল থাকবে তারা কৃতকার্য হবে, আর যারা এ দু’টিকে আল্লাহর চেয়ে অধিক ভালবাসবে তারা ব্যর্থ হয়ে যাবে)। আর আল্লাহ এমন যাঁর কাছে আছে মহা পুরস্কার।', 'Your wealth and your children are but a trial, and Allah has with Him a great reward.', 'তোমাদের ধন-সম্পদ আর সন্তানাদি পরীক্ষা (’র বস্তু) মাত্র (যারা এ দু’টিকে সঠিকভাবে ব্যবহার ক’রে আল্লাহর পথে অটল থাকবে তারা কৃতকার্য হবে, আর যারা এ দু’টিকে আল্লাহর চেয়ে অধিক ভালবাসবে তারা ব্যর্থ হয়ে যাবে)। আর আল্লাহ এমন যাঁর কাছে আছে মহা পুরস্কার।', 'Your wealth and your children are but a trial, and Allah has with Him a great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064015.mp3', now()),
  (64, 16, '', '[{"id":18461,"position":1,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":18462,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18463,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যতটা","root":"—","lemma":"مَا\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":18464,"position":4,"text_uthmani":"ٱسْتَطَعْتُمْ","transliteration":"is''taṭaʿtum","translation_bn":"তোমরা পারো","root":"طوع","lemma":"ٱسْتَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18465,"position":5,"text_uthmani":"وَٱسْمَعُوا۟","transliteration":"wa-is''maʿū","translation_bn":"ও তোমরা শুনো","root":"سمع","lemma":"سَمِعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18466,"position":6,"text_uthmani":"وَأَطِيعُوا۟","transliteration":"wa-aṭīʿū","translation_bn":"ও তোমরা আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18467,"position":7,"text_uthmani":"وَأَنفِقُوا۟","transliteration":"wa-anfiqū","translation_bn":"তোমরা খরচ করো","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18468,"position":8,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18469,"position":9,"text_uthmani":"لِّأَنفُسِكُمْ ۗ","transliteration":"li-anfusikum","translation_bn":"তোমাদের নিজেদের জন্যে","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":18471,"position":10,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":18472,"position":11,"text_uthmani":"يُوقَ","transliteration":"yūqa","translation_bn":"রক্ষা পেল","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18473,"position":12,"text_uthmani":"شُحَّ","transliteration":"shuḥḥa","translation_bn":"সংকীর্ণতা (থেকে)","root":"شحح","lemma":"شُحّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18474,"position":13,"text_uthmani":"نَفْسِهِۦ","transliteration":"nafsihi","translation_bn":"তার মনের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":18475,"position":14,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"তবে ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"ফলাফল পদ (Result)"},{"id":18476,"position":15,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":18477,"position":16,"text_uthmani":"ٱلْمُفْلِحُونَ","transliteration":"l-muf''liḥūna","translation_bn":"সফলকাম","root":"فلح","lemma":"مُفْلِحُون","grammar_bn":"শব্দ"},{"id":18478,"position":17,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ittaqū l-laha mā is''taṭaʿtum wa-is''maʿū wa-aṭīʿū wa-anfiqū khayran li-anfusikum waman yūqa shuḥḥa nafsihi fa-ulāika humu l-muf''liḥūna', 'কাজেই তোমরা আল্লাহকে তোমাদের সাধ্যমত ভয় কর, তোমরা (তাঁর বাণী) শুন, তোমরা (তাঁর) আনুগত্য কর এবং (তাঁর পথে) ব্যয় কর, এটা তোমাদের নিজেদেরই জন্য কল্যাণকর। যারা অন্তরের সংকীর্ণতা থেকে রক্ষা পেল, তারাই সফলকাম।', 'So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', 'কাজেই তোমরা আল্লাহকে তোমাদের সাধ্যমত ভয় কর, তোমরা (তাঁর বাণী) শুন, তোমরা (তাঁর) আনুগত্য কর এবং (তাঁর পথে) ব্যয় কর, এটা তোমাদের নিজেদেরই জন্য কল্যাণকর। যারা অন্তরের সংকীর্ণতা থেকে রক্ষা পেল, তারাই সফলকাম।', 'So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064016.mp3', now()),
  (64, 17, '', '[{"id":19441,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19442,"position":2,"text_uthmani":"تُقْرِضُوا۟","transliteration":"tuq''riḍū","translation_bn":"তোমরা কর্জ দাও","root":"قرض","lemma":"أَقْرَضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19443,"position":3,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19444,"position":4,"text_uthmani":"قَرْضًا","transliteration":"qarḍan","translation_bn":"কর্জ","root":"قرض","lemma":"قَرْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":19445,"position":5,"text_uthmani":"حَسَنًۭا","transliteration":"ḥasanan","translation_bn":"উত্তম","root":"حسن","lemma":"حَسَن","grammar_bn":"বিশেষণ (Adjective)"},{"id":19446,"position":6,"text_uthmani":"يُضَـٰعِفْهُ","transliteration":"yuḍāʿif''hu","translation_bn":"তা বহু গুণ করবেন","root":"ضعف","lemma":"يُضَٰعِفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19447,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":19448,"position":8,"text_uthmani":"وَيَغْفِرْ","transliteration":"wayaghfir","translation_bn":"ও মাফ করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19449,"position":9,"text_uthmani":"لَكُمْ ۚ","transliteration":"lakum","translation_bn":"তোমাদেরকে","root":"—","lemma":"لَكُمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":19451,"position":10,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":19452,"position":11,"text_uthmani":"شَكُورٌ","transliteration":"shakūrun","translation_bn":"গুণগ্রাহী","root":"شكر","lemma":"شَكُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":19453,"position":12,"text_uthmani":"حَلِيمٌ","transliteration":"ḥalīmun","translation_bn":"ধৈর্যশীল","root":"حلم","lemma":"حَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":19454,"position":13,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'in tuq''riḍū l-laha qarḍan ḥasanan yuḍāʿif''hu lakum wayaghfir lakum wal-lahu shakūrun ḥalīmun', 'তোমরা যদি আল্লাহকে উত্তম ঋণ দাও, তবে তিনি তা তোমাদের জন্য দ্বিগুণ করে দেবেন, আর তোমাদেরকে ক্ষমা করবেন, আল্লাহ (কারো কাজের) অতি মর্যাদাদানকারী, সহনশীল।', 'If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.', 'তোমরা যদি আল্লাহকে উত্তম ঋণ দাও, তবে তিনি তা তোমাদের জন্য দ্বিগুণ করে দেবেন, আর তোমাদেরকে ক্ষমা করবেন, আল্লাহ (কারো কাজের) অতি মর্যাদাদানকারী, সহনশীল।', 'If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064017.mp3', now()),
  (64, 18, '', '[{"id":20696,"position":1,"text_uthmani":"عَـٰلِمُ","transliteration":"ʿālimu","translation_bn":"পরিজ্ঞাতা","root":"علم","lemma":"عَٰلِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20697,"position":2,"text_uthmani":"ٱلْغَيْبِ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":20698,"position":3,"text_uthmani":"وَٱلشَّهَـٰدَةِ","transliteration":"wal-shahādati","translation_bn":"ও দৃশ্যের","root":"شهد","lemma":"شَهَٰدَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20699,"position":4,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"মহাপরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":20700,"position":5,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":20701,"position":6,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'ʿālimu l-ghaybi wal-shahādati l-ʿazīzu l-ḥakīmu', 'তিনি অদৃশ্য ও দৃশ্যের জ্ঞানের অধিকারী, মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.', 'তিনি অদৃশ্য ও দৃশ্যের জ্ঞানের অধিকারী, মহাপরাক্রান্ত, মহাবিজ্ঞানী।', 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/064018.mp3', now())
