  (66, 1, '', '[{"id":555,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":556,"position":2,"text_uthmani":"ٱلنَّبِىُّ","transliteration":"l-nabiyu","translation_bn":"নবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":557,"position":3,"text_uthmani":"لِمَ","transliteration":"lima","translation_bn":"কেন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":558,"position":4,"text_uthmani":"تُحَرِّمُ","transliteration":"tuḥarrimu","translation_bn":"হারাম কর তুমি","root":"حرم","lemma":"حَرَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":559,"position":5,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":560,"position":6,"text_uthmani":"أَحَلَّ","transliteration":"aḥalla","translation_bn":"হালাল করেছেন","root":"حلل","lemma":"أَحَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":561,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":562,"position":8,"text_uthmani":"لَكَ ۖ","transliteration":"laka","translation_bn":"তোমার জন্যে","root":"—","lemma":"لَكَ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":564,"position":9,"text_uthmani":"تَبْتَغِى","transliteration":"tabtaghī","translation_bn":"তুমি চাও (কি)","root":"بغي","lemma":"ٱبْتَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":565,"position":10,"text_uthmani":"مَرْضَاتَ","transliteration":"marḍāta","translation_bn":"সন্তুষ্টি","root":"رضو","lemma":"مَرْضَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":566,"position":11,"text_uthmani":"أَزْوَٰجِكَ ۚ","transliteration":"azwājika","translation_bn":"তোমার স্ত্রীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":568,"position":12,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":569,"position":13,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":570,"position":14,"text_uthmani":"رَّحِيمٌۭ","transliteration":"raḥīmun","translation_bn":"মেহেরবান","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":571,"position":15,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nabiyu lima tuḥarrimu mā aḥalla l-lahu laka tabtaghī marḍāta azwājika wal-lahu ghafūrun raḥīmun', 'হে নবী! আল্লাহ যা তোমার জন্য হালাল করেছেন তা তুমি কেন হারাম করছ? (এর দ্বারা) তুমি তোমার স্ত্রীদের সন্তুষ্টি পেতে চাও, (আল্লাহ তোমার এ ত্রুটি ক্ষমা করে দিলেন কেননা) আল্লাহ অতি ক্ষমাশীল, বড়ই দয়ালু।', 'O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful.', 'হে নবী! আল্লাহ যা তোমার জন্য হালাল করেছেন তা তুমি কেন হারাম করছ? (এর দ্বারা) তুমি তোমার স্ত্রীদের সন্তুষ্টি পেতে চাও, (আল্লাহ তোমার এ ত্রুটি ক্ষমা করে দিলেন কেননা) আল্লাহ অতি ক্ষমাশীল, বড়ই দয়ালু।', 'O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066001.mp3', now()),
  (66, 2, '', '[{"id":1448,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":1449,"position":2,"text_uthmani":"فَرَضَ","transliteration":"faraḍa","translation_bn":"নির্দিষ্ট করেছেন","root":"فرض","lemma":"فَرَضَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1450,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1451,"position":4,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":1452,"position":5,"text_uthmani":"تَحِلَّةَ","transliteration":"taḥillata","translation_bn":"মুক্তির ব্যবস্থা","root":"حلل","lemma":"تَحِلَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1453,"position":6,"text_uthmani":"أَيْمَـٰنِكُمْ ۚ","transliteration":"aymānikum","translation_bn":"তোমাদের শপথগুলোর","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":1455,"position":7,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":1456,"position":8,"text_uthmani":"مَوْلَىٰكُمْ ۖ","transliteration":"mawlākum","translation_bn":"তোমাদের মনিব","root":"ولي","lemma":"مَوْلَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1458,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1459,"position":10,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":1460,"position":11,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":1461,"position":12,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'qad faraḍa l-lahu lakum taḥillata aymānikum wal-lahu mawlākum wahuwa l-ʿalīmu l-ḥakīmu', 'আল্লাহ তোমাদের জন্য নিজেদের কসমের বাধ্যবাধকতা থেকে নিস্কৃতি পাওয়ার ব্যবস্থা করেছেন, আল্লাহ তোমাদের মালিক-মনিব-রক্ষক, আর তিনি সর্বজ্ঞাতা, মহা প্রজ্ঞার অধিকারী।', 'Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise.', 'আল্লাহ তোমাদের জন্য নিজেদের কসমের বাধ্যবাধকতা থেকে নিস্কৃতি পাওয়ার ব্যবস্থা করেছেন, আল্লাহ তোমাদের মালিক-মনিব-রক্ষক, আর তিনি সর্বজ্ঞাতা, মহা প্রজ্ঞার অধিকারী।', 'Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066002.mp3', now()),
  (66, 3, '', '[{"id":2493,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":2494,"position":2,"text_uthmani":"أَسَرَّ","transliteration":"asarra","translation_bn":"গোপনে বলেছিল","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2495,"position":3,"text_uthmani":"ٱلنَّبِىُّ","transliteration":"l-nabiyu","translation_bn":"নবী","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"শব্দ"},{"id":2496,"position":4,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"নিকট","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2497,"position":5,"text_uthmani":"بَعْضِ","transliteration":"baʿḍi","translation_bn":"কারও","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":2498,"position":6,"text_uthmani":"أَزْوَٰجِهِۦ","transliteration":"azwājihi","translation_bn":"তার স্ত্রীদের","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":2499,"position":7,"text_uthmani":"حَدِيثًۭا","transliteration":"ḥadīthan","translation_bn":"একটি কথা","root":"حدث","lemma":"حَدِيث","grammar_bn":"বিশেষ্য (Noun)"},{"id":2500,"position":8,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"যখন অতঃপর","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":2501,"position":9,"text_uthmani":"نَبَّأَتْ","transliteration":"nabba-at","translation_bn":"সে বলে দেয় (অন্য স্ত্রীকে)","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2502,"position":10,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"তা সম্পর্কে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":2503,"position":11,"text_uthmani":"وَأَظْهَرَهُ","transliteration":"wa-aẓharahu","translation_bn":"ও তা প্রকাশ করলেন","root":"ظهر","lemma":"أَظْهَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2504,"position":12,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2505,"position":13,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2506,"position":14,"text_uthmani":"عَرَّفَ","transliteration":"ʿarrafa","translation_bn":"(নবী) ব্যক্ত করল","root":"عرف","lemma":"عَرَّفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2507,"position":15,"text_uthmani":"بَعْضَهُۥ","transliteration":"baʿḍahu","translation_bn":"তার কিছুটা","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":2508,"position":16,"text_uthmani":"وَأَعْرَضَ","transliteration":"wa-aʿraḍa","translation_bn":"ও এড়িয়ে গেল","root":"عرض","lemma":"أَعْرَضَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2509,"position":17,"text_uthmani":"عَنۢ","transliteration":"ʿan","translation_bn":"(যে)","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2510,"position":18,"text_uthmani":"بَعْضٍۢ ۖ","transliteration":"baʿḍin","translation_bn":"কিছু","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":2512,"position":19,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"যখন অতঃপর","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":2513,"position":20,"text_uthmani":"نَبَّأَهَا","transliteration":"nabba-ahā","translation_bn":"তাকে জানাল","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2514,"position":21,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"সে সম্পর্কে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":2515,"position":22,"text_uthmani":"قَالَتْ","transliteration":"qālat","translation_bn":"সে বলল (স্ত্রী)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2516,"position":23,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"\"কে","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2517,"position":24,"text_uthmani":"أَنۢبَأَكَ","transliteration":"anba-aka","translation_bn":"আপনাকে খবর দিল","root":"نبا","lemma":"أَن[بَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2518,"position":25,"text_uthmani":"هَـٰذَا ۖ","transliteration":"hādhā","translation_bn":"এটা\"","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2520,"position":26,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলল (নবী)","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2521,"position":27,"text_uthmani":"نَبَّأَنِىَ","transliteration":"nabba-aniya","translation_bn":"\"আমাকে খবর দিয়েছেন","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2522,"position":28,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":2523,"position":29,"text_uthmani":"ٱلْخَبِيرُ","transliteration":"l-khabīru","translation_bn":"ওয়াকিবহাল\"","root":"خبر","lemma":"خَبِير","grammar_bn":"শব্দ"},{"id":2524,"position":30,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh asarra l-nabiyu ilā baʿḍi azwājihi ḥadīthan falammā nabba-at bihi wa-aẓharahu l-lahu ʿalayhi ʿarrafa baʿḍahu wa-aʿraḍa ʿan baʿḍin falammā nabba-ahā bihi qālat man anba-aka hādhā qāla nabba-aniya l-ʿalīmu l-khabīru', 'স্মরণ কর- যখন নবী তার স্ত্রীদের কোন একজনকে গোপনে একটি কথা বলেছিল। অতঃপর সে স্ত্রী যখন তা (অন্য একজনকে) জানিয়ে দিল, তখন আল্লাহ এ ব্যাপারটি নবীকে জানিয়ে দিলেন। তখন নবী (তার স্ত্রীর কাছে) কিছু কথার উল্লেখ করল আর কিছু কথা ছেড়ে দিল। নবী যখন তা তার স্ত্রীকে জানাল তখন সে বলল, ‘আপনাকে এটা কে জানিয়ে দিল?’’ নবী বলল, ‘‘আমাকে জানিয়ে দিলেন যিনি সর্বজ্ঞাতা, ওয়াকিফহাল।’’', 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Acquainted."', 'স্মরণ কর- যখন নবী তার স্ত্রীদের কোন একজনকে গোপনে একটি কথা বলেছিল। অতঃপর সে স্ত্রী যখন তা (অন্য একজনকে) জানিয়ে দিল, তখন আল্লাহ এ ব্যাপারটি নবীকে জানিয়ে দিলেন। তখন নবী (তার স্ত্রীর কাছে) কিছু কথার উল্লেখ করল আর কিছু কথা ছেড়ে দিল। নবী যখন তা তার স্ত্রীকে জানাল তখন সে বলল, ‘আপনাকে এটা কে জানিয়ে দিল?’’ নবী বলল, ‘‘আমাকে জানিয়ে দিলেন যিনি সর্বজ্ঞাতা, ওয়াকিফহাল।’’', 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Acquainted."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066003.mp3', now()),
  (66, 4, '', '[{"id":3918,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":3919,"position":2,"text_uthmani":"تَتُوبَآ","transliteration":"tatūbā","translation_bn":"তোমরা দুজনে তওবা কর","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3920,"position":3,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"নিকট","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3921,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3922,"position":5,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"নিশ্চয় কেননা","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":3923,"position":6,"text_uthmani":"صَغَتْ","transliteration":"ṣaghat","translation_bn":"ঝুঁকেছিল","root":"صغو","lemma":"صَغَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3924,"position":7,"text_uthmani":"قُلُوبُكُمَا ۖ","transliteration":"qulūbukumā","translation_bn":"তোমাদের দু''জনের অন্তর","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":3926,"position":8,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3927,"position":9,"text_uthmani":"تَظَـٰهَرَا","transliteration":"taẓāharā","translation_bn":"তোমরা দু''জনে পরস্পরকে সাহায্য কর","root":"ظهر","lemma":"تَظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3928,"position":10,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3929,"position":11,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"নিশ্চয় তবে","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":3930,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3931,"position":13,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3932,"position":14,"text_uthmani":"مَوْلَىٰهُ","transliteration":"mawlāhu","translation_bn":"তার মনিব","root":"ولي","lemma":"مَوْلَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3933,"position":15,"text_uthmani":"وَجِبْرِيلُ","transliteration":"wajib''rīlu","translation_bn":"ও জিবরাঈল","root":"—","lemma":"جِبْرِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3934,"position":16,"text_uthmani":"وَصَـٰلِحُ","transliteration":"waṣāliḥu","translation_bn":"ও নেককার","root":"صلح","lemma":"صَٰلِح","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3935,"position":17,"text_uthmani":"ٱلْمُؤْمِنِينَ ۖ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনরা","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":3937,"position":18,"text_uthmani":"وَٱلْمَلَـٰٓئِكَةُ","transliteration":"wal-malāikatu","translation_bn":"ও ফেরেশতারা","root":"ملك","lemma":"مَلَك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3938,"position":19,"text_uthmani":"بَعْدَ","transliteration":"baʿda","translation_bn":"পরে","root":"بعد","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":3939,"position":20,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"উপরন্তু","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3940,"position":21,"text_uthmani":"ظَهِيرٌ","transliteration":"ẓahīrun","translation_bn":"সাহায্যকারী","root":"ظهر","lemma":"ظَهِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":3941,"position":22,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'in tatūbā ilā l-lahi faqad ṣaghat qulūbukumā wa-in taẓāharā ʿalayhi fa-inna l-laha huwa mawlāhu wajib''rīlu waṣāliḥu l-mu''minīna wal-malāikatu baʿda dhālika ẓahīrun', 'তোমরা দু’জন যদি অনুশোচনাভরে আল্লাহর দিকে ফিরে আস (তবে তা তোমাদের জন্য উত্তম), তোমাদের অন্তর (অন্যায়ের দিকে) ঝুঁকে পড়েছে, তোমরা যদি নবীর বিরুদ্ধে একে অপরকে সহযোগিতা কর, তবে (জেনে রেখ) আল্লাহ তার মালিক-মনিব-রক্ষক। আর এ ছাড়াও জিবরীল, নেককার মু’মিনগণ আর ফেরেশতাগণও তার সাহায্যকারী।', 'If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.', 'তোমরা দু’জন যদি অনুশোচনাভরে আল্লাহর দিকে ফিরে আস (তবে তা তোমাদের জন্য উত্তম), তোমাদের অন্তর (অন্যায়ের দিকে) ঝুঁকে পড়েছে, তোমরা যদি নবীর বিরুদ্ধে একে অপরকে সহযোগিতা কর, তবে (জেনে রেখ) আল্লাহ তার মালিক-মনিব-রক্ষক। আর এ ছাড়াও জিবরীল, নেককার মু’মিনগণ আর ফেরেশতাগণও তার সাহায্যকারী।', 'If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066004.mp3', now()),
  (66, 5, '', '[{"id":5148,"position":1,"text_uthmani":"عَسَىٰ","transliteration":"ʿasā","translation_bn":"সম্ভবতঃ","root":"عسي","lemma":"عَسَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":5149,"position":2,"text_uthmani":"رَبُّهُۥٓ","transliteration":"rabbuhu","translation_bn":"তার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5150,"position":3,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":5151,"position":4,"text_uthmani":"طَلَّقَكُنَّ","transliteration":"ṭallaqakunna","translation_bn":"তোমাদের তালাক দেয় (নবী)","root":"طلق","lemma":"طَلَّقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5152,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":5153,"position":6,"text_uthmani":"يُبْدِلَهُۥٓ","transliteration":"yub''dilahu","translation_bn":"তাকে বদলে দেবেন","root":"بدل","lemma":"يُبْدِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5154,"position":7,"text_uthmani":"أَزْوَٰجًا","transliteration":"azwājan","translation_bn":"(এমন সব) স্ত্রী","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":5155,"position":8,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":5156,"position":9,"text_uthmani":"مِّنكُنَّ","transliteration":"minkunna","translation_bn":"(যারা) তোমাদের চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5157,"position":10,"text_uthmani":"مُسْلِمَـٰتٍۢ","transliteration":"mus''limātin","translation_bn":"আত্নসমর্পণকারিণী","root":"سلم","lemma":"مُسْلِمَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5158,"position":11,"text_uthmani":"مُّؤْمِنَـٰتٍۢ","transliteration":"mu''minātin","translation_bn":"মুমিনা","root":"امن","lemma":"مُّؤْمِنَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5159,"position":12,"text_uthmani":"قَـٰنِتَـٰتٍۢ","transliteration":"qānitātin","translation_bn":"আনুগত্যশীলা","root":"قنت","lemma":"قَٰنِتَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5160,"position":13,"text_uthmani":"تَـٰٓئِبَـٰتٍ","transliteration":"tāibātin","translation_bn":"তওবাকারিনী","root":"توب","lemma":"تَٰ^ئِبَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5161,"position":14,"text_uthmani":"عَـٰبِدَٰتٍۢ","transliteration":"ʿābidātin","translation_bn":"ইবাদতকারিণী","root":"عبد","lemma":"عَٰبِدَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5162,"position":15,"text_uthmani":"سَـٰٓئِحَـٰتٍۢ","transliteration":"sāiḥātin","translation_bn":"রোজাদার","root":"سيح","lemma":"سَٰ^ئِحَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5163,"position":16,"text_uthmani":"ثَيِّبَـٰتٍۢ","transliteration":"thayyibātin","translation_bn":"অকুমারী","root":"ثيب","lemma":"ثَيِّبَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":5164,"position":17,"text_uthmani":"وَأَبْكَارًۭا","transliteration":"wa-abkāran","translation_bn":"ও কুমারী","root":"بكر","lemma":"بِكْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5165,"position":18,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ʿasā rabbuhu in ṭallaqakunna an yub''dilahu azwājan khayran minkunna mus''limātin mu''minātin qānitātin tāibātin ʿābidātin sāiḥātin thayyibātin wa-abkāran', 'নবী যদি তোমাদের সবাইকে তালাক দিয়ে দেয় তবে সম্ভবতঃ তার প্রতিপালক তোমাদের পরিবর্তে তাকে দিবেন তোমাদের চেয়ে উত্তম স্ত্রী- যারা হবে আত্মসমপর্ণকারিণী মু’মিনা অনুগতা, তাওবাহকারিণী, ‘ইবাদাতকারিণী, রোযা পালনকারিণী, অকুমারী ও কুমারী।', 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.', 'নবী যদি তোমাদের সবাইকে তালাক দিয়ে দেয় তবে সম্ভবতঃ তার প্রতিপালক তোমাদের পরিবর্তে তাকে দিবেন তোমাদের চেয়ে উত্তম স্ত্রী- যারা হবে আত্মসমপর্ণকারিণী মু’মিনা অনুগতা, তাওবাহকারিণী, ‘ইবাদাতকারিণী, রোযা পালনকারিণী, অকুমারী ও কুমারী।', 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066005.mp3', now()),
  (66, 6, '', '[{"id":6433,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":6434,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6435,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছ","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6436,"position":4,"text_uthmani":"قُوٓا۟","transliteration":"qū","translation_bn":"তোমরা রক্ষা কর","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6437,"position":5,"text_uthmani":"أَنفُسَكُمْ","transliteration":"anfusakum","translation_bn":"তোমাদের নিজেদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":6438,"position":6,"text_uthmani":"وَأَهْلِيكُمْ","transliteration":"wa-ahlīkum","translation_bn":"ও তোমাদের পরিবারবর্গকে","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6439,"position":7,"text_uthmani":"نَارًۭا","transliteration":"nāran","translation_bn":"আগুন (থেকে)","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":6440,"position":8,"text_uthmani":"وَقُودُهَا","transliteration":"waqūduhā","translation_bn":"যার ইন্ধন","root":"وقد","lemma":"وَقُود","grammar_bn":"বিশেষ্য (Noun)"},{"id":6441,"position":9,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানুষ","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":6442,"position":10,"text_uthmani":"وَٱلْحِجَارَةُ","transliteration":"wal-ḥijāratu","translation_bn":"ও পাথর","root":"حجر","lemma":"حِجَارَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6443,"position":11,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6444,"position":12,"text_uthmani":"مَلَـٰٓئِكَةٌ","transliteration":"malāikatun","translation_bn":"ফেরেশতারা","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":6445,"position":13,"text_uthmani":"غِلَاظٌۭ","transliteration":"ghilāẓun","translation_bn":"নির্দয়","root":"غلظ","lemma":"غَلِيظ","grammar_bn":"বিশেষণ (Adjective)"},{"id":6446,"position":14,"text_uthmani":"شِدَادٌۭ","transliteration":"shidādun","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":6447,"position":15,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6448,"position":16,"text_uthmani":"يَعْصُونَ","transliteration":"yaʿṣūna","translation_bn":"তারা অমান্য করে","root":"عصي","lemma":"عَصَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":6449,"position":17,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6450,"position":18,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6451,"position":19,"text_uthmani":"أَمَرَهُمْ","transliteration":"amarahum","translation_bn":"তাদের নির্দেশ দেন তিনি","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6452,"position":20,"text_uthmani":"وَيَفْعَلُونَ","transliteration":"wayafʿalūna","translation_bn":"এবং তারা করে","root":"فعل","lemma":"فَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6453,"position":21,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6454,"position":22,"text_uthmani":"يُؤْمَرُونَ","transliteration":"yu''marūna","translation_bn":"তাদের নির্দেশ দেয়া হয়","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6455,"position":23,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū qū anfusakum wa-ahlīkum nāran waqūduhā l-nāsu wal-ḥijāratu ʿalayhā malāikatun ghilāẓun shidādun lā yaʿṣūna l-laha mā amarahum wayafʿalūna mā yu''marūna', 'হে মু’মিনগণ! তোমরা তোমাদের নিজেদেরকে আর তোমাদের পরিবার-পরিজনকে জাহান্নামের আগুন থেকে রক্ষা কর যার ইন্ধন হবে মানুষ ও পাথর, যাতে মোতায়েন আছে পাষাণ হৃদয় কঠোর স্বভাব ফেরেশতা। আল্লাহ যা আদেশ করেন, তা তারা অমান্য করে না, আর তারা তাই করে, তাদেরকে যা করার জন্য আদেশ দেয়া হয়।', 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.', 'হে মু’মিনগণ! তোমরা তোমাদের নিজেদেরকে আর তোমাদের পরিবার-পরিজনকে জাহান্নামের আগুন থেকে রক্ষা কর যার ইন্ধন হবে মানুষ ও পাথর, যাতে মোতায়েন আছে পাষাণ হৃদয় কঠোর স্বভাব ফেরেশতা। আল্লাহ যা আদেশ করেন, তা তারা অমান্য করে না, আর তারা তাই করে, তাদেরকে যা করার জন্য আদেশ দেয়া হয়।', 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066006.mp3', now()),
  (66, 7, '', '[{"id":7841,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"\"ওহে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":7842,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"\"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7843,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"\"কুফরী করেছ","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7844,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":7845,"position":5,"text_uthmani":"تَعْتَذِرُوا۟","transliteration":"taʿtadhirū","translation_bn":"তোমরা ওজর পেশ করো","root":"عذر","lemma":"يَعْتَذِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7846,"position":6,"text_uthmani":"ٱلْيَوْمَ ۖ","transliteration":"l-yawma","translation_bn":"আজ","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":7848,"position":7,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7849,"position":8,"text_uthmani":"تُجْزَوْنَ","transliteration":"tuj''zawna","translation_bn":"তোমাদের প্রতিফল দেয়া হবে","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7850,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7851,"position":10,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7852,"position":11,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করতেছিলে\"","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7853,"position":12,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna kafarū lā taʿtadhirū l-yawma innamā tuj''zawna mā kuntum taʿmalūna', '(সেখানে বলা হবে) ওহে যারা কুফুরী করেছ! আজ ওযর পেশ করো না, তোমরা যা করতে তোমাদেরকে তারই প্রতিফল দেয়া হবে।', 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.', '(সেখানে বলা হবে) ওহে যারা কুফুরী করেছ! আজ ওযর পেশ করো না, তোমরা যা করতে তোমাদেরকে তারই প্রতিফল দেয়া হবে।', 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/066007.mp3', now()),
