  (67, 1, '', '[{"id":572,"position":1,"text_uthmani":"تَبَـٰرَكَ","transliteration":"tabāraka","translation_bn":"বড় বরকতময়","root":"برك","lemma":"تَبَارَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":573,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"সেই(সত্তা)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":574,"position":3,"text_uthmani":"بِيَدِهِ","transliteration":"biyadihi","translation_bn":"যার হাতে","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":575,"position":4,"text_uthmani":"ٱلْمُلْكُ","transliteration":"l-mul''ku","translation_bn":"কর্তৃত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"শব্দ"},{"id":576,"position":5,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":577,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":578,"position":7,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":579,"position":8,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":580,"position":9,"text_uthmani":"قَدِيرٌ","transliteration":"qadīrun","translation_bn":"ক্ষমতাবান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":581,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tabāraka alladhī biyadihi l-mul''ku wahuwa ʿalā kulli shayin qadīrun', 'অতি মহান ও শ্রেষ্ঠ তিনি, সর্বময় কর্তৃত্ব ও রাজত্ব যাঁর হাতে; তিনি সব কিছুর উপর ক্ষমতাবান।', 'Blessed is He in whose hand is dominion, and He is over all things competent -', 'অতি মহান ও শ্রেষ্ঠ তিনি, সর্বময় কর্তৃত্ব ও রাজত্ব যাঁর হাতে; তিনি সব কিছুর উপর ক্ষমতাবান।', 'Blessed is He in whose hand is dominion, and He is over all things competent -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067001.mp3', now()),
  (67, 2, '', '[{"id":1462,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1463,"position":2,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1464,"position":3,"text_uthmani":"ٱلْمَوْتَ","transliteration":"l-mawta","translation_bn":"মৃত্যু","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":1465,"position":4,"text_uthmani":"وَٱلْحَيَوٰةَ","transliteration":"wal-ḥayata","translation_bn":"এবং জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1466,"position":5,"text_uthmani":"لِيَبْلُوَكُمْ","transliteration":"liyabluwakum","translation_bn":"তোমাদের পরীক্ষা করার জন্য","root":"بلو","lemma":"بَلَوْ","grammar_bn":"শব্দ"},{"id":1467,"position":6,"text_uthmani":"أَيُّكُمْ","transliteration":"ayyukum","translation_bn":"তোমাদের মধ্যে কে","root":"—","lemma":"أَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1468,"position":7,"text_uthmani":"أَحْسَنُ","transliteration":"aḥsanu","translation_bn":"সর্বোত্তম","root":"حسن","lemma":"أَحْسَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":1469,"position":8,"text_uthmani":"عَمَلًۭا ۚ","transliteration":"ʿamalan","translation_bn":"আমলে","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1471,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":1472,"position":10,"text_uthmani":"ٱلْعَزِيزُ","transliteration":"l-ʿazīzu","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"শব্দ"},{"id":1473,"position":11,"text_uthmani":"ٱلْغَفُورُ","transliteration":"l-ghafūru","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"শব্দ"},{"id":1474,"position":12,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī khalaqa l-mawta wal-ḥayata liyabluwakum ayyukum aḥsanu ʿamalan wahuwa l-ʿazīzu l-ghafūru', 'যিনি সৃষ্টি করেছেন মরণ ও জীবন যাতে তোমাদেরকে পরীক্ষা করেন- ‘আমালের দিক দিয়ে তোমাদের মধ্যে কোন্ ব্যক্তি সর্বোত্তম? তিনি (একদিকে যেমন) মহা শক্তিধর, (আবার অন্যদিকে) অতি ক্ষমাশীল।', '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -', 'যিনি সৃষ্টি করেছেন মরণ ও জীবন যাতে তোমাদেরকে পরীক্ষা করেন- ‘আমালের দিক দিয়ে তোমাদের মধ্যে কোন্ ব্যক্তি সর্বোত্তম? তিনি (একদিকে যেমন) মহা শক্তিধর, (আবার অন্যদিকে) অতি ক্ষমাশীল।', '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067002.mp3', now()),
  (67, 3, '', '[{"id":2525,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"তিনিই","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2526,"position":2,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2527,"position":3,"text_uthmani":"سَبْعَ","transliteration":"sabʿa","translation_bn":"সাত","root":"سبع","lemma":"سَبْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":2528,"position":4,"text_uthmani":"سَمَـٰوَٰتٍۢ","transliteration":"samāwātin","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":2529,"position":5,"text_uthmani":"طِبَاقًۭا ۖ","transliteration":"ṭibāqan","translation_bn":"স্তরে স্তরে","root":"طبق","lemma":"طَبَق","grammar_bn":"বিশেষণ (Adjective)"},{"id":2531,"position":6,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2532,"position":7,"text_uthmani":"تَرَىٰ","transliteration":"tarā","translation_bn":"দেখতে পাবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":2533,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2534,"position":9,"text_uthmani":"خَلْقِ","transliteration":"khalqi","translation_bn":"সৃষ্টির","root":"خلق","lemma":"خَلْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":2535,"position":10,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"দয়াবানের","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":2536,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2537,"position":12,"text_uthmani":"تَفَـٰوُتٍۢ ۖ","transliteration":"tafāwutin","translation_bn":"অসঙ্গতি","root":"فوت","lemma":"تَفَٰوُت","grammar_bn":"বিশেষ্য (Noun)"},{"id":2539,"position":13,"text_uthmani":"فَٱرْجِعِ","transliteration":"fa-ir''jiʿi","translation_bn":"অতএব ফিরাও","root":"رجع","lemma":"رَجَعَ","grammar_bn":"কারণবাচক (Cause)"},{"id":2540,"position":14,"text_uthmani":"ٱلْبَصَرَ","transliteration":"l-baṣara","translation_bn":"দৃষ্টিশক্তি","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":2541,"position":15,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2542,"position":16,"text_uthmani":"تَرَىٰ","transliteration":"tarā","translation_bn":"দেখতে পাও","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":2543,"position":17,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2544,"position":18,"text_uthmani":"فُطُورٍۢ","transliteration":"fuṭūrin","translation_bn":"ত্রুটি","root":"فطر","lemma":"فُطُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":2545,"position":19,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī khalaqa sabʿa samāwātin ṭibāqan mā tarā fī khalqi l-raḥmāni min tafāwutin fa-ir''jiʿi l-baṣara hal tarā min fuṭūrin', 'যিনি সৃষ্টি করেছেন সাত আসমান- একটির উপর আরেকটি। তোমরা মহা দয়াময়ের সৃষ্টিকার্যে কোনরূপ অসামঞ্জস্য দেখতে পাবে না। তোমরা আবার দৃষ্টি ফিরিয়ে দেখ, কোন দোষ-ত্রুটি দেখতে পাও কি?', '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?', 'যিনি সৃষ্টি করেছেন সাত আসমান- একটির উপর আরেকটি। তোমরা মহা দয়াময়ের সৃষ্টিকার্যে কোনরূপ অসামঞ্জস্য দেখতে পাবে না। তোমরা আবার দৃষ্টি ফিরিয়ে দেখ, কোন দোষ-ত্রুটি দেখতে পাও কি?', '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067003.mp3', now()),
  (67, 4, '', '[{"id":3942,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"আবার","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3943,"position":2,"text_uthmani":"ٱرْجِعِ","transliteration":"ir''jiʿi","translation_bn":"ফিরাও","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3944,"position":3,"text_uthmani":"ٱلْبَصَرَ","transliteration":"l-baṣara","translation_bn":"দৃষ্টি","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":3945,"position":4,"text_uthmani":"كَرَّتَيْنِ","transliteration":"karratayni","translation_bn":"বার বার","root":"كرر","lemma":"كَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3946,"position":5,"text_uthmani":"يَنقَلِبْ","transliteration":"yanqalib","translation_bn":"ফিরে আসবে","root":"قلب","lemma":"ٱنقَلَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3947,"position":6,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3948,"position":7,"text_uthmani":"ٱلْبَصَرُ","transliteration":"l-baṣaru","translation_bn":"দৃষ্টি","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":3949,"position":8,"text_uthmani":"خَاسِئًۭا","transliteration":"khāsi-an","translation_bn":"ব্যর্থ হয়ে","root":"خسا","lemma":"خَاسِئ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3950,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তা (হবে)","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":3951,"position":10,"text_uthmani":"حَسِيرٌۭ","transliteration":"ḥasīrun","translation_bn":"ক্লান্তশ্রান্ত","root":"حسر","lemma":"حَسِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":3952,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma ir''jiʿi l-baṣara karratayni yanqalib ilayka l-baṣaru khāsi-an wahuwa ḥasīrun', 'অতঃপর তোমরা বারবার দৃষ্টি ফিরিয়ে দেখ; ক্লান্ত, শ্রান্ত ও ব্যর্থ হয়ে দৃষ্টি তোমার দিকে ফিরে আসবে।', 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.', 'অতঃপর তোমরা বারবার দৃষ্টি ফিরিয়ে দেখ; ক্লান্ত, শ্রান্ত ও ব্যর্থ হয়ে দৃষ্টি তোমার দিকে ফিরে আসবে।', 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067004.mp3', now()),
  (67, 5, '', '[{"id":5166,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":5167,"position":2,"text_uthmani":"زَيَّنَّا","transliteration":"zayyannā","translation_bn":"আমরা সাজিয়েছি","root":"زين","lemma":"زَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5168,"position":3,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":5169,"position":4,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"নিকটবর্তী","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":5170,"position":5,"text_uthmani":"بِمَصَـٰبِيحَ","transliteration":"bimaṣābīḥa","translation_bn":"প্রদীপরাশি দিয়ে","root":"صبح","lemma":"مِصْبَاح","grammar_bn":"অব্যয় (Preposition)"},{"id":5171,"position":6,"text_uthmani":"وَجَعَلْنَـٰهَا","transliteration":"wajaʿalnāhā","translation_bn":"এবং তা আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5172,"position":7,"text_uthmani":"رُجُومًۭا","transliteration":"rujūman","translation_bn":"নিক্ষেপ উপকরণ","root":"رجم","lemma":"رُجُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":5173,"position":8,"text_uthmani":"لِّلشَّيَـٰطِينِ ۖ","transliteration":"lilshayāṭīni","translation_bn":"শয়তানদের জন্য","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":5175,"position":9,"text_uthmani":"وَأَعْتَدْنَا","transliteration":"wa-aʿtadnā","translation_bn":"এবং আমরা প্রস্তুত করে রেখেছি","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5176,"position":10,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5177,"position":11,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5178,"position":12,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"প্রজ্জ্বলিত আগুনের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":5179,"position":13,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad zayyannā l-samāa l-dun''yā bimaṣābīḥa wajaʿalnāhā rujūman lilshayāṭīni wa-aʿtadnā lahum ʿadhāba l-saʿīri', 'আমি নিকটবর্তী আকাশকে প্রদীপমালা দিয়ে সুসজ্জিত করেছি আর শয়ত্বানকে তাড়িয়ে দেয়ার জন্য, এবং প্রস্তুত করে রেখেছি জ্বলন্ত আগুনের শাস্তি।', 'And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.', 'আমি নিকটবর্তী আকাশকে প্রদীপমালা দিয়ে সুসজ্জিত করেছি আর শয়ত্বানকে তাড়িয়ে দেয়ার জন্য, এবং প্রস্তুত করে রেখেছি জ্বলন্ত আগুনের শাস্তি।', 'And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067005.mp3', now()),
  (67, 6, '', '[{"id":6461,"position":1,"text_uthmani":"وَلِلَّذِينَ","transliteration":"walilladhīna","translation_bn":"এবং যারা জন্যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শব্দ"},{"id":6462,"position":2,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6463,"position":3,"text_uthmani":"بِرَبِّهِمْ","transliteration":"birabbihim","translation_bn":"তাদের রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6464,"position":4,"text_uthmani":"عَذَابُ","transliteration":"ʿadhābu","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":6465,"position":5,"text_uthmani":"جَهَنَّمَ ۖ","transliteration":"jahannama","translation_bn":"জাহান্নামের","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6467,"position":6,"text_uthmani":"وَبِئْسَ","transliteration":"wabi''sa","translation_bn":"এবং অত্যন্ত খারাপ","root":"باس","lemma":"بِئْسَ","grammar_bn":"শব্দ"},{"id":6468,"position":7,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন স্থল","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":6469,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'walilladhīna kafarū birabbihim ʿadhābu jahannama wabi''sa l-maṣīru', 'যারা তাদের প্রতিপালককে অস্বীকার করে তাদের জন্য আছে জাহান্নামের শাস্তি; কতই না নিকৃষ্ট সে প্রত্যাবর্তনস্থল!', 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.', 'যারা তাদের প্রতিপালককে অস্বীকার করে তাদের জন্য আছে জাহান্নামের শাস্তি; কতই না নিকৃষ্ট সে প্রত্যাবর্তনস্থল!', 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067006.mp3', now()),
  (67, 7, '', '[{"id":7854,"position":1,"text_uthmani":"إِذَآ","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":7855,"position":2,"text_uthmani":"أُلْقُوا۟","transliteration":"ul''qū","translation_bn":"নিক্ষিপ্ত হবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":7856,"position":3,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7857,"position":4,"text_uthmani":"سَمِعُوا۟","transliteration":"samiʿū","translation_bn":"তারা শুনবে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7858,"position":5,"text_uthmani":"لَهَا","transliteration":"lahā","translation_bn":"তার জন্য","root":"—","lemma":"لَهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":7859,"position":6,"text_uthmani":"شَهِيقًۭا","transliteration":"shahīqan","translation_bn":"বিকট শব্দ","root":"شهق","lemma":"شَهِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":7860,"position":7,"text_uthmani":"وَهِىَ","transliteration":"wahiya","translation_bn":"এবং তা","root":"—","lemma":"وَهِىَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":7861,"position":8,"text_uthmani":"تَفُورُ","transliteration":"tafūru","translation_bn":"উদ্বেলিত হবে","root":"فور","lemma":"فَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7862,"position":9,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'idhā ul''qū fīhā samiʿū lahā shahīqan wahiya tafūru', 'তাদেরকে যখন তাতে নিক্ষেপ করা হবে তখন তারা জাহান্নামের শ্বাস গ্রহণের (ভয়াবহ) গর্জন শুনতে পাবে আর তা হবে উদ্বেলিত।', 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.', 'তাদেরকে যখন তাতে নিক্ষেপ করা হবে তখন তারা জাহান্নামের শ্বাস গ্রহণের (ভয়াবহ) গর্জন শুনতে পাবে আর তা হবে উদ্বেলিত।', 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067007.mp3', now()),
  (67, 8, '', '[{"id":9038,"position":1,"text_uthmani":"تَكَادُ","transliteration":"takādu","translation_bn":"উপক্রম হবে","root":"كود","lemma":"كَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9039,"position":2,"text_uthmani":"تَمَيَّزُ","transliteration":"tamayyazu","translation_bn":"ফেটে পড়ার","root":"ميز","lemma":"تَمَيَّزُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9040,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9041,"position":4,"text_uthmani":"ٱلْغَيْظِ ۖ","transliteration":"l-ghayẓi","translation_bn":"রোষে","root":"غيظ","lemma":"غَيْظ","grammar_bn":"শব্দ"},{"id":9043,"position":5,"text_uthmani":"كُلَّمَآ","transliteration":"kullamā","translation_bn":"যখনই","root":"كلل\r","lemma":"كُلَّمَا","grammar_bn":"কালবাচক (Time)"},{"id":9044,"position":6,"text_uthmani":"أُلْقِىَ","transliteration":"ul''qiya","translation_bn":"নিক্ষিপ্ত হবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":9045,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9046,"position":8,"text_uthmani":"فَوْجٌۭ","transliteration":"fawjun","translation_bn":"কোন দল","root":"فوج","lemma":"فَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":9047,"position":9,"text_uthmani":"سَأَلَهُمْ","transliteration":"sa-alahum","translation_bn":"জিজ্ঞেস তাদের করবে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9048,"position":10,"text_uthmani":"خَزَنَتُهَآ","transliteration":"khazanatuhā","translation_bn":"তার রক্ষীরা","root":"خزن","lemma":"خَزَنَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":9049,"position":11,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"\"নাই কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":9050,"position":12,"text_uthmani":"يَأْتِكُمْ","transliteration":"yatikum","translation_bn":"তোমাদের কাছে আসে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":9051,"position":13,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"সতর্ককারী\"","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":9052,"position":14,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'takādu tamayyazu mina l-ghayẓi kullamā ul''qiya fīhā fawjun sa-alahum khazanatuhā alam yatikum nadhīrun', 'ক্রোধে আক্রোশে জাহান্নাম ফেটে পড়ার উপক্রম হবে। যখনই কোন দলকে তাতে ফেলা হবে তখন তার রক্ষীরা তাদেরকে জিজ্ঞেস করবে, ‘তোমাদের কাছে কি কোন সতর্ককারী আসেনি?’', 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"', 'ক্রোধে আক্রোশে জাহান্নাম ফেটে পড়ার উপক্রম হবে। যখনই কোন দলকে তাতে ফেলা হবে তখন তার রক্ষীরা তাদেরকে জিজ্ঞেস করবে, ‘তোমাদের কাছে কি কোন সতর্ককারী আসেনি?’', 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067008.mp3', now()),
  (67, 9, '', '[{"id":10240,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10241,"position":2,"text_uthmani":"بَلَىٰ","transliteration":"balā","translation_bn":"\"হ্যাঁ","root":"—","lemma":"بَلَىٰ\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":10242,"position":3,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"অবশ্যই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":10243,"position":4,"text_uthmani":"جَآءَنَا","transliteration":"jāanā","translation_bn":"এসেছিল আমাদের (কাছে)","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10244,"position":5,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":10245,"position":6,"text_uthmani":"فَكَذَّبْنَا","transliteration":"fakadhabnā","translation_bn":"তবে আমরা মিথ্যারোপ করেছিলাম","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10246,"position":7,"text_uthmani":"وَقُلْنَا","transliteration":"waqul''nā","translation_bn":"এবং আমরা বলে ছিলাম","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10247,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"নাই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":10248,"position":9,"text_uthmani":"نَزَّلَ","transliteration":"nazzala","translation_bn":"নাযিল করেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10249,"position":10,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10250,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10251,"position":12,"text_uthmani":"شَىْءٍ","transliteration":"shayin","translation_bn":"কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10252,"position":13,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নও","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":10253,"position":14,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10254,"position":15,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":10255,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10256,"position":17,"text_uthmani":"ضَلَـٰلٍۢ","transliteration":"ḍalālin","translation_bn":"গুমরাহীর","root":"ضلل","lemma":"ضَلَٰل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10257,"position":18,"text_uthmani":"كَبِيرٍۢ","transliteration":"kabīrin","translation_bn":"বড়\"","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":10258,"position":19,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'qālū balā qad jāanā nadhīrun fakadhabnā waqul''nā mā nazzala l-lahu min shayin in antum illā fī ḍalālin kabīrin', 'তারা জবাব দিবে, ‘হ্যাঁ, অবশ্যই আমাদের কাছে সতর্ককারী এসেছিল, কিন্তু আমরা তাদেরকে অস্বীকার করেছিলাম আর আমরা বলেছিলাম, ‘আল্লাহ কোন কিছুই অবতীর্ণ করেননি, তোমরা তো ঘোর বিভ্রান্তিতে পড়ে আছ।’', 'They will say," Yes, a warner had come to us, but we denied and said, ''Allah has not sent down anything. You are not but in great error.''"', 'তারা জবাব দিবে, ‘হ্যাঁ, অবশ্যই আমাদের কাছে সতর্ককারী এসেছিল, কিন্তু আমরা তাদেরকে অস্বীকার করেছিলাম আর আমরা বলেছিলাম, ‘আল্লাহ কোন কিছুই অবতীর্ণ করেননি, তোমরা তো ঘোর বিভ্রান্তিতে পড়ে আছ।’', 'They will say," Yes, a warner had come to us, but we denied and said, ''Allah has not sent down anything. You are not but in great error.''"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067009.mp3', now()),
  (67, 10, '', '[{"id":11497,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11498,"position":2,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"\"''যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":11499,"position":3,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11500,"position":4,"text_uthmani":"نَسْمَعُ","transliteration":"nasmaʿu","translation_bn":"শুনতাম","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11501,"position":5,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11502,"position":6,"text_uthmani":"نَعْقِلُ","transliteration":"naʿqilu","translation_bn":"আমরা বিবেচনা করতাম","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11503,"position":7,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":11504,"position":8,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11505,"position":9,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11506,"position":10,"text_uthmani":"أَصْحَـٰبِ","transliteration":"aṣḥābi","translation_bn":"অধিবাসীদের","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11507,"position":11,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"প্রজ্বলিত আগুনের\"","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":11508,"position":12,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū law kunnā nasmaʿu aw naʿqilu mā kunnā fī aṣḥābi l-saʿīri', 'তারা আরো বলবে, ‘আমরা যদি শুনতাম অথবা বুঝতাম তাহলে আমরা জ্বলন্ত আগুনের বাসিন্দাদের মধ্যে শামিল হতাম না।', 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."', 'তারা আরো বলবে, ‘আমরা যদি শুনতাম অথবা বুঝতাম তাহলে আমরা জ্বলন্ত আগুনের বাসিন্দাদের মধ্যে শামিল হতাম না।', 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067010.mp3', now()),
  (67, 11, '', '[{"id":12795,"position":1,"text_uthmani":"فَٱعْتَرَفُوا۟","transliteration":"fa-iʿ''tarafū","translation_bn":"এভাবে তারা স্বীকার করবে","root":"عرف","lemma":"ٱعْتَرَفُ","grammar_bn":"শব্দ"},{"id":12796,"position":2,"text_uthmani":"بِذَنۢبِهِمْ","transliteration":"bidhanbihim","translation_bn":"তাদের অপরাধকে","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":12797,"position":3,"text_uthmani":"فَسُحْقًۭا","transliteration":"fasuḥ''qan","translation_bn":"অভিশাপ অতএব","root":"سحق","lemma":"سُحْق","grammar_bn":"শব্দ"},{"id":12798,"position":4,"text_uthmani":"لِّأَصْحَـٰبِ","transliteration":"li-aṣḥābi","translation_bn":"অধিবাসীদের জন্য","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"অব্যয় (Preposition)"},{"id":12799,"position":5,"text_uthmani":"ٱلسَّعِيرِ","transliteration":"l-saʿīri","translation_bn":"প্রজ্বলিত আগুনের","root":"سعر","lemma":"سَعِير","grammar_bn":"শব্দ"},{"id":12800,"position":6,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'fa-iʿ''tarafū bidhanbihim fasuḥ''qan li-aṣḥābi l-saʿīri', 'তারা তাদের অপরাধ স্বীকার করবে, অতএব দূর হোক জাহান্নামের অধিবাসীরা!', 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.', 'তারা তাদের অপরাধ স্বীকার করবে, অতএব দূর হোক জাহান্নামের অধিবাসীরা!', 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067011.mp3', now()),
  (67, 12, '', '[{"id":13922,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13923,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13924,"position":3,"text_uthmani":"يَخْشَوْنَ","transliteration":"yakhshawna","translation_bn":"ভয় করে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13925,"position":4,"text_uthmani":"رَبَّهُم","transliteration":"rabbahum","translation_bn":"তাদের রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13926,"position":5,"text_uthmani":"بِٱلْغَيْبِ","transliteration":"bil-ghaybi","translation_bn":"অদেখা অবস্থায়","root":"غيب","lemma":"غَيْب","grammar_bn":"অব্যয় (Preposition)"},{"id":13927,"position":6,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তাদের জন্য","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":13928,"position":7,"text_uthmani":"مَّغْفِرَةٌۭ","transliteration":"maghfiratun","translation_bn":"ক্ষমা","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":13929,"position":8,"text_uthmani":"وَأَجْرٌۭ","transliteration":"wa-ajrun","translation_bn":"এবং প্রতিদান","root":"اجر","lemma":"أَجْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13930,"position":9,"text_uthmani":"كَبِيرٌۭ","transliteration":"kabīrun","translation_bn":"বড়","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":13931,"position":10,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna yakhshawna rabbahum bil-ghaybi lahum maghfiratun wa-ajrun kabīrun', 'যারা তাদের প্রতিপালকে না দেখেই ভয় করে তাদের জন্য আছে ক্ষমা আর মহা পুরস্কার।', 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.', 'যারা তাদের প্রতিপালকে না দেখেই ভয় করে তাদের জন্য আছে ক্ষমা আর মহা পুরস্কার।', 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067012.mp3', now()),
  (67, 13, '', '[{"id":15125,"position":1,"text_uthmani":"وَأَسِرُّوا۟","transliteration":"wa-asirrū","translation_bn":"এবং তোমরা গোপন কর","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"শব্দ"},{"id":15126,"position":2,"text_uthmani":"قَوْلَكُمْ","transliteration":"qawlakum","translation_bn":"তোমাদের কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15127,"position":3,"text_uthmani":"أَوِ","transliteration":"awi","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15128,"position":4,"text_uthmani":"ٱجْهَرُوا۟","transliteration":"ij''harū","translation_bn":"প্রকাশ কর","root":"جهر","lemma":"جَهَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15129,"position":5,"text_uthmani":"بِهِۦٓ ۖ","transliteration":"bihi","translation_bn":"তাকে","root":"—","lemma":"بِهِۦٓ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":15131,"position":6,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15132,"position":7,"text_uthmani":"عَلِيمٌۢ","transliteration":"ʿalīmun","translation_bn":"খুব জ্ঞাত","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15133,"position":8,"text_uthmani":"بِذَاتِ","transliteration":"bidhāti","translation_bn":"অবস্থা সম্পর্কে","root":"—","lemma":"ذُو","grammar_bn":"অব্যয় (Preposition)"},{"id":15134,"position":9,"text_uthmani":"ٱلصُّدُورِ","transliteration":"l-ṣudūri","translation_bn":"অন্তরগুলোর","root":"صدر","lemma":"صَدْر","grammar_bn":"শব্দ"},{"id":15135,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-asirrū qawlakum awi ij''harū bihi innahu ʿalīmun bidhāti l-ṣudūri', 'তোমরা তোমাদের কথা চুপেচাপেই বল আর উচ্চৈঃস্বরেই বল, তিনি (মানুষের) অন্তরের গোপন কথা সম্পর্কে পুরোপুরি অবগত।', 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.', 'তোমরা তোমাদের কথা চুপেচাপেই বল আর উচ্চৈঃস্বরেই বল, তিনি (মানুষের) অন্তরের গোপন কথা সম্পর্কে পুরোপুরি অবগত।', 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067013.mp3', now()),
  (67, 14, '', '[{"id":16202,"position":1,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"না কি","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16203,"position":2,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16204,"position":3,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যিনি","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16205,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16206,"position":5,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"অথচ তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":16207,"position":6,"text_uthmani":"ٱللَّطِيفُ","transliteration":"l-laṭīfu","translation_bn":"সূক্ষ্মদর্শী","root":"لطف","lemma":"لَطِيف","grammar_bn":"শব্দ"},{"id":16208,"position":7,"text_uthmani":"ٱلْخَبِيرُ","transliteration":"l-khabīru","translation_bn":"খুব অবগত","root":"خبر","lemma":"خَبِير","grammar_bn":"শব্দ"},{"id":16209,"position":8,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'alā yaʿlamu man khalaqa wahuwa l-laṭīfu l-khabīru', 'যিনি সৃষ্টি করেছেন তিনিই কি জানেন না? তিনি অতি সূক্ষ্মদর্শী, ওয়াকিফহাল।', 'Does He who created not know, while He is the Subtle, the Acquainted?', 'যিনি সৃষ্টি করেছেন তিনিই কি জানেন না? তিনি অতি সূক্ষ্মদর্শী, ওয়াকিফহাল।', 'Does He who created not know, while He is the Subtle, the Acquainted?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067014.mp3', now()),
  (67, 15, '', '[{"id":17389,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":17390,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17391,"position":3,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17392,"position":4,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":17393,"position":5,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"ভূতলকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":17394,"position":6,"text_uthmani":"ذَلُولًۭا","transliteration":"dhalūlan","translation_bn":"অধীন","root":"ذلل","lemma":"ذَلُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":17395,"position":7,"text_uthmani":"فَٱمْشُوا۟","transliteration":"fa-im''shū","translation_bn":"তোমরা অতঃপর চল","root":"مشي","lemma":"مَّشَ","grammar_bn":"শব্দ"},{"id":17396,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17397,"position":9,"text_uthmani":"مَنَاكِبِهَا","transliteration":"manākibihā","translation_bn":"তার বক্ষের","root":"نكب","lemma":"مَنَاكِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":17398,"position":10,"text_uthmani":"وَكُلُوا۟","transliteration":"wakulū","translation_bn":"এবং তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17399,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17400,"position":12,"text_uthmani":"رِّزْقِهِۦ ۖ","transliteration":"riz''qihi","translation_bn":"তার রিযক","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":17402,"position":13,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"শব্দ"},{"id":17403,"position":14,"text_uthmani":"ٱلنُّشُورُ","transliteration":"l-nushūru","translation_bn":"পুনরুত্থান","root":"نشر","lemma":"نُشُور","grammar_bn":"শব্দ"},{"id":17404,"position":15,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī jaʿala lakumu l-arḍa dhalūlan fa-im''shū fī manākibihā wakulū min riz''qihi wa-ilayhi l-nushūru', 'তিনি তোমাদের জন্য যমীনকে (তোমাদের ইচ্ছার) অধীন করে দিয়েছেন, কাজেই তোমরা তার বুকের উপর দিয়ে চলাচল কর, আর আল্লাহর দেয়া রিযক হতে আহার কর, পুনরায় জীবিত হয়ে তাঁর কাছেই যেতে হবে।', 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.', 'তিনি তোমাদের জন্য যমীনকে (তোমাদের ইচ্ছার) অধীন করে দিয়েছেন, কাজেই তোমরা তার বুকের উপর দিয়ে চলাচল কর, আর আল্লাহর দেয়া রিযক হতে আহার কর, পুনরায় জীবিত হয়ে তাঁর কাছেই যেতে হবে।', 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067015.mp3', now()),
  (67, 16, '', '[{"id":18479,"position":1,"text_uthmani":"ءَأَمِنتُم","transliteration":"a-amintum","translation_bn":"তোমরা নিরাপদ কি হয়েছ","root":"امن","lemma":"أَمِنَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":18480,"position":2,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"(তাঁর থেকে) যিনি","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18481,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"আছেন","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18482,"position":4,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আসমানে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":18483,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":18484,"position":6,"text_uthmani":"يَخْسِفَ","transliteration":"yakhsifa","translation_bn":"ধসিয়ে দেবেন","root":"خسف","lemma":"خَسَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18485,"position":7,"text_uthmani":"بِكُمُ","transliteration":"bikumu","translation_bn":"তোমাদের সহ","root":"—","lemma":"بِكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":18486,"position":8,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"মাটিকে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":18487,"position":9,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর","root":"—","lemma":"إِذَا2\r","grammar_bn":"শব্দ"},{"id":18488,"position":10,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তা","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":18489,"position":11,"text_uthmani":"تَمُورُ","transliteration":"tamūru","translation_bn":"কাঁপবে","root":"مور","lemma":"تَمُورُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18490,"position":12,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'a-amintum man fī l-samāi an yakhsifa bikumu l-arḍa fa-idhā hiya tamūru', 'তোমরা কি তোমাদেরকে নিরাপদ মনে করে নিয়েছ যে, যিনি আকাশে আছেন তিনি তোমাদেরকে যমীনে বিধ্বস্ত করে দিবেন না যখন তা হঠাৎ থর থর করে কাঁপতে থাকবে?', 'Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?', 'তোমরা কি তোমাদেরকে নিরাপদ মনে করে নিয়েছ যে, যিনি আকাশে আছেন তিনি তোমাদেরকে যমীনে বিধ্বস্ত করে দিবেন না যখন তা হঠাৎ থর থর করে কাঁপতে থাকবে?', 'Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067016.mp3', now()),
  (67, 17, '', '[{"id":19455,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19456,"position":2,"text_uthmani":"أَمِنتُم","transliteration":"amintum","translation_bn":"তোমরা নির্ভয় হয়েছ","root":"امن","lemma":"أَمِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19457,"position":3,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"(তাঁর থেকে) যিনি","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19458,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"আছেন","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19459,"position":5,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আসমানে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":19460,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":19461,"position":7,"text_uthmani":"يُرْسِلَ","transliteration":"yur''sila","translation_bn":"পাঠাবেন","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19462,"position":8,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19463,"position":9,"text_uthmani":"حَاصِبًۭا ۖ","transliteration":"ḥāṣiban","translation_bn":"কঙ্করবর্ষী ঝঞ্ঝা","root":"حصب","lemma":"حَاصِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":19465,"position":10,"text_uthmani":"فَسَتَعْلَمُونَ","transliteration":"fasataʿlamūna","translation_bn":"তোমরা জানবে তখন","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":19466,"position":11,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":19467,"position":12,"text_uthmani":"نَذِيرِ","transliteration":"nadhīri","translation_bn":"আমার সতর্কীকরণ","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":19468,"position":13,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'am amintum man fī l-samāi an yur''sila ʿalaykum ḥāṣiban fasataʿlamūna kayfa nadhīri', 'কিংবা তোমরা কি নিরাপদ হয়ে গেছ যে, যিনি আকাশে আছেন তিনি তোমাদের উপর পাথর বর্ষণকারী ঝড়ো হাওয়া পাঠাবেন না? যাতে তোমরা জানতে পারবে যে, কেমন (ভয়ানক) ছিল আমার সতর্কবাণী।', 'Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning.', 'কিংবা তোমরা কি নিরাপদ হয়ে গেছ যে, যিনি আকাশে আছেন তিনি তোমাদের উপর পাথর বর্ষণকারী ঝড়ো হাওয়া পাঠাবেন না? যাতে তোমরা জানতে পারবে যে, কেমন (ভয়ানক) ছিল আমার সতর্কবাণী।', 'Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067017.mp3', now()),
  (67, 18, '', '[{"id":20539,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং করে ছিল নিশ্চয়","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":20540,"position":2,"text_uthmani":"كَذَّبَ","transliteration":"kadhaba","translation_bn":"মিথ্যারোপ","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20541,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20542,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"(ছিল)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20543,"position":5,"text_uthmani":"قَبْلِهِمْ","transliteration":"qablihim","translation_bn":"তাদের পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":20544,"position":6,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"কেমন ফলে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"শব্দ"},{"id":20545,"position":7,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20546,"position":8,"text_uthmani":"نَكِيرِ","transliteration":"nakīri","translation_bn":"আমার পাক্‌ড়াও","root":"نكر","lemma":"نَكِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":20547,"position":9,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad kadhaba alladhīna min qablihim fakayfa kāna nakīri', 'তাদের আগের লোকেরাও (আমার সতর্কবাণী) প্রত্যাখ্যান করেছিল, ফলে কেমন (কঠোর) হয়েছিল আমার শাস্তি!', 'And already had those before them denied, and how [terrible] was My reproach.', 'তাদের আগের লোকেরাও (আমার সতর্কবাণী) প্রত্যাখ্যান করেছিল, ফলে কেমন (কঠোর) হয়েছিল আমার শাস্তি!', 'And already had those before them denied, and how [terrible] was My reproach.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067018.mp3', now()),
  (67, 19, '', '[{"id":21617,"position":1,"text_uthmani":"أَوَلَمْ","transliteration":"awalam","translation_bn":"কি নাই","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":21618,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা দেখে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":21619,"position":3,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21620,"position":4,"text_uthmani":"ٱلطَّيْرِ","transliteration":"l-ṭayri","translation_bn":"পাখিগুলির","root":"طير","lemma":"طَيْر","grammar_bn":"শব্দ"},{"id":21621,"position":5,"text_uthmani":"فَوْقَهُمْ","transliteration":"fawqahum","translation_bn":"তাদের উপরে","root":"فوق","lemma":"فَوْق","grammar_bn":"স্থানবাচক (Location)"},{"id":21622,"position":6,"text_uthmani":"صَـٰٓفَّـٰتٍۢ","transliteration":"ṣāffātin","translation_bn":"পাখা বিস্তার করে","root":"صفف","lemma":"صَٰ^فَّٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":21623,"position":7,"text_uthmani":"وَيَقْبِضْنَ ۚ","transliteration":"wayaqbiḍ''na","translation_bn":"ও গুটিয়ে নেয়","root":"قبض","lemma":"قَبَضْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21625,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21626,"position":9,"text_uthmani":"يُمْسِكُهُنَّ","transliteration":"yum''sikuhunna","translation_bn":"তাদের ধরে ধরে (অন্য কেউ)","root":"مسك","lemma":"أَمْسَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21627,"position":10,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":21628,"position":11,"text_uthmani":"ٱلرَّحْمَـٰنُ ۚ","transliteration":"l-raḥmānu","translation_bn":"দয়াবান","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":21630,"position":12,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21631,"position":13,"text_uthmani":"بِكُلِّ","transliteration":"bikulli","translation_bn":"সব উপর","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":21632,"position":14,"text_uthmani":"شَىْءٍۭ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":21633,"position":15,"text_uthmani":"بَصِيرٌ","transliteration":"baṣīrun","translation_bn":"দৃষ্টিবান","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":21634,"position":16,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'awalam yaraw ilā l-ṭayri fawqahum ṣāffātin wayaqbiḍ''na mā yum''sikuhunna illā l-raḥmānu innahu bikulli shayin baṣīrun', 'তারা কি তাদের উপর দিকে পাখীগুলোর প্রতি লক্ষ্য করে না যারা ডানা মেলে দেয় আবার গুটিয়ে নেয়? দয়াময় ছাড়া অন্য কেউই তাদেরকে (উপরে) ধরে রাখে না। তিনি সবকিছুর সম্যক দ্রষ্টা।', 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.', 'তারা কি তাদের উপর দিকে পাখীগুলোর প্রতি লক্ষ্য করে না যারা ডানা মেলে দেয় আবার গুটিয়ে নেয়? দয়াময় ছাড়া অন্য কেউই তাদেরকে (উপরে) ধরে রাখে না। তিনি সবকিছুর সম্যক দ্রষ্টা।', 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067019.mp3', now()),
  (67, 20, '', '[{"id":22685,"position":1,"text_uthmani":"أَمَّنْ","transliteration":"amman","translation_bn":"অথবা কোন","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22686,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এমন","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22687,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22688,"position":4,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সেই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22689,"position":5,"text_uthmani":"جُندٌۭ","transliteration":"jundun","translation_bn":"সৈন্যবাহিনী","root":"جند","lemma":"جُند","grammar_bn":"বিশেষ্য (Noun)"},{"id":22690,"position":6,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্য আছে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":22691,"position":7,"text_uthmani":"يَنصُرُكُم","transliteration":"yanṣurukum","translation_bn":"তোমাদের সাহায্য করবে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22692,"position":8,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22693,"position":9,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"ছাড়া","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":22694,"position":10,"text_uthmani":"ٱلرَّحْمَـٰنِ ۚ","transliteration":"l-raḥmāni","translation_bn":"রহমান","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":22696,"position":11,"text_uthmani":"إِنِ","transliteration":"ini","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":22697,"position":12,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"আমান্যকারীরা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":22698,"position":13,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":22699,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22700,"position":15,"text_uthmani":"غُرُورٍ","transliteration":"ghurūrin","translation_bn":"ধোঁকার","root":"غرر","lemma":"غُرُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":22701,"position":16,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'amman hādhā alladhī huwa jundun lakum yanṣurukum min dūni l-raḥmāni ini l-kāfirūna illā fī ghurūrin', 'দয়াময় ছাড়া কে তোমাদেরকে সাহায্য করবে তোমাদের সেনাবাহিনী হয়ে? কাফিররা তো কেবল ধোঁকার মধ্যে পড়ে আছে।', 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.', 'দয়াময় ছাড়া কে তোমাদেরকে সাহায্য করবে তোমাদের সেনাবাহিনী হয়ে? কাফিররা তো কেবল ধোঁকার মধ্যে পড়ে আছে।', 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067020.mp3', now()),
  (67, 21, '', '[{"id":23872,"position":1,"text_uthmani":"أَمَّنْ","transliteration":"amman","translation_bn":"কে অথবা আছে","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23873,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এমন","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":23874,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23875,"position":4,"text_uthmani":"يَرْزُقُكُمْ","transliteration":"yarzuqukum","translation_bn":"তোমাদের রিযক দেবে","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23876,"position":5,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":23877,"position":6,"text_uthmani":"أَمْسَكَ","transliteration":"amsaka","translation_bn":"তিনি বন্ধ করেন","root":"مسك","lemma":"أَمْسَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23878,"position":7,"text_uthmani":"رِزْقَهُۥ ۚ","transliteration":"riz''qahu","translation_bn":"তার রিযক","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":23880,"position":8,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":23881,"position":9,"text_uthmani":"لَّجُّوا۟","transliteration":"lajjū","translation_bn":"তারা অবিচল","root":"لجج","lemma":"لَّجُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23882,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23883,"position":11,"text_uthmani":"عُتُوٍّۢ","transliteration":"ʿutuwwin","translation_bn":"খোদাদ্রোহিতার","root":"عتو","lemma":"عُتُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23884,"position":12,"text_uthmani":"وَنُفُورٍ","transliteration":"wanufūrin","translation_bn":"এবং সত্য পরিহারে","root":"نفر","lemma":"نُفُور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23885,"position":13,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'amman hādhā alladhī yarzuqukum in amsaka riz''qahu bal lajjū fī ʿutuwwin wanufūrin', 'অথবা এমন কে আছে যে তোমাদেরকে রিযক দিবে যদি তিনি তাঁর রিযক বন্ধ করে দেন? আসলে তারা অহমিকা ও অনীহায় ডুবে আছে।', 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.', 'অথবা এমন কে আছে যে তোমাদেরকে রিযক দিবে যদি তিনি তাঁর রিযক বন্ধ করে দেন? আসলে তারা অহমিকা ও অনীহায় ডুবে আছে।', 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067021.mp3', now()),
  (67, 22, '', '[{"id":24867,"position":1,"text_uthmani":"أَفَمَن","transliteration":"afaman","translation_bn":"যে অতএব কি","root":"—","lemma":"مَن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":24868,"position":2,"text_uthmani":"يَمْشِى","transliteration":"yamshī","translation_bn":"চলে","root":"مشي","lemma":"مَّشَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24869,"position":3,"text_uthmani":"مُكِبًّا","transliteration":"mukibban","translation_bn":"অধঃগতি","root":"كبب","lemma":"مُكِبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24870,"position":4,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24871,"position":5,"text_uthmani":"وَجْهِهِۦٓ","transliteration":"wajhihi","translation_bn":"তার মুখের","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":24872,"position":6,"text_uthmani":"أَهْدَىٰٓ","transliteration":"ahdā","translation_bn":"অধিক সত্য পথপ্রাপ্ত","root":"هدي","lemma":"أَهْدَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24873,"position":7,"text_uthmani":"أَمَّن","transliteration":"amman","translation_bn":"যে অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24874,"position":8,"text_uthmani":"يَمْشِى","transliteration":"yamshī","translation_bn":"চলে","root":"مشي","lemma":"مَّشَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24875,"position":9,"text_uthmani":"سَوِيًّا","transliteration":"sawiyyan","translation_bn":"সোজাসুজি","root":"سوي","lemma":"سَوِيّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24876,"position":10,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24877,"position":11,"text_uthmani":"صِرَٰطٍۢ","transliteration":"ṣirāṭin","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":24878,"position":12,"text_uthmani":"مُّسْتَقِيمٍۢ","transliteration":"mus''taqīmin","translation_bn":"সরল","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":24879,"position":13,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'afaman yamshī mukibban ʿalā wajhihi ahdā amman yamshī sawiyyan ʿalā ṣirāṭin mus''taqīmin', 'যে লোক উপুড় হয়ে মুখের ভরে চলে সেই কি অধিক সৎপথপ্রাপ্ত, না সেই লোক যে সোজা হয়ে সরল সঠিক পথে চলে?', 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?', 'যে লোক উপুড় হয়ে মুখের ভরে চলে সেই কি অধিক সৎপথপ্রাপ্ত, না সেই লোক যে সোজা হয়ে সরল সঠিক পথে চলে?', 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067022.mp3', now()),
  (67, 23, '', '[{"id":25907,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25908,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"\"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":25909,"position":3,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25910,"position":4,"text_uthmani":"أَنشَأَكُمْ","transliteration":"ansha-akum","translation_bn":"তোমাদের সৃষ্টি করেছেন","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25911,"position":5,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং দিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25912,"position":6,"text_uthmani":"لَكُمُ","transliteration":"lakumu","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمُ","grammar_bn":"অব্যয় (Preposition)"},{"id":25913,"position":7,"text_uthmani":"ٱلسَّمْعَ","transliteration":"l-samʿa","translation_bn":"শ্রবণশক্তি","root":"سمع","lemma":"سَمْع","grammar_bn":"শব্দ"},{"id":25914,"position":8,"text_uthmani":"وَٱلْأَبْصَـٰرَ","transliteration":"wal-abṣāra","translation_bn":"ও দৃষ্টিশক্তি","root":"بصر","lemma":"بَصَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25915,"position":9,"text_uthmani":"وَٱلْأَفْـِٔدَةَ ۖ","transliteration":"wal-afidata","translation_bn":"এবং অন্তঃকরণ","root":"فاد","lemma":"فُؤَاد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25917,"position":10,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"কমই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":25918,"position":11,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25919,"position":12,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"তোমরা শোকর কর\"","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25920,"position":13,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'qul huwa alladhī ansha-akum wajaʿala lakumu l-samʿa wal-abṣāra wal-afidata qalīlan mā tashkurūna', 'বলে দাও, ‘তিনিই তোমাদেরকে সৃষ্টি করেছেন আর তোমাদেরকে দিয়েছেন শোনার ও দেখার শক্তি আর অন্তঃকরণ; তোমরা শোকর আদায় খুব অল্পই করে থাক।’', 'Say, "It is He who has produced you and made for you hearing and vision and hearts; little are you grateful."', 'বলে দাও, ‘তিনিই তোমাদেরকে সৃষ্টি করেছেন আর তোমাদেরকে দিয়েছেন শোনার ও দেখার শক্তি আর অন্তঃকরণ; তোমরা শোকর আদায় খুব অল্পই করে থাক।’', 'Say, "It is He who has produced you and made for you hearing and vision and hearts; little are you grateful."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/067023.mp3', now()),
  (67, 24, '', '[{"id":26986,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26987,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"\"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26988,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26989,"position":4,"text_uthmani":"ذَرَأَكُمْ","transliteration":"dhara-akum","translation_bn":"তোমাদের ছড়িয়ে দিয়েছেন","root":"ذرا","lemma":"ذَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26990,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26991,"position":6,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":26992,"position":7,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং তাঁরই দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"শব্দ"},{"id":26993,"position":8,"text_uthmani":"تُحْشَرُونَ","transliteration":"tuḥ''sharūna","translation_bn":"তোমাদের একত্রিত করা হবে\"","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26994,"position":9,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'qul huwa alladhī dhara-akum fī l-arḍi wa-ilayhi tuḥ''sharūna', 'বলে দাও, ‘তিনিই তোমাদেরকে যমীনে ছড়িয়ে দিয়েছেন আর তাঁর কাছেই তোমাদেরকে সমবেত করা হবে।', 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."', 'বলে দাও, ‘তিনিই তোমাদেরকে যমীনে ছড়িয়ে দিয়েছেন আর তাঁর কাছেই তোমাদেরকে সমবেত করা হবে।', 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://