  (68, 1, '', '[{"id":582,"position":1,"text_uthmani":"نٓ ۚ","transliteration":"noon","translation_bn":"নুন","root":"—","lemma":"نٓ ۚ","grammar_bn":"শব্দ"},{"id":584,"position":2,"text_uthmani":"وَٱلْقَلَمِ","transliteration":"wal-qalami","translation_bn":"কলমের শপথ","root":"قلم","lemma":"قَلَم","grammar_bn":"অব্যয় (Preposition)"},{"id":585,"position":3,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":586,"position":4,"text_uthmani":"يَسْطُرُونَ","transliteration":"yasṭurūna","translation_bn":"তারা লিখছে","root":"سطر","lemma":"يَسْطُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":587,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'noon wal-qalami wamā yasṭurūna', 'নূন, কলমের শপথ আর লেখকেরা যা লেখে তার শপথ।', 'Nun. By the pen and what they inscribe,', 'নূন, কলমের শপথ আর লেখকেরা যা লেখে তার শপথ।', 'Nun. By the pen and what they inscribe,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068001.mp3', now()),
  (68, 2, '', '[{"id":1475,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا","grammar_bn":"না-বোধক (Negative)"},{"id":1476,"position":2,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1477,"position":3,"text_uthmani":"بِنِعْمَةِ","transliteration":"biniʿ''mati","translation_bn":"অনুগ্রহে","root":"نعم","lemma":"نِعْمَة","grammar_bn":"অব্যয় (Preposition)"},{"id":1478,"position":4,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1479,"position":5,"text_uthmani":"بِمَجْنُونٍۢ","transliteration":"bimajnūnin","translation_bn":"পাগল","root":"جنن","lemma":"مَجْنُون","grammar_bn":"অব্যয় (Preposition)"},{"id":1480,"position":6,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā anta biniʿ''mati rabbika bimajnūnin', 'তোমার প্রতিপালকের অনুগ্রহে তুমি পাগল নও।', 'You are not, [O Muhammad], by the favor of your Lord, a madman.', 'তোমার প্রতিপালকের অনুগ্রহে তুমি পাগল নও।', 'You are not, [O Muhammad], by the favor of your Lord, a madman.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068002.mp3', now()),
  (68, 3, '', '[{"id":2550,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":2551,"position":2,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমার জন্য","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":2552,"position":3,"text_uthmani":"لَأَجْرًا","transliteration":"la-ajran","translation_bn":"অবশ্যই(আছে) পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":2553,"position":4,"text_uthmani":"غَيْرَ","transliteration":"ghayra","translation_bn":"ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2554,"position":5,"text_uthmani":"مَمْنُونٍۢ","transliteration":"mamnūnin","translation_bn":"শেষ","root":"منن","lemma":"مَمْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":2555,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna laka la-ajran ghayra mamnūnin', 'তোমার জন্য অবশ্যই আছে অফুরন্ত পুরস্কার,', 'And indeed, for you is a reward uninterrupted.', 'তোমার জন্য অবশ্যই আছে অফুরন্ত পুরস্কার,', 'And indeed, for you is a reward uninterrupted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068003.mp3', now()),
  (68, 4, '', '[{"id":3965,"position":1,"text_uthmani":"وَإِنَّكَ","transliteration":"wa-innaka","translation_bn":"এবং তুমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3966,"position":2,"text_uthmani":"لَعَلَىٰ","transliteration":"laʿalā","translation_bn":"উপর অবশ্যই(অথিষ্ঠিত)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3967,"position":3,"text_uthmani":"خُلُقٍ","transliteration":"khuluqin","translation_bn":"চরিত্রের","root":"خلق","lemma":"خُلُق","grammar_bn":"বিশেষ্য (Noun)"},{"id":3968,"position":4,"text_uthmani":"عَظِيمٍۢ","transliteration":"ʿaẓīmin","translation_bn":"মহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":3969,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innaka laʿalā khuluqin ʿaẓīmin', 'নিশ্চয়ই তুমি মহান চরিত্রের উচ্চমার্গে উন্নীত।', 'And indeed, you are of a great moral character.', 'নিশ্চয়ই তুমি মহান চরিত্রের উচ্চমার্গে উন্নীত।', 'And indeed, you are of a great moral character.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068004.mp3', now()),
  (68, 5, '', '[{"id":5261,"position":1,"text_uthmani":"فَسَتُبْصِرُ","transliteration":"fasatub''ṣiru","translation_bn":"অতএব তুমি শীঘ্রই দেখবে","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"শব্দ"},{"id":5262,"position":2,"text_uthmani":"وَيُبْصِرُونَ","transliteration":"wayub''ṣirūna","translation_bn":"এবং তারা দেখবে,","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5263,"position":3,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fasatub''ṣiru wayub''ṣirūna', 'শীঘ্রই তুমি দেখতে পাবে আর তারাও দেখবে,', 'So you will see and they will see', 'শীঘ্রই তুমি দেখতে পাবে আর তারাও দেখবে,', 'So you will see and they will see', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068005.mp3', now()),
  (68, 6, '', '[{"id":6484,"position":1,"text_uthmani":"بِأَييِّكُمُ","transliteration":"bi-ayyikumu","translation_bn":"তোমাদের মধ্যে কে","root":"—","lemma":"أَىّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6485,"position":2,"text_uthmani":"ٱلْمَفْتُونُ","transliteration":"l-maftūnu","translation_bn":"বিকারগ্রস্ত","root":"فتن","lemma":"مَفْتُون","grammar_bn":"শব্দ"},{"id":6486,"position":3,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'bi-ayyikumu l-maftūnu', 'তোমাদের মধ্যে কে পাগলামিতে আক্রান্ত।', 'Which of you is the afflicted [by a devil].', 'তোমাদের মধ্যে কে পাগলামিতে আক্রান্ত।', 'Which of you is the afflicted [by a devil].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068006.mp3', now()),
