  (68, 16, '', '[{"id":18491,"position":1,"text_uthmani":"سَنَسِمُهُۥ","transliteration":"sanasimuhu","translation_bn":"তাকে দাগাব শিঘ্র","root":"وسم","lemma":"نَسِمُ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":18492,"position":2,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18493,"position":3,"text_uthmani":"ٱلْخُرْطُومِ","transliteration":"l-khur''ṭūmi","translation_bn":"শুড়ের","root":"خرطم","lemma":"خُرْطُوم","grammar_bn":"শব্দ"},{"id":18494,"position":4,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'sanasimuhu ʿalā l-khur''ṭūmi', 'আমি তার শুঁড়ের উপর দাগ দিয়ে দিব (অর্থাৎ তাকে লাঞ্ছিত করব)।', 'We will brand him upon the snout.', 'আমি তার শুঁড়ের উপর দাগ দিয়ে দিব (অর্থাৎ তাকে লাঞ্ছিত করব)।', 'We will brand him upon the snout.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/068016.mp3', now()),
