  (69, 6, '', '[{"id":6487,"position":1,"text_uthmani":"وَأَمَّا","transliteration":"wa-ammā","translation_bn":"আর","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6488,"position":2,"text_uthmani":"عَادٌۭ","transliteration":"ʿādun","translation_bn":"আদ","root":"عود","lemma":"عَاد2","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6489,"position":3,"text_uthmani":"فَأُهْلِكُوا۟","transliteration":"fa-uh''likū","translation_bn":"অতঃপর ধ্বংস করা হয়েছে","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"শব্দ"},{"id":6490,"position":4,"text_uthmani":"بِرِيحٍۢ","transliteration":"birīḥin","translation_bn":"বায়ু দিয়ে","root":"روح","lemma":"رِيح","grammar_bn":"অব্যয় (Preposition)"},{"id":6491,"position":5,"text_uthmani":"صَرْصَرٍ","transliteration":"ṣarṣarin","translation_bn":"ঝঞ্জা","root":"صرصر","lemma":"صَرْصَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":6492,"position":6,"text_uthmani":"عَاتِيَةٍۢ","transliteration":"ʿātiyatin","translation_bn":"প্রচন্ড","root":"عتو","lemma":"عَاتِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":6493,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā ʿādun fa-uh''likū birīḥin ṣarṣarin ʿātiyatin', 'আর ‘আদকে ধ্বংস করা হয়েছিল এক প্রচন্ড ঝড়ো হাওয়া দিয়ে।', 'And as for ''Aad, they were destroyed by a screaming, violent wind', 'আর ‘আদকে ধ্বংস করা হয়েছিল এক প্রচন্ড ঝড়ো হাওয়া দিয়ে।', 'And as for ''Aad, they were destroyed by a screaming, violent wind', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069006.mp3', now()),
  (69, 7, '', '[{"id":7888,"position":1,"text_uthmani":"سَخَّرَهَا","transliteration":"sakharahā","translation_bn":"তা প্রবাহিত করেন","root":"سخر","lemma":"سَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7889,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7890,"position":3,"text_uthmani":"سَبْعَ","transliteration":"sabʿa","translation_bn":"সাত","root":"سبع","lemma":"سَبْع","grammar_bn":"কালবাচক (Time)"},{"id":7891,"position":4,"text_uthmani":"لَيَالٍۢ","transliteration":"layālin","translation_bn":"রাত","root":"ليل","lemma":"لَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7892,"position":5,"text_uthmani":"وَثَمَـٰنِيَةَ","transliteration":"wathamāniyata","translation_bn":"এবং আট","root":"ثمن","lemma":"ثَمَٰنِيَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7893,"position":6,"text_uthmani":"أَيَّامٍ","transliteration":"ayyāmin","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7894,"position":7,"text_uthmani":"حُسُومًۭا","transliteration":"ḥusūman","translation_bn":"ক্রমাগত","root":"حسم","lemma":"حُسُوم","grammar_bn":"বিশেষণ (Adjective)"},{"id":7895,"position":8,"text_uthmani":"فَتَرَى","transliteration":"fatarā","translation_bn":"তুমি দেখতে তখন (তথায় থাকিলে)","root":"راي","lemma":"رَءَا","grammar_bn":"শব্দ"},{"id":7896,"position":9,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"সে জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":7897,"position":10,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7898,"position":11,"text_uthmani":"صَرْعَىٰ","transliteration":"ṣarʿā","translation_bn":"পড়ে থাকা","root":"صرع","lemma":"صَرْعَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7899,"position":12,"text_uthmani":"كَأَنَّهُمْ","transliteration":"ka-annahum","translation_bn":"তারা যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7900,"position":13,"text_uthmani":"أَعْجَازُ","transliteration":"aʿjāzu","translation_bn":"কাণ্ড সমূহ","root":"عجز","lemma":"أَعْجَاز","grammar_bn":"বিশেষ্য (Noun)"},{"id":7901,"position":14,"text_uthmani":"نَخْلٍ","transliteration":"nakhlin","translation_bn":"খেজুর গাছের","root":"نخل","lemma":"نَخْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":7902,"position":15,"text_uthmani":"خَاوِيَةٍۢ","transliteration":"khāwiyatin","translation_bn":"পরিত্যাক্ত","root":"خوي","lemma":"خَاوِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":7903,"position":16,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'sakharahā ʿalayhim sabʿa layālin wathamāniyata ayyāmin ḥusūman fatarā l-qawma fīhā ṣarʿā ka-annahum aʿjāzu nakhlin khāwiyatin', 'যা তাদের উপর প্রবাহিত হয়েছিল সাত রাত আট দিন বিরামহীনভাবে, তুমি দেখতে তারা পড়ে আছে ইতস্তত বিক্ষিপ্ত, যেন তারা পুরাতন শুকনো খেজুর গাছের কান্ড।', 'Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.', 'যা তাদের উপর প্রবাহিত হয়েছিল সাত রাত আট দিন বিরামহীনভাবে, তুমি দেখতে তারা পড়ে আছে ইতস্তত বিক্ষিপ্ত, যেন তারা পুরাতন শুকনো খেজুর গাছের কান্ড।', 'Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069007.mp3', now()),
  (69, 8, '', '[{"id":9071,"position":1,"text_uthmani":"فَهَلْ","transliteration":"fahal","translation_bn":"কি এক্ষণে","root":"—","lemma":"هَل\r","grammar_bn":"শব্দ"},{"id":9072,"position":2,"text_uthmani":"تَرَىٰ","transliteration":"tarā","translation_bn":"তুমি দেখ","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":9073,"position":3,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"তদেরকে","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":9074,"position":4,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"কিছু","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9075,"position":5,"text_uthmani":"بَاقِيَةٍۢ","transliteration":"bāqiyatin","translation_bn":"অবশিষ্ট","root":"بقي","lemma":"بَاقِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9076,"position":6,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'fahal tarā lahum min bāqiyatin', 'তুমি তাদের কাউকে রক্ষা পেয়ে বেঁচে থাকতে দেখছ কি?', 'Then do you see of them any remains?', 'তুমি তাদের কাউকে রক্ষা পেয়ে বেঁচে থাকতে দেখছ কি?', 'Then do you see of them any remains?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069008.mp3', now()),
  (69, 9, '', '[{"id":10288,"position":1,"text_uthmani":"وَجَآءَ","transliteration":"wajāa","translation_bn":"এবং এসেছিল","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"শব্দ"},{"id":10289,"position":2,"text_uthmani":"فِرْعَوْنُ","transliteration":"fir''ʿawnu","translation_bn":"ফিরাউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10290,"position":3,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"ও যারা","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10291,"position":4,"text_uthmani":"قَبْلَهُۥ","transliteration":"qablahu","translation_bn":"তার পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"কালবাচক (Time)"},{"id":10292,"position":5,"text_uthmani":"وَٱلْمُؤْتَفِكَـٰتُ","transliteration":"wal-mu''tafikātu","translation_bn":"এবং উলটে দেয়া বস্তীবাসীদের","root":"افك","lemma":"مُؤْتَفِكَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10293,"position":6,"text_uthmani":"بِٱلْخَاطِئَةِ","transliteration":"bil-khāṭi-ati","translation_bn":"অপরাধের কারণে","root":"خطا","lemma":"خَاطِئَة","grammar_bn":"অব্যয় (Preposition)"},{"id":10294,"position":7,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wajāa fir''ʿawnu waman qablahu wal-mu''tafikātu bil-khāṭi-ati', 'ফেরাউন আর তার পূর্ববর্তীরা আর উল্টে দেয়া জনপদবাসীরা গুরুতর পাপে লিপ্ত ছিল।', 'And there came Pharaoh and those before him and the overturned cities with sin.', 'ফেরাউন আর তার পূর্ববর্তীরা আর উল্টে দেয়া জনপদবাসীরা গুরুতর পাপে লিপ্ত ছিল।', 'And there came Pharaoh and those before him and the overturned cities with sin.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069009.mp3', now()),
  (69, 10, '', '[{"id":11519,"position":1,"text_uthmani":"فَعَصَوْا۟","transliteration":"faʿaṣaw","translation_bn":"অতঃপর তারা অমান্য করেছিল","root":"عصي","lemma":"عَصَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11520,"position":2,"text_uthmani":"رَسُولَ","transliteration":"rasūla","translation_bn":"রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":11521,"position":3,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11522,"position":4,"text_uthmani":"فَأَخَذَهُمْ","transliteration":"fa-akhadhahum","translation_bn":"ফলে তাদের ধরলেন","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11523,"position":5,"text_uthmani":"أَخْذَةًۭ","transliteration":"akhdhatan","translation_bn":"ধরা","root":"اخذ","lemma":"أَخْذ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11524,"position":6,"text_uthmani":"رَّابِيَةً","transliteration":"rābiyatan","translation_bn":"শক্ত","root":"ربو","lemma":"رَّابِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":11525,"position":7,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'faʿaṣaw rasūla rabbihim fa-akhadhahum akhdhatan rābiyatan', 'তারা তাদের প্রতিপালকের রসূলকে অমান্য করেছিল, তখন তিনি তাদেরকে পাকড়াও করলেন- অত্যন্ত কঠিন পাকড়াও।', 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].', 'তারা তাদের প্রতিপালকের রসূলকে অমান্য করেছিল, তখন তিনি তাদেরকে পাকড়াও করলেন- অত্যন্ত কঠিন পাকড়াও।', 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069010.mp3', now()),
  (69, 11, '', '[{"id":12835,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":12836,"position":2,"text_uthmani":"لَمَّا","transliteration":"lammā","translation_bn":"যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":12837,"position":3,"text_uthmani":"طَغَا","transliteration":"ṭaghā","translation_bn":"জলোচ্ছ্বাস হয়েছিল","root":"طغي","lemma":"طَغَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12838,"position":4,"text_uthmani":"ٱلْمَآءُ","transliteration":"l-māu","translation_bn":"(পানি)","root":"موه","lemma":"مَا^ء","grammar_bn":"শব্দ"},{"id":12839,"position":5,"text_uthmani":"حَمَلْنَـٰكُمْ","transliteration":"ḥamalnākum","translation_bn":"তোমাদের আমরা আরোহী করেছিলাম","root":"حمل","lemma":"حَمَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12840,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12841,"position":7,"text_uthmani":"ٱلْجَارِيَةِ","transliteration":"l-jāriyati","translation_bn":"নৌযানের","root":"جري","lemma":"جَارِيَة","grammar_bn":"শব্দ"},{"id":12842,"position":8,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'innā lammā ṭaghā l-māu ḥamalnākum fī l-jāriyati', '(নূহের বানের) পানি যখন কূল ছাপিয়ে সীমা ছাড়িয়ে গেল, তখন আমি তোমাদেরকে চলন্ত নৌযানে আরোহণ করালাম।', 'Indeed, when the water overflowed, We carried your ancestors in the sailing ship', '(নূহের বানের) পানি যখন কূল ছাপিয়ে সীমা ছাড়িয়ে গেল, তখন আমি তোমাদেরকে চলন্ত নৌযানে আরোহণ করালাম।', 'Indeed, when the water overflowed, We carried your ancestors in the sailing ship', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069011.mp3', now()),
  (69, 12, '', '[{"id":14094,"position":1,"text_uthmani":"لِنَجْعَلَهَا","transliteration":"linajʿalahā","translation_bn":"তা বানাই আমরা যেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"শব্দ"},{"id":14095,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":14096,"position":3,"text_uthmani":"تَذْكِرَةًۭ","transliteration":"tadhkiratan","translation_bn":"শিক্ষা","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14097,"position":4,"text_uthmani":"وَتَعِيَهَآ","transliteration":"wataʿiyahā","translation_bn":"এবং তার ষ্মৃতি বহন করে","root":"وعي","lemma":"تَعِيَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14098,"position":5,"text_uthmani":"أُذُنٌۭ","transliteration":"udhunun","translation_bn":"কান","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14099,"position":6,"text_uthmani":"وَٰعِيَةٌۭ","transliteration":"wāʿiyatun","translation_bn":"স্মরন বাহক","root":"وعي","lemma":"وَٰعِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":14100,"position":7,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'linajʿalahā lakum tadhkiratan wataʿiyahā udhunun wāʿiyatun', 'যেন এ ঘটনাটিকে আমি তোমাদের জন্য শিক্ষাপ্রদ-স্মারক করে রাখি আর সংরক্ষণকারী কান তা সংরক্ষণ করে।', 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.', 'যেন এ ঘটনাটিকে আমি তোমাদের জন্য শিক্ষাপ্রদ-স্মারক করে রাখি আর সংরক্ষণকারী কান তা সংরক্ষণ করে।', 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069012.mp3', now()),
  (69, 13, '', '[{"id":15213,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"যখন অতঃপর","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":15214,"position":2,"text_uthmani":"نُفِخَ","transliteration":"nufikha","translation_bn":"ফুক দেয়া হবে","root":"نفخ","lemma":"نَفَخَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15215,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15216,"position":4,"text_uthmani":"ٱلصُّورِ","transliteration":"l-ṣūri","translation_bn":"শিঙ্গায়","root":"صور","lemma":"صُّور","grammar_bn":"শব্দ"},{"id":15217,"position":5,"text_uthmani":"نَفْخَةٌۭ","transliteration":"nafkhatun","translation_bn":"ফুক","root":"نفخ","lemma":"نَفْخَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15218,"position":6,"text_uthmani":"وَٰحِدَةٌۭ","transliteration":"wāḥidatun","translation_bn":"একবার","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":15219,"position":7,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā nufikha fī l-ṣūri nafkhatun wāḥidatun', 'অতঃপর যখন সিঙ্গায় ফুঁৎকার দেয়া হবে- মাত্র একটি ফুঁৎকার।', 'Then when the Horn is blown with one blast', 'অতঃপর যখন সিঙ্গায় ফুঁৎকার দেয়া হবে- মাত্র একটি ফুঁৎকার।', 'Then when the Horn is blown with one blast', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069013.mp3', now()),
  (69, 14, '', '[{"id":16249,"position":1,"text_uthmani":"وَحُمِلَتِ","transliteration":"waḥumilati","translation_bn":"এবং উঠানো হবে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16250,"position":2,"text_uthmani":"ٱلْأَرْضُ","transliteration":"l-arḍu","translation_bn":"যমীন","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":16251,"position":3,"text_uthmani":"وَٱلْجِبَالُ","transliteration":"wal-jibālu","translation_bn":"এবং পাহাড়গুলো","root":"جبل","lemma":"جَبَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16252,"position":4,"text_uthmani":"فَدُكَّتَا","transliteration":"fadukkatā","translation_bn":"বিচূর্ণ করা হবে অতঃপর","root":"دكك","lemma":"دُكَّتِ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16253,"position":5,"text_uthmani":"دَكَّةًۭ","transliteration":"dakkatan","translation_bn":"চূর্ণ বিচূর্ণ","root":"دكك","lemma":"دَكَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16254,"position":6,"text_uthmani":"وَٰحِدَةًۭ","transliteration":"wāḥidatan","translation_bn":"একবার","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":16255,"position":7,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'waḥumilati l-arḍu wal-jibālu fadukkatā dakkatan wāḥidatan', 'পৃথিবী আর পর্বতমালা উৎক্ষিপ্ত হবে আর একই আঘাতে তাদেরকে চূর্ণ বিচূর্ণ করা হবে।', 'And the earth and the mountains are lifted and leveled with one blow -', 'পৃথিবী আর পর্বতমালা উৎক্ষিপ্ত হবে আর একই আঘাতে তাদেরকে চূর্ণ বিচূর্ণ করা হবে।', 'And the earth and the mountains are lifted and leveled with one blow -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069014.mp3', now()),
  (69, 15, '', '[{"id":17436,"position":1,"text_uthmani":"فَيَوْمَئِذٍۢ","transliteration":"fayawma-idhin","translation_bn":"সেদিন অতঃপর","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":17437,"position":2,"text_uthmani":"وَقَعَتِ","transliteration":"waqaʿati","translation_bn":"সংঘটিত হবে","root":"وقع","lemma":"وَقَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17438,"position":3,"text_uthmani":"ٱلْوَاقِعَةُ","transliteration":"l-wāqiʿatu","translation_bn":"মহাপ্রলয়","root":"وقع","lemma":"وَاقِعَة","grammar_bn":"শব্দ"},{"id":17439,"position":4,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'fayawma-idhin waqaʿati l-wāqiʿatu', 'সেদিন ঘটবে সেই সংঘটিতব্য (মহা) ঘটনা।', 'Then on that Day, the Resurrection will occur,', 'সেদিন ঘটবে সেই সংঘটিতব্য (মহা) ঘটনা।', 'Then on that Day, the Resurrection will occur,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069015.mp3', now()),
  (69, 16, '', '[{"id":18425,"position":1,"text_uthmani":"وَٱنشَقَّتِ","transliteration":"wa-inshaqqati","translation_bn":"এবং বিদীর্ণ হবে","root":"شقق","lemma":"ٱنشَقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18426,"position":2,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আসমান","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":18427,"position":3,"text_uthmani":"فَهِىَ","transliteration":"fahiya","translation_bn":"তা অতঃপর","root":"—","lemma":"فَهِىَ","grammar_bn":"শব্দ"},{"id":18428,"position":4,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":18429,"position":5,"text_uthmani":"وَاهِيَةٌۭ","transliteration":"wāhiyatun","translation_bn":"বিশ্লিষ্ট হবে","root":"وهي","lemma":"وَاهِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18430,"position":6,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inshaqqati l-samāu fahiya yawma-idhin wāhiyatun', 'আকাশ হয়ে যাবে দীর্ণ বিদীর্ণ আর সেদিন তা হবে বাঁধন-হারা-বিক্ষিপ্ত।', 'And the heaven will split [open], for that Day it is infirm.', 'আকাশ হয়ে যাবে দীর্ণ বিদীর্ণ আর সেদিন তা হবে বাঁধন-হারা-বিক্ষিপ্ত।', 'And the heaven will split [open], for that Day it is infirm.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069016.mp3', now()),
  (69, 17, '', '[{"id":19493,"position":1,"text_uthmani":"وَٱلْمَلَكُ","transliteration":"wal-malaku","translation_bn":"এবং ফেরেশতাগণ","root":"ملك","lemma":"مَلَك","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":19494,"position":2,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19495,"position":3,"text_uthmani":"أَرْجَآئِهَا ۚ","transliteration":"arjāihā","translation_bn":"(আসমানের) বিভিন্ন প্রান্তে থাকবে","root":"رجو","lemma":"أَرْجَا^ئ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19497,"position":4,"text_uthmani":"وَيَحْمِلُ","transliteration":"wayaḥmilu","translation_bn":"এবং বহন করবে","root":"حمل","lemma":"حَمَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19498,"position":5,"text_uthmani":"عَرْشَ","transliteration":"ʿarsha","translation_bn":"আরশ","root":"عرش","lemma":"عَرْش","grammar_bn":"বিশেষ্য (Noun)"},{"id":19499,"position":6,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19500,"position":7,"text_uthmani":"فَوْقَهُمْ","transliteration":"fawqahum","translation_bn":"তাদের উপরে,","root":"فوق","lemma":"فَوْق","grammar_bn":"স্থানবাচক (Location)"},{"id":19501,"position":8,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":19502,"position":9,"text_uthmani":"ثَمَـٰنِيَةٌۭ","transliteration":"thamāniyatun","translation_bn":"আট (ফেরেশতা)","root":"ثمن","lemma":"ثَمَٰنِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":19503,"position":10,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-malaku ʿalā arjāihā wayaḥmilu ʿarsha rabbika fawqahum yawma-idhin thamāniyatun', 'ফেরেশতারা থাকবে আকাশের আশে পাশে। আটজন ফেরেশতা সেদিন তোমার প্রতিপালকের ‘আরশ নিজেদের ঊর্ধ্বে বহন করবে।', 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].', 'ফেরেশতারা থাকবে আকাশের আশে পাশে। আটজন ফেরেশতা সেদিন তোমার প্রতিপালকের ‘আরশ নিজেদের ঊর্ধ্বে বহন করবে।', 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069017.mp3', now()),
  (69, 18, '', '[{"id":20593,"position":1,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":20594,"position":2,"text_uthmani":"تُعْرَضُونَ","transliteration":"tuʿ''raḍūna","translation_bn":"পেশ করা হবে তোমাদের","root":"عرض","lemma":"عَرَضَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20595,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20596,"position":4,"text_uthmani":"تَخْفَىٰ","transliteration":"takhfā","translation_bn":"আড়াল করা হবে","root":"خفي","lemma":"يَخْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20597,"position":5,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20598,"position":6,"text_uthmani":"خَافِيَةٌۭ","transliteration":"khāfiyatun","translation_bn":"কোন গোপন কিছুই","root":"خفي","lemma":"خَافِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":20599,"position":7,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'yawma-idhin tuʿ''raḍūna lā takhfā minkum khāfiyatun', 'সেদিন তোমাদেরকে (বিচারের জন্য) হাজির করা হবে আর তোমাদের কোন কাজই- যা তোমরা গোপন কর- গোপন থাকবে না।', 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.', 'সেদিন তোমাদেরকে (বিচারের জন্য) হাজির করা হবে আর তোমাদের কোন কাজই- যা তোমরা গোপন কর- গোপন থাকবে না।', 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069018.mp3', now()),
