  (69, 45, '', '[{"id":45227,"position":1,"text_uthmani":"لَأَخَذْنَا","transliteration":"la-akhadhnā","translation_bn":"অবশ্যই আমরা ধরতাম","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":45228,"position":2,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তাকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45229,"position":3,"text_uthmani":"بِٱلْيَمِينِ","transliteration":"bil-yamīni","translation_bn":"ডান হাত দ্বারা;","root":"يمن","lemma":"يَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":45230,"position":4,"text_uthmani":"٤٥","transliteration":"","translation_bn":"(৪৫)","root":"—","lemma":"٤٥","grammar_bn":"মার্কার"}]'::jsonb, 'la-akhadhnā min''hu bil-yamīni', 'আমি অবশ্যই তার ডান হাত ধরে তাকে পাকড়াও করতাম,', 'We would have seized him by the right hand;', 'আমি অবশ্যই তার ডান হাত ধরে তাকে পাকড়াও করতাম,', 'We would have seized him by the right hand;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069045.mp3', now()),
  (69, 46, '', '[{"id":45965,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"তারপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":45966,"position":2,"text_uthmani":"لَقَطَعْنَا","transliteration":"laqaṭaʿnā","translation_bn":"অবশ্যই আমরা কাটতাম","root":"قطع","lemma":"قُطِعَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":45967,"position":3,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তার থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":45968,"position":4,"text_uthmani":"ٱلْوَتِينَ","transliteration":"l-watīna","translation_bn":"মহাধমনী.","root":"وتن","lemma":"وَتِين","grammar_bn":"শব্দ"},{"id":45969,"position":5,"text_uthmani":"٤٦","transliteration":"","translation_bn":"(৪৬)","root":"—","lemma":"٤٦","grammar_bn":"মার্কার"}]'::jsonb, 'thumma laqaṭaʿnā min''hu l-watīna', 'তারপর অবশ্যই কেটে দিতাম তার হৃৎপিন্ডের শিরা,', 'Then We would have cut from him the aorta.', 'তারপর অবশ্যই কেটে দিতাম তার হৃৎপিন্ডের শিরা,', 'Then We would have cut from him the aorta.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069046.mp3', now()),
  (69, 47, '', '[{"id":46593,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":46594,"position":2,"text_uthmani":"مِنكُم","transliteration":"minkum","translation_bn":"তোমাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46595,"position":3,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোন","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46596,"position":4,"text_uthmani":"أَحَدٍ","transliteration":"aḥadin","translation_bn":"কেও","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":46597,"position":5,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"[তার কাছ থেকে]","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":46598,"position":6,"text_uthmani":"حَـٰجِزِينَ","transliteration":"ḥājizīna","translation_bn":"বিরতকারী","root":"حجز","lemma":"حَٰجِزِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":46599,"position":7,"text_uthmani":"٤٧","transliteration":"","translation_bn":"(৪৭)","root":"—","lemma":"٤٧","grammar_bn":"মার্কার"}]'::jsonb, 'famā minkum min aḥadin ʿanhu ḥājizīna', 'অতঃপর তোমাদের মধ্যে এমন কেউ নেই যে, (আমার গোস্বা থেকে তাকে রক্ষা করার জন্য) বাধা সৃষ্টি করতে পারে।', 'And there is no one of you who could prevent [Us] from him.', 'অতঃপর তোমাদের মধ্যে এমন কেউ নেই যে, (আমার গোস্বা থেকে তাকে রক্ষা করার জন্য) বাধা সৃষ্টি করতে পারে।', 'And there is no one of you who could prevent [Us] from him.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069047.mp3', now()),
  (69, 48, '', '[{"id":47088,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"এবং তা","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":47089,"position":2,"text_uthmani":"لَتَذْكِرَةٌۭ","transliteration":"latadhkiratun","translation_bn":"অবশ্যই উপদেশ","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":47090,"position":3,"text_uthmani":"لِّلْمُتَّقِينَ","transliteration":"lil''muttaqīna","translation_bn":"মুত্তাকীদের","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"অব্যয় (Preposition)"},{"id":47091,"position":4,"text_uthmani":"٤٨","transliteration":"","translation_bn":"(৪৮)","root":"—","lemma":"٤٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu latadhkiratun lil''muttaqīna', 'মুত্তাক্বীদের জন্য এ কুরআন অবশ্যই এক উপদেশ,', 'And indeed, the Qur''an is a reminder for the righteous.', 'মুত্তাক্বীদের জন্য এ কুরআন অবশ্যই এক উপদেশ,', 'And indeed, the Qur''an is a reminder for the righteous.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069048.mp3', now()),
  (69, 49, '', '[{"id":47934,"position":1,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":47935,"position":2,"text_uthmani":"لَنَعْلَمُ","transliteration":"lanaʿlamu","translation_bn":"অবশ্যই জানি","root":"علم","lemma":"عَلِمَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":47936,"position":3,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":47937,"position":4,"text_uthmani":"مِنكُم","transliteration":"minkum","translation_bn":"তোমাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":47938,"position":5,"text_uthmani":"مُّكَذِّبِينَ","transliteration":"mukadhibīna","translation_bn":"অস্বীকারকারীরা (সম্পূর্ণ).","root":"كذب","lemma":"مُّكَذِّبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":47939,"position":6,"text_uthmani":"٤٩","transliteration":"","translation_bn":"(৪৯)","root":"—","lemma":"٤٩","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innā lanaʿlamu anna minkum mukadhibīna', 'আমি অবশ্যই জানি যে, তোমাদের মধ্যে কতক লোক (কুরআনকে) অস্বীকার করবে।', 'And indeed, We know that among you are deniers.', 'আমি অবশ্যই জানি যে, তোমাদের মধ্যে কতক লোক (কুরআনকে) অস্বীকার করবে।', 'And indeed, We know that among you are deniers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069049.mp3', now()),
  (69, 50, '', '[{"id":48697,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"এবং নিশ্চয় তা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":48698,"position":2,"text_uthmani":"لَحَسْرَةٌ","transliteration":"laḥasratun","translation_bn":"আক্ষেপের","root":"حسر","lemma":"حَسْرَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":48699,"position":3,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":48700,"position":4,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফিরদের.","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":48701,"position":5,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu laḥasratun ʿalā l-kāfirīna', 'আর এ কুরআন কাফিরদের জন্য অবশ্যই দুঃখ ও হতাশার কারণ হবে (যখন কুরআনে বর্ণিত শাস্তি তাদেরকে ঘিরে ধরবে)।', 'And indeed, it will be [a cause of] regret upon the disbelievers.', 'আর এ কুরআন কাফিরদের জন্য অবশ্যই দুঃখ ও হতাশার কারণ হবে (যখন কুরআনে বর্ণিত শাস্তি তাদেরকে ঘিরে ধরবে)।', 'And indeed, it will be [a cause of] regret upon the disbelievers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069050.mp3', now()),
  (69, 51, '', '[{"id":49239,"position":1,"text_uthmani":"وَإِنَّهُۥ","transliteration":"wa-innahu","translation_bn":"ও নিশ্চয় তা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49240,"position":2,"text_uthmani":"لَحَقُّ","transliteration":"laḥaqqu","translation_bn":"অবশ্যই সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":49241,"position":3,"text_uthmani":"ٱلْيَقِينِ","transliteration":"l-yaqīni","translation_bn":"সুনিশ্চিত","root":"يقن","lemma":"يَقِين","grammar_bn":"শব্দ"},{"id":49242,"position":4,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innahu laḥaqqu l-yaqīni', 'এটা একেবারে নিশ্চিত সত্য।', 'And indeed, it is the truth of certainty.', 'এটা একেবারে নিশ্চিত সত্য।', 'And indeed, it is the truth of certainty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069051.mp3', now()),
  (69, 52, '', '[{"id":49973,"position":1,"text_uthmani":"فَسَبِّحْ","transliteration":"fasabbiḥ","translation_bn":"অতএব তাসবীহ পাঠ কর","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"শব্দ"},{"id":49974,"position":2,"text_uthmani":"بِٱسْمِ","transliteration":"bi-is''mi","translation_bn":"নামের","root":"سمو","lemma":"ٱسْم","grammar_bn":"অব্যয় (Preposition)"},{"id":49975,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49976,"position":4,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":49977,"position":5,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'fasabbiḥ bi-is''mi rabbika l-ʿaẓīmi', 'অতএব তুমি তোমার মহান প্রতিপালকের নামের পবিত্রতা ও মহিমা বর্ণনা কর।', 'So exalt the name of your Lord, the Most Great.', 'অতএব তুমি তোমার মহান প্রতিপালকের নামের পবিত্রতা ও মহিমা বর্ণনা কর।', 'So exalt the name of your Lord, the Most Great.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/069052.mp3', now())
