  (70, 1, '', '[{"id":594,"position":1,"text_uthmani":"سَأَلَ","transliteration":"sa-ala","translation_bn":"জিজ্ঞাসা করল","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":595,"position":2,"text_uthmani":"سَآئِلٌۢ","transliteration":"sāilun","translation_bn":"এক প্রশ্নকারী","root":"سال","lemma":"سَا^ئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":596,"position":3,"text_uthmani":"بِعَذَابٍۢ","transliteration":"biʿadhābin","translation_bn":"এমন আযাব সম্পর্কে","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":597,"position":4,"text_uthmani":"وَاقِعٍۢ","transliteration":"wāqiʿin","translation_bn":"যা আপতিত হবে","root":"وقع","lemma":"وَاقِع","grammar_bn":"বিশেষণ (Adjective)"},{"id":598,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sa-ala sāilun biʿadhābin wāqiʿin', 'এক ব্যক্তি চাইল সে ‘আযাব যা অবশ্যই সংঘটিত হবে।', 'A supplicant asked for a punishment bound to happen', 'এক ব্যক্তি চাইল সে ‘আযাব যা অবশ্যই সংঘটিত হবে।', 'A supplicant asked for a punishment bound to happen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070001.mp3', now()),
  (70, 2, '', '[{"id":1552,"position":1,"text_uthmani":"لِّلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"কাফিরদের উপর,","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":1553,"position":2,"text_uthmani":"لَيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1554,"position":3,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তার","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":1555,"position":4,"text_uthmani":"دَافِعٌۭ","transliteration":"dāfiʿun","translation_bn":"কোন প্রতিরোধকারী","root":"دفع","lemma":"دَافِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":1556,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'lil''kāfirīna laysa lahu dāfiʿun', 'কাফিরদের জন্য তা প্রতিরোধ করার কেউ নেই', 'To the disbelievers; of it there is no preventer.', 'কাফিরদের জন্য তা প্রতিরোধ করার কেউ নেই', 'To the disbelievers; of it there is no preventer.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070002.mp3', now()),
