  (70, 38, '', '[{"id":39817,"position":1,"text_uthmani":"أَيَطْمَعُ","transliteration":"ayaṭmaʿu","translation_bn":"লোভকরে কি","root":"طمع","lemma":"يَطْمَعُ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":39818,"position":2,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":39819,"position":3,"text_uthmani":"ٱمْرِئٍۢ","transliteration":"im''ri-in","translation_bn":"ব্যক্তি","root":"مرا","lemma":"ٱمْرِئ","grammar_bn":"বিশেষ্য (Noun)"},{"id":39820,"position":4,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39821,"position":5,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":39822,"position":6,"text_uthmani":"يُدْخَلَ","transliteration":"yud''khala","translation_bn":"প্রবেশ করানো হবে","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39823,"position":7,"text_uthmani":"جَنَّةَ","transliteration":"jannata","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":39824,"position":8,"text_uthmani":"نَعِيمٍۢ","transliteration":"naʿīmin","translation_bn":"নিয়ামতের","root":"نعم","lemma":"نَعِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":39825,"position":9,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'ayaṭmaʿu kullu im''ri-in min''hum an yud''khala jannata naʿīmin', 'তাদের প্রত্যেকেই কি এই লোভ করে যে, তাকে নি‘মাত-ভরা জান্নাতে দাখিল করা হবে?', 'Does every person among them aspire to enter a garden of pleasure?', 'তাদের প্রত্যেকেই কি এই লোভ করে যে, তাকে নি‘মাত-ভরা জান্নাতে দাখিল করা হবে?', 'Does every person among them aspire to enter a garden of pleasure?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070038.mp3', now()),
  (70, 39, '', '[{"id":40725,"position":1,"text_uthmani":"كَلَّآ ۖ","transliteration":"kallā","translation_bn":"কখনও নয়!","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":40727,"position":2,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":40728,"position":3,"text_uthmani":"خَلَقْنَـٰهُم","transliteration":"khalaqnāhum","translation_bn":"[আমরা] তাদেরকে সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40729,"position":4,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"যা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40730,"position":5,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে.","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40731,"position":6,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'kallā innā khalaqnāhum mimmā yaʿlamūna', 'কক্ষনো না, আমি তাদেরকে কী থেকে সৃষ্টি করেছি তা তারা জানে (এমন নগণ্য বস্তু থেকে সৃষ্ট মানুষ কেবল মানুষ হয়ে জন্ম নেয়ার কারণেই জান্নাতে চলে যাবে এ রকম লোভ করা বড়ই অবিবেচনাপ্রসূত ব্যাপার)।', 'No! Indeed, We have created them from that which they know.', 'কক্ষনো না, আমি তাদেরকে কী থেকে সৃষ্টি করেছি তা তারা জানে (এমন নগণ্য বস্তু থেকে সৃষ্ট মানুষ কেবল মানুষ হয়ে জন্ম নেয়ার কারণেই জান্নাতে চলে যাবে এ রকম লোভ করা বড়ই অবিবেচনাপ্রসূত ব্যাপার)।', 'No! Indeed, We have created them from that which they know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070039.mp3', now()),
  (70, 40, '', '[{"id":41393,"position":1,"text_uthmani":"فَلَآ","transliteration":"falā","translation_bn":"অতএব, না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":41394,"position":2,"text_uthmani":"أُقْسِمُ","transliteration":"uq''simu","translation_bn":"আমি কসম করছি যে","root":"قسم","lemma":"أَقْسَمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41395,"position":3,"text_uthmani":"بِرَبِّ","transliteration":"birabbi","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":41396,"position":4,"text_uthmani":"ٱلْمَشَـٰرِقِ","transliteration":"l-mashāriqi","translation_bn":"উদয়স্থল","root":"شرق","lemma":"مَشْرِق","grammar_bn":"শব্দ"},{"id":41397,"position":5,"text_uthmani":"وَٱلْمَغَـٰرِبِ","transliteration":"wal-maghāribi","translation_bn":"ও অস্তাচলসমূহের","root":"غرب","lemma":"مَغْرِب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41398,"position":6,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয় আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":41399,"position":7,"text_uthmani":"لَقَـٰدِرُونَ","transliteration":"laqādirūna","translation_bn":"সক্ষম","root":"قدر","lemma":"قَادِر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":41400,"position":8,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'falā uq''simu birabbi l-mashāriqi wal-maghāribi innā laqādirūna', 'আমি শপথ করছি উদয়স্থানসমূহের ও অস্তাচলসমূহের রব্বের-আমি অবশ্যই সক্ষম,', 'So I swear by the Lord of [all] risings and settings that indeed We are able', 'আমি শপথ করছি উদয়স্থানসমূহের ও অস্তাচলসমূহের রব্বের-আমি অবশ্যই সক্ষম,', 'So I swear by the Lord of [all] risings and settings that indeed We are able', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070040.mp3', now()),
  (70, 41, '', '[{"id":42188,"position":1,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42189,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":42190,"position":3,"text_uthmani":"نُّبَدِّلَ","transliteration":"nubaddila","translation_bn":"বদলাব","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42191,"position":4,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"আমরা","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":42192,"position":5,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের চেয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42193,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا","grammar_bn":"শব্দ"},{"id":42194,"position":7,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমাদের","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":42195,"position":8,"text_uthmani":"بِمَسْبُوقِينَ","transliteration":"bimasbūqīna","translation_bn":"অতিক্রমকারী","root":"سبق","lemma":"مَسْبُوقِين","grammar_bn":"অব্যয় (Preposition)"},{"id":42196,"position":9,"text_uthmani":"٤١","transliteration":"","translation_bn":"(৪১)","root":"—","lemma":"٤١","grammar_bn":"মার্কার"}]'::jsonb, 'ʿalā an nubaddila khayran min''hum wamā naḥnu bimasbūqīna', 'তাদের পরিবর্তে তাদের চেয়ে উৎকৃষ্ট মানুষ বানাতে, আমাকে পরাস্ত করবে এমন কেউ নেই।', 'To replace them with better than them; and We are not to be outdone.', 'তাদের পরিবর্তে তাদের চেয়ে উৎকৃষ্ট মানুষ বানাতে, আমাকে পরাস্ত করবে এমন কেউ নেই।', 'To replace them with better than them; and We are not to be outdone.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070041.mp3', now()),
  (70, 42, '', '[{"id":43034,"position":1,"text_uthmani":"فَذَرْهُمْ","transliteration":"fadharhum","translation_bn":"সুতরাং তাদের ছেড়ে দাও,","root":"وذر","lemma":"يَذَرَ","grammar_bn":"শব্দ"},{"id":43035,"position":2,"text_uthmani":"يَخُوضُوا۟","transliteration":"yakhūḍū","translation_bn":"(করতে) বেহুদা কথায়","root":"خوض","lemma":"خَاضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43036,"position":3,"text_uthmani":"وَيَلْعَبُوا۟","transliteration":"wayalʿabū","translation_bn":"আর খেল-তামাশায়","root":"لعب","lemma":"يَلْعَبْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43037,"position":4,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43038,"position":5,"text_uthmani":"يُلَـٰقُوا۟","transliteration":"yulāqū","translation_bn":"দেখা পায়","root":"لقي","lemma":"يُلَٰقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43039,"position":6,"text_uthmani":"يَوْمَهُمُ","transliteration":"yawmahumu","translation_bn":"সেদিনের,","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":43040,"position":7,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":43041,"position":8,"text_uthmani":"يُوعَدُونَ","transliteration":"yūʿadūna","translation_bn":"তাদের ওয়াদা করা হয়েছে","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43042,"position":9,"text_uthmani":"٤٢","transliteration":"","translation_bn":"(৪২)","root":"—","lemma":"٤٢","grammar_bn":"মার্কার"}]'::jsonb, 'fadharhum yakhūḍū wayalʿabū ḥattā yulāqū yawmahumu alladhī yūʿadūna', 'কাজেই তাদেরকে অনর্থক কথাবার্তা ও খেল তামাশায় মত্ত থাকতে দাও যতক্ষণ না তারা তাদের সেদিনের সাক্ষাৎ লাভ করে যে দিনের ও‘য়াদা তাদেরকে দেয়া হয়েছিল।', 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -', 'কাজেই তাদেরকে অনর্থক কথাবার্তা ও খেল তামাশায় মত্ত থাকতে দাও যতক্ষণ না তারা তাদের সেদিনের সাক্ষাৎ লাভ করে যে দিনের ও‘য়াদা তাদেরকে দেয়া হয়েছিল।', 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070042.mp3', now()),
  (70, 43, '', '[{"id":43734,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"যেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":43735,"position":2,"text_uthmani":"يَخْرُجُونَ","transliteration":"yakhrujūna","translation_bn":"তারা বের হবে","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43736,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43737,"position":4,"text_uthmani":"ٱلْأَجْدَاثِ","transliteration":"l-ajdāthi","translation_bn":"কবরগুলো","root":"جدث","lemma":"أَجْدَاث","grammar_bn":"শব্দ"},{"id":43738,"position":5,"text_uthmani":"سِرَاعًۭا","transliteration":"sirāʿan","translation_bn":"দ্রুতভাবে","root":"سرع","lemma":"سِرَاع","grammar_bn":"বিশেষ্য (Noun)"},{"id":43739,"position":6,"text_uthmani":"كَأَنَّهُمْ","transliteration":"ka-annahum","translation_bn":"তারা যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":43740,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":43741,"position":8,"text_uthmani":"نُصُبٍۢ","transliteration":"nuṣubin","translation_bn":"লক্ষ্যের","root":"نصب","lemma":"نُصُب","grammar_bn":"বিশেষ্য (Noun)"},{"id":43742,"position":9,"text_uthmani":"يُوفِضُونَ","transliteration":"yūfiḍūna","translation_bn":"ছুটে যাচ্ছে","root":"وفض","lemma":"يُوفِضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":43743,"position":10,"text_uthmani":"٤٣","transliteration":"","translation_bn":"(৪৩)","root":"—","lemma":"٤٣","grammar_bn":"মার্কার"}]'::jsonb, 'yawma yakhrujūna mina l-ajdāthi sirāʿan ka-annahum ilā nuṣubin yūfiḍūna', 'যেদিন তারা কবর থেকে বের হবে দ্রুততার সাথে- যেন তারা কোন লক্ষ্যস্থলের দিকে ছুটে চলেছে।', 'The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening.', 'যেদিন তারা কবর থেকে বের হবে দ্রুততার সাথে- যেন তারা কোন লক্ষ্যস্থলের দিকে ছুটে চলেছে।', 'The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070043.mp3', now()),
  (70, 44, '', '[{"id":44478,"position":1,"text_uthmani":"خَـٰشِعَةً","transliteration":"khāshiʿatan","translation_bn":"অবনত","root":"خشع","lemma":"خَاشِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":44479,"position":2,"text_uthmani":"أَبْصَـٰرُهُمْ","transliteration":"abṣāruhum","translation_bn":"তাদের চোখ","root":"بصر","lemma":"بَصَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":44480,"position":3,"text_uthmani":"تَرْهَقُهُمْ","transliteration":"tarhaquhum","translation_bn":"তাদেরকে আচ্ছন্ন করবে","root":"رهق","lemma":"يَرْهَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44481,"position":4,"text_uthmani":"ذِلَّةٌۭ ۚ","transliteration":"dhillatun","translation_bn":"লাঞ্ছনা","root":"ذلل","lemma":"ذِلَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":44483,"position":5,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":44484,"position":6,"text_uthmani":"ٱلْيَوْمُ","transliteration":"l-yawmu","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":44485,"position":7,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যার","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":44486,"position":8,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তাদেরকে দেয়া হয়েছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44487,"position":9,"text_uthmani":"يُوعَدُونَ","transliteration":"yūʿadūna","translation_bn":"যার ওয়াদা","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":44488,"position":10,"text_uthmani":"٤٤","transliteration":"","translation_bn":"(৪৪)","root":"—","lemma":"٤٤","grammar_bn":"মার্কার"}]'::jsonb, 'khāshiʿatan abṣāruhum tarhaquhum dhillatun dhālika l-yawmu alladhī kānū yūʿadūna', 'তাদের দৃষ্টি হবে অবনমিত, লাঞ্ছনা তাদেরকে আচ্ছন্ন করবে। এটাই হল সেই দিন যার ও‘য়াদা তাদেরকে দেয়া হচ্ছিল।', 'Their eyes humbled, humiliation will cover them. That is the Day which they had been promised.', 'তাদের দৃষ্টি হবে অবনমিত, লাঞ্ছনা তাদেরকে আচ্ছন্ন করবে। এটাই হল সেই দিন যার ও‘য়াদা তাদেরকে দেয়া হচ্ছিল।', 'Their eyes humbled, humiliation will cover them. That is the Day which they had been promised.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/070044.mp3', now())
